export default {"decoder":[{"id":"RENT-START-001","domain":"签约前","subScene":"需求确认","name":"第一次租房要核验什么","alias":["首次租房","租房","新手租房","第一次租房子","租房注意事项"],"cq":"我第一次租房，最该先确认什么？","ola":"先验房东身份和房屋产权再签合同，别急着交定金","cp":["核验房东身份与房屋产权","合同写明押金/租期/违约条款","警惕二房东违规转租","租金支付方式与到账凭证留痕"],"detail":"首次租房客户普遍缺少经验，最易在房东身份、房屋产权、合同书面形式三处踩坑。租住线起步客户核心特征：预算敏感、对流程陌生、易被低价假房源带节奏。经纪人应帮助其完成\"房东身份+产权核验→书面合同→押金与违约条款确认\"三步前置，避免签约后因主体不实或条款不清导致钱房两空。","legalRef":"《民法典》第703条（租赁合同定义）、第707条（租赁期6个月以上应采用书面形式）","consumerBenefit":"不踩假房东和阴阳合同，定金押金更安全","tags":{"clientType":["tenant"],"stage":"pre","layer":"shu"},"scene":"租住前·需求确认"},{"id":"RENT-START-002","domain":"签约前","subScene":"需求确认","name":"合租和整租怎么选","alias":["合租","整租","租房合租","和别人合租"],"cq":"合租和整租哪个更适合我？","ola":"合租先看室友和分摊规则，整租先确认合同主体是不是真房东","cp":["合租确认次卧合法性","明确水电燃气分摊方式","整租核验房产证与出租人身份","转租须经出租人同意"],"detail":"合租适合预算有限、对独立空间要求不高的起步客户；整租适合重视私密与稳定的客户。无论哪种，都应核验出租人身份与产权，合租还需明确公共区域使用与费用分摊，避免日后纠纷。","legalRef":"《民法典》第703条（租赁合同）、第716条（承租人转租须经出租人同意）","consumerBenefit":"选对租住形态，少扯皮更省心","tags":{"clientType":["tenant"],"stage":"pre","layer":"shu"},"scene":"租住前·需求确认"},{"id":"RENT-START-003","domain":"签约前","subScene":"需求确认","name":"租房预算怎么算不超支","alias":["租房预算","租金预算","租房花多少钱","月租怎么算"],"cq":"我租房预算该怎么定才不超支？","ola":"月租别超收入三分之一，押金和中介费单列算清","cp":["租金占收入比控制","押金上限与退还条件","中介费/服务费一次性成本","物业水电燃气月固定支出"],"detail":"租住线起步客户常低估隐性成本。合理预算应覆盖：月租（建议不超过月收入1/3）、押金（通常1-2个月）、中介费或服务费、以及物业水电燃气等月固定支出，避免签约后现金流断裂。","legalRef":"《民法典》第5条（自愿原则）、第6条（公平原则）——租金与费用依合同自治约定","consumerBenefit":"把账算在前面，住得稳不心慌","tags":{"clientType":["tenant"],"stage":"pre","layer":"shu"},"scene":"租住前·需求确认"},{"id":"RENT-RIMP-001","domain":"签约前","subScene":"需求确认","name":"什么时候该换租改善","alias":["换租","租住改善","改善租","换房子租","租房换大"],"cq":"我现在的租屋不太满意，什么时候该换？","ola":"通勤太远或空间太小影响生活就值得换，换前先算清违约和搬家成本","cp":["提前评估新租成本","核查原合同违约条款","搬家与时间成本核算","租期衔接避免空窗"],"detail":"租住改善客户已从\"有地方住\"转向\"住得好\"。触发换租的典型信号：通勤过长、空间不足、邻里或物业体验差。换租前务必看清原合同违约与退押金条件，避免新旧租期空窗或违约金超预期。","legalRef":"《民法典》第563条（合同法定解除情形）、第734条（租赁期满继续使用视为不定期租赁）","consumerBenefit":"换得值，不因冲动换租多花冤枉钱","tags":{"clientType":["tenant"],"stage":"pre","layer":"shu"},"scene":"租住前·需求确认"},{"id":"RENT-RIMP-002","domain":"签约前","subScene":"需求确认","name":"租屋改善要和房东谈什么","alias":["改善租","租房装修","租屋改造","和房东谈改善"],"cq":"我想把租的房子稍微改善一下，要注意什么？","ola":"想改善先取得房东书面同意，退租才不会被扣押金","cp":["装修改善须房东同意","书面确认不扣押金","可谈长租换费用减免","恢复原状责任提前约定"],"detail":"租住改善客户希望对租屋做适度装饰或增设。依法承租人改善或增设他物须经出租人同意，未经同意出租人可请求恢复原状或赔偿。建议以书面方式确认，并把\"退租是否恢复原状\"写进合同。","legalRef":"《民法典》第715条（承租人改善增设物须经出租人同意）","consumerBenefit":"改善不被秋后算账，押金有保底","tags":{"clientType":["tenant"],"stage":"pre","layer":"shu"},"scene":"租住前·需求确认"},{"id":"RENT-FAM-001","domain":"签约前","subScene":"需求确认","name":"带娃租房要注意什么","alias":["家庭","孩子","带孩子租房","家庭租房"],"cq":"我带孩子租房，最该关注什么？","ola":"先看户型安全和邻里环境，再看学区与通勤","cp":["户型安全（防护/通风/无隐患）","学区与划片先核实","邻里与社区环境","租赁物危及安全健康可随时解除"],"detail":"家庭租住客户最关心孩子安全与成长环境。除常规产权核验外，应重点看房屋结构安全、通风采光、社区邻里与学区划片真实性，并保留依法解除不安全租赁的权利。","legalRef":"《民法典》第731条（租赁物危及安全或健康，承租人可随时解除）","consumerBenefit":"孩子住得安全，家长更安心","tags":{"clientType":["tenant"],"stage":"pre","layer":"shu"},"scene":"租住前·需求确认"},{"id":"RENT-FAM-002","domain":"签约前","subScene":"需求确认","name":"陪读租房怎么避坑","alias":["陪读","学区","学区房租赁","陪读租约"],"cq":"为了孩子陪读要租房，怎么避免踩坑？","ola":"陪读租约别只签一年，先核验房东真产权，避免中途被赶","cp":["产权与出租人身份核验","租期匹配学业周期","转租/退租条款写清","6个月以上须书面合同"],"detail":"陪读租赁周期与学业绑定，最怕租期中途生变。签约前应核验产权与出租人身份，租期尽量覆盖学业周期，并明确中途退租或转租条件，六个月以上租期必须采用书面形式。","legalRef":"《民法典》第707条（租赁期6个月以上应采用书面形式）、第716条（转租须经出租人同意）","consumerBenefit":"学业不中断，陪读更稳当","tags":{"clientType":["tenant"],"stage":"pre","layer":"shu"},"scene":"租住前·需求确认"},{"id":"RENT-QUAL-001","domain":"签约前","subScene":"需求确认","name":"品质租房看装修还是看社区","alias":["品质","装修","社区","品质租房","租房看什么"],"cq":"我想租得好一点，到底看装修还是看社区？","ola":"装修看环保和质保，社区看物业和服务，别被照片骗","cp":["装修环保与甲醛风险","物业与管家服务","社区安静与配套","出租人须保持租赁物符合约定用途"],"detail":"品质租住客户愿意为体验付费。判断标准应兼顾\"硬装环保（甲醛/质保）\"与\"软性服务（物业/社区/安静）\"。出租人依法应在租期内保持租赁物符合约定用途，租户对不符合安全健康的房屋依法可解除。","legalRef":"《民法典》第708条（出租人保持租赁物符合约定用途）、第731条（危及安全健康可解除）","consumerBenefit":"花得值，住得舒服不被坑","tags":{"clientType":["tenant"],"stage":"pre","layer":"shu"},"scene":"租住前·需求确认"},{"id":"RENT-QUAL-002","domain":"签约前","subScene":"需求确认","name":"长租短租怎么选更划算","alias":["品质长租","长租","短租","长租折扣"],"cq":"我该长租还是短租？","ola":"长租可谈年付折扣，短租灵活但单价高，看你的稳定度","cp":["长租年付折扣空间","短租灵活性与单价","随时解约成本","租赁期限不得超20年"],"detail":"品质租住客户常在稳定与灵活间权衡。长租通常能谈年付折扣且更稳定，短租灵活但单价高、变动成本大。无论长短，租赁期限依法不得超过二十年，期满后继续使用且出租人无异议的视为不定期租赁。","legalRef":"《民法典》第705条（租赁期限不得超过20年）、第734条（期满继续使用视为不定期租赁）","consumerBenefit":"按稳定度选租期，钱花在刀刃上","tags":{"clientType":["tenant"],"stage":"pre","layer":"shu"},"scene":"租住前·需求确认"},{"id":"SRV-AST-001","name":"房屋全权委托托管","domain":"L3-持有阶段","subScene":"委托管理模式","scene":"L3-持有阶段·委托管理模式","cq":"房屋全权委托托管是什么？我需要做什么？","ola":"业主将房屋全部管理权委托托管方，自己无需操心任何租务。","cp":["业主仅收租金，其余全委托","托管方负责招租到退租全流程","适合无精力管理的业主"],"detail":"房屋全权委托托管是指业主将房屋的出租、管理、维护等全部权利委托给专业托管机构，由托管机构代为行使房屋经营管理权的一种服务模式。在全权委托模式下，业主仅需按约定周期收取租金，房屋的招租、租客筛选、合同签订、租金收取、日常维修、租务纠纷处理、退租验收等所有环节均由托管机构负责。该模式的核心价值在于为业主提供'省心'服务，特别适合长期不在本地、工作繁忙或缺乏租赁管理经验的业主。全权委托通常签订3-5年的托管合同，托管方按月收取托管费（一般为租金的5%-15%），部分机构采用'保底租金+分成'模式。业主需注意：全权委托不等于房屋所有权转移，业主仍享有房屋处分权，但需遵守合同约定的委托期限和条件。选择全权委托时，务必确认托管机构的资质、资金监管机制和违约责任条款。","legalRef":"《民法典》第九百二十条：委托人可以特别委托受托人处理一项或者数项事务，也可以概括委托受托人处理一切事务。","consumerBenefit":"免除所有租务管理烦恼，稳定收取租金","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"dao","meetingPhase":[]},"alias":["全权托管","全权委托管理","整屋托管"],"dataRef":"全权委托托管费率行业均值8%-12%","caseRef":"某业主长期旅居海外，全权委托托管机构管理3套房产，年均空置率低于5%，年化收益率达4.2%"},{"id":"SRV-AST-003","name":"独家代理托管","domain":"L3-持有阶段","subScene":"委托管理模式","scene":"L3-持有阶段·委托管理模式","cq":"独家代理托管和普通托管有什么不同？","ola":"业主仅委托一家机构，托管方享有排他经营权，服务更深度。","cp":["业主不得再委托其他机构","托管方投入更多营销资源","通常承诺更短空置期"],"detail":"独家代理托管是指业主在约定期限内，将房屋的租赁经营权独家授予一家托管机构，不得同时委托其他机构或自行出租的托管模式。该模式的核心特征是排他性：托管方因为享有独占经营权，通常会投入更多营销资源和精力进行招租，包括专业摄影、多平台推广、带看优化等，因此往往能实现更短的空置期和更高的出租率。独家代理的托管费率通常略低于全权委托（约5%-10%），因为托管方通过独家经营获得稳定的收益预期。部分独家代理合同会设定'空置期保证'条款，如约定最长空置期不超过30天，否则托管方承担违约责任。业主需注意：独家代理期限内，即使业主自行找到租客，也可能需要向托管方支付佣金。解除独家代理通常需要提前30-60天书面通知，并可能涉及违约金。","legalRef":"《民法典》第九百二十七条：受托人处理委托事务取得的财产，应当交还给委托人。","consumerBenefit":"获得托管方更专注的服务和资源投入，缩短空置期","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"dao","meetingPhase":[]},"alias":["独家托管","独家委托","排他性托管"],"dataRef":"独家代理平均空置期比非独家短7-15天","caseRef":"某业主签约独家代理后，托管方投入专业摄影和多平台推广，7天内完成招租，比自行出租快2周"},{"id":"SRV-AST-004","name":"风险代理托管","domain":"L3-持有阶段","subScene":"委托管理模式","scene":"L3-持有阶段·委托管理模式","cq":"风险代理托管是什么？托管方真的会承担风险吗？","ola":"托管方承诺保底租金，超出部分分成，与业主共担风险。","cp":["托管方承诺最低保底租金","超额租金按比例分成","托管方承担空置风险"],"detail":"风险代理托管是一种托管方与业主共担出租风险的委托模式，其核心特征是托管方向业主承诺'保底租金'——无论房屋是否出租、租金是否收齐，托管方都按约定金额向业主支付租金。实际出租收入超出保底部分，由托管方与业主按约定比例分成（常见7:3或6:4）；若实际收入低于保底，差额由托管方承担。该模式对业主而言收益更稳定，但保底租金通常低于市场租金的10%-20%，这是托管方承担风险的'溢价'。风险代理的托管期限通常较长（3-5年），因为托管方需要通过长期运营来对冲短期空置风险。该模式在长租公寓行业中广泛使用，但也存在较大风险：部分机构以高保底吸引业主签约后因资金链断裂而'跑路'。业主选择风险代理时，务必审查托管方的资金实力、经营年限和资金监管安排。","legalRef":"《民法典》第五百零九条：当事人应当按照约定全面履行自己的义务。","consumerBenefit":"无论是否出租都稳定收租金，空置风险转移给托管方","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"fa","meetingPhase":[]},"alias":["风险托管","保底托管","兜底托管"],"dataRef":"风险代理保底租金一般为市场租金的80%-90%","caseRef":"某业主签约风险代理，保底月租5000元，实际月租6000元，超出部分7:3分成，业主月收入5300元"},{"id":"SRV-AST-007","name":"托管与自行管理对比分析","domain":"L3-持有阶段","subScene":"委托管理模式","scene":"L3-持有阶段·委托管理模式","cq":"房屋托管和自己管，到底哪个更划算？","ola":"自管省费用但费精力，托管省心但有成本，取决于业主时间和能力。","cp":["自管节省托管费8%-15%","托管减少空置期和纠纷损失","远程业主托管性价比更高"],"detail":"托管与自行管理的选择本质上是'金钱成本'与'时间精力成本'的权衡。自行管理的优势在于零托管费支出，业主可直接掌控租客选择、租金定价和维修决策，且无需担心托管方的信用风险。但自管需要业主投入大量时间精力处理招租带看、合同签订、租金催收、维修协调、纠纷调解等事务，尤其对于非本地业主，时间和交通成本可能远超托管费。托管的优势在于专业化运营：托管方拥有租客资源库、多平台推广渠道和标准化的管理流程，通常能实现更短的空置期和更规范的租务处理。综合测算：以月租6000元的房屋为例，年托管费约7200元（10%费率），但托管可能减少1-2个月空置损失（6000-12000元）和维修纠纷损失，实际经济账可能更优。决策建议：本地、有精力、有经验的业主适合自管；异地、繁忙、多套房产的业主更适合托管。","legalRef":"《民法典》第九百二十七条：受托人处理委托事务取得的财产，应当交还给委托人。","consumerBenefit":"理性评估两种模式的真实成本，做出经济最优决策","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"dao","meetingPhase":[]},"alias":["托管vs自管","托管和自管哪个好","自己管还是托管"],"dataRef":"托管平均空置期18天 vs 自管平均空置期35天","caseRef":"某业主3套房产自管年耗费时间约480小时，转托管后释放时间且年净收益仅减少3.2%"},{"id":"SRV-AST-026","name":"招租衔接与快速出租","domain":"L3-持有阶段","subScene":"空置期管理","scene":"L3-持有阶段·空置期管理","cq":"租客退租后怎么尽快找到新租客？缩短空置期？","ola":"提前30天启动招租，多平台同步推广，实现退租与招租无缝衔接。","cp":["租客退租前30天启动招租","多平台同步挂牌推广","灵活定价策略加速成交"],"detail":"招租衔接是缩短空置期的关键策略，核心在于'提前启动、多线并行、快速匹配'。标准招租衔接流程：一、提前30天启动——在现有租客提交退租意向后立即启动招租准备，包括更新房源信息、安排专业拍照、确定招租价格区间；二、多平台同步——在贝壳、自如、58同城、闲鱼等多个平台同步挂牌，扩大曝光量；三、价格策略——设定有竞争力的起租价，可略低于市场价3%-5%以加速成交，避免因坚持高价导致长空置期；四、灵活带看——托管方安排专人7×12小时带看，缩短租客决策周期；五、快速签约——准备标准化租赁合同，看房满意当天可签约。对于托管机构，通常承诺'7-15天出租'，其核心手段是利用租客资源库优先匹配——新房源优先推送给历史租客和在等租客，匹配效率远高于公开挂牌。业主应了解：招租衔接的最佳时间窗口是退租前15-30天，退租后再招租平均多空置10-15天。","legalRef":"《民法典》第七百三十三条：租赁期限届满，承租人应当返还租赁物。","consumerBenefit":"最大程度缩短空置期，减少租金收入中断","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"shu","meetingPhase":[]},"alias":["快速招租","招租衔接","空置期招租"],"dataRef":"提前30天启动招租，空置期平均缩短40%","caseRef":"某托管方在租客退租前25天启动招租，利用租客资源库3天内匹配新租客，实现零空置衔接"},{"id":"SRV-MOV-016","name":"不同搬家方式费用对比","domain":"L2-交易阶段","subScene":"搬家费用与选择","scene":"L2-交易阶段·搬家费用与选择","cq":"自己搬、叫货拉拉、请搬家公司哪种划算？","ola":"少量物品自搬最省，普通家庭选搬家公司，高端需求选日式搬家。","cp":["自搬：仅油费约100-300元最省力少","平台叫车：200-500元适合少量物品","专业搬家公司：500-3000元服务最全"],"detail":"搬家方式的选择应基于物品数量、距离、个人能力和预算综合考量，常见方式有四种。第一，自己搬家——租借面包车/小货车自行装卸，费用仅含油费和车辆租借费约100-300元，适合物品极少（5箱以内）、距离近（10公里内）、有帮手的情况，优点是费用最低，缺点是体力消耗大、无保险保障。第二，平台叫车（货拉拉、滴滴货运等）——通过APP叫车，司机提供车辆和基本搬运协助，费用约200-500元，适合少量到中等物品（10-20箱）同城短距离搬家，优点是下单方便、价格透明，缺点是司机非专业搬运工、物品损坏赔偿额度低（平台通常约定单件上限500元）。第三，专业搬家公司标准服务——提供车辆+工人+基本包装材料，费用约500-3000元，适合普通家庭搬家（20箱以上含家具家电），优点是服务专业、有合同保障、含装卸楼层搬运。第四，日式搬家全流程服务——费用约1500-5000元，适合高收入人群或物品多且贵重的家庭，优点是省心省力全程不动手、含保险。跨城搬家的选择：少量物品可用物流快递寄送（大件走德邦/顺丰大件），大量物品建议选择专业跨城搬家公司。选择建议：优先评估物品数量和价值，贵重物品多选专业公司+保险。","legalRef":"《民法典》第八百零九条至八百四十二条关于运输合同的相关规定。","consumerBenefit":"根据实际需求选择性价比最高的搬家方式，既不浪费也不委屈。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"dao","meetingPhase":[]},"alias":["搬家方式对比","搬家方案","搬家方式选择"],"dataRef":"自己搬家平均费用约200元但物品损坏率约12%，平台叫车平均约350元损坏率约8%，专业搬家公司平均约1200元损坏率约3%。","caseRef":"某客户用平台叫车搬家，司机搬运中摔坏一台价值3000元的显示器，平台按约定仅赔偿500元。"},{"id":"SRV-MOV-020","name":"社区搬家规定与电梯预约","domain":"L2-交易阶段","subScene":"搬家纠纷与衔接","scene":"L2-交易阶段·搬家纠纷与衔接","cq":"搬家需要跟物业报备吗？电梯怎么预约？","ola":"搬家前向物业报备，预约货梯时段，缴押金，遵守噪音时间规定。","cp":["提前向物业申请搬家通行证","预约货梯或专用电梯时段","缴纳搬家押金验收后退还"],"detail":"社区搬家涉及物业管理和邻里关系，了解并遵守社区搬家规定可以避免搬家受阻和纠纷。物业报备流程：大多数小区物业要求搬家前1-3天到物业服务中心办理搬家登记，填写搬家申请表（含搬出/搬入地址、搬家日期和时间段、搬家公司信息），缴纳搬家押金（通常200-500元，搬家完成后经检查公共区域无损坏后退还），领取搬家通行证。电梯预约：高层住宅搬家需预约货梯或专用电梯，通常物业会指定搬家使用货梯的特定时段（如工作日9:00-17:00，周末8:00-12:00），预约时段通常为2-4小时，部分小区收取电梯使用费50-200元/次。搬出和搬入两边的物业都需报备：搬出小区物业需确认搬出物品与业主/租客身份一致，防止盗窃物品搬出；搬入小区物业需确认搬入身份（购房合同或租赁合同），办理入住手续和门禁卡。社区搬家规定通常包括：搬家时间限制（工作日全天、周末仅上午、节假日禁止搬家）、噪音控制、公共区域保护（走廊、电梯、大堂需铺设保护垫，损坏公共设施需赔偿）、车辆停放（搬家车辆需停在指定区域，不可占用消防通道）。未报备物业直接搬家的后果：物业可能阻止搬家车辆进入小区、拒绝使用电梯，导致搬家延误和额外费用。","legalRef":"《物业管理条例》关于业主和使用人遵守物业管理规约的规定。《民法典》第二百八十六条：业主应当遵守法律、法规及管理规约。","consumerBenefit":"提前报备和预约确保搬家顺利进行，避免物业阻拦导致延误。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"shu","meetingPhase":[]},"alias":["物业搬家规定","电梯预约","搬家通行证"],"dataRef":"约70%的小区物业要求搬家前报备，其中高层住宅要求电梯预约的比例达90%。","caseRef":"某客户未提前向新居物业报备，搬家车辆到达小区门口被保安拦下不让进入，等待2小时办理手续后才放行，搬家公司加收超时费200元。"},{"id":"SRV-CLN-003","name":"开荒保洁服务指南","domain":"L3-持有阶段","subScene":"保洁类型与标准","scene":"L3-持有阶段·保洁类型与标准","cq":"什么是开荒保洁？新房装修后必须做吗？","ola":"装修后首次全面清洁，清除建筑垃圾、油漆水泥残留。","cp":["装修后首次全面深度清洁","清除油漆水泥胶水残留","全面除尘除味消毒"],"detail":"开荒保洁是指房屋装修或翻新完成后进行的首次全面彻底清洁，目的是清除装修过程中残留的建筑垃圾、粉尘、油漆点、水泥渍、胶水痕迹等，使房屋达到可入住标准。开荒保洁的必要性：装修后室内粉尘、甲醛、TVOC等有害物质浓度极高，玻璃上的保护膜胶渍、瓷砖上的水泥点、地板上的油漆滴落、门窗轨道内的碎屑等日常保洁无法清除，必须通过专业开荒才能彻底清理。服务内容包括：全屋粗清——清理建筑垃圾和大型杂物、大面积除尘；玻璃清洁——清除玻璃保护膜和胶渍、擦拭玻璃和窗框、清理门窗轨道；地面清洁——清除地面水泥点油漆渍、瓷砖美缝后残留清洁、地板除胶除尘打蜡（如需）；墙面清洁——清除墙面油漆溅点、开关面板周围污渍、踢脚线残留；厨卫清洁——清除瓷砖水泥残留、洁具表面保护膜和胶渍、橱柜内外粉尘清理、五金件除水泥；细节处理——灯具除尘、空调出风口清理、插座开关面板擦拭。开荒保洁需使用专业工具和药剂（铲刀、草酸、除胶剂、水泥克星等），由2-4人团队作业，100平米房屋约需8-12小时。建议在装修完工通风7-14天后、家具搬入前进行开荒保洁。","legalRef":"《民法典》第七百七十条：承揽合同相关规定。装修合同中关于竣工清洁的约定。","consumerBenefit":"彻底清除装修残留有害物质和污渍，确保新房达到安全入住标准。","tags":{"clientType":["seller","tenant"],"stage":"pre","layer":"shu","meetingPhase":[]},"alias":["开荒保洁","装修后保洁","新房开荒"],"dataRef":"装修后室内粉尘量可达日常的50-100倍，甲醛浓度通常超标2-5倍；开荒保洁可使室内可吸入颗粒物降低80%以上。","caseRef":"某业主装修后未做开荒直接入住，3个月后孩子出现呼吸道不适，检测发现室内粉尘和甲醛仍超标，补做开荒后指标恢复正常。"},{"id":"SRV-AST-002","name":"部分委托管理模式","domain":"L3-持有阶段","subScene":"委托管理模式","scene":"L3-持有阶段·委托管理模式","cq":"我不想全部托管，可以只委托部分事项吗？","ola":"业主可选择性委托招租或维修等单项服务，保留其他管理权。","cp":["按需选择委托服务模块","保留部分自主管理权","费用低于全权委托"],"detail":"部分委托管理模式是指业主根据自身需求，将房屋租赁管理中的部分环节委托给托管机构，而保留其余环节自主管理权的灵活托管方式。常见的部分委托组合包括：仅委托招租（托管方负责找租客，后续由业主自行管理）、仅委托维修（业主自行招租收租，维修事项外包）、仅委托租务处理（租客日常沟通、纠纷处理由托管方负责）等。该模式适合有一定管理能力但某些环节力不从心的业主，如本地业主可自行收租但不想处理维修，或擅长招租但不愿处理租客纠纷。部分委托的收费通常按服务模块单独计费，如招租费为1个月租金，维修调度按次收费等。部分委托的优势在于灵活性和成本可控，但需注意业主与托管方之间的责任边界必须清晰界定，避免出现'三不管'地带，如租客报修后的响应责任归属问题。","legalRef":"《民法典》第九百二十条：委托人可以特别委托受托人处理一项或者数项事务。","consumerBenefit":"灵活选择服务，兼顾自主管理与专业支持","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"dao","meetingPhase":[]},"alias":["半委托托管","部分委托","分段托管"],"dataRef":"部分委托单项服务费通常为月租金的50%-100%","caseRef":"某业主仅委托招租模块，托管方2周内完成租客匹配，后续业主自行管理，年节省托管费约8000元"},{"id":"SRV-AST-008","name":"托管模式选择决策","domain":"L3-持有阶段","subScene":"委托管理模式","scene":"L3-持有阶段·委托管理模式","cq":"我该选哪种托管模式？有没有决策方法？","ola":"按业主精力、距离、房源数和风险偏好四维度匹配最优托管模式。","cp":["异地多房优先全权委托","本地少房可部分委托","追求稳定选风险代理"],"detail":"托管模式选择是一个多维度决策过程，需要综合评估业主的个人情况和房源特征。核心决策维度包括四个：一、精力维度——业主是否有时间处理租务，无精力选全权委托，有精力选部分委托；二、距离维度——业主与房屋是否同城，异地选全权委托，同城可部分委托或独家代理；三、房源数维度——1套房源可自管或部分委托，2套以上建议至少部分托管，3套以上优先全权委托；四、风险偏好维度——风险厌恶型选风险代理（保底租金），风险中性型选全权委托，风险承受型选独家代理或自管。决策流程建议：先评估自身四维度得分，再根据得分匹配推荐模式，最后结合托管机构的服务方案做最终选择。特别提醒：没有'最好的'托管模式，只有'最适合的'托管模式，业主应避免被托管机构的营销话术引导而选择不适合自身的模式。","legalRef":"《民法典》第一百六十一条：民事主体可以通过代理人实施民事法律行为。","consumerBenefit":"系统化评估自身需求，避免选错托管模式导致后悔和损失","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"qi","meetingPhase":[]},"alias":["托管模式选择","如何选托管模式","托管方式选择"],"dataRef":"选择匹配度高的托管模式，业主满意度提升40%以上","caseRef":"某业主误选风险代理但实际更看重控制权，半年后转全权委托，产生违约金1.5万元"},{"id":"SRV-AST-013","name":"租金代收代付服务","domain":"L3-持有阶段","subScene":"代运营服务","scene":"L3-持有阶段·代运营服务","cq":"托管方怎么帮我收租金？资金安全吗？","ola":"托管方代收租客租金后按约定周期转入业主账户，需设监管账户。","cp":["租客交租给托管方","托管方按约定周期转付业主","资金应通过监管账户流转"],"detail":"租金代收代付是托管服务中最核心的代运营功能之一，指托管方代为向租客收取租金，再按合同约定的周期和方式转付给业主。标准流程为：租客每月/每季向托管方指定账户缴纳租金→托管方核对到账→扣除托管费等应扣款项→将净租金转入业主指定账户。代收代付的关键风险在于资金安全——托管方收取租金后若未及时转付，甚至挪用资金，将直接损害业主利益。为此，越来越多的城市要求托管机构开设'资金监管账户'（即第三方银行托管账户），租客租金直接进入监管账户，银行按约定自动划转给业主，托管方无法挪用。业主在签约时务必确认：资金流转路径是否经过监管账户、转付周期（月付/季付）、到账时间（T+1/T+3）、逾期转付的违约责任等。对于未使用监管账户的托管方，建议业主要求按月转付并设置到账提醒。","legalRef":"《民法典》第九百二十七条：受托人处理委托事务取得的财产，应当交还给委托人。","consumerBenefit":"免除催租烦恼，按时收到租金，资金流转透明可追溯","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"fa","meetingPhase":[]},"alias":["租金代收","代收租金","租金代付"],"dataRef":"使用监管账户的托管方，租金挪用风险降低90%以上","caseRef":"某托管方未设监管账户，挪用12位业主3个月租金后跑路，业主合计损失超50万元"},{"id":"SRV-AST-018","name":"租客筛选与入驻管理","domain":"L3-持有阶段","subScene":"代运营服务","scene":"L3-持有阶段·代运营服务","cq":"托管方怎么帮我选租客？会筛选哪些内容？","ola":"托管方审核租客身份、信用和收入，匹配优质租客入驻。","cp":["核验租客身份和信用记录","评估租客收入和支付能力","匹配租客与房屋适配度"],"detail":"租客筛选是代运营服务的入口环节，直接决定后续管理的难易程度。专业托管方通常建立多维度的租客筛选体系：一、身份核验——通过身份证验证、人脸识别确认租客真实身份，排除虚假信息；二、信用评估——查询租客的征信记录、法院被执行人信息、历史租赁信用（如是否有欠租、毁约记录）；三、收入验证——要求提供收入证明或银行流水，确认月收入不低于月租金的2-3倍；四、背景调查——了解租客职业、生活习惯（是否吸烟、是否有宠物）、家庭成员构成等；五、适配匹配——将租客需求与房屋条件匹配，如家庭租客匹配大户型、单身租客匹配小户型，降低后续纠纷概率。入驻管理包括：签订租赁合同、收取押金和首期租金、办理入住交接、录入门禁系统、建立租客档案、设置租金代扣等。优质托管方会将租客筛选标准书面化，业主可在合同中约定'不接受'的租客类型。","legalRef":"《民法典》第五百零九条：当事人应当按照约定全面履行自己的义务；《住房租赁条例》第十七条：住房租赁企业应当对承租人身份进行核验。","consumerBenefit":"获得经过严格筛选的优质租客，降低后续管理风险","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"shu","meetingPhase":[]},"alias":["租客筛选","托管招租","租客准入"],"dataRef":"严格筛选后租客违约率降低至3%以下","caseRef":"某托管方因未核实租客征信，签约后发现租客为被执行人，3个月后欠租跑路，业主损失2个月租金"},{"id":"SRV-AST-027","name":"空置期费用承担","domain":"L3-持有阶段","subScene":"空置期管理","scene":"L3-持有阶段·空置期管理","cq":"空置期间物业费、供暖费谁出？损失谁承担？","ola":"空置期费用由业主承担，风险代理模式下保底租金不受影响。","cp":["物业费等固定成本业主承担","普通托管空置损失业主承担","风险代理空置期照付保底租金"],"detail":"空置期费用承担是业主和托管方博弈的焦点问题。在普通托管模式下，空置期间的各项费用和损失由业主承担，具体包括：一、物业费——按月缴纳，空置不停缴；二、供暖费——北方地区冬季供暖费，空置仍需缴纳（部分城市空置房可申请减免20%-30%）；三、水电基础费——水表和电表的月度基础费用；四、贷款利息——如有房贷，月供照常偿还；五、保险费——房屋保险的年度保费；六、托管费——部分托管合同约定空置期减半收取托管费，部分全额收取。以上费用合计，空置1个月的净损失约为月租金的110%-130%（含物业费等持有成本）。风险代理模式下，空置期费用和损失由托管方承担——无论是否出租，托管方都按月向业主支付保底租金，物业费等固定费用通常由托管方代缴后从租金收入中扣除。业主在签约前务必确认空置期的费用分摊规则，尤其是物业费和托管费的收取方式。","legalRef":"《民法典》第七百一十二条：出租人应当履行租赁物的维修义务；《物业管理条例》第四十一条：业主应当根据物业服务合同的约定交纳物业服务费用。","consumerBenefit":"清晰了解空置期费用构成和承担方，做出经济合理的托管模式选择","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"shu","meetingPhase":[]},"alias":["空置期费用","空置期谁承担","空置期成本"],"dataRef":"空置1个月净损失约为月租金的110%-130%","caseRef":"某业主未料空置3个月，物业费+供暖费+贷款利息合计损失1.8万元，远超预期"},{"id":"SRV-AST-033","name":"装修翻新与招租","domain":"L3-持有阶段","subScene":"空置期管理","scene":"L3-持有阶段·空置期管理","cq":"房子不好出租，要不要翻新装修？划算吗？","ola":"翻新可提升租金10%-25%，投入2年内回本才划算。","cp":["翻新可提升租金10%-25%","核心翻新区域为厨卫和墙面","投入需在2年内通过增租回本"],"detail":"装修翻新是解决房源竞争力不足导致长期空置的有效手段，但需精算投入产出比。翻新策略应遵循'性价比优先'原则：一、高回报翻新项——厨卫翻新（投入1-3万元，租金提升15%-25%）、墙面刷新（投入3000-8000元，租金提升5%-10%）、灯具更换（投入1000-3000元，提升视觉效果显著）；二、中回报翻新项——地板更换（投入5000-15000元，租金提升5%-10%）、空调更换（投入3000-8000元，提升竞争力）、储物空间改造（投入2000-5000元）；三、低回报翻新项——豪华装修（投入超10万元，租金提升有限，回本周期长）、非常规风格装修（受众窄，可能反而降低出租率）。翻新决策公式：翻新投入÷月租金增量=回本月数，回本超过24个月不建议投入。特殊场景：长期空置超3个月的房源，可考虑'轻翻新'策略（总投入1-2万元），快速提升出租竞争力，避免继续空置的损失叠加翻新投入。","legalRef":"《民法典》第七百一十二条：出租人应当履行租赁物的维修义务。","consumerBenefit":"通过精准翻新提升房源竞争力和租金水平，加速出租并提高收益","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"qi","meetingPhase":[]},"alias":["翻新招租","装修出租","翻新再租"],"dataRef":"厨卫翻新投资回报率最高，投入1-3万可提升租金15%-25%","caseRef":"某业主投入1.8万元翻新厨卫和刷新墙面，月租金从4500元提升至5500元，14个月回本"},{"id":"SRV-MOV-005","name":"新房搬入前检查清单","domain":"L2-交易阶段","subScene":"搬家流程与准备","scene":"L2-交易阶段·搬家流程与准备","cq":"搬入新房前需要检查哪些项目？","ola":"搬入前检查水电门窗、墙面地面、厨卫设施，拍照存证。","cp":["水电燃气全面通断测试","门窗锁具开关灵活性检查","墙面地面裂缝渗漏排查"],"detail":"新房搬入前的检查是保障居住品质和明确房屋状况责任的关键步骤，应在搬家当天或前一天完成。检查分为六大系统：水路系统——逐个打开厨房和卫生间水龙头检查出水是否正常、排水是否通畅、有无漏水滴水现象，检查水表读数并记录；电路系统——逐个测试各房间开关和插座是否正常通电，检查配电箱各回路标识是否清晰，记录电表读数；燃气系统——检查燃气表读数、燃气阀门开关是否灵活、燃气灶和热水器点火是否正常，闻有无燃气异味；门窗系统——逐扇检查门窗开关是否顺畅、锁具是否完好、密封条是否完整、玻璃有无裂纹；墙面地面——检查墙面有无裂缝、起皮、渗水痕迹，地面瓷砖/地板有无空鼓、翘起、划痕，卫生间和阳台做闭水试验检查防水；设施设备——检查马桶冲水是否正常、油烟机是否运转、空调是否制冷制热、热水器是否出热水。所有检查项目发现的问题应拍照录像存证，形成检查清单并由房东或物业签字确认。对于购买二手房的买家，搬入前检查尤为重要，可及时发现原业主遗留的房屋问题并在保修期内主张维修。租客搬入时的检查清单可作为退租时房屋状况对比的基准。","legalRef":"《民法典》第七百零四条：租赁合同应包含房屋状况及维修责任约定；《商品房买卖合同》关于交付标准的约定。","consumerBenefit":"及时发现房屋问题避免后续维修纠纷，明确搬入时房屋状况。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"shu","meetingPhase":[]},"alias":["搬入检查","新房验收","入住检查"],"dataRef":"新房交付后30天内发现的问题，开发商维修响应率约85%；超期后降至50%以下。","caseRef":"某买家搬入二手房后一个月发现卫生间漏水，因搬入时未做闭水试验拍照存证，原业主和物业互相推诿，维修费自担。"},{"id":"SRV-MOV-010","name":"搬家费用构成与计算方式","domain":"L2-交易阶段","subScene":"搬家费用与选择","scene":"L2-交易阶段·搬家费用与选择","cq":"搬家费用一般怎么算？包含哪些项目？","ola":"搬家费含出车费+人工费+里程费+楼层费+特殊物品附加费。","cp":["基础出车费按车型计","楼层费无电梯每层加收","特殊物品单独计价"],"detail":"搬家费用由多个项目构成，了解费用结构有助于避免被乱收费。主要费用项目包括：第一，出车费/车型费——按车辆类型计费，面包车约200-300元/车适合单身少量物品，厢式货车4.2米约400-600元/车适合一至两室，6.8米货车约800-1200元/车适合三室以上；第二，人工费——按人数和工时计算，2-4人约150-300元/人/次含装卸；第三，里程费——同城含基础里程10-15公里，超出按5-10元/公里加收，跨城按公里计价约8-15元/公里含油费过路费；第四，楼层费——无电梯或电梯无法使用时每层加收20-50元/层/人，通常从第二层开始计费；第五，特殊物品附加费——钢琴500-1500元/台、保险柜300-800元/个、大鱼缸200-500元/个；第六，拆装费——衣柜100-300元、空调200-500元、床架50-150元；第七，其他费用——夜间服务加收30%-50%、周末及节假日加收20%-30%、超时等候费50-100元/小时、包装材料费按实际使用量计。消费者应要求搬家公司提供详细费用清单，一口价报价需明确包含和不包含的项目。","legalRef":"《民法典》第八百一十三条：旅客、托运人或者收货人应当支付票款或者运输费用。","consumerBenefit":"了解费用构成避免被乱收费，精准预算搬家成本。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"shu","meetingPhase":[]},"alias":["搬家费用","搬家价格","搬运费"],"dataRef":"2025年全国同城搬家平均费用：一室一厅约500-800元，两室一厅约800-1500元，三室一厅约1500-3000元。","caseRef":"某客户获报价500元一口价，搬家当天被加收楼层费200元、拆装费300元、超距费150元，实际支付1150元。"},{"id":"SRV-MOV-011","name":"如何选择靠谱的搬家公司","domain":"L2-交易阶段","subScene":"搬家费用与选择","scene":"L2-交易阶段·搬家费用与选择","cq":"怎么选择靠谱的搬家公司？","ola":"查资质口碑比三家，签书面合同，拒绝超低价报价。","cp":["查验营业执照和道路运输许可","查看线上真实评价和投诉记录","至少比较三家报价"],"detail":"选择靠谱的搬家公司是保障搬家顺利和安全的核心决策，应从资质、口碑、服务、价格四个维度评估。资质查验——正规搬家公司应具备营业执照（经营范围含搬家运输服务）和道路运输经营许可证，可要求查看原件或扫描件，并在国家企业信用信息公示系统查询企业注册信息和经营状态；口碑调查——在大众点评、美团、百度口碑等平台查看真实用户评价，重点关注差评内容和商家回复态度，在黑猫投诉、12315平台搜索公司名称查看投诉记录，向朋友邻居推荐获取实际体验反馈；服务评估——靠谱公司应提供免费上门估价或视频估价服务、书面报价单和合同、明确的服务流程和标准、正规发票，客服响应及时且沟通专业；价格比较——联系至少3家公司获取报价，警惕明显低于市场价的报价（可能是低价吸引后加价的陷阱），确认报价包含和不包含的项目，了解超时、超距、特殊物品的计费标准。选择时的红线信号：无法提供营业执照、只留手机号无固定办公电话、报价异常低、拒绝签订书面合同、要求全额预付款、无法提供发票。建议优先选择品牌连锁搬家公司或有较长经营历史的本地公司，购买搬家保险。","legalRef":"《道路运输条例》关于货物运输经营许可的规定；《消费者权益保护法》关于消费者知情权和选择权的规定。","consumerBenefit":"选择靠谱公司避免被坑骗，保障物品安全和维权能力。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"dao","meetingPhase":[]},"alias":["搬家公司选择","搬家服务选择","搬家公司推荐"],"dataRef":"正规搬家公司投诉解决率约75%，无资质'搬家游击队'投诉解决率不足10%。","caseRef":"某客户选择网上低价搬家公司（无营业执照），搬家当天加价3倍，拒绝后被工人威胁，报警后才解决。"},{"id":"SRV-MOV-014","name":"搬家公司服务等级与报价差异","domain":"L2-交易阶段","subScene":"搬家费用与选择","scene":"L2-交易阶段·搬家费用与选择","cq":"不同等级的搬家服务有什么区别？价格差多少？","ola":"经济型仅运输，标准型含装卸，高端型含打包拆装还原全流程。","cp":["经济型：仅车辆运输约300-600元","标准型：含人工装卸约500-1200元","高端型：全流程服务约1500-5000元"],"detail":"搬家公司的服务等级通常分为三个档次，价格和服务内容差异显著。经济型服务（约300-600元/车）——仅提供车辆和司机运输服务，不提供人工装卸，客户需自行搬上搬下所有物品，适合物品少、有帮手、预算有限的客户，如学生搬家、单身公寓少量物品搬迁。标准型服务（约500-1200元/车）——提供车辆、司机及2-4名搬运工人，包含装卸服务、楼层搬运、基本包装材料，适合普通家庭搬家，是目前市场上选择最多的服务类型。高端型/日式搬家服务（约1500-5000元/次）——提供全流程搬家服务，包括上门估价、专业打包分类、家具拆装、物品运输、到新居后拆包归位还原、垃圾清理甚至新居保洁，客户全程无需动手，适合高收入家庭、工作繁忙人士、老人搬家。选择服务等级时应考虑：物品数量和复杂度、个人体力和帮手情况、时间紧迫程度、预算承受能力。报价差异的原因：高端服务需要经过专业培训的搬家团队、全套包装材料成本、更长服务时间（高端服务通常需6-12小时，标准型2-4小时）、更高的保险覆盖额度。部分搬家公司还提供中间档服务（如'半日式'——含打包但不含还原），消费者可根据需求灵活选择。","legalRef":"《消费者权益保护法》第九条：消费者享有自主选择商品或服务的权利。","consumerBenefit":"根据需求选择合适服务等级，避免过度消费或服务不足。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"dao","meetingPhase":[]},"alias":["搬家服务等级","搬家服务档次","搬家套餐"],"dataRef":"标准型搬家服务市场份额约65%，经济型约20%，高端型约15%但增速最快。","caseRef":"某企业高管选择日式搬家服务花费4800元，全程无需动手，4人团队8小时完成打包搬运还原及保洁，评价'物有所值'。"},{"id":"SRV-MOV-015","name":"搬家附加费用说明","domain":"L2-交易阶段","subScene":"搬家费用与选择","scene":"L2-交易阶段·搬家费用与选择","cq":"搬家除了基本费用还有哪些附加费用？","ola":"附加费含楼层费、超距费、超时费、特殊物品费及夜间节假日加价。","cp":["楼层费：无电梯每层20-50元","超时等候费：50-100元/小时","夜间节假日加收20%-50%"],"detail":"搬家附加费用是除基本出车费和人工费之外可能产生的额外收费项目，了解这些费用有助于准确预算和避免纠纷。常见附加费用包括：楼层费——当房屋无电梯或电梯无法使用时按楼层加收，通常从第二层开始计费，每层每名工人20-50元；超距费——搬家距离超出基础里程（通常10-15公里）后按每公里5-15元加收；超时等候费——因客户原因导致工人等待超过约定免费等候时间（通常30-60分钟）后按50-100元/小时加收；特殊物品附加费——钢琴500-1500元、保险柜300-800元、大鱼缸200-500元；拆装费——衣柜100-300元、床架50-150元、空调200-500元；包装材料费——纸箱15-30元/个、气泡膜5-15元/米、编织袋10-20元/个，按实际使用量计；夜间服务加价——晚18点后加收30%-50%；节假日加价——周末加收20%、法定节假日加收30%-50%；多点装卸费——每增加一个装卸点加收100-200元；车辆通行费——过路费、停车费由客户承担。建议搬家前要求搬家公司提供完整附加费用清单并书面确认，避免到现场后被临时加价。","legalRef":"《价格法》第十三条：经营者提供服务和收取费用，应当按照规定明码标价。《消费者权益保护法》第八条：消费者享有知悉服务真实情况的权利。","consumerBenefit":"提前了解所有可能的附加费用，精准预算避免被临时加价。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"shu","meetingPhase":[]},"alias":["搬家额外费用","搬家附加收费","搬家杂费"],"dataRef":"搬家附加费用平均占总费用的25%-40%，其中楼层费和拆装费占比最高。","caseRef":"某客户搬家基础报价600元，因无电梯5楼、需拆装衣柜和空调、超时等候1.5小时，附加费合计830元，总费用1430元。"},{"id":"SRV-MOV-017","name":"搬家合同签订要点","domain":"L2-交易阶段","subScene":"搬家费用与选择","scene":"L2-交易阶段·搬家费用与选择","cq":"签搬家合同时需要注意什么？","ola":"合同写明费用明细、赔偿标准、服务范围、违约责任，拒签空白合同","cp":["费用明细逐项列明含全部费用","赔偿标准和上限明确约定","违约责任和服务范围书面确认"],"detail":"搬家合同是保障消费者权益和解决纠纷的法律依据，签订时需重点关注以下条款。第一，服务信息条款——合同应明确搬出地址、搬入地址、搬家日期和时间、车辆类型和数量、工人人数、预计服务时长。第二，费用条款——合同应逐项列明出车费、人工费、里程费、楼层费、拆装费、特殊物品附加费、包装材料费、其他可能费用，最后注明'总价含上述全部费用，不再另行加收'。第三，赔偿条款——合同应约定物品损坏或丢失的赔偿标准：每件赔偿上限、是否按实际价值赔偿、赔偿支付方式和时限；消费者应争取将赔偿上限提高至合理水平，贵重物品单独列明价值和赔偿标准。第四，服务范围条款——明确搬家公司提供哪些服务和不提供哪些服务。第五，违约责任条款——搬家公司迟到或爽约的赔偿、客户取消或改期的费用。第六，保险条款——是否含运输保险、保险金额、理赔流程。第七，争议解决条款——约定争议解决方式和管辖法院。签订时的注意事项：仔细阅读全部条款再签字，不接受空白合同，口头承诺必须写入合同正文，保留合同原件和付款凭证。","legalRef":"《民法典》第八百零九条：运输合同是承运人将货物从起运地点运输到约定地点，托运人支付运输费用的合同。第四百七十条：合同内容应包括标的、数量、质量、价款、履行期限、违约责任等。","consumerBenefit":"合同是维权的根本依据，完善的合同条款可避免90%以上的纠纷。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"fa","meetingPhase":[]},"alias":["搬家合同","搬家协议","搬迁合同"],"dataRef":"签订书面搬家合同的消费者纠纷解决率约78%，未签合同的不足15%。","caseRef":"某客户签订搬家合同但未约定赔偿上限，搬家时电视机损坏，搬家公司主张按行业惯例每件赔500元，法院判决按实际价值赔偿3800元。"},{"id":"SRV-MOV-021","name":"租客搬家注意事项","domain":"L2-交易阶段","subScene":"搬家纠纷与衔接","scene":"L2-交易阶段·搬家纠纷与衔接","cq":"租客搬家退租时需要注意什么？","ola":"退租搬家需交接房屋、恢复原状、清空物品、结清费用、拍照留证。","cp":["退租前恢复房屋原状并拍照","结清水电燃气物业费用","物品全部清空不留遗弃物"],"detail":"租客搬家退租是租赁关系结束的关键环节，处理不当可能导致押金被扣或承担额外责任。退租搬家应在合同到期前7-14天开始准备。第一步，通知房东——按合同约定提前通知房东退租意向（通常需提前30天书面通知），协商退房时间和交接安排。第二步，房屋恢复原状——按合同约定将房屋恢复至搬入时状态：修复正常使用造成的墙面污渍、修复因使用不当造成的损坏（如墙面钉孔、地板划痕）、恢复房东不同意改造的装修改动；搬入时的房屋状况照片是恢复的参照标准。第三步，物品清空——所有个人物品全部搬出，不留任何遗弃物（遗留物品房东有权处置并从押金扣除清理费用），包括阳台、储物间、橱柜内部。第四步，费用结清——结清退租前所有水电燃气费用（记录最终表读数并拍照）、物业费、网络宽带费，办理过户或销户手续。第五步，房屋交接——与房东约定时间共同验房，逐项检查房屋状况和配置物品清单，对照搬入时的照片和清单确认无新增损坏，双方签字确认交接单。第六步，押金退还——确认房屋交接无误后，要求房东在约定时间内退还押金，扣除合理费用后出具收据。退租搬家当天应先搬完物品再交还钥匙；如房东无法到场，可通过视频方式验房并保留录像证据。","legalRef":"《民法典》第七百三十三条：租赁期间届满，承租人应当返还租赁物。返还的租赁物应当符合按照约定或者根据租赁物的性质使用后的状态。第七百一十四条：承租人应当妥善保管租赁物。","consumerBenefit":"规范退租流程避免押金被扣，顺利结束租赁关系。","tags":{"clientType":["tenant"],"stage":"mid","layer":"shu","meetingPhase":[]},"alias":["租客搬家","租房搬家","退租搬家"],"dataRef":"租客退租押金纠纷中，约40%因房屋恢复和物品清理问题引发，平均争议金额约1500元。","caseRef":"某租客退租时遗留旧衣柜和杂物未清运，房东花费300元请人清理并从押金扣除，租客认为不合理但无证据证明搬出时已清空。"},{"id":"SRV-MOV-025","name":"跨城搬家服务指南","domain":"L2-交易阶段","subScene":"搬家纠纷与衔接","scene":"L2-交易阶段·搬家纠纷与衔接","cq":"跨城/跨省搬家怎么操作？费用和注意事项？","ola":"跨城搬家按公里计费，选专线物流或搬家公司，提前规划保险。","cp":["跨城搬家按公里数计价约8-15元/公里","选择专线物流或专业跨城搬家","贵重物品随身携带或保价运输"],"detail":"跨城搬家与同城搬家在费用、时效、风险和服务方式上存在显著差异，需要更充分的准备。跨城搬家的主要方式：第一，专业跨城搬家公司——提供门到门服务，按公里数计价约8-15元/公里含油费过路费，另加人工费和装卸费，适合物品较多（20箱以上含家具家电）的家庭，费用通常3000-15000元，时效1-3天。第二，物流公司零担运输——将物品打包后通过德邦、顺丰等物流公司寄送，费用按重量和体积计算，适合物品中等（10-30箱无大型家具），费用约1000-5000元，时效3-7天，缺点是需自行打包送至网点或到货后自行取货或付费配送上门。第三，集装箱/整车运输——包一辆货车直达，适合物品量大，费用约5000-20000元，时效1-2天。第四，少量物品快递——适合物品极少的情况。跨城搬家的特殊注意事项：运输时间较长，易碎品需特别加固包装；贵重物品和重要证件随身携带不托运；家具家电长途运输损坏风险高，务必购买运输保险；新城市的物业报备、水电燃气开通需提前安排；跨城搬家合同应特别约定运输时效和到达后验货流程。建议提前2-3周开始准备，比价3家以上服务商。","legalRef":"《民法典》第八百一十一条：承运人应当在约定期限内将货物运输到约定地点。第八百一十四条：货物在运输过程中因不可抗力灭失的，承运人不承担责任；货物部分灭失的，托运人有权拒绝支付该部分运费。","consumerBenefit":"选择最适合的跨城搬家方式，控制成本并保障物品安全。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"dao","meetingPhase":[]},"alias":["跨城搬家","异地搬家","长途搬家"],"dataRef":"跨城搬家平均费用：500公里约3000-6000元，1000公里约6000-12000元，2000公里约10000-25000元。","caseRef":"某客户从北京跨城搬家至成都（约1800公里），选择专业跨城搬家公司门到门服务，费用9800元含保险，2天到达，无损坏。"},{"id":"SRV-CLN-009","name":"保洁服务费用参考","domain":"L3-持有阶段","subScene":"保洁费用与选择","scene":"L3-持有阶段·保洁费用与选择","cq":"保洁服务一般多少钱？怎么收费的？","ola":"日常35-50元/时，深度8-15元/平，开荒8-20元/平","cp":["日常保洁按小时计约35-50元","深度清洁按平米计约8-15元","开荒保洁按平米计约8-20元"],"detail":"保洁服务费用根据服务类型、房屋面积、清洁难度和所在城市差异较大。各类保洁服务费用参考：日常保洁——按小时计费约35-50元/小时，或按次计费60-90平米约150-250元/次、90-120平米约200-350元/次。深度清洁——按面积计费约8-15元/平米，90平米约700-1350元，需6-8小时1-2人作业。开荒保洁——按面积计费约8-20元/平米，100平米约800-2000元，需1-2天2-4人作业。专项清洁——油烟机拆洗150-300元/台、空调清洗100-200元/台、洗衣机清洗100-200元/台、冰箱清洗80-150元/台、床垫除螨80-150元/张、沙发清洗200-500元/套。玻璃清洁——室内50-100元/间，外窗高空100-300元/扇。影响价格的因素：城市等级（一线城市比三四线高30%-50%）、服务时段（周末和节假日加收20%-30%、夜间加收50%）、清洁难度（宠物家庭、重油厨房加收20%-50%）、清洁用品（部分含清洁剂，部分另收费）。建议比价3家以上，确认报价包含和不包含的项目。","legalRef":"《价格法》第十三条：经营者提供服务应按规定明码标价。《消费者权益保护法》关于消费者知情权的规定。","consumerBenefit":"了解市场行情合理预算，避免被高价宰客或低价陷阱。","tags":{"clientType":["seller","tenant"],"stage":"pre","layer":"shu","meetingPhase":[]},"alias":["保洁费用","保洁价格","清洁费用"],"dataRef":"2025年全国保洁服务平均价格：日常保洁约40元/小时，深度清洁约11元/平米，开荒保洁约13元/平米。","caseRef":"某客户预约深度清洁获报价8元/平米，实际服务时被告知不含厨房和卫生间深度清洁，需另加300元，总价远超预期。"},{"id":"SRV-CLN-010","name":"如何选择靠谱的保洁公司","domain":"L3-持有阶段","subScene":"保洁费用与选择","scene":"L3-持有阶段·保洁费用与选择","cq":"怎么选择靠谱的保洁服务公司？","ola":"查资质口碑比三家，确认员工背景调查和保险，签服务协议。","cp":["查验营业执照和家政服务许可","查看真实评价和投诉记录","确认员工持健康证和背景调查"],"detail":"选择靠谱的保洁公司关系到家庭财产安全和清洁服务质量，应从资质、人员、口碑、服务四个维度评估。资质查验——正规保洁公司应具备营业执照（经营范围含家政或清洁服务），可在国家企业信用信息公示系统查询，优先选择家政行业协会会员企业。人员管理——靠谱公司对保洁员有严格筛选：持有效健康证（每年体检更新）、身份背景调查（无犯罪记录）、岗前培训和专业技能考核、统一着装佩戴工牌、签订劳动合同并购买意外保险。口碑调查——在大众点评、美团、58同城等平台查看真实评价，重点关注差评内容和商家回复，在黑猫投诉搜索公司名称，向朋友邻居获取推荐。服务评估——靠谱公司应提供明确的服务标准和范围清单、书面报价和预约确认、服务协议或合同、正规发票、品质监督和投诉渠道、不满意返工或退款承诺。选择时的红线信号：无法提供营业执照、保洁员无健康证或身份不明、无固定客服电话只有个人微信、要求全额预付大额费用、拒绝签订服务协议。建议优先选择品牌连锁家政公司或经营3年以上的本地公司，首次建议先预约单次试服务。","legalRef":"《消费者权益保护法》关于消费者知情权和选择权的规定。《家政服务业管理暂行办法》关于家政服务机构和人员资质的要求。","consumerBenefit":"选择靠谱公司保障家庭财产安全和清洁质量，减少纠纷风险。","tags":{"clientType":["seller","tenant"],"stage":"pre","layer":"dao","meetingPhase":[]},"alias":["保洁公司选择","保洁服务选择","家政公司筛选"],"dataRef":"正规保洁公司投诉解决率约70%，个人保洁员（非公司管理）投诉解决率不足20%。","caseRef":"某客户通过微信群找个人保洁员，保洁时偷走家中现金和首饰，因无公司信息和合同无法追责。"},{"id":"SRV-CLN-011","name":"保洁服务方式对比","domain":"L3-持有阶段","subScene":"保洁费用与选择","scene":"L3-持有阶段·保洁费用与选择","cq":"钟点工、保洁公司、平台预约哪种保洁方式好？","ola":"钟点工灵活便宜，保洁公司规范有保障，平台预约便捷透明。","cp":["钟点工灵活便宜但无保障","保洁公司规范有保险","平台预约便捷价格透明"],"detail":"保洁服务方式主要有三种，各有优劣，应根据家庭需求和安全考量选择。第一种，个人钟点工/阿姨——通过熟人推荐或社区介绍找到的个人保洁员，按小时收费约25-40元/小时（比公司低20%-30%），优点是价格便宜、人员固定、沟通灵活、长期合作熟悉家庭情况，缺点是无保险保障（保洁员受伤或损坏物品难追责）、无服务标准和监督、无投诉渠道、人员稳定性差（可能随时不来）。第二种，保洁公司派员——与正规家政保洁公司签约，公司派遣经过培训的保洁员上门服务，按小时或按次收费约35-60元/小时，优点是有服务标准和培训、公司购买保险（员工意外险和第三者责任险）、有投诉和返工机制、有合同保障，缺点是价格较高、可能每次派不同人员、需要预约排期。第三种，互联网平台预约——通过天鹅到家、58到家、美团等平台在线预约保洁服务，优点是下单便捷、价格透明、可看评价选人、平台有保障机制，缺点是平台抽成导致实际保洁员收入较低可能影响服务质量、高峰期可能加价、部分平台对保洁员管理不严格。选择建议：注重安全和保障选保洁公司，注重性价比和灵活性选固定钟点工，注重便捷和透明选平台预约；首次使用建议选有保险保障的方式。","legalRef":"《民法典》第一千一百九十二条：个人之间形成劳务关系，提供劳务一方造成他人损害的，由接受劳务一方承担侵权责任。《家政服务业管理暂行办法》关于服务机构责任的规定。","consumerBenefit":"根据需求选择最适合的保洁方式，平衡价格、安全和便捷性。","tags":{"clientType":["seller","tenant"],"stage":"pre","layer":"dao","meetingPhase":[]},"alias":["保洁方式对比","保洁服务类型","保洁方案选择"],"dataRef":"保洁服务方式市场份额：平台预约约45%、保洁公司约35%、个人钟点工约20%。","caseRef":"某客户雇佣个人钟点工保洁时打碎价值3000元的花瓶，因无保险和合同，钟点工仅愿赔200元，客户自担损失。"},{"id":"SRV-CLN-013","name":"保洁套餐与单次服务选择","domain":"L3-持有阶段","subScene":"保洁费用与选择","scene":"L3-持有阶段·保洁费用与选择","cq":"保洁选单次还是买套餐划算？套餐怎么选？","ola":"长期需求选套餐省20%-30%，偶尔需求选单次更灵活无风险。","cp":["长期需求选套餐优惠大","偶尔需求选单次无预付风险","套餐先试1-3月满意再续"],"detail":"保洁套餐与单次服务的选择取决于家庭清洁需求的频率和稳定性，需综合考虑价格优惠和预付风险。单次服务特点：按次或按小时付费，无需预付大额费用，随时预约随时服务，灵活度高无绑定风险，适合清洁需求不固定或首次体验的家庭，价格通常是基准价无优惠。保洁套餐特点：预付一定期限费用，享受固定频次保洁，价格比单次优惠20%-30%，适合有规律清洁需求的家庭。常见类型：月度套餐（4次/月，适合每周1次）、双周套餐（2次/月，适合每两周1次）、年度套餐（48次或24次/年）。选择注意事项：第一，先试后买——先预约1-2次单次服务确认质量后再购套餐；第二，短期优先——套餐期限不超过3个月，避免商家停业跑路；第三，确认条款——包含的服务类型（日常还是深度）、单次时长、清洁用品是否含、改期取消规则、退款政策、过期处理；第四，金额控制——月度不超500元、季度不超1500元。费用对比：以90平米日常保洁为例，单次200元×4次=800元/月，套餐价约560-640元/月，节省160-240元。","legalRef":"《消费者权益保护法》第五十三条：经营者以预收款方式提供服务的，未按照约定提供的，应当按照消费者的要求履行约定或退回预付款。","consumerBenefit":"根据需求选择最优付费方式，既享受优惠又控制风险。","tags":{"clientType":["seller","tenant"],"stage":"pre","layer":"dao","meetingPhase":[]},"alias":["保洁套餐选择","单次vs套餐","保洁包月"],"dataRef":"保洁套餐预付消费纠纷中，商家停业跑路占比约45%，服务质量下降引发的退款纠纷约35%。","caseRef":"某客户购买年度保洁套餐预付4800元，使用3个月后家政公司更换保洁员导致服务质量下降，要求退款被扣30%违约金。"},{"id":"SRV-CLN-016","name":"保洁服务合同要点","domain":"L3-持有阶段","subScene":"保洁费用与选择","scene":"L3-持有阶段·保洁费用与选择","cq":"签保洁服务合同时要注意什么？","ola":"合同写明服务范围、价格、赔偿标准、保险和退款条款。","cp":["服务范围和标准逐项列明","损坏赔偿标准和保险约定","退款和投诉处理条款明确"],"detail":"保洁服务合同是保障消费者权益和处理纠纷的法律依据，无论单次还是套餐都应签订书面协议。合同应包含的核心条款：第一，服务信息——服务类型、地址、频次和时间、每次时长、保洁员人数。第二，服务范围——详细列明清洁区域和项目清单，明确包含和不包含的内容（如'含厨房灶台表面清洁，不含油烟机拆洗'）。第三，费用条款——单价或总价、计费方式、付款方式和时间、清洁用品费用由谁承担、是否含税发票。第四，赔偿条款——保洁中造成物品损坏的赔偿标准（按实际价值赔偿还是固定额度）、赔偿支付方式和时限、贵重物品特殊约定。第五，保险条款——保洁公司是否购买第三者责任险、保险金额和覆盖范围、理赔流程。第六，安全条款——保洁员持健康证和身份认证的承诺、客户贵重物品保管提醒。第七，变更和取消——客户改期或取消的规则和费用、保洁公司改派人员的通知义务。第八，退款条款——套餐未使用部分的退款规则、退款比例和时限。第九，投诉和争议解决——投诉渠道和响应时限、争议解决方式。签订时注意：不接受空白协议、口头承诺写入正文、保留合同原件和付款凭证。","legalRef":"《民法典》第七百七十条至七百八十七条承揽合同相关规定。第四百七十条：合同内容应包括标的、数量、质量、价款、履行期限、违约责任等。","consumerBenefit":"完善的合同条款保障权益，纠纷发生时有据可依。","tags":{"clientType":["seller","tenant"],"stage":"pre","layer":"fa","meetingPhase":[]},"alias":["保洁合同","保洁协议","家政服务合同"],"dataRef":"签订书面保洁合同的消费者纠纷解决率约72%，未签合同的不足20%。","caseRef":"某客户未签合同仅口头约定保洁范围，保洁后认为卫生间未清洁到位，保洁公司主张'日常保洁不含卫生间深度清洁'，因无书面约定无法维权。"},{"id":"SRV-CLN-017","name":"保洁服务预约与安排","domain":"L3-持有阶段","subScene":"保洁费用与选择","scene":"L3-持有阶段·保洁费用与选择","cq":"保洁服务怎么预约？需要提前多久？","ola":"日常提前1-2天，深度提前3-5天，春节前需提前2周。","cp":["日常保洁提前1-2天预约","深度清洁提前3-5天","节假日前需提前1-2周"],"detail":"保洁服务的预约时机和安排方式直接影响服务可用性和价格，合理规划可避免临时约不到人或高峰期加价。预约渠道：电话预约适合需详细沟通的客户；线上预约通过APP/小程序/平台在线下单，可实时查看可用时间段和价格；微信预约适合长期固定合作的客户。预约时机建议：日常保洁工作日提前1-2天，周末提前2-3天；深度清洁提前3-5天（需协调1-2名保洁员较长时间）；开荒保洁提前5-7天（需组建团队和准备专业工具）；专项清洁提前3-5天；节假日（特别是春节前1-2周）需提前1-2周且价格上浮30%-50%。预约时需确认的信息：服务类型和范围、服务地址、预约日期和时间段（建议选择白天自然光好的时段）、房屋面积和户型、特殊清洁需求（如宠物家庭、有婴幼儿、特殊材质表面）、清洁用品由谁提供、预计费用和付款方式、保洁员人数和预计到达时间。预约后的注意事项：前一天确认到达时间、整理贵重物品和隐私物品、告知保洁员家中特殊情况（宠物、过敏源、不能碰的物品）、确保家中有人或安排钥匙交接。","legalRef":"《民法典》第七百七十一条：承揽合同当事人可以约定承揽工作的履行期限。","consumerBenefit":"合理规划预约时机确保服务可用，避免高峰期加价和临时约不到人。","tags":{"clientType":["seller","tenant"],"stage":"pre","layer":"fa","meetingPhase":[]},"alias":["保洁预约","保洁排期","保洁预约流程"],"dataRef":"保洁服务高峰期（春节前2周）价格上浮30%-50%，预约等待时间从1天延长至5-7天。","caseRef":"某客户春节前3天才预约保洁，多家公司已满档，最终以平时2倍价格约到服务且质量不佳。"},{"id":"SRV-AST-005","name":"托管公司与中介公司的区别","domain":"L3-持有阶段","subScene":"委托管理模式","scene":"L3-持有阶段·委托管理模式","cq":"房屋托管公司和中介公司有什么区别？我该找哪个？","ola":"托管是持续管理，中介是撮合交易，两者角色和收费完全不同。","cp":["中介只负责撮合，不参与管理","托管提供持续性运营服务","中介按次收费，托管按周期收费"],"detail":"房屋托管公司与中介公司的本质区别在于服务角色和持续周期。中介公司（房地产经纪机构）扮演的是居间角色，核心职责是撮合房东与租客达成租赁交易，收取一次性佣金（通常为1个月租金），交易完成后服务即终止。托管公司则扮演的是受托人角色，在委托期限内持续负责房屋的运营管理，包括招租、租客管理、维修、收租、纠纷处理等全流程服务，按月收取托管费。另一个关键区别是法律关系：中介关系中，租赁合同由房东与租客直接签订；托管关系中，租赁合同通常由托管方与租客签订，托管方再与业主签订托管合同。因此，托管方的责任更重、服务更深，但业主对房屋的控制权也相应减少。选择建议：仅需招租的业主可找中介，需要持续管理的业主应选择托管。","legalRef":"《民法典》第九百二十三条：受托人应当亲自处理委托事务；《民法典》第九百六十一条：中介合同是中介人向委托人报告订立合同的机会或者提供订立合同的媒介服务。","consumerBenefit":"清晰理解两种服务差异，避免选错服务类型导致后续问题","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"dao","meetingPhase":[]},"alias":["托管vs中介","托管机构与中介区别","房屋托管和中介一样吗"],"dataRef":"中介佣金通常为月租金的100%，托管费为月租金的5%-15%","caseRef":"某业主误将托管当中介签约，发现中介仅负责招租后租客纠纷无人处理，损失2个月租金"},{"id":"SRV-AST-006","name":"托管费用标准与收费方式","domain":"L3-持有阶段","subScene":"委托管理模式","scene":"L3-持有阶段·委托管理模式","cq":"托管费一般怎么收？行业标准是多少？","ola":"托管费通常为月租金5%-15%，按月收取或从租金中扣除。","cp":["全权委托费率8%-15%","部分委托按模块单独计费","风险代理从分成中提取"],"detail":"房屋托管费用是业主委托托管机构管理房屋所支付的服务报酬，其收费标准和方式因托管模式、服务内容和地区而异。目前行业常见的收费方式有以下几种：一、按月费率收取，即每月从租金中扣除一定比例作为托管费，全权委托一般为月租金的8%-15%，部分委托按模块收费（如招租费1个月租金、维修调度费每月100-300元等）；二、固定月费，不随租金浮动，适用于高端托管服务，月费通常2000-5000元；三、分成模式，风险代理中托管方从超额租金中按比例分成（常见30%-50%）；四、一次性收费，如仅招租服务收取1个月租金作为服务费。此外，部分托管机构还会收取'空置期管理费'（空置期间按月收取较低费用）和'维修基金'（按月预存用于维修）。业主需注意：托管费之外可能还有隐形收费，如广告推广费、租客替换费等，签约前务必索要完整费用清单。","legalRef":"《民法典》第九百二十八条：受托人完成委托事务的，委托人应当按照约定向其支付报酬。","consumerBenefit":"了解行业标准费率，避免被过高收费或隐形收费","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"shu","meetingPhase":[]},"alias":["托管费率","托管收费","托管管理费"],"dataRef":"一线城市全权托管费率均值10.5%，二线城市8.3%","caseRef":"某业主签约时仅关注托管费率8%，后发现另有'租客替换费'每次2000元，全年实际费率超13%"},{"id":"SRV-AST-010","name":"托管机构资质与备案","domain":"L3-持有阶段","subScene":"委托管理模式","scene":"L3-持有阶段·委托管理模式","cq":"托管公司需要什么资质？怎么判断是否合规？","ola":"合规托管机构需具备营业执照、房产经纪备案和住房租赁备案。","cp":["必须持有工商营业执照","需完成房地产经纪机构备案","住房租赁企业需专项备案"],"detail":"托管机构的资质合规是业主选择托管服务的首要审查事项。根据现行法规，从事房屋托管业务的企业至少需要具备以下资质：一、工商营业执照，经营范围应包含'住房租赁经营'或'物业管理'或'房地产经纪'等相应类目；二、房地产经纪机构备案证，由住建部门颁发，证明其具有从事房地产经纪服务的资格；三、住房租赁企业备案，根据《住房租赁条例》要求，从事住房租赁经营的企业需向住建部门备案。此外，部分城市还要求托管机构缴纳'租赁保证金'或开设'资金监管账户'。业主审查资质时，可通过国家企业信用信息公示系统查询营业执照信息，通过当地住建委官网查询备案情况。特别警惕'无照经营'和'超范围经营'的托管机构，这类机构往往以高保底租金吸引业主，但缺乏法律保障。","legalRef":"《住房租赁条例》第十五条：住房租赁企业应当依法办理备案；《房地产经纪管理办法》第十一条：房地产经纪机构及其分支机构应当自领取营业执照之日起30日内备案。","consumerBenefit":"识别合规托管机构，降低因托管方不合规导致的法律和经济风险","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"fa","meetingPhase":[]},"alias":["托管机构资质","托管公司备案","托管方资质审查"],"dataRef":"约35%的托管纠纷涉及无资质或超范围经营机构","caseRef":"某业主委托未备案托管机构，机构跑路后因无监管账户，业主损失6个月租金且追偿困难"},{"id":"SRV-AST-014","name":"租务处理与租客沟通","domain":"L3-持有阶段","subScene":"代运营服务","scene":"L3-持有阶段·代运营服务","cq":"托管期间租客的问题谁来处理？包括哪些内容？","ola":"托管方全权负责租客日常沟通和租务响应，业主无需介入。","cp":["日常租客咨询由托管方响应","投诉和纠纷由托管方协调处理","紧急事务托管方先行处理再通知"],"detail":"租务处理是代运营服务中工作量最大的环节，涵盖租客入住到退租期间的所有日常沟通和事务处理。具体服务内容包括：一、日常沟通——租客关于房屋使用、设施操作、物业规则等咨询的响应；二、投诉处理——租客对噪音、邻扰、物业服务等投诉的受理和协调；三、维修响应——租客报修的接收、评估和调度（详见维修调度条目）；四、费用答疑——租客对租金、水电费、物业费等账务问题的解答；五、纠纷调解——租客与邻居或物业之间的纠纷协调；六、续租沟通——租赁到期前的续租意向确认和条件协商。托管方通常设有7×12或7×24小时租务热线，紧急事务（如漏水、停电）承诺2小时内响应。业主需注意：虽然租务处理由托管方负责，但重大事项（如租金调整、租客违约、法律纠纷）托管方应及时通知业主，业主应保留对重大决策的知情权和参与权。","legalRef":"《民法典》第九百二十二条：受托人应当按照委托人的指示处理委托事务。需要变更委托人指示的，应当经委托人同意。","consumerBenefit":"免除与租客直接沟通的烦恼，专业团队高效处理租务","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"shu","meetingPhase":[]},"alias":["租务处理","租客沟通","租务管理"],"dataRef":"专业租务团队平均响应时间4小时 vs 业主自行处理平均24小时","caseRef":"某业主自行管理时因未及时响应租客漏水报修，导致地板损毁赔偿1.2万元，托管后类似问题2小时响应"},{"id":"SRV-AST-015","name":"维修调度与保养管理","domain":"L3-持有阶段","subScene":"代运营服务","scene":"L3-持有阶段·代运营服务","cq":"托管期间房屋需要维修怎么处理？费用谁出？","ola":"托管方统一调度维修，小额从维修基金扣，大额需业主确认。","cp":["托管方24小时内响应报修","设维修基金支付日常维修","大额维修需业主审批确认"],"detail":"维修调度与保养管理是托管代运营中技术性最强、争议最多的服务模块。托管方通常建立标准化的维修响应流程：租客报修→托管方分类评估（紧急/一般/非必要）→调度维修人员→完成维修→验收反馈。维修费用承担规则通常为：日常小修（单次500元以下，如换灯泡、修水龙头）从每月预存的'维修基金'中扣除；中修（500-3000元，如家电维修、局部管道更换）需提前通知业主，业主确认后从维修基金或单独支付；大修（3000元以上，如空调更换、防水修缮）必须取得业主书面确认，费用由业主承担。保养管理方面，托管方会定期安排空调清洗、管道疏通、白蚁检查等预防性维护，费用从维修基金扣除。业主需在合同中明确：维修基金月存金额（通常100-300元）、审批门槛、紧急维修的先行处置权限（如漏水可先处理后报备），避免维修延误造成更大损失。","legalRef":"《民法典》第七百一十二条：出租人应当履行租赁物的维修义务，但是当事人另有约定的除外。","consumerBenefit":"专业高效的维修响应，避免小问题拖成大损失","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"shu","meetingPhase":[]},"alias":["维修调度","托管维修","房屋维修管理"],"dataRef":"及时维修可减少房屋资产贬值约15%-20%","caseRef":"某业主托管房屋水管微漏未及时处理，3个月后地板霉变，维修费从800元飙升至1.5万元"},{"id":"SRV-AST-016","name":"账务管理与报表服务","domain":"L3-持有阶段","subScene":"代运营服务","scene":"L3-持有阶段·代运营服务","cq":"托管期间我能看到收支明细吗？账务怎么管理？","ola":"托管方按月提供收支报表，业主可随时查看租金和费用明细。","cp":["每月生成收支明细报表","收入支出逐项列明","支持线上随时查看对账"],"detail":"账务管理与报表服务是托管方为业主提供的财务透明化工具，确保业主对托管期间的收支情况有清晰的了解。标准服务内容包括：一、月度收支报表，列明当月租金收入、托管费扣除、维修支出、物业水电代缴等全部收支明细，附银行流水凭证；二、季度汇总报告，汇总季度总收支、同比环比分析、空置期统计等；三、年度税务报告，汇总年度租金收入和可抵扣费用，辅助业主进行个税申报；四、线上查询系统，业主通过APP或小程序随时查看实时账务。账务管理的核心原则是'收支分离'——租金收入和托管方自有资金分开管理，避免资金混同。合规的托管方会为每套托管房屋建立独立账套，确保账务可追溯。业主应重点关注：报表是否按月按时提供、收支是否有对应凭证、维修支出是否有维修记录和照片佐证、是否存在未经确认的扣款。","legalRef":"《民法典》第九百二十七条：受托人处理委托事务取得的财产，应当交还给委托人。","consumerBenefit":"收支透明可追溯，随时掌握资产运营状况","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"shu","meetingPhase":[]},"alias":["托管账务管理","托管报表","租金报表"],"dataRef":"提供月度报表的托管方，业主投诉率降低60%","caseRef":"某业主发现托管方月度报表中连续3月有'维修费'扣款但无维修记录，追回不合理扣款3600元"},{"id":"SRV-AST-017","name":"租客纠纷处理","domain":"L3-持有阶段","subScene":"代运营服务","scene":"L3-持有阶段·代运营服务","cq":"托管期间租客和邻居吵架、扰民、违约，谁处理？","ola":"托管方负责调解租客纠纷，严重违约可启动法律程序处理。","cp":["日常纠纷由托管方调解","租客违约托管方依约处理","涉及法律程序需业主配合"],"detail":"租客纠纷处理是托管代运营中最考验专业能力的环节。常见纠纷类型包括：一、邻里纠纷——租客噪音扰民、占用公共空间、宠物纠纷等，托管方负责上门调解、发送整改通知、必要时启动违约条款；二、租客违约——拖欠租金、擅自转租、违规装修、擅自养宠等，托管方先发送催告通知，逾期不改则按合同约定处理（如解除合同、扣除押金）；三、合同纠纷——租赁条款理解分歧、续租条件争议等，托管方代表业主与租客协商；四、安全事故——租客人身伤害、火灾漏水等，托管方先行应急处置，同时通知业主和保险公司。处理原则：轻微纠纷托管方自行调解并事后告知业主；中等纠纷（涉及扣款、整改）需提前通知业主；重大纠纷（解除合同、法律诉讼）需业主参与决策。托管方应建立纠纷台账，记录处理过程和结果，作为后续证据留存。","legalRef":"《民法典》第七百二十二条：承租人无正当理由未支付或者迟延支付租金的，出租人可以请求承租人在合理期限内支付；《民法典》第七百一十六条：承租人未经出租人同意转租的，出租人可以解除合同。","consumerBenefit":"专业团队高效处理租客纠纷，避免业主直接冲突和法律风险","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"fa","meetingPhase":[]},"alias":["托管纠纷处理","租务纠纷","托管租客纠纷"],"dataRef":"约30%的租赁关系出现过不同程度的纠纷","caseRef":"某租客长期扰民，托管方3次调解无效后启动违约条款解除合同，全程业主未出面，避免邻里关系恶化"},{"id":"SRV-AST-019","name":"日常巡检服务","domain":"L3-持有阶段","subScene":"代运营服务","scene":"L3-持有阶段·代运营服务","cq":"托管期间有人定期检查房屋状况吗？","ola":"托管方每月或每季度安排巡检，及时发现和解决问题。","cp":["定期上门巡检房屋状况","检查设施设备和安全隐患","出具巡检报告通知业主"],"detail":"日常巡检服务是托管方主动维护房屋资产的重要手段，通过定期上门检查及时发现和解决问题，避免小隐患发展成大损失。标准巡检内容包括：一、设施检查——家电是否正常运转、水管是否渗漏、电路是否安全、门窗是否完好；二、环境检查——室内是否整洁、是否存在违规改造（如打孔、拆墙）、是否有安全隐患（如电线私拉、燃气管老化）；三、合规检查——租客是否存在转租分租、违规养宠、擅自装修等违约行为；四、保养提醒——空调滤网是否需要清洗、油烟机是否需要维护等。巡检频率通常为每月1次或每季度2次，高端托管服务可增加至每月2次。巡检流程：提前24小时通知租客→按标准清单逐项检查→拍照记录→出具巡检报告→发现问题按紧急程度分级处理→报告同步业主。巡检的法律依据是业主对房屋的所有权，但需注意提前通知租客，避免侵犯租客的居住安宁权。","legalRef":"《民法典》第七百一十四条：承租人应当妥善保管租赁物，因保管不善造成租赁物毁损、灭失的，应当承担赔偿责任。","consumerBenefit":"主动发现问题，避免小隐患变大损失，保护房屋资产价值","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"shu","meetingPhase":[]},"alias":["托管巡检","房屋巡检","定期巡检"],"dataRef":"定期巡检的托管房屋，维修费用比无巡检低30%","caseRef":"某托管方巡检发现租客违规使用电磁炉导致电路过载，及时整改避免了潜在火灾风险"},{"id":"SRV-AST-025","name":"空置风险识别与评估","domain":"L3-持有阶段","subScene":"空置期管理","scene":"L3-持有阶段·空置期管理","cq":"房屋空置有哪些风险？怎么评估空置风险？","ola":"空置风险含收入中断、资产贬值和安全隐患，需定量评估。","cp":["空置直接损失为月租金×空置月数","长期空置加速房屋老化贬值","空置房存在安全隐患和被盗风险"],"detail":"空置风险是业主持有出租资产面临的核心风险之一，包含三个层面：一、收入风险——空置期间租金收入归零，但物业费、供暖费、贷款利息等持有成本仍在发生，净损失等于月租金×空置月数+持有成本；二、资产贬值风险——长期空置的房屋缺乏日常维护和使用，设施老化加速（如管道生锈、电器受潮），市场价租金随之下调，研究显示空置超6个月的房屋再次出租时租金平均下降8%-15%；三、安全风险——空置房屋无人看管，存在漏水未发现、盗窃、火灾隐患等安全风险。空置风险评估方法：计算'空置损失率'=年度空置月数÷12×100%，行业平均空置率约8%-12%（即年空置1-1.5个月），超过15%即属高风险。影响空置率的因素包括：地段交通、装修状况、租金定价、季节周期、竞品数量等。业主应定期评估空置风险，根据评估结果调整招租策略或考虑托管。","legalRef":"《民法典》第五百八十四条：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失。","consumerBenefit":"量化空置风险，提前制定应对策略，减少空置损失","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"dao","meetingPhase":[]},"alias":["空置风险","空置风险评估","空置率风险"],"dataRef":"行业平均空置率8%-12%，超过15%为高风险","caseRef":"某业主因租金定价过高导致连续空置4个月，损失2.4万元，调价至市场价后2周出租"},{"id":"SRV-AST-028","name":"空置期保险方案","domain":"L3-持有阶段","subScene":"空置期管理","scene":"L3-持有阶段·空置期管理","cq":"空置期可以买保险吗？有哪些保险方案？","ola":"可投保房东综合险，覆盖空置期财产损失和第三方责任。","cp":["房东综合险覆盖财产损失","第三方责任险保障邻损赔偿","空置超30天需特别申报"],"detail":"空置期保险是业主转移空置风险的重要工具。常见的保险方案包括：一、房东综合保险——承保房屋及室内财产因火灾、爆炸、水管爆裂、暴风雨等造成的损失，年保费通常为房屋价值的0.1%-0.3%，保额从50万到500万不等；二、第三方责任险——承保因房屋原因造成第三方（如邻居）人身或财产损失的赔偿责任，如漏水淹了楼下邻居，年保费200-500元；三、租金损失险——承保因房屋受损（如火灾）导致无法出租期间的租金损失，通常按月租金的80%赔付，最长赔付6-12个月；四、租客损坏险——承保租客故意或过失造成的房屋损坏，通常与房东综合险合并承保。投保注意事项：一、大多数家财险条款规定'空置超过30天需申报'，未申报可能影响理赔；二、选择'空置房扩展条款'的产品，确保空置期间保障不中断；三、保险标的需与房产证一致，装修和家电需单独列明保额；四、出险后及时报案，保留现场证据。","legalRef":"《保险法》第十六条：订立保险合同，保险人就保险标的或者被保险人的有关情况提出询问的，投保人应当如实告知。","consumerBenefit":"用小额保费转移空置期大额损失风险，保障资产安全","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"qi","meetingPhase":[]},"alias":["空置保险","房屋空置险","空置期保险"],"dataRef":"房东综合险年保费约年租金的1%-3%","caseRef":"某业主空置房因楼上漏水导致地板损毁，房东综合险赔付维修费2.8万元，自付仅500元免赔额"},{"id":"SRV-AST-029","name":"季节性空置规律","domain":"L3-持有阶段","subScene":"空置期管理","scene":"L3-持有阶段·空置期管理","cq":"什么时候是出租旺季？什么时候容易空置？","ola":"2-4月和6-8月为旺季，11-1月为淡季，顺应周期定价。","cp":["春节后2-4月为第一旺季","毕业季6-8月为第二旺季","年底11-1月为出租淡季"],"detail":"房屋出租存在明显的季节性规律，掌握这些规律有助于业主合理安排招租时间和定价策略。全年出租周期可分为四个阶段：一、第一旺季（2-4月）——春节后返城务工潮和职场跳槽季叠加，租赁需求集中释放，是全年出租最容易的时段，租金议价空间大，业主可适当上调3%-5%；二、第二旺季（6-8月）——高校毕业季推动大规模租房需求，尤其是靠近地铁站、商圈和产业园区的房源供不应求，此时期租金可达全年峰值；三、过渡期（9-10月）——需求逐步回落，租金回归均值，属于'不太难租但也不太好租'的阶段；四、淡季（11-1月）——临近年末，租客倾向续租而非搬迁，新租需求锐减，空置风险最高，租金通常低于均值5%-10%。对业主的实操建议：租约到期尽量安排在旺季（2-4月或6-8月），避免在淡季退租；淡季空置可考虑短期降价或提供免租期吸引租客；长期策略可通过调整租期（如签18个月而非12个月）将退租时间调整至旺季。","legalRef":"《民法典》第五百零九条：当事人应当按照约定全面履行自己的义务。","consumerBenefit":"顺应季节规律安排招租，降低空置风险并优化租金收益","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"dao","meetingPhase":[]},"alias":["季节空置","租赁淡旺季","出租季节性"],"dataRef":"旺季出租周期平均7-10天，淡季平均25-40天","caseRef":"某业主将12月到期租约提前2个月续签到次年2月，避免淡季空置，年化收益提升5%"},{"id":"SRV-AST-031","name":"长期空置预警机制","domain":"L3-持有阶段","subScene":"空置期管理","scene":"L3-持有阶段·空置期管理","cq":"房子空了很久怎么办？有没有预警机制？","ola":"空置30天黄色预警，60天红色预警，启动应急招租。","cp":["空置30天触发黄色预警","空置60天触发红色预警","预警后启动应急招租方案"],"detail":"长期空置预警机制是托管方为防范长时间空置导致重大损失而建立的分级响应系统。标准预警等级和响应措施如下：一、绿色状态（空置0-15天）——正常招租期，按标准流程推广，每周向业主报告招租进展；二、黄色预警（空置15-30天）——触发原因可能是定价偏高或房源竞争力不足，响应措施包括：下调租金3%-5%、增加推广平台、优化房源照片和描述、安排专场带看；三、橙色预警（空置30-60天）——触发原因可能是市场环境变化或房源存在硬伤，响应措施包括：降价8%-10%、考虑短期出租或分租方案、评估是否需要翻新升级、每日向业主报告进展；四、红色预警（空置超60天）——属于严重空置，响应措施包括：大幅降价或提供免租期、考虑转换出租策略（长租转短租）、启动合同约定的'空置特别条款'、与业主协商是否调整托管方案。业主应积极配合预警响应，尤其是价格调整决策——空置每多1个月的损失通常远大于降价的损失。","legalRef":"《民法典》第九百二十二条：受托人应当按照委托人的指示处理委托事务。需要变更委托人指示的，应当经委托人同意。","consumerBenefit":"通过分级预警机制及时发现空置问题并采取应对措施，避免长期空置造成重大损失","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"qi","meetingPhase":[]},"alias":["空置预警","长期空置预警","空置超期预警"],"dataRef":"空置超60天的房屋年化收益率下降30%以上","caseRef":"某业主拒绝黄色预警的降价建议，坚持原价导致空置3个月，损失1.8万元，远超降价2个月的差额"},{"id":"SRV-AST-035","name":"托管合同必备条款","domain":"L3-持有阶段","subScene":"托管合同与风险","scene":"L3-持有阶段·托管合同与风险","cq":"签托管合同必须写哪些条款？哪些条款绝对不能少？","ola":"托管合同必须包含委托范围、费用标准、违约责任和资金监管条款。","cp":["明确委托范围和权限","列明费用标准和支付方式","约定违约责任和解除条件"],"detail":"托管合同是业主与托管方之间权利义务的核心法律文件，必备条款缺一不可。一、当事人信息——双方名称、地址、联系方式、法定代表人或负责人；二、委托标的——房屋坐落、面积、户型、装修状况，附《房屋状况确认书》和照片；三、委托范围——明确委托事项（招租、收租、维修、纠纷处理等），全权委托需概括列明'全部管理事项'；四、委托期限——起止日期、续约条件、提前解除条件；五、租金条款——基准租金、浮动区间、定价权限、租金调整机制；六、费用条款——托管费率及计算方式、维修基金标准、其他收费项目和标准、费用支付时间；七、资金条款——租金转付周期和方式、是否使用监管账户、逾期转付的违约责任；八、权利义务——业主权利（知情权、审批权、解约权）、托管方义务（勤勉义务、报告义务、保密义务）；九、违约责任——双方违约情形和违约金标准；十、争议解决——协商、调解、仲裁或诉讼。特别强调：资金监管条款和违约责任条款是最容易被省略但最重要的保护性条款。","legalRef":"《民法典》第九百一十九条：委托合同是委托人和受托人约定，由受托人处理委托人事务的合同。《民法典》第四百七十条：合同的内容由当事人约定。","consumerBenefit":"签订完备的托管合同，为托管关系提供法律保障","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"fa","meetingPhase":[]},"alias":["托管合同条款","托管合同内容","托管合同要点"],"dataRef":"约50%的托管纠纷因合同条款不完备导致维权困难","caseRef":"某业主签的托管合同无资金监管条款和违约金条款，托管方挪用租金后业主维权无据"},{"id":"SRV-AST-036","name":"托管期限与续约条款","domain":"L3-持有阶段","subScene":"托管合同与风险","scene":"L3-持有阶段·托管合同与风险","cq":"托管一般签几年？到期怎么续约？","ola":"托管期限通常1-5年，到期前30天确认续约，可重新协商条款。","cp":["首次托管建议1-2年试水","续约前评估托管服务质量","续约可重新协商费率和条款"],"detail":"托管期限的设定直接影响业主的灵活性和收益稳定性。行业常见的托管期限如下：一、短期托管（1年）——适合首次托管试水，便于评估托管方服务质量后决定是否继续，但托管方投入资源意愿较低；二、中期托管（2-3年）——最常见的选择，托管方有足够时间运营和回本，业主也有中期灵活性；三、长期托管（3-5年）——风险代理模式的典型期限，托管方需要通过长期运营对冲短期风险，业主享受更长期的价格稳定但灵活性降低。续约条款的核心内容：一、续约通知——到期前30-60天书面确认是否续约，逾期未通知视为自动续约或终止（取决于合同约定）；二、续约条件——费率是否调整、条款是否变更、基准租金是否重估；三、续约期限——续约1年还是按原期限续约；四、不续约的交接——按托管到期交接流程执行。业主建议：首次托管选择1-2年，满意后续约延长至3年，避免一次性签5年锁定期过长。","legalRef":"《民法典》第九百二十条：委托人可以特别委托受托人处理一项或者数项事务，也可以概括委托受托人处理一切事务。","consumerBenefit":"合理设定托管期限，兼顾服务深度和自身灵活性","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"fa","meetingPhase":[]},"alias":["托管期限","托管续约","托管合同期限"],"dataRef":"首次托管1年期业主满意度约75%，3年期约60%","caseRef":"某业主首次签约5年托管，1年后发现服务质量差但解约需支付高额违约金，陷入被动"},{"id":"SRV-AST-037","name":"违约责任与赔偿","domain":"L3-持有阶段","subScene":"托管合同与风险","scene":"L3-持有阶段·托管合同与风险","cq":"托管方违约了怎么办？我违约了又怎样？","ola":"违约方按合同约定支付违约金，造成额外损失的还需赔偿。","cp":["托管方违约需支付违约金","业主提前解约也需付违约金","违约金不足以弥补损失可追偿"],"detail":"违约责任是托管合同中约束双方行为、保障权益的关键条款。常见违约情形及责任如下：一、托管方违约——（1）逾期转付租金，按逾期金额×0.05%/天支付滞纳金；（2）挪用租金，除返还本金外支付违约金（通常为挪用金额的20%-50%）；（3）未尽维修义务导致损失扩大，承担扩大的损失；（4）擅自降低租金，补足差额并支付违约金；（5）未经同意签订不利于业主的租赁合同，承担全部损失。二、业主违约——（1）提前解除合同，支付违约金（通常为1-3个月托管费或1-2个月租金）；（2）隐瞒房屋重大缺陷，承担托管方和租客的损失；（3）未按时支付托管费，按逾期金额支付滞纳金。三、赔偿原则——违约金不足以弥补实际损失的，受损害方有权要求赔偿差额；违约金过分高于实际损失的（超过30%），违约方可请求法院调减。业主需注意：合同中应同时约定双方的违约责任，避免只约束业主而托管方违约无惩罚的不对等条款。","legalRef":"《民法典》第五百八十五条：当事人可以约定一方违约时应当根据违约情况向对方支付一定数额的违约金。《民法典》第五百八十四条：损失赔偿额应当相当于因违约所造成的损失。","consumerBenefit":"明确违约后果，通过合同约束保障双方权益","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"fa","meetingPhase":[]},"alias":["托管违约","托管违约责任","托管违约赔偿"],"dataRef":"违约金设定为月租金1-3倍最常见且被法院支持","caseRef":"某托管方逾期转付租金2个月，业主依合同收取滞纳金3600元，托管方未按时支付后业主解除合同"},{"id":"SRV-AST-038","name":"资金安全保障","domain":"L3-持有阶段","subScene":"托管合同与风险","scene":"L3-持有阶段·托管合同与风险","cq":"托管期间我的租金安全吗？怎么保证资金不被挪用？","ola":"通过银行监管账户和分账管理，确保租金直接到达业主账户。","cp":["使用银行监管账户流转租金","托管方自有资金与租金分离","按月对账确保资金可追溯"],"detail":"资金安全是托管服务中最核心的风险管控环节。近年来多起托管机构'跑路'事件均涉及租金挪用，因此资金保障机制至关重要。主流资金安全保障措施包括：一、银行监管账户——托管方在合作银行开立专项监管账户，租客租金直接进入监管账户，银行按合同约定自动划转至业主账户，托管方无法擅自提取，这是目前最有效的资金安全保障；二、分账管理——托管方的服务费收入和业主的租金收入分账管理，不同房源的租金独立记账，避免资金混同；三、按月对账——托管方每月提供银行流水和收支明细，业主核对确认，发现异常立即核查；四、保证金制度——托管方向业主缴纳履约保证金（通常为1-3个月租金），用于担保托管义务的履行；五、保险保障——部分托管机构投保'职业责任险'，承保因托管方过失导致的业主资金损失。业主选择托管方时，应将'是否使用银行监管账户'作为首要筛选条件，未设监管账户的机构风险显著增高。","legalRef":"《民法典》第九百二十七条：受托人处理委托事务取得的财产，应当交还给委托人。《住房租赁条例》第二十三条：住房租赁企业应当设立资金监管账户。","consumerBenefit":"通过多重保障机制确保租金安全，防止托管方挪用或侵占资金","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"fa","meetingPhase":[]},"alias":["托管资金安全","资金监管","托管资金保障"],"dataRef":"使用监管账户的托管方资金安全事件接近0%，未使用的高达15%","caseRef":"某长租公寓托管方未设监管账户，挪用200余位业主租金后跑路，涉案金额超2000万元"},{"id":"SRV-AST-040","name":"托管机构选择标准","domain":"L3-持有阶段","subScene":"托管合同与风险","scene":"L3-持有阶段·托管合同与风险","cq":"怎么选择靠谱的托管机构？有没有评估标准？","ola":"从资质、规模、口碑、资金监管五维度综合评估。","cp":["核实资质备案和经营年限","考察管理规模和行业口碑","确认资金监管和保障机制"],"detail":"托管机构的选择直接决定托管体验和资金安全，业主应从五个维度系统评估：一、资质维度——是否持有营业执照和住建部门备案、经营年限是否超3年、是否有行政处罚或司法诉讼记录（通过企查查/天眼查核实）；二、规模维度——管理房源数量（过少可能规模不足、过多可能服务稀释）、团队人数与房源比（1人管理不超过50套为合理）、覆盖区域是否集中；三、口碑维度——在线评价和业主口碑（可通过业主社群了解）、续约率（高续约率说明服务质量好）、投诉处理效率和态度；四、资金维度——是否使用银行监管账户、租金转付周期和方式、是否缴纳履约保证金、是否有职业责任保险；五、合同维度——合同条款是否完备对等、违约责任是否双向约定、解除条件是否合理、隐形收费是否披露。选择流程建议：初步筛选3-5家→实地考察2-3家→对比方案和合同→选择最优1家签约。特别提醒：不要仅看费率高低做选择，最低费率可能意味着最低服务质量或最高隐性风险。","legalRef":"《住房租赁条例》第十五条：住房租赁企业应当依法办理备案。","consumerBenefit":"通过系统化评估选出靠谱托管机构，降低托管风险并提升服务体验","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"qi","meetingPhase":[]},"alias":["托管机构选择","选择托管公司","如何选托管机构"],"dataRef":"成立3年以上的托管机构跑路率低于2%，不足1年的高达20%","caseRef":"某业主仅凭低费率选择托管机构，后发现机构成立仅8个月且无监管账户，2个月后机构跑路"},{"id":"SRV-AST-044","name":"托管资金监管账户","domain":"L3-持有阶段","subScene":"托管合同与风险","scene":"L3-持有阶段·托管合同与风险","cq":"托管资金监管账户是什么？怎么运作的？","ola":"银行托管租金专户，租金直接划转业主，不可挪用。","cp":["租客租金进入银行监管账户","银行按约定自动划转至业主","托管方无权擅自提取资金"],"detail":"托管资金监管账户是当前防范租金挪用风险最有效的制度设计，由银行作为独立第三方对租金资金进行监管。运作机制：一、开户——托管方在合作银行开立'住房租赁资金监管账户'，账户性质为专用账户，与托管方自有资金账户完全隔离；二、缴入——租客缴纳的租金直接进入监管账户（而非托管方公司账户），部分城市要求租客通过银行转账而非现金/个人微信支付，确保资金可追溯；三、划转——银行按托管合同约定的周期和规则，自动将租金（扣除托管费后）划转至业主指定账户，托管方无法干预划转过程；四、监督——银行对监管账户的资金进出进行监督，发现异常交易（如大额非正常提取）有权冻结并通知相关方。目前北京、上海、深圳、杭州等城市已强制要求住房租赁企业设立监管账户。业主确认方法：要求托管方提供监管账户开户证明、银行名称和账号，可致电银行核实账户性质。使用监管账户是选择托管方的'硬性门槛'。","legalRef":"《住房租赁条例》第二十三条：住房租赁企业应当设立资金监管账户，用于收取和支付租金。各地出台的住房租赁资金监管办法有更具体的规定。","consumerBenefit":"通过银行第三方监管确保租金安全，从根本上杜绝挪用风险","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"fa","meetingPhase":[]},"alias":["资金监管账户","托管监管账户","租金监管账户"],"dataRef":"已实施监管账户强制要求的城市，托管资金安全事件下降95%","caseRef":"某城市实施监管账户制度后，租客租金由银行直接划转业主，杜绝了托管方挪用现象，业主零损失"},{"id":"SRV-MOV-001","name":"搬家前物品盘点清单","domain":"L2-交易阶段","subScene":"搬家流程与准备","scene":"L2-交易阶段·搬家流程与准备","cq":"搬家前需要做哪些物品盘点和准备？","ola":"搬家前逐房逐物清点，拍照留档，列清单分优先级。","cp":["逐房间盘点拍照留档","按贵重/易碎/普通分类","清单与搬家公司签字确认"],"detail":"搬家前物品盘点是确保财产安全、减少纠纷的核心准备环节。盘点应在搬家前7-10天开始，按房间逐一进行：客厅、卧室、厨房、卫生间、阳台，每个房间从大到小清点。对贵重物品（首饰、证件、电子产品）单独列册并拍照，记录品牌、型号、序列号；对易碎品（瓷器、玻璃器皿、艺术品）标注易碎标记并预估价值；对大型家具家电记录尺寸和当前状态（有无划痕、损坏），拍照存证。盘点清单应一式三份，客户、搬家公司、物业各执一份，搬家当天逐件核对。建议使用表格工具制作清单，包含物品名称、数量、所在房间、包装方式、价值估算、备注等字段。盘点过程中可同步进行断舍离，将不需要的物品提前处理（捐赠、出售、丢弃），减少搬运量和费用。对于租客，盘点清单还可作为退房时房屋及物品状况的证明依据，避免房东恶意扣扣押金。盘点完成后，将贵重物品和重要证件单独携带，不放入搬家车辆。","legalRef":"《民法典》第八百三十二条：承运人对运输过程中货物的毁损、灭失承担赔偿责任。","consumerBenefit":"避免物品丢失或损坏时无从索赔，搬家后快速核对找回物品。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"shu","meetingPhase":[]},"alias":["搬家清点","搬前盘点","物品清单"],"dataRef":"搬家纠纷中约35%因物品丢失或损坏引发，其中未做搬前盘点的占比超60%。","caseRef":"某客户搬家后发现电视机屏幕碎裂，因搬前未拍照存证，搬家公司拒绝赔偿，最终仅获赔200元。"},{"id":"SRV-MOV-002","name":"搬家打包技巧与材料选择","domain":"L2-交易阶段","subScene":"搬家流程与准备","scene":"L2-交易阶段·搬家流程与准备","cq":"搬家时怎么打包才能保护物品不损坏？","ola":"按物品类型选材，重物小箱、轻物大箱，缝隙填实防震。","cp":["重物装小箱轻物装大箱","易碎品气泡膜包裹填缝","箱子封口H型胶带加固"],"detail":"搬家打包是保护物品安全的关键环节，合理的打包可以将运输损坏率降低70%以上。打包材料主要包括：瓦楞纸箱（5层和3层两种厚度）、气泡膜、珍珠棉、封箱胶带、记号笔、编织袋、缠绕膜等。打包原则是'重物小箱、轻物大箱'——书籍、厨房用具等重物用小号纸箱（约40×30×30cm），衣物、被褥等轻物可用大号纸箱或编织袋。易碎品打包需'三层防护'：先用气泡膜逐件包裹，再放入纸箱后用珍珠棉或旧报纸填充缝隙确保不晃动，箱体外标注'易碎-向上'标记。衣物可使用真空压缩袋节省空间，但皮革和羽绒制品不宜长时间压缩。电子产品（电脑、显示器）尽量使用原包装，无原包装则用气泡膜多层包裹并标注'勿压'。每个箱子打包完毕后，用记号笔在箱体外面写明：房间归属（如'主卧'）、内容物概要（如'冬季衣物'）、编号（如'3/20'表示第3箱共20箱）、易碎标记。封箱采用H型封箱法——先封中间一条，再封上下两条边，形成H字型，承重力更强。打包顺序应从非必需品开始（装饰品、换季衣物），必需品最后打包并单独标注'最先打开'。","legalRef":"《民法典》第八百三十二条：托运人应当按照约定的方式包装货物。","consumerBenefit":"大幅降低物品损坏率，搬家后拆箱整理更高效有序。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"shu","meetingPhase":[]},"alias":["打包方法","搬家包装","装箱技巧"],"dataRef":"规范打包可使搬家物品损坏率从15%降至3%以下。","caseRef":"某客户使用旧报纸填充瓷器缝隙，因填充不实导致运输中碰撞碎裂，搬家公司以包装不合格为由减轻赔偿责任。"},{"id":"SRV-MOV-003","name":"搬家物品分类与标记方法","domain":"L2-交易阶段","subScene":"搬家流程与准备","scene":"L2-交易阶段·搬家流程与准备","cq":"搬家时物品怎么分类和标记最方便？","ola":"按房间分类装箱，彩色标签区分，编号登记防遗漏。","cp":["按目的地房间分类装箱","彩色标签区分房间类别","箱体编号与总箱数对应"],"detail":"搬家物品分类与标记是提升搬家效率和减少混乱的核心方法。分类应遵循'按目的地房间归类'原则，而非按原房间归类——即物品按照新家中的摆放位置分类装箱，这样到新家后可以直接按箱体标记送到对应房间，无需二次分拣。具体分类方法：使用四种不同颜色的彩色标签贴纸，红色代表厨房用品、蓝色代表卧室衣物、绿色代表客厅物品、黄色代表卫生间用品。每个箱子外侧贴上对应颜色标签，并用记号笔写明：房间名称、内容物概要、箱号（如'厨房-锅碗-05/25'）。特殊标记包括：'易碎'用红色三角标、'勿压'用向上箭头标、'优先拆箱'用星号标、'随身携带'用圆圈标。建议制作一份总清单表格，记录每个箱号对应的房间、内容物、数量，搬家前后逐箱核对。对于搬家当天需要立即使用的物品（洗漱用品、换洗衣物、充电器、重要文件），单独装入一个'第一晚箱'并放在车辆最后装载的位置，确保最先卸下。家具拆解后的螺丝配件用密封袋装好并标注所属家具名称，用胶带贴在家具本体上。分类标记的最终目标是：任何一个箱子送到新家后，不需要打开就能知道该送到哪个房间。","legalRef":"《民法典》第八百二十七条：托运人应当按照约定的方式包装货物，并作出危险物品标志和标签。","consumerBenefit":"搬家后拆箱整理效率提升50%以上，避免物品找不到的焦虑。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"fa","meetingPhase":[]},"alias":["物品标记","搬家分类","装箱标记"],"dataRef":"采用分类标记系统的搬家案例中，拆箱整理时间平均缩短40%。","caseRef":"某客户搬家30箱未做分类标记，到新家后花3天才找到急需的电脑充电器，严重影响工作。"},{"id":"SRV-MOV-004","name":"贵重物品搬运处理指南","domain":"L2-交易阶段","subScene":"搬家流程与准备","scene":"L2-交易阶段·搬家流程与准备","cq":"搬家时贵重物品（珠宝、字画、古董）怎么处理？","ola":"贵重物品随身携带，购买专项保险，拍照留证登记价值。","cp":["珠宝证件现金务必随身携带","字画古董请专业搬运公司","高价值物品购买专项运输保险"],"detail":"贵重物品搬运是搬家过程中风险最高的环节，需要特殊处理策略。贵重物品可分为三类：第一类是可随身携带的贵重品（珠宝首饰、现金、证件、银行卡、笔记本电脑、移动硬盘），这类物品绝对不能放入搬家车辆，必须由本人随身携带，建议使用贴身腰包或手提箱；第二类是需要专业搬运的高价值物品（字画、古董、艺术品、钢琴、高档音响），这类物品不建议普通搬家公司搬运，应联系专业的艺术品运输公司或搬家公司的高端服务线，使用防震防潮的专业包装和恒温运输车辆；第三类是大型高价值家电（大屏电视、对开门冰箱、洗烘一体机），这类物品需原包装或专业包装，搬运时注意保持直立（冰箱搬运倾斜不超过45度），搬运后静置2-4小时再通电。所有贵重物品在搬家前应拍照存证并记录品牌、型号、购买价格、当前估值，建议购买搬家运输保险——普通搬家公司赔偿上限通常为每件500-2000元，远低于贵重物品实际价值。对于字画古董等无法替代的物品，建议请专业评估机构出具估值报告，并购买足额运输保险。搬家当天，贵重物品装车和卸车时本人必须在场监督。","legalRef":"《民法典》第八百三十三条：货物的毁损、灭失的赔偿额，当事人有约定的按照约定；没有约定或约定不明的，按照交付或者应当交付时货物到达地的市场价格计算。","consumerBenefit":"避免不可挽回的财产损失，保障高价值物品安全到家。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"qi","meetingPhase":[]},"alias":["贵重物品搬家","贵重物品运输","珠宝搬运"],"dataRef":"搬家贵重物品损失平均赔偿率不足实际价值的30%，主要因赔偿上限约定过低。","caseRef":"某客户搬家时将价值8万元的翡翠手镯放入搬家箱，到目的地后发现丢失，搬家公司按合同赔偿上限仅赔2000元。"},{"id":"SRV-MOV-006","name":"搬家时间规划与流程安排","domain":"L2-交易阶段","subScene":"搬家流程与准备","scene":"L2-交易阶段·搬家流程与准备","cq":"搬家应该怎么规划时间和流程？","ola":"提前两周规划，前7天打包，当天按装运卸查四步执行。","cp":["提前两周启动搬家准备工作","搬家前7天完成打包整理","搬家当天按装运卸查四步执行"],"detail":"搬家时间规划直接决定搬家过程的顺利程度，合理的规划可以将搬家压力降至最低。建议按照倒推法制定时间表：搬家前14天——确定搬家日期（避开月底月初搬家高峰期、周末高峰时段）、联系至少3家搬家公司比价、预约搬家日期和车辆、向物业申请搬家通行证和电梯使用；搬家前10天——开始整理物品，进行断舍离，处理不需要的物品（二手出售、捐赠、丢弃），购买打包材料；搬家前7天——开始正式打包，从非必需品开始（换季衣物、装饰品、书籍），每天打包2-3个房间；搬家前3天——打包日常用品，准备'第一晚箱'（洗漱用品、换洗衣物、充电器、重要文件），通知水电燃气宽带等服务机构变更地址或过户；搬家前1天——确认搬家公司到达时间，最后检查所有物品已打包，清空冰箱并除霜，拆卸大型家具，与物业确认搬家电梯时段，在新居张贴房间分布图供搬运工人参考；搬家当天——早上确认搬家公司车辆和人员到位，逐箱核对清单装车，贵重物品随身携带，到达新居后按房间标记卸货，全部卸完后逐箱清点核对，确认无误后签收付款；搬家后1-3天——拆包整理、检查水电燃气是否正常、更新地址信息、办理新居物业交接。","legalRef":"《民法典》第八百二十七条至八百三十六条关于运输合同履行的相关规定。","consumerBenefit":"系统化规划避免遗漏关键步骤，搬家当天从容不迫。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"shu","meetingPhase":[]},"alias":["搬家计划","搬家时间表","搬家流程安排"],"dataRef":"有规划搬家比临时搬家的物品丢失损坏率低80%，时间效率提升60%。","caseRef":"某客户未提前预约搬家公司，月底搬家当天临时找车，被收取高于正常价格2倍的费用，且服务态度差。"},{"id":"SRV-MOV-007","name":"大型家具家电搬运要点","domain":"L2-交易阶段","subScene":"搬家流程与准备","scene":"L2-交易阶段·搬家流程与准备","cq":"大型家具家电搬家时需要注意什么？","ola":"大件家具拆解搬运，家电保持直立，测量门电梯楼道尺寸。","cp":["搬运前测量门宽电梯楼道尺寸","冰箱洗衣机搬运倾斜不超45度","钢琴需专业搬运团队"],"detail":"大型家具家电是搬家过程中最容易损坏物品和房屋的环节，需要特别注意搬运方法。搬运前的关键准备：测量——用卷尺测量新居和旧居的门宽、走廊宽度、电梯轿厢尺寸、楼梯转角空间，确认大型家具能否通过；如无法通过需考虑窗户吊装或拆解搬运。冰箱搬运——搬运前24小时断电除霜清空内容物，搬运时倾斜角度不超过45度（防止压缩机润滑油倒流），搬运后静置2-4小时再通电，运输途中避免剧烈颠簸；洗衣机搬运——排水排净、固定内筒（用运输固定螺栓），搬运时不可倒置；空调搬运——建议由空调售后或专业人员拆卸和安装，自行拆卸可能导致制冷剂泄漏和保修失效；电视搬运——屏幕用气泡膜多层包裹，使用原包装箱，无原包装则竖立放置不可平放，运输中不可重压；钢琴搬运——必须委托专业钢琴搬运公司，需4-6人协同，用专用钢琴搬运带和防滑垫，楼梯搬运时琴键面朝墙壁，运输中固定不可晃动；衣柜/书柜搬运——可拆卸的尽量拆解，不可拆卸的需用缠绕膜固定柜门和抽屉防止运输中打开，转角处注意保护。所有大型家具家电在搬运前应拍照记录现状，搬运后检查有无新增损坏。搬运过程中注意保护墙面、地板、门框，必要时使用护角和地垫。","legalRef":"《民法典》第八百三十二条：承运人对运输过程中货物的毁损、灭失承担赔偿责任，但不可抗力、货物自然性质或托运人过错除外。","consumerBenefit":"避免大件物品搬运损坏和房屋刮伤，保障家电正常使用。","tags":{"clientType":["buyer","tenant"],"stage":"mid","layer":"shu","meetingPhase":[]},"alias":["家具搬运","家电搬运","大件搬运"],"dataRef":"大型家电搬运损坏占搬家赔偿纠纷的45%，其中冰箱和电视占比最高。","caseRef":"某客户搬家时冰箱倾斜超过90度搬运，到家后通电导致压缩机损坏，维修费用2800元，搬家公司以操作不当为由拒赔。"},{"id":"SRV-MOV-008","name":"搬家前断舍离与物品处理","domain":"L2-交易阶段","subScene":"搬家流程与准备","scene":"L2-交易阶段·搬家流程与准备","cq":"搬家前怎么处理不需要的物品？","ola":"搬家前分类清理，二手出售、捐赠、丢弃三步走。","cp":["按使用频率和情感价值分类","二手平台出售高价值闲置","捐赠或回收低价值物品"],"detail":"搬家前的断舍离是降低搬家成本、提升新居居住品质的重要环节。建议在搬家前10-14天开始进行物品筛选，按照'近一年未使用''未来半年不需要''已有替代品'三个标准进行初步筛选。物品处理分为四个渠道：第一，二手出售——高价值且品相良好的物品（家电、家具、品牌衣物、书籍）通过闲鱼、转转等二手平台出售，大型家具家电也可联系二手回收商上门估价收购，通常可在搬家前一周完成交易；第二，捐赠——衣物、被褥、书籍、儿童玩具等可通过公益组织（如旧衣回收箱、社区捐赠点、线上捐赠平台）进行捐赠，既环保又能帮助他人；第三，回收——电子产品、金属制品、纸箱等可联系废品回收站上门回收，部分家电以旧换新可抵扣购机款；第四，丢弃——无法使用且无回收价值的物品直接丢弃，注意垃圾分类和大件垃圾预约清运。断舍离的核心原则是'搬入新居的每件物品都应该是你需要的'，这不仅能减少搬家箱数和费用（每减少5箱约节省100-200元），还能让新居更加整洁有序。对于租客退租，断舍离也关系到退房清洁度，遗留大量杂物可能被房东扣留押金。","legalRef":"《固体废物污染环境防治法》关于生活垃圾和大件垃圾分类处理的规定。","consumerBenefit":"减少搬家费用和搬运量，新居更整洁，旧物变现回血。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"fa","meetingPhase":[]},"alias":["搬家断舍离","搬家前清理","旧物处理"],"dataRef":"搬家前断舍离平均可减少30%-40%的搬运量，节省搬家费用约200-500元。","caseRef":"某客户搬家前通过二手平台出售旧冰箱、旧沙发和50件衣物，回收金额超2000元，搬家箱数从35箱减至22箱。"},{"id":"SRV-MOV-012","name":"搬家报价陷阱与防范","domain":"L2-交易阶段","subScene":"搬家费用与选择","scene":"L2-交易阶段·搬家费用与选择","cq":"搬家有哪些常见的报价陷阱？怎么防范？","ola":"警惕低价吸引后加价，签书面合同写明全部费用项目。","cp":["低价吸引现场加价最常见","口头报价无约束力","合同注明含全部费用"],"detail":"搬家报价陷阱是消费者投诉最集中的问题，常见陷阱有以下几种。第一，低价吸引后加价——电话报价时给出极低价格（如'199元搬家'），到现场后以各种理由加价：物品多需加车、楼层高需加楼层费、大件需加搬运费，最终费用可能是报价的3-5倍。防范方法：要求上门估价或视频估价，获取书面报价单注明'一口价含全部费用'。第二，口头报价不认账——电话沟通的报价到现场不承认。防范方法：所有报价通过微信文字或书面确认，保留聊天记录。第三，隐形收费项目——装车费、卸车费、包装费、楼层费等名目繁多，事前不告知事后逐项加收。防范方法：要求搬家公司提供完整费用清单逐项确认。第四，按件计费陷阱——声称'按件收费每件10元'，但将一个衣柜拆成多个'件'计算。防范方法：明确'件'的定义，大件家具按整体一件计。第五，中途加价要挟——装车到一半或运输途中要求加价，不加钱就不继续搬运。防范方法：签订书面合同约定总价和违约责任，遇到要挟立即报警并拨打12315投诉。第六，计量做手脚——虚报车辆次数或搬运箱数。防范方法：自己记录装车箱数和车辆次数，与工人核对签字。","legalRef":"《消费者权益保护法》第五十五条：经营者提供商品或服务有欺诈行为的，应增加赔偿三倍费用。《价格法》关于明码标价的规定。","consumerBenefit":"识别并防范报价陷阱，避免搬家费用超出预算数倍。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"qi","meetingPhase":[]},"alias":["搬家陷阱","搬家加价","搬家隐形收费"],"dataRef":"搬家投诉中约65%涉及报价纠纷，其中'低价吸引后加价'占比超50%。","caseRef":"某客户获电话报价300元，搬家当天被加收楼层费240元、包装费180元、超距费120元、拆装费300元，实际支付1140元，为报价的3.8倍。"},{"id":"SRV-MOV-013","name":"搬家保险与理赔指南","domain":"L2-交易阶段","subScene":"搬家费用与选择","scene":"L2-交易阶段·搬家费用与选择","cq":"搬家需要买保险吗？怎么理赔？","ola":"建议购买搬家运输保险，保单覆盖物品实际价值，48小时内报案。","cp":["确认搬家公司基础赔偿上限","高价值物品购买专项保险","损坏后48小时内报案留证"],"detail":"搬家保险是转移搬家财产风险的重要工具，大多数消费者忽视了这一环节。搬家保险分为三个层次：第一层是搬家公司基础赔偿——正规搬家合同通常约定每件物品赔偿上限（如500-2000元/件），这是搬家公司自带的保障，但赔偿额度远低于贵重物品实际价值；第二层是搬家公司购买的责任保险——部分大型搬家公司为运输车辆购买了货物运输责任险，当承运物品发生损失时由保险公司赔付，但赔偿标准仍按合同约定执行；第三层是消费者自购运输保险——消费者可自行向保险公司购买'家庭财产运输险'或'个人货物运输险'，按物品实际价值投保，保费通常为保额的0.3%-1%，这是保障最全面的方案。购买保险时的注意事项：投保前对贵重物品拍照并保留购买凭证或估价报告，保单上注明承保物品清单和价值；确认保险覆盖范围（是否含搬运装卸过程）；了解免赔额和赔偿比例。理赔流程：发现物品损坏或丢失后，第一时间拍照留证并通知搬家公司和保险公司，在48小时内正式报案，填写理赔申请表并附上损失清单、照片、购买凭证、搬家合同等材料，配合保险公司查勘定损，通常15-30个工作日内获赔。无法提供购买凭证的物品，赔偿按市场评估价计算。","legalRef":"《民法典》第八百三十三条：货物的毁损、灭失的赔偿额，当事人有约定的按约定；无约定或约定不明的，按交付时货物到达地市场价格计算。《保险法》关于财产保险的规定。","consumerBenefit":"搬家物品损失获得足额赔偿，高价值物品风险得到保障。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"qi","meetingPhase":[]},"alias":["搬家保险","搬家理赔","运输保险"],"dataRef":"购买搬家运输保险的消费者中，理赔获赔率约82%，平均理赔金额约3500元；未购保险仅靠搬家公司赔偿的获赔率约45%，平均赔偿额约800元。","caseRef":"某客户搬家时价值1.2万元的电视损坏，因购买了保额2万元的运输保险，获赔1.2万元全额赔偿；另一客户未购保险，搬家公司按合同上限仅赔2000元。"},{"id":"SRV-MOV-022","name":"业主搬入新房流程","domain":"L2-交易阶段","subScene":"搬家纠纷与衔接","scene":"L2-交易阶段·搬家纠纷与衔接","cq":"买新房后搬入需要走哪些流程？","ola":"收房验房→办物业手续→开通水电燃气→搬家入户→更新地址信息。","cp":["先验房收房再安排搬家","办理物业交接和门禁手续","水电燃气网络开通后再搬入"],"detail":"业主搬入新房是一个涉及多个环节的流程，需要在购房交房后系统化推进。第一步，收房验房——开发商通知交房后，业主应先验房再签收：检查房屋结构和装修是否符合合同约定（墙面、地面、门窗、水电、厨卫设施），发现质量问题在收房单上注明并要求开发商限期整改。第二步，办理物业手续——签订前期物业服务协议、缴纳物业费（通常预缴半年或一年）、办理门禁卡和车位手续、确认物业搬家管理规定。第三步，开通水电燃气——水：到供水公司或物业办理开通，确认水表读数；电：确认电表读数；燃气：联系燃气公司预约开通（需入户检查燃气管道和设备，通常需预约3-7个工作日）；网络宽带：提前联系运营商预约安装。第四步，安排搬家——按照搬家流程选择搬家公司、预约时间、打包整理、执行搬家。第五步，搬家后手续——到社区居委会登记入住信息、办理户口迁移、更新驾照/银行卡/快递等地址信息、为孩子办理转学手续、购买家庭财产保险。新房搬入的特殊注意事项：新房装修后应充分通风（建议至少3个月），入住前可做甲醛检测确保达标；新房可能有收尾工程，建议在开荒保洁后再搬入家具；如购买的是精装房，搬入前同样需要逐项检查装修质量。","legalRef":"《民法典》第五百九十八条：出卖人应当按约交付标的物。《商品房买卖合同》关于房屋交付标准的约定。《物业管理条例》关于业主入住的规定。","consumerBenefit":"系统化完成新房搬入全流程，顺利入住无遗漏。","tags":{"clientType":["buyer"],"stage":"post","layer":"shu","meetingPhase":[]},"alias":["新房搬入","业主入住","新房搬家"],"dataRef":"新房交付后首次验房发现问题率约75%，其中墙面裂缝和门窗密封问题占比最高。","caseRef":"某业主未验房直接搬入，入住后发现卫生间防水不合格导致漏水至楼下，开发商以'已签收'为由拒绝免费维修，业主自费8000元重做防水。"},{"id":"SRV-MOV-026","name":"搬家后收尾与适应","domain":"L2-交易阶段","subScene":"搬家纠纷与衔接","scene":"L2-交易阶段·搬家纠纷与衔接","cq":"搬家后还需要做哪些收尾工作？","ola":"搬家后逐箱拆包归位、检查水电网络、更新地址、熟悉社区配套。","cp":["按优先级拆包整理先必需品","检查水电燃气网络是否正常","更新各类地址信息和证件"],"detail":"搬家后的收尾工作决定了新居生活的顺利过渡，建议在搬家后1-2周内逐步完成。第一优先级（搬家当天-第1天）：确认所有箱子和物品已到位无丢失损坏；检查水电燃气是否正常；检查网络宽带是否已安装到位；组装床铺和必需家具；打开'第一晚箱'取出洗漱用品和换洗衣物；检查门窗锁具是否正常。第二优先级（第2-3天）：按房间逐个拆包整理，优先整理厨房和卧室；检查所有家电是否正常运转（冰箱通电后等待2小时再放食物、空调测试制冷制热）；家具归位并固定（高大家具建议固定在墙上防倾倒）。第三优先级（第4-7天）：更新地址信息——银行账单、快递收货、医保社保、驾照地址变更（30天内办理）、孩子学校变更通知；办理社区入住登记和户籍迁移；熟悉社区配套——超市、医院、学校、公交地铁站点、快递驿站。第四优先级（第2周内）：完成全部拆包和物品归位；处理搬家纸箱和包装材料；做一次全面清洁或请保洁服务；检查有无遗漏的纠纷或赔偿问题；如从租房搬出，确认前房东已退还押金。新环境可能需要1-3个月适应期，保持积极心态，主动了解社区活动建立邻里关系。","legalRef":"《民法典》第二百零九条：不动产物权的设立、变更、转让和消灭，经依法登记发生效力。户口迁移和地址变更的相关行政法规。","consumerBenefit":"系统化完成搬家收尾，快速适应新居生活，不遗漏重要事项。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"fa","meetingPhase":[]},"alias":["搬家后整理","搬入适应","搬家收尾"],"dataRef":"搬家后平均需要7-10天完成全部拆包整理，约30%的人搬家后1个月内仍有未拆封的箱子。","caseRef":"某客户搬家后忘记更改驾驶证地址，被交警查到后处以警告并要求限期变更。"},{"id":"SRV-CLN-001","name":"日常保洁服务标准","domain":"L3-持有阶段","subScene":"保洁类型与标准","scene":"L3-持有阶段·保洁类型与标准","cq":"日常保洁都包含哪些服务内容？","ola":"日常保洁含全屋表面除尘、地面清洁、厨卫基础清理、垃圾倾倒。","cp":["全屋桌面台面除尘擦拭","地面扫拖清洁","厨房卫生间基础清理","垃圾收集倾倒"],"detail":"日常保洁是最基础的家居清洁服务，主要针对日常生活中产生的灰尘、污渍和杂乱进行维护性清洁，保持居住环境的基本整洁。服务内容通常包括：客厅区域——茶几电视柜桌面除尘、沙发整理、地面扫拖、踢脚线擦拭；卧室区域——床头柜衣柜表面除尘、床铺整理、地面清洁、窗台擦拭；厨房区域——灶台台面擦拭、水槽清洁、地面拖洗、油烟机表面擦拭（不含深度拆洗）；卫生间区域——洗手台马桶淋浴区清洁消毒、镜子擦拭、地面拖洗消毒；其他——门把手开关面板擦拭、垃圾收集倾倒、杂物归位整理。日常保洁不包含：高空作业（如天花板除尘、吊灯清洁）、深度去污（如瓷砖缝隙霉斑、顽固油垢）、家电内部清洁（如油烟机拆洗、空调清洗）、窗外玻璃清洁。日常保洁适合长期居住的房屋定期维护，建议频率为每周1-2次或每两周1次。服务时长根据房屋面积而定，60-90平米约2-3小时，90-120平米约3-4小时。选择日常保洁时应明确服务范围和标准，避免保洁人员'只做表面功夫'而忽略卫生死角。","legalRef":"《民法典》第七百七十条：承揽合同是承揽人按照定作人的要求完成工作，交付工作成果，定作人支付报酬的合同。","consumerBenefit":"维持居住环境基本整洁，减少日常家务负担，提升生活品质。","tags":{"clientType":["seller","tenant"],"stage":"all","layer":"shu","meetingPhase":[]},"alias":["日常保洁","日常清洁","普通保洁"],"dataRef":"2025年家政保洁服务市场中日常保洁占比约55%，平均单价约35-50元/小时。","caseRef":"某客户预约日常保洁，保洁员仅擦拭桌面和拖地，未清洁卫生间马桶和厨房灶台，客户投诉后保洁公司补做并退还50%费用。"},{"id":"SRV-CLN-002","name":"深度清洁服务内容","domain":"L3-持有阶段","subScene":"保洁类型与标准","scene":"L3-持有阶段·保洁类型与标准","cq":"深度清洁和日常保洁有什么区别？","ola":"深度清洁增加顽固污渍去除、死角清理和消毒杀菌。","cp":["含日常保洁全部内容","增加顽固污渍和死角清理","含厨卫深度去油除霉消毒"],"detail":"深度清洁是在日常保洁基础上的升级服务，针对长期积累的顽固污渍、卫生死角和细菌滋生区域进行彻底清洁，清洁深度和细致程度远超日常保洁。与日常保洁的核心区别：日常保洁是'表面维护'，深度清洁是'彻底清根'。深度清洁的额外内容包括：厨房深度——油烟机拆洗清洗（拆下叶轮浸泡去油）、灶台顽固油垢分解去除、橱柜内外擦拭、瓷砖缝隙油污清理、厨房五金件除水垢；卫生间深度——瓷砖缝隙霉斑清除、淋浴花洒水垢去除、马桶底部和背后死角清洁、地漏清理除味、浴室玻璃水痕去除、洁具除菌消毒；全屋细节——门窗轨道缝隙清理、开关插座面板清洁、踢脚线上沿除尘、灯具表面擦拭（不含拆卸）、墙角蛛网清除、家具底部和背后清洁、床垫除螨吸尘、窗帘轨道除尘。深度清洁使用专业清洁剂和工具（如蒸汽清洁机、除螨仪、管道疏通器），耗时较长，90平米房屋通常需要6-8小时（1-2人）。深度清洁适合以下场景：长期未做深度清洁的房屋、换季大扫除、家有婴幼儿或过敏体质者、宠物家庭、准备出售或出租的房屋。建议频率为每3-6个月一次。","legalRef":"《民法典》第七百七十条：承揽人应按定作人要求完成工作并交付工作成果。","consumerBenefit":"彻底清除日常保洁无法处理的顽固污渍和细菌，提升居住健康水平。","tags":{"clientType":["seller","tenant"],"stage":"all","layer":"shu","meetingPhase":[]},"alias":["深度保洁","深度清洁","精细保洁"],"dataRef":"深度清洁平均费用约日常保洁的2-3倍，客户满意度比日常保洁高约25%。","caseRef":"某客户家中有过敏体质儿童，定期做深度清洁后，室内尘螨检测值下降60%，儿童过敏症状明显改善。"},{"id":"SRV-CLN-004","name":"定期保洁维护方案","domain":"L3-持有阶段","subScene":"保洁类型与标准","scene":"L3-持有阶段·保洁类型与标准","cq":"定期保洁套餐值不值得买？怎么选？","ola":"定期保洁按周或月固定服务，比单次便宜20%-30%。","cp":["按周或月固定安排服务","套餐价比单次优惠20%-30%","固定保洁员熟悉房屋情况"],"detail":"定期保洁维护方案是家政公司提供的包月或包年保洁服务，通过固定频次、固定人员为客户提供持续的家居清洁维护。定期保洁的核心优势：价格优惠——套餐价格比单次预约优惠20%-30%，如单次日常保洁150元/次，包月4次约450-480元（折合112-120元/次）；固定人员——同一保洁员或团队定期服务，熟悉房屋布局、物品摆放和客户习惯，清洁效率和满意度更高；优先排期——套餐客户享有优先预约权，高峰期（如春节前）不被挤占；品质跟踪——家政公司对套餐客户有定期回访和品质跟踪，服务质量更有保障。定期保洁的套餐类型：每周1次（适合有婴幼儿或宠物的家庭、追求高品质生活环境者）、每两周1次（适合普通家庭，性价比最高）、每月1次（适合房屋面积大但日常维护较好、或长期在外出差者）、每周2次（适合大户型或高要求家庭）。选择建议：首次购买建议先试单次服务满意后再签约套餐；套餐期限建议先签1-3个月试运行，满意后续签；确认套餐包含的服务类型（日常还是深度）、单次服务时长、是否含清洁用品、取消和改期规则。注意：部分套餐要求预付全款，如中途取消可能产生违约金。","legalRef":"《民法典》第七百七十条至七百八十七条关于承揽合同的规定。《消费者权益保护法》关于预付式消费的规定。","consumerBenefit":"长期固定保洁省心省钱，家中持续保持整洁，无需反复预约。","tags":{"clientType":["seller","tenant"],"stage":"all","layer":"dao","meetingPhase":[]},"alias":["定期保洁","保洁套餐","包月保洁"],"dataRef":"定期保洁套餐客户续约率约65%，客户满意度比单次预约高约20%；预付式消费纠纷中家政类占比约12%。","caseRef":"某客户购买包年保洁套餐预付5400元，3个月后家政公司停业，剩余服务价值3600元无法追回。"},{"id":"SRV-CLN-008","name":"玻璃与外墙清洁服务","domain":"L3-持有阶段","subScene":"保洁类型与标准","scene":"L3-持有阶段·保洁类型与标准","cq":"高层住宅的外窗玻璃怎么清洁？安全吗？","ola":"高层外窗须专业高空人员操作，禁自行探身擦窗。","cp":["高层外窗须专业高空作业人员","室内玻璃可自行或请保洁","使用专用玻璃水和刮水器"],"detail":"玻璃和外墙清洁是保洁服务中安全要求最高的项目，高层住宅外窗玻璃清洁涉及高空作业，必须由持证专业人员操作。玻璃清洁的分类：室内玻璃——包括室内隔断玻璃、淋浴房玻璃、玻璃桌面、镜子等，可由保洁人员或自行使用玻璃清洁剂和刮水器清洁，难度较低。外窗玻璃——包括窗户外侧玻璃、阳台玻璃外侧、落地窗外侧等，低楼层（1-3层）可从室外或阳台伸手清洁，中高楼层（4层以上）需专业高空作业。高层外窗清洁的安全要求：作业人员必须持有高空作业操作证，使用专业安全装备（安全带、安全绳、吊板/吊篮），作业前检查安全绳固定点和承重能力，风力5级以上或雨雪天气禁止作业，至少两人配合（一人作业一人地面监护）。玻璃清洁的正确方法：先用清水冲洗玻璃表面去除浮尘，喷洒专用玻璃清洁剂，用玻璃刮从上至下刮除（每刮一次用抹布擦干刮条），顽固污渍（如鸟粪、胶渍）用专用铲刀轻轻刮除，最后用干抹布擦拭窗框和窗台。外墙清洗——适用于别墅外墙、底层住宅外墙、商业建筑外墙，根据外墙材质选择清洁方式（瓷砖外墙用高压水枪冲洗、涂料外墙用软毛刷轻刷、玻璃幕墙用专用清洁剂）。建议频率：室内玻璃每月一次，外窗玻璃每季度至半年一次。","legalRef":"《安全生产法》关于高处作业的安全管理规定：高处作业人员必须持证上岗，佩戴安全防护装备。《民法典》第一千一百九十二条：承揽人在完成工作中造成第三人损害或自己损害的，定作人不承担赔偿责任。","consumerBenefit":"安全清洁高层外窗玻璃，改善采光和视野，避免自行擦窗的坠落风险。","tags":{"clientType":["seller","tenant"],"stage":"all","layer":"qi","meetingPhase":[]},"alias":["玻璃清洁","外墙清洗","窗户保洁"],"dataRef":"家庭擦窗坠落事故中，自行探身擦外窗占比超80%；专业高空清洁事故率低于0.1%。","caseRef":"某住户自行探身擦5楼外窗玻璃不慎坠落受重伤，因未使用安全装备且非专业作业，医疗费用自担。"},{"id":"SRV-CLN-012","name":"自助保洁与专业保洁对比","domain":"L3-持有阶段","subScene":"保洁费用与选择","scene":"L3-持有阶段·保洁费用与选择","cq":"自己打扫和请保洁公司哪个更划算？","ola":"日常简单清洁可自助，深度清洁和专业项目建议请专业人员。","cp":["日常表面清洁可自行处理","深度清洁需专业设备和药剂","高空和家电清洗必须请专业"],"detail":"自助保洁与专业保洁各有适用场景，合理搭配可以在控制成本的同时保证清洁效果。自助保洁的优势：零人工成本（仅消耗清洁用品费用）、时间灵活随时可做、了解自家情况清洁更有针对性、隐私安全无外人进入。自助保洁的局限：缺乏专业设备（如蒸汽机、除螨仪、高压水枪）、缺乏专业药剂（如除霉剂、水泥克星）、清洁技巧经验不足（可能用错方法损坏物品）、体力时间消耗大（全屋深度清洁自做需1-2天）、部分项目无法自行完成（高空外窗、油烟机拆洗、空调管道清洗）。专业保洁的优势：专业设备和药剂清洁效果更好、经验丰富能处理顽固污渍、效率高节省时间、有保险保障。专业保洁的局限：需要费用支出、需预约等待、陌生人进入家庭有安全顾虑。建议搭配方案：日常保洁（每周1-2次）自行完成控制成本；深度清洁（每3-6个月1次）请专业公司；专项清洁（油烟机拆洗、空调清洗、外窗清洁、床垫除螨等）必须请专业人员。清洁用品年度花费约300-800元，专业保洁年度约2000-5000元，合理搭配比全请专业节省约40%-60%。","legalRef":"《民法典》第七百七十条：承揽合同相关规定。","consumerBenefit":"合理搭配自助和专业保洁，既控制成本又保证清洁效果。","tags":{"clientType":["seller","tenant"],"stage":"all","layer":"dao","meetingPhase":[]},"alias":["自己保洁vs请人","自助清洁","家庭自洁"],"dataRef":"家庭年度清洁总支出：全自助约500元、全专业约4000元、合理搭配约1500-2500元。","caseRef":"某客户自行用钢丝球擦洗不锈钢灶台导致表面划伤不可修复，专业维修费用800元，得不偿失。"},{"id":"SRV-CLN-014","name":"保洁人员资质与培训","domain":"L3-持有阶段","subScene":"保洁费用与选择","scene":"L3-持有阶段·保洁费用与选择","cq":"保洁人员需要什么资质？怎么判断专业性？","ola":"正规保洁员应持健康证、经岗前培训、有身份背景调查和保险。","cp":["持有效健康证每年体检","经岗前培训和安全教育","有身份背景调查和保险"],"detail":"保洁人员的专业素质直接关系到清洁服务质量、家庭财产安全和隐私保护，了解资质要求有助于筛选靠谱的保洁服务。正规保洁人员应具备的资质：第一，健康证明——持有效期内的健康证（通常每年体检更新），无传染性疾病，对有婴幼儿、老人的家庭至关重要。第二，身份认证——保洁公司应进行身份核实和背景调查（无犯罪记录证明），平台预约应通过实名认证。第三，岗前培训——内容包括清洁标准和流程、清洁剂正确使用方法、各类材质清洁注意事项、安全操作规范、服务礼仪。部分公司有等级认证（初级、中级、高级），高级保洁员能处理更复杂任务。第四，保险保障——正规公司应为保洁员购买意外伤害保险和第三者责任险，这是转移风险的关键。判断保洁人员专业性的方法：观察着装是否统一整洁、是否携带专业清洁工具、是否按标准流程操作（先上后下、先里后外）、是否能识别不同材质并使用对应清洁剂、是否主动避让贵重物品。客户有权要求保洁公司提供保洁员的健康证和保险证明，拒绝提供的一律不录用。","legalRef":"《家政服务业管理暂行办法》第十二条：家政服务机构应当对家政服务员进行身份核实和岗前培训。《传染病防治法》关于从业人员健康管理的规定。","consumerBenefit":"筛选专业保洁人员保障清洁质量、家庭安全和隐私。","tags":{"clientType":["seller","tenant"],"stage":"pre","layer":"fa","meetingPhase":[]},"alias":["保洁员资质","保洁员培训","保洁人员要求"],"dataRef":"正规保洁公司保洁员持证上岗率约80%，个人保洁员持证率不足15%。","caseRef":"某客户通过平台预约保洁，保洁员使用漂白剂清洁彩色大理石台面导致褪色，因保洁员未接受材质识别培训，平台赔偿1200元。"},{"id":"SRV-CLN-015","name":"保洁工具与清洁剂标准","domain":"L3-持有阶段","subScene":"保洁费用与选择","scene":"L3-持有阶段·保洁费用与选择","cq":"保洁服务应该用什么工具和清洁剂？安全吗？","ola":"专业保洁用分区色标工具、环保清洁剂，客户可要求查看产品成分。","cp":["工具按区域分色使用防交叉","使用环保无毒清洁剂","特殊材质用专用清洁产品"],"detail":"保洁工具和清洁剂的专业程度直接影响清洁效果和家庭健康安全。专业保洁工具标准：分区色标管理——正规保洁使用不同颜色抹布区分区域，红色用于卫生间、黄色用于厨房、蓝色用于客厅卧室、绿色用于玻璃镜面，防止交叉污染。工具配备应包含超细纤维抹布（多色多块）、玻璃刮水器、缝隙刷、百洁布、拖把、扫帚簸箕、喷壶、铲刀、梯子、垃圾袋。清洁剂标准：应使用符合国家标准的清洁产品，无毒或低毒、可生物降解、无强刺激性气味；避免使用含强酸强碱、挥发性有机物超标的劣质产品。分类使用——厨房用除油剂（弱碱性）、卫生间用除垢除霉剂（弱酸性或含氯消毒剂）、玻璃用专用玻璃水、地面用中性清洁剂、不锈钢用专用护理剂、木质表面用中性清洁剂。客户有权要求保洁公司提供清洁剂产品信息（品牌、成分、安全认证），有婴幼儿或过敏体质家庭应要求使用婴幼儿安全级别清洁剂。注意事项：84消毒液不可与洁厕灵混用（产生有毒氯气）、酸性清洁剂不可用于大理石和金属表面、漂白剂不可用于彩色织物和有色表面。","legalRef":"《产品质量法》关于销售和使用合格产品的规定。《危险化学品安全管理条例》关于清洁剂安全使用的规定。","consumerBenefit":"确保使用安全环保的清洁产品，保护家人健康和物品表面。","tags":{"clientType":["seller","tenant"],"stage":"mid","layer":"qi","meetingPhase":[]},"alias":["保洁工具","清洁剂标准","清洁用品"],"dataRef":"劣质清洁剂导致的物品损坏和健康问题投诉占保洁类投诉的约15%；专业分区色标管理可使交叉污染率降低80%。","caseRef":"某保洁员将84消毒液与洁厕灵混合使用产生有毒氯气，导致家中老人呼吸道刺激送医，保洁公司赔偿医疗费3000元。"},{"id":"SRV-CLN-020","name":"退租保洁标准界定","domain":"L3-持有阶段","subScene":"保洁纠纷与权益","scene":"L3-持有阶段·保洁纠纷与权益","cq":"退租时保洁做到什么程度才算合格？","ola":"退租保洁应恢复至搬入时清洁度，全屋无污渍无垃圾无遗留物品。","cp":["恢复至搬入时清洁程度","全屋无污渍垃圾遗留物","厨卫深度清洁达标"],"detail":"退租保洁标准是租客与房东之间最容易产生争议的问题之一，明确标准有助于减少押金纠纷。退租保洁的基本原则：租客应将房屋恢复至搬入时的清洁程度，正常使用产生的轻微磨损除外。具体标准：全屋——地面清洁无污渍无垃圾、墙面无新增污渍和钉孔（已有钉孔需填补）、踢脚线无灰尘、门窗清洁开关正常、所有个人物品和垃圾全部清运；厨房——台面灶台清洁无油渍、水槽无水垢无堵塞、橱柜内外清洁无杂物、油烟机表面无油滴、地面清洁；卫生间——马桶内外清洁无黄渍无异味、洗手台无水垢、淋浴区无皂垢、镜子无水痕、地漏通畅无异味；卧室客厅——家具表面无灰尘、地板/地毯清洁无污渍、窗户玻璃清洁（室内面）、窗帘如属租客安装的需清洗或拆除。退租保洁与日常保洁的区别：退租保洁要求更全面彻底，包括日常保洁不常做的项目（橱柜内部、冰箱内部、灯具表面、阳台角落等），接近深度清洁标准。争议处理：如合同约定了退租保洁标准或费用承担方式，按合同执行；如无约定，按'恢复原状'原则，以搬入时房屋清洁状况照片为基准对比。如果房东认为保洁不合格，应明确指出具体不达标区域并拍照，要求租客补做或从押金中扣除合理的清洁费用（需提供保洁报价或收据作为扣款依据）。","legalRef":"《民法典》第七百三十三条：租赁期间届满，承租人应当返还租赁物，返还的租赁物应当符合约定或根据租赁物的性质使用后的状态。第七百一十四条：承租人应当妥善保管租赁物。","consumerBenefit":"明确退租保洁标准，避免因清洁问题被房东过度扣减押金。","tags":{"clientType":["tenant","seller"],"stage":"post","layer":"fa","meetingPhase":[]},"alias":["退租保洁","退房清洁","退租清洁标准"],"dataRef":"退租押金纠纷中约35%涉及保洁标准争议，平均争议金额约800-1500元；有搬入时清洁状况照片的纠纷解决率提高60%。","caseRef":"某租客退租时做了日常保洁，房东认为不够彻底要求深度清洁并扣1500元押金，因合同未约定保洁标准且搬入时无照片记录，经调解扣除500元清洁费。"},{"id":"SRV-CLN-021","name":"保洁纠纷处理流程","domain":"L3-持有阶段","subScene":"保洁纠纷与权益","scene":"L3-持有阶段·保洁纠纷与权益","cq":"保洁服务发生纠纷怎么处理？","ola":"保洁纠纷先协商，再投诉消协或平台，最后可起诉维权。","cp":["先与保洁公司协商解决","协商不成向12315投诉","严重纠纷可向法院起诉"],"detail":"保洁服务纠纷包括清洁不到位、物品损坏、费用争议、人员行为问题等多种类型，掌握正确的处理流程有助于高效维权。纠纷处理的三步流程：第一步，协商解决——发现问题后第一时间联系保洁公司客服或负责人，说明问题并提供照片/视频证据，提出合理诉求（返工、补做、退款或赔偿），给予24-48小时响应时间；大部分纠纷可在协商阶段解决。第二步，投诉调解——协商不成时向以下渠道投诉：12315消费者投诉热线（电话或线上投诉，需提供公司名称、服务日期、问题描述和诉求）、平台投诉（通过预约平台提交投诉，平台有客服介入调解和保障机制）、家政行业协会投诉（针对会员企业）、消费者协会申请调解。投诉时需提供：服务合同或预约记录、付款凭证、问题照片或视频、与保洁公司的沟通记录、具体诉求和金额。第三步，法律途径——纠纷金额较大（3000元以上）或调解无果的，可向法院起诉：准备起诉状和证据材料，向被告所在地或服务履行地基层法院提起诉讼；金额较小的可申请小额诉讼程序。各类纠纷处理重点：清洁不到位要求返工或退款；物品损坏要求按实际价值赔偿；费用争议要求退还多收费用；人员行为问题（偷窃、损坏故意隐瞒）报警处理。","legalRef":"《消费者权益保护法》第三十九条：消费者和经营者发生消费者权益争议的，可通过协商、调解、投诉、仲裁、诉讼等途径解决。《民法典》第七百八十一条：承揽人交付的工作成果不符合质量要求的，定作人可以请求修理、重作、减少报酬、赔偿损失。","consumerBenefit":"掌握纠纷处理流程高效维权，避免投诉无门或维权不当。","tags":{"clientType":["seller","tenant"],"stage":"post","layer":"fa","meetingPhase":[]},"alias":["保洁纠纷","保洁投诉","保洁争议"],"dataRef":"保洁纠纷中约60%通过协商解决，25%通过投诉调解解决，15%通过诉讼解决；投诉到12315的案件中调解成功率约70%。","caseRef":"某客户保洁后价值2000元的摆件被损坏，保洁公司只愿赔500元，客户通过12315投诉后调解获赔1800元。"},{"id":"SRV-CLN-022","name":"保洁服务投诉渠道","domain":"L3-持有阶段","subScene":"保洁纠纷与权益","scene":"L3-持有阶段·保洁纠纷与权益","cq":"保洁服务不好可以到哪里投诉？","ola":"可向12315、平台、家政协会或消协投诉，严重可报警。","cp":["12315消费者投诉热线","预约平台客服投诉","家政行业协会或消协调解"],"detail":"保洁服务不满或权益受损时，消费者有多种投诉渠道。第一，保洁公司内部投诉——直接联系客服或负责人投诉，是最快捷的渠道，适合清洁不到位、服务态度差等一般性问题，通常24-48小时内响应。第二，预约平台投诉——通过天鹅到家、58到家、美团等平台预约的保洁，可在APP内提交投诉，平台客服介入调查协调，通常有保障机制（不满意退款、先行赔付等），处理时效约3-7个工作日。第三，12315消费者投诉——拨打12315热线或通过全国12315平台在线投诉，适合保洁公司拒绝解决、退款纠纷、费用欺诈等，需提供公司名称、服务日期、问题描述、诉求和金额，处理时效约7-15个工作日，市场监管部门介入调解。第四，消费者协会——向所在地消协投诉申请调解，作为第三方调解机构具有公信力。第五，家政行业协会——如保洁公司是会员可向协会投诉，协会有权监督和处分会员。第六，报警——涉及偷窃、故意损坏、人身威胁等违法行为时立即报警。第七，法院起诉——纠纷金额较大或调解无果时向法院起诉，小额纠纷可走小额诉讼程序。投诉时需准备：服务合同或预约截图、付款凭证、问题照片或视频、沟通记录、损失清单和价值证明。","legalRef":"《消费者权益保护法》第三十九条：消费者权益争议可通过协商和解、消费者协会调解、向行政部门投诉、提请仲裁或向法院起诉等途径解决。第四十六条：消费者向有关行政部门投诉的，该部门应当自收到投诉之日起七个工作日内予以处理并告知消费者。","consumerBenefit":"了解多种投诉渠道选择最有效的维权方式，提高纠纷解决效率。","tags":{"clientType":["seller","tenant"],"stage":"post","layer":"fa","meetingPhase":[]},"alias":["保洁投诉","投诉保洁公司","保洁维权渠道"],"dataRef":"12315保洁类投诉平均处理周期约10个工作日，调解成功率约70%；平台投诉处理周期约5个工作日，成功率约75%。","caseRef":"某客户通过平台预约保洁被多收费200元，平台投诉后3天内获得全额退款并获50元补偿券。"},{"id":"SRV-CLN-023","name":"保洁安全隐患防范","domain":"L3-持有阶段","subScene":"保洁纠纷与权益","scene":"L3-持有阶段·保洁纠纷与权益","cq":"保洁服务有哪些安全隐患？怎么防范？","ola":"含化学品误用、高空作业、触电和物品损坏等隐患。","cp":["清洁剂混用可产生毒气","高空作业须持证专业人员","保洁员受伤客户可能担责"],"detail":"保洁服务中存在多种安全隐患，既可能危害保洁员人身安全，也可能造成客户财产损失。主要安全隐患及防范措施：第一，化学品安全——清洁剂混用是最常见的隐患，84消毒液与洁厕灵混合会产生剧毒氯气、漂白剂与含氨清洁剂混合会产生有毒气体。防范：清洁剂分类使用不混用、使用时保持通风、佩戴手套口罩、有婴幼儿家庭使用无毒环保产品。第二，高空作业安全——擦外窗玻璃、清洁吊灯等高空作业存在坠落风险。防范：高层外窗必须由持证高空作业人员操作、客户不自行探身擦窗、作业时楼下设置警示区域。第三，用电安全——保洁中接触水和电器存在触电风险。防范：清洁前关闭相关区域电源、不直接用水冲洗带电设备、保持手部干燥操作开关。第四，滑倒摔伤——湿滑地面是跌倒主要风险。防范：拖地后放置防滑警示牌、及时擦干水渍、保洁员穿防滑鞋。第五，保洁员受伤的法律风险——雇佣个人保洁员（非公司员工），保洁员在客户家中受伤时客户可能承担雇主赔偿责任。防范：选择有工伤保险的保洁公司而非个人、不指挥保洁员进行危险操作。第六，财产安全——保洁员进入家庭存在偷窃风险。防范：选择有背景调查的保洁公司、贵重物品提前收好、安装监控（提前告知保洁员）。","legalRef":"《民法典》第一千一百九十二条：个人之间形成劳务关系，提供劳务一方因劳务造成他人损害的，由接受劳务一方承担侵权责任；提供劳务一方自己受到损害的，根据双方各自过错承担相应责任。《安全生产法》关于高处作业安全的规定。","consumerBenefit":"防范保洁安全隐患，保护家人健康和财产安全，避免法律责任。","tags":{"clientType":["seller","tenant"],"stage":"mid","layer":"qi","meetingPhase":[]},"alias":["保洁安全","保洁隐患","清洁安全"],"dataRef":"保洁安全事故中化学品混用中毒占比约30%、滑倒摔伤约35%、高空坠落约15%、触电约10%。","caseRef":"某客户雇佣个人保洁员擦外窗，保洁员不慎从3楼坠落受伤，法院判决客户作为雇主承担70%赔偿责任，赔偿12万元。"},{"id":"SRV-CLN-025","name":"保洁服务退款与维权","domain":"L3-持有阶段","subScene":"保洁纠纷与权益","scene":"L3-持有阶段·保洁纠纷与权益","cq":"保洁服务不满意可以退款吗？预付的套餐怎么退？","ola":"单次不满意可要求退款或返工，预付套餐未使用部分应可退。","cp":["单次服务不合格可要求退款","预付套餐未使用部分可退","退款被拒可向12315投诉"],"detail":"保洁服务退款涉及单次服务退款和预付套餐退款两种情况，消费者应了解退款权利和维权途径。单次服务退款：服务前取消——应在约定服务时间前通知（通常提前4-24小时），一般可全额退款；临近取消可能扣除少量违约金（不超服务费20%）。服务中退款——发现服务严重不达标或保洁员行为不当，可中止服务并要求退款；已部分完成的按比例退款。服务后退款——发现严重质量问题（如大面积未清洁、物品损坏），可要求全额或部分退款，需提供照片或视频证据。预付套餐退款的法律依据：《消费者权益保护法》第五十三条规定，经营者以预收款方式提供服务的，未按照约定提供的，应当按照消费者的要求履行约定或退回预付款。预付套餐退款处理：未使用部分应全额退还（可扣除已享受的优惠差额）；已使用部分按单次原价计算扣除后退还余额；商家设置'一律不退''过期作废'等格式条款属于无效条款。退款被拒的处理：第一步与保洁公司协商并提供退款依据；第二步向12315投诉或通过平台申请退款；第三步向消费者协会申请调解；第四步向法院起诉。注意事项：保留付款凭证和套餐合同、记录已使用次数和日期、退款要求以书面形式提出并保留记录。","legalRef":"《消费者权益保护法》第五十三条：经营者以预收款方式提供商品或服务的，应当按照约定提供。未按照约定提供的，应当按照消费者的要求履行约定或者退回预付款。《民法典》第五百六十三条：当事人一方迟延履行债务或者有其他违约行为致使不能实现合同目的的，当事人可以解除合同。","consumerBenefit":"了解退款权利和流程，预付费用不被套牢，不满意服务能退回费用。","tags":{"clientType":["seller","tenant"],"stage":"post","layer":"fa","meetingPhase":[]},"alias":["保洁退款","保洁退费","预付保洁退款"],"dataRef":"保洁预付套餐退款纠纷中，消费者通过投诉维权成功退款率约68%；'过期作废''一律不退'等格式条款被认定无效的比例约85%。","caseRef":"某客户购买季度保洁套餐预付1800元（含6次），使用2次后对服务质量不满要求退款，保洁公司以'套餐不退'为由拒绝，经12315投诉后退还未使用4次费用1200元。"},{"id":"SRV-AST-009","name":"托管期间租金定价策略","domain":"L3-持有阶段","subScene":"委托管理模式","scene":"L3-持有阶段·委托管理模式","cq":"托管期间租金由谁定价？定多少合适？","ola":"租金由双方约定基准价，托管方在授权范围内可灵活调价。","cp":["合同约定基准租金和浮动范围","托管方在区间内可灵活调价","调价需符合市场行情变化"],"detail":"托管期间的租金定价是业主与托管方博弈的核心议题。通常做法是：在托管合同中约定'基准租金'（即正常出租的参考月租金）和'浮动区间'（如基准价的±10%），托管方在该区间内有权根据市场行情调整租金，无需逐次征得业主同意。定价策略上，托管方通常采用'动态定价'——旺季（毕业季、春节后）适度上调，淡季适度下调以缩短空置期。业主在约定基准租金时，应参考同小区同户型的近期成交租金，而非挂牌价，避免基准价虚高导致空置期延长。部分合同约定'保底租金+超额分成'的定价机制，此时基准租金的确定更加关键。建议业主在合同中增加'租金调整通知条款'——托管方调整租金超过一定幅度时需提前通知业主，保障业主的知情权。对于高端房源，可约定'租金下限保护'，确保租金不低于设定底线。","legalRef":"《民法典》第九百二十二条：受托人应当按照委托人的指示处理委托事务。","consumerBenefit":"确保租金定价合理，兼顾出租速度与收益水平","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"shu","meetingPhase":[]},"alias":["托管租金定价","托管定价","托管租金策略"],"dataRef":"动态定价策略可缩短空置期20%-30%","caseRef":"某业主坚持高于市场15%的基准租金，导致空置3个月，损失1.8万元，后下调至市场价2周内出租"},{"id":"SRV-AST-011","name":"托管到期交接流程","domain":"L3-持有阶段","subScene":"委托管理模式","scene":"L3-持有阶段·委托管理模式","cq":"托管到期后怎么交接？要注意什么？","ola":"到期后双方验房确认、结算费用、退还保证金，签署交接确认书。","cp":["双方到场验房确认房屋状况","结算托管期间费用和维修基金","退还保证金签署交接确认书"],"detail":"托管到期交接是托管关系终结时的关键环节，涉及房屋实物交接、费用结算和责任认定三个方面。标准交接流程包括：一、提前通知，合同到期前30天双方确认是否续约；二、预约验房，双方到场对房屋状况进行逐项检查，对照托管开始时的《房屋状况确认书》比对，记录正常损耗和异常损坏；三、费用结算，包括未付租金、维修基金余额、水电物业欠费、托管费尾款等，双方确认结算金额；四、保证金退还，若托管时收取了房屋保证金，扣除合理扣款后退还业主；五、签署《托管交接确认书》，确认双方权利义务终止，对房屋状况和费用结算无异议。交接中的常见争议点包括：房屋损耗界定（正常老化vs人为损坏）、维修基金余额归属、租客押金移交等。建议业主在交接时全程拍照录像留存证据，必要时邀请第三方见证。","legalRef":"《民法典》第九百二十九条：因受托人的过错造成委托人损失的，委托人可以请求赔偿损失。","consumerBenefit":"规范完成托管交接，避免后续纠纷和损失","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"shu","meetingPhase":[]},"alias":["托管到期交接","托管期满交接","托管到期验收"],"dataRef":"约25%的托管纠纷发生在到期交接环节","caseRef":"某业主托管到期后未到场验房，事后发现地板严重磨损，托管方以'正常损耗'拒赔，业主维权困难"},{"id":"SRV-AST-012","name":"委托管理模式转换","domain":"L3-持有阶段","subScene":"委托管理模式","scene":"L3-持有阶段·委托管理模式","cq":"托管签了一半想换模式可以吗？怎么操作？","ola":"合同期内可协商变更托管模式，但可能涉及违约金或费用调整。","cp":["需双方协商一致并签署补充协议","可能产生违约金或费用差","建议在合同续签时转换"],"detail":"委托管理模式转换是指在托管合同履行期间，业主与托管方协商将当前托管模式变更为另一种模式的操作。常见转换场景包括：部分委托转全权委托（业主发现自管精力不足，希望增加委托范围）、全权委托转部分委托（业主希望收回部分管理权，降低托管成本）、普通委托转风险代理（业主希望获得保底收益保障）等。模式转换的法律依据是合同变更——需双方协商一致并签署《托管合同补充协议》，明确变更内容、生效时间和费用调整方案。需注意的风险点：一、部分托管合同约定'模式变更需支付违约金'，金额可能为1-3个月托管费；二、模式转换后费用标准可能调整，如部分委托转全权委托后费率上升；三、建议业主在合同到期续签时转换模式，避免合同期内的变更成本。转换前应充分评估新模式的优劣势，避免反复变更。","legalRef":"《民法典》第五百四十三条：当事人协商一致，可以变更合同。","consumerBenefit":"灵活调整托管方案以匹配变化的需求，提升服务满意度","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"qi","meetingPhase":[]},"alias":["托管模式转换","托管模式变更","托管模式升级"],"dataRef":"约15%的业主在托管期内申请模式转换","caseRef":"某业主部分委托1年后转全权委托，协商免除变更费，费率从5%调整为10%，整体满意度提升"},{"id":"SRV-AST-020","name":"租金催收与欠租处理","domain":"L3-持有阶段","subScene":"代运营服务","scene":"L3-持有阶段·代运营服务","cq":"租客拖欠租金，托管方怎么处理？能帮我催吗？","ola":"托管方按流程催收：提醒→催告→宽限期→违约处理。","cp":["逾期1-3天短信提醒","逾期7天书面催告","逾期15天启动违约条款"],"detail":"租金催收与欠租处理是托管代运营中最直接关系业主现金流的服务模块。标准催收流程分为四个递进阶段：一、友好提醒——逾期1-3天内，通过短信或电话友好提醒租客缴纳租金，了解是否因出差、遗忘等非主观原因延迟；二、书面催告——逾期7天以上，发送正式催告函，列明欠租金额、逾期天数和缴费期限，同时通知业主；三、宽限期——催告后给予3-7天宽限期，期间托管方持续跟进，同时评估租客还款意愿和能力；四、违约处理——宽限期届满仍未缴纳的，启动租赁合同违约条款，包括：按日收取滞纳金（通常为欠租的0.05%-0.1%/天）、从押金中扣除欠租、发送解除合同通知书、启动清退程序等。对于恶意欠租或多次欠租的租客，托管方应记录其不良信用信息。业主需注意：催收过程中不得采取断水断电、换锁等非法手段，否则业主和托管方可能承担侵权责任。","legalRef":"《民法典》第七百二十二条：承租人无正当理由未支付或者迟延支付租金的，出租人可以请求承租人在合理期限内支付；逾期不支付的，出租人可以解除合同。","consumerBenefit":"专业化催收流程保障租金及时到账，避免业主直接面对催收尴尬","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"fa","meetingPhase":[]},"alias":["租金催收","欠租处理","催缴租金"],"dataRef":"专业催收7天内回款率达85%，自管催收回款率仅60%","caseRef":"某租客连续2月欠租，托管方按流程催告无果后启动解除合同，同时从押金中扣除欠租，业主损失最小化"},{"id":"SRV-AST-021","name":"退租验收与结算","domain":"L3-持有阶段","subScene":"代运营服务","scene":"L3-持有阶段·代运营服务","cq":"租客退租时托管方怎么验收？押金怎么退？","ola":"托管方到场验房、确认损坏、结算费用、退还押金，全流程代办。","cp":["对照入住记录逐项验收","界定正常损耗和人为损坏","结算费用后退还押金余额"],"detail":"退租验收与结算是租赁周期结束时的关键环节，直接影响业主的资产状况和租客的押金退还。标准流程如下：一、退租预约——租客提前15-30天通知退租意向，托管方预约验收时间；二、到场验收——托管方携带《入住状况确认书》和入住时照片，逐项比对房屋现状，重点检查墙面、地板、门窗、家电家具的完好程度；三、损耗界定——正常损耗（如墙面轻微泛黄、家电正常老化）由业主承担，人为损坏（如墙面大面积涂鸦、地板刮痕、家电人为损坏）从租客押金中扣除维修费用；四、费用结算——计算水电物业等欠费、维修扣款、未付租金，与押金抵扣后多退少补；五、押金退还——扣除合理费用后，7-15个工作日内退还押金余额。验收中的常见争议点：损耗界定分歧（业主认为人为损坏、租客认为正常老化）、家电老化责任归属、押金扣款金额争议。建议托管方在入住和退租时均拍照录像，作为客观证据。","legalRef":"《民法典》第七百一十四条：承租人应当妥善保管租赁物；《民法典》第七百三十三条：租赁期限届满，承租人应当返还租赁物。","consumerBenefit":"专业验收保护房屋资产，合理扣费避免纠纷","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"shu","meetingPhase":[]},"alias":["退租验收","退租结算","退租交接"],"dataRef":"约40%的退租纠纷涉及损耗界定争议","caseRef":"某租客退租时墙面大面积污渍，托管方凭借入住照片对比证明为租客造成，扣款2000元维修费"},{"id":"SRV-AST-022","name":"物业费用代缴","domain":"L3-持有阶段","subScene":"代运营服务","scene":"L3-持有阶段·代运营服务","cq":"托管期间物业费、水电费谁交？托管方能代缴吗？","ola":"托管方可代缴物业费等固定费用，水电费一般由租客自理。","cp":["物业费通常从租金中代扣代缴","水电费由租客自行缴纳","代缴记录纳入月度报表"],"detail":"物业费用代缴是托管代运营的基础服务之一，指托管方代为缴纳房屋相关的固定性费用，确保费用不拖欠、房屋不停供。代缴范围通常包括：一、物业管理费——按月或按季从租金中扣除后代缴给物业公司；二、供暖费——北方地区冬季供暖费，可选择一次性代缴或分期扣除；三、房屋保险费——如业主购买了房屋财产保险，保费可由托管方代缴；四、车位管理费——带车位出租时车位管理费的代缴。不代缴的费用：水电燃气费——通常由租客按实际使用量自行缴纳，托管方负责督促租客按时缴费并在退租时结算；网络费——由租客自行办理和缴费。费用代缴的记账逻辑：代缴金额先从租金收入中扣除，剩余净租金转付业主，所有代缴记录纳入月度报表附缴费凭证。业主需注意：代缴仅是受托代付，费用实际承担方按合同约定——物业费通常由业主承担，供暖费根据合同约定由业主或租客承担。","legalRef":"《民法典》第九百二十一条：委托人应当预付处理委托事务的费用。","consumerBenefit":"免除缴费烦恼，避免因欠费导致停供或滞纳金","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"shu","meetingPhase":[]},"alias":["物业费代缴","代缴物业费","托管代缴费"],"dataRef":"物业费代缴服务使欠费率从12%降至1%以下","caseRef":"某业主因忘缴物业费3个月，被物业起诉并产生滞纳金500元，托管后代缴再无此问题"},{"id":"SRV-AST-023","name":"税务申报与合规","domain":"L3-持有阶段","subScene":"代运营服务","scene":"L3-持有阶段·代运营服务","cq":"托管期间租金收入要交税吗？托管方帮忙报税吗？","ola":"租金收入需依法纳税，部分托管方提供税务代理服务。","cp":["租金收入需缴纳个人所得税","部分托管方代为申报纳税","可合法享受税收优惠政策"],"detail":"房屋出租的税务合规是业主常忽略但不可回避的法定义务。房屋租金收入涉及的税种主要包括：一、个人所得税——按'财产租赁所得'计税，月租金收入扣除法定费用（修缮费每月最高800元、税费等）后，再扣除800元或20%的法定减除费用，剩余按20%税率缴纳；二、增值税——个人出租住房按1.5%征收率缴纳，月租金10万元以下免征；三、房产税——个人出租住房按4%税率缴纳；四、印花税——按租赁金额0.1%贴花。部分城市对个人出租住房实行'综合税率'，将上述税种合并按月租金的4%-6%一次性征收。托管方的税务服务通常包括：年度租金收入汇总、计算应纳税额、协助准备申报材料、代为向税务局申报（需业主授权）。业主需注意：依法纳税是法定义务，不申报或逃税将面临补税、滞纳金和罚款，严重的可能构成逃税罪。建议业主充分利用合法的税收优惠，如住房贷款利息抵扣、修缮费扣除等。","legalRef":"《个人所得税法》第二条：财产租赁所得应缴纳个人所得税；《房产税暂行条例》第三条：房产出租的，以房产租金收入为房产税的计税依据。","consumerBenefit":"确保税务合规，避免因漏报逃税受到处罚","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"fa","meetingPhase":[]},"alias":["托管税务","租金税务申报","托管报税"],"dataRef":"个人出租住房综合税率约4%-6%（因城市而异）","caseRef":"某业主2年未申报租金个税，被税务稽查后补税+滞纳金合计1.8万元"},{"id":"SRV-AST-024","name":"代运营服务费计算方法","domain":"L3-持有阶段","subScene":"代运营服务","scene":"L3-持有阶段·代运营服务","cq":"代运营服务费具体怎么算？有没有计算公式？","ola":"代运营费=月租金×费率+单项服务费+维修基金，合计测算。","cp":["基础费率乘以月租金","叠加单项服务模块费用","加上维修基金预存金额"],"detail":"代运营服务费的计算是业主评估托管经济性的核心依据。完整的费用构成包括三个部分：一、基础托管费——按月租金×费率计算，全权委托费率8%-15%，部分委托按委托模块分别计费（如仅招租1个月租金、仅维修调度每月100-300元、仅租务处理每月200-500元）；二、单项服务费——按次或按期收取的附加费用，如租客替换费（每次2000-5000元）、广告推广费（每次500-2000元）、法律咨询费（每次500-1500元）、年度税务申报费（每年500-1000元）；三、维修基金——每月预存100-300元用于日常小修，年度结算多退少补。举例：月租6000元、全权委托费率10%的房屋，月基础托管费600元+维修基金200元=月度费用800元，年度费用9600元，加上租客替换费1次2000元，年度总费用11600元，占年租金收入的16.1%。业主签约前应要求托管方提供完整的费用模拟测算表，逐项列明所有可能费用。","legalRef":"《民法典》第九百二十八条：受托人完成委托事务的，委托人应当按照约定向其支付报酬。","consumerBenefit":"精确测算代运营总成本，做出经济合理的托管决策","tags":{"clientType":["seller","landlord"],"stage":"pre","layer":"shu","meetingPhase":[]},"alias":["代运营费用","代运营费计算","代运营收费"],"dataRef":"全权委托年度总费用约占年租金收入12%-20%","caseRef":"某业主签约前要求完整费用测算，发现实际年费率达16%，高于宣传的10%，据此协商降低了租客替换费"},{"id":"SRV-AST-030","name":"空置期房屋维护","domain":"L3-持有阶段","subScene":"空置期管理","scene":"L3-持有阶段·空置期管理","cq":"房子空着没人住，需要怎么维护？","ola":"空置期需定期通风、检查水电、保养家电，防止设施老化损坏。","cp":["每月至少通风1-2次","定期检查水电管道","家电定期开机运行保养"],"detail":"空置期房屋维护是常被业主忽视但极为重要的资产管理环节。空置房屋因缺乏日常使用和通风，比有人居住时更容易出现设施老化和损坏。核心维护措施包括：一、通风防潮——每月至少通风1-2次，每次2-4小时，潮湿季节增加至每周1次，防止墙面发霉、木地板变形、衣物和家具受潮；二、水电检查——每月检查水龙头、马桶是否渗漏，水管接口是否松动，电路是否正常通电；三、家电保养——空调每月开机运行30分钟（防止压缩机卡死），冰箱每月通电2小时（防止管路腐蚀），洗衣机每月空转一次；四、管道防堵——每月开水龙头放水5分钟，防止水管内积水和锈蚀，地漏加注清水防止干涸反味；五、安全巡查——检查门窗锁具、清理信箱、观察是否有异常迹象。托管方通常将空置维护纳入巡检服务，每月上门1次执行维护清单。业主自行管理时，可委托物业或邻居定期帮忙，每次成本约50-100元。","legalRef":"《民法典》第七百一十二条：出租人应当履行租赁物的维修义务。","consumerBenefit":"防止空置期设施老化和损坏，保护房屋资产价值","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"shu","meetingPhase":[]},"alias":["空置维护","空置房保养","空置期养护"],"dataRef":"缺乏维护的空置房再次出租时维修费平均增加40%","caseRef":"某业主空置6个月未维护，空调压缩机卡死、木地板受潮变形，维修费合计8000元"},{"id":"SRV-AST-032","name":"空置期税费减免","domain":"L3-持有阶段","subScene":"空置期管理","scene":"L3-持有阶段·空置期管理","cq":"房屋空置期间物业费和供暖费能减免吗？","ola":"部分城市空置房可申请物业减免30%、供暖减免20%。","cp":["物业费减免需与物业协商","供暖费部分城市有减免政策","需提供空置证明申请减免"],"detail":"空置期税费减免是业主降低空置持有成本的合法途径，但各地政策差异较大，需主动了解和申请。主要减免项目包括：一、物业费减免——部分城市规定空置房物业费可减免，如山东、河南等地空置6个月以上的房屋物业费减免30%，但需业主向物业提出书面申请并提交空置证明（如水电零使用记录）；部分小区物业自主提供空置减免（10%-30%不等），无统一标准，需逐案协商；二、供暖费减免——北方城市普遍有空置房供暖费减免政策，通常减免20%-30%，但需在供暖季开始前申请并办理'暂停供暖'手续，部分城市要求'整栋楼多数住户同意方可停暖'；三、房产税——目前个人自用住房不征收房产税，但出租后涉及从租计征，空置期间从价计征部分可能涉及优惠（各地政策不同）；四、其他费用——如车位管理费，部分物业可减免空置车位管理费。申请减免的通用流程：准备空置证明材料→向物业或供暖公司提交书面申请→审核通过后按减免标准执行。业主应主动了解当地政策，不要因为'不知道'而白白多交费用。","legalRef":"《物业管理条例》第四十一条：业主应当根据物业服务合同的约定交纳物业服务费用。各地方性法规对空置物业费减免有具体规定。","consumerBenefit":"合法减免空置期税费，降低持有成本","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"shu","meetingPhase":[]},"alias":["空置税费减免","空置物业减免","空置供暖减免"],"dataRef":"空置物业费减免幅度通常为10%-30%，供暖费减免20%-30%","caseRef":"某业主2套房空置申请物业费减免30%，年节省物业费4200元"},{"id":"SRV-AST-034","name":"空置期安全管理","domain":"L3-持有阶段","subScene":"空置期管理","scene":"L3-持有阶段·空置期管理","cq":"房子空着怎么保证安全？怕被盗或者出事故怎么办？","ola":"空置房需关水电总阀、加装智能监控、委托物业定期巡查。","cp":["关闭水阀总闸和燃气阀门","安装智能门锁和远程监控","委托物业或邻居定期巡查"],"detail":"空置期安全管理是防止空置房发生安全事故和财产损失的重要保障措施。主要安全风险和防范措施如下：一、水患防范——关闭水阀总闸（最重要），排空管道存水，防止水管爆裂漏水；检查所有水龙头和管道接口是否关闭严密；如需保留供水（如浇花），安装漏水报警器。二、火灾防范——关闭燃气总阀门，拔除所有电器插头，关闭电闸（保留必要供电如监控）；清除室内易燃杂物，检查烟感报警器是否正常。三、防盗防范——更换或加固门锁，安装智能门锁（可远程查看开门记录）；安装远程监控摄像头（支持手机APP实时查看）；贵重物品全部搬离，窗帘保留日常状态避免暴露空置信息。四、委托巡查——委托物业每周巡查1次，检查门窗是否完好、有无异常迹象；委托邻居帮忙留意，发现异常及时通知。五、保险保障——确认房屋保险是否覆盖空置期风险，如实申报空置状态。托管方通常将安全管理纳入空置期巡检服务，每次巡检按安全清单逐项检查。","legalRef":"《民法典》第一千一百六十五条：行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。","consumerBenefit":"全面防范空置期安全风险，避免因事故造成的财产损失和第三方责任","tags":{"clientType":["seller","landlord"],"stage":"mid","layer":"fa","meetingPhase":[]},"alias":["空置安全","空置房安全","空置期安全"],"dataRef":"空置房漏水事故占空置房安全事故的60%以上","caseRef":"某业主空置房因未关水阀，水管冻裂后漏水3天未被发觉，地板和楼下邻居装修损毁，赔偿5.6万元"},{"id":"SRV-AST-039","name":"托管机构跑路风险","domain":"L3-持有阶段","subScene":"托管合同与风险","scene":"L3-持有阶段·托管合同与风险","cq":"听说有托管公司跑路了，怎么避免这种风险？","ola":"选择合规机构、使用监管账户、签订保障条款，三重防范跑路风险。","cp":["优先选择有监管账户的机构","警惕高于市场价的保底承诺","签约时增加风险保障条款"],"detail":"托管机构跑路是业主面临的最严重风险之一，近年多起长租公寓'暴雷'事件给业主造成了巨大损失。跑路风险的典型模式：机构以高于市场价的保底租金吸引业主签约，收取租客半年或一年租金后，仅向业主支付1-2个月租金便卷款跑路，业主既收不到后续租金，又面临租客已预付租金要求继续居住的法律困境。防范跑路风险的关键措施：一、资质审查——核查营业执照、备案证、经营年限，成立不足2年的机构风险较高；二、监管账户——确认使用银行监管账户，这是最有效的防线；三、警惕高保底——保底租金高于市场价90%的机构可能存在'庞氏'嫌疑；四、缩短转付周期——约定租金按月转付而非按季或按年，减少资金在托管方的沉淀；五、收取保证金——要求托管方缴纳1-3个月租金的履约保证金；六、分散风险——多套房产不要全部委托同一家机构。一旦发现托管方出现租金转付延迟、客服失联、办公地址搬迁等异常信号，应立即启动合同解除和资金保全措施。","legalRef":"《住房租赁条例》第二十三条：住房租赁企业应当设立资金监管账户，用于收取和支付租金。《刑法》第二百七十二条：挪用资金罪。","consumerBenefit":"系统识别和防范托管机构跑路风险，保护自身资金安全","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"fa","meetingPhase":[]},"alias":["托管跑路","托管机构跑路","长租公寓暴雷"],"dataRef":"近年托管跑路案件中业主平均损失约4.5个月租金","caseRef":"某长租公寓以高于市场价15%的保底吸引200余位业主签约，半年后跑路，业主平均损失5.2万元"},{"id":"SRV-AST-041","name":"托管合同解除条件","domain":"L3-持有阶段","subScene":"托管合同与风险","scene":"L3-持有阶段·托管合同与风险","cq":"什么情况下可以解除托管合同？提前解约要赔多少？","ola":"协商一致、对方违约或不可抗力可解除，提前解约付违约金。","cp":["协商一致可无责解除","对方根本违约可单方解除","提前解约需付1-3月租金违约金"],"detail":"托管合同解除涉及业主退出托管关系的核心权利，需清楚了解解除条件和后果。合同解除分为三种情形：一、协商解除——双方协商一致，签署《合同解除协议》，通常不产生违约金，按实际托管期间结算费用后交接，这是最理想的解除方式；二、法定解除——因对方根本违约而单方解除，如托管方挪用租金、长期未转付租金、严重违反管理义务等，业主可书面通知解除合同并追究违约责任，无需支付违约金；三、单方提前解除——无正当理由提前解除合同，属于违约行为，需支付违约金（通常为1-3个月租金），同时需结算已发生的托管费用。解除后的处理流程：一、书面通知对方解除意向和理由；二、结清已发生的托管费用和维修费用；三、按托管到期交接流程验房交接；四、退还保证金或扣除违约金后退还余额；五、如涉及租客在住，需协调租赁合同的处理（转由业主接管或与新托管方衔接）。业主应特别注意合同中的'自动续约条款'——部分合同约定到期未书面通知则自动续约，可能被绑定更长期限。","legalRef":"《民法典》第五百六十三条：有下列情形之一的，当事人可以解除合同：（一）因不可抗力致使不能实现合同目的；（二）在履行期限届满前，当事人一方明确表示或者以自己的行为表明不履行主要债务；（三）当事人一方迟延履行主要债务，经催告后在合理期限内仍未履行。","consumerBenefit":"清楚了解解约权利和后果，在需要退出时有据可依","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"fa","meetingPhase":[]},"alias":["托管解约","合同解除","托管提前解约"],"dataRef":"约20%的托管合同在到期前被提前解除","caseRef":"某业主发现托管方连续2月未转付租金，以'根本违约'为由书面通知解除合同，免付违约金并追回租金"},{"id":"SRV-AST-042","name":"长租公寓托管风险","domain":"L3-持有阶段","subScene":"托管合同与风险","scene":"L3-持有阶段·托管合同与风险","cq":"长租公寓托管有什么风险？怎么避免踩坑？","ola":"核心风险为资金池和加杠杆，重点审查资金链安全。","cp":["资金池模式风险最高","加杠杆扩张易断裂","审查租金收付差和杠杆率"],"detail":"长租公寓托管是近年来风险事件最集中的领域，业主需深刻理解其商业模式和风险根源。长租公寓托管分为两种模式：一、分散式——托管方从多位业主手中收房，装修后溢价出租赚取租金差（收房价低于出房价），典型如蛋壳、青客等；二、集中式——托管方整栋承租或自持物业统一运营。分散式长租公寓的核心风险在于'资金池'模式：以月付方式向业主支付租金，但要求租客季付或年付，形成资金沉淀（'期限错配'），再将沉淀资金用于收更多房源（'加杠杆'），一旦新收房源速度放缓或出租率下降，资金链即断裂，表现为'暴雷跑路'。风险识别信号：一、收房价明显高于市场价（'高收低出'不可持续）；二、要求租客年付或使用租金贷；三、短期内快速扩张收房；四、无银行监管账户；五、经营主体频繁变更。业主防范建议：选择'不收租客年付'的托管方、使用监管账户、按月转付、收取保证金、分散托管。","legalRef":"《住房租赁条例》第二十三条：住房租赁企业不得以隐瞒、欺骗、强迫等方式要求承租人使用住房租金贷款。《刑法》第一百九十二条：集资诈骗罪。","consumerBenefit":"识别长租公寓托管的核心风险，避免'暴雷'损失","tags":{"clientType":["seller","landlord"],"stage":"all","layer":"fa","meetingPhase":[]},"alias":["长租公寓风险","长租公寓托管","公寓托管风险"],"dataRef":"近年长租公寓暴雷涉及业主超10万户，平均损失约5万元","caseRef":"某长租公寓'高收低出'模式下收房价比市场高15%、出房价低10%，资金链断裂后跑路，业主和租客双损"},{"id":"SRV-AST-043","name":"托管纠纷仲裁与诉讼","domain":"L3-持有阶段","subScene":"托管合同与风险","scene":"L3-持有阶段·托管合同与风险","cq":"和托管方发生纠纷协商不了怎么办？能打官司吗？","ola":"纠纷可依次通过协商、调解、仲裁或诉讼解决，仲裁效率更高。","cp":["先协商后调解再诉讼","合同约定仲裁条款可仲裁","诉讼周期6-18个月"],"detail":"托管纠纷的解决遵循'协商优先、调解居中、仲裁/诉讼兜底'的递进原则。各解决途径的特点如下：一、协商——业主与托管方直接沟通，最快捷、成本最低，但需要双方均有诚意，适合轻微争议（如小额费用分歧）；二、调解——通过居委会、住建部门或行业协会调解，中立第三方协助协商，调解协议具有合同效力，但无强制执行力，适合中等争议；三、仲裁——合同中约定仲裁条款的，向约定的仲裁委员会申请仲裁，仲裁程序比诉讼简便（3-6个月出裁决），一裁终局有强制执行力，但仲裁费用较高（按争议金额2%-5%收取），且需合同中有有效的仲裁条款；四、诉讼——向房屋所在地法院起诉，程序最正式但周期最长（一审6-12个月、二审3-6个月），成本包括诉讼费（按争议金额分段收取）、律师费（争议金额5%-10%），判决有强制执行力。实操建议：纠纷金额1万元以下优先协商调解；1-10万元考虑仲裁（如有条款）；10万元以上可诉讼。无论何种途径，保留证据是关键——合同、付款凭证、沟通记录、房屋照片等。","legalRef":"《民法典》第二百三十三条：物权受到侵害的，权利人可以通过和解、调解、仲裁、诉讼等途径解决。《仲裁法》第四条：当事人采用仲裁方式解决纠纷，应当双方自愿，达成仲裁协议。","consumerBenefit":"了解纠纷解决途径和各自特点，选择最适合的方式高效维权","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"fa","meetingPhase":[]},"alias":["托管纠纷仲裁","托管诉讼","托管纠纷维权"],"dataRef":"托管纠纷调解成功率达65%，仲裁平均周期4个月，诉讼一审平均8个月","caseRef":"某业主与托管方就3万元维修费争议诉至法院，一审8个月判决业主胜诉，托管方承担维修费和诉讼费"},{"id":"SRV-MOV-009","name":"搬家当天注意事项与流程","domain":"L2-交易阶段","subScene":"搬家流程与准备","scene":"L2-交易阶段·搬家流程与准备","cq":"搬家当天有哪些注意事项和流程？","ola":"当天核对清单装车、全程监督、到新居逐箱清点签收。","cp":["装车前逐箱核对清单编号","贵重物品随身全程监督","卸车后逐箱清点再签收"],"detail":"搬家当天的流程执行直接关系到物品安全和纠纷预防，应严格按照'装-运-卸-查'四步执行。搬家当天早上准备：确认搬家公司车辆和人员准时到达，核对车牌号和人员身份；再次确认书面报价单和合同条款；准备好搬家清单和手机用于拍照录像。装车环节（约1-2小时）：工人装车时客户应全程在场监督，每箱装车前核对箱号和清单；先装大件重物（家具家电）放底部，后装小件轻物放上部；易碎品标注'勿压'并单独区域放置；贵重物品（珠宝、证件、现金、电子产品）随身携带不上车；装车完毕后对车厢内物品拍照存证，确认车厢封闭。运输环节：跟车或自驾跟随搬家车辆，记录出发时间和路线；如无法跟车，要求搬家公司提供GPS定位和预计到达时间。卸车环节（约1-2小时）：到达新居后先对车厢外观拍照确认封条完好；按房间标记逐箱卸货并送至对应房间；大件家具家电卸车时检查有无新增损坏，发现问题立即拍照并当场告知工人。签收环节：全部卸完后逐箱核对清单编号确认无遗漏；检查易碎品有无损坏；确认无误后在送货单上签字，保留客户联；如有损坏或丢失，在签收单上注明问题并要求工人签字确认，拒绝签署'一切完好'声明。","legalRef":"《民法典》第八百三十条：货物交付时承运人应当按约定向收货人交付货物凭证；第八百三十一条：收货人提货时应当按照约定的期限检验货物。","consumerBenefit":"全程监督和逐项核对最大限度保障财产安全，纠纷发生时有据可依。","tags":{"clientType":["buyer","tenant"],"stage":"mid","layer":"shu","meetingPhase":[]},"alias":["搬家当天","搬运当天流程","搬家日"],"dataRef":"搬家当天全程监督的案例中，物品丢失损坏纠纷发生率低于5%；未监督的达25%。","caseRef":"某客户搬家当天未在场监督，搬家公司工人将一台微波炉'遗漏'在车上，客户签收后发现缺少，因已签署'一切完好'声明无法索赔。"},{"id":"SRV-MOV-018","name":"搬家物品损坏赔偿标准","domain":"L2-交易阶段","subScene":"搬家纠纷与衔接","scene":"L2-交易阶段·搬家纠纷与衔接","cq":"搬家时物品损坏了怎么赔偿？赔偿标准是什么？","ola":"物品损坏按合同约定赔偿，无约定按市场价赔偿，需当场拍照留证。","cp":["损坏当场拍照通知搬家公司","按合同约定标准索赔","无约定按到达地市场价赔偿"],"detail":"搬家物品损坏是最高发的纠纷类型，掌握正确的处理流程和赔偿标准至关重要。发现物品损坏后的处理流程：第一步，当场发现——卸车或拆包时发现损坏，立即拍照（多角度拍摄损坏部位和整体）、录像记录，通知搬家公司现场负责人确认并签字；第二步，延迟发现——部分损坏可能在搬运后数小时或数天才发现，应在发现后48小时内通知搬家公司并拍照，超过48小时搬家公司可能拒绝承认；第三步，索赔协商——凭照片、购买凭证、搬家合同向搬家公司提出赔偿要求。赔偿标准的法律依据：《民法典》第八百三十三条规定，货物毁损灭失的赔偿额，当事人有约定的按照约定，没有约定或约定不明确的，按照交付或应当交付时货物到达地的市场价格计算。这意味着：如果搬家合同约定了每件赔偿上限（如500元/件），则按约定执行；如果合同未约定赔偿标准或约定不明，则按物品市场价值赔偿。消费者维权策略：如果合同中的赔偿上限条款明显不合理，可主张该格式条款无效；如果搬家公司存在重大过失或故意损坏，不受赔偿上限条款限制；购买搬家保险的，直接向保险公司理赔。如协商不成，可向12315投诉、向法院起诉。","legalRef":"《民法典》第八百三十二条：承运人对运输过程中货物的毁损、灭失承担赔偿责任。第八百三十三条：赔偿额有约定按约定，无约定按到达地市场价格计算。第四百九十七条：格式条款不合理免除己方责任的条款无效。","consumerBenefit":"掌握赔偿标准和维权流程，物品损坏后获得合理赔偿。","tags":{"clientType":["buyer","tenant"],"stage":"mid","layer":"fa","meetingPhase":[]},"alias":["搬家损坏赔偿","物品损坏赔偿","搬运损坏"],"dataRef":"搬家物品损坏纠纷中，约55%通过协商解决，25%通过消协调解解决，20%通过诉讼解决；平均赔偿金额约1800元。","caseRef":"某客户搬家时衣柜门板被刮花，因搬前已拍照记录完好状态，搬家公司承认责任赔偿800元维修费。"},{"id":"SRV-MOV-019","name":"搬家时间约定与违约处理","domain":"L2-交易阶段","subScene":"搬家纠纷与衔接","scene":"L2-交易阶段·搬家纠纷与衔接","cq":"搬家公司迟到或爽约怎么办？","ola":"合同约定到达时间和违约金，迟到可索赔，爽约可要求赔偿损失。","cp":["合同写明到达时间和违约金","迟到超2小时可要求减免费用","爽约可索赔实际损失"],"detail":"搬家时间约定是搬家合同的重要内容，搬家公司迟到或爽约会给客户造成严重不便和经济损失。时间约定的注意事项：签订合同时应明确搬家日期和具体到达时间（如'某月某日上午8:00-9:00到达'），而非模糊表述；约定免费等候时间（如客户等候超过约定时间2小时，搬家公司应减免部分费用）；约定违约金标准（如迟到每小时减免50-100元，爽约赔偿200-500元）。搬家公司迟到的处理：迟到1小时内属正常范围；迟到1-2小时，要求搬家公司说明原因并书面确认，可协商减免费用；迟到超过2小时，有权要求减免费用或取消服务不承担违约责任；因搬家公司迟到导致其他损失（如电梯预约过期需重新预约、请假扣工资等），可要求搬家公司赔偿实际损失。搬家公司爽约的处理：立即联系其他搬家公司应急（保留加急服务的额外费用凭证作为索赔依据），向原搬家公司提出赔偿要求——退还已付定金、赔偿实际损失，向12315投诉。预防措施：搬家前1天电话确认到达时间，搬家当天早上再次确认车辆出发状态，选择有信誉的搬家公司并签订含违约条款的书面合同。","legalRef":"《民法典》第八百一十一条：承运人应当在约定期限或者合理期限内将货物运输到约定地点。第五百七十七条：当事人一方不履行合同义务或履行不符合约定的，应承担继续履行、采取补救措施或赔偿损失等违约责任。","consumerBenefit":"搬家公司迟到爽约时获得合理补偿，避免连带损失。","tags":{"clientType":["buyer","tenant"],"stage":"mid","layer":"fa","meetingPhase":[]},"alias":["搬家时间约定","搬家迟到","搬家爽约"],"dataRef":"搬家公司迟到或爽约投诉占搬家类投诉的约18%，其中爽约占比约6%。","caseRef":"某客户预约早上8点搬家，搬家公司到下午2点才到，导致客户新房电梯预约过期需重新预约（损失100元），请假1天扣工资300元，经投诉获赔500元。"},{"id":"SRV-MOV-023","name":"搬家噪音投诉与处理","domain":"L2-交易阶段","subScene":"搬家纠纷与衔接","scene":"L2-交易阶段·搬家纠纷与衔接","cq":"搬家噪音被邻居投诉怎么办？","ola":"遵守物业规定搬家时段，提前告知邻居，噪音过大需协调处理。","cp":["遵守物业规定搬家时段","提前告知相邻邻居","大件搬运铺设减震垫"],"detail":"搬家过程中产生的噪音（搬运碰撞声、电梯运送声、拆装家具声、人员交谈声）可能引起邻居投诉，尤其在高层住宅和密集社区中更为突出。噪音产生的主要环节：大件家具通过楼道搬运时的碰撞声、家具拆装时的敲击声、物品装车卸车时的碰撞声、搬家工人之间的喊话交流声。预防措施：第一，遵守时段——严格按照物业规定的搬家时段进行（通常工作日9:00-17:00，周末8:00-12:00），避开午休和晚间休息时段；第二，提前告知——搬家前1-2天在楼道张贴搬家告知书或在业主群发通知，说明搬家日期、时间和可能的影响；第三，减噪措施——在楼道和电梯内铺设保护垫（既保护墙面也减噪）、大件家具搬运时轻拿轻放、提醒工人控制音量。邻居投诉后的处理：第一时间向投诉邻居道歉并说明搬家是临时行为；如投诉持续，请物业协调沟通；如邻居报警，配合警方说明情况并加快搬家进度。特殊情况处理：老旧小区楼道狭窄，大件家具搬运噪音难以避免，建议选择工作日搬家减少影响；钢琴等大型乐器搬运噪音较大，建议预约专门的搬运时段并提前通知。物业管理有权对违反搬家时间规定、造成严重噪音扰民的行为进行劝阻。","legalRef":"《噪声污染防治法》第六十六条：对已建成投用的住宅楼进行室内装修和搬运活动，应当限制作业时间。《民法典》第二百八十八条：不动产的相邻权利人应当按照有利生产、方便生活、团结互助、公平合理的原则处理相邻关系。","consumerBenefit":"妥善处理邻里关系，避免搬家噪音引发投诉和纠纷。","tags":{"clientType":["buyer","tenant"],"stage":"mid","layer":"fa","meetingPhase":[]},"alias":["搬家噪音","搬运噪音","搬家扰民"],"dataRef":"搬家噪音投诉占社区物业投诉的约8%，周末和节假日搬家投诉率是工作日的3倍。","caseRef":"某客户周末早上7点开始搬家，邻居投诉噪音扰民报警，警方到场劝阻，搬家延误2小时，搬家公司加收超时费150元。"},{"id":"SRV-MOV-024","name":"搬家物品丢失处理","domain":"L2-交易阶段","subScene":"搬家纠纷与衔接","scene":"L2-交易阶段·搬家纠纷与衔接","cq":"搬家后发现东西丢了怎么办？","ola":"发现物品丢失立即核查清单，通知搬家公司，48小时内报案投诉。","cp":["对照搬前清单逐项核查","立即通知搬家公司并报案","保留证据向消协或法院索赔"],"detail":"搬家物品丢失是比损坏更严重的纠纷类型，丢失物品可能是搬家公司工人疏忽遗漏、搬运途中遗失，也可能是人为盗窃。发现物品丢失后的处理流程：第一步，核查确认——发现物品缺失后，立即对照搬家前的物品清单逐项核查，确认确实丢失而非放错箱子或还在原住所；检查搬家车辆是否已全部卸空；联系原住所确认物品是否遗落。第二步，通知搬家公司——确认丢失后立即联系搬家公司，说明丢失物品名称、数量、价值和最后见到的时间，要求搬家公司协助查找。第三步，报警——如怀疑被盗或搬家公司拒绝配合，应立即报警，警方介入有助于调取监控和调查。第四步，索赔——凭搬家清单、照片、购买凭证向搬家公司提出赔偿要求；如拒绝赔偿，向12315投诉、向消费者协会申请调解、向法院起诉。物品丢失赔偿的法律依据：《民法典》第八百三十二条规定承运人对货物灭失承担赔偿责任，第八百三十三条规定赔偿额有约定按约定、无约定按市场价格计算。预防物品丢失的措施：搬家前制作详细清单并编号、贵重物品随身携带、装车和卸车时逐箱核对、签收前确认所有物品到位、不签署'一切完好'声明。如工人有盗窃行为，除赔偿外可向公安机关报案追究刑事责任。","legalRef":"《民法典》第八百三十二条：承运人对运输过程中货物的毁损、灭失承担赔偿责任。《刑法》第二百六十四条：盗窃公私财物数额较大的，处三年以下有期徒刑。","consumerBenefit":"丢失物品后掌握正确的处理和索赔流程，最大限度挽回损失。","tags":{"clientType":["buyer","tenant"],"stage":"mid","layer":"fa","meetingPhase":[]},"alias":["搬家丢东西","物品丢失","搬家盗窃"],"dataRef":"搬家物品丢失纠纷中约60%为小型物品（首饰、电子产品），平均丢失物品价值约2500元；通过法律途径追回率约55%。","caseRef":"某客户搬家后发现一台笔记本电脑丢失，因未做物品清单且已签署'一切完好'，搬家公司拒绝赔偿，报警后因无证据未能立案。"},{"id":"SRV-CLN-005","name":"保洁验收标准与流程","domain":"L3-持有阶段","subScene":"保洁类型与标准","scene":"L3-持有阶段·保洁类型与标准","cq":"保洁完成后怎么验收？标准是什么？","ola":"保洁验收按区域逐项检查，重点看无灰尘污渍水痕异味，签字确认。","cp":["按区域逐项检查清洁效果","重点检查死角和玻璃","合格签字不合格要求返工"],"detail":"保洁验收是保障保洁服务质量的关键环节，应在保洁完成后当面进行，发现问题及时要求返工。验收标准按区域划分：地面——目视无灰尘无污渍无水痕，瓷砖缝隙无黑垢，木地板无划痕新增，地毯无新污渍；玻璃——透亮无水痕无指纹无胶渍，窗框轨道无灰尘碎屑；厨房——台面无油渍无水渍，灶台无油垢，水槽无水垢无异味，橱柜内外无灰尘，油烟机表面无油滴；卫生间——洁具无水垢无黄渍，马桶内外清洁无异味，淋浴区无皂垢水垢，镜子无水痕无雾渍，地漏无堵塞无异味；卧室客厅——家具表面无灰尘，床头和沙发缝隙无碎屑，踢脚线无灰尘，灯具无蛛网无灰尘，开关面板无污渍手指印；细节——门把手无污渍，窗台无灰尘，墙角无蛛网，垃圾桶已倾倒清洗。验收流程：保洁完成后与保洁人员逐房间检查；发现问题当场指出并要求返工；全部合格后在服务确认单上签字；如有不满意项在确认单上注明并要求安排补做。验收时的注意事项：建议在自然光下检查（灯光可能掩盖灰尘和水痕）；用手触摸表面检查是否有残留灰尘；检查保洁人员是否使用了客户的私人物品（如毛巾、牙刷）；贵重物品检查是否完好无损坏。","legalRef":"《民法典》第七百七十九条：承揽工作完成后，定作人应当验收承揽人交付的工作成果。《消费者权益保护法》关于服务质量保证的规定。","consumerBenefit":"确保花钱买到合格的保洁服务，不满意及时返工不花冤枉钱。","tags":{"clientType":["seller","tenant"],"stage":"post","layer":"shu","meetingPhase":[]},"alias":["保洁验收","保洁检查","清洁验收标准"],"dataRef":"保洁服务投诉中约40%因'清洁不彻底'引发，其中未做验收直接签字的占比超70%。","caseRef":"某客户保洁后未验收直接签字，第二天发现厨房灶台油渍未清洁、卫生间镜子有水痕，要求返工被拒，因已签字确认无法维权。"},{"id":"SRV-CLN-006","name":"厨房深度清洁要点","domain":"L3-持有阶段","subScene":"保洁类型与标准","scene":"L3-持有阶段·保洁类型与标准","cq":"厨房深度清洁需要做哪些项目？多久做一次？","ola":"厨房深度清洁含油烟机拆洗、灶台去油、橱柜内外、瓷砖缝隙除油。","cp":["油烟机拆洗去油最核心","灶台台面顽固油垢清除","瓷砖缝隙橱柜内外清洁"],"detail":"厨房是家庭中油污最重、清洁难度最大的区域，深度清洁需要针对油污特性使用专业去油产品和工具。厨房深度清洁的核心项目：油烟机深度清洁——这是厨房清洁的重中之重，需拆卸油烟机叶轮和滤网浸泡去油（使用专用油烟机清洗剂或火碱溶液浸泡30分钟后刷洗），清洁油烟机外壳和集油盒，检查排烟管道是否通畅；建议每3-6个月清洗一次，长期不洗不仅影响排烟效果，还有火灾隐患。灶台区域——清除灶头周围的顽固油垢（使用除油剂喷洒静置5分钟后擦拭），清洁灶台不锈钢表面的烧灼痕迹，清理灶头火盖的堵塞物。台面和墙面——清除橱柜台面的水渍和油渍，瓷砖墙面油污清洁（特别是灶台背后区域），瓷砖缝隙中的油垢用缝隙刷配合除油剂清理。橱柜清洁——擦拭橱柜门板内外（注意门铰链和拉手角落），清理橱柜内部的油渍和碎屑，检查是否有受潮发霉。水槽和水龙头——去除水槽水垢和油渍，清洁水龙头表面的水垢和氧化层，清理下水口滤网。地面——厨房地面油污清洁（使用除油拖地液），特别注意橱柜下方和角落的油污积聚。厨房深度清洁建议每3个月一次，重油家庭（经常煎炸烹饪）每月一次。","legalRef":"《消防法》关于厨房油烟管道定期清洗的规定：餐饮场所油烟管道应定期清洗。","consumerBenefit":"彻底去除厨房油污改善烹饪环境，降低油烟机火灾风险，延长厨电使用寿命。","tags":{"clientType":["seller","tenant"],"stage":"all","layer":"shu","meetingPhase":[]},"alias":["厨房保洁","厨房清洁","厨房去油"],"dataRef":"油烟机长期不清洗导致排烟效率下降40%以上，电机负荷增加30%；厨房火灾中约30%与油烟积聚有关。","caseRef":"某家庭油烟机3年未清洗，烹饪时油烟机内部油垢起火，烧毁油烟机和厨房吊柜，损失约8000元。"},{"id":"SRV-CLN-007","name":"卫生间深度清洁要点","domain":"L3-持有阶段","subScene":"保洁类型与标准","scene":"L3-持有阶段·保洁类型与标准","cq":"卫生间深度清洁需要重点处理哪些问题？","ola":"卫生间深度清洁重点除霉除水垢，含马桶淋浴区瓷砖缝隙消毒杀菌。","cp":["瓷砖缝隙霉斑彻底清除","洁具水垢皂垢去除","全区域消毒杀菌除味"],"detail":"卫生间是家庭中湿度最高、细菌和霉菌最容易滋生的区域，深度清洁需要针对水垢、霉斑、皂垢和细菌进行专项处理。卫生间深度清洁的核心项目：瓷砖和缝隙——瓷砖表面的水垢和皂垢用酸性清洁剂（如柠檬酸溶液）溶解后擦除，瓷砖缝隙中的黑色霉斑用含氯消毒剂（如84消毒液稀释液）浸泡10-15分钟后用缝隙刷刷洗，顽固霉斑可用除霉啫喱涂抹静置后清除。马桶区域——马桶内壁用洁厕灵浸泡刷洗，马桶外部底座和后方死角用消毒液擦拭，马桶水箱内部清洗（揭开水箱盖清洗内部配件和水垢），马桶座圈铰链缝隙清洁消毒。淋浴区——花洒头水垢去除（将花洒浸泡在白醋或柠檬酸溶液中2-4小时），淋浴玻璃门水垢和皂垢清除（使用玻璃水垢清洁剂），淋浴地砖防滑处理。洗手台区域——台面水垢和牙膏渍清除，水龙头水垢和氧化层去除，下水口清理除味，镜子水痕和雾渍清除。地面和排水——地砖深度清洁和消毒，地漏拆开清理毛发和污垢，排水管道除味（使用管道清洁剂或小苏打+白醋）。消毒杀菌——全区域喷洒消毒液（特别是马桶、地漏、门把手等高频接触区域），保持通风30分钟以上。卫生间深度清洁建议每1-2个月一次。","legalRef":"《民法典》第七百七十条：承揽人应按定作人要求完成工作。","consumerBenefit":"消除卫生间霉菌和细菌滋生源，改善卫生环境，预防皮肤病和呼吸道问题。","tags":{"clientType":["seller","tenant"],"stage":"all","layer":"shu","meetingPhase":[]},"alias":["卫生间保洁","卫生间清洁","卫浴清洁"],"dataRef":"卫生间是家庭细菌含量最高的区域，未定期深度清洁的卫生间细菌数可达清洁后的10-50倍；霉菌暴露可增加40%的哮喘风险。","caseRef":"某家庭卫生间长期未深度清洁，瓷砖缝隙大面积发霉，租客出现皮肤过敏症状，深度清洁除霉后症状消失。"},{"id":"SRV-CLN-018","name":"保洁物品损坏赔偿标准","domain":"L3-持有阶段","subScene":"保洁纠纷与权益","scene":"L3-持有阶段·保洁纠纷与权益","cq":"保洁时物品被损坏了怎么赔偿？","ola":"保洁损坏物品按实际价值赔偿，当场拍照留证，联系公司索赔。","cp":["损坏当场拍照通知保洁员","按实际价值向公司索赔","有保险的可走保险理赔"],"detail":"保洁过程中物品损坏是常见纠纷类型，掌握正确的处理流程和赔偿标准有助于维护权益。发现物品损坏后的处理流程：第一步，当场发现——立即拍照（多角度拍摄损坏部位和整体）、录像记录，通知保洁员当场确认并签字，联系保洁公司客服报备。第二步，延迟发现——部分损坏可能在保洁后数小时或数天才发现，应在发现后24-48小时内通知保洁公司并拍照，超时后保洁公司可能拒绝承认。第三步，索赔协商——凭照片、购买凭证、物品价值证明向保洁公司提出赔偿要求。赔偿标准的法律依据：保洁服务属于承揽合同关系，《民法典》第七百七十八条规定承揽人应当妥善保管定作人提供的材料和工作成果，造成损失的应当赔偿。赔偿应按物品实际价值计算——新购物品按购买价格折旧后赔偿，无法提供购买凭证的按市场评估价赔偿。如果保洁公司购买了第三者责任险，可直接走保险理赔。如果保洁公司拒绝赔偿或金额不合理，可向12315投诉、向消费者协会申请调解、向法院起诉。预防措施：保洁前收好贵重物品和易碎品、告知保洁员特殊材质和注意事项、贵重物品区域拍照存证、选择有保险保障的保洁公司。","legalRef":"《民法典》第七百七十八条：承揽人应当妥善保管定作人提供的材料和工作成果，造成毁损灭失的应当赔偿。第一千一百六十五条：行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。","consumerBenefit":"物品损坏后获得合理赔偿，减少财产损失。","tags":{"clientType":["seller","tenant"],"stage":"mid","layer":"fa","meetingPhase":[]},"alias":["保洁损坏赔偿","保洁损坏物品","清洁损坏"],"dataRef":"保洁物品损坏纠纷平均赔偿金额约1200元，通过法律途径获赔率约65%。","caseRef":"某保洁员使用酸性清洁剂擦拭大理石台面导致表面腐蚀泛白，因客户保留了购买凭证（价值3500元），保洁公司全额赔偿。"},{"id":"SRV-CLN-019","name":"保洁不到位处理方式","domain":"L3-持有阶段","subScene":"保洁纠纷与权益","scene":"L3-持有阶段·保洁纠纷与权益","cq":"保洁做完后发现不干净怎么办？","ola":"保洁不合格当场要求返工，已离开的联系公司安排补做或退款。","cp":["当场验收发现问题要求返工","已离开的联系公司补做","严重不合格可要求退款"],"detail":"保洁不到位是消费者最常遇到的问题，处理方式取决于发现时机和问题程度。当场发现（保洁员尚未离开）：立即指出未清洁到位的区域，要求保洁员当场返工补做；保洁员拒绝或返工后仍不满意的，联系保洁公司客服反馈，要求重新安排人员或退款；在服务确认单上注明不满意的项目，不要签署'服务满意'确认。延迟发现（保洁员已离开）：在24-48小时内联系保洁公司反馈问题，发送问题区域照片和视频作为证据；要求免费补做或返工；如拒绝补做，可要求部分退款。保洁不到位的常见问题及处理：死角未清洁（家具背后、橱柜顶部、灯具上方）——要求补做死角清洁；表面有灰尘残留——要求重新擦拭；卫生间厨房清洁不彻底——要求深度补做；玻璃有水痕指纹——要求重新擦拭；垃圾未倾倒——要求立即处理。预防措施：预约时明确服务范围和标准清单、保洁前告知重点清洁区域、保洁过程中适时检查进度、保洁完成后按验收标准逐项检查再签字。如多次投诉仍不改善服务质量，建议更换服务商并在平台留下真实评价。通过平台预约的可使用平台投诉和退款保障机制。","legalRef":"《民法典》第七百七十七条：定作人可以中途变更承揽工作的要求，承揽人因此造成损失的由定作人赔偿。第七百八十一条：承揽人交付的工作成果不符合质量要求的，定作人可以合理选择请求承揽人承担修理、重作、减少报酬、赔偿损失等违约责任。","consumerBenefit":"保洁不到位时获得返工或退款，确保花钱买到合格服务。","tags":{"clientType":["seller","tenant"],"stage":"post","layer":"fa","meetingPhase":[]},"alias":["保洁不干净","清洁不到位","保洁质量差"],"dataRef":"保洁服务投诉中'清洁不到位'占比约45%，是最高发的投诉类型；当场验收并返工的满意度达85%。","caseRef":"某客户保洁后未验收签字，第二天发现多个区域未清洁，联系保洁公司要求返工被拒，因已签字确认'服务满意'无法维权。"},{"id":"SRV-CLN-024","name":"特殊材质清洁纠纷","domain":"L3-持有阶段","subScene":"保洁纠纷与权益","scene":"L3-持有阶段·保洁纠纷与权益","cq":"保洁时特殊材质（大理石、实木等）被损坏怎么办？","ola":"特殊材质需专用清洁剂，保洁前务必告知，损坏按实际价值索赔。","cp":["大理石禁用酸性清洁剂","实木表面禁用酒精强碱","保洁前书面告知注意事项"],"detail":"特殊材质表面的清洁需要专业知识和专用产品，错误的清洁方式可能导致不可逆的损坏，是保洁纠纷中赔偿金额较高的类型。常见特殊材质的清洁禁忌：大理石和人造石——禁用酸性清洁剂（如洁厕灵、醋酸），酸会腐蚀碳酸钙导致表面泛白失去光泽，应使用中性石材专用清洁剂；禁用钢丝球摩擦。实木家具和地板——禁用含酒精的清洁剂（溶解漆面）、禁用大量水浸泡（木材膨胀变形）、禁用钢丝球，应使用微湿抹布和中性木器清洁剂。不锈钢——禁用钢丝球和含氯漂白剂（导致划痕和锈蚀），应使用不锈钢专用清洁剂顺着纹路擦拭。真皮沙发——禁用碱性清洁剂和酒精（导致皮面干裂褪色），应使用皮革专用清洁剂。古董和艺术品——禁用任何化学清洁剂，应由专业人员处理。纠纷处理：保洁前已告知特殊材质注意事项但保洁员仍使用错误方法的，保洁公司应全额赔偿；保洁前未告知的，双方可能分担责任。预防措施：保洁前在特殊材质区域张贴提示标签或口头告知并要求确认、选择有专业培训的保洁公司、贵重特殊材质表面提前拍照存证。赔偿标准：可修复的按维修费用赔偿，不可修复的按物品实际价值赔偿。","legalRef":"《民法典》第七百七十八条：承揽人应当妥善保管定作人提供的材料和工作成果，造成毁损灭失的应当赔偿。第一千一百六十五条：因过错侵害他人民事权益造成损害的应当承担侵权责任。","consumerBenefit":"保护家中特殊材质物品不被错误清洁损坏，损坏后获得合理赔偿。","tags":{"clientType":["seller","tenant"],"stage":"mid","layer":"qi","meetingPhase":[]},"alias":["特殊材质清洁","大理石清洁","实木清洁"],"dataRef":"特殊材质清洁损坏纠纷平均赔偿金额约2500元，其中大理石和实木家具损坏占比最高。","caseRef":"某保洁员用洁厕灵清洁大理石台面导致大面积腐蚀泛白，维修费用5000元，因客户保洁前已口头告知且保洁员签字确认，保洁公司全额赔偿。"},{"id":"P1-B4-002","name":"换购住房退个税政策怎么用","domain":"市场数据","subScene":"购房·贷款办理","scene":"市场数据·购房·贷款办理","cq":"换房子能退个税是真的吗？","ola":"卖房后1年内买房，个税全退","cp":["同一城市1年内","新购≥售房全额退","新购<售房按比例退","先缴后退","有效期至2025年底"],"detail":"换购住房退个税政策：出售自有住房后1年内在同一城市重新购买住房的，可全额退还出售住房时缴纳的个人所得税。退税条件：①出售和购买必须在同一城市 ②出售与购房时间间隔不超过1年 ③新购住房金额≥售房金额→全额退税；新购金额<售房金额→按比例退税（新购金额/售房金额×已缴个税）。操作流程：①售房时先正常缴纳个税 ②购房后向税务机关申请退税 ③提供售房合同、购房合同、完税证明等材料。","legalRef":"《财政部 税务总局关于支持居民换购住房有关个人所得税政策的公告》2023年第28号","consumerBenefit":"换房可退数万个税，降低换房成本","tags":{"clientType":["buyer","seller"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["换购住房退税","换房退个税","卖房买房退税"],"dataRef":"退税金额=已缴个税×(新购金额/售房金额)，最高全额退还"},{"id":"P1-H3-001","name":"租金回报率怎么算才准","domain":"跨域通用","subScene":"购房·资产管理","scene":"跨域通用·购房·资产管理","cq":"房子出租的回报率怎么算？","ola":"净回报率=（年租-支出）/总价，二线2.5-4%为合理","cp":["毛回报率不含支出","净回报率扣支出","一线1.5-2.5%","二线2.5-4%","要算空置损失"],"detail":"租金回报率计算：①毛租金回报率=年租金/房屋总价×100%（不含支出） ②净租金回报率=（年租金-年支出）/房屋总价×100%（支出含物业费/维修/空置损失/房产税） ③参考标准：一线城市1.5-2.5%，二线城市2.5-4%，三线城市4-6%。投资判断：回报率>银行理财（约3%）→可考虑持有；回报率<3%→依赖增值收益。","legalRef":"《中华人民共和国城市房地产管理法》第三十二条（房地产转让/抵押时房屋所有权与土地使用权同时处分）","consumerBenefit":"算清真实回报率，决定该不该买/该不该持有","tags":{"clientType":["buyer","landlord"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["租金回报率","租金收益率","租售比"],"dataRef":"杭州2024年平均租金回报率约2.0-2.5%（中国房价行情网数据）"},{"id":"P1-B4-001","name":"房贷利息抵扣个税怎么操作","domain":"市场数据","subScene":"购房·贷款办理","scene":"市场数据·购房·贷款办理","cq":"房贷利息能抵个税吗？怎么操作？","ola":"首套房贷利息每月抵1000元个税，最长240月","cp":["每月扣1000元","最长240个月","仅首套房","个税APP操作","夫妻只能选一方"],"detail":"首套住房贷款利息可享受个人所得税专项附加扣除，标准为每月1000元，最长扣除期限240个月。操作流程：①在\"个人所得税\"APP中选择\"专项附加扣除填报\"②选择\"住房贷款利息\"③填写贷款合同编号、贷款银行、贷款类型、首次还款日期等信息 ④选择扣除方式（独生子女/非独生子女分摊）⑤选择申报方式（通过单位预扣或年度汇算清缴）。注意：只能享受一套首套房贷利息扣除；必须是贷款购买的首套住房；","legalRef":"《中华人民共和国个人所得税法》第六条；《个人所得税专项附加扣除暂行办法》国发〔2018〕41号第十四条","consumerBenefit":"每年省下数千元个税，买房的隐性福利","tags":{"clientType":["buyer"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["房贷利息抵税","房贷个税扣除","住房贷款利息扣除"],"dataRef":"每月1000元扣除额，按最高税率45%计算年省5400元"},{"id":"P1-H3-002","name":"持有房子的隐性成本有哪些","domain":"跨域通用","subScene":"购房·资产管理","scene":"跨域通用·购房·资产管理","cq":"养一套房子除了月供还要花多少钱？","ola":"物业+维修+资金成本+空置+交易，年隐性成本3-5%","cp":["物业费年2400-6000","维修年0.5-1%","资金机会成本","空置月损失","出售交易成本5-8%"],"detail":"持有房产的隐性成本清单：①物业费→2-5元/㎡/月（100㎡房子年2400-6000元） ②房产税→目前仅重庆/上海试点，但需关注政策走向 ③折旧维修→年均房价的0.5-1%（老旧房屋更高） ④资金成本→首付+已还贷款的利息机会成本（如果没买房存银行的收益） ⑤空置成本→出租空置1个月=损失1个月租金+物业费 ⑥交易成本→未来出售时契税+个税+中介费约占房价5-8% ⑦保险→房屋财产险（可选...","legalRef":"《中华人民共和国房产税暂行条例》国发〔1986〕90号","consumerBenefit":"算清持有成本，不被\"买房必赚\"的幻觉误导","tags":{"clientType":["buyer","landlord"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["持有成本","房产隐性成本","养房成本"],"dataRef":"持有成本约占房价3-5%/年（含资金机会成本）"},{"id":"P1-H1-001","name":"房屋托管给中介要注意什么","domain":"跨域通用","subScene":"购房·资产管理","scene":"跨域通用·购房·资产管理","cq":"房子交给中介托管有什么风险？","ola":"查资质+拒高收低租+拒租金贷+不交房产证原件","cp":["查验营业执照+备案","警惕高收低租","拒绝租金贷","只给复印件不交原件","每季度巡查"],"detail":"房屋托管风险防范要点：①选机构→查验营业执照+备案证明+实际经营地址，优先选品牌长租机构 ②合同条款→明确托管期限/租金支付方式（按月/季）/维修责任划分/违约责任/提前解约条件 ③警惕\"高收低租\"→中介以高于市场价收房、低于市场价出租，资金链断裂跑路风险极高 ④拒绝\"租金贷\"→中介诱导租客办贷款一次性付清全年租金，中介卷款跑路后租客既被赶还在还贷 ⑤保留权证→不交房产证原件，只提供复印件 ...","legalRef":"《住房租赁条例》（国务院令第730号）第六条、第十五条；《中华人民共和国民法典》第七百一十六条","consumerBenefit":"托管省心但要防坑，避免\"租金没收到房子还被占\"","tags":{"clientType":["landlord"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["房屋托管","房子托管给中介","长租公寓托管"],"dataRef":"2020-2022年多家长租公寓暴雷（如蛋壳公寓），房东租客双受损"},{"id":"P1-B1-002","name":"LPR利率怎么选浮动还是固定","domain":"市场数据","subScene":"购房·贷款办理","scene":"市场数据·购房·贷款办理","cq":"房贷利率选浮动还是固定好？","ola":"降息选浮动锁收益，加息选固定防风险","cp":["LPR定价机制","浮动vs固定利率","每年1月1日重定价","降息周期选浮动","长贷选浮动更优"],"detail":"LPR（贷款市场报价利率）定价方式下，借款人可选择浮动利率或固定利率。浮动利率随LPR调整，每年1月1日按最新LPR重新定价；固定利率在贷款期限内不变。选择逻辑：①处于降息周期→选浮动利率，月供可能减少 ②处于加息周期→选固定利率，锁定低利率 ③贷款期限短（5年内）→差异不大，选固定更省心 ④贷款期限长（20-30年）→浮动利率长期可能更优，但需承受利率波动风险。","legalRef":"《中国人民银行公告〔2019〕第30号》关于存量浮动利率贷款定价基准转换","consumerBenefit":"选对利率方式，30年贷款可能省数万利息","tags":{"clientType":["buyer"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["LPR利率","浮动利率","固定利率"],"dataRef":"2024年5年期以上LPR为3.95%（中国人民银行官网2024年数据）"},{"id":"P1-B2-001","name":"公积金能贷多少额度怎么算","domain":"市场数据","subScene":"购房·贷款办理","scene":"市场数据·购房·贷款办理","cq":"公积金能贷多少怎么算？","ola":"余额倍数×月缴存×房价比例×封顶额，取最低","cp":["余额15-30倍","月缴存额推算","房价70-80%","当地封顶额度","每家庭限用两次"],"detail":"公积金贷款额度计算方式：①按账户余额倍数：各地不同，一般为余额的15-30倍 ②按月缴存额：月缴存额×剩余工作年限×12×一定系数 ③按房价比例：最高贷款比例一般为房价的70-80% ④当地封顶额度限制（如杭州单人最高50万，家庭最高100万；北京单人最高120万）。最终贷款额度取以上四项最低值。注意：公积金贷款次数有限制，一个家庭最多使用两次；首套利率2.85%，二套3.325%。","legalRef":"《住房公积金管理条例》第二十六条；各地住房公积金管理中心贷款办法","consumerBenefit":"用足公积金低息贷款额度，省下数万利息","tags":{"clientType":["buyer"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["公积金贷款额度","公积金贷款计算","公积金可贷额度"],"dataRef":"杭州单人最高50万家庭100万；北京单人最高120万（各地公积金中心2024年标准）"},{"id":"P1-B2-002","name":"公积金和商业贷款组合贷怎么做","domain":"市场数据","subScene":"购房·贷款办理","scene":"市场数据·购房·贷款办理","cq":"公积金贷款不够怎么办？","ola":"公积金不够就用组合贷，利率综合最低","cp":["先审公积金额度","差额走商贷","同时审批同时放款","审批多2-4周","部分卖家不接受"],"detail":"组合贷即公积金贷款+商业贷款组合使用，适用于公积金贷款额度不够覆盖房款的情况。操作流程：①先向公积金中心申请公积金贷款额度审批 ②公积金额度确定后，差额部分向商业银行申请商业贷款 ③两笔贷款同时审批、同时放款 ④分别按各自利率还款。注意：组合贷审批周期比纯商贷长2-4周；部分开发商或卖家不接受组合贷（因放款慢）；公积金部分利率2.85%，商贷部分按LPR定价，可有效降低综合利率。","legalRef":"《住房公积金管理条例》第二十六条；《个人住房组合贷款管理办法》","consumerBenefit":"组合贷比纯商贷省20-30%利息，降低月供压力","tags":{"clientType":["buyer"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["组合贷","公积金商贷组合","组合贷款"],"dataRef":"组合贷综合利率约3.5-4.2%，比纯商贷低0.5-1个百分点"},{"id":"P1-H2-001","name":"整装和自装怎么选","domain":"跨域通用","subScene":"购房·整装服务","scene":"跨域通用·购房·整装服务","cq":"装修选整装好还是自己装好？","ola":"忙人选整装省心，懂行选自装省钱，折中选半包","cp":["整装省心贵15-30%","自装省钱费时","半包折中方案","整装工期60-90天","关键看时间和经验"],"detail":"整装（全包）vs自装（清包）对比：整装优势→省时省心、统一质保、设计施工一体化、工期可控（一般60-90天）；整装劣势→总价比自装高15-30%、材料选择受限、需选择靠谱公司。自装优势→成本可控、材料自选、可分步施工；自装劣势→耗时耗力（需频繁跑工地）、需懂行否则容易踩坑、无统一质保。","legalRef":"《住宅室内装饰装修管理办法》建设部令第110号","consumerBenefit":"选对装修方式省心又省钱，避免装修踩坑","tags":{"clientType":["buyer"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["整装","全包","自装"],"dataRef":"整装均价800-1500元/㎡（杭州2024年中端市场数据）"},{"id":"P1-H2-002","name":"装修预算怎么分配不超支","domain":"跨域通用","subScene":"购房·整装服务","scene":"跨域通用·购房·整装服务","cq":"装修预算怎么分配不会超支？","ola":"施工35%+主材30%+家具20%+软装5%+备用金10%","cp":["施工占35-40%","主材占30-35%","预留10%备用金","水电最易超支","签闭口合同防增项"],"detail":"装修预算分配建议（以100㎡为例，总预算10-15万）：①基础施工（拆改+水电+泥瓦+木工+油漆）占35-40% ②主材（瓷砖/地板/门窗/橱柜/卫浴）占30-35% ③家具家电占20-25% ④软装配饰占5-10% ⑤预留10%备用金应对增项。控制超支关键：①签合同时明确\"闭口合同\"（无增项）或限定增项比例 ②提前确定所有主材型号价格 ③水电改造按实计费要提前预估上限 ④避免施工中被劝升级材料。","legalRef":"《建筑装饰装修工程质量验收标准》GB50210-2018","consumerBenefit":"科学分配预算，装修不超支不返工","tags":{"clientType":["buyer"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["装修预算","装修费用","装修预算分配"],"dataRef":"杭州2024年中端整装均价800-1500元/㎡"},{"id":"P1-H2-004","name":"装修监理请不请值不值","domain":"跨域通用","subScene":"购房·整装服务","scene":"跨域通用·购房·整装服务","cq":"装修要不要请监理？值不值？","ola":"预算超15万建议请，水电验收最关键","cp":["监理费20-50元/㎡","水电验收最重要","预算超15万建议请","自装强烈建议请","可选关键节点验收"],"detail":"装修监理是第三方专业人员代表业主监督施工质量。监理服务内容：①水电隐蔽工程验收（管线走向、接头处理、打压测试）②泥瓦工验收（空鼓率、平整度、坡度）③木工验收（垂直度、接缝）④油漆验收（色差、流坠）⑤竣工验收。费用参考：按面积收费20-50元/㎡，或按次收费每次500-2000元。","legalRef":"《建设工程监理规范》GB/T50319-2013","consumerBenefit":"花小钱防大坑，监理费远低于返工损失","tags":{"clientType":["buyer"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["装修监理","装修监理费用","装修要不要请监理"],"dataRef":"监理费20-50元/㎡，返工损失动辄数千上万"},{"id":"P1-G3-001","name":"装修材料环保等级怎么认","domain":"跨域通用","subScene":"购房·整装服务","scene":"跨域通用·购房·整装服务","cq":"装修材料环保等级怎么看？","ola":"认准E0/ENF级+十环认证，看检测报告不看广告","cp":["E1国标最低","E0推荐标准","ENF最高标准","看检测报告","入住前通风3-6月"],"detail":"装修材料环保等级：板材看甲醛释放量→E1级（≤0.124mg/m³）为国标最低要求，E0级（≤0.050mg/m³）为推荐标准，ENF级（≤0.025mg/m³）为最高标准。油漆看VOC含量→水性漆优于油性漆，VOC≤120g/L为合格。","legalRef":"《室内装饰装修材料人造板及其制品中甲醛释放限量》GB18580-2017；《民用建筑工程室内环境污染控制标准》GB50325-2020","consumerBenefit":"环保材料保护家人健康，入住安心","tags":{"clientType":["buyer"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["装修环保","环保等级","甲醛标准"],"dataRef":"室内甲醛国标≤0.08mg/m³（GB50325-2020）"},{"id":"P1-G3-002","name":"水电改造有哪些坑要避","domain":"跨域通用","subScene":"购房·整装服务","scene":"跨域通用·购房·整装服务","cq":"水电改造有哪些坑？","ola":"预估封顶+进场验材料+打压测试，三大保命动作","cp":["报价约定上限","材料进场验收","强弱电分管150mm间距","全屋用热水管","打压测试0.8MPa"],"detail":"水电改造常见坑：①报价低后期加钱→按实计费不封顶，建议签合同时约定预估上限 ②材料偷换→合同写品牌型号，进场验收拍照 ③管线走法不合理→横平竖直看似好看但费钱，点对点更省材料 ④强弱电同管→信号干扰，必须分管且间距≥150mm ⑤插座数量不够→建议客厅6-8个、厨房6-8个、卧室4-6个 ⑥水管没用热水管→全屋用PPR热水管（壁厚更厚），冷水管价格差异不大 ⑦没做打压测试→水管焊好后必须0....","legalRef":"《建筑给水排水及采暖工程施工质量验收规范》GB50242-2002；《建筑电气工程施工质量验收规范》GB50303-2015","consumerBenefit":"水电改造不踩坑，避免返工数万损失","tags":{"clientType":["buyer"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["水电改造","水电改造坑","水电改造注意事项"],"dataRef":"水电改造超支率30-50%为行业常态"},{"id":"P1-G3-004","name":"卫生间装修防水怎么做才保险","domain":"跨域通用","subScene":"购房·整装服务","scene":"跨域通用·购房·整装服务","cq":"卫生间防水怎么做才不会漏？","ola":"淋浴区1.8m+涂刷2-3遍+闭水48小时+门槛石先贴","cp":["淋浴区防水≥1.8m","柔性防水涂2-3遍","管根做附加层","闭水48小时","门槛石先贴防窜水"],"detail":"卫生间防水是装修最关键环节，漏水返工代价巨大。标准做法：①防水高度→淋浴区墙面防水≥1.8m（建议做到顶），其他墙面≥0.3m ②防水材料→聚合物水泥防水涂料（柔性防水），涂刷2-3遍，每遍干透再刷下一遍 ③重点部位→管根/地漏/阴阳角先做附加层（网格布增强） ④闭水试验→防水干透后蓄水≥3cm深，保持48小时无渗漏为合格 ⑤门槛石→先贴门槛石再做防水，防水层上翻至门槛石外侧防止\"窜水\" ⑥...","legalRef":"《住宅室内防水工程技术规范》JGJ 298-2013","consumerBenefit":"防水做好一次到位，避免漏水赔楼下数万元","tags":{"clientType":["buyer"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["卫生间防水","防水做法","闭水试验"],"dataRef":"卫生间漏水返工费用5000-20000元（含楼下赔偿）"},{"id":"CRO-GEN-005","name":"首购人群和改善人群买房有什么不同","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我是第一次买房，和换房的人看的东西一样吗","ola":"首购看总价通勤改善看品质空间","cp":["首购关注总价和通勤","改善关注品质和空间","首购需流程引导风控提示","改善需税费测算时序规划"],"detail":"首购人群预算有限、缺乏经验，最关注总价可控和通勤便利；改善人群有房产经验、预算更宽裕，更关注品质提升和空间升级。经纪人需区分两类客户的核心诉求差异，首购侧重风险提示和流程引导，改善侧重税费测算和卖旧买新时序规划。","legalRef":"行业通行做法","consumerBenefit":"不走弯路，首套房买得明白","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["首套房和二套房区别","首购和改善区别","首次置业有什么不同"]},{"id":"CRO-GEN-008","name":"为了孩子上学买房怎么选","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"为了孩子上学，学区房怎么选才靠谱","ola":"学位占用户口年限划片政策逐项核","cp":["核实对口学校是否稳定","确认学位未被占用","户口迁入年限要满足","多校划片政策需确认"],"detail":"学区置业需核实对口学校是否稳定、学位是否被占用、户口迁入是否满足年限要求、多校划片政策是否已落地。经纪人需提醒客户学区政策每年可能调整，签约前必须到教育局或学校核实当年招生范围和入学条件。","legalRef":"《义务教育法》第12条","consumerBenefit":"买到真正能入学的学区房","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["道"],"meetingPhase":["见前"]},"alias":["学区房怎么选","买房为了上学","学区房选购要点"]},{"id":"CRO-GEN-009","name":"养老住房怎么选","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"给父母买养老房，怎么选合适","ola":"电梯低层医疗配套生活便利物业安全","cp":["电梯低楼层优先选择","医疗配套步行可达","生活便利是硬需求","物业安全服务要到位"],"detail":"养老住房需优先考虑无障碍通行（电梯低楼层）、医疗配套（社区医院三甲距离）、生活便利（菜场超市步行可达）、社区安全（物业24小时值守）。经纪人应关注适老化细节，如卫生间干湿分离、门口无门槛、楼道扶手等。","legalRef":"行业通行做法","consumerBenefit":"老人住得安全方便，子女放心","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["养老房怎么选","老人住什么房子好","适老化住房"]},{"id":"CRO-GEN-011","name":"二胎家庭换房怎么规划","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"二胎了，想换个更大的房子怎么规划","ola":"三居收纳学区衔接资金缺口先算好","cp":["至少三居室才够住","收纳和活动空间要足","两个孩子的学区衔接","换房资金缺口先算清"],"detail":"多孩家庭换房需重点规划卧室数量（至少三居）、收纳空间（儿童用品多）、学区连续性（两个孩子间隔入学）、活动空间（客厅面积优先）。经纪人需帮客户测算换房资金缺口，评估卖旧买新的时间窗口与学区衔接风险。","legalRef":"行业通行做法","consumerBenefit":"两个孩子都有空间，学区不断档","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["二胎换房怎么选","多孩家庭换房","二胎住房需求"]},{"id":"PRE-NEED-076","name":"改善型换房和刚需买房有什么区别","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我是换房改善，和第一次买房有什么不一样的？","ola":"改善更重品质但贷款利率高，必须算好卖旧买新衔接","cp":["刚需敏感总价改善关注品质","二套贷款利率高首付比例高","刚需关注流通性改善关注自住","刚需通勤导向改善可能不在意","改善需计算卖旧买新资金衔接"],"detail":"改善型购房与刚需购房的核心差异在于：刚需客户最敏感的是总价和首付，改善客户更关注户型面积和居住品质；刚需客户通常首套房贷款利率低、首付比例低，改善客户二套贷款利率高、首付比例高；刚需客户对流通性关注度高（未来可能再换），改善客户更看重自住体验；刚需客户多为通勤导向，改善客户可能已不在意通勤距离。改善换房需特别计算卖旧买新的资金衔接。","legalRef":"《中华人民共和国民法典》第1062条","consumerBenefit":"理解改善购房的独有挑战，不做错误的财务规划","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["改善和刚需购房差异","二套房和首套购房区别","改善购房策略和刚需不同吗"]},{"id":"CRO-GEN-006","name":"结婚买房怎么选","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我们准备结婚，婚房怎么选","ola":"通勤生育空间出资产权四点先谈清","cp":["兼顾双方通勤距离","预留未来生育空间","明确出资与产权关系","月供不超过家庭收入一半"],"detail":"婚房选购需兼顾双方通勤、未来生育空间、双方家庭出资份额、产权登记方式等核心要素。经纪人需引导新人明确预算上限（含婚后月供压力），预判3-5年家庭变化对空间的需求，并提前沟通产权登记与出资证明的关联。","legalRef":"行业通行做法","consumerBenefit":"婚房选得合适，减少婚后矛盾","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["婚房怎么选","结婚买房看什么","婚房选购建议"]},{"id":"CRO-GEN-077","name":"买学区房最怕遇到什么政策变化","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"为了孩子上学买了高价学区房，万一政策变了岂不是亏大了？","ola":"警惕多校划片、学区重划及落户年限要求等政策调整。","cp":["多校划片打破单校对口","学区范围面临重新划分","入学顺位看重落户年限","教师轮岗稀释名校优势"],"detail":"学区房受教育资源均衡化政策影响极大。主要风险包括：多校划片导致买房后无法进入对口名校、学区范围重新划分被划出名校片区、教师轮岗制度削弱名校师资优势、以及入学顺位调整（如要求实际居住年限）导致有房无户或新购房被调剂。","legalRef":"各地教育行政部门招生政策","consumerBenefit":"认清学区房的政策不确定性，理性评估溢价风险，避免盲目追高。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"术","meetingPhase":["见中","见前"]},"alias":["学区房政策风险","多校划片对学区房影响","学区划分变了怎么办"]},{"id":"PRE-MATCH-096","name":"学区房学位占用怎么查","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"怎么确认学区房的学位没被占用？","ola":"到学校查，写入合同保证学位可用","cp":["到学校/教育局查学位占用","问前业主子女是否在读","部分城市6年一个学位","签约前确认写入合同"],"detail":"学位占用是学区房的核心风险。查询方法：①到对口学校教务处/教育局查询该房产学位是否被占用；②问前业主子女是否在对口学校就读及毕业年份；③查当地'学位锁定'政策（部分城市一套房6年内只提供一个学位）。学位被占用意味着买入后子女无法入学，学位价值为零。务必在签约前确认学位可用，写入合同补充条款。","legalRef":"各地义务教育招生入学政策学位锁定规则","consumerBenefit":"学位不落空钱不白花","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["学位占用怎么确认","前业主孩子还在上学怎么办","学位几年释放"]},{"id":"PRE-NEED-018","name":"换房改善怎么规划最划算","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我想把现在的房子卖掉换大的，怎么操作最划算？","ola":"看首付充裕度和旧房好不好卖，同城市可退个税","cp":["先买后卖担两份月供风险","先卖后买怕过渡期涨价","首付充裕度决定路径选择","同城市换购可退个税","旧房流通性是关键变量"],"detail":"改善换房分两种路径：先买后卖（有足够首付先买新房再卖旧房）和先卖后买（先卖旧房回笼资金再买新房）。先买后卖风险在于旧房滞销导致同时承担两套房贷；先卖后买风险在于过渡期无房住且房价可能上涨。选择路径的关键看：首付充裕度、旧房市场流通性、过渡期住房安排。卖旧买新在同一城市可申请换购住房个税退税（延续至2027年12月31日）。","legalRef":"《关于延续实施全年一次性奖金个人所得税政策的公告》（财政部 税务总局2023年）；换购住房个税退税政策延续至2027.12.31","consumerBenefit":"选对路径省利息省税费，不两头受压","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["改善型购房策略","卖旧买新流程","置换买房怎么操作"]},{"id":"PRE-NEED-020","name":"给爸妈买房要注意什么","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"想给爸妈买套房子，要注意哪些问题？","ola":"选低楼层近医院，注意贷款年限和产权归属","cp":["优选低楼层带电梯","3公里内需有医院","人车分流无障碍通道","贷款年限受年龄限制","署名与继承要提前规划"],"detail":"给父母购房需关注适老性四大维度：楼层（优选带电梯的低楼层，1-3层最佳）、医疗配套（3公里内有三甲医院或社区卫生中心）、社区环境（人车分流、无障碍通道、适老活动空间）、户型（卫生间干湿分离且干区靠近卧室、避免台阶和门槛）。需注意：产证署名与继承安排、老人独立购房的贷款年限受年龄限制（贷款年限+年龄≤65-70岁）、部分城市对老年购房者有税费优惠。","legalRef":"《中华人民共和国民法典》第1127条（法定继承顺序）；《老年人权益保障法》第13条","consumerBenefit":"让父母住得安全方便，产权安排不留纠纷","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["老人购房注意","给父母买房要点","适老住宅标准"]},{"id":"PRE-NEED-090","name":"买学区房要注意什么","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我想买学区房，怎么确保孩子一定能上学？","ola":"查落户年限、学位占用、对口校近3年名单","cp":["核实对口学校稳定性","查落户年限要求","确认学位未被占用","警惕学区政策调整风险"],"detail":"学区房核心风险在于政策变动导致学区失效。需核实四要素：①学区对口学校是否稳定（查近3年入学名单）；②落户年限要求（热门校通常要求落户满2-5年）；③学位是否被占用（前业主子女是否在读）；④学区政策是否面临调整风险。购买前务必到教育局或学校招生办现场确认，不可仅听中介口头承诺。","legalRef":"《义务教育法》第12条就近入学原则；各地学区划分政策","consumerBenefit":"孩子入学有保障，钱不白花","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["学区房怎么买","学区房避坑指南","学区房入学条件"]},{"id":"PRE-SCH-005","name":"怎么查学区名额有没有被占用","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买学区房怎么确认学位没有被前业主占用？","ola":"到辖区教育局或学校查学位使用记录，签约前必须查","cp":["教育局窗口查询最权威","部分学校不对外查询","部分城市支持线上查","签约前必须核验非过户后","发现占用可要求降价或解约"],"detail":"学位占用核验的四种方法：①辖区教育局——持房产证或购房合同到教育局学籍管理窗口查询（最权威）②对口学校——直接联系学校教务处查询（部分学校不对外查询）③教育局官网/APP——部分城市支持线上查询（如北京「入学服务平台」）④中介协助——部分品牌中介提供学位核验服务。核验内容：学位是否在使用中、学位使用起始时间、预计释放时间。必须核验的时间点：签约前而非过户后，发现占用可要求卖方降价或解除合同。","legalRef":"各城市教育局学位管理办法；《中华人民共和国民法典》第500条（缔约过失责任）","consumerBenefit":"不买学位被占的学区房，孩子入学有保障","tags":{"clientType":["buyer"],"stage":"pre","layer":["法","道"],"meetingPhase":["见前"]},"alias":["学位占用查询方法","前业主孩子还在上学吗","学位核验去哪里查"]},{"id":"PRE-SCH-007","name":"户口没迁过来孩子能上学吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"我买了学区房但户口还没迁过来，孩子能上对口学校吗？","ola":"不能优先入学，人户一致才第一顺位，买了必须迁户口","cp":["入学要求人户一致","有房无户顺位靠后可能被统筹","人户一致且父母房产为第一顺位","购学区房后必须迁孩子户口","迁户需在入学前1年完成"],"detail":"多数城市小学入学要求「人户一致」——适龄儿童户籍与房产地址一致才能优先入学。户口不在学区的后果：顺位靠后甚至无法入学，有户无房的优先于有房无户的。入学顺位一般排列：①人户一致且房产为父母所有（第一顺位）②人户一致但房产为祖辈所有（第二顺位）③有房无户（第三顺位，可能被统筹到其他学校）④有户无房（集体户/挂靠户）。购买学区房后必须及时将孩子户口迁入学区地址，否则买了也上不了对口学校。","legalRef":"《义务教育法》第12条；各城市义务教育阶段招生入学工作实施意见","consumerBenefit":"买了学区房不忘迁户口，孩子入学不落空","tags":{"clientType":["buyer"],"stage":"pre","layer":["术","道"],"meetingPhase":["见前"]},"alias":["户口不在学区能入学吗","人户一致要求","户口与学区入学关系"]},{"id":"PRE-SCH-010","name":"前业主户口不迁走影响孩子上学吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"前业主户口没迁走，影响我家孩子上学吗？","ola":"学位可能被占6年锁定，户口占用影响顺位，必须约定迁出","cp":["学位被前业主子女占用6年锁定","户口占用可能影响迁入和顺位","合同约定迁出时限和违约金","预留5-10万户口保证金","签约前到派出所查户籍底档"],"detail":"前业主户口不迁走对学区的影响取决于两点：①学位是否被占用——如果前业主子女正在对口学校就读，学位被锁定六年，你的孩子无法入学②户口占用——即使前业主子女已毕业，户口仍挂在该地址可能影响你的迁入和入学顺位。部分城市规定同一地址下不能同时有两个入学适龄儿童的户口，前业主户口在可能导致你的户口迁入受阻。必须在购房合同中约定户口迁出时限和逾期违约金，预留户口保证金。","legalRef":"《户口登记条例》第10条；《中华人民共和国民法典》第577条（违约责任）；各城市入学顺位规定","consumerBenefit":"不买户口遗留的学区房，孩子入学不受影响","tags":{"clientType":["buyer"],"stage":"pre","layer":["术","道"],"meetingPhase":["见前"]},"alias":["遗留户口占用学区名额","原业主户口在影响入学吗","户口不迁学位被占"]},{"id":"PRE-SCH-029","name":"前业主户口不迁走孩子能上对口学校吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"前业主的户口还没迁走，我孩子还能上这个学校吗？","ola":"可能占学位影响入学，合同必须约定迁出期限和违约金","cp":["前业主户口不迁可能占用学位","六年一学位下6年内只提供一个学位","合同约定户口迁出期限和违约金","部分城市可向公安机关申请强迁","签约前必须查学区名额使用情况"],"detail":"前业主户口未迁出可能导致学区名额被占用，影响买家子女入学。六年一学位政策下，一个房产地址6年内只提供一个入学学位，前业主子女如在使用该学位，买家子女将无法对口入学。处理方式：一是签约前核实户口迁出条款并设定违约金；二是在合同中约定户口迁出期限和逾期违约金（通常按日万分之五计算）；三是向公安机关申请强制迁移（部分城市支持）；四是向法院起诉要求承担违约责任。签约前务必要求经纪人查询学区名额使用情况。","legalRef":"《中华人民共和国户口登记条例》第10条；各地户籍管理规定","consumerBenefit":"合同保障户口迁出，孩子入学不受前业主影响","tags":{"clientType":["buyer"],"stage":"pre","layer":["道"],"meetingPhase":["见前"]},"alias":["前业主户口在影响上学吗","户口不迁出学区名额占用","原房主户口不迁怎么办"]},{"id":"PRE-NEED-139","name":"给父母买房怎么确认是不是真正的养老需求？（PRE-NEED）","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"给父母买房，怎么挑到真正适合养老的房子？","ola":"养老房首看医疗配套和适老化设施，而非商业地铁。","cp":["医疗配套是核心","低楼层与无障碍","环境安静避喧嚣","考察小区适老设施","避免按刚需标准推荐"],"detail":"情境：客户为父母买房，但要求周边有大型商业和地铁。判断依据：真正的养老需求首要考虑医疗配套、低楼层、无障碍设施和安静环境。行动建议：经纪人需带看时重点考察医院距离和小区适老化设施。风险提示：若按普通刚需推荐，会忽略医疗和适老化细节，导致父母居住不适。","legalRef":"《老年人权益保障法》相关配套政策及行业惯例","consumerBenefit":"为父母选到真正宜居的养老房，提升晚年生活质量。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["养老购房需求怎么识别","买养老房要注意什么","怎么判断客户是养老购房"]},{"id":"PRE-NEED-152","name":"养老购房适老化评估","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"给父母买房怎么判断房子适不适合老人住","ola":"5项评估：楼层加卫生间加地面加动线加安全设施","cp":["优选低楼层带电梯","卫生间坐便优于蹲便","地面无高差防滑","卧卫距离短通道宽"],"detail":"为父母购房5项适老化评估：楼层（优选带电梯低楼层1-3层，无电梯必须1楼）；卫生间（坐便器优于蹲便，有无加装扶手条件，干湿分离情况）；地面（有无高差/门槛，材质是否防滑）；动线（卧室到卫生间距离是否短，通道是否宽敞大于等于900mm）；安全设施（有无烟雾报警器，入户门是否可换智能锁）。住建部47项改造要点作为评估基准。","legalRef":"住建部《城市居家适老化改造指导手册》；《无障碍环境建设法》第26条","consumerBenefit":"买房时就能判断适老程度，不买完再后悔","tags":{"clientType":["agent","buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["养老房适老评估","给父母买房评估","适老购房5项评估"]},{"id":"P2-C1-014","name":"学位被占用了还能入学吗","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"如果买的房子学位已经被占用了，孩子还能上学吗？","ola":"仍可入学，但可能改为统筹安排。","cp":["仍可申请入学","可能改为多校划片统筹","不保证对口学校入学"],"detail":"学位被占用不影响孩子接受义务教育的权利，仍可申请入学，但入学方式可能发生变化。以海淀区2026年优化政策为例，学位被占用的房产仍可申请入学，但方式从单校划片改为多校划片统筹安排。这意味着孩子可能被分配到周边其他学校，而非原对口学校。购房前务必核实学位状态。","legalRef":"各地义务教育招生入学实施细则（学位统筹安排）","consumerBenefit":"了解学位占用后的入学安排，做好备选准备。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["学位被占用还能上学吗","学位已用完怎么入学","房子学位被占影响入学吗"]},{"id":"OWN-LND-020","name":"房子委托给谁出租好","domain":"业主资产","subScene":"委托托管与维修责任","scene":"业主资产·委托托管与维修责任","cq":"房东问：房子想委托出去出租，找中介还是托管公司？","ola":"中介促签vs托管包租，按需选择。","cp":["中介仅促签收佣金","托管包租省心但有空置期","选正规公司签书面协议"],"detail":"委托出租有两种模式：一是中介居间模式，中介仅提供租客信息并促成签约，收取一次性佣金，房东自行管理后续；二是托管包租模式，租赁公司按月支付固定租金，负责招租和管理，但通常要求1-2个月空置期和低于市场价的包租租金。选择时需评估自身管理能力和时间精力。建议选择正规有资质的租赁企业，签订书面委托协议明确服务内容、费用标准和责任划分。警惕高收低租等风险模式。","legalRef":"《中华人民共和国民法典》第九百一十九条（委托合同）","consumerBenefit":"帮房东选择合适的委托出租方式。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["房子委托出租","委托中介出租","房屋托管出租"]},{"id":"CRO-GEN-007","name":"换大房子要考虑什么","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"想换个大点的房子，要注意什么","ola":"卖买时序贷款政策税费过渡期四件先算清","cp":["先卖后买vs先买后卖","二套房贷款首付比例更高","卖旧房税费不能忽略","过渡期居住需提前安排"],"detail":"改善换房涉及卖旧买新的时序安排、二套房贷款政策、税费差异（增值税个税契税）、过渡期居住方案等关键问题。经纪人需帮客户评估先卖后买还是先买后卖的资金链风险，测算两套交易的税费和贷款差异。","legalRef":"行业通行做法","consumerBenefit":"换房资金链不断，税费不冤枉","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["改善换房注意什么","换房怎么操作","改善型购房"]},{"id":"CRO-GEN-021","name":"怎么看小区品质高低","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"这个小区品质怎么样怎么看","ola":"物业绿化安防设施居民车位六维看","cp":["物业服务：响应速度专业度","绿化景观：覆盖率维护水平","安防系统：门禁监控巡逻","车位配比：充足且可租可买"],"detail":"小区品质评估从物业服务（响应速度专业度）、绿化景观（覆盖率维护水平）、公共设施（电梯健身房儿童区）、安防系统（门禁监控巡逻）、居民素质（邻里关系租客比例）、车位配比（是否充足可租可买）六个维度综合判断。","legalRef":"行业通行做法","consumerBenefit":"选到品质好的小区，住得安心保值","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["法"],"meetingPhase":["见前"]},"alias":["小区品质怎么看","小区好坏判断标准","小区档次怎么看"]},{"id":"LIV-DEC-074","name":"装修风格怎么选适合自己","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修风格怎么选适合自己","ola":"现代简约维护简单适合上班族","cp":["现代简约维护简单适合上班族","北欧风适合小户型温馨自然","新中式适合中年家庭","选风格看生活方式和预算","风格和面积预算要匹配"],"detail":"常见风格：①现代简约维护简单适合上班族；②北欧风温馨自然适合小户型；③新中式沉稳有底蕴适合中年家庭；④轻奢法式精致感强预算较高；⑤日式原木+收纳适合小户型。选风格核心看生活方式和预算。","legalRef":"行业通行做法","consumerBenefit":"了解关键要点避免踩坑","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["装修选什么风格好看","装修风格有哪些","现代简约和北欧区别"]},{"id":"PRE-NEED-086","name":"刚需和改善有什么区别","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我有一套小房子想换大的，算刚需还是改善？","ola":"已有房再买就算改善，首付利率都不同","cp":["刚需解决有无改善追求品质","首付利率契税政策差异大","刚需预算刚改善弹性大","先确认身份再算成本"],"detail":"刚需指首套自住、解决有无问题，通常面积紧凑、总价敏感；改善指已有住房、追求品质升级，关注户型空间、小区环境、物业服务。核心区别在于：刚需预算刚性强、容错率低，改善预算弹性大、品质要求高。政策上首套与二套在首付比例、贷款利率、契税均有差异，直接影响购房成本。","legalRef":"《关于调整差别化住房信贷政策的通知》首套二套认定标准","consumerBenefit":"搞清身份不误判政策优惠","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["刚需改善咋分","我是刚需还是改善","刚需房改善房差别"]},{"id":"PRE-NEED-089","name":"想买婚房有什么要注意的","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我和对象准备结婚，婚房怎么选比较好？","ola":"预留儿童房、通勤折中、学区别过度溢价","cp":["预留儿童房空间","通勤折中选区域","学区预留别过度溢价","考虑父母帮带娃便利"],"detail":"婚房选购需兼顾双方通勤、未来3-5年家庭规划、学区预留三个维度。常见误区：只看当前两人需求忽略育儿空间、过度追求面积导致通勤过长、忽视双方父母帮带娃的居住便利。建议婚房面积至少预留一间儿童房，优先选双方通勤折中区域，有学区预留意识但不必为远期学区溢价过多。","legalRef":"行业通行做法","consumerBenefit":"婚房一步到位，少折腾换房","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["结婚买房注意啥","婚房选多大合适","婚房要学区吗"]},{"id":"PRE-NEED-091","name":"养老房怎么选比较好","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"想给爸妈买套养老房，怎么选？","ola":"低楼层+近医院+步行配套+适老设施","cp":["低楼层或有电梯","距医院3公里内","配套步行可达","适老化设施不能少"],"detail":"养老房五大硬性标准：①低楼层或有电梯（2楼以下优先）；②距医院3公里内；③生活配套步行可达（菜场、药店、公园）；④采光通风好避免阴冷潮湿；⑤社区有适老化设施（扶手、防滑地砖、无障碍通道）。避免偏远郊区大盘、避免楼梯房高楼层、避免周边缺乏医疗资源的项目。","legalRef":"行业通行做法","consumerBenefit":"老人住得安全方便，子女放心","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["老人住什么房好","养老房标准","适合老人住的房子"]},{"id":"PRE-NEED-123","name":"刚需买房最怕什么坑","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"第一次买房最容易被什么坑？","ola":"月供超标+得房率低+学区没查+资格没核","cp":["月供超50%生活崩盘","得房率低等于面积缩水","学区要查落户和学位占用","资格先查定金后交"],"detail":"刚需五大高频踩坑：①只看总价忽略月供压力（月供超50%生活质量崩盘）；②只看面积忽略得房率（100平高层实际75平）；③冲着学区买但没查落户年限和学位占用；④选偏远郊区图便宜但通勤1.5小时+配套全无；⑤没查购房资格就交定金导致资格不符定金不退。刚需容错率低，每一步都必须验证再决策。","legalRef":"行业通行做法","consumerBenefit":"首购不踩五大坑","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["刚需踩坑常见有哪些","首购最容易犯什么错","刚需买房避坑清单"]},{"id":"PRE-PRICE-013","name":"换购住房个税退税怎么操作","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"我卖了旧房一年内再买新房，个税能退吗？","ola":"能退，同城市1年内再购按差额退个税，延续至2027年底","cp":["政策延续至2027.12.31","1年内在同城市再购可退税","新购≥出售价全额退还","新购<出售价按比例退还","先缴后退需提供完税证明"],"detail":"自2024年1月1日至2027年12月31日，纳税人出售自有住房并在现住房出售后1年内在同一城市重新购买住房的，可按新购住房金额与原住房销售额的差额申请退还出售住房时缴纳的个人所得税。退税金额=新购住房金额≥原住房销售额的，全额退还；新购住房金额<原住房销售额的，按比例退还。操作流程：出售时先缴个税→1年内购买新房→向税务局申请退税→审核通过后退回。需提供出售和新购的完税证明及合同。","legalRef":"财政部 税务总局 住建部《关于延续实施居民换购住房个人所得税退税政策的公告》（2023年第28号）","consumerBenefit":"换房退个税省几千到几万，政策红利别错过","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["卖房再买退个税","换房退税政策","出售住房一年内再购退税"]},{"id":"PRE-QUAL-026","name":"离婚后买房算首套还是二套","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"如果离婚了，房子怎么分？","ola":"婚前全款归个人，婚内购买双方均分，共同还贷需补偿","cp":["婚前全款属个人不分割","婚内购买属共同均分","婚前贷款婚后共还贷需补偿","一方父母全款属个人","离婚协议备案后可强制执行"],"detail":"离婚房产分割规则：①婚前全款购买登记一方名下——属个人财产不分割②婚内购买无论谁名下——属共同财产原则上均分③婚前贷款婚后共同还贷——房屋归登记方，补偿对方共同还贷+增值部分④一方父母全款出资登记己方子女——属个人财产⑤双方父母共同出资——按出资比例分割。离婚协议中的房产分割条款经民政局备案后具有法律效力，一方不履行另一方可申请法院强制执行。","legalRef":"《中华人民共和国民法典》第1062条、第1063条、第1087条；婚姻家庭编解释（一）第29条、第78条","consumerBenefit":"了解分割规则保护自身权益","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["离婚房产分割规则","婚内购房离婚分配","贷款房离婚怎么分"]},{"id":"PRE-QUAL-048","name":"首套房首付要多少","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"第一次买房首付要准备多少？","ola":"商贷两到三成公积金两成，一线城市更高","cp":["首套商贷20-30%公积金20%","一线城市首付比例更高","二套首付40-60%差距大","实际需准备房价25-35%"],"detail":"首套房首付比例因城市和贷款类型而异：商业贷款首套一般20%-30%（一线城市35%）、公积金贷款首套20%。首付比例还受房屋面积影响（部分城市对90㎡以下首付更低）。二套房首付比例大幅提高至40%-60%。首付=房价×首付比例+税费+维修基金等附加费用，实际需准备金额约为房价的25%-35%。","legalRef":"《关于调整差别化住房信贷政策的通知》首套房首付比例","consumerBenefit":"首付准备充足不差钱","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["首套首付比例多少","第一次买房首付几成","刚需首付最低多少"]},{"id":"PRE-SCH-002","name":"六年一学位是什么意思影响大吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"听说学区房有六年一学位，什么意思？影响我买房吗？","ola":"6年只给1个学位，前业主用了你孩子就没学位，必须核验","cp":["6年内只提供一个学位","前业主占用你6年不能用","锁定从首次使用日起算6年","同家庭二胎多胞胎除外","购学区房必须核验学位占用"],"detail":"六年一学位指同一套住房在6年内只提供一个入学学位（同一家庭的多胞胎/二胎除外）。如果前业主子女在使用该学位，你的子女在6年内无法使用同一学位入学。学位锁定从该学位首次使用之日起算6年。北京、上海、深圳等城市已全面实行。影响：如果学位被前业主占用，你买下这套房后孩子可能在6年内无法入学对应学校。购买学区房必须核验学位是否被占用，核验方法：到辖区教育局或学校查询学位使用记录。","legalRef":"各城市教育局六年一学位政策文件（如京教基二〔2017〕9号）","consumerBenefit":"不买学位被占的学区房，孩子入学不落空","tags":{"clientType":["buyer"],"stage":"pre","layer":["道"],"meetingPhase":["见前"]},"alias":["学位锁定政策","六年一个学位","学位被占怎么办"]},{"id":"PRE-SCH-009","name":"租的房子能在学区上学吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"不买房只租房，孩子能上这个学区的学校吗？","ola":"顺位最低极可能被统筹，纯靠租房上名校基本不可能","cp":["入学顺位租房最低可能被统筹","需租赁备案居住证社保无房证明","热门校明确不接收租房生源","租购同权推进中但实际差距大","纯靠租房上名校可能性极低"],"detail":"租购同权是政策方向但实际落地差异大。当前入学顺位：有房有户>有户无房>有房无户>租房无户。租房入学需要的材料：租赁合同备案、居住证、社保缴纳证明、无房证明。租房入学的问题：顺位最低极可能被统筹到非对口学校、部分热门学校明确不接收租房生源、租赁备案需满一定年限（1-3年）。广州、深圳在推进租购同权但实际执行中购房仍远优于租房。纯靠租房上名校的可能性极低。","legalRef":"《关于加快发展住房租赁市场推进租购同权的实施方案》（各城市版本）；《居住证暂行条例》","consumerBenefit":"不抱租房上名校幻想，有入学需求就买房","tags":{"clientType":["buyer"],"stage":"pre","layer":["道"],"meetingPhase":["见前"]},"alias":["租房能上对口学校吗","租购同权入学","租房入学顺位"]},{"id":"PRE-SCH-013","name":"入学前多久买学区房最合适","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"孩子明年要上小学，现在买学区房还来得及吗？","ola":"多数要求入学前1年迁户口，提前2-3年买最稳","cp":["多数城市要求入学前1年迁户口","学位被占需等6年释放","5-6月报名需房产证户口本","建议入学前2-3年启动购房","临入学买可能顺位降级"],"detail":"购买学区房的时间规划需考虑三个时间节点：①户口迁入截止日——多数城市要求入学前1年户口已迁入学区（部分城市要求3年），如2026年9月入学需2025年8月前迁入②学位释放——如果学位被前业主占用，需等6年期满释放，购房前确认释放时间③入学报名——每年5-6月报名需提供房产证/户口本。建议：孩子入学前2-3年启动购房，留足户口迁入和学位释放时间。临入学才买可能因户口迁入不满1年被降顺位。","legalRef":"各城市义务教育阶段招生入学工作实施意见","consumerBenefit":"不因时间不够白买学区房，规划好时间节点","tags":{"clientType":["buyer"],"stage":"pre","layer":["法"],"meetingPhase":["见前"]},"alias":["学区房购买时机","入学前几年买学区房","迁户口要提前多久"]},{"id":"PRE-SCH-019","name":"北京学区政策有多复杂","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"北京买学区房有什么要注意的？政策复杂吗？","ola":"全国最复杂：多校划片+六年学位+校额到校，选九年一贯制最稳","cp":["城六区全面多校划片","六年一学位锁定6年","校额到校弱校也有名校机会","入学顺位5级从本区户籍排起","选九年一贯制确定性最高"],"detail":"北京学区政策全国最复杂：①多校划片——城六区已全面实行，购学区房不保证对口名校②六年一学位——同一地址6年只提供1个学位③校额到校——优质高中招生名额分配给普通初中④入学顺位——本区户籍+父母房产排第一。策略：选九年一贯制确定性最高，选教育强区整体均衡（西城/海淀），校额到校下普通初中的名校升学率也在提升。","legalRef":"《北京市教育委员会关于2024年义务教育阶段入学工作的意见》（京教基二〔2024〕8号）；各区入学实施细则","consumerBenefit":"了解北京学区全貌，不盲目买不踩坑","tags":{"clientType":["buyer"],"stage":"pre","layer":["道"],"meetingPhase":["见前"]},"alias":["北京学区政策详解","北京多校划片怎么执行","北京校额到校什么意思"]},{"id":"PRE-SCH-024","name":"学区房溢价到底值不值","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"学区房比周边贵了30%，值不值得买？","ola":"3年内入学值得，纯投资需谨慎溢价收缩风险","cp":["学区溢价通常20%-50%","自住+上学双重需求则溢价合理","多校划片使确定性下降","出生率下降减少学区需求","3年内入学可买纯投资谨慎"],"detail":"学区房溢价是指因学区资源导致房价高于同区域非学区房的部分，通常溢价20%-50%。溢价是否值得取决于：自住+上学双重需求则溢价合理，纯投资风险较高。风险点：多校划片政策推广使学区确定性下降，溢价可能收缩；人口出生率下降导致学区需求减少；教育均衡化政策推动优质资源向薄弱校流动。建议：如3年内有入学需求可考虑购买；纯投资需谨慎，溢价收缩风险不可忽视。","legalRef":"《义务教育法》第12条","consumerBenefit":"想清楚买学区房的真实目的，不为焦虑买单","tags":{"clientType":["buyer"],"stage":"pre","layer":["术"],"meetingPhase":["见前"]},"alias":["学区房溢价多高合理","学区房贵多少值得买","学区溢价会不会跌"]},{"id":"PRE-SCH-027","name":"学区房用完了再卖还值钱吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"学区名额用完了，这套房子还值钱吗？","ola":"学位占用折价10%-20%，但地段品质仍有价值","cp":["学位占用后折价10%-20%","学区价值约占学区溢价的40%-60%","六年一学位需等6年才可再用","学区房还有地段品质等非学区价值","入学后可考虑出售避免政策风险"],"detail":"学区房用完学位后再出售，价值取决于剩余学位可用时间和学区热度。六年一学位政策下，学位被占用后需等6年才可再次使用，期间房屋的学区属性价值大打折扣。市场表现：学位被占用的学区房比可用学位的同类房源折价10%-20%；但学区房的核心价值还包括地段、品质等因素，学区价值约占学区房溢价的40%-60%。建议：如孩子已入学且短期无二胎需求，可在学位占用后但学区热度仍高时出售，避免多校划片政策风险。","legalRef":"《义务教育法》第12条","consumerBenefit":"合理规划学区房出售时机，利益最大化","tags":{"clientType":["buyer"],"stage":"pre","layer":["术"],"meetingPhase":["见前"]},"alias":["学区名额用了还值钱吗","学区房用完名额后贬值多少","六年一学位用完影响卖吗"]},{"id":"PRE-SCH-030","name":"怎么查学区名额有没有被前业主占用","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"怎么确认前业主的孩子还在不在用这个学区的学位？","ola":"直接问学校教务处最可靠，部分城市可线上查","cp":["联系学校教务处核实最可靠","部分城市教育局官网可线上查询","物业社区可辅助了解信息","贝壳系统部分城市可查学位状态","学位被占用须在合同约定释放时间"],"detail":"核实学区名额使用情况的方法：一是向小区对应学校的教务处咨询该地址是否有在册学生；二是通过当地教育局官网或APP查询学位使用情况（部分城市已开通线上查询）；三是联系物业或社区了解前业主子女就学信息；四是通过经纪人查询，部分城市的贝壳系统可查询学区名额状态。最可靠的方式是直接联系学校教务处核实。如发现学位被占用，应在合同中约定前业主子女毕业后学位释放的时间和违约责任。","legalRef":"《义务教育法》第12条","consumerBenefit":"提前确认学区名额可用，不买了才发现被占用","tags":{"clientType":["buyer"],"stage":"pre","layer":["法"],"meetingPhase":["见前"]},"alias":["学区名额怎么查","怎么确认学位没被占用","学位查询去哪里查"]},{"id":"PRE-SCH-032","name":"买学区房户口必须迁过来吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买了学区房但户口还没迁过来，孩子能上对口学校吗？","ola":"人户一致才最优先，户口没迁可能被调剂，尽快迁入","cp":["多数城市要求人户一致方可对口入学","有房无户排序低于有房有户","热门学校人户不一致可能进不去","买房后尽快迁户口确保最优先排序","部分城市还要求实际居住证明"],"detail":"多数城市入学要求'人户一致'，即户口地址与房产地址一致。户口不在学区房所在地址的情况下：部分城市按'有房无户'排序，优先级低于'有房有户'，热门学校可能进不去；部分城市要求必须户口迁入方可对口入学。北京、上海等严格实行人户一致的城市，户口未迁入可能被调剂。建议：购买学区房后尽快将全家户口迁入房产地址，确保入学排序最优先。部分城市还要求实际居住，需提供水电费等居住证明。","legalRef":"《义务教育法》第12条","consumerBenefit":"及时迁户口保住入学优先级，不因户口问题被调剂","tags":{"clientType":["buyer"],"stage":"pre","layer":["法"],"meetingPhase":["见前"]},"alias":["学区房必须迁户口吗","户口不在学区房能不能上学","只过户不迁户口影响入学吗"]},{"id":"PRE-SCH-CASE-001","name":"买学区房没过户孩子能提前落户上学吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"房子还没过户，孩子马上要报名了，我能先把户口迁进去吗？","ola":"未过户无产权，无法办理落户入学。","cp":["户口迁移属公安管辖","产权未转移无法落户","法院不受理强制落户","落户必须以过户为前提"],"detail":"张某购买学区房，合同约定过户后迁户口。因贷款审批慢未过户，张某要求提前迁入户口以便孩子报名。卖家拒绝。张某起诉要求强制迁户口。法院审理认为，户口迁移属公安机关行政管理范畴，且房屋产权未发生转移，张某不具备落户条件，判决驳回张某诉求。","legalRef":"《中华人民共和国民法典》第二百零九条","consumerBenefit":"明确落户与产权过户的法定先后顺序，避免耽误孩子报名。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["没过户能落户上学吗","学区房未过户能上学吗","买房没下本能落户吗"]},{"id":"PRE-SCH-CASE-004","name":"买学区房发现学位被政策锁定六年怎么办","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买了学区房才发现学位被前业主的孩子锁定了六年，我能退房吗？","ola":"隐瞒学位锁定致无法入学，可解约并索赔。","cp":["学位锁定导致无法入学","隐瞒锁定属违约行为","购房目的落空可解约","卖家需赔偿利息损失"],"detail":"赵某购买学区房，合同约定“学位未被占用”。过户后发现该房屋学位因前业主子女就读被教育局“六年一学位”政策锁定，赵某子女无法入学。赵某起诉卖家违约。法院认为，卖家隐瞒学位被锁定事实，导致赵某购房目的无法实现，判决解除合同，卖家退还房款并赔偿赵某利息损失。","legalRef":"《中华人民共和国民法典》第五百条","consumerBenefit":"明确学位锁定政策的法律效力，掌握因学位锁定解约退房的法律依据。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["学位锁定六年能买吗","学区房学位被占用锁定","六年一学位政策怎么查"]},{"id":"PRE-SCH-CASE-009","name":"买学区房发现原房东用房子注册了公司影响上学吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买了学区房才发现前房东用这地址注册了公司，影响孩子上学怎么办？","ola":"房屋注册公司影响落户，可诉请强制注销并索赔。","cp":["注册公司影响户口迁入","需注销后方可落户入学","卖家有义务清除障碍","延期落户可索赔损失"],"detail":"郑某购买学区房，过户后发现原房东将该房屋地址注册为某公司住所地。当地教育局规定，房屋地址若被注册为公司，需注销后方可办理户口迁入及入学报名。郑某起诉原房东要求强制注销并赔偿。法院判决原房东限期注销公司注册地址，并赔偿郑某因延期落户导致的租房损失。","legalRef":"《中华人民共和国民法典》第五百零九条","consumerBenefit":"签约前核查房屋是否被注册公司，避免落户入学受阻。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["原房东注册公司影响上学吗","学区房被注册公司能买吗","房屋注册公司影响落户"]},{"id":"PRE-NEED-138","name":"换房时怎么分清自己是真改善还是假改善？（PRE-NEED）","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我想换个大房子但钱不够，算改善还是刚需？","ola":"改善看重品质地段，刚需看重总价门槛，需明确底线。","cp":["改善重品质与地段","刚需重总价与门槛","梳理核心换房痛点","明确预算与面积底线","避免房源推荐错位"],"detail":"情境：客户表示要换大房子，但预算仅够买远郊小三房。判断依据：改善型看重核心地段、配套和品质，刚需看重总价和上车门槛。行动建议：经纪人需引导客户梳理核心痛点，若无法兼顾地段与面积，需明确其底线。风险提示：将刚需误判为改善会推荐超预算房源，导致流失；将改善误判为刚需会推荐远郊盘，降低满意度。","legalRef":"行业惯例","consumerBenefit":"明确换房核心诉求，在预算内找到最优解。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["改善和刚需怎么区分","换房需求是改善还是刚需","怎么判断改善型购房需求"]},{"id":"PRE-NEED-145","name":"卖旧买新时怎么避免置换周期错配导致违约？（PRE-NEED）","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我旧房还没卖掉，能先交新房定金吗？","ola":"风险极高，需拉长新房付款周期或增加解约条款。","cp":["预估旧房成交周期","拉长新房付款周期","增加解约保护条款","防范资金链断裂","合理规划买卖时序"],"detail":"情境：客户旧房还没卖，就交了新房定金，导致新房首付凑不齐。判断依据：当前二手房成交周期拉长，买卖时间差极易造成资金链断裂。行动建议：经纪人需合理预估旧房成交周期，在新房合同中约定较长的付款周期或加入解约条款。风险提示：周期错配会导致客户违约，损失定金甚至承担高额违约金。","legalRef":"《中华人民共和国民法典》第五百九十条","consumerBenefit":"保障置换资金安全，避免因周期错配导致违约。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["卖旧买新置换周期错配","换房怎么衔接买卖时间","卖旧房买新房时间差"]},{"id":"P2-C1-003","name":"学区范围每年会变吗","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"学区范围是固定的还是每年都可能变？","ola":"可能调整，以当年公布为准。","cp":["学区范围可动态调整","以当年教育部门公告为准","新房交付可能影响划片"],"detail":"学区范围并非一成不变，区县教育部门每年会根据适龄人口变化、新建学校交付、学位供需情况等因素调整学区边界。尤其新建小区集中交付的年份，学区调整概率更大。建议每年招生季前关注当地教育部门官方公告，不要仅凭往年学区图做决策。","legalRef":"各地义务教育阶段招生入学实施方案","consumerBenefit":"提前预判学区变动风险，避免买了房学区却变了。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["学区会不会每年调整","学区范围是否固定","学区划片会变动吗"]},{"id":"P2-C1-004","name":"租房能不能上对口学区学校","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"我不买房只租房，孩子能上对口学区学校吗？","ola":"视当地政策，部分地区可凭租房入学。","cp":["部分城市允许租房入学","需办理租赁备案","顺位通常排在户籍之后"],"detail":"租房能否上对口学校取决于当地政策。部分城市如北京、上海对持居住证并办理租赁备案的租房家庭开放入学申请，但顺位通常排在户籍适龄儿童之后，不保证对口入学。多数城市租房入学由教育部门统筹安排，可能被分配到周边有空余学位的学校。具体政策需咨询当地教育部门。","legalRef":"各地随迁子女入学政策及租赁入学规定","consumerBenefit":"了解租房入学可能性，规划子女教育路径。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["租房可以上学区学校吗","租房子能上对口学校吗","租房入学政策"]},{"id":"P2-C1-005","name":"非本地户籍孩子怎么入学","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"我们没有本地户口，孩子在这里怎么入学？","ola":"凭居住证等材料申请统筹入学。","cp":["需持居住证申请入学","由教育部门统筹安排","通常不保证对口入学"],"detail":"非本地户籍适龄儿童入学需持居住证、务工证明、住房证明等材料向区县教育部门申请。教育部门根据学位情况统筹安排入学，通常不保证对口入学。各地政策差异较大，部分城市对社保缴纳年限、居住证年限有要求。建议提前了解当地随迁子女入学政策并准备材料。","legalRef":"《中华人民共和国义务教育法》第十二条及各地随迁子女入学办法","consumerBenefit":"掌握非户籍入学流程，提前准备所需材料。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["外地户籍孩子怎么上学","非沪籍非京籍怎么入学","随迁子女入学条件"]},{"id":"P2-C1-017","name":"户口落在房子里就能上对口学校吗","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"我把户口落到学区房里，孩子就一定能上对口学校吗？","ola":"落户是重要条件但不保证，还需看顺位。","cp":["落户是入学重要条件","需满足顺位和年限要求","多校划片区域仍需派位"],"detail":"户口落在学区房内是入学的重要条件，但不等于保证对口入学。还需满足顺位要求（户籍+房产一致优先）、落户年限要求（部分城市要求落户满一定年限），以及多校划片区域的电脑派位结果。若落户时间短或顺位靠后，可能被统筹到其他学校。建议提前了解当地落户入学具体要求。","legalRef":"《中华人民共和国义务教育法》第十二条及各地落户入学规定","consumerBenefit":"明确落户与入学的关系，合理规划落户时间。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["落户就能上对口学校吗","户口在学区房就能入学吗","落户对口入学保障"]},{"id":"P2-C1-022","name":"期房能上学区学校吗","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"我买的是期房还没交付，孩子能上对口学区学校吗？","ola":"通常需交房并落户后才能入学。","cp":["一般需交房后才能入学","未交房通常无法对口入学","建议确认交房与入学时间"],"detail":"期房能否上学区学校取决于交房时间和当地政策。一般情况下需房屋交付并办理房产证、迁入户口后方可享受对口入学。若交房时间晚于入学信息采集截止日，孩子可能无法当年对口入学，需由教育部门统筹安排。建议购房前核实交房时间与入学时间节点的匹配，做好备选方案。","legalRef":"各地义务教育招生入学实施细则及《城市商品房预售管理办法》","consumerBenefit":"评估期房入学风险，合理安排购房计划。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["期房入学问题","买期房能上对口学校吗","期房没交付能入学吗"]},{"id":"P2-C3-011","name":"集体户口孩子怎么入学","domain":"学区教育","subScene":"教育规划","scene":"学区教育·教育规划","cq":"我们是集体户口，孩子怎么入学？顺位会不会靠后？","ola":"可入学但顺位通常低于个人户籍。","cp":["集体户口可申请入学","顺位通常排在个人户籍之后","可能由教育部门统筹安排"],"detail":"集体户口适龄儿童可正常申请入学，但顺位通常低于户籍加房产一致的家庭。部分城市将集体户口安排在第二或第三顺位，可能由教育部门统筹安排学校而非对口入学。具体政策因城市而异，部分区域对集体户口设有单独顺位规则。建议提前了解当地集体户口入学政策，准备相关证明材料并做好统筹入学的心理准备。","legalRef":"各地集体户口入学实施细则","consumerBenefit":"了解集体户口入学规则，提前做好准备。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["集体户口入学政策","集体户口孩子怎么上学","集体户口入学条件"]},{"id":"P2-C3-014","name":"跨区上学可以吗","domain":"学区教育","subScene":"教育规划","scene":"学区教育·教育规划","cq":"想让孩子跨区上学，可以吗？有什么条件？","ola":"一般不可以，义务教育以户籍地就近入学。","cp":["义务教育以户籍地就近入学","跨区入学需特殊条件","部分情况可申请统筹"],"detail":"义务教育阶段原则上以户籍所在地就近入学，一般不允许跨区择校。但在特定情况下可申请跨区入学，如父母工作调动、户籍迁移、集体户口等，需经双方区县教育部门审批同意。部分城市对跨区入学有严格限制，仅个别情况予以批准。建议了解当地跨区入学政策，评估可行性和办理难度后再做规划。","legalRef":"各地跨区入学政策及实施细则","consumerBenefit":"了解跨区入学政策，评估可行性。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["跨区上学政策","能不能跨区上学","跨区入学条件"]},{"id":"OWN-LND-025","name":"委托出租合同要注意什么","domain":"业主资产","subScene":"委托托管与维修责任","scene":"业主资产·委托托管与维修责任","cq":"房东问：签委托出租合同要注意什么？怎么保护自己？","ola":"明确权责、费用、期限和解约条件。","cp":["明确服务内容和费用","约定空置期和租金支付","保留随时解约权"],"detail":"委托出租合同注意事项：一、明确服务内容，是居间还是托管包租；二、约定费用标准，佣金比例或管理费比例；三、约定租金支付时间和方式，托管模式下房东每月何时收到租金；四、约定空置期上限和空置期间的责任；五、保留随时解约权，约定提前通知期限；六、明确房屋损坏赔偿标准；七、约定托管公司的维修响应时限。建议要求托管公司提供营业执照和住房租赁企业备案证明，核实资质后再签约。","legalRef":"《中华人民共和国民法典》第九百一十九条（委托合同）","consumerBenefit":"帮房东审慎签订委托合同，保护自身权益。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["委托出租合同注意","托管合同条款","委托租赁协议"]},{"id":"OWN-SLR-012","name":"独家委托还是多家委托好","domain":"业主资产","subScene":"出售委托","scene":"业主资产·出售委托","cq":"业主问：卖房是找一家独家委托还是多家挂牌好？","ola":"独家省心价高，多家曝光广各有利弊。","cp":["独家委托服务更专注","多家挂牌曝光更广","独家通常承诺限期出售"],"detail":"独家委托与多家委托对比：独家委托优势是中介投入更多资源，通常承诺限期出售、专人服务、定期反馈，适合不急于出售且期望高价的业主；多家委托优势是曝光面广，多家中介同时推客，适合急于出售的业主。独家委托注意要点：一、约定委托期限，通常3-6个月；二、约定最低售价和违约责任；三、约定中介服务标准和反馈频率；四、保留自行成交的权利。多家委托注意避免多家中介带同一客户看房产生佣金争议。","legalRef":"《中华人民共和国民法典》第九百一十九条（委托合同）","consumerBenefit":"帮业主选择委托方式，高效出售。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["独家委托vs多家委托","卖房委托方式","独家代理卖房"]},{"id":"OWN-SLR-029","name":"底价怎么设定","domain":"业主资产","subScene":"议价谈判","scene":"业主资产·议价谈判","cq":"业主问：卖房底价怎么定？留多少谈判空间？","ola":"挂牌价+5%，期望价，底价-5%。","cp":["底价=期望价-10%","挂牌价=期望价+5%","不可突破心理底线"],"detail":"底价设定方法：一、确定市场基准价，参考同小区同户型近3个月成交均价；二、设定期望价，根据房屋条件在基准价上下浮动5%-10%；三、设定挂牌价，挂牌价=期望价+5%-10%，留谈判空间；四、设定底价，底价=期望价-5%-10%，低于此价不卖。例如市场价300万的房子：挂牌价315万、期望价300万、底价285万。底价设定考虑因素：一、贷款余额，底价需覆盖剩余贷款；二、置换成本，卖房后购房需要的资金；","legalRef":"《中华人民共和国民法典》第五百九十五条（买卖合同定义）","consumerBenefit":"帮业主科学设定底价，掌控谈判节奏。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["卖房底价设定","最低出售价","卖房底线"]},{"id":"P3-A4-025","name":"买卖不破租赁怎么理解","domain":"法规政策","subScene":"租赁法规","scene":"法规政策·租赁法规","cq":"客户问：买卖不破租赁怎么理解？","ola":"房屋所有权变动不影响租赁合同效力，新房东须继续履行原租约。","cp":["房屋转让后原租赁合同继续有效","新房东取代原房东成为出租人","租赁在前买卖在后才适用"],"detail":"买卖不破租赁是民法典确立的重要原则，租赁物在承租人按照租赁合同占有期限内发生所有权变动的，不影响租赁合同的效力。即房屋被出售、赠与或继承后，新的所有权人自动取代原出租人成为租赁合同当事人，须继续履行原租赁合同至期满。适用前提是租赁关系先于买卖关系存在，先买后租的不适用。","legalRef":"《中华人民共和国民法典》第七百二十五条","consumerBenefit":"帮租客理解买卖不破租赁原则，房屋易主也不怕被迫搬离。","tags":{"clientType":["tenant","landlord","buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["买卖不破租赁什么意思","房子卖了租客要搬吗","新房东能赶走老租客吗"]},{"id":"CRO-GEN-001","name":"买房从哪些方面开始考虑","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我想买房，但不知道从哪方面开始看","ola":"价格区位品质风险八大维度逐一看","cp":["价格维度：总价与月供","区位维度：通勤与生活圈","品质维度：户型与物业","风险维度：产权与合规"],"detail":"购房决策涉及价格、区位、品质、交通、配套、学区、产权、风险八大核心维度，每个维度内部又可细分为多个子指标。经纪人需掌握维度框架，帮助客户按优先级筛选，避免遗漏关键因素导致决策偏差。","legalRef":"行业通行做法","consumerBenefit":"不遗漏关键因素，决策更全面","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["买房考虑什么","购房看哪些维度","买房关注点"]},{"id":"CRO-GEN-003","name":"怎么判断住得舒不舒服","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"这房子住着到底舒不舒服","ola":"户型采光物业配套绿化综合看","cp":["户型方正通透是基础","采光通风决定日常舒适","物业质量影响长期体验","周边配套关系生活便利"],"detail":"居住品质由户型方正度、采光通风、隔音效果、物业服务、小区绿化、周边配套、交通通达性、邻居素质等指标综合决定。经纪人带看时需主动讲解品质维度，帮助客户建立客观判断框架。","legalRef":"行业通行做法","consumerBenefit":"买到真正住着舒服的房子","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["住得舒服看什么","居住品质怎么看","房子住着舒服吗"]},{"id":"CRO-GEN-039","name":"不同城市买房有什么区别","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"不同城市买房到底有什么不一样","ola":"限购房价贷款学区户口城市各不同","cp":["限购政策城市差异大","房价水平总价差距显著","贷款首套认定标准不同","户口含金量城市间差异大"],"detail":"不同城市购房差异主要体现在限购政策（一线城市严格二三线宽松）、房价水平（一线城市总价高首付比例大）、贷款政策（首套房认定标准城市不同）、学区政策（多校划片落地程度不同）、户口价值（一线户口含金量高）等方面。经纪人需掌握本地政策细节。","legalRef":"行业通行做法","consumerBenefit":"了解城市差异，跨城购房不踩坑","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["城市买房差异","一线和二线买房区别","城市间购房差异"]},{"id":"EXT-SEL-005","name":"卖了出租中的房子租客怎么办","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"我的房子还在出租，能挂牌卖吗？","ola":"能卖，但租客可住到期满，且有优先购买权","cp":["买卖不破租赁原则","租客可住到原合同期满","须通知租客出卖事项","租客有优先购买权","合同须如实填写出租状态"],"detail":"出售已出租房屋时对承租人的处理。依据'买卖不破租赁'原则，租赁合同对新房东继续有效，租客可住到期满。业主须在出卖前合理期限内通知租客，租客享有同等条件优先购买权。卖方须在合同中如实填写房屋出租状态，即使承诺自行解约也不得填'未出租'。","legalRef":"《中华人民共和国民法典》第725条、第726条","consumerBenefit":"合法处理带租约出售，避免租客纠纷","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["带租约出售","卖房租客处理","出售已出租房"]},{"id":"EXT-SEL-030","name":"什么时候卖房最划算","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"什么时候卖房最划算","ola":"旺季3-5月和9-11月挂牌","cp":["旺季3-5月和9-11月挂牌","置换/资金需求优先于市场","利好政策后市场回暖出手","结合小区近期成交价定价","不追涨杀跌理性决策"],"detail":"卖房时机判断：①看市场周期：量价齐升期适合卖出，量跌价稳/量价齐跌期不宜急于出售；②看个人需求：置换/资金需求优先于市场判断；③季节因素：3-5月和9-11月为传统交易旺季挂牌看房活跃；④政策窗口：限购放松/利率下降等利好政策出台后市场回暖适合出手；⑤定价策略：不追涨杀跌，结合急迫程度和小区近期成交价理性定价。","legalRef":"行业通行做法","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["卖房最佳时机","房价什么时候见顶","市场行情怎么看"]},{"id":"LIV-MNT-CASE-011","name":"租客自己花钱翻新房子退租时能要补偿吗","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"我自己花钱把租的房子翻新了，退租时能找房东要装修补偿吗？","ola":"未经房东同意的装修，退租无补偿。","cp":["未经同意装修无补偿","出租人可要求恢复原状","装修前须获书面同意","擅自装修需自担损失","保留房东同意证据"],"detail":"赵某承租孙某房屋，未经孙某同意自行花费2万元更换地板并粉刷墙面。退租时，赵某要求孙某补偿装修费。孙某拒绝并要求恢复原状。法院审理认为，根据《民法典》第七百一十五条，承租人未经出租人同意装饰装修，出租人可请求恢复原状或赔偿损失。判决赵某无权要求补偿，且需承担恢复原状费用。","legalRef":"《中华人民共和国民法典》第七百一十五条","consumerBenefit":"避免盲目投资装修，明确未经同意的装修无法获得补偿的法律风险。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租客装修房屋退租能要补偿吗","未经房东同意装修退租怎么算","租房自己花钱改造退租能报销吗"]},{"id":"OWN-POL-050","name":"限购放松业主趁势出售成功案例","domain":"业主服务","subScene":"政策","scene":"业主服务·政策","cq":"限购放松了，是不是趁现在卖比较好？","ola":"窗口期通常1-3月，核心区更受益但勿做确定性预测","cp":["限购放松→买方资格池扩大","短期供需错配=窗口期","窗口期通常1-3月","价格影响因区域分化","核心区涨幅大于远郊"],"detail":"典型案例：某二线城市2025年限购从认房又认贷调整为认房不认贷，非本地户籍社保要求从5年降至2年。业主李某持有一套次新房，限购放松后买方资格池明显扩大，李某在政策出台后第3天挂牌，因供应短期内未跟上需求增长，成交价较限购期评估价高出5%。关键启示：限购放松初期存在短期供需错配窗口期，但窗口期有限（通常1-3月），且价格影响因区域分化严重。核心区涨幅大于远郊。","legalRef":"行业案例分析（参考各城市限购调整后市场数据）","consumerBenefit":"理解政策窗口期的规律但不盲目跟风","tags":{"clientType":["seller"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["限购放松卖房成功实例","限购调整后卖房经验","政策放松卖房时机案例"]},{"id":"OWN-RET-008","name":"房子租不出去空置了怎么管理","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"我租的房子还没到期，房东说房子空着要收我空置费，合理吗？","ola":"定期巡查防隐患，按时缴纳空置期物业费。","cp":["定期巡查防漏水漏电","保持通风防发霉","按时缴纳空置期物业费等","可委托专业机构托管"],"detail":"房屋在换租或招租期间处于空置状态，仍需进行妥善管理以防资产贬值或产生安全隐患。业主应定期巡查房屋，检查水电燃气阀门，防止漏水漏电；保持室内通风，防止发霉；结清空置期间的物业、供暖等费用。同时，可考虑购买空置房保险，或委托物业、长租公寓机构进行托管，降低管理成本与风险。","legalRef":"《物业管理条例》及地方空置房物业费减免政策","consumerBenefit":"了解空置房的管理要点，避免因房屋失修导致退租时产生纠纷。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["空置房管理","房子空着怎么打理","出租房空置期维护"]},{"id":"P0-DEC-029","name":"忽略客户隐性需求导致退单的案例","domain":"交易综合","subScene":"客户解码","scene":"交易综合·客户解码","cq":"中介没问清我要给老人买带电梯的房能退中介费吗？","ola":"未深挖隐性需求致错配，中介需担责退费。","cp":["养老需求需关注电梯医院","中介未尽充分询问义务","仅看表面需求导致错配","法院判决退还部分费用","解码需深挖核心场景"],"detail":"某客户购房主要为老人养老，中介仅关注面积和价格，未挖掘出必须有电梯且靠近医院的隐性需求。签约后客户发现无电梯要求退单，引发中介费纠纷。法院认为中介未尽充分询问与匹配义务，判决退还部分中介费。提示：需求解码必须深挖核心使用场景。","legalRef":"《中华人民共和国民法典》第471条","consumerBenefit":"明确中介需深挖需求，保障购房初衷实现。","tags":{"clientType":["buyer"],"stage":"pre,mid","layer":"法","meetingPhase":["见前","见中"]},"alias":["隐性需求退单案","没问清需求退单","忽略痛点致解约"]},{"id":"P0-DEC-CASE-010","name":"买给老人养老的房子没电梯能退吗","domain":"交易综合","subScene":"客户解码","scene":"交易综合·客户解码","cq":"我买房给老人养老，结果没电梯老人上不去，这房子我能退吗？","ola":"未明确告知特殊人群具体需求，个人原因拒买需担责。","cp":["特殊人群需求需明确具体标准","未告知身体限制不构成房屋瑕疵","买方需对特殊使用场景负责","模糊需求导致误判适用定金罚则"],"detail":"韩某为父母养老购房，向经纪人表示“要安静、环境好”，但未明确提及老人腿脚不便需电梯的硬性要求。经纪人推荐并促成韩某购买一套一楼带院但需下5级台阶的二手房。韩某支付定金后，父母实地看房表示台阶不便轮椅通行，拒绝购买。韩某要求退定金。法院认为，房屋无电梯且非一楼平层并非质量瑕疵。韩某未明确告知老人身体状况及无障碍需求，属于买方未尽审慎义务。依据《民法典》第五百八十七条，判决定金不予退还。","legalRef":"《中华人民共和国民法典》第五百八十七条","consumerBenefit":"明确特殊人群购房需将具体硬件要求书面化。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前","见中"]},"alias":["买给老人养老没电梯能退吗","买房给老人住没电梯能退房吗","老人爬不动楼买的房能退吗"]},{"id":"PRE-MATCH-022","name":"人车分流是什么意思重要吗","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"人车分流是什么意思？买房一定要选人车分流吗？","ola":"地面无车道车位才叫真分流，有孩子老人必须选","cp":["车辆入口直接入地库","地面无车道无停车位","半分流不等于真分流","对有儿童老人家庭极重要","品质小区标配人车分流"],"detail":"人车分流指小区内机动车与行人完全分离，车辆从入口直接进入地下车库，地面无车道无停车位。完整的人车分流需满足：小区地面无车道、所有车位在地下、电梯直达地下车库、地面为纯步行区。半人车分流（部分地面有车道/车位）安全性和舒适度大打折扣。人车分流对有儿童和老人的家庭极其重要：地面无车辆消除了最大安全隐患，也是品质小区的标配。","legalRef":"《城市居住区规划设计标准》GB50180-2018第6.0.3条（停车布局）","consumerBenefit":"孩子老人地面安全活动，不担心车辆","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["人车分流好处","人车分流小区安全吗","人车不分流影响大吗"]},{"id":"PRE-MATCH-073","name":"学区房对口学校怎么核实","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"怎么确认这套房一定对口那个学校？","ola":"查教育局文件+问学校招生办+查3年名单","cp":["查教育局学区划分文件","到学校招生办确认对口名单","查近3年入学名单看稳定性","学区每年可能微调"],"detail":"学区对口学校核实四步：①查教育局官网当年学区划分文件；②打电话或到学校招生办确认当年对口小区名单；③查近3年入学名单看对口是否稳定；④问已入住业主子女实际入学情况。注意：学区划分每年可能微调，对口学校不是终身不变的，购买前务必确认当年有效。热门学校可能要求落户满2-5年，仅买房不够。","legalRef":"《义务教育法》第12条就近入学；各地教育局学区划分公告","consumerBenefit":"学区核实不落空","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["怎么查对口学校","学区划分在哪看","对口学校几年一变"]},{"id":"PRE-NEED-094","name":"买新房还是二手房好","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我是买新房还是买二手房？","ola":"要配套选二手，要全新选新房，看你在乎啥","cp":["新房有交付风险二手房所见即所得","刚需选二手次新房配套成熟","改善选品牌新房","贷款年限受房龄影响"],"detail":"新房优势：全新交付、户型设计新、首付比例低；劣势：期房交付风险、位置多偏远、配套待成熟。二手房优势：所见即所得、配套成熟、可议价；劣势：房龄影响贷款年限、有折旧、交易税费更复杂。刚需首购建议选配套成熟二手次新房，改善选品牌新房，投资看租售比不论新旧。","legalRef":"行业通行做法","consumerBenefit":"选对产品类型，少后悔","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["新房二手房怎么选","一手房二手房优劣","新房好还是二手好"]},{"id":"PRE-NEED-105","name":"预算不够能不能先买小再换大","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"钱不多先买个小房子以后再换大的行吗？","ola":"可以但两次交易成本8%起，小房要能增值","cp":["两次交易税费成本8-12%","持有满2年免增值税","二套首付利率更高","小房增值要覆盖置换成本"],"detail":"先小后大策略的核心成本是两次交易的税费和中介费，合计约占房价8%-12%。需评估：①小房能否增值覆盖置换成本；②持有期是否满两年免增值税；③换房时是否受二套政策限制（首付比例和利率更高）；④换房期间是否有过渡居住方案。如果小房增值潜力弱且持有不足2年，置换成本可能吃掉全部增值。","legalRef":"《关于调整房地产交易环节契税营业税优惠政策的通知》满2年免增值税","consumerBenefit":"置换策略算清账，不白折腾","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["先买小后换大行吗","阶梯式购房","小换大有啥成本"]},{"id":"PRE-NEED-113","name":"改善换房先卖后买还是先买后卖","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我要换房，先卖老房子还是先买新的？","ola":"先卖再买资金稳，限购城市必须先卖","cp":["先卖后买资金有保障","先买后卖双月供压力大","附条件合同衔接卖买","限购城市要先卖腾资格"],"detail":"先卖后买：资金有保障但面临卖掉后没房住的过渡期，且如房价上涨可能买不回同等品质。先买后卖：避免无房住风险但需同时承担两套房月供，资金压力大。建议方案：先挂牌卖同时锁定意向新房，签附条件合同（卖房款到账后X日内签约新房），或选择短租过渡。限购城市需先卖才能腾购房资格。","legalRef":"行业通行做法","consumerBenefit":"换房不断档，资金不断链","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["换房顺序怎么定","先买后卖还是先卖后买","改善置换流程"]},{"id":"PRE-NEED-115","name":"容积率高低有什么影响","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"容积率3.5高不高，住着会不会很挤？","ola":"3.5算偏高，人多车多会比较拥挤","cp":["容积率决定居住密度","刚需3.0内改善2.5内","超高容积率停车电梯都成问题","低容积率房价也更高"],"detail":"容积率=总建筑面积/用地面积，直接决定居住密度和舒适度。参考值：独墅0.3-0.5、联排0.5-0.8、多层1.0-1.5、小高层2.0-3.0、高层3.0-5.0、超高层5.0+。容积率越高人口越密集，电梯等候、停车、绿化、噪音问题越突出。刚需3.0以内可接受，改善建议2.5以内，追求品质选1.5以内。","legalRef":"《城市居住区规划设计标准》GB50180-2018容积率控制指标","consumerBenefit":"密度适中住得宽松","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["容积率越低越好吗","容积率怎么看","高容积率小区好不好"]},{"id":"PRE-NEED-127","name":"首套房选多大面积合适","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"第一次买房选多大面积好？","ola":"两居80平三居100平，尽量一步到位","cp":["两居70-90三居90-110","适度偏大减少换房次数","换房成本8-12%别折腾","首套尽量一步到位"],"detail":"首套房面积取决于人口和预算：单身/两人70-90㎡两居、三口之家90-110㎡小三居、三代同住110-130㎡大三居。面积太小住着憋屈且未来换房成本高，面积太大月供压力大且浪费空间。首套房建议买适度偏大而非贪小，因为换房交易成本约占房价8%-12%，尽量一步到位减少换房次数。","legalRef":"行业通行做法","consumerBenefit":"首套不将就少换房","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["首套买多大面积","第一次买房选多大","首购面积怎么定"]},{"id":"PRE-PRICE-033","name":"挂牌价虚高怎么判断真实底价","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"这个小区挂牌价感觉虚高，怎么知道房东真实底价？","ola":"查成交均价+看挂牌天数+观察调价+让中介试探","cp":["查同小区近3月成交均价做基准","挂牌超90天未成交说明偏高","频繁小降说明有议价空间","通过经纪人试探业主底线","首次出价低于目标价3%-5%"],"detail":"判断业主真实底价的方法：第一步，查同小区近3个月同户型成交均价作为基准；第二步，看该房源挂牌天数，超过90天未成交说明挂牌价偏高；第三步，观察调价频率和幅度，频繁小降说明有议价空间；第四步，通过经纪人试探业主底线，方式包括'有诚心买家出XX万'、'客户全款能到XX万'等话术；第五步，综合以上信息出价，首次出价可低于目标价3%-5%留谈判空间。","legalRef":"《房地产经纪管理办法》第22条（如实报告义务）","consumerBenefit":"不被虚高挂牌价吓退，出价精准不花冤枉钱","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["挂牌价和底价差多少","怎么判断业主真实底价","挂牌价虚高怎么识别"]},{"id":"PRE-PRICE-039","name":"卖旧买新个税能退吗怎么操作","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"听说卖房再买可以退个税，怎么申请？退多少？","ola":"卖房1年内同城再购可退个税，新购≥原价全额退","cp":["政策延续至2027年12月31日","出售后1年内同一城市再购可退","新购金额≥转让金额全额退","新购金额<转让金额按比例退","购房后向税务机关申请退税"],"detail":"自2024年1月1日至2027年12月31日，纳税人出售自有住房并在现住房出售后1年内在同一城市重新购买住房的，可按规定申请退还其出售现住房已缴纳的个人所得税。退税金额=新购住房金额÷现住房转让金额×已缴纳个税。新购住房金额大于或等于现住房转让金额的，全部退还已缴纳个税；小于的按比例退还。需在购房后向税务机关提交退税申请。","legalRef":"财政部 税务总局 住建部公告2023年第28号第1条、第2条","consumerBenefit":"合法退税省下数万元，换房成本大幅降低","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["卖房再买退税怎么操作","换购住房退税条件","卖旧买新个税退还"]},{"id":"PRE-PRICE-048","name":"维修基金怎么交以后卖房能退吗","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"维修基金要交多少？卖房的时候能退吗？","ola":"新房交100-200元/㎡，二手房随房转不能退","cp":["北京多层100元/㎡高层200元/㎡","二手房交易维修基金随房转移","原业主无法退回维修基金","买方不需重新缴纳","使用需2/3以上业主同意"],"detail":"住宅专项维修资金（简称维修基金）是房屋的'养老金'，用于住宅共用部位和设施设备的维修更新。缴纳标准各地不同，北京为多层100元/㎡、高层200元/㎡；杭州为无电梯27.5元/㎡、有电梯65元/㎡。二手房交易时维修基金随房转移给买方，不需要重新缴纳，也无法退回原业主。使用条件：需经专有部分占建筑物总面积2/3以上的业主且占总人数2/3以上的业主同意。","legalRef":"《住宅专项维修资金管理办法》第7条、第12条","consumerBenefit":"了解维修基金规则不花冤枉钱","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["维修基金交多少","维修基金退不退","二手房维修基金谁出"]},{"id":"PRE-SCH-001","name":"学区划片规则是什么意思","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买了这个小区就能上对面的小学吗？学区怎么定的？","ola":"看是单校还是多校划片，单校固定对口，多校随机派位","cp":["单校划片固定对口一所","多校划片随机派位不确定","多校划片逐步取代单校划片","每年6月前后公布学区","教育局官网可查询学区范围"],"detail":"学区划片分为两种模式：单校划片——一个小区固定对口一所学校，入学确定性高；多校划片——一个小区对口多所学校，通过电脑随机派位决定入学，不确定性高。趋势：教育部推动多校划片取代单校划片，北京/上海等城市核心区已全面实行多校划片。划片由区教育局划定，每年6月前后公布当年学区范围，可能微调但一般不会大变。查询方法：区教育局官网/微信公众号、学校招生简章、教育局咨询电话。","legalRef":"《教育部办公厅关于进一步做好小学升入初中免试就近入学工作的实施意见》（教基一厅〔2014〕1号）；各城市教育局学区划分方案","consumerBenefit":"搞清划片模式再买房，不买了上不了对口学校","tags":{"clientType":["buyer"],"stage":"pre","layer":["道"],"meetingPhase":["见前"]},"alias":["学区怎么划定的","单校划片和多校划片区别","学区划分由谁决定"]},{"id":"PRE-SCH-003","name":"多校划片随机派位公平吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"我们这边多校划片，买学区房还能保证上好学校吗？","ola":"不能保证，随机派位中签率10%-30%，选整体好片区更稳","cp":["学区溢价30%-40%降至15%-25%","对口多校随机派位入学","热门校中签率10%-30%","选整体好片区降低风险","不赌单校选片区均衡"],"detail":"多校划片下，一个小区对口多所学校（含优质校和普通校），通过电脑随机派位决定入学，家长无法确保孩子进入优质校。中签率取决于优质校在该划片中的招生名额与申请人数之比，热门学校中签率可能仅10%-30%。多校划片对学区房价格的影响：核心学区房溢价从原来的30%-40%降至15%-25%，但仍是购房重要考量。应对策略：选择对口学校整体水平较高的片区（即使派位也不差），而非只赌一所名校。","legalRef":"《教育部办公厅关于进一步做好小学升入初中免试就近入学工作的实施意见》（教基一厅〔2014〕1号）","consumerBenefit":"不赌单校运气，选片区均衡降低派位风险","tags":{"clientType":["buyer"],"stage":"pre","layer":["道"],"meetingPhase":["见前"]},"alias":["多校划片能上好学校吗","随机派位中签率多少","多校划片学区房还值吗"]},{"id":"PRE-SCH-006","name":"学区划片调整了房子会不会白买","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买了学区房之后如果划片变了怎么办？","ola":"政府有权调整无法索赔，房价可能跌10%-30%","cp":["学区调整是最大政策风险","政府有权调整业主无法索赔","调出名校房价可能跌10%-30%","选教育均衡片区降低风险","合同学区承诺对政府调整无效"],"detail":"学区划片调整是学区房最大的政策风险。调整方式：单校划片改为多校划片、学校合并撤销、新增学校改变划片范围。法律上政府有权根据教育资源变化调整学区，业主无法因学区调整主张赔偿。对房价的影响：优质学区被调出对应范围，房价可能下跌10%-30%。防范措施：选择教育资源整体均衡的片区、关注教育局每年招生方案。","legalRef":"《义务教育法》第12条（就近入学）；各城市教育局学区调整公告","consumerBenefit":"知道学区调整风险，不把全部赌注押在一所学校上","tags":{"clientType":["buyer"],"stage":"pre","layer":["术","道"],"meetingPhase":["见前"]},"alias":["学区调整风险","对口学校变了怎么办","划片调整能维权吗"]},{"id":"PRE-SCH-016","name":"划片调整房价暴跌怎么办","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"万一买了学区房之后被划出学区，房价会跌多少？","ola":"真实案例3月跌25%，政府调整无法索赔，选均衡片区降风险","cp":["学区调整房价3月跌25%真实案例","政府行政行为业主无权索赔","合同学区条款不约束政府","起诉教育局基本不支持","选教育均衡片区降低依赖"],"detail":"真实案例：北京某小区原对口某重点小学，2023年区教育局宣布改为多校划片，该小区房价3个月内从12万/㎡跌至9万/㎡，跌幅25%。法律分析：政府调整学区属行政行为，业主无权因学区调整要求政府赔偿；购房合同中即使有学区条款也仅约束卖方不约束政府。个别案例中业主起诉教育局要求撤销学区调整，法院以「行政行为合理性审查」为由基本不支持。应对策略：选择教育资源整体均衡的片区，降低对单一学校的依赖度。","legalRef":"《行政诉讼法》第70条（行政行为合法性审查）；各城市教育局学区调整决定","consumerBenefit":"不把全部身家押在一所名校上，均衡片区更抗跌","tags":{"clientType":["buyer"],"stage":"pre","layer":["器","道"],"meetingPhase":["见前"]},"alias":["学区调整房价下跌案例","对口学校变了房价跌多少","学区房被调出名校范围"]},{"id":"PRE-SCH-020","name":"深圳积分入学怎么算","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"深圳积分入学怎么算？买学区房能加多少分？","ola":"深户+购房100分最高，非深户+租房仅60分，社保累积加分","cp":["深户+购房基础分最高100分","非深户+租房仅60分差距大","社保/户籍时间可加分","学位锁定小学3年初中3年","尽早入深户+购房累积加分"],"detail":"深圳实行积分入学制度，按户籍/房产/社保/居住证等项目累计积分，按积分高低依次录取。基础积分规则：深户+购房=满分基础分100分、深户+租房=80分、非深户+购房=75分、非深户+租房=60分。加分项：社保每满1月加0.1分、户籍迁入时间每满1月加0.1分、双居住证加5分。学区锁定：学位申请成功后该地址6年内锁定（小学3年/初中3年）。策略：尽早迁入深户+购房获取最高基础分，社保不断缴累积加分。","legalRef":"《深圳市义务教育阶段学校招生入学工作指导意见》深教〔2024〕号；各区积分入学实施办法","consumerBenefit":"算清积分排好位，入学有保障","tags":{"clientType":["buyer"],"stage":"pre","layer":["道"],"meetingPhase":["见前"]},"alias":["深圳学区积分规则","深圳入学积分计算","深圳学区房积分排名"]},{"id":"PRE-SCH-023","name":"买学区房到底是买小学还是初中","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买学区房应该重点看小学还是初中？","ola":"小学确定性高优先选，九年一贯制最稳","cp":["小学单校划片确定性高","初中多校划片确定性低","九年一贯制确定性最高","根据孩子年龄选优先级","小学初中学区可能不重叠"],"detail":"学区房选择需区分小学学区和初中学区。小学学区实行单校划片，一套房对应一所小学；初中学区多数城市实行多校划片或对口直升，确定性低于小学。九年一贯制学校的小学部可直升初中部，确定性最高但竞争也最激烈。选小学还是初中学区取决于孩子年龄：幼儿园阶段选小学学区更紧迫；小学阶段关注初中学区。部分城市小学和初中学区不完全重叠，需分别核实。","legalRef":"《义务教育法》第12条","consumerBenefit":"选对学区阶段，花钱买到真正需要的学区资源","tags":{"clientType":["buyer"],"stage":"pre","layer":["术"],"meetingPhase":["见前"]},"alias":["学区房小学和初中哪个重要","买小学学区还是初中学区","小学和初中学区房怎么选"]},{"id":"PRE-SCH-025","name":"学区房购买时间有什么讲究","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"孩子明年上小学，现在买学区房来得及吗？","ola":"热门学区来不及，需提前1.5-2年，当年买风险大","cp":["热门学校要求落户1-3年","交易到落户约3-4个月","建议至少提前1.5-2年购买","热门学区提前2-3年","入学当年购买风险极大"],"detail":"学区房购买时机需考虑三个时间节点：一是落户年限要求，部分热门学校要求落户1-3年甚至更久，落户时间不足可能被调剂；二是交易周期，二手房交易从签约到过户约2-3个月，过户到落户约1个月；三是入学报名时间通常在每年5-6月。综合以上，建议至少提前1.5-2年购买学区房，热门学区提前2-3年。入学当年购买风险极大，可能因落户时间不足无法入学。","legalRef":"《义务教育法》第12条","consumerBenefit":"提前规划不因落户时间不足被调剂","tags":{"clientType":["buyer"],"stage":"pre","layer":["法"],"meetingPhase":["见前"]},"alias":["学区房提前多久买","买学区房最佳时间","入学当年买学区房来得及吗"]},{"id":"PRE-SCH-026","name":"租房能上对口学校吗和买房差在哪","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"不买房只租房，孩子能上这个小区对口的学校吗？","ola":"排序低于购房家庭，热门学校基本进不去，可能被调剂","cp":["购房入学排序高于租房","热门学校租房基本进不去","租房可能被调剂到其他学校","租购同权保障有学上不保证对口","积分制城市购房积分高于租房"],"detail":"多数城市入学政策中，购房和租房的入学排序有差异。北京入学排序为：有房有户>有户无房>有房无户>无房无户（租房）。上海实行积分制，购房积分高于租房。深圳按类别+积分，购房属于第一类，租房属于较低类别。核心区别：购房入学对口学校确定性强，租房可能被调剂到周边有空位的学校；热门学校通常购房家庭已满，租房家庭基本无法进入。'租购同权'政策主要保障租房子女有学上，但不保证上对口热门学校。","legalRef":"《义务教育法》第12条","consumerBenefit":"了解租购房入学差异，做对学区选择","tags":{"clientType":["buyer"],"stage":"pre","layer":["道"],"meetingPhase":["见前"]},"alias":["租房能上好学校吗","租房和买房学区待遇差别","租购同权入学一样吗"]},{"id":"PRE-SCH-028","name":"多校划片后学区房还值得买吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"现在都是多校划片了，学区房还值得买吗？","ola":"确定性下降溢价缩水，选优质学区群而非单一名校","cp":["多校划片确定性大幅下降","名校周边溢价可能收缩10%-30%","优质学区群房源仍有价值","优先选学区群而非单一名校","3年内入学且单校划片可考虑"],"detail":"多校划片是指一个小区对应多所学校，通过随机派位决定入学学校，不再一对一对应。多校划片对学区房的影响：确定性下降，买房不再保证上指定学校；名校周边学区房溢价可能收缩10%-30%；但优质学区群（多所好学校聚集区域）的房源仍有价值。选择策略：优先选择优质学区群而非单一名校；了解当地多校划片的具体执行力度（有的城市名义多校实际仍偏向名校）；如3年内有入学需求且当地尚为单校划片，可考虑购买。","legalRef":"《义务教育法》第12条","consumerBenefit":"理解多校划片影响，理性决策不盲目追学区","tags":{"clientType":["buyer"],"stage":"pre","layer":["术"],"meetingPhase":["见前"]},"alias":["多校划片后买学区房还有意义吗","多校划片对学区房影响多大","多校划片还能确定上好学校吗"]},{"id":"PRE-SCH-CASE-002","name":"中介承诺买学区房包上名校没考上能退钱吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"中介当时拍胸脯说肯定能上名校，结果被调剂了，我能要回中介费吗？","ola":"中介无法控制入学，包上学承诺多无效。","cp":["入学受政策多重影响","中介无法控制入学","口头承诺举证困难","包上学承诺通常无效"],"detail":"李某通过某中介购买学区房，中介业务员口头承诺“保证能上某名校，上不了退中介费”。后李某孩子被调剂。李某起诉中介要求退还中介费。法院认为，入学资格受教育部门政策及户籍等多重因素影响，中介无法控制，其“包上名校”承诺违反客观规律，且无书面证据，判决驳回李某诉求。","legalRef":"《中华人民共和国民法典》第九百六十一条","consumerBenefit":"警惕中介口头“包上学”承诺，避免维权时缺乏证据。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["中介包上名校能退钱吗","学区房中介虚假承诺","承诺包上学没上成退钱"]},{"id":"PRE-SCH-CASE-003","name":"买学区房发现是商业性质不能落户上学怎么退","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买了才发现是商业公寓不能落户上学，我能要求退房并赔偿吗？","ola":"商业性质无法落户入学，可主张根本违约退房。","cp":["商业性质无法落户","无法入学属根本违约","隐瞒性质可解除合同","购房目的落空可索赔"],"detail":"王某购买一套低价“学区房”，签约后发现房屋规划用途为“商业/办公”，无法落户及入学。王某以中介和卖家隐瞒房屋性质为由起诉解除合同并索赔。法院认定，王某购房核心目的为子女入学，商业性质房屋客观上无法实现该目的，构成根本违约，判决解除合同，卖家退还全款并支付违约金。","legalRef":"《中华人民共和国民法典》第五百六十三条","consumerBenefit":"签约前核实房屋规划用途，避免买入无法落户上学的商办类房屋。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["商业性质学区房能退吗","买商住房不能落户上学","公寓性质学区房能退吗"]},{"id":"PRE-SCH-CASE-005","name":"为了孩子赶时间买学区房贷款下不来算违约吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"为了孩子上学着急买房，结果贷款没批下来，算我违约吗？","ola":"贷款未获批非不可抗力，买方违约定金不退。","cp":["贷款拒批非不可抗力","买方需评估贷款能力","无法全款属买方违约","违约定金不予退还"],"detail":"孙某为赶孩子入学报名，急购学区房并交定金。因孙某流水不足，银行拒批贷款。孙某无法全款支付，卖家没收定金。孙某起诉要求退还。法院认为，贷款未获批非不可抗力，孙某未充分评估自身贷款能力导致合同无法履行，构成违约，判决驳回孙某诉求，定金不予退还。","legalRef":"《中华人民共和国民法典》第五百八十七条","consumerBenefit":"提醒买方在签约前确认贷款资质，避免因贷款失败导致定金损失。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["学区房贷款下不来算违约吗","赶时间买学区房贷款拒批","买学区房贷款批不下来"]},{"id":"PRE-SCH-CASE-006","name":"买学区房发现是共有产权房不能落户上学怎么退","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买了才发现是共有产权房，不能落户也不能上学，这合同能撤销吗？","ola":"共有产权房无法落户入学，可主张重大误解撤销。","cp":["共有产权房禁迁户口","无法入学属重大误解","未告知特殊性质可撤销","撤销后退还购房全款"],"detail":"刘某购买一套“学区房”，签约后得知该房屋为共有产权住房，政策规定共有产权房不得办理户口迁入，子女无法按划片入学。刘某起诉要求撤销合同。法院认为，卖家及中介未告知房屋为共有产权性质，导致刘某落户入学目的落空，构成重大误解，判决撤销合同，退还购房款。","legalRef":"《中华人民共和国民法典》第一百四十七条","consumerBenefit":"识别共有产权房等特殊性质房屋的落户限制，避免买入后无法入学。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["共有产权房能落户上学吗","买共有产权房不能上学","共有产权房学区房能退吗"]},{"id":"PRE-SCH-CASE-008","name":"交定金后买学区房发现片区被划出学区能退定金吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"刚交完定金，教育局就把这个小区划出学区了，我的定金能要回来吗？","ola":"学区划片调整属政策变化，可要求全额退定金。","cp":["学区调整属政策变化","非双方违约可解约","合同目的无法实现","卖家需全额退还定金"],"detail":"吴某交定金购买学区房，次日教育局发布新政，该小区被划出原名校学区。吴某要求退还定金。卖家同意退房但拒绝退定金。吴某起诉。法院认为，学区划片调整属于不可归责于双方的政策变化，导致合同目的无法实现，不属于任何一方违约，判决解除合同，卖家全额退还定金。","legalRef":"《中华人民共和国民法典》第五百三十三条","consumerBenefit":"明确突发政策变动下的定金处理规则，避免政策风险导致的定金损失。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["划出学区能退定金吗","交定金后学区调整","买学区房学区被划走"]},{"id":"PRE-SCH-CASE-011","name":"买学区房发现是查封状态无法过户耽误孩子上学能索赔吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买了学区房才发现房子被法院查封了，过不了户耽误孩子上学，能索赔吗？","ola":"隐瞒查封致无法过户，可解约退房并索赔违约金。","cp":["隐瞒查封属根本违约","无法过户致目的落空","合同解除退还首付款","可主张违约金赔偿"],"detail":"马某购买学区房并支付首付，准备过户时发现房屋因卖家债务纠纷被法院查封，无法过户，导致其子女错过入学报名。马某起诉卖家要求解除合同、退还首付并赔偿延期入学损失。法院认定，卖家隐瞒房屋被查封事实，导致合同目的无法实现，判决解除合同，退还首付，并赔偿马某违约金。","legalRef":"《中华人民共和国民法典》第五百六十三条","consumerBenefit":"签约前务必进行产权核验，避免买入查封房导致钱房两空。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["查封房耽误上学能索赔吗","买学区房发现被查封","房屋查封无法过户上学"]},{"id":"OWN-OWN-CASE-034","name":"业主自住房屋满五唯一，但实际有隐性债务未结清，出售时有什么风险？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东的房子满五唯一，但我听说他有隐性债务，我买这房子有什么风险？","ola":"隐性债务易引发突发查封，导致无法过户及违约赔偿。","cp":["隐性债务随时可能引发查封","查封导致无法过户构成违约","业主需承担高额违约赔偿责任","建议交易前进行背景尽职调查"],"detail":"业务场景：业主自住房屋符合“满五唯一”免税条件，但业主存在民间借贷、担保等隐性债务，债权人可能随时申请财产保全。判断要点：隐性债务未体现在房产证上，但在交易过程中，若债权人起诉并申请查封，房屋将无法过户。关键风险在于交易周期内突发查封导致违约，业主不仅需退还定金，还可能承担高额违约金。","legalRef":"《中华人民共和国民法典》第五百七十七条","consumerBenefit":"识别隐性债务风险，采取资金监管或产调措施保障交易安全。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["满五唯一但有隐性债务出售有什么风险","自住房有未结清隐性债务卖房风险","房屋有隐性债务没结清出售会怎样"]},{"id":"OWN-VAL-CASE-034","name":"房屋带租约出售业主如何核算租金收益支撑溢价估值","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"房子带租约卖，怎么算租金收益让买家接受高估值？","ola":"核算净租金收益，用资本化率法推算并展示租客资质。","cp":["核算剩余租期及租金递增条款","使用资本化率法推算收益价值","展示租客优质资质降低空置担忧","对比市场租售比验证估值合理性"],"detail":"对于带租约出售的投资型房产，租金收益是支撑其估值溢价的核心。操作流程上，业主需核算当前租约的剩余期限、租金递增条款及租客履约信用。通过资本化率法，将年净租金收益除以市场合理回报率，推算出房屋的收益价值。同时，需向买家展示租客的优质资质，降低买家对空置期的担忧。关键决策因素是租金的真实性、租约的稳定性及当前市场租售比。","legalRef":"《中华人民共和国民法典》第一百七十六条","consumerBenefit":"掌握收益法估值逻辑，有效向买家传递带租约房产的投资价值。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["带租约卖房怎么计算租金收益来支撑高估值","房子带租约出售如何核算租金支撑溢价估值","带租约的房子怎么算租金收益让买家接受高估值"]},{"id":"PRE-NEED-137","name":"买学区房到底是为了孩子上学还是为了投资赚钱？（PRE-NEED）","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"客户一直问学区房价能涨多少，怎么判断他是不是纯投资？","ola":"问涨幅和转手周期多为投资，问学校细节多为自住。","cp":["关注涨幅多为投资","关注学校细节为自住","测试真实购房意图","防范政策变动风险","避免推荐房源错配"],"detail":"情境：客户强调要买学区房，但频繁询问未来涨幅和转手周期。判断依据：若客户对划片学校细节不关心，只关注租金回报和倒挂空间，多为投资客。行动建议：经纪人需通过提问测试其真实意图，若为投资需提示学区政策变动风险。风险提示：误判会导致推荐错配，投资客买自住型学区会嫌溢价高，刚需买投资型会忽略居住体验。","legalRef":"行业惯例及《房地产经纪管理办法》第二十一条","consumerBenefit":"精准匹配真实需求，避免买错房导致资金或时间浪费。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["学区房投资还是自住","买学区房怎么判断真实目的","学区投资与自住如何区分"]},{"id":"PRE-NEED-142","name":"买学区房怎么防范学区划分调整的风险？（PRE-NEED）","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"买学区房怎么保证一定能上对口学校？","ola":"无绝对保证，需核实多校划片政策并告知调剂风险。","cp":["核实最新划片政策","警惕多校划片趋势","查阅教育局官方文件","明确告知调剂风险","防范高价接盘落空"],"detail":"情境：客户高价买入老破小纯为学区，但该区正推行多校划片。判断依据：教育局近年政策倾向于教育资源均衡化，单校划片逐步取消。行动建议：经纪人必须查阅最新教育局文件，明确告知多校划片概率及调剂风险。风险提示：隐瞒政策风险会导致客户高价接盘后学位落空，引发重大纠纷。","legalRef":"《中华人民共和国民法典》第五百条","consumerBenefit":"提前规避政策变动风险，避免高价买学区却无学可上。","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前"]},"alias":["学区房政策变动风险","买学区房怕被划出去","学区划分调整怎么办"]},{"id":"PRE-NEED-CASE-148","name":"买一楼带院子的养老房，能自己改造无障碍设施吗？（PRE-NEED）","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"买一楼带院子，我能自己建个轮椅坡道吗？","ola":"需物业和城管审批，私自扩建属违建面临强拆风险。","cp":["核实改造合规边界","警惕私自扩建违建","建议买适老化成品房","提前咨询物业城管","防范强拆损失风险"],"detail":"情境：客户买一楼带院子准备给父母养老，想私自扩建无障碍坡道或封闭院子。判断依据：小区外立面及公共绿地改造需经物业及城管审批，私自改造属违建。行动建议：经纪人需提前告知改造合规边界，建议购买内部已做适老化设计的房源。风险提示：私自改造会被城管强拆，不仅损失装修费，还可能影响房屋交易。","legalRef":"《中华人民共和国城乡规划法》第四十条","consumerBenefit":"避免盲目改造导致违建被拆，保障养老居住安全。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["养老房适老化改造限制","一楼院子能改无障碍通道吗","买房后适老化改造规定"]},{"id":"PRE-RISK-094","name":"房子带学区但政策刚改划片怎么办？（PRE-RISK）","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"卖家说这房子肯定能上对口小学，结果政策变了划到别的学校，我能退房吗？","ola":"需查阅官方文件，合同中必须约定学区变动的解约条款。","cp":["查阅教育局最新文件","合同约定政策变动条款","口头承诺学区无效","防范多校划片风险"],"detail":"教育资源分配受政策影响极大，多校划片或教师轮岗政策可能导致原定学区失效。判断依据是当地教育局最新发布的招生划片文件及落户年限要求。行动建议是在合同中明确约定若因政策原因导致无法就读目标学校，买家有权解除合同或要求降价。风险提示：中介或卖家口头承诺的“包上学”无法律效力，必须查阅官方最新文件。","legalRef":"《中华人民共和国民法典》第五百四十三条、《义务教育法》第十二条","consumerBenefit":"避免高价买入学区房却因政策变动无法就读目标学校。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["学区房政策变了划片改了怎么办","买学区房发现被划出学区能退吗","多校划片政策下买学区房风险"]},{"id":"OWN-SEL-DEEP-008","name":"卖房挂牌多久卖不掉就该调价了","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"房子挂了1个多月了还没卖掉，要不要降价？（从租客/买家角度）","ola":"2周无看房需警觉，1月无报价降3%-5%。","cp":["告诉业主卖房调价时间节点","1.挂牌2周看房量<5组→说明定价偏.…","提醒业主调价不是认输","是适应市场"],"detail":"本词条涉及出售决策领域的STD类问题。告诉业主卖房调价时间节点：1.挂牌2周看房量<5组→说明定价偏高 2.1个月无人出价→建议降价3%-5% 3.3个月未成交→需重新评估定价策略。提醒业主调价不是认输，是适应市场。。该问题属于soft级别，属于行业惯例范畴。","legalRef":"行业通行做法","consumerBenefit":"获取行业经验参考，做出更优决策。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["卖房挂牌多久卖不掉就该调价了","房子挂多久没卖掉要降价","卖房多久不出手需调价"]},{"id":"OWN-OPS-DEEP-006","name":"持有空置房每月成本多少该卖还是该租","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"房东空着房子不租，物业费怎么算？","ola":"月租超持有成本则租，否则考虑出售。","cp":["帮业主算空置持有成本","1.物业费","2-8元/㎡/月 2.折旧","每年2%-5% 3.资金成本","按当前贷款利率算 4.机会成本"],"detail":"本词条涉及资产运营领域的STD类问题。帮业主算空置持有成本：1.物业费：2-8元/㎡/月 2.折旧：每年2%-5% 3.资金成本：按当前贷款利率算 4.机会成本：卖掉变现后投资收益。决策模型：月租>持有成本+合理回报→租；月租<持有成本→。该问题属于soft级别，属于行业惯例范畴。","legalRef":"行业通行做法","consumerBenefit":"获取行业经验参考，做出更优决策。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["空置房持有成本计算","房子空着还是租出去划算","空置房产卖还是租"]},{"id":"OWN-CASE-RNT-002","name":"租客擅自装修退租要求补偿装修费被驳回案例","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"我装修了出租房退租时能要补偿吗？","ola":"未经同意装修属违约，无权要求补偿。","cp":["未经同意装修属违约","无权要求补偿装修费","还需承担恢复原状费用","装修需提前书面同意"],"detail":"租客何某未经房东郑某同意，花费5万元对出租房进行精装修。退租时何某要求郑某补偿装修费用，郑某拒绝。法院认定：何某未经同意装修属于违约行为，郑某有权要求恢复原状，何某无权要求补偿装修费用。何某还需承担恢复原状的费用。","legalRef":"《中华人民共和国民法典》第七百一十五条","consumerBenefit":"参考判例明确权利义务。","tags":{"clientType":["landlord","seller","tenant"],"stage":"post","layer":"器","meetingPhase":["见前","见中","见后"]},"alias":["租客擅自装修退租要求补偿装修费被驳回判例","租客擅自装修退租要求补偿装修费被驳回案例","租客擅自装修退租要求补偿装修费被驳回"]},{"id":"OWN-CASE-RNT-005","name":"出租房燃气泄漏致租客中毒房东被判赔偿案例","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"出租房燃气泄漏我中毒了，房东要赔吗？","ola":"房东未检修全赔，医疗费+精神损害。","cp":["房东有安全交付义务","燃气属房东维修责任","未检查出事故全赔","精神损害也要赔"],"detail":"房东韩某将使用15年的老房子出租，未做燃气安全检查。租客蒋某因燃气软管老化泄漏导致一氧化碳中毒，医疗费2万元。蒋某起诉韩某赔偿，法院认定韩某作为房东有提供安全居住环境的义务，燃气设施属于房东维修责任范围，判决韩某赔偿医疗费2万元+精神损害抚慰金5000元。","legalRef":"《中华人民共和国民法典》第七百零八条、第一千一百七十九条","consumerBenefit":"了解法院裁判规则，预判维权结果。","tags":{"clientType":["landlord","seller","tenant"],"stage":"post","layer":"器","meetingPhase":["见前","见中","见后"]},"alias":["出租房燃气泄漏致租客中毒房东被判赔偿案例","出租房燃气泄漏致租客中毒房东被判赔偿","出租房燃气泄漏致租客中毒房东被判赔偿判例"]},{"id":"OWN-CASE-RNT-007","name":"租客养犬咬伤邻居房东连带赔偿案例","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"被出租房的狗咬了，房东也要赔吗？","ola":"明知不制止担20%次责，合同可免责。","cp":["动物伤人饲养人主责","房东明知不制止担次责","合同约定宠物条款可免责","养宠物必须约束管理"],"detail":"租客方某在出租房内饲养大型犬，犬只逃出咬伤邻居曹某。曹某同时起诉方某和房东范某，要求赔偿医疗费1.5万元。法院认定：方某作为动物饲养人承担主要责任(80%)；范某作为房东在合同中未约定宠物条款且明知租客养犬未制止，承担次要责任(20%)。","legalRef":"《中华人民共和国民法典》第一千二百四十五条、第一千二百四十六条","consumerBenefit":"参考判例明确权利义务。","tags":{"clientType":["landlord","seller","tenant"],"stage":"post","layer":"器","meetingPhase":["见前","见中","见后"]},"alias":["租客养犬咬伤邻居房东连带赔偿判例","租客养犬咬伤邻居房东连带赔偿案例","租客养犬咬伤邻居房东连带赔偿"]},{"id":"PRE-NEED-153","name":"养老房适老化改造预算速算","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"适老化改造大概要花多少钱","ola":"3档：2-5千/8千-2万/3-8万，补贴后降50-80%","cp":["基础安全档2-5千","标准舒适档8千-2万","品质提升档3-8万","补贴后支出降50-80%"],"detail":"3档预算速算：基础安全档(2000-5000元)：防滑处理加2处扶手加感应灯加紧急呼救装置加门把手更换；标准舒适档(8000-20000元)：基础档加蹲便改坐便加淋浴椅加干湿分离加插座开关改造加智能门锁；品质提升档(30000-80000元)：标准档加房门拓宽加推拉门加适老家具加恒温花洒加全屋智能。叠加补贴后实际支出可降50%-80%。","legalRef":"住建部《城市居家适老化改造指导手册》附件1-2；《无障碍环境建设法》第26条","consumerBenefit":"心中有数不超预算，叠加补贴更省钱","tags":{"clientType":["agent","buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前","见中"]},"alias":["适老改造预算速算","适老改造3档预算","适老化改造费用估算"]},{"id":"PRE-RNT-004","name":"首次租房必须确认的七项需求","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"第一次租房不知道该确认什么？","ola":"预算通勤户型配套安全特殊需求租期，七项先列清","cp":["七项必确认需求","带看前逐项核对","避免无效带看","需求表先行"],"detail":"首次租房客户常因经验不足遗漏关键需求，入住后才发现不便。七项必确认需求：①预算上限（含隐性成本）②通勤距离（单程≤45min）③户型要求（几居/朝向/面积）④生活配套（超市/医院/快递）⑤安全要求（门禁/监控/楼层）⑥特殊需求（宠物/做饭/储物）⑦租期预期（短租/长租/可转租）。经纪人应在带看前用七项需求表逐项确认，避免带看不匹配的房源浪费双方时间。","legalRef":"无直接法条","consumerBenefit":"系统化确认需求避免遗漏","tags":{"clientType":["tenant"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["租房需求清单","首次租房注意","租房必备需求"]},{"id":"P2-C1-001","name":"买学区房就能上对口学校吗","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"我花大价钱买了学区房，孩子就一定能上对口学校吗？","ola":"不一定，需满足户籍和招生政策要求。","cp":["就近入学以户籍为准","学区房不等于保入学","需满足招生顺位要求"],"detail":"义务教育法规定适龄儿童在户籍所在地就近入学，但「就近」不等于「对口」。各地实行划片入学政策，学区房只是入学条件之一，还需满足户籍、落户年限、顺位等要求。多校划片区域购房后还需电脑派位，不保证入读特定学校。买前务必核实当年招生政策，切勿轻信「买房保入学」承诺。","legalRef":"《中华人民共和国义务教育法》第十二条","consumerBenefit":"了解学区房入学真实规则，避免盲目购房。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["学区房一定能上对口学校吗","买了学区房就能入学吗","学区房是否保证入学"]},{"id":"P2-C1-002","name":"学区划分是按什么标准来的","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"学区到底是怎么划分的，有没有统一标准？","ola":"按适龄人口和学校分布划片。","cp":["以人口分布为基础","结合学校容量划片","区县教育部门制定"],"detail":"学区划分由区县级教育行政部门负责，主要依据区域内适龄儿童人口数量、学校分布和学位供给情况综合划定。划分原则是就近入学，但「就近」并非直线距离最近，而是综合考虑道路、安全、学位等因素。各地每年会根据实际情况动态调整学区范围并公布。","legalRef":"教育部《关于进一步做好小学升入初中免试就近入学工作的实施意见》","consumerBenefit":"了解学区划分逻辑，判断房源是否在目标学区内。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["学区划分依据什么","学区怎么划分的","学区划片标准是什么"]},{"id":"P2-C1-006","name":"多校划片是什么意思","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"听说现在搞多校划片，到底是什么意思？","ola":"一个小区对应多所学校，电脑派位入学。","cp":["一个学区对应多所学校","通过电脑随机派位分配","不再锁定单一对口学校"],"detail":"多校划片是指将一个小区或片区对应多所学校，适龄儿童通过电脑随机派位方式分配入学，不再锁定单一对口学校。该政策旨在促进教育公平，缓解学区房热。北京城六区已推行多校划片，新购房业主子女入学适用该政策。派位结果具有随机性，无法保证入读特定学校。","legalRef":"教育部《关于进一步做好小学升入初中免试就近入学工作的实施意见》","consumerBenefit":"理解多校划片机制，评估学区房入学不确定性。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["多校划片政策解读","多校划片是什么","多校划片怎么理解"]},{"id":"P2-C1-009","name":"多校划片和单校划片哪个好","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"多校划片和单校划片到底哪个对我们有利？","ola":"各有优劣，单校确定性强，多校促公平。","cp":["单校划片入学确定性强","多校划片促进教育公平","选择取决于个人需求"],"detail":"单校划片一个小区对应一所学校，入学确定性强但推高学区房价格；多校划片通过随机派位分配，促进教育公平但入学不确定性增加。对家长而言，单校划片便于规划但成本高，多校划片降低购房门槛但有随机风险。选择哪种方式取决于个人对确定性和成本的权衡。","legalRef":"各地义务教育招生入学政策对比","consumerBenefit":"对比两种划片模式，做出合理教育规划。","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前"]},"alias":["多校划片和单校划片对比","多校划片好还是单校划片好","单校划片和多校划片区别"]},{"id":"P2-C1-012","name":"怎么查房子学位有没有被占用","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"我想买这套学区房，怎么查它的学位有没有被占用？","ola":"可向学校或教育部门查询学位使用情况。","cp":["向对口学校咨询查询","联系区县教育部门","部分城市支持线上查询"],"detail":"查询房产学位是否被占用可通过以下途径：一是直接联系对口学校咨询学位使用记录；二是联系区县教育部门查询；三是部分城市已开通线上学位查询服务。购房前务必查询，若学位已被占用且未满六年，子女入学将受影响。建议在购房合同中约定学位未占用条款以保障权益。","legalRef":"各地学位查询服务规定及实施细则","consumerBenefit":"掌握学位查询方法，购房前规避风险。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["查询学位是否被占用","房子学位占用怎么查","学位使用情况查询"]},{"id":"P2-C1-015","name":"租房入学会占房东的学位吗","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"如果我租房入学，会占用房东的学位名额吗？","ola":"视当地政策，部分城市会占用。","cp":["部分城市租房入学占学位","可能影响房东子女入学","需提前与房东确认"],"detail":"租房入学是否占用房东学位因城市而异。部分城市如北京，租房入学使用的是该房产的学位，若六年一学位政策适用，则租房入学会占用房东的学位名额，可能影响房东子女入学。建议租房前与房东充分沟通，了解学位使用情况，并在租赁合同中明确学位使用相关条款。","legalRef":"各地随迁子女入学政策及学位使用规定","consumerBenefit":"明确租房入学对学位的影响，避免纠纷。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["租房入学影响房东学位吗","租房上学占不占学位","租客入学是否消耗学位"]},{"id":"P2-C1-019","name":"孩子几岁可以上小学","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"孩子几岁可以上小学？有没有硬性年龄规定？","ola":"年满六周岁应当入学接受义务教育。","cp":["年满六周岁应入学","部分地区可放宽至六岁半","以当年8月31日为截止"],"detail":"《义务教育法》规定凡年满六周岁的儿童应当入学接受义务教育。各地执行中通常以当年8月31日为年龄截止日，即9月1日前满六周岁的儿童当年入学。部分地区允许条件不具备的地区推迟至七周岁。家长需关注当地教育部门发布的入学年龄要求，按时进行信息采集和报名。","legalRef":"《中华人民共和国义务教育法》第十一条","consumerBenefit":"明确入学年龄规定，按时办理入学手续。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["小学入学年龄规定","孩子多大上小学","小学入学几岁"]},{"id":"P2-C1-021","name":"买了学区房多久能入学","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"买了学区房后，孩子多久能入学？有时间要求吗？","ola":"需提前购房并落户，一般要求一年以上。","cp":["需提前购房并迁入户口","部分城市要求满一年","热门学区要求更长时间"],"detail":"买了学区房后入学时间取决于当地政策。多数城市要求购房并落户满一定时间方可享受对口入学，通常为一年以上。热门学区可能要求更长落户年限。多校划片区域新购房需按多校划片政策入学。建议在孩子入学前至少一年至两年完成购房和落户，确保满足各项时间要求。","legalRef":"各地义务教育招生入学实施细则（购房入学时间要求）","consumerBenefit":"了解购房入学时间要求，提前做好规划。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["购房后多久能入学","学区房入学时间要求","买房后入学等待期"]},{"id":"P2-C3-002","name":"转学需要什么条件","domain":"学区教育","subScene":"教育规划","scene":"学区教育·教育规划","cq":"想给孩子转学，需要满足什么条件？怎么办理？","ola":"需符合户籍或房产变更等条件并申请。","cp":["需户籍或房产变更等理由","经双方学校和教育部门同意","受学位空余情况限制"],"detail":"转学需满足一定条件，通常包括户籍迁移、房产变更、父母工作调动等正当理由。办理流程为：先向转入学校提交申请并获得同意，再由转出学校和教育部门审批。转学受目标学校学位空余情况限制，热门学校通常无空余学位。部分城市规定学期中不予转学，仅在寒暑假办理。建议提前了解当地转学政策并准备相关材料。","legalRef":"《中小学生学籍管理办法》及各地转学实施细则","consumerBenefit":"了解转学条件和流程，顺利办理手续。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["转学条件是什么","怎么办理转学","转学需要哪些手续"]},{"id":"P2-C3-009","name":"二孩上学能跟大孩同校吗","domain":"学区教育","subScene":"教育规划","scene":"学区教育·教育规划","cq":"大孩已经在这所学校上学，二孩能申请同校吗？","ola":"部分地区支持「长幼随学」可申请同校。","cp":["多地推出长幼随学服务","需满足条件并提前申请","二孩不受学位限制"],"detail":"部分地区已推出「长幼随学」服务，允许二孩申请与大孩同校入学。2025年浙江等地明确支持二孩同校申请。同时六年一学位政策通常豁免二孩三孩，不影响同校入学资格。具体条件因地区而异，一般需大孩在读且二孩符合入学年龄。建议提前向学校和教育部门咨询申请条件和流程，尽早提交申请。","legalRef":"各地「长幼随学」服务政策","consumerBenefit":"了解长幼随学政策，争取二孩同校入学。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["二孩能跟大孩同校吗","二孩同校入学","长幼随学政策"]},{"id":"P2-C3-010","name":"学区划分有争议怎么申诉","domain":"学区教育","subScene":"教育规划","scene":"学区教育·教育规划","cq":"对学区划分不满意，有什么途径可以申诉？","ola":"可向教育部门提出书面异议或申诉。","cp":["向区县教育部门提出异议","提供相关证明材料","申诉不影响正常入学"],"detail":"对学区划分有争议可向区县教育部门提出书面异议或申诉。申诉时需提供户籍证明、房产证明等相关材料，说明争议理由和诉求。教育部门会根据政策规定和实际情况进行审查并回复。申诉期间不影响孩子正常入学报名。若对处理结果不满，可进一步向上级教育主管部门反映。建议理性申诉，了解政策依据。","legalRef":"各地义务教育招生入学申诉处理办法","consumerBenefit":"掌握学区争议申诉途径，维护入学权益。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["学区划分争议申诉","学区划分不满怎么办","学区划分申诉途径"]},{"id":"P2-C3-015","name":"陪读租房怎么规划","domain":"学区教育","subScene":"教育规划","scene":"学区教育·教育规划","cq":"为了孩子上学想在学区附近租房陪读，怎么规划？","ola":"提前调研、控制预算、确保租赁合法。","cp":["提前调研学校周边房源","控制租金在合理范围","确保租赁备案合规"],"detail":"陪读租房规划建议：一是提前调研学校周边房源和租金水平，了解通勤距离和居住环境；二是控制租金预算在家庭收入合理比例内；三是确保签订正规租赁合同并办理租赁备案，部分城市租房入学需要备案证明；四是考虑租期灵活性，避免长期绑定；五是关注社区安全和生活便利性。建议提前两至三个月开始找房。","legalRef":"综合教育规划及租房建议","consumerBenefit":"科学规划陪读租房，平衡教育需求和生活成本。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["陪读租房怎么安排","陪读租房建议","陪读租房规划"]},{"id":"OWN-LND-001","name":"出租房怎么定价才好租","domain":"业主资产","subScene":"出租定价与空置控制","scene":"业主资产·出租定价与空置控制","cq":"房东问：我的房子出租，租金定多少合适？","ola":"参考周边成交价，留谈判空间。","cp":["调研周边同类型房源","留5%-10%谈判空间","空置成本计入定价"],"detail":"出租房定价建议参考周边同类型房源的成交租金，而非挂牌价。可查询贝壳、链家等平台的同小区出租历史成交记录。定价时需考虑楼层、朝向、装修程度、家电配置等因素。建议预留5%-10%的谈判空间，同时将空置期的机会成本计入心理底线。过高的定价会导致空置时间延长，空置一个月可能损失全年租金的8%以上。","legalRef":"《中华人民共和国民法典》第七百零三条（租赁合同定义）","consumerBenefit":"帮房东合理定价，缩短空置周期。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["出租房定价方法","租金怎么定合适","房屋出租定价技巧"]},{"id":"OWN-LND-002","name":"空置期过长怎么办","domain":"业主资产","subScene":"出租定价与空置控制","scene":"业主资产·出租定价与空置控制","cq":"房东问：房子空置两个月了还租不出去，怎么办？","ola":"降租金、提配置、扩渠道三管齐下。","cp":["适度降租金5%-10%","添置家电提升吸引力","多渠道挂牌曝光"],"detail":"空置期过长建议从三方面调整：一是适度降低租金，空置一个月的损失往往大于降租100-200元的让利；二是提升房屋配置，如添置洗衣机、空调等提升吸引力；三是扩大挂牌渠道，同时在贝壳、自如、58同城等多平台发布，配合实拍照片和VR看房。也可考虑委托专业租赁机构托管，减少自行管理的精力投入。","legalRef":"《中华人民共和国民法典》第七百零三条（租赁合同定义）","consumerBenefit":"帮房东应对空置，减少租金损失。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["房屋空置期太长","出租房空置怎么办","减少空置的策略"]},{"id":"OWN-SLR-001","name":"什么时候卖房最好","domain":"业主资产","subScene":"出售咨询","scene":"业主资产·出售咨询","cq":"业主问：什么时候卖房最合适？怎么判断时机？","ola":"关注政策和市场周期，择机出手。","cp":["关注限购限贷政策变化","春季秋季为传统旺季","区域利好出台时出手"],"detail":"卖房时机建议关注三个维度：一是政策面，限购放松、利率下调等利好政策出台后市场活跃度提升，适合出手；二是市场面，二手房挂牌量下降、成交量上升时为卖方市场，议价空间大；三是季节面，春季三四月和秋季九十月的看房量通常高于夏季和冬季。如持有不满2年，需缴纳增值税，建议满2年后再卖。满五唯一可免个人所得税，是最佳出售时机。","legalRef":"财政部 税务总局公告2025年第17号（个人销售住房增值税政策）","consumerBenefit":"帮业主把握卖房时机，实现利益最大化。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"道","meetingPhase":["见前"]},"alias":["卖房最佳时机","什么时候卖房好","卖房时机选择"]},{"id":"OWN-SLR-002","name":"卖房要交哪些税","domain":"业主资产","subScene":"出售咨询","scene":"业主资产·出售咨询","cq":"业主问：卖房要交哪些税？大概多少钱？","ola":"增值税个税是主要税种，满二免增值税。","cp":["不满2年交3%增值税","满2年免增值税","满五唯一免个税"],"detail":"卖房主要税费：一、增值税，购买不满2年的住房按3%征收率全额缴纳，满2年免征（2026年1月起执行新规）；二、个人所得税，按房屋转让差额的20%或总价的1%缴纳，满五唯一住房免征；三、印花税，目前个人销售住房暂免征收；四、交易手续费和工本费，金额较小。税费通常由卖方承担增值税和个人所得税，买方承担契税。实际承担方式可由双方在合同中约定。建议出售前核算税费成本，满五唯一是最佳出售时机。","legalRef":"财政部 税务总局公告2025年第17号（个人销售住房增值税政策）","consumerBenefit":"帮业主算清卖房税费，避免事后纠纷。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["卖房交什么税","卖房税费有哪些","二手房出售税费"]},{"id":"OWN-SLR-003","name":"二手房出售完整流程","domain":"业主资产","subScene":"出售咨询","scene":"业主资产·出售咨询","cq":"业主问：卖房子的完整流程是什么？","ola":"签合同→网签→缴税→过户→交房五步走。","cp":["签约后及时网签备案","缴税后才能过户","交房时结清所有费用"],"detail":"二手房出售完整流程：第一步签订买卖合同，明确价格、付款方式、过户时间等条款；第二步网签备案，在房管部门系统签订电子合同防止一房二卖；第三步缴纳税费，双方到税务部门缴纳契税、增值税、个人所得税等；第四步过户登记，双方到不动产登记中心办理产权转移；第五步交房，结清物业水电燃气费，签署交割确认书，移交钥匙。全流程通常需要15-30个工作日。建议委托专业中介代办，避免流程疏漏。","legalRef":"《中华人民共和国民法典》第二百零九条（不动产物权登记）","consumerBenefit":"帮业主理清出售流程，顺利完成交易。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["卖房流程步骤","二手房出售流程","卖房子要什么流程"]},{"id":"OWN-SLR-004","name":"卖房需要准备什么证件","domain":"业主资产","subScene":"出售咨询","scene":"业主资产·出售咨询","cq":"业主问：卖房需要准备什么证件和材料？","ola":"房产证、身份证、婚姻证明缺一不可。","cp":["不动产权证书原件","身份证和户口本","婚姻状况证明"],"detail":"卖房需要准备的材料：一、不动产权证书原件（房产证）；二、卖方身份证原件及复印件；三、户口本，用于核实户籍信息；四、婚姻状况证明，已婚需配偶同意出售的书面声明，离异需离婚证和财产分割协议；五、如为共有产权，需所有共有人到场或提供公证委托书；六、购房发票和契税完税证明，用于计算税费；七、如委托中介，需签署委托协议。建议提前准备齐全，避免交易中途因材料缺失延误。","legalRef":"《不动产登记暂行条例》第十四条（登记申请材料）","consumerBenefit":"帮业主备齐卖房材料，避免流程延误。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["卖房要什么证件","出售房屋所需材料","卖房证件清单"]},{"id":"OWN-SLR-006","name":"卖房信息怎么发布效果好","domain":"业主资产","subScene":"出售咨询","scene":"业主资产·出售咨询","cq":"业主问：卖房信息怎么发布才有效果？怎么写吸引人？","ola":"多渠道挂牌，标题突出卖点，照片要专业。","cp":["多平台同时挂牌","标题突出核心卖点","实拍照片光线明亮"],"detail":"卖房信息发布建议：一、多渠道挂牌，同时在贝壳、链家、58同城等平台发布，扩大曝光；二、标题突出核心卖点，如「南北通透精装三房近地铁」比「出售三居室」更吸引人；三、照片拍摄注意光线明亮、角度全面，客厅、主卧、厨卫各拍一张，建议白天自然光下拍摄；四、描述诚实准确，写明面积、楼层、朝向、装修、配套等关键信息；五、定价参考同小区成交价，略高于预期成交价留谈判空间；六、及时更新挂牌状态，","legalRef":"《中华人民共和国民法典》第五百条（缔约过失责任）","consumerBenefit":"帮业主高效发布卖房信息，吸引优质买家。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["卖房信息发布","卖房怎么挂牌","房源发布技巧"]},{"id":"OWN-SLR-013","name":"委托协议要注意什么","domain":"业主资产","subScene":"出售委托","scene":"业主资产·出售委托","cq":"业主问：签中介委托协议要注意什么？","ola":"看清期限、价格、佣金、违约四大条款。","cp":["明确委托期限和范围","约定最低出售价格","佣金比例和服务标准"],"detail":"委托协议注意事项：一、委托期限，建议3-6个月，到期可续签，避免过长被锁定；二、委托价格，约定最低出售价格，中介低于此价成交需经业主同意；三、佣金条款，明确佣金比例（通常1%-3%）、支付时点和支付方；四、服务标准，约定带看频率、反馈周期、营销方案等；五、独家条款，如为独家委托，约定自行成交是否仍需付佣金；六、违约责任，中介未完成服务的退款机制和业主提前解约的赔偿；七、信息保密，","legalRef":"《中华人民共和国民法典》第九百一十九条（委托合同）","consumerBenefit":"帮业主审慎签订委托协议，保护权益。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["委托协议注意事项","卖房委托合同","中介委托协议"]},{"id":"OWN-SLR-049","name":"资产配置多元化建议","domain":"业主资产","subScene":"资产优化","scene":"业主资产·资产优化","cq":"业主问：卖了房后资金怎么配置才安全？","ola":"房产+金融+现金+保险分散配置。","cp":["房产+金融资产组合","按风险偏好分配","定期再平衡"],"detail":"资产配置多元化建议：一、资产分类，将资产分为房产（实物资产）、金融资产（股票债券基金）、现金类（存款货币基金）、保险（保障型）；二、配置原则，不同年龄段配置不同：30-40岁可适当增加权益类资产比例，50岁以上逐步增加固定收益类比例；三、房产占比，如卖房后不换房，建议房产占总资产不超过50%，避免过度集中；四、应急储备，预留6-12个月生活费在活期或货币基金中；五、保险保障，","legalRef":"《中华人民共和国民法典》第五百九十五条（买卖合同定义）","consumerBenefit":"帮业主科学配置资产，分散风险。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"道","meetingPhase":["见前"]},"alias":["资产配置多元化","卖房后资产配置","不要把鸡蛋放一个篮子"]},{"id":"P3-A4-027","name":"租房押金最多收多少","domain":"法规政策","subScene":"租赁法规","scene":"法规政策·租赁法规","cq":"客户问：租房押金最多收多少？","ola":"法律未规定押金上限，但一般不超过两个月租金，超收可主张返还。","cp":["一般不超过两个月租金","押金应独立于租金管理","退租时应及时退还押金"],"detail":"法律未对房屋租赁押金设定统一上限，但各地住房租赁条例普遍规定押金一般不超过两个月租金。超过部分承租人可主张返还。押金应独立于租金管理，不得随意扣除。退租时除扣除拖欠租金和合理维修费用外，房东应在合同约定的期限内全额退还押金。房东无正当理由拒不退还的，承租人可向法院起诉要求返还并支付利息。","legalRef":"《中华人民共和国民法典》第五百八十六条","consumerBenefit":"帮租客了解押金合理标准，退租时依法要回全部押金。","tags":{"clientType":["tenant","landlord"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["租房押金上限是多少","押金超过三个月合理吗","租房押金法律规定"]},{"id":"P3-A4-028","name":"居住权对租房有什么影响","domain":"法规政策","subScene":"租赁法规","scene":"法规政策·租赁法规","cq":"客户问：居住权对租房有什么影响？","ola":"设立居住权的房屋原则上不得出租，另有约定除外，租前须核实。","cp":["居住权房屋原则上不得出租","另有约定的可出租","租客租前应查不动产登记簿"],"detail":"设立居住权的住宅原则上不得出租，但当事人另有约定的除外。若房屋已设立居住权且未约定可出租，房东擅自出租的，居住权人有权要求承租人搬离，租客面临被迫搬家的风险。反之若当事人约定允许出租，则租赁合同有效。租客在签约前应到不动产登记中心查询房屋是否设有居住权，确认无居住权或已约定可出租后再签约。","legalRef":"《中华人民共和国民法典》第三百六十九条","consumerBenefit":"帮租客规避居住权房屋的租赁风险，签约前核实登记信息。","tags":{"clientType":["tenant","landlord"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["设了居住权的房子能租吗","租住设有居住权的房屋","居住权和租赁权冲突"]},{"id":"P3-A4-029","name":"群租房合法吗有什么风险","domain":"法规政策","subScene":"租赁法规","scene":"法规政策·租赁法规","cq":"客户问：群租房合法吗有什么风险？","ola":"群租房违反人均面积和隔断规定，面临行政处罚和合同无效风险。","cp":["出租房人均面积不得低于5平米","客厅隔断出租属违规","违规出租面临行政处罚"],"detail":"各地住房租赁管理规定明确：出租房人均居住面积不得低于5平方米，每个房间居住人数不得超过2人（有法定赡养抚养关系除外）。将客厅等非居住空间隔断出租、改变房屋原有结构分割出租均属违规群租。群租房面临城管和房管部门行政处罚，隔断须恢复原状。租赁合同中违规群租条款可能被认定无效，租客面临随时被清退的风险。","legalRef":"《商品房屋租赁管理办法》第八条","consumerBenefit":"帮租客和房东识别群租违法风险，避免被处罚和清退。","tags":{"clientType":["tenant","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前"]},"alias":["群租房法律规定","隔断房出租合法吗","人均居住面积最低标准"]},{"id":"D16-058","name":"学龄家庭有什么典型画像和居住需求？","domain":"社区服务与运营","subScene":"家庭画像与需求预判","scene":"社区服务与运营·家庭画像与需求预判","cq":"客户问：我们家孩子要上学了，社区能提供什么帮助？","ola":"学龄家庭核心需求围绕教育资源、安全通学、课后托管和活动空间","cp":["核心需求：居住需求集中在教育资源上","衍生需求：衍生需求包括课后托管服务","改善需求：改善需求方面","服务时机：服务时机上"],"detail":"学龄家庭是社区服务中的高需求密度群体。画像特征：家庭结构为父母加1-2名学龄子女，时间节奏受学校日历支配，工作日早晚接送是刚需，周末活动需求集中。核心居住需求集中在教育资源上，包括学区划分确认、入学政策解读、学校口碑比较、跨区择校可行性等。衍生需求包括课后托管服务、兴趣班资源对接、儿童友好活动场地、安全通学路线规划等。改善需求方面，幼升小、小升初、初升高三个升学节点均可能触发换房需求——或换到更好学区、或换到离学校更近的住处、或出租原住房以租养贷。服务时机上，入学前6个月是最佳触达窗口，此时家长焦虑感最强、信息需求最密集。开学后9-10月需关注孩子适应情况，3-4月关注升学政策发布。日常可通过社区微信群推送教育资讯、组织亲子活动等方式维持高频互动。","legalRef":"无","consumerBenefit":"帮客户解决孩子上学相关居住需求","tags":{"clientType":["buyer","landlord","seller","tenant"],"stage":"all","layer":"术","meetingPhase":["见前"]},"alias":["有孩子的家庭需求","学区家庭画像","上学家庭要什么服务"]},{"id":"D16-059","name":"养老家庭的画像特征和核心需求是什么？","domain":"社区服务与运营","subScene":"家庭画像与需求预判","scene":"社区服务与运营·家庭画像与需求预判","cq":"客户问：我父母住这个小区，有什么适合老人的服务吗？","ola":"养老家庭核心需求是医疗对接、居家适老改造、日常采买和紧急救助","cp":["核心需求：需求分三层：第一层是医疗健康层","居住需求：适老化改造、电梯维护保障","生活需求：画像特征：生活节奏缓慢","服务方式：减少线上操作环节"],"detail":"养老家庭指家中主要常住人口为60岁以上老人的家庭，包括独居老人、老两口家庭、三代同堂中的老人等。画像特征：生活节奏缓慢、对数字化服务接受度低、健康管理需求强、社交圈以社区为主。核心需求分三层：第一层是医疗健康层，包括社区医院/卫生站对接、定期体检提醒、慢病用药管理、紧急呼叫和快速送医通道，这是养老家庭最刚性的需求；第二层是居住安全层，包括适老化改造建议（卫生间防滑、走廊扶手、感应夜灯、门槛消除）、电梯运行保障、消防安全排查等；第三层是生活便利层，包括代购代买、上门保洁、助餐配餐、家电维修、陪同就医等。服务方式上须注意老年群体对APP和小程序使用困难，应优先提供电话直拨和上门服务通道。同时建议建立社区养老家庭台账，标注每位老人的健康状况、紧急联系人、用药情况，以便在突发情况时快速响应。","legalRef":"无","consumerBenefit":"帮客户为父母安排好养老居住服务","tags":{"clientType":["buyer","landlord","seller","tenant"],"stage":"all","layer":"术","meetingPhase":["见前"]},"alias":["老人家庭需要什么","养老住户画像","老年家庭服务需求"]},{"id":"D16-060","name":"租客家庭有什么典型画像和服务需求？","domain":"社区服务与运营","subScene":"家庭画像与需求预判","scene":"社区服务与运营·家庭画像与需求预判","cq":"客户问：我是租户，社区服务对我们有什么用？","ola":"租客家庭需求集中在快速安家、维修响应、租期管理和到期续约","cp":["安家需求：开荒保洁","维护需求：日常维护需求以水电维修","租期需求：提供当前市场租金参考","融入需求：融入需求方面"],"detail":"租客家庭是社区中流动性最大、服务需求频次最高的群体。画像特征：年龄以25-35岁为主，职业多为白领或自由职业，居住周期通常1-3年，对社区归属感较弱但对服务效率要求高。安家阶段需求集中在入住前后的快速配置：搬家服务、开荒保洁、家具家电租赁或采购、网络宽带开通、水电燃气过户等，租客希望拎包入住、快速安定。日常维护需求以水电维修、门锁更换、物业问题协调为主，核心诉求是响应速度快，因为租客通常不具备自行维修的条件和意愿。租期管理是租客家庭区别于自住家庭的核心需求：到期前2个月需提醒续约决策，提供当前市场租金参考；退租时需协调退租清洁、押金退还、物品交接等。融入需求方面，租客初到新社区常面临信息不对称，需要周边生活指南、邻里关系建立等支持。服务租客时要特别注意租客与业主之间的权责边界，维修和改造需求须先经业主同意。","legalRef":"无","consumerBenefit":"帮租客快速安家并享受便利服务","tags":{"clientType":["tenant","landlord","seller"],"stage":"all","layer":"术","meetingPhase":["见前"]},"alias":["租房的人需要什么","租客画像特征","出租房住户需求"]},{"id":"D16-070","name":"孩子升学节点会触发哪些居住需求？","domain":"社区服务与运营","subScene":"家庭画像与需求预判","scene":"社区服务与运营·家庭画像与需求预判","cq":"客户问：孩子马上要升学了，房子方面需要做什么准备？","ola":"幼升小、小升初、初升高三个节点分别触发学区房购置、改善换房","cp":["幼升小：幼升小阶段（5-6岁）","小升初：小升初阶段（11-12岁）","初升高：初升高阶段（14-15岁）","时间节点：入学前6个月启动规划"],"detail":"孩子升学是触发居住需求变更的高频节点，每个升学阶段对应不同的需求模式。幼升小阶段（5-6岁），家长核心需求是确认学区资格和学区房配置：已在学区内的家庭需确认户籍和房产年限是否符合入学要求，不在学区内的家庭可能需购置或租赁学区房，入学政策通常在3-4月发布，须提前6个月启动规划。小升初阶段（11-12岁），需求更加多元化：部分城市小升初实行划片入学需确认对口初中，优质初中片区房源可能涨价需提前锁定，部分家庭选择民办初中需考虑通勤距离和陪读安排。初升高阶段（14-15岁），需求集中在陪读和学区房退出：高中阶段多数学生需住校或陪读，陪读租房需求在7-8月集中爆发，原学区房可能在孩子毕业后面临出售或出租，须关注市场时机。服务升学家庭的关键是建立升学时间轴：提前6个月推送政策信息、提前3个月协助房产决策、入学后1个月跟进适应情况，形成完整服务闭环。","legalRef":"无","consumerBenefit":"帮客户提前规划孩子升学居住安排","tags":{"clientType":["buyer","seller","tenant"],"stage":"all","layer":"术","meetingPhase":["见前"]},"alias":["升学要换房吗","孩子上学触发什么需求","幼升小换房需求"]},{"id":"D16-076","name":"租客更替频率高意味着什么？如何应对？","domain":"社区服务与运营","subScene":"家庭画像与需求预判","scene":"社区服务与运营·家庭画像与需求预判","cq":"客户问：我们小区租客换得太频繁了，这正常吗？","ola":"租客更替频率高可能反映租金偏高、房屋品质差或社区环境问题","cp":["原因分析：租金定价","影响：频繁搬家加速房屋和设施损耗","留存：合理定价+及时维修+改善环境","服务优化：是服务维度"],"detail":"租客更替频率是衡量社区出租房运营质量的重要指标。正常情况下，住宅租客的平均租期为1.5-2年，如果社区内租客平均租期低于1年或同一房源每年更替超过1次，则属于高更替频率。高更替的原因需从三个维度分析：第一是房屋维度，租金定价是否高于市场水平、房屋设施是否老化损坏、装修是否过时；第二是服务维度，维修响应是否及时、物业服务质量是否达标、租客合理诉求是否被重视；第三是环境维度，社区治安是否良好、邻里关系是否和谐、周边生活配套是否便利。高更替频率的影响是多方面的：每次空置都意味着1-2个月的租金损失，频繁搬家加速房屋和设施损耗，租客流动性大导致邻里关系不稳定、社区归属感弱。应对策略包括：合理定价（参考同小区同户型成交租金）、建立快速维修响应机制、提供续约优惠（如续约免一周租金或赠送保洁）、长租激励（签2年约降月租5%）等。同时建立租客满意度回访制度，在退租时了解真实原因并持续改进。","legalRef":"无","consumerBenefit":"帮客户降低租客流失和空置成本","tags":{"clientType":["landlord","tenant","seller"],"stage":"all","layer":"术","meetingPhase":["见前"]},"alias":["租客频繁换怎么办","出租房周转率","租客流动性分析"]},{"id":"CRO-GEN-013","name":"刚需买房最看重什么","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"预算不多，刚需买房最该看什么","ola":"通勤优先总价可控基本功能齐全","cp":["通勤优先降低时间成本","总价可控不影响生活","基本功能齐全即可","区分必选项和可让步项"],"detail":"刚需购房者预算有限，需在价格、通勤、面积之间做取舍排序。核心原则是通勤优先（降低时间成本）、总价可控（不影响生活质量）、基本功能齐全（厨卫独立可做饭）。经纪人需帮刚需客户明确不可妥协项和可让步项。","legalRef":"行业通行做法","consumerBenefit":"有限预算买到最适合自己的房","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["刚需买房怎么选","刚需购房优先级","刚需房选什么"]},{"id":"CRO-GEN-040","name":"买房预算怎么算才合理","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"买房到底要准备多少钱才够","ola":"首付税费佣金装修应急五项加总","cp":["总预算=首付+税费+佣金+装修+应急","月供加持有不超收入50%","税费约为房款5%-10%","应急预留3-6个月月供"],"detail":"合理购房预算=首付+税费+中介佣金+装修储备+应急资金。月供+持有成本不超过家庭月收入50%。预算分配建议：首付占房款30%-70%（看城市和套数），税费约为房款5%-10%，装修预留总价的10%-20%，应急预留3-6个月月供。","legalRef":"行业通行做法","consumerBenefit":"预算算得清，买房不超支不慌张","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["法"],"meetingPhase":["见前"]},"alias":["购房预算怎么算","买房花多少钱合适","购房总预算怎么估"]},{"id":"CRO-GEN-046","name":"交的物业费到底都包含哪些服务","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我家里的水管坏了，物业能免费用物业费来修吗？","ola":"物业费只管公共区域，室内维修需自费。","cp":["包含公共区域保洁保安","包含电梯等共用设施维保","包含公共区域水电费","不包含业主室内专属维修"],"detail":"物业费是指物业管理公司按照物业服务合同约定，对房屋及配套的设施设备和相关场地进行维修、养护、管理，维护环境卫生和相关秩序，向业主所收取的费用。通常包含：公共区域保洁、绿化养护、秩序维护（保安）、共用设施设备（如电梯、水泵、消防）的日常运行与维护、公共区域水电费及物业办公费用等。但不包含业主室内的专属维修费用及大修、中修费用（需动用维修资金）。","legalRef":"《物业管理条例》第41条","consumerBenefit":"明确物业费边界，避免对物业服务产生不合理预期。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"法","meetingPhase":["见中","见前"]},"alias":["物业费包含哪些项目","物业费包含电梯维修吗","不交物业费有什么后果"]},{"id":"EXT-INH-282","name":"继承房产有纠纷能直接卖吗","domain":"退租出售","subScene":"继承赠与","scene":"退租出售·继承赠与","cq":"买的继承房有纠纷过不了户怎么办？","ola":"继承房产有纠纷未分割前无法过户，不能合法出售。","cp":["权属有争议无法过户","私自出售属无权处分","隐瞒纠纷交易需赔偿","建议先析产再挂牌出售"],"detail":"依据《民法典》第1132条及《不动产登记暂行条例》第14条，继承房产在存在权属争议或未完成遗产分割前，无法办理继承过户登记，自然无法合法出售。实践中，若部分继承人私自出售，买卖合同可能因无权处分而面临解除风险，且房管局会中止办理。风险提示：切勿在纠纷未决时隐瞒事实交易，否则需承担违约赔偿责任。","legalRef":"《中华人民共和国民法典》第1132条","consumerBenefit":"避免买到产权有瑕疵的继承房，防止钱房两空。","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["继承纠纷期间能卖房吗","房产继承有争议能过户吗","继承人不同意能出售房产吗"]},{"id":"EXT-SEL-001","name":"房子挂牌出售要什么条件","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"我的房子想挂牌卖，需要准备什么？","ola":"房本、身份证、签委托协议，无查封等限制","cp":["需两证一书：房本+身份证+委托书","须取得不动产权证书","不能有查封等限制","经济适用房需满5年","共有需共有权人同意"],"detail":"房屋挂牌出售的基本条件。委托人需提供房屋权属证明、业主身份证明，并签署书面委托协议（'两证一书'）。房屋须取得不动产权证书且无禁止交易情形（如被查封、集体产权、未取得上市许可的经济适用房等）。特殊情形如代理、共有还需额外证件。","legalRef":"《中华人民共和国城市房地产管理法》第38条","consumerBenefit":"提前备齐材料，快速挂牌不耽误","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["卖房挂牌条件","出售委托","挂牌资质"]},{"id":"EXT-SEL-006","name":"卖房要交哪些税费","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"我要卖房，大概要交多少税？","ola":"增值税满2年免，个税满五唯一免","cp":["增值税满2年免征","个税满五唯一免征","不满2年交增值税","房改房需缴土地出让金","经适房需补缴综合地价"],"detail":"出售房屋时卖方需缴纳的税费种类。主要包括：增值税及附加（满2年免征，不满2年全额征收）、个人所得税（满五唯一免征，否则按差额20%或核定1%征收）。房改房还需缴纳土地出让金。经济适用房再出售需补缴综合地价款。税费政策因城市而异。","legalRef":"《财税〔2016〕36号附件3第5条","consumerBenefit":"了解税费成本，合理定价","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["出售方税费","卖房税费","业主税费"]},{"id":"EXT-SEL-015","name":"想卖房怎么确定合理报价","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"我的房子想卖，挂牌价怎么定？","ola":"参考同小区成交价，留10%-15%议价空间","cp":["参考同小区近期成交价","对比周边类似房源挂牌价","留合理议价空间","定期根据带看反馈调价","调价次数和幅度影响判断"],"detail":"挂牌价的合理确定方法。应参考同小区同户型近期成交价、周边类似房源挂牌价、市场行情走势等因素。挂牌价通常高于预期成交价，留出议价空间。议价空间=（挂牌价-成交价）/挂牌价×100%。议价空间不断缩小代表市场向好，扩大则市场趋冷。","legalRef":"《价格法》第3条","consumerBenefit":"合理定价缩短成交周期","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["出售定价","卖房报价","挂牌价参考"]},{"id":"EXT-SEL-016","name":"房子挂牌多久卖不出要降价","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"房子挂了两个月还没卖出去，是不是该降价了？","ola":"带看少、无出价说明价偏高，建议调价","cp":["带看量低说明价偏高","2-4周评估一次","参考竞品成交价走势","调价需业主确认并留凭证","分步降价优于一步到位"],"detail":"根据挂牌时间和市场反馈判断是否需要调降挂牌价。若挂牌后带看量低、长期无诚心出价、同小区竞品成交价持续走低，说明挂牌价偏高应考虑降价。一般建议每2-4周根据市场反馈评估一次。降价幅度和频率应与业主充分沟通，留存调价凭证。","legalRef":"《价格法》第3条","consumerBenefit":"合理调价加速成交，减少空置成本","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["挂牌周期","出售周期","调价时机"]},{"id":"EXT-SEL-017","name":"代理人能替业主卖房吗","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"房东在国外，他朋友能代他签卖房合同吗？","ola":"须有公证委托书，受托人不能是买方","cp":["须有公证授权委托书","受托人不能是买方","买卖双方不能同委托一人","签约前核实委托真实性","留存核实电话录音等证据"],"detail":"业主委托代理人出售房屋的条件和要求。需提供经公证的授权委托书，至少包括委托人和受托人基本信息、委托事项、委托期限、委托人签名。代理人不可为买受方或其配偶，买卖双方不能委托同一人。签约前应与业主本人核实委托真实性并留存证据。","legalRef":"《中华人民共和国民法典》第161条、第162条","consumerBenefit":"确认代理合法有效，避免合同被撤销","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["委托代理卖房","他人代签","公证委托售房"]},{"id":"EXT-SEL-024","name":"房子有居住权能卖吗","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"房子上设有居住权，还能卖吗？","ola":"能卖但居住权不受影响，买家无法自住","cp":["有居住权仍可出售过户","居住权不受房屋转让影响","买家无法自住或出租","严重影响房屋价值","交易前须查询居住权登记"],"detail":"设立居住权的房屋可以出售过户，但居住权不受影响。根据《民法典》，居住权人有权按照合同约定对他人的住宅享有占有、使用的用益物权。房屋出售后，居住权人仍可继续居住至居住权期限届满或居住权人死亡。买家购买此类房屋后无法自住或出租，严重影响房屋价值。交易前须查询不动产登记簿确认是否存在居住权登记。","legalRef":"《中华人民共和国民法典》第366条、第369条","consumerBenefit":"了解居住权对卖房的影响，提前做好告知","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["设立居住权的房子能卖吗","居住权对卖房的影响","有居住权的房子能过户吗"]},{"id":"EXT-SEL-200","name":"卖房时租客还在住怎么办","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"卖房时租客还在住怎么办","ola":"买卖不破租赁新房东续履约","cp":["买卖不破租赁新房东续履约","租客有优先购买权","须书面通知租客出售事宜","交房日一般在租期届满后","未通知租客可主张赔偿"],"detail":"带租约出售规则：①买卖不破租赁：租赁期内房屋所有权变动不影响租赁合同效力，新房东须继续履行租赁合同至期满；②租客优先购买权：卖房须提前通知租客同等条件下租客有优先购买权，未通知的租客可主张赔偿但不可主张买卖合同无效；③实际操作：带租约出售的交房日在租期届满后，或在合同中约定租客搬离时间；④通知租客：卖方须书面通知租客出售事宜和价格给其合理时间行使优先购买权。","legalRef":"《中华人民共和国民法典》第725条、第726条","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["有租客的房子能卖吗","买卖不破租赁规则","卖房须通知租客吗"]},{"id":"EXT-SEL-246","name":"卖房议价谈判有哪些技巧","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"买房时中介一直说房东急售，我怎么判断是不是真的？","ola":"设定底价阶梯，用成交数据支撑，用非价格条件置换让步。","cp":["提前设定底价与让步阶梯","用同小区成交数据做支撑","用交房时间或家电替代降价","隐藏急售心态掌握主动权"],"detail":"议价谈判是二手房交易的核心环节。卖方需提前设定底价与让步阶梯，避免被买方或中介连环压价。实践要点：掌握房屋核心卖点（如学区、地铁），利用近期同小区成交数据作为支撑；面对买方挑刺，保持冷静，用客观事实回应；若买方诚意金到位，可适度在家具家电或交房时间上让步，而非直接降价。风险提示：切勿在多人看房时表现出急售心态，以免丧失议价主动权。","legalRef":"行业惯例","consumerBenefit":"掌握科学的议价策略，避免在谈判中因心态失衡而低价贱卖。","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["卖房怎么谈价格","卖房议价技巧","卖房底价怎么守"]},{"id":"EXT-TRM-011","name":"转租和退租有什么区别","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"我不想租了，找人接手算转租还是退租？","ola":"找人接手是转租，需房东同意；不续租是退租","cp":["转租不终止原租赁合同","退租终止原租赁合同","转租需业主书面同意","未经同意业主可解约","换租=解约+新签"],"detail":"转租是租客在租赁期间将承租房屋部分或全部再出租给第三方（次承租人），原租赁合同继续有效。退租是业主与租客解除租赁合同、业主收回房屋。转租不终止原合同，退租终止原合同。转租需经业主同意，未经同意业主可解除合同。","legalRef":"《中华人民共和国民法典》第716条","consumerBenefit":"选择成本更低的方式处理租期问题","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["转租vs退租","换租和退租","租期内换人"]},{"id":"EXT-TRM-020","name":"租期最长不能超过多少年","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"房东想跟我签30年的租约，这合法吗？","ola":"租期最长20年，超期部分无效","cp":["租期上限为20年","超20年部分无效","续订也不超20年","6月以上须书面合同","未书面视为不定期租赁"],"detail":"依据《民法典》第705条，租赁期限不得超过20年。超过20年的，超过部分无效。租赁期届满可续订合同，但续订之日起也不得超过20年。租期6个月以上的应采用书面形式，未采用书面形式的视为不定期租赁，当事人可随时解除。","legalRef":"《中华人民共和国民法典》第705条、第707条","consumerBenefit":"避免签超长期合同导致权益不受保护","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["租赁期限上限","最长租期","租房合同期限"]},{"id":"EXT-TRM-022","name":"退租时墙面自然磨损要赔吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租时房东说墙面有磨损要扣押金，合理吗？","ola":"自然磨损不赔，人为损坏才需赔偿，入住时拍照留证","cp":["自然磨损不承担赔偿责任","人为损坏需赔偿或修复","入住时应拍照记录状况","退租时对照原始状况","正常使用损耗受法律保护"],"detail":"退租时墙面的自然磨损（如正常使用导致的轻微变黄、细小裂纹等）不属于租客赔偿范围。根据《民法典》，承租人按照约定方法或租赁物性质使用租赁物致使损耗的，不承担赔偿责任。但人为损坏（如大面积涂画、故意破坏、钉孔过多等）需赔偿或修复。建议入住时拍照记录墙面状况，退租时对照避免争议。","legalRef":"《中华人民共和国民法典》第710条","consumerBenefit":"正常使用磨损不用赔，保住押金","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["退租墙面正常老化要赔吗","租房墙面磨损算谁的","退房墙面变黄要赔吗"]},{"id":"EXT-TRM-025","name":"合租室友退租我怎么办","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"合租的室友突然说退租，我怎么办？","ola":"共同合同需补足租金，签约时应约定退租机制","cp":["共同租赁合同承担连带责任","一人退租其他人需补足租金","独立合同互不影响","签约时约定退租处理机制","可寻找替代租客减少损失"],"detail":"合租中一方退租，需区分合同类型：1）如签的是共同租赁合同，所有合租人对租金承担连带责任，一人退租后其他人需补足差额或找新室友；2）如各签独立合同，一方退租不影响其他人。建议合租签约时约定退租处理机制（如提前通知期、违约金分担、寻找替代租客等），避免因一方退租导致其他人的被动损失。","legalRef":"《中华人民共和国民法典》第518条","consumerBenefit":"了解合租退租规则，不被室友退租拖累","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["合租有人退租怎么办","合租室友走了房租谁付","合租退租影响我吗"]},{"id":"EXT-TRM-027","name":"租期内发现房屋有安全隐患能退租吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"租的房子墙体有裂缝感觉不安全，能退租吗？","ola":"危及安全可随时无责退租，房东应退押金和余租","cp":["危及安全可随时解除合同","不承担违约责任","房东应退还押金和剩余租金","即使签约时已知也不影响","安全隐患需有证据支持"],"detail":"根据《民法典》，租赁物危及承租人安全或健康的，即使承租人订立合同时明知该租赁物质量不合格，承租人仍然可以随时解除合同。如发现房屋存在安全隐患（如墙体开裂有倒塌风险、燃气泄漏、电线老化起火风险等），租客有权随时解除合同并不承担违约责任，房东应退还押金和剩余租金。","legalRef":"《中华人民共和国民法典》第731条","consumerBenefit":"发现安全隐患可以无责退租保命","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["房屋有安全问题能退租吗","租房发现安全隐患解约","租的房子有危房风险能退吗"]},{"id":"EXT-TRM-030","name":"退租时家具自然老化要赔偿吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租时房东说沙发旧了要赔钱，合理吗？","ola":"自然老化不赔，只有人为损坏才需赔偿","cp":["自然老化损耗不承担赔偿","人为损坏需赔偿","入住时拍照记录家具状况","电器使用年限内性能下降属正常","区分自然老化和人为损坏"],"detail":"退租时家具家电的自然老化损耗不属于租客赔偿范围。根据《民法典》，承租人按约定方法使用租赁物致使损耗的，不承担赔偿责任。自然老化包括：电器使用年限内的正常性能下降、家具正常磨损褪色、床垫使用痕迹等。但人为损坏（如摔坏、烫坏、宠物咬坏等）需赔偿。建议入住时拍照记录家具家电状况，退租时对照。","legalRef":"《中华人民共和国民法典》第710条","consumerBenefit":"自然老化不用赔，避免被房东多扣押金","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["退租家电老化要赔吗","租房家具自然折旧赔偿","退房家具旧了要赔吗"]},{"id":"EXT-TRM-031","name":"不定期租赁合同怎么解除","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"租房没签合同，我能随时退吗？","ola":"不定期租赁可随时解除，一般提前1个月通知","cp":["双方均可随时解除合同","出租人解除须提前合理期限通知","承租人一般需提前1个月通知","6个月以上未签书面视为不定期","解除合同押金应全额退还"],"detail":"不定期租赁是指双方未约定租期或约定期限不明确，或未采用书面形式（租期6个月以上）的租赁。根据《民法典》，不定期租赁双方均可随时解除合同，但出租人解除合同应在合理期限之前通知承租人。承租人解除一般需提前1个月通知。如房东不定期租赁要涨租，租客不同意可解除合同搬离，押金应全额退还。","legalRef":"《中华人民共和国民法典》第707条、第730条","consumerBenefit":"不定期租赁可灵活退租，不受长期约束","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["没约定期限的租房怎么退","不定期租赁解除通知期","口头租房合同怎么退租"]},{"id":"EXT-TRM-032","name":"房东不肯签解约协议怎么办","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"我退租了但房东不签解约协议，怎么办？","ola":"微信发解约通知留证，贝壳签约可线上解约","cp":["通过微信短信发送解约通知留证","录制沟通记录","贝壳签约可线上发起解约","保留钥匙归还记录","书面证据可替代解约协议"],"detail":"房东不肯签解约协议时，租客应通过其他方式固定解约证据：1）通过微信、短信等书面方式向房东发送解约通知，截图留存；2）录制双方关于退租的沟通记录；3）通过贝壳APP线上发起解约流程（贝壳签约合同支持线上解约）；4）保留退租交房的钥匙归还记录。有以上证据即使房东拒签解约协议，也能证明租客已履行退租义务。","legalRef":"《中华人民共和国民法典》第565条","consumerBenefit":"即使房东不签协议也能证明已退租","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["退租房东不签解约书","房东不配合办理解约","退租房东不签字怎么办"]},{"id":"EXT-TRM-033","name":"租期到了不想续但房东不退押金","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"租期到了我不想续了，房东说押金不退，合理吗？","ola":"不合理，正常到期无违约应全额退押金","cp":["正常到期无违约应全额退押金","不续租不是扣押金的理由","要求房东列明扣款项目","可向住建部门或12345投诉","可提起小额诉讼"],"detail":"租期正常到期退租，如租客无违约行为且房屋无损坏，房东必须全额退还押金。房东不得以'不续租了'为由扣押金。如房东找各种理由拒绝退还，租客可：1）要求房东列明扣款项目和金额，出示维修票据；2）向住建部门或12345投诉；3）向法院提起小额诉讼。注意押金不是违约金，正常到期无违约应全额退还。","legalRef":"《中华人民共和国民法典》第577条","consumerBenefit":"正常到期退租押金应全退，不被无理扣押","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["到期退租房东不退押金","租期满了押金不退","正常到期退租房东扣钱"]},{"id":"EXT-TRM-034","name":"租期内工作调动能无责退租吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"因为工作调动要搬家，能无责退租吗？","ola":"工作调动不属不可抗力，提前退租仍需付违约金","cp":["工作调动不属于不可抗力","提前退租仍属违约","须按合同承担违约金","合同有约定可免违约金","签约时建议加入灵活条款"],"detail":"工作调动不属于法律规定的不可抗力，租客因工作调动提前退租仍构成违约，须按合同约定承担违约责任（通常为1个月租金违约金）。但如合同中有'因工作调动可无责退租'的条款，则可按约定免违约金。建议签约时与房东协商加入此类灵活条款，如'提前30天书面通知可免违约金退租'。","legalRef":"《中华人民共和国民法典》第180条、第577条","consumerBenefit":"了解工作调动退租的法律后果，合理规划","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["工作调动退租算违约吗","因工作变动退租房东违约金","调工作退租能退押金吗"]},{"id":"EXT-TRM-035","name":"退租时物品清单和入住时不一致","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租时房东说少了东西，但我记得入住时就没有，怎么办？","ola":"以入住时交割单为准，没清单的协商或凭照片举证","cp":["以物业交割单为准核对差异","未做清单双方难以举证","照片视频可作为辅助证据","建议入住退租都做清单签字","物品清单是避免纠纷的关键"],"detail":"退租时物品清单与入住时不一致，责任认定取决于：1）如入住时双方签署了物业交割单，以交割单为准核对差异；2）如入住时未做清单，双方对物品数量状况有争议的，较难举证，建议协商处理；3）如入住时有照片或视频记录，可作为辅助证据。强烈建议入住和退租时都做详细的物品清单登记并双方签字确认。","legalRef":"《中华人民共和国民法典》第710条","consumerBenefit":"有清单有证据退租不扯皮","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["退租房东西少了","退租物品清单对不上","入住时没做物品清单"]},{"id":"EXT-TRM-036","name":"退租时房东要求专业清洁合理吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租时房东要求做专业保洁，必须做吗？","ola":"合同没约定则只需正常使用状态，不必专业保洁","cp":["清洁要求以合同约定为准","无约定只需正常使用状态","房东不得以不够干净扣押金","人为污损须修复或赔偿","交房时共同验收签字确认"],"detail":"退租时是否需要做房屋清洁取决于合同约定。如合同约定退租时须清洁至一定标准，租客应按要求完成。如合同无约定，租客只需将房屋恢复至正常使用状态即可，无需专业保洁。房东不得以'不够干净'为由扣押金，除非存在明显的人为污损。建议退租时做基本清洁，交房时与房东共同验收签字确认。","legalRef":"《中华人民共和国民法典》第710条","consumerBenefit":"不被房东强制要求做高价专业保洁","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["退房需要打扫卫生吗","退租房东要求保洁合理吗","退租清洁费谁出"]},{"id":"EXT-TRM-046","name":"房东不退押金去哪投诉","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"房东不退押金去哪投诉","ola":"先书面催退函限期退还","cp":["先书面催退函限期退还","可向住建局/12345投诉","可起诉适用小额诉讼程序","通过平台中介协助协调","押金纠纷属民事警方不受理"],"detail":"房东不退押金维权渠道：①先与房东协商发书面催退函（限期内退还）；②协商不成可向当地住建局/房管部门投诉（部分城市有租赁监管平台）；③拨打12345市民热线投诉；④向法院起诉（押金金额通常在1-2万以内适用小额诉讼程序，审理周期1-3个月）；⑤通过租房平台/中介协助协调；⑥注意：押金纠纷属民事纠纷公安机关不受理但可调解。","legalRef":"《中华人民共和国民法典》第577条；行业通行做法","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["房东扣押金维权","退租押金纠纷处理","租房押金找谁要回来"]},{"id":"EXT-TRM-072","name":"转租算不算违约","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"转租算不算违约","ola":"未经同意转租房东可解约","cp":["未经同意转租房东可解约","须取得房东书面同意","转租期不超过剩余租期","擅自转租须担违约责任","次承租人可向转租人索赔"],"detail":"转租规则：①承租人未经出租人同意转租的，出租人可以解除合同；②合同约定可以转租或房东书面同意转租的合法有效；③转租期限不得超过承租人剩余租赁期限；④擅自转租的法律后果：房东可解除合同收回房屋，转租人须对房东和次承租人承担违约责任；⑤次承租人（二租客）权益：房东解除合同后次承租人可向转租人主张违约赔偿。","legalRef":"《中华人民共和国民法典》第716条","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["未经同意转租违法吗","房东不同意转租","租房能转租给别人吗"]},{"id":"EXT-TRM-114","name":"合租退租自己那份怎么退","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"合租退租自己那份怎么退","ola":"按合同约定执行","cp":["按合同约定执行","提前通知给合理时间找人","押金份额待新室友入住后退还","提前走可能承担空置损失","合租合同应约定退租条件"],"detail":"合租单方退租处理：①合租合同有约定的按约定执行；②合同未约定的：退租人须提前通知合租人和房东/二房东给合理时间找新室友；③押金处理：如押金是统一交的，退租人的押金份额待新室友入住后由新室友支付给退租人，或由房东从总押金中退还退租人份额；④退租人提前走可能承担空置期租金损失；⑤建议合租时签明确约定退租条件和押金分配的合同。","legalRef":"行业通行做法","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["合租单方退租","合租人退租流程","合租退押金怎么算"]},{"id":"EXT-TRM-141","name":"租房合同到期房东不续租","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"租房合同到期房东不续租","ola":"到期不续签不构成违约","cp":["到期不续签不构成违约","应提前合理时间通知对方","押金扣应扣后须退还","优先续租权违约须赔偿","可要求合理搬离时间"],"detail":"合同到期房东不续租：①租赁合同到期任何一方均可选择不续签，不续签不构成违约（除非合同约定了优先续租权）；②到期不续签的房东/租客均应提前合理时间通知对方（合同约定通知期的按约定，未约定的提前1个月较合理）；③押金在扣除应扣款项后须退还；④有约定优先续租权的房东不续签可能构成违约须按约定赔偿；⑤租客对到期不续签无补偿请求权但可要求合理搬离时间。","legalRef":"《中华人民共和国民法典》第733条","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["房东到期不续租合理吗","合同到期房东不续签","到期不续租要提前通知吗"]},{"id":"LIV-DEC-060","name":"装修包清工和包工包料哪个好","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修选包清工还是包工包料好？","ola":"有时间懂材料选清工，追求省心选半包","cp":["包清工费时但可控材料品质","半包兼顾品质和便利是主流","全包省心但材料难把控","全包增项风险较高","选择需根据时间和专业度决定"],"detail":"装修承包方式主要有包清工（仅人工，材料自购）、半包（人工+辅材，主材自购）、全包/包工包料（人工+全部材料）。包清工适合有时间且懂材料的业主，可控制材料品质但费时费力；半包兼顾品质和便利，是主流选择；全包省时省心但材料质量难把控，增项风险较高。选择时需根据自身时间、专业度和预算决定。","legalRef":"《住宅室内装饰装修管理办法》第24条","consumerBenefit":"选对承包方式，装修省钱又省心","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["装修半包全包清工区别","装修包清工划算吗","装修全包和半包怎么选"]},{"id":"LIV-DEC-064","name":"装修能不能自己找工人不做全包","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修能不能自己找工人不做全包","ola":"清包省钱但费精力","cp":["清包省钱但费精力","半包性价比最高","全包省心但增项风险大","全包须签闭口合同","半包业主控主材品质"],"detail":"装修方式分清包、半包、全包三种。清包最省钱但最费精力需协调各工种；半包性价比高业主控主材品质；全包省心但增项风险大。建议有经验选半包，完全没时间选全包但合同须闭口。","legalRef":"行业通行做法","consumerBenefit":"了解关键要点避免踩坑","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["装修半包好还是全包好","装修自己找人干行吗","装修不全包可以吗"]},{"id":"LIV-MNT-CASE-010","name":"租的房子甲醛超标我直接退租算违约吗","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"刚租的房子甲醛超标，我直接退租会被房东扣违约金吗？","ola":"甲醛超标危及健康，退租不算违约。","cp":["甲醛超标危及健康","承租人可随时解除合同","无需承担违约责任","需具备CMA检测报告","保留沟通与检测证据"],"detail":"王某承租刘某新装修房屋，入住后感觉刺鼻，经CMA资质机构检测甲醛超标2倍。王某提出退租，刘某以合同未到期为由要求支付违约金。法院认为，刘某交付的房屋不符合安全健康标准，致使不能实现合同目的。依据《民法典》第七百三十一条，租赁物危及承租人安全健康的，承租人可随时解除合同。判决王某无需支付违约金。","legalRef":"《中华人民共和国民法典》第七百三十一条","consumerBenefit":"掌握健康受损时的法定解除权，避免被不合理索赔违约金。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["出租屋甲醛超标能退租吗","租房甲醛检测不合格怎么退租","新装修房子甲醛超标租客退租"]},{"id":"LIV-NBR-CASE-015","name":"邻居把房子租给别人做违法活动怎么举报","domain":"居住中","subScene":"邻里纠纷","scene":"居住中·邻里纠纷","cq":"邻居把房子租给别人干违法的事怎么举报？","ola":"邻居出租房涉违法需报警并要求解约。","cp":["房东对租客违法活动负有管理责任","面临治安管理处罚","侵害相邻权及社区安全","判决解除租赁合同消除影响"],"detail":"业主董某将房屋出租，租客利用该房屋从事非法传销活动，频繁有陌生人进出，严重干扰邻居生活，并存在治安隐患。邻居向公安机关举报。公安机关查实后对租客进行处罚，并依据《治安管理处罚法》第五十七条，对明知租客从事违法活动而未报告的房东董某处以罚款。同时，法院依据《民法典》第二百八十六条，支持业委会要求董某解除租赁合同、消除影响的诉求。","legalRef":"《中华人民共和国民法典》第二百八十六条、《治安管理处罚法》第五十七条","consumerBenefit":"及时消除社区治安隐患，保障自身居住安全。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["邻居出租房违法活动","邻居房屋涉嫌违法","邻居租客从事违法活动"]},{"id":"LIV-PMG-008","name":"空置房物业费要全额交吗","domain":"居住中","subScene":"物业管理","scene":"居住中·物业管理","cq":"我的新房交房两年了一直没住，物业费还要全额交吗？","ola":"一般须全额交，个别城市空置超6月可减免30%","cp":["物业费不以入住为前提","公共服务无论入住均提供","多数地方空置房不打折","少数城市可减免不超过30%"],"detail":"业主交纳物业费的义务基于物业服务合同的约定，不以是否实际入住为前提。物业服务针对的是公共区域和公共设施，无论业主是否入住，物业服务均持续提供。多数地方规定空置房物业费不打折，少数城市（如部分省份）规定空置6个月以上可适当减免（通常减免幅度不超过30%）。","legalRef":"《物业管理条例》第41条第2款","consumerBenefit":"了解当地空置房减免政策，能省则省","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["没入住的房子物业费打折吗","空置房物业费减免政策","新房没装修住人要交物业费吗"]},{"id":"LIV-SAF-012","name":"家里有老人怎么防跌倒","domain":"居住中","subScene":"居住安全","scene":"居住中·居住安全","cq":"家里老人年纪大了，怎么装修才能防跌倒？","ola":"卫生间防滑装扶手，去高低差装夜灯","cp":["卫生间防滑砖加扶手","走廊装起夜感应灯","去除地面高低差","家具圆角防撞处理","65岁以上1/3每年跌倒"],"detail":"老年人跌倒是居家伤害致死主因（65岁以上老人约1/3每年跌倒一次）。防跌倒要点：①卫生间铺防滑地砖+防滑垫，安装扶手②淋浴区装折叠座椅和扶手③走廊和卧室装起夜感应灯④去除地面高低差和门槛⑤家具圆角处理或贴防撞条⑥不使用带轮子的椅子⑦保持通道无障碍。《住宅设计规范》对适老化设计有专项规定。","legalRef":"《住宅设计规范》GB50096-2011第5.3节（适老化）","consumerBenefit":"降低老人跌倒风险，减少居家伤害","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["老人防跌倒","适老化改造","卫生间防滑"]},{"id":"OWN-AST-CASE-011","name":"租客利用出租屋从事违法活动房东担责吗","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"租客在房子里干违法的事，房东会被处罚吗？","ola":"明知租客违法不报告，房东将承担行政责任及经济损失。","cp":["明知违法不报告需承担行政责任","发现违法活动应立即报警并解约","未尽管理义务可能没收租金","房屋被查封损失需按过错分担","合同中应明确禁止违法活动"],"detail":"房东冯某将房屋出租给韩某，韩某在屋内设立窝点从事电信诈骗。公安机关查处时，发现冯某明知韩某无正当职业且常有可疑人员出入，但未向公安机关报告，也未解除合同。冯某被公安机关处以罚款，并没收违法所得。后冯某起诉韩某要求赔偿房屋被查封期间的租金损失。法院认为，冯某未尽到出租人管理义务，对损失发生存在过错，驳回其部分诉讼请求。","legalRef":"《治安管理处罚法》第五十七条","consumerBenefit":"明确出租屋治安管理责任，指导业主规避因租客违法带来的法律风险。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租客在出租屋赌博房东有责任吗","租客搞传销房东会被抓吗","出租屋发生违法活动房东担责吗"]},{"id":"OWN-OPS-028","name":"多套房怎么管理更高效","domain":"资产持有与运营","subScene":"运营维护","scene":"资产持有与运营·运营维护","cq":"我有好几套房子在出租，怎么管理更省心？","ola":"用管理App+台账+SOP，超5套建议托管","cp":["管理App统一管租约收租","Excel台账记录全状态","标准化SOP提效降错","超5套建议委托管家","核心是租期和收租追踪"],"detail":"多套房管理核心痛点：租期到期日分散难追踪、维修报修响应慢、租金到账不透明。解决方案：使用房东管理App（如蘑菇租房、水滴管家）统一管理租约和收租；建Excel台账记录每套房的租期/租金/维修/空置状态；设标准化SOP（入住清单、退租验收单、维修响应时限）。超5套房建议委托管家或组建小团队。","legalRef":"行业通行做法","consumerBenefit":"系统化管理降低遗漏和纠纷","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["多套房产管理工具","多套房出租怎么管","资产管理软件推荐"]},{"id":"OWN-RET-009","name":"自己的房子出租定多少租金合适","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"房东定的租金比周围都贵，我能怎么跟他砍价？","ola":"参考同小区成交价，结合装修及空置成本定价。","cp":["参考同小区同户型成交价","评估装修及家电配置溢价","考虑空置期带来的隐性成本","根据淡旺季动态调整租金"],"detail":"租金定价需综合考虑房屋自身条件、地段配套及市场供需。业主可通过参考同小区同户型近期成交价、咨询周边中介、评估房屋装修及家电配置来制定初始租金。定价过高易导致空置期延长，增加隐性成本；定价过低则损失收益。建议采用“略高于市场均价但留出议价空间”的策略，并根据淡旺季及空置成本动态调整。","legalRef":"行业通行做法及市场定价机制","consumerBenefit":"了解租金定价逻辑，在租房时能更合理地评估租金水平并进行议价。","tags":{"clientType":["landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["租房定价","出租房租金怎么定","租金定价策略"]},{"id":"OWN-RET-011","name":"找中介帮忙出租房子到底划不划算？","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"通过中介租房和直接找房东租有什么区别？","ola":"中介代租省心快捷但需付佣金，适合时间紧张的业主。","cp":["客源广出租快","需支付中介佣金","节省业主时间精力","需防范中介吃差价"],"detail":"中介代租是指业主将房屋出租事宜全权或部分委托给房产中介办理。优势在于中介客源广、带看效率高，能节省业主时间并快速匹配租客，同时协助处理合同及初期纠纷；劣势是需支付半个月至一个月租金作为佣金，且部分不良中介可能存在隐瞒房屋瑕疵或赚取差价的行为。业主需根据房屋空置成本与自身精力权衡是否选择。","legalRef":"《房地产经纪管理办法》第二十一条","consumerBenefit":"帮助租客了解中介代租模式，明确自身在租赁关系中的权利义务。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["中介代租好不好","房屋托管中介靠谱吗","找中介出租有什么优缺点"]},{"id":"OWN-RET-012","name":"房东自己直租房子要注意哪些坑？","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"直接和房东签合同租房，我需要注意看他的什么证件？","ola":"直租省中介费但需亲力亲为，务必核实身份并签规范合同。","cp":["省中介费但费时","必须核实租客身份","亲自签署规范合同","警惕二房东转租"],"detail":"房东自行出租即不通过中介直接与租客达成租赁意向。此方式可节省中介费，但需业主自行核实租客身份、起草合同、收取押金及租金。主要风险包括：遇到职业二房东违规转租、租客拖欠租金、房屋设施被恶意损坏等。业主需严格审查租客身份证件及工作证明，并亲自签署规范的租赁合同，明确各项维修与违约责任。","legalRef":"行业通行做法","consumerBenefit":"帮助租客在直租时识别真房东，避免遭遇二房东诈骗。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["个人出租房屋注意事项","房东直租怎么防骗","自己发招租信息要注意什么"]},{"id":"OWN-RET-035","name":"怎么算我这套出租房实际赚了多少？","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"房东算收益时把中介费也算在我头上，这合理吗？","ola":"总租金减去空置、维修、物业等所有持有成本。","cp":["总租金减去各项成本","扣除房屋空置期损失","核算维修与持有成本","评估真实盈利能力"],"detail":"租金收益是指房东出租房屋获得的净收入。计算公式为：租金收益 = 实际收取的总租金 - 房屋空置期损失 - 维修维护成本 - 物业费/取暖费等持有成本 - 中介费及税费。准确计算净收益有助于房东评估房屋的真实盈利能力，从而制定合理的租金定价和空置期管理策略。","legalRef":"行业通行做法","consumerBenefit":"了解收益计算逻辑，促进租赁双方对租金定价的合理预期。","tags":{"clientType":["landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["租房净收益","出租房利润计算","房屋出租收入"]},{"id":"P0-DEC-009","name":"六维测评卡评估法","domain":"交易综合","subScene":"客户解码","scene":"交易综合·客户解码","cq":"客户需求怎么量化比较？","ola":"六维打分：价格/品质/学区/通勤/投资/速度","cp":["六维度1-5分量化","非客户填而是经纪人评","评分生成客户类型标签","标签直接匹配带看策略"],"detail":"将客户需求量化为六个维度的评分卡：价格敏感度（1-5分，5=预算硬线）、品质敏感度（1-5分，5=非品质不可）、学区刚需度（1-5分，5=入学年限迫近）、通勤敏感度（1-5分，5=通勤时间硬约束）、投资属性（1-5分，5=纯投资）、决策速度（1-5分，5=急迫成交）。六维评分不是让客户填，是经纪人在2-3次沟通后根据观察打分。","legalRef":"行业惯例","consumerBenefit":"需求量化不再凭感觉推荐","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["六维测评","客户六维评估","测评卡法"]},{"id":"P0-DEC-CASE-009","name":"因为中介没按时交房导致我违约怎么办","domain":"交易综合","subScene":"客户解码","scene":"交易综合·客户解码","cq":"我买房是为了孩子上学，中介没盯紧导致延期交房孩子没学上，怎么办？","ola":"紧迫性需求未写入合同，仅能追究卖方逾期违约责任。","cp":["核心时间诉求必须写入书面合同","口头承诺难以追究中介违约责任","卖方逾期交房需承担违约赔偿","买方需主动要求明确关键时间节点"],"detail":"陈某购房核心诉求为赶在9月1日前落户以便孩子入学，其向经纪人明确表达了该时间紧迫性。经纪人未在合同中约定具体交房及户口迁出时间，仅口头承诺。后因卖方拖延，陈某未能按时落户，导致孩子无法入学。陈某起诉卖方及中介要求赔偿。法院认为，卖方逾期交房构成违约，需承担违约金；但陈某未将紧迫性写入合同补充条款，对中介的口头承诺举证不足，中介仅承担部分管理瑕疵责任。","legalRef":"《中华人民共和国民法典》第五百七十七条","consumerBenefit":"明确特殊时间需求必须通过书面合同条款固定。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前","见中"]},"alias":["中介没按时交房导致我违约怎么办","买房急用没按时交房能索赔吗","因为入住时间延误导致我违约"]},{"id":"P0-DEC-CASE-017","name":"刚买完学区房政策变了能找中介赔偿吗","domain":"交易综合","subScene":"客户解码","scene":"交易综合·客户解码","cq":"刚买完学区房，政策就变了变成多校划片，我能找中介赔偿吗？","ola":"学区政策变动属行政行为，中介未提示不担责。","cp":["学区政策变动属不可预见行政行为","中介无义务保证学区划片永久不变","未提示政策风险不构成欺诈","中介促成交易即有权收取报酬"],"detail":"柏某购买学区房，核心目的是子女入学。经纪人带看时未提示学区政策可能调整的风险。签约过户后，教育局出台新政，该小区实行多校划片，柏某子女无法进入对口名校。柏某以中介未提示风险、存在欺诈为由，起诉要求中介退还全额中介费并赔偿损失。法院认为，学区政策属政府行政行为，具有不可预见性。中介已促成交易，无证据证明中介故意隐瞒已知政策变动。依据《民法典》第九百六十二条，判决中介不承担赔偿责任。","legalRef":"《中华人民共和国民法典》第九百六十二条","consumerBenefit":"认清学区政策风险，不将政策变动责任归咎于中介。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前","见中"]},"alias":["买完学区房划片变了能索赔吗","学区房政策调整能找中介退钱吗","买房后学区政策变了中介要赔吗"]},{"id":"P0-NEG-CASE-013","name":"卖家承诺学区没落实能索赔吗","domain":"交易综合","subScene":"谈判斡旋","scene":"交易综合·谈判斡旋","cq":"买学区房发现名额被占了，孩子上不了学，能找卖家索赔吗？","ola":"卖家违反学区名额约定，需承担违约金及实际损失赔偿。","cp":["学区名额约定属合同核心条款","名额被占用构成根本违约","买方可主张违约金及实际损失","签约前必须核实学区名额状态","保留入学受阻的证据材料"],"detail":"孙某为子女上学购买二手房，合同明确约定“卖家保证该房屋学区名额未使用，若因名额问题导致无法入学，卖家承担违约责任”。过户后，孙某发现该房屋学区名额已被卖家子女占用。孙某诉至法院要求赔偿。法院审理认为，卖家违反合同明确约定，导致孙某购房目的无法实现。根据《民法典》第五百七十七条，法院判决卖家支付违约金20万元，并赔偿孙某子女就读私立学校的差价损失。","legalRef":"《中华人民共和国民法典》第577条","consumerBenefit":"确保学区条款写入合同，掌握名额被占时的索赔权利与取证方法。","tags":{"clientType":["buyer"],"stage":"mid","layer":"器","meetingPhase":["见中","见前"]},"alias":["学区房名额被占用能退房吗","卖家隐瞒学区名额被占","购房合同学区条款违约"]},{"id":"PRE-MATCH-012","name":"异形户型折价多少合理","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"这套房子户型不太方正，买的话折价多少合理？","ola":"刀把5%-10%，手枪8%-15%，三角10%-20%","cp":["刀把形折价5%-10%","手枪形折价8%-15%","三角形折价10%-20%","折价原因：面积浪费+采光差","刚需可考虑改善需避免"],"detail":"异形户型指非方正矩形布局的户型，常见类型：刀把形（走廊过长浪费面积）、手枪形（主卧突出采光差）、三角形（尖角空间无法利用）、L形（采光面窄）。异形户型折价幅度：刀把形折价5%-10%、手枪形折价8%-15%、三角形折价10%-20%。折价原因：面积利用率低（走廊/尖角无效面积）、采光通风差、家具布置困难、二次出售折价更多。建议：刚需预算紧可考虑，改善需求避免。","legalRef":"GB50096-2011《住宅设计规范》第5.1节；GB/T50362-2005《住宅性能评定技术标准》","consumerBenefit":"异形户型砍价有据，不按方正价买不规则房","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["刀把户型折价","手枪户型能买吗","跑道户型优缺点"]},{"id":"PRE-MATCH-059","name":"低密度住宅和高密度住宅差别有多大","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"低密度小区和高密度小区住起来差别大吗？","ola":"差别大，低密度采光好不挤但贵，看需求选","cp":["低密度容积率1.5以下","高密度容积率2.5以上","低密度采光好私密性强但贵","高密度配套好但资源紧张","改善选低密度刚需选高密度"],"detail":"低密度住宅通常指容积率1.5以下，以别墅、洋房、多层为主；高密度住宅容积率2.5以上，以高层、超高层为主。低密度优势：楼间距大采光好、绿化多环境优、人口密度低私密性好、电梯不拥挤停车方便；劣势：位置可能偏远、总价高、物业费高。高密度优势：通常位于核心区域、总价相对低、配套成熟；劣势：楼间距窄采光受限、公共资源紧张、噪音和隐私问题。自住改善优先低密度，刚需通勤优先高密度。","legalRef":"《城市居住区规划设计标准》GB50180-2018","consumerBenefit":"理解容积率对居住体验的影响，选对密度等级","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["容积率高低住着差别大吗","低密度住宅什么标准","容积率1.5以下什么体验"]},{"id":"PRE-MATCH-093","name":"看房时中介说的话能信多少","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"中介说的能信吗？","ola":"交叉验证，学区查教育局规划查政府文件","cp":["催促施压别上当","口头承诺不可信要自己核实","学区查教育局规划查政府","价格查成交记录交叉验证"],"detail":"中介信息需要交叉验证不可全信。常见套路：①'这套很抢手再不定就没了'（催促施压别上当）；②'对口XX名校'（口头承诺不可信必须自己核实）；③'业主急售底价XX'（底价是谈判起点不是真实底价）；④'这个小区明年通地铁'（规划≠通车）。验证方法：学区查教育局、规划查政府文件、价格查同小区成交记录、信息多方交叉核实。","legalRef":"《房地产经纪管理办法》第21条经纪人员不得隐瞒重要事实","consumerBenefit":"不踩中介信息坑","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["中介的话可信吗","中介怎么避坑","中介常见套路"]},{"id":"PRE-MATCH-099","name":"同价位不同区域怎么选","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"同样价格买核心小户型还是远郊大的？","ola":"自住选地段，核心小比远郊大更保值","cp":["自住刚需选地段","改善有车可选面积","投资必选地段","核心小户型保值流通远优于远郊大"],"detail":"同价位地段vs面积的选择原则：自住刚需选地段（通勤短配套好生活品质高）、改善有车族可选面积（牺牲地段换空间）、投资选地段（流通性远比面积重要）。核心区小户型保值性和流通性远优于远郊大户型，远郊大盘在下行周期跌幅更大且难出手。口诀：自住买地段、改善看面积、投资买地段。","legalRef":"行业通行做法","consumerBenefit":"地段面积取舍有原则","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["同样价格选哪个区","同价位远郊大vs近郊小","核心区小户型vs远区大户型"]},{"id":"PRE-NEED-019","name":"婚房什么时候买最合适","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我们准备结婚，婚房什么时候买比较好？写谁名字？","ola":"提前半年启动，婚前买属个人婚后买属共有","cp":["婚前买房属个人财产","婚后买房属共同财产","提前6-12个月启动","出资比例与署名要约定","双方公积金可合并用"],"detail":"婚房购房的核心决策点是产权登记时点：婚前购买登记在一方名下属于个人财产，婚后购买无论登记谁名下均属夫妻共同财产。建议在婚期前6-12个月启动购房流程，预留贷款审批和装修时间。婚房客户普遍预算紧张但品质需求高，常见矛盾是面积与总价的平衡。需特别关注：双方出资比例与产证署名约定、婚前财产协议的必要性、双方公积金能否合并使用。","legalRef":"《中华人民共和国民法典》第1062条（夫妻共同财产）、第1063条（个人财产）；最高人民法院关于适用《中华人民共和国民法典》婚姻家庭编的解释（一）第29条","consumerBenefit":"提前规划产权归属，婚后不因房产闹矛盾","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["结婚买房时机","婚前买房还是婚后买","婚房写谁名字"]},{"id":"PRE-NEED-028","name":"商业贷款能批多少","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我买200万的房子，商业贷款能批多少？","ola":"首套最高贷评估价85%，实际约150-160万","cp":["首套最高贷85%二套75%","银行按评估价不按成交价","评估价通常为成交价90%-95%","月供受DTI不超50%限制","实际可贷额度需预留差额"],"detail":"商业贷款额度=房屋评估价×贷款成数。贷款成数由首付比例倒推：首套最高可贷85%（对应首付15%），二套最高可贷75%（对应首付25%）。但银行实际审批额度受收入负债比限制（月供≤月收入50%），且采用评估价而非成交价计算，评估价通常为成交价的90%-95%。因此实际可贷额度=成交价×90%-95%×75%-85%，需自行预留差额。","legalRef":"《中国人民银行 国家金融监督管理总局关于调整个人住房贷款最低首付比例政策的通知》（2024年9月）","consumerBenefit":"提前算准可贷额度，不被差额打乱首付计划","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["商贷额度怎么算","贷款能贷几成","商贷最高额度"]},{"id":"PRE-NEED-044","name":"老人被骗买房怎么维权","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我爸妈被中介忽悠买了套有问题的房子，能退吗？","ola":"收集欺诈证据1年内起诉撤销，可投诉中介和消协","cp":["收集欺诈证据1年内起诉撤销","向住建局投诉中介违规","限民事行为老人签约需代理人同意","虚假宣传学区可追责","保留宣传资料作证据"],"detail":"老年人购房被骗常见手段：虚假宣传学区/地铁规划、隐瞒房屋重大瑕疵、诱导签订不利条款、冒充子女签字。维权途径：收集欺诈证据（宣传资料、录音录像、证人证言）在1年内起诉撤销合同；向住建局投诉经纪机构违规；向消协投诉。根据《民法典》，限制民事行为能力人实施的纯获利益或与其智力精神健康状况相适应的民事法律行为有效，其他需法定代理人同意。","legalRef":"《中华人民共和国民法典》第145条（限制民事行为能力人）、第148条（欺诈撤销权）、第152条（撤销权期限）；《中华人民共和国消费者权益保护法》第55条（欺诈三倍赔偿）","consumerBenefit":"帮父母维权追回损失，让骗子付出代价","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前","见后"]},"alias":["老年人购房被骗","老人被忽悠买房","老年人买房维权"]},{"id":"PRE-NEED-052","name":"有老人同住选几楼最好","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我爸妈跟我们一起住，买几楼比较好？","ola":"有老人优先选低楼层1-3层，出行方便不靠电梯","cp":["低楼层出入方便不依赖电梯","中楼层兼顾采光与出行","高楼层停电老人出行困难","7层以上必须设电梯","老人房优先选1-3层"],"detail":"有老人同住的家庭选房，楼层是核心考量因素。低楼层（1-3层）出入方便、不依赖电梯、灾害逃生容易，但可能采光不足、潮湿、噪音大。中楼层（4-6层）兼顾出入与采光，是老人家庭折中方案。高楼层采光好但电梯依赖度高，停电或故障时老人出行困难。《住宅设计规范》规定7层及以上须设电梯，12层及以上电梯不少于2台。","legalRef":"《住宅设计规范》GB50096-2011第6.1.1条、第6.1.2条","consumerBenefit":"老人出行安全便利，电梯故障不影响日常生活","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["老人住几楼合适","有老人选什么楼层","老人房楼层推荐"]},{"id":"PRE-NEED-053","name":"二胎家庭需要几室才够住","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我们有两个孩子，买几室的房子才够住？","ola":"两孩至少三室，带老人至少四室，双卫更实用","cp":["两孩至少三室理想四室","带老人至少四室","儿童房面宽不低于2.7米","双卫配置减少早高峰冲突","户型方正利用率高"],"detail":"二胎家庭选房的核心矛盾是房间数量与总价的平衡。两孩家庭至少需要三室（主卧+两间儿童房），理想配置为四室（主卧+两间儿童房+书房/老人房）。如与老人同住则至少四室。户型选择需注意：儿童房面宽不宜低于2.7米，进深不宜超过3.9米，主卧建议3.3米以上面宽。同时需考虑双卫配置减少早高峰抢卫生间问题。","legalRef":"《人口与计划生育法》第18条","consumerBenefit":"选对户型一步到位，避免二胎后又得换房","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["二胎选几居室","两个孩子要几室房","二胎家庭户型推荐"]},{"id":"PRE-NEED-054","name":"单身买房选一居还是两居","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我一个人住，买一居室还是两居室好？","ola":"预算允许优先两居，可自住+出租，未来不用急换房","cp":["一居总价低但流通性弱","两居可自住+出租补贴月供","两居未来结婚不用急换房","一居适合纯过渡自住","两居流通性远优于一居"],"detail":"单身购房选择一居还是两居，关键看预算与未来规划。一居室总价低、月供压力小，适合纯自住且预算紧张的客户；但一居室功能单一、流通性弱，未来结婚换房时可能难出手。两居室总价高约30%-50%，但功能分区合理、流通性强，可自住一间出租一间补贴月供，未来结婚不用立刻换房。建议预算允许时优先选两居。","legalRef":"《中华人民共和国民法典》第240条（所有权）","consumerBenefit":"一步到位省去换房成本，出租可补贴月供","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["单身买什么户型好","一个人住要多大面积","单身公寓还是两居室"]},{"id":"PRE-NEED-055","name":"三代同堂选多大房子合适","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我爸妈和我们一家三口一起住，买多大的房子合适？","ola":"至少四室两卫130平以上，老人房靠近卫生间","cp":["三代同堂至少四室两卫","老人房靠近卫生间","主卧与老人房保持隐私距离","建筑面积建议130平以上","公共活动空间不可少"],"detail":"三代同堂家庭（老人+夫妻+孩子）选房，至少需要四室两卫，建筑面积建议130平方米以上。核心需求：老人房尽量靠近入户门或卫生间，减少夜间走动距离；主卧与老人房保持适当距离以保障各自隐私；至少双卫配置，主卫最好在主卧套内；需要独立的公共活动空间。若预算紧张，三室两卫可通过客餐厅分区弥补。","legalRef":"《中华人民共和国民法典》第240条（所有权）","consumerBenefit":"家人各有私密空间，生活不互相干扰","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["三代同住要多大面积","跟父母住买几室好","三代人一起住选什么户型"]},{"id":"PRE-NEED-057","name":"离婚后名下无房再买算首套吗","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我刚离婚，想自己买套房，算首套还是二套？","ola":"各地政策不同，北京离婚1年内按二套贷，需核实","cp":["北京离婚1年内按二套贷款","上海按离婚前家庭套数认定","各地政策差异大需核实","需带离婚证和协议核验资格","防假离婚规避限购是政策初衷"],"detail":"离婚后购房的套数认定，不同城市政策差异大。北京规定离婚1年内购房按二套贷款政策执行；上海离婚后住房套数按离婚前家庭总套数计算；广州部分区域离婚1年内按二套认定。各地对离婚购房的限制主要是防止通过'假离婚'规避限购限贷政策。客户需携带离婚证、离婚协议或法院判决书到房管部门核验购房资格。","legalRef":"《关于调整优化差别化住房信贷政策的通知》（银发〔2023〕194号）；各地住建部门限购实施细则","consumerBenefit":"提前了解认定规则，不因套数认定错误多付首付利息","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["离婚后购房算几套","离婚买房算首套吗","离异购房资格怎么认定"]},{"id":"PRE-NEED-095","name":"家里有几个人住怎么选户型","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我们家三口人，买几室合适？","ola":"三口人选三居，预留一间灵活空间","cp":["卧室数≥人口数-1","刚需两居70-90三居90-120","二胎必须三居+双卫","改善面积上浮30-50%"],"detail":"户型选择核心原则：卧室数≥常住人口数-1（预留客房或书房）。两口选两居、三口选三居、四口及以上选三居或四居。面积参考：刚需两居70-90㎡、三居90-120㎡；改善三居120-140㎡、四居140-180㎡。二胎家庭务必选三居以上且至少两个卫生间，避免早高峰抢卫。","legalRef":"行业通行做法","consumerBenefit":"户型匹配家庭结构，住得舒服","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["几口人选多大房","户型怎么选适合家人","两居室三居室怎么选"]},{"id":"PRE-NEED-104","name":"家里老人出钱买房写谁名字","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我爸妈出首付，房产证写我名字行吗？","ola":"可以但婚后一般算共同财产，建议签协议","cp":["婚后出资一般视为共同财产","出资前签书面协议明确性质","加名需银行同意或还清贷款","赠与和借款法律后果不同"],"detail":"父母出资买房的产权归属取决于出资时间、登记方式、婚姻状态。婚后父母全额出资登记在子女名下，如无特别约定视为对子女个人赠与；首付出资则一般视为夫妻共同财产。建议：出资前签书面协议明确出资性质（赠与or借款）和产权归属，避免后续纠纷。加名需还清贷款或有银行同意。","legalRef":"《中华人民共和国民法典》第1062条夫妻共同财产；最高人民法院婚姻家庭编司法解释(一)第29条","consumerBenefit":"家庭出资不扯皮，产权清晰","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["父母出资房产归属","买房写谁名字好","老人出钱写子女名行吗"]},{"id":"PRE-NEED-111","name":"二胎家庭买房怎么选","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"家里马上要二胎了，房子要怎么选？","ola":"三室两卫120平起，两孩同校区最省心","cp":["至少三室两卫","面积120㎡以上","两孩同校区方便接送","储物空间要加倍"],"detail":"二胎家庭选房四个硬性需求：①至少三室两卫（两个孩子+老人帮带需独立空间）；②面积120㎡以上（四口+老人同住需5人空间）；③学区优先三室（两个孩子在同一学区入学）；④储物空间要大（两个孩子物品量翻倍）。注意：如果头胎已入学，二胎学区需确认是否与头胎同一学校以方便接送。","legalRef":"行业通行做法","consumerBenefit":"一家住得下，孩子上学方便","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["二胎要换房吗","二胎户型要求","两个孩子选多大房"]},{"id":"PRE-NEED-114","name":"买房要不要看小区绿化","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"小区绿化率多少算好？","ola":"30%及格35%良好，别被植草砖忽悠","cp":["绿化率≥30%合格35%良好","区分绿化率和绿地率","高绿化通常低容积率","刚需30%够改善35%+"],"detail":"绿化率直接影响小区微气候和居住舒适度。标准：新建小区绿化率≥30%为合格、35%以上为良好、40%以上为优秀。但需区分绿化率和绿地率（后者要求更严格不含植草砖等）。高绿化率通常伴随低容积率，也意味着公摊面积大、房价偏高。选择时平衡绿化与价格，刚需30%即可，改善追求35%+。","legalRef":"《城市居住区规划设计标准》GB50180-2018绿地率要求","consumerBenefit":"小区环境好，住得舒服","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["绿化率多少算好","小区环境重不重要","绿化率影响居住吗"]},{"id":"PRE-NEED-132","name":"买房选高楼层还是低楼层好","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"买高层还是低层好？","ola":"年轻选中高层，有老人选3-5楼","cp":["高采光好但等电梯怕停电","低出行便但潮噪蚊虫多","年轻选中高老人选低","超高层火灾逃生是大问题"],"detail":"高楼层优势：视野好、采光好、通风好、噪音小、蚊虫少、隐私性强；劣势：等电梯久、停水水压低、停电爬楼痛苦、火灾逃生难、公摊大。低楼层优势：出行方便、停水无感、逃生容易、适合老人；劣势：采光差、潮湿蚊虫、噪音大、安全差。年轻人选中高层兼顾视野和便利，有老人家庭选3-5楼。","legalRef":"《建筑设计防火规范》GB50016-2014高层建筑消防要求","consumerBenefit":"楼层匹配需求住得舒服","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["高层低层哪个好","高楼和矮楼怎么选","住高住低各有什么优缺点"]},{"id":"PRE-PRICE-007","name":"契税到底要交多少","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"我买首套房90平米，契税要交多少？","ola":"首套≤90㎡交1%，>90㎡交1.5%，按不含增值税成交价算","cp":["首套≤90㎡1%，>90㎡1.5%","二套≤90㎡1%，>90㎡1%/2%","三套及以上3%","以省为单位认定家庭套数","逾期按日加收0.05%滞纳金"],"detail":"契税税率按家庭住房套数和面积分档：首套≤90㎡税率1%，首套>90㎡税率1.5%；二套≤90㎡税率1%（北上广深二套>90㎡为2%，其他城市1%）；三套及以上统一3%。计算基数为不含增值税的成交价。家庭套数认定以省为单位，夫妻及未成年子女为同一家庭。注意：契税应在纳税义务发生之日起10日内申报、20日内缴纳，逾期按日加收万分之五滞纳金。","legalRef":"《中华人民共和国契税法》第3条；财政部 税务总局 住建部《关于契税法实施后有关优惠政策衔接问题的公告》（2021年第29号）","consumerBenefit":"算准契税不超预算，首套小户型最划算","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["首套契税1%还是1.5%","契税90平以下和以上区别","家庭唯一住房契税优惠"]},{"id":"PRE-PRICE-010","name":"维修基金怎么交交多少","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"买房还要交维修基金吗？交多少？","ola":"新房交100-200元/㎡，二手房随房转不重缴","cp":["多层约100元高层150-200元/㎡","新房开发商代收代缴","二手房随房转移不重缴","使用需2/3以上业主同意","用于共用部位大修"],"detail":"住宅专项维修资金（俗称维修基金）是用于住宅共用部位共用设施设备保修期满后大修和更新的专项资金。缴纳标准：多层住宅约100元/㎡、高层住宅约150-200元/㎡（各城市标准不同，北京六层以下100元/㎡、六层以上200元/㎡）。新房由开发商代收代缴，二手房交易时维修基金随房转移不需重新缴纳。使用维修基金需经专有部分占建筑物总面积三分之二以上的业主且占总人数三分之二以上的业主同意。","legalRef":"《住宅专项维修资金管理办法》第7条（交存标准）、第12条（分摊规则）、第22条（使用条件）","consumerBenefit":"算清维修基金成本，二手房省这笔钱","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["公共维修基金标准","维修基金谁交","维修基金多少一平米"]},{"id":"PRE-PRICE-030","name":"买期房怎么判断价格合不合理","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"期房比旁边的二手房贵不少，值不值？","ola":"贵10%-20%正常，折价系数超1.3需警惕，核实配套兑现度","cp":["期房比同区二手房贵10%-20%正常","折价系数超1.3需警惕","查开发商交付品质口碑","核实规划配套是否已开工","配套未兑现房价可能回调"],"detail":"期房定价通常比同区域二手房高10%-20%（溢价来自全新+开发商品牌+规划配套），但交付时可能因市场变化导致二手房倒挂。判断期房价格合理性：①对比同区域3个以上二手房小区成交均价②计算折价系数=期房单价/周边二手房均价，正常1.0-1.2，超1.3需警惕③查开发商前期楼盘交付品质④核实规划配套兑现时间。特别注意：期房含期许溢价，交付时配套未兑现房价可能回调。","legalRef":"《城市商品房预售管理办法》第6条（预售条件）；《商品房销售管理办法》第23条（明码标价）","consumerBenefit":"不为期许溢价买单，配套不兑现就是虚高","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["期房价格评估","新房价格对比方法","期房值不值这个价"]},{"id":"PRE-PRICE-040","name":"契税1%和1.5%怎么区分适用","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"首套房契税是1%还是1.5%？怎么区分？","ola":"首套90平以下1%，90平以上1.5%，二套另有规则","cp":["首套90平以下1%以上1.5%","二套90平以下1%以上2%","一线城市二套90平以上3%","三套及以上统一3%","套数以家庭成员为单位认定"],"detail":"契税优惠税率适用规则：个人购买家庭唯一住房（家庭成员范围包括购房人、配偶及未成年子女），面积90平方米及以下的减按1%征收，90平方米以上的减按1.5%征收。个人购买家庭第二套改善性住房，面积90平方米及以下的减按1%征收，90平方米以上的减按2%征收（北上广深等一线城市二套90平以上仍按3%）。三套及以上统一3%。住房套数以家庭成员为单位认定。","legalRef":"《关于调整房地产交易环节契税 营业税优惠政策的通知》（财税〔2016〕23号）；《中华人民共和国契税法》第3条","consumerBenefit":"算准契税不花冤枉钱，买小户型省更多","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["契税1%什么条件","首套90平以下契税多少","二套房契税1%还是2%"]},{"id":"PRE-PRICE-056","name":"新房能不能砍价","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"新房价格还能谈吗？","ola":"能，3-8%空间，月底年末更好谈","cp":["底价在销售权限3-5%经理再加1-2%","月底年末冲刺期优惠大","团购渠道额外1-3%","首次报价有3-5%水分"],"detail":"新房砍价空间3-8%，比二手房小但有技巧：①先问底价再选房（销售有折扣权限通常3-5%，找销售经理可再加1-2%）；②月底/季末/年末冲刺期优惠更大；③团购/渠道客户额外折扣1-3%；④全款比贷款多1-3%折扣；⑤车位/装修包打包谈更优惠。注意：售楼处报价≠底价，首次报价通常有3-5%水分可挤。","legalRef":"行业通行做法","consumerBenefit":"新房不买挂牌价","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["新房价格能谈吗","售楼处能砍价吗","新房优惠怎么谈"]},{"id":"PRE-PRICE-063","name":"维修基金要交多少","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"维修基金要交多少？","ola":"高层约150元/㎡，新房交房前一次性交","cp":["多层约100元/㎡高层130-200元","新房交房前缴纳二手随房转移","用于共用设施大修更新","需2/3业主同意才可用"],"detail":"住宅维修基金标准：商品房按当地住建部门公布标准缴纳，通常多层约100元/㎡、带电梯高层约130-200元/㎡。缴纳时点：新房在交房前缴纳、二手房如原业主已缴纳则无需再交（随房转移）。维修基金用于住宅共用部位共用设施设备大修中修更新改造，使用需2/3以上业主同意。这笔钱一次性缴纳较大但不可省。","legalRef":"《住宅专项维修资金管理办法》第7条交存标准","consumerBenefit":"维修基金预算不遗漏","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["维修基金怎么算","物业维修基金标准","维修基金谁出"]},{"id":"PRE-PRICE-068","name":"房价下行能等吗","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"房价还在跌我要不要再等等？","ola":"刚需不等改善可等但别超半年","cp":["刚需不等居住需求不等人","改善可观望但不宜超6个月","投资等明确信号","精准抄底概率极低"],"detail":"房价下行期观望与否取决于需求类型：刚需自住不必等（居住需求不等人、租金也在支出、利息差有限）；改善可适度观望但不宜超6个月（好房源不等人）；投资建议等明确信号再入场。历史数据看：精准抄底概率极低，等底往往等到反弹才追高。刚需原则：看到合适的就买，不追求买在最低点，买在合理点即可。","legalRef":"行业通行做法","consumerBenefit":"不因观望错过合适房源","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["房价在跌要不要等","现在买还是等降了再买","房价还会继续跌吗"]},{"id":"PRE-PRICE-071","name":"挂牌价是不是还能再降","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"挂牌价还能再降吗？","ola":"挂牌超3个月或多次调价说明还有空间","cp":["挂牌与底价差5-10%","超3个月挂牌有较大空间","调价记录多=急售空间大","报低3-5%试探底线"],"detail":"挂牌价与业主底价通常差5%-10%，判断降价空间：①挂牌时长（超3个月通常有5-10%空间）；②调价记录（已降3次以上说明业主急售空间大）；③同小区竞品（比同户型成交价高5%以上有空间）；④卖方原因（急用钱/换房急=大空间，不急=小空间）。试探方法：报一个低于成交价3-5%的价格看卖方反应判断底线。","legalRef":"行业通行做法","consumerBenefit":"降价空间有判断","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["挂牌价能砍多少","业主底价怎么看","怎么试探业主底线"]},{"id":"PRE-PRICE-083","name":"房价怎么谈才能谈到最低","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"怎么才能把价格谈到最低？","ola":"拿数据+找硬伤+比竞品+控节奏","cp":["准备数据+硬伤+竞品","首次报价低于心理价10%","拉锯中释放有其他选择信号","降幅收窄时一锤定音"],"detail":"砍价到最低的四步法：①准备阶段——查3套成交价+找5个硬伤+准备3个竞品房源；②开局——首次报价低于心理价10%（留谈判空间）；③拉锯——卖方每降一次你升一次、控制节奏不急不慢、适时表示'我还有别的好选择'；④收尾——当降价幅度收窄（每次只降1-2万）说明接近底线，此时一次出价定胜负。全程保持真诚不撕破脸。","legalRef":"行业通行做法","consumerBenefit":"砍价到心中有数","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["砍价终极技巧","怎么谈到业主底线","砍价心理战"]},{"id":"PRE-PRICE-098","name":"二套房税费比首套多多少","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"二套房税费比首套多多少？","ola":"契税多0.5-1.5%，主要贵在首付比例","cp":["契税二套比首套多0.5-1.5%","增值税个税与套数无关","首付差异是最大差距","二套资金门槛远高于首套"],"detail":"首套vs二套税费主要差异在契税：首套90㎡下1%/90㎡上1.5%，二套90㎡下1%/90㎡上2%（北上广深3%）。以200万90㎡以上为例：首套契税3万、二套契税4万（差1万）、深二套6万（差3万）。增值税和个税看房产年限与套数无关。叠加首付差异（首套20-30%vs二套40-60%），二套总资金门槛远高于首套。","legalRef":"《关于调整房地产交易环节契税营业税优惠政策的通知》二套契税税率","consumerBenefit":"二套成本算得清","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["二套税费增加多少","首套二套税费差异","二套增值税和首套一样吗"]},{"id":"PRE-QUAL-007","name":"认房不认贷和认房又认贷区别在哪","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我名下有贷款但房子已经卖了，再买算首套还是二套？","ola":"认房不认贷下名下无房就算首套，不管贷款记录","cp":["认房不认贷2023年8月全国执行","只看当地名下有无住房","外地有房本地无房算首套","认房又认贷仅少数核心区执行","当前主流认定标准=认房不认贷"],"detail":"首套认定有三种标准：①认房不认贷——只看当地名下有无住房，有贷款记录但名下无房仍算首套（2023年8月起全国执行）②认房又认贷——名下有房或有贷款记录都算二套（目前仅少数城市核心区执行）③认贷不认房——只看有无贷款记录，名下有房无贷款算首套（2014-2016年部分城市执行过）。当前主流是认房不认贷，意味着在外地有房有贷款但在本地无房的，本地购房可按首套享受首付比例和利率优惠。","legalRef":"《关于优化个人住房贷款中住房套数认定标准的通知》（住建部等三部门，建房〔2023〕52号）","consumerBenefit":"卖旧买新可享首套待遇，首付更低利率更低","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["首套认定标准","认房认贷认房不认贷区别","有贷款记录还算首套吗"]},{"id":"PRE-QUAL-008","name":"外地有房本地再买算几套","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我在老家有一套房，在北京再买算首套还是二套？","ola":"多数城市只查本地算首套，但部分银行查征信全国记录","cp":["认房不认贷多数城市只查本地","一线城市部分银行查全国贷款记录","不动产登记尚未全国联网","征信系统已覆盖全国贷款记录","建议同时查住建局和央行征信"],"detail":"认房不认贷下，外地有房本地再买的套数认定取决于城市：多数城市只查本地房产，外地有房本地无房按首套认定；但一线城市核心区可能要求查询全国贷款记录，有异地贷款记录按二套认定（部分银行内部执行，非官方规定）。全国不动产登记信息尚未完全联网，但央行个人征信系统已覆盖全国贷款记录。建议购房前同时查询当地住建局购房资格和央行个人征信，双线确认套数认定结果。","legalRef":"建房〔2023〕52号；《不动产登记暂行条例》第27条","consumerBenefit":"提前双线确认套数认定，不签约后才发现被按二套","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["异地房产影响本地购房吗","跨城市套数认定","不同城市分别算套数吗"]},{"id":"PRE-QUAL-039","name":"婚前一方名下有房婚后另一方算二套吗","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我老公婚前有套房，我名下没有，我买房算首套还是二套？","ola":"婚后以家庭为单位算二套，首付和利率都更高","cp":["婚后以家庭为单位认定套数","婚前一方有房婚后另一方算二套","二套首付比例和利率更高","外地房产是否计入看当地政策","购房前咨询当地认定标准"],"detail":"婚后购房的套数认定以家庭为单位，包含夫妻双方及未成年子女。婚前一方名下有房，婚后另一方购房通常认定为家庭第二套房，适用二套房贷款政策（首付比例更高、利率更高）。例外情况：如婚前房产在限购城市以外且当地限购政策以本市住房套数认定，则另一方可按首套认定。认定规则因城市而异，购房前需咨询当地住建部门和银行的具体认定标准。","legalRef":"《关于调整差别化住房信贷政策的通知》（银发〔2023〕194号）","consumerBenefit":"提前了解套数认定，做好首付和利率的预算规划","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["婚前有房婚后买房算几套","婚后买房查谁的征信","配偶名下有房自己买房算二套吗"]},{"id":"PRE-QUAL-040","name":"有过一次房贷记录再买算几套","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"以前贷过款但已经还清了，再买算首套还是二套？","ola":"认房不认贷城市名下无房按首套，多数城市已执行","cp":["认房不认贷名下无房按首套","认房又认贷有贷款记录按二套","2023年9月后多数城市认房不认贷","一线城市已改为认房不认贷","具体以贷款银行认定标准为准"],"detail":"是否认定为二套取决于当地是'认房又认贷'还是'认房不认贷'。认房不认贷（2023年9月后多数城市已实施）：只要名下无住房，无论之前有无贷款记录，均按首套贷款政策执行。认房又认贷（少数城市仍在执行）：只要有过房贷记录，即使已还清且名下无房，再购仍按二套认定。北京、上海等一线城市已改为认房不认贷。具体政策需向贷款银行确认，不同银行认定标准可能不同。","legalRef":"《关于调整优化差别化住房信贷政策的通知》（银发〔2023〕194号）","consumerBenefit":"利用认房不认贷政策享受首套利率和首付优惠","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["有过贷款记录再买房算几套","贷款已还清再买算首套吗","认房不认贷什么意思"]},{"id":"PRE-QUAL-049","name":"二套房首付和利率高多少","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我已经有一套房了，再买首付要多少？","ola":"二套首付四到六成，利率也比首套高","cp":["二套首付40-60%远高于首套","利率比首套高0.6%左右","认定标准认房又认贷最严","结清再买可能仍算二套"],"detail":"二套房首付和利率均显著高于首套：首付商贷40%-60%（一线更高）、公积金30%-40%；利率商贷LPR+60BP起（比首套高约0.6%）、公积金3.325%（比首套高0.675%）。二套认定标准：认房又认贷（多数城市）或认房不认贷（少数放松城市）。已有房贷结清再买仍可能被认定为二套，需查当地认定标准。","legalRef":"《关于调整差别化住房信贷政策的通知》二套房认定及首付利率","consumerBenefit":"二套成本算清不被吓到","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["二套贷款利率","首套二套差别多大","已有房再买算几套"]},{"id":"PRE-QUAL-062","name":"离婚后买房资格怎么算","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"离婚了还能按首套买房吗？","ola":"部分城市离婚3年内仍算二套，别假离婚","cp":["部分城市离婚1-3年限购","原房贷未结清影响负债认定","假离婚有真离婚风险","财产分割纠纷难以预料"],"detail":"离婚后购房资格各地政策差异大。部分城市对离婚1-3年内购房按原家庭套数认定（防假离婚），如北京离婚3年内仍按二套执行。离婚后贷款如原房贷未结清影响负债认定。法律风险：为买房假离婚可能导致真离婚财产分割纠纷，对方反悔不复合则房产归属争议。切勿为购房资格假离婚，风险远大于收益。","legalRef":"各城市限购政策中离婚购房特别条款","consumerBenefit":"不因资格问题冒法律风险","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["离婚买房算几套","离婚后限购吗","离婚买房要等多久"]},{"id":"PRE-QUAL-076","name":"买房契税怎么交","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"买房契税要交多少？","ola":"首套1-1.5%二套1-3%，90平是分界线","cp":["首套1-1.5%二套1-3%","90平是税率分界线","办证前必须缴纳","逾期有滞纳金"],"detail":"契税是购房必须缴纳的税费，税率：首套90㎡及以下1%、90㎡以上1.5%；二套90㎡及以下1%、90㎡以上2%（北上广深二套统一3%）。契税=房屋成交价×税率。缴纳时间：办理不动产权证前。契税优惠需满足家庭名下无房（首套认定），二套无优惠。购房后3年内未缴契税会产生滞纳金。","legalRef":"《中华人民共和国契税法》第3条税率；《关于调整房地产交易环节契税营业税优惠政策的通知》","consumerBenefit":"契税算准预算不超","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["契税多少","首套契税税率","90平以上契税区别"]},{"id":"PRE-QUAL-097","name":"首套资格被误判为二套怎么办","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我没房却被算成二套怎么办？","ola":"查名下记录有误持凭证更正，换银行或找住建","cp":["核对名下房产和贷款记录","不动产信息有误持凭证更正","向银行申诉或换银行","政策争议找住建部门"],"detail":"首套资格被误判为二套的解决路径：①先确认认定标准是认房又认贷还是认房不认贷，核对名下房产和贷款记录是否准确；②如不动产查询有误（如已出售未过户仍显示在名下），持过户凭证到不动产中心更正；③如银行认定有误可向该行申诉或换认定更宽松的银行；④如属政策争议可向当地住建部门咨询投诉。","legalRef":"各城市差别化住房信贷政策及异议处理机制","consumerBenefit":"首套优惠不丢","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["首套认定有误怎么办","资格认定争议怎么解决","被算二套实际是首套"]},{"id":"PRE-SCH-004","name":"九年一贯制直升有什么好处","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"九年一贯制的学校和普通学校比有什么好处？","ola":"小升初100%直升不受派位影响，9年确定性值5%-10%溢价","cp":["小升初100%直升不受派位影响","9年确定性强溢价更高5%-10%","课程衔接更顺畅","学位锁定9年更清晰","部分学校可选择不直升参加派位"],"detail":"九年一贯制学校指小学和初中在同一所学校连续就读，小升初无需参加派位或考试直接直升。优势：①确定性高——小升初100%直升，不受多校划片影响②节省精力——无需准备小升初③课程衔接更顺畅④学位锁定更清晰。对学区房的影响：九年一贯制学区房溢价更高（比纯小学学区房高5%-10%），因为9年确定性更有价值。","legalRef":"《义务教育法》第12条（就近入学）；各城市九年一贯制学校招生办法","consumerBenefit":"买九年一贯制学区房，9年入学不用愁","tags":{"clientType":["buyer"],"stage":"pre","layer":["术"],"meetingPhase":["见前"]},"alias":["九年一贯制学校优势","直升初中不用考吗","九年制学区房值不值"]},{"id":"PRE-SCH-011","name":"合同里怎么写学区条款才安全","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买学区房合同里怎么写才能保护我？","ola":"写明对口校名+学位未占+户口迁出+违约金","cp":["写明对口学校全称和学位未占用","约定户口迁出时限和日万分之五违约金","学位不实可解约双倍返还定金","学区变更可解约（法院可能不支持）","四项条款缺一不可"],"detail":"学区条款是学区房购房合同的必备补充条款，建议包含四项：①学区确认——卖方确认该房产对口XX学校且学位未被占用②户口迁出——卖方承诺在约定期限前迁出全部户口，逾期按日支付总房款万分之五违约金③学位保证——学位不实买方有权解除合同并双倍返还定金④学区变更——如因政府调整导致对口学校变更买方有权解约。","legalRef":"《中华人民共和国民法典》第470条（合同主要条款）、第577条（违约责任）、第587条（定金罚则）","consumerBenefit":"合同写清学区承诺，出了问题有据维权","tags":{"clientType":["buyer"],"stage":"pre","layer":["道"],"meetingPhase":["见前"]},"alias":["购房合同学区约定","学区条款补充协议","学区承诺怎么写合同"]},{"id":"PRE-SCH-014","name":"学区名额占用纠纷怎么打官司","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买完学区房发现学位被前业主占了，能告他吗？","ola":"隐瞒学位占用构成欺诈，可撤销合同双倍退定金","cp":["隐瞒学位占用构成欺诈可撤销","合同有学区条款违约金有保障","无学区条款法院可能减轻卖方责任","胜诉关键：合同条款+卖方承诺","可主张退还房款+赔偿损失"],"detail":"学位被前业主占用引发的纠纷，法院一般支持买方：①卖方隐瞒学位被占用构成欺诈，买方可请求撤销合同并双倍返还定金②合同约定学位未占用条款的，卖方违约需支付违约金③合同未约定学区条款的，法院可能以买方自身未核实为由减轻卖方责任。真实案例：卖方隐瞒学位占用，法院判决撤销合同、退还购房款、赔偿中介费和利息。","legalRef":"《中华人民共和国民法典》第148条（欺诈撤销权）、第500条（缔约过失责任）、第577条（违约责任）、第587条（定金罚则）","consumerBenefit":"法律保护你，但合同有条款维权更有力","tags":{"clientType":["buyer"],"stage":"pre","layer":["器","道"],"meetingPhase":["见前"]},"alias":["学位占用起诉案例","学区纠纷判例","学位被占维权途径"]},{"id":"PRE-SCH-022","name":"学区划片调整有法律救济途径吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"学区划片变了，我买的学区房白买了，能维权吗？","ola":"合同约定了学区可维权，没约定属政策风险很难追","cp":["学区调整属行政行为一般不构成违约","合同约定学区的可依违约条款维权","合同未约定学区属政策风险自担","开发商虚假宣传可主张欺诈","中介明知变更仍承诺可追责"],"detail":"学区划片调整属于教育行政行为，一般不构成开发商或卖方的违约（除非合同中有特别约定）。法律救济途径有限：如果购房合同中明确约定了学区学校，且调整导致无法入学，可依据合同违约条款主张权利；如果合同未约定学区，法院通常认定学区属于政策风险，买方自行承担。但在以下情形可尝试维权：开发商虚假宣传特定学区构成欺诈；中介明知学区变更仍承诺原学区。","legalRef":"《中华人民共和国民法典》第148条（欺诈）；第500条（缔约过失责任）","consumerBenefit":"了解法律边界，合同中写好学区条款才是真保障","tags":{"clientType":["buyer"],"stage":"pre","layer":["道"],"meetingPhase":["见前"]},"alias":["学区调整能起诉吗","划片变了怎么维权","学区政策变化能否退房"]},{"id":"PRE-SCH-031","name":"九年一贯制和普通小学初中分开哪个好","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"九年一贯制的学校好不好？和普通小学比有什么优势？","ola":"直升初中确定性最高，但必须初中质量也行才行","cp":["九年一贯制可直升初中确定性最高","免去小升初焦虑和教育断层","部分学校初中弱直升反而不如派位","选择时必须同时评估小学和初中质量","有些学校允许放弃直升参加派位"],"detail":"九年一贯制学校小学部毕业后可直升本校初中部，无需参加小升初摇号或对口派位，确定性最高。优势：免去小升初焦虑、教育连贯性好、学位确定性高（只要进了小学就保证初中名额）。劣势：部分九年一贯制学校小学部强但初中部弱，直升反而不如参加派位去更好的初中；有些九年一贯制允许小升初时放弃直升参加派位，有些不允许。选择时需同时评估小学和初中的教学质量，不应只看小学排名。","legalRef":"《义务教育法》第12条","consumerBenefit":"理解九年一贯制优劣，选到真正持续优质的学区","tags":{"clientType":["buyer"],"stage":"pre","layer":["术"],"meetingPhase":["见前"]},"alias":["九年一贯制有什么优势","九年一贯制学区稳定吗","直升初中好不好"]},{"id":"PRE-SCH-CASE-007","name":"中介承诺买学区房一定能上对口学校被调剂能索赔吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"中介微信上说肯定能上对口学校，结果被调剂了，我能让中介赔钱吗？","ola":"入学政策非中介可控，未写入合同索赔难。","cp":["入学政策非中介可控","居间方无权保证入学","未写入合同难获支持","口头承诺对口无效"],"detail":"周某通过中介购买学区房，中介在微信中承诺“100%上对口小学”。入学时因该小区多校划片，周某子女被调剂。周某起诉中介索赔。法院认为，入学政策由教育部门制定，中介作为居间方无权也无法保证入学结果，其承诺超出居间服务范围，且周某未将“必须上对口学校”写入合同作为解除条件，判决驳回周某诉求。","legalRef":"《中华人民共和国民法典》第九百六十二条","consumerBenefit":"认清中介居间服务边界，将核心诉求落实到书面合同条款中。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["中介承诺对口学校能索赔吗","学区房被调剂能找中介吗","中介保证上对口学校"]},{"id":"PST-MNT-003","name":"维修基金怎么申请使用","domain":"签约后","subScene":"维修维护","scene":"签约后·维修维护","cq":"小区电梯坏了，我们怎么申请动用大修基金来修啊？","ola":"需双三分之二业主表决同意，紧急情况可走绿色通道。","cp":["需双三分之二业主表决同意","物业或业委会制定维修方案","方案公示后组织业主投票","紧急情况可走应急绿色通道"],"detail":"申请使用维修基金需经法定表决程序。根据《住宅专项维修资金管理办法》第22条，使用维修资金应当经专有部分占建筑物总面积三分之二以上的业主且占总人数三分之二以上的业主同意。实操中，通常由物业或业委会提出使用建议、制定维修方案并公示，然后组织业主投票表决。表决通过后，向相关部门提交材料申请拨付。若是紧急危及安全的维修，可走绿色通道应急使用。","legalRef":"《住宅专项维修资金管理办法》第22条","consumerBenefit":"房屋问题及时修，居住更安心","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见前","见中"]},"alias":["房屋养老金怎么提取","小区大修基金申请流程","动用维修资金需要什么手续"]},{"id":"OWN-RNT-CASE-014","name":"业主如何合理制定出租房屋的租金定价？","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"房东定租金有标准吗？","ola":"参考同小区近期成交价并结合配置调整。","cp":["参考同小区同户型近期成交价","根据装修和家电配置调整溢价","考虑楼层朝向等硬件条件折价","结合空置成本动态调整定价"],"detail":"业务场景：业主在房屋挂牌前需确定合理的租金价格，以平衡出租效率与收益。判断要点：需参考同小区同户型近期实际成交价，结合房屋装修、家电配置及楼层朝向进行溢价或折价调整。关键决策因素：定价过高会导致空置期拉长增加隐性成本，定价过低则损失收益，需根据市场供需及自身资金需求动态调整。","legalRef":"市场调节价","consumerBenefit":"提高出租效率，缩短空置期。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["房东怎么定租金价格","出租房租金怎么定价","业主怎么评估房子能租多少钱"]},{"id":"OWN-OWN-CASE-035","name":"业主自住房屋是央产房或房改房，上市交易前有哪些权属风险需要排查？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东的房子是央产房或房改房，上市交易前有哪些权属风险需要排查？","ola":"需排查央产房批单、原单位限制及土地出让金缴纳情况。","cp":["央产房需取得上市出售批单","房改房需核实原单位限制约定","需确认是否已补足土地出让金","未经审批交易可能导致合同无效"],"detail":"业务场景：业主自住房屋为央产房或已购公房，准备上市交易。判断要点：此类房屋上市需满足特定条件，如央产房需取得上市出售批单，房改房需确认是否已补足土地出让金或满足原产权单位的优先购买权约定。关键风险在于未经审批擅自交易导致合同无效，或因原单位行使优先购买权导致交易失败。","legalRef":"《已购公有住房和经济适用住房上市出售管理暂行办法》第五条","consumerBenefit":"明确特殊产权房屋的交易门槛，避免合同无效或交易停滞。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["央产房房改房上市交易前权属风险","自住房是央产房交易有什么风险","房改房上市交易需要排查哪些风险"]},{"id":"OWN-OWN-CASE-039","name":"业主自住房屋的共有权人未经其他共有人同意，私自出租给长租公寓，有什么风险？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东的共有房屋，一方私自租给长租公寓，有什么风险？","ola":"未经共有人同意出租效力存疑，易引发腾退及索赔诉讼。","cp":["未经全体同意出租效力待定","长租合同涉及重大管理行为","其他共有人可主张合同无效","易引发长租机构索赔连环诉讼"],"detail":"业务场景：业主自住房屋为多人共有，其中一方未经其他共有人同意，私自将房屋出租给长租公寓机构。判断要点：依据《民法典》，出租虽非处分，但长租合同通常涉及房屋改造、转租及长期限，属于重大管理行为。关键风险在于：其他共有人有权主张租赁合同对其不发生效力，要求腾退房屋；长租公寓机构若已投入装修，将向签约方索赔，引发复杂连环诉讼。","legalRef":"《中华人民共和国民法典》第三百零一条","consumerBenefit":"明确共有房屋出租的法律边界，保护自身财产权益不受侵害。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["共有权人私自出租给长租公寓有什么风险","自住房未经共有人同意出租长租公寓风险","共有房屋一方私自签长租合同风险"]},{"id":"OWN-VAL-CASE-023","name":"业主听信中介高承诺导致房屋错过最佳出售时机能索赔吗","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"中介忽悠我高价挂牌结果没卖掉，跌价了能让他赔吗？","ola":"除非有确凿证据证明中介欺诈，否则业主需自担定价风险。","cp":["口头承诺难举证需书面证据","业主自主定价需自担决策风险","需证明中介存在故意欺诈行为","差价索赔需评估市场公允价"],"detail":"业务场景中，业主常因中介为了获取独家委托或促成带看，口头承诺能卖高价而设定过高挂牌价。当市场下行或房屋长期滞销最终降价成交时，业主常要求中介赔偿差价。判断要点在于中介是否构成欺诈或重大误解，以及业主作为完全民事行为能力人是否应承担自主定价的最终决策责任。关键决策因素是是否有书面证据证明中介存在虚假承诺，以及实际成交价与当时市场公允价的差额。","legalRef":"《中华人民共和国民法典》第一百四十八条（欺诈）、第九百六十二条（中介人如实报告义务）","consumerBenefit":"明确中介承诺的法律效力，避免盲目听信高价承诺。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["中介忽悠我高价挂牌没卖掉能赔差价吗","听信经纪人定价太高导致房子卖亏了能起诉吗","中介承诺高价结果没卖出去能要求赔偿损失吗"]},{"id":"OWN-VAL-CASE-031","name":"业主想快速卖房如何根据近期成交数据制定挂牌估值","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"我想快点把房子卖掉，怎么根据成交数据定挂牌价？","ola":"参考近3个月同户型最低成交价下浮2%-5%挂牌。","cp":["参考近3个月真实成交价非挂牌价","快速成交需参考最低成交价下浮","根据楼层装修等系数微调估值","结合业主资金紧迫度调整策略"],"detail":"当业主急需资金或希望快速置换时，制定合理的挂牌估值是核心。业务流程上，经纪人需拉取同小区或同板块近3个月的真实成交数据，而非挂牌数据。判断要点是区分挂牌价与成交价的折让率，并结合房屋自身条件（楼层、装修、位置）进行系数调整。快速成交的估值策略通常是参考同户型近3个月最低成交价的95%至98%作为挂牌价。关键决策因素是数据的真实性、时效性及业主的资金紧迫程度。","legalRef":"行业操作规范","consumerBenefit":"掌握科学定价方法，缩短房屋成交周期，提高资金周转效率。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["想快点把房子卖出去怎么根据成交数据定价","急售房屋如何参考同小区近期成交价定挂牌价","想快速卖房怎么制定合理的挂牌估值"]},{"id":"OWN-VAL-CASE-032","name":"房屋准备出售前业主如何低成本微改造提升估值","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"卖房前怎么花点小钱改造，能让房子估值更高？","ola":"通过深度保洁、墙面补漆和灯光优化提升视觉估值。","cp":["深度保洁与杂物清理是基础","墙面补漆与更换灯泡提升明亮度","避免硬装拆改控制改造成本","针对房屋短板进行视觉优化"],"detail":"房屋在出售前进行适当的微改造，能有效提升买家看房时的第一印象，从而支撑更高的估值。操作流程上，重点在于视觉提亮与瑕疵掩盖。包括深度保洁、墙面局部补漆刷新、更换老旧开关面板及灯泡、清理冗余杂物。判断要点是投入产出比，避免进行涉及硬装拆改的重投入。关键决策因素是房屋现状的短板（如采光差、墙面脏）及目标客群的审美偏好。","legalRef":"行业操作规范","consumerBenefit":"以极低成本提升房屋卖相，提高看房转化率及最终成交溢价。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["卖房前怎么花小钱改造让房子估值更高","房子出售前如何进行低成本微改造提升估值","想提高卖房估值有哪些低成本的房屋微改造方法"]},{"id":"OWN-VAL-CASE-035","name":"市场下行期业主如何分阶段调整挂牌估值避免资产缩水","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"房价一直跌，我怎么分阶段调整挂牌价避免亏太多？","ola":"采用小步快跑策略，根据带看反馈阶梯式下调。","cp":["首周设定略低于均价的破冰价","无带看反馈时按3%-5%阶梯下调","根据带看量和反馈数据动态调整","关注宏观政策及同小区成交信号"],"detail":"在市场处于下行期时，业主若死守初始高估值，极易导致房屋长期滞销，最终面临更大的资产缩水。业务流程上，建议采用小步快跑的分阶段调价策略。首周设定略低于市场均价的破冰价以获取流量；若2至3周无带看或意向，按3%至5%的幅度阶梯式下调；若市场出现宏观政策利好或同小区有高价成交，可暂缓下调。关键决策因素是带看量、反馈数据及市场宏观政策的边际变化。","legalRef":"《中华人民共和国民法典》第一百七十六条","consumerBenefit":"掌握动态调价策略，在市场下行期最大化减少资产贬值损失，提高流动性。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["房价下跌时怎么分阶段调整挂牌价避免亏太多","市场不好如何分阶段调整房屋估值避免资产缩水","二手房市场下行期业主怎么调整挂牌估值"]},{"id":"OWN-SLD-CASE-030","name":"卖房时卖方是未成年人父母代卖买家如何审查才有效","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"买小孩名下的房子，他爸妈代签，我怎么审查才能保证合同有效？","ola":"需审查亲属证明及为未成年人利益声明。","cp":["监护人非为被监护人利益不得处分","需审查亲属关系证明材料","需出具为未成年人利益出售声明","未尽审查义务存合同无效风险"],"detail":"房屋产权登记在未成年人名下，父母作为法定监护人代为出售。根据法律规定，监护人除为维护被监护人利益外，不得处分被监护人的财产。买方及经纪人在审查时，必须要求父母提供未成年人出生证明、户口本等亲属关系证明，并重点审查父母出具的为未成年人利益出售房产的书面保证。若未尽审查义务，可能导致合同效力瑕疵。","legalRef":"《中华人民共和国民法典》第三十五条（监护人职责）及《中华人民共和国未成年人保护法》第十六条（监护人履行监护职责）","consumerBenefit":"规范未成年人房产交易审查，保障合同效力。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["卖房时产权人是小孩父母代签怎么审查","未成年人房产父母代卖需要什么手续","卖房时业主未成年监护人代卖如何防范风险"]},{"id":"OWN-SLD-CASE-032","name":"卖房时业主想多家中介挂牌如何避免被锁盘或索要违约金","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"我想让多家中介帮我卖房，怎么防止被其中一家坑了说要交违约金？","ola":"签一般委托并拒签排他违约金条款。","cp":["明确勾选一般委托而非独家","拒签含高额违约金的排他条款","保留多家中介同时带看证据","警惕中介系统恶意锁盘行为"],"detail":"业主选择一般委托将房屋在多家中介挂牌，以期快速出售。为避免被某家中介锁盘或被索要独家违约金，业主在签委托协议时必须做到：明确勾选一般委托而非独家委托；仔细阅读协议中关于跳单和违约金的条款，拒绝签署包含高额违约金的排他性条款；保留多家中介同时带看的证据，证明未违反一般委托约定。","legalRef":"《中华人民共和国民法典》第九百六十五条（跳单规定）、《中华人民共和国消费者权益保护法》第二十六条（格式条款）。","consumerBenefit":"保障业主多渠道售房权益，防范中介霸王条款。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["卖房时同时委托多家中介怎么防止被锁盘","一般委托卖房怎么避免被中介索要独家违约金","卖房时不想签独家怎么防止中介恶意锁盘"]},{"id":"OWN-SLD-CASE-035","name":"卖房时业主想保留特定家具在合同和交割中如何约定","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"卖家说合同里写了送家具，但交房时他把一件红木家具搬走了，这算违约吗？","ola":"合同附件明确保留并交割时签字确认。","cp":["合同附件明确列出保留物品清单","标注卖方保留不随房出售","搬离时拍照录像留存现状证据","交割时对照清单双方签字确认"],"detail":"业主在出售房屋时，希望保留屋内某件特定家具，不随房赠送。为避免交割纠纷，操作流程如下：在房屋买卖合同附件的物品清单中，明确列出该家具的名称、品牌、数量，并标注卖方保留不随房出售；在交房前，业主将该家具搬离，并拍摄搬离后的房屋现状照片留存；交割时，双方对照清单逐项核对，确认该家具已按约定保留，买方签字确认。","legalRef":"《中华人民共和国民法典》第四百七十条（合同内容条款）。","consumerBenefit":"规范物品保留流程，避免交割纠纷。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见后"]},"alias":["卖房时想保留某件家具合同里怎么写","卖房时不想送红木家具交割时怎么明确","二手房出售业主想保留特定物品如何约定"]},{"id":"OWN-DISPUTE-043","name":"业主卖房时配偶未签字合同是否有效的法律依据","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"只有一方签字的买房合同算数吗？","ola":"共有房产单方出售，未经配偶同意且未过户可被撤销。","cp":["未过户配偶可主张无效","已过户买家可善意取得","必须取得配偶书面同意","核实产权与婚姻状况"],"detail":"业主在出售登记在其一人名下但实为夫妻共同财产的房产时，若配偶未签字同意，合同效力如何认定。根据《民法典》及相关司法解释，若买家为善意、支付合理对价并已办理产权登记，买家可善意取得；若未过户，配偶可主张合同无效或拒绝履行。经纪人需核实房屋产权性质及婚姻状况，若为共有，必须要求配偶出具同意出售的书面声明或共同签字，避免后续因配偶阻挠导致交易失败或违约。","legalRef":"《中华人民共和国民法典》第三百一十一条（善意取得）及第一千零六十二条（夫妻共同财产）","consumerBenefit":"明确共有房产处分规则，防止因单方违约导致交易失败。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["隐瞒已婚事实卖房法律依据","单方出售共有房产法律怎么规定","夫妻共有房屋买卖效力认定"]},{"id":"OWN-OWN-CASE-048","name":"房屋产权人去世，子女未办继承直接出售房屋，买家能主张合同有效吗？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东去世了他儿子没办继承就直接把房子卖给我，这合同有效吗？","ola":"买卖合同有效，但未办继承登记无法直接过户。","cp":["1.未办继承未取得处分权","2.冒名签字属无权代理","3.买卖合同本身可有效","4.未过户前无法直接履约"],"detail":"业务场景：房屋产权人去世，其子女（法定继承人）在未办理继承公证和不动产转移登记的情况下，直接以产权人名义或自己名义与买家签订房屋买卖合同。判断要点：物权变动需经依法登记，继承人未办理继承登记前，尚未取得该房屋的完整处分权。关键决策因素：若以deceased产权人名义签字，属无权代理/伪造签名，合同对产权人不生效；若以自己名义卖，属无权处分。买家可主张合同有效（买卖合同效力与物权处分权分离），但..","legalRef":"《中华人民共和国民法典》第二百三十条（因继承取得物权的生效时间）、第二百一十四条（不动产物权登记生效）、第五百九十七条（无权处分买卖合同效力）","consumerBenefit":"厘清合同效力与物权变动的区别，明确继承房产交易的先决条件。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["父亲去世没办继承子女直接卖房合同有效吗","产权人去世继承人未过户就卖房买家能要房吗","没办继承手续直接卖去世父母的房子合法吗"]},{"id":"OWN-SLD-CASE-045","name":"业主卖房时共有人未签字买家能主张房屋买卖合同无效吗","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"卖家老公没签字，这卖房合同有效吗？","ola":"单方出售合同有效，但能否过户看买家是否善意。","cp":["区分合同效力与物权变动","买家善意取得受保护","未过户可能无法强制履行","签字共有人承担违约责任"],"detail":"业务场景：房屋属于夫妻共同财产或多人共有，但仅部分共有人出面签订买卖合同，其他共有人未签字。事后其他共有人以未同意出售为由主张合同无效。判断要点：需区分合同效力与物权变动效力。关键决策因素：买家是否构成善意取得、是否支付合理对价、是否已办理过户登记。若买家善意且已过户，合同有效且物权转移；若未过户，合同可能有效但无法履行。","legalRef":"《中华人民共和国民法典》第三百一十一条，无处分权人将不动产或者动产转让给受让人的，所有权人有权追回；除法律另有规定外，符合下列情形的，受让人取得该不动产或者动产的所有权：（一）受让人受让该不动产或者动产时是善意。","consumerBenefit":"明确共有房屋交易规则，保障交易安全。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["配偶没签字卖房合同效力","未经共有人同意卖房","卖房缺少共有人签字怎么办"]},{"id":"OWN-SLD-CASE-056","name":"业主卖房时把房产证原件交给买家保管有什么风险","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"让房东把房产证押在我这里，能防止他一房二卖吗？","ola":"存在买家利用房产证借贷或遗失污损的重大风险。","cp":["买家利用房产证民间借贷风险","房产证遗失补办流程繁琐","污损影响过户进度","应通过网签或监管替代"],"detail":"业务场景：买家为表示诚意或防止业主一房二卖，要求业主将房产证原件交由自己保管，直至过户。判断要点：此操作对业主存在重大风险。关键决策因素：房产证遗失补办流程繁琐；若买家利用房产证进行民间借贷抵押或诈骗，业主可能卷入法律纠纷；买家保管不善导致污损影响过户。经纪人应制止此行为，建议通过资金监管或网签锁定交易。","legalRef":"《不动产登记暂行条例》第二十一条，登记事项自记载于不动产登记簿时完成登记。不动产登记机构完成登记，应当依法向申请人核发不动产权属证书。","consumerBenefit":"保护业主核心产权凭证，防范衍生法律风险。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["房产证交给买家风险","卖家把房产证给买家保管","房产证原件交由买方"]},{"id":"OWN-SLD-CASE-057","name":"业主卖房时轻信买家口头承诺不写进合同有什么风险","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"房东口头答应送家具，没写进合同，这算数吗？","ola":"口头承诺无书面证据无效，必须写入补充协议。","cp":["口头承诺极难举证","法院以书面合同为准","买家反悔业主维权无门","所有承诺必须写入补充协议"],"detail":"业务场景：业主在交易中对买家的某些口头承诺信以为真，未将其写入正式合同。判断要点：口头承诺在发生纠纷时极难举证，法院通常以书面合同为准。关键决策因素：缺乏书面证据导致业主无法主张权利；买家事后反悔，业主面临违约或额外支出。经纪人必须将所有承诺落实到补充协议中。","legalRef":"《中华人民共和国民法典》第四百六十九条，当事人订立合同，可以采用书面形式、口头形式或者其他形式。书面形式是合同书、信件、电报、电传、传真等可以有形地表现所载内容的形式。","consumerBenefit":"确保交易条件明确，保障业主合法权益。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["口头承诺不写进合同风险","买家口头承诺有效吗","卖房轻信口头承诺"]},{"id":"OWN-SLD-CASE-058","name":"业主卖房时未核实中介资质直接签独家代理有什么风险","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"中介让房东签独家代理，这有什么风险吗？","ola":"存在被无资质中介锁盘及承担高额违约金风险。","cp":["警惕中介无资质或备案","防范独家期限过长锁盘","审查违约金条款是否公平","明确中介具体推广义务"],"detail":"业务场景：业主在未核实中介公司资质和实力的情况下，被中介忽悠签订了独家代理协议，约定高额违约金。判断要点：若中介缺乏客源或存在违规行为，房屋将被锁盘无法售出。关键决策因素：中介是否具备合法备案资质、独家期限是否过长、违约金条款是否显失公平、是否约定了推广义务。业主需警惕假独家真锁盘陷阱。","legalRef":"《房地产经纪管理办法》第十一条，房地产经纪机构及其分支机构应当具有足够数量的房地产经纪人员。","consumerBenefit":"保障业主选择权，防范被不良中介恶意锁盘。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["签独家代理风险","未核实中介资质签独家","卖房签独家协议的隐患"]},{"id":"OWN-TNT-CASE-046","name":"房东将房屋抵押后抵押权实现租赁合同还有效吗","domain":"资产持有与运营","subScene":"租客纠纷应对","scene":"资产持有与运营·租客纠纷应对","cq":"房东把房子抵押给银行了，如果房子被拍卖我还能住吗？","ola":"先出租并占有，抵押权实现不影响租赁合同效力。","cp":["先出租并占有不受抵押权影响","先抵押后出租不得对抗抵押权","买卖不破租赁适用于先租后抵","核实抵押登记与租赁合同时间"],"detail":"根据《民法典》规定，抵押权设立前，抵押财产已经出租并转移占有的，原租赁关系不受该抵押权的影响。业务判断要点在于出租与抵押的先后顺序及是否已转移占有。若先出租且租客已实际入住，后抵押导致房屋被拍卖，适用买卖不破租赁，租赁合同对受让人继续有效。若先抵押后出租，则租赁关系不得对抗已登记的抵押权，抵押权实现时租客需搬离。关键决策因素是租赁合同签订、占有转移与抵押登记的时间先后。","legalRef":"《中华人民共和国民法典》第四百零五条","consumerBenefit":"明确先租后抵情况下的居住权保障，避免被违规清退。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["房子被抵押拍卖了租客还能继续住吗","房东抵押房产后银行拍卖房子租赁合同的效力","先出租后抵押房屋被拍卖买卖破租赁吗"]},{"id":"PRE-MATCH-106","name":"预算不够又想地段好学区好怎么挑（PRE-MATCH）","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"钱不够但又想要好学区和好地段，我该怎么取舍？","ola":"明确核心需求排序，通过面积或房龄降级来满足核心痛点。","cp":["明确核心需求排序","引导需求合理降级","避免决策疲劳","测算后期置换成本","警惕过度杠杆风险"],"detail":"情境：客户对地段、学区、面积三个维度要求极高，但预算无法同时满足。判断依据：客户核心痛点排序及家庭生命周期。行动建议：引导客户进行需求降级，如用面积换地段，或用老破小换学区。风险提示：强行上车导致生活质量下降或后期置换困难，且容易在多看几套后产生决策疲劳。","legalRef":"行业惯例（客户需求管理与预期管理）","consumerBenefit":"避免盲目加杠杆，买到最符合家庭核心需求的高性价比房源。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["预算有限怎么买好地段","要求多预算少怎么匹配","既要学区又要地段怎么挑"]},{"id":"PRE-FINA-093","name":"认房不认贷政策下，二套房认定标准到底怎么算（PRE-FINA）","domain":"签约前","subScene":"融资贷款","scene":"签约前·融资贷款","cq":"我老家有套房有贷款，但在本地没房，现在本地买房算首套还是二套？","ola":"以本地房管局查册无房证明为准，但需确认当地银行具体执行口径。","cp":["以当地房管局查册为准","家庭为单位拉无房证明","异地房产联网情况","结清贷款才算首套"],"detail":"情境：买家名下无房但有贷款记录，或有过房产交易记录。依据：各地认房不认贷政策通常以当地房管局查册结果为准。建议：以家庭为单位在当地不动产中心拉取无房证明。风险：若异地有房未联网或历史贷款记录未结清，部分银行仍可能按二套认定。","legalRef":"住建部《关于优化个人住房贷款中住房套数认定标准的通知》","consumerBenefit":"准确判断自身房屋套数认定，避免按二套房准备首付导致资金不足。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["认房不认贷怎么认定","二套房认定标准是什么","名下无房算首套吗"]},{"id":"PRE-FINA-095","name":"二套房认定有争议导致买不了，合同能解除吗（PRE-FINA）","domain":"签约前","subScene":"融资贷款","scene":"签约前·融资贷款","cq":"签合同时中介说算首套，结果过户时政策变了算二套，首付不够了能解除合同退定金吗？","ola":"因政策突变导致套数认定变化可无责解约，隐瞒房产则需违约赔偿。","cp":["政策突变可主张无责解约","隐瞒房产买家全责违约","核实最新限购限贷政策","保留政策变化证据"],"detail":"情境：买卖双方对房屋套数认定存在分歧，或政策突变导致买家失去首套资格。依据：《民法典》及最高法司法解释，因不可归责于双方的事由导致合同不能履行的，可解除合同。建议：核实当地最新限购限贷政策，若因政策调整导致二套认定变化，可主张无责解约。风险：若因买家隐瞒真实房产情况导致认定错误，买家需承担违约责任。","legalRef":"《中华人民共和国民法典》第五百三十三条、《最高人民法院关于审理商品房买卖合同纠纷案件适用法律若干问题的解释》第四条","consumerBenefit":"掌握因政策或认定争议导致交易受阻时的合法解约路径，挽回定金损失。","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前"]},"alias":["二套房认定争议解约","套数认定错误能退房吗","二套认定不符能退定金吗"]},{"id":"PRE-FINA-CASE-100","name":"离婚析产贷款没结清，再买房算二套怎么打官司（PRE-FINA）","domain":"签约前","subScene":"融资贷款","scene":"签约前·融资贷款","cq":"我离婚后房子归我但贷款没结清，现在再买房被算作二套，我打官司能赢改回首套吗？","ola":"离婚不消除贷款记录，未结清贷款再买房通常被认定为二套。","cp":["离婚不消除贷款记录","未结清贷款算二套","提前咨询当地认定标准","离婚协议明确房贷归属"],"detail":"情境：买家离婚后分得房产，但原共同贷款未结清，再次买房时被认定为二套，买家起诉要求按首套认定。依据：法院通常支持银行或房管局按认房又认贷或当地最新政策认定，离婚析产不改变贷款记录事实。建议：离婚时明确房贷归属及结清责任，提前咨询当地二套认定标准。风险：若盲目按首套准备首付，将面临贷款成数降低及利率上浮的损失。","legalRef":"《中华人民共和国民法典》第一千零八十七条","consumerBenefit":"了解离婚析产对房屋套数认定的影响，提前规划房贷结清或首付准备。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前"]},"alias":["离婚析产二套房认定","贷款未结清算二套案例","离婚买房套数认定纠纷"]},{"id":"OWN-SEL-DEEP-002","name":"卖房定价怎么避免定高卖不掉定低吃大亏","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"房东房子挂多少价合适？挂高了怕卖不掉，挂低了怕吃亏。","ola":"成交价取中位数，±5%微调。","cp":["帮业主做三步定价法","1.查同小区近3月成交价取中位数 2.…","提醒业主定价超成交价10%以上会严重.…"],"detail":"本词条涉及出售决策领域的RISK类问题。帮业主做三步定价法：1.查同小区近3月成交价取中位数 2.看同小区在挂价取下四分位 3.根据楼层朝向装修做±5%微调。提醒业主定价超成交价10%以上会严重延长卖房周期。。该问题属于medium级别，涉及行业规范标准。","legalRef":"《中华人民共和国民法典》相关条文","consumerBenefit":"掌握规范操作流程，降低风险。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["卖房定价怎么避免定高卖不掉定低吃大亏","卖房定价怎样避免定高卖不掉定低吃大亏","卖房定价如何避免定高卖不掉定低吃大亏"]},{"id":"OWN-SEL-DEEP-006","name":"卖房时发现房子有抵押怎么处理才能顺利过户","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"房东房子还有贷款没还完，能卖吗？怎么操作？","ola":"先解押再过户，可用买方首付还贷。","cp":["告诉业主","有抵押的房子可以卖","但必须先还清贷款解除抵押才能过户","三条路径","1.用买方首付解押 2.自己筹钱先还.…"],"detail":"本词条涉及出售决策领域的PROC类问题。告诉业主：有抵押的房子可以卖，但必须先还清贷款解除抵押才能过户。三条路径：1.用买方首付解押 2.自己筹钱先还贷 3.做转按揭(少数银行支持)。提醒业主提前了解贷款余额，规划解押资金来源。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第四百零六条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["卖房时发现房子有抵押怎么处理才能顺利过户","卖房时发现房子有抵押如何处理才能顺利过户","卖房时发现房子有抵押怎样处理才能顺利过户"]},{"id":"OWN-SEL-DEEP-009","name":"卖房时买家贷款审批不过定金怎么退","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"买家贷款审批没通过，房东收的定金要退吗？","ola":"看合同约定，有免责条款则退还。","cp":["告诉业主","买家贷款不过的处理取决于合同约定","如果合同约定'贷款不过则合同解除","则业主必须退定金","如果合同未约定"],"detail":"本词条涉及出售决策领域的LAW类问题。告诉业主：买家贷款不过的处理取决于合同约定。如果合同约定'贷款不过则合同解除、定金退还'，则业主必须退定金。如果合同未约定，买家单方违约则定金不退。建议业主签合同时加上'贷款审批不过的免责解约条款'保护双方。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第五百八十七条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["卖房时买家贷款审批不过定金怎么退","卖房时买家贷款审批不过定金如何退","卖房时买家贷款审批不过定金怎样退"]},{"id":"OWN-SEL-DEEP-010","name":"卖房后发现买家是炒房客怎么办","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"房东怀疑买家是炒房客，有什么风险吗？能不卖吗？","ola":"不违法但合同要严谨，不能以此拒售。","cp":["告诉业主识别炒房客特征","1.看房时不关心房屋状况只关心价格 .…","提醒业主","卖给炒房客本身不违法","但需注意1.合同条款要严谨 2.过户.…"],"detail":"本词条涉及出售决策领域的RISK类问题。告诉业主识别炒房客特征：1.看房时不关心房屋状况只关心价格 2.全款或高杠杆 3.频繁问能不能快过户 4.可能有多个关联人买房。提醒业主：卖给炒房客本身不违法，但需注意1.合同条款要严谨 2.过户时间要明确 3.保留完整交易记录。。该问题属于medium级别，涉及行业规范标准。","legalRef":"《中华人民共和国民法典》第五百零九条","consumerBenefit":"掌握规范操作流程，降低风险。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["卖房后发现买家是炒房客怎么办","卖房后发现买家是炒房客怎么处理","卖房后发现买家是炒房客如何应对"]},{"id":"OWN-SEL-DEEP-011","name":"夫妻共同房产一方不同意卖怎么办","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"产证是房东名字但配偶不同意卖，能自己卖吗？","ola":"婚后房产必须双方同意，单方出售可撤销。","cp":["告诉业主","夫妻共同财产出售需双方同意","一方擅自出售","另一方有权主张买卖合同无效","但买方善意取得的除外"],"detail":"本词条涉及出售决策领域的LAW类问题。告诉业主：夫妻共同财产出售需双方同意。一方擅自出售，另一方有权主张买卖合同无效。但买方善意取得的除外。建议业主：1.卖房前必须取得配偶书面同意 2.配偶签字的同意书要公证 3.产证只写一人名字的也要配偶确认。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第一千零六十二条、第三百一十一条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["夫妻共同房产一方不同意卖怎么办","夫妻共同房产一方不同意卖怎么处理","夫妻共同房产一方不同意卖如何应对"]},{"id":"OWN-OWN-DEEP-001","name":"房子被法院查封了怎么解除查封卖房","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房子被法院查封了，还能卖吗？怎么解封？（从租客/买家角度）","ola":"清偿债务或和解后申请解封即可出售。","cp":["告诉业主","查封房产的解除路径——1.清偿债务后.…","提醒业主","查封期间不能过户、不能抵押","但可以居住"],"detail":"本词条涉及权属维护领域的PROC类问题。告诉业主：查封房产的解除路径——1.清偿债务后申请法院解封 2.提供担保申请解封 3.与债权人达成和解后解封。提醒业主：查封期间不能过户、不能抵押，但可以居住。帮业主联系执行法官了解具体解封条件。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民事诉讼法》第一百零四条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["房子被法院查封了怎样解除查封卖房","房子被法院查封了怎么解除查封卖房","房子被法院查封了如何解除查封卖房"]},{"id":"OWN-OWN-DEEP-003","name":"房产代持协议怎么签才有法律效力","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东想找人代持买房，协议怎么签才安全？","ola":"书面+公证+出资凭证完整，但不能对抗善意第三人。","cp":["帮业主了解代持协议有效要件","1.双方真实意思表示 2.出资凭证完.…","提醒业主","即使协议有效","仍不能对抗善意第三人——代持人卖房给.…"],"detail":"本词条涉及权属维护领域的LAW类问题。帮业主了解代持协议有效要件：1.双方真实意思表示 2.出资凭证完整保留 3.协议内容明确(代持原因、产权归属、回购条件、违约责任) 4.建议公证。提醒业主：即使协议有效，仍不能对抗善意第三人——代持人卖房给不知情买家，买家取得产权。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第一百四十三条、第三百一十一条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["房产代持协议如何签才有法律效力","房产代持协议怎么签才有法律效力","房产代持协议怎样签才有法律效力"]},{"id":"OWN-SEL-DEEP-003","name":"独家委托和多家委托哪个对卖家更有利","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"中介让房东签独家委托，该签吗？独家和多家哪个好？","ola":"先签1月独家试水，不满意转多家。","cp":["帮业主分析独家vs多家利弊","独家好处是中介更用心推广、避免撞客压价","多家好处是覆盖面广、竞争促动","建议业主签短期独家(1个月)试效果","不满意再转多家"],"detail":"本词条涉及出售决策领域的LAW类问题。帮业主分析独家vs多家利弊：独家好处是中介更用心推广、避免撞客压价；多家好处是覆盖面广、竞争促动。建议业主签短期独家(1个月)试效果，不满意再转多家。必须提醒独家期间业主不得自行成交。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第九百六十一条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["独家委托和多家委托哪个对卖家更有利","独家还是多家委托好","卖房签独家还是多家"]},{"id":"OWN-OWN-DEEP-007","name":"设立居住权的房子买卖租有什么限制","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东给父母设了居住权的房子，以后能卖吗？有什么限制？","ola":"可卖但必须告知，居住权期间不能驱赶。","cp":["告诉业主","居住权是民法典新设的用益物权","设立后房子可以买卖但买家必须尊重居住.…","居住权期间不能要求居住权人搬走","提醒业主"],"detail":"本词条涉及权属维护领域的LAW类问题。告诉业主：居住权是民法典新设的用益物权，设立后房子可以买卖但买家必须尊重居住权人的居住权利。居住权期间不能要求居住权人搬走。提醒业主：1.卖房前必须告知买家有居住权 2.居住权需登记才生效 3.居住权期限届满或居住权人死亡后消灭。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第三百六十六条至三百七十一条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["设立居住权的房子买卖租有什么限制","居住权房产交易限制","带居住权房产出售"]},{"id":"OWN-RNT-DEEP-005","name":"房屋自然老化维修费谁承担怎么划分责任","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"房东说维修费全由我出，自然老化也要我修吗？","ola":"自然老化房东修，使用不当租客赔。","cp":["告诉业主维修责任划分","常见自然老化","水管老化漏水、墙皮脱落、电器使用寿命到期","提醒业主","入住时做好物品状况记录"],"detail":"本词条涉及出租管理领域的LAW类问题。告诉业主维修责任划分：1.自然老化/正常损耗→房东承担 2.租客使用不当造成→租客承担 3.合同有约定从约定。常见自然老化：水管老化漏水、墙皮脱落、电器使用寿命到期。提醒业主：入住时做好物品状况记录，。该问题属于medium级别，涉及行业规范标准。","legalRef":"《中华人民共和国民法典》第七百一十二条、第七百一十三条","consumerBenefit":"掌握规范操作流程，降低风险。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["出租房维修费谁承担","自然老化维修责任划分","房屋正常损耗房东修还是租客修"]},{"id":"OWN-RNT-DEEP-006","name":"怎么筛选优质租客避免租给麻烦人","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"房东不租给我是不是歧视？","ola":"核实身份+工作+人数，排除群租商用。","cp":["帮业主建立租客筛选标准","建议业主签合同前做3项基本核实","身份+工作+租住人数"],"detail":"本词条涉及出租管理领域的STD类问题。帮业主建立租客筛选标准：1.查验身份证+工作证明 2.电话核实工作单位 3.查征信(需租客授权) 4.了解租住人数和用途 5.合同约定禁止群租/转租/商用。建议业主签合同前做3项基本核实：身份+工作+。该问题属于soft级别，属于行业惯例范畴。","legalRef":"行业通行做法","consumerBenefit":"获取行业经验参考，做出更优决策。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["优质租客筛选标准","避免租给不靠谱的人","出租房选租客技巧"]},{"id":"OWN-OPS-DEEP-001","name":"房产税怎么计算哪些房产需要交","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"房东要涨租说是因为房产税，合理吗？","ola":"自住免征，出租4%从租计征。","cp":["告诉业主房产税计算方式","1.从价计征","房产原值×(1-扣除比例)×1.2%.…","租金收入×12%(个人出租住房4%).…","个人非营业用房产免征"],"detail":"本词条涉及资产运营领域的LAW类问题。告诉业主房产税计算方式：1.从价计征：房产原值×(1-扣除比例)×1.2% 2.从租计征：租金收入×12%(个人出租住房4%) 3.免征范围：个人非营业用房产免征。提醒业主：目前个人自住房免房产税，但。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第二百七十八条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["哪些房产要交房产税","两套房房产税怎么算","房产税免征条件"]},{"id":"OWN-OPS-DEEP-002","name":"房产抵押贷款怎么操作风险有哪些","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"房东抵押贷款会影响我租住吗？","ola":"可贷5-7成，还不上银行可拍卖房产。","cp":["告诉业主抵押贷款流程和风险","提醒业主","抵押贷款要量力而行"],"detail":"本词条涉及资产运营领域的PROC类问题。告诉业主抵押贷款流程和风险：1.评估房产价值→银行审批→签抵押合同→登记→放款 2.贷款额度一般为评估价50%-70% 3.风险：还不上贷款银行可拍卖房产 4.经营贷违规流入楼市会被抽贷。提醒业主：抵。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第三百九十四条、第四百一十条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["房产抵押贷款流程","房子抵押贷款风险","抵押贷款还不上怎么办"]},{"id":"OWN-OPS-DEEP-003","name":"装修出租房花多少钱回本怎么算投资回报","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"房东装修后涨租合理吗？","ola":"简装1-2年回本，精装3-4年。","cp":["帮业主算装修投资回报","提醒业主","装修折旧5-8年，别过度装修"],"detail":"本词条涉及资产运营领域的STD类问题。帮业主算装修投资回报：1.简装出租回本周期约1-2年(装修成本3-5万，月租增量1000-2000) 2.精装出租回本周期约3-4年(装修成本8-15万，月租增量2000-4000) 3.关键指标：月。该问题属于medium级别，涉及行业规范标准。","legalRef":"行业通行做法","consumerBenefit":"掌握规范操作流程，降低风险。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["出租房装修多少钱合适","装修出租房投资回报计算","简装出租回本周期"]},{"id":"OWN-CASE-RNT-006","name":"群租被查处房东被罚款案例","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"群租被查了我还能住吗？","ola":"房东罚款3万+恢复原状，合同预防是关键。","cp":["群租房东也要被罚","罚款可达3万元以上","需恢复原状","合同约定人数上限是预防关键"],"detail":"房东许某将100平米三居室出租给租客丁某，丁某将客厅隔成3间、每个卧室隔成2间共7间出租给12人。邻居举报后城管和住建部门联合执法，认定群租违法。许某作为房东被罚款3万元，并要求恢复原状。丁某被要求限期搬离全部次承租人。","legalRef":"《住房租赁条例》+地方规定","consumerBenefit":"了解法院裁判规则，预判维权结果。","tags":{"clientType":["landlord","seller","tenant"],"stage":"post","layer":"器","meetingPhase":["见前","见中","见后"]},"alias":["群租被查处房东被罚款判例","群租被查处房东被罚款案例","群租被查处房东被罚款"]},{"id":"PRE-RNT-002","name":"租房选合租还是整租","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"第一次租房，合租好还是整租好？","ola":"预算紧选合租但要定规则，预算够选整租更省心","cp":["合租省30-50%但冲突多","整租隐私好成本高","过渡期合租长期整租","须做方案对比表"],"detail":"合租和整租的选择本质是成本与隐私的权衡。合租月租低30-50%，但存在公共区域使用冲突、作息不一致、卫生责任不清、室友更换频繁等问题。整租隐私好、生活自由，但成本高且独担风险。决策框架：预算紧张选合租但须明确室友规则；预算允许优先整租；过渡期（3个月内）合租更灵活，长期定居选整租更稳定。经纪人应帮客户列出两个方案的月成本对比表和风险清单，而非简单推房源。","legalRef":"无直接法条","consumerBenefit":"选择最适合的租房方式避免后悔","tags":{"clientType":["tenant"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["合租vs整租","租房方式选择","合租优缺点"]},{"id":"PRE-RNT-005","name":"租房怕踩坑怎么提前排查","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"租房怕被骗，该注意什么？","ola":"查产权、验授权、写费用、检安全、读合同，五步避坑","cp":["五大高频坑要提前排","产权核实是第一步","费用必须写进合同","经纪人主动提供避坑清单"],"detail":"租房五大高频坑：①假房源（图片不符/低价20%以上）②二房东无权转租（未见原始合同和授权）③隐形收费（物业/中介/服务费未提前说明）④安全隐患（燃气/电路/防水未检查）⑤合同陷阱（违约金过高/维修不清/退租苛刻）。排查：查房产证原件核对产权人、验转租授权、费用写进合同、交房前安全检查。经纪人主动提供避坑清单。","legalRef":"《中华人民共和国民法典》第七百一十六条","consumerBenefit":"系统化防范租房风险","tags":{"clientType":["tenant"],"stage":"pre","layer":"道","meetingPhase":["见前"]},"alias":["租房避坑指南","租房防骗","租房风险排查"]},{"id":"PRE-RNT-006","name":"租房房源信息真假怎么辨别","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"网上租房信息怎么判断真假？","ola":"比价看图核证三步走，低于市场价20%的基本是假","cp":["低价20%以上大概率假","图片无生活痕迹可疑","要核验码或房产证","三步法：比价看图核证"],"detail":"识别假房源的三步法：①比价——同小区同户型租金低于市场价20%以上的大概率是假房源，目的是吸引客户来电后以'已租出'为由推荐其他房源②看图——图片无小区环境外景、室内照片过度美化无生活痕迹、多套房源用同一组图片的均可疑③核证——要求经纪人提供房产证照片（遮挡敏感信息）、通过物业或居委会核实房源是否存在。正规平台已推行房源核验码，可扫码验证真实性。","legalRef":"《房地产经纪管理办法》第二十五条","consumerBenefit":"避免被虚假房源误导浪费时间","tags":{"clientType":["tenant"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["假房源识别","租房信息核实","房源真实性验证"]},{"id":"PRE-RNT-008","name":"怎么判断出租房是不是群租房","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"怎么判断这个房子是不是群租房？","ola":"看有没有隔断、多电表、无客厅、多门、超员，群租违法别租","cp":["隔断/多电表/无客厅/多门/超员","群租违法可被清退","人均面积不低于5平米","可举报并解约退租"],"detail":"群租房的五个识别特征：①客厅/阳台被隔成独立房间（木板隔断最常见）②一套房装了独立电表水表超过自然间数③公共区域极小或没有客厅④入户门或房间门超过自然间数⑤居住人数明显超过房屋设计容量。群租的法律风险：房东可能被处以罚款并责令恢复原状，租客面临随时被清退的风险。各地对群租有具体标准，如北京规定出租房屋人均居住面积不得低于5平方米。租到群租房可向住建部门举报并要求解除合同退租。","legalRef":"《中华人民共和国商品房屋租赁管理办法》第八条","consumerBenefit":"避免租到违法群租房被清退","tags":{"clientType":["tenant"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["群租房识别","群租特征","违法群租判断"]},{"id":"PRE-RNT-012","name":"租房押几付几是什么意思怎么选","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"租房押一付三是什么意思？押金能退吗？","ola":"押一个月押金付三个月租金，退房无损坏可全退，退还条件写进合同","cp":["押一付三最常见","付六可降租但占资金","押金退还条件必须写清","退房后X工作日退还"],"detail":"常见押付方式：押一付一（月付，资金压力小但房东可能不愿）、押一付三（季付，最常见）、押一付六（半年付，议价空间大但资金占用多）、押二付三（额外一个月押金，多见于商住两用）。选择原则：短期租或资金紧张选押一付一/付三；长期稳定且想降租选押一付六。押金退还需满足：合同期满、无违约、房屋无人为损坏、结清所有费用。签约时务必写明押金退还条件和时间（退房后X个工作日内退还）。","legalRef":"《中华人民共和国民法典》第七百一十四条","consumerBenefit":"理解押付规则保护自身权益","tags":{"clientType":["tenant"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["押付方式","租房押金","押一付三"]},{"id":"PRE-RNT-013","name":"租金包含哪些费用哪些要另付","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"租房除了租金还要交什么钱？","ola":"水电燃气网费自己付，物业费供暖费看合同约定，签前抄表留底","cp":["租金一般只含房屋使用费","水电燃气网费租客付","物业费供暖费看约定","签前抄表列清单"],"detail":"租金通常只包含房屋使用权，不含其他费用。需明确区分：①含在租金中的——一般只有房屋本身的使用费②租客另付的——水费、电费、燃气费、网费、有线电视费、电话费③看合同约定的——物业费、供暖费（北方）、停车费（有的房东含有的不含）④签合同前必须列清——每项费用的当前读数（水电气表）、缴费方式、欠费情况。常见纠纷是入住后发现欠费或物业费没约定清楚。经纪人应提供费用清单模板，双方签字确认。","legalRef":"《中华人民共和国民法典》第七百零九条","consumerBenefit":"避免费用纠纷明确支出预期","tags":{"clientType":["tenant"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["租金含什么","租房费用明细","租房额外费用"]},{"id":"PRE-RNT-015","name":"租房合同必须写明的十二个条款","domain":"签约前","subScene":"合同审查","scene":"签约前·合同审查","cq":"租房合同必须写哪些内容？","ola":"身份地址期限租金押金费用维修转租退租续租交付争议","cp":["十二个必备条款缺一不可","押金退还条件必须写明","维修责任要划清","用示范文本最安全"],"detail":"租房合同十二个必备条款：①双方身份信息及联系方式②房屋坐落地址及面积③租赁期限（起止日期）④月租金金额及支付方式⑤押金金额及退还条件⑥物业费/供暖费等费用承担方⑦维修责任划分⑧转租约定⑨提前退租条件及违约金⑩续租优先权及调租规则⑪房屋交付状态及附属设施清单⑫争议解决方式。缺任何一项都可能引发纠纷。使用住建部门推荐的《房屋租赁合同示范文本》可确保条款完整。","legalRef":"《中华人民共和国民法典》第七百零四条","consumerBenefit":"确保合同完整避免纠纷","tags":{"clientType":["tenant"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["租赁合同必备条款","租房合同要点","租赁合同审查"]},{"id":"PRE-RNT-016","name":"租房合同违约条款怎么谈才公平","domain":"签约前","subScene":"合同审查","scene":"签约前·合同审查","cq":"租房合同违约金怎么写才不吃亏？","ola":"提前退扣1月租，房东收回也赔，违约金不超损失30%","cp":["提前退租争取只扣1月租","房东收回也须赔偿","滞纳金不超日万分之五","违约金不超实际损失30%"],"detail":"租房违约金常见不公平条款及应对：①租客提前退租扣全部押金——应争取改为扣1个月租金作为违约金，剩余押金退还②房东提前收回房屋只退押金——应加'房东提前收回需提前30天通知并赔偿1个月租金'③滞纳金过高（日千分之五）——应改为日万分之五以内④恢复原状条款模糊——应写明'正常使用磨损除外'。公平违约条款的核心原则：违约方赔偿对方实际损失，违约金不超过实际损失的30%。","legalRef":"《中华人民共和国民法典》第五百八十五条","consumerBenefit":"避免不公平违约条款造成损失","tags":{"clientType":["tenant"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["租房违约金","租赁违约条款","租房违约责任"]},{"id":"PRE-RNT-017","name":"二房东转租怎么确认才合法","domain":"签约前","subScene":"合同审查","scene":"签约前·合同审查","cq":"租二房东的房子安全吗？怎么确认？","ola":"看原合同有无转租条款、核剩余租期、留原房东联系方式","cp":["三必须：看原合同+核租期+留联系方式","原房东同意是前提","转租期不超原合同期","无权转租合同无效"],"detail":"确认二房东转租合法的三个必须：①必须查看原始租赁合同——确认原房东同意转租条款，或取得原房东书面同意②必须核实剩余租期——转租期限不能超过原合同剩余期限③必须留存二房东身份证和原房东联系方式——以备纠纷时联系原房东确认。如果原合同明确禁止转租或未经原房东同意，转租合同无效，原房东有权收回房屋。租客租二房东的房子风险极高：二房东跑路、原房东清退、押金无法追回都是高频问题。","legalRef":"《中华人民共和国民法典》第七百一十六条、第七百一十七条","consumerBenefit":"避免租到无权转租房屋被清退","tags":{"clientType":["tenant"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["转租合法性","二房东核实","租房转租确认"]},{"id":"PRE-RNT-018","name":"租房合同里维修责任怎么划分","domain":"签约前","subScene":"合同审查","scene":"签约前·合同审查","cq":"租房期间东西坏了谁负责修？","ola":"自然老化房东修，人为损坏租客修，签约时列清单拍照留底","cp":["自然老化房东修","人为损坏租客修","设施清单交房拍照","约定不明协商分担"],"detail":"维修责任划分：①房屋主体结构及自然老化——房东负责（墙皮脱落/管道锈蚀/屋顶漏水）②附属设施自然损坏——房东负责（空调/热水器老化）③租客人为损坏——租客负责（打碎玻璃/宠物咬坏）④约定不明——协商分担。签约时在《房屋设施清单》列明设施状态，交房时拍照留证。约定'非人为损坏房东修'，交房时测试所有家电。","legalRef":"《中华人民共和国民法典》第七百一十二条、第七百一十三条","consumerBenefit":"明确维修责任避免推诿","tags":{"clientType":["tenant"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["租房维修责任","租赁维修义务","租房东西坏了谁修"]},{"id":"PRE-RNT-020","name":"租房遇到黑中介怎么识别和维权","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"租房遇到黑中介怎么办？","ola":"认准五特征，维权打12345投诉住建和市监，正规中介有照有票","cp":["五特征识别黑中介","维权打12345+住建+市监","正规中介有照有备案开票","不交定金不签空白合同"],"detail":"黑中介五个特征：①无营业执照或未在住建部门备案②收费不开发票或开收据③合同以外加收'看房费''服务费''信息费'④看房前要求交定金或会员费⑤以各种理由不退押金。维权途径：①拨打12345市民热线投诉②向当地住建部门举报③向市场监督管理局投诉④涉及金额较大可报警或起诉⑤通过'黑名单'系统查询中介是否有不良记录。正规中介应在门店公示营业执照和备案证明，收费开具正规发票，合同使用示范文本。","legalRef":"《房地产经纪管理办法》第三十三条","consumerBenefit":"识别和防范黑中介陷阱","tags":{"clientType":["tenant"],"stage":"pre","layer":"道","meetingPhase":["见前"]},"alias":["黑中介识别","租房中介陷阱","不良中介防范"]},{"id":"P2-C1-008","name":"多校划片派位没中签怎么办","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"如果多校划片电脑派位没中理想的学校怎么办？","ola":"由教育部门统筹安排其他学校。","cp":["未中签由教育部门统筹","不保证入读首选学校","可能分配到周边学校"],"detail":"多校划片派位未中签的适龄儿童，由区县教育部门统筹安排到周边有空余学位的学校入学。统筹学校可能不在家长预期范围内，但不影响孩子接受义务教育的权利。部分区域允许在派位前填报多个志愿，建议合理填报并了解统筹学校范围，做好备选方案。","legalRef":"各地多校划片电脑派位实施细则","consumerBenefit":"了解派位未中后的安排，做好备选规划。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["多校划片没摇上怎么办","派位没中签怎么处理","多校划片落选怎么办"]},{"id":"P2-C1-013","name":"六年一学位二孩三孩受限制吗","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"六年一学位政策对二孩三孩有影响吗？","ola":"二孩三孩不受六年一学位限制。","cp":["二孩三孩可正常入学","多地已明确豁免规定","「长幼随学」可申请同校"],"detail":"六年一学位政策对二孩三孩通常不予限制，同一房产的二孩三孩可正常使用学位入学。北京等地已明确二孩三孩不受六年一学位约束。此外2025年浙江等地推出「长幼随学」服务，二孩可申请与兄姐同校入学。各地政策细节有差异，建议向当地教育部门确认具体规定。","legalRef":"《中华人民共和国义务教育法》第十二条","consumerBenefit":"明确多孩家庭学位权益，消除入学顾虑。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["二孩受六年一学位限制吗","三孩入学学位限制","六年一学位二孩豁免"]},{"id":"P2-C1-018","name":"落户年限对入学有影响吗","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"落户年限不够会影响孩子入学吗？各地有什么要求？","ola":"部分城市要求落户满一定年限。","cp":["部分城市设落户年限门槛","年限不足可能降低顺位","热门学校要求更严格"],"detail":"部分城市对落户年限有明确要求，如要求落户满一年或三年方可享受对口入学。落户年限不足可能导致顺位降低或被统筹安排。热门学区学校对落户年限要求通常更严格。各地政策差异大，且每年可能调整。建议购房后尽早迁入户口，确保满足落户年限要求，避免影响孩子入学。","legalRef":"各地义务教育招生入学实施方案（落户年限要求）","consumerBenefit":"了解落户年限要求，提前规划户口迁移。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["落户年限影响入学吗","落户多久才能入学","落户年限要求"]},{"id":"P2-C1-023","name":"学区房值不值得买","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"现在这个形势下，学区房还值不值得买？","ola":"需综合评估政策风险和实际需求。","cp":["政策变动风险较大","教育公平趋势削弱溢价","自住需求可考虑购买"],"detail":"学区房是否值得买需综合考虑多方面因素。近年来多校划片、六年一学位等政策持续推进，学区房的入学确定性在下降。教育均衡化趋势也在削弱学区房的溢价空间。但若为自住需求且对口学校优质，仍有购买价值。建议理性评估政策风险、自身经济能力和教育需求，不盲目跟风。","legalRef":"综合市场数据及教育政策分析","consumerBenefit":"理性评估学区房价值，做出明智购房决策。","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前"]},"alias":["学区房值得买吗","学区房购买价值","学区房有没有必要买"]},{"id":"P2-C1-025","name":"买学区房要注意哪些坑","domain":"学区教育","subScene":"学区政策","scene":"学区教育·学区政策","cq":"买学区房有哪些常见的坑需要避开？","ola":"注意学位占用、政策变动和落户年限等风险。","cp":["核实学位是否被占用","确认学区划分和顺位","警惕政策变动风险"],"detail":"买学区房需警惕以下风险：一是学位被占用且未满六年，导致子女无法对口入学；二是学区范围调整，买房后学区可能变更；三是多校划片政策下购房不再保证对口入学；四是落户年限不足影响顺位；五是期房未交付无法当年入学；六是轻信中介「买房保入学」承诺。建议购房前全面核实信息并在合同中约定保障条款。","legalRef":"综合购房风险提示及教育政策分析","consumerBenefit":"掌握学区房购房避坑要点，降低交易风险。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["学区房购买陷阱","买学区房注意事项","学区房避坑指南"]},{"id":"P2-C2-006","name":"对口初中怎么看","domain":"学区教育","subScene":"学校评估","scene":"学区教育·学校评估","cq":"选小学时怎么了解它的对口初中好不好？","ola":"查教育部门划片信息并评估初中质量。","cp":["查询教育部门划片公告","评估对口初中升学率","关注对口稳定性"],"detail":"了解对口初中可通过教育部门发布的学区划片公告查询对应初中。评估对口初中质量可看升学率、师资力量、办学特色等。需注意对口关系可能调整，建议关注历年对口稳定性。九年一贯制学校对口确定性更高。选小学时同时考虑对口初中质量，有助于规划完整升学路径。","legalRef":"教育部相关指导意见及各地招生政策","consumerBenefit":"了解对口初中情况，规划完整升学路径。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["怎么查对口初中","对口初中好不好","对口初中怎么了解"]},{"id":"P2-C2-018","name":"学校家庭教育指导怎么看","domain":"学区教育","subScene":"学校评估","scene":"学区教育·学校评估","cq":"学校的家庭教育指导服务重要吗？怎么看好不好？","ola":"重要，良好的家校合作促进孩子成长。","cp":["家校沟通渠道是否畅通","家长教育活动是否丰富","教师家访和反馈频率"],"detail":"学校家庭教育指导是家校共育的重要环节。良好的家庭教育指导包括定期家长会、家长学堂、家访制度、及时沟通反馈等。评估时可了解学校家校沟通渠道是否畅通、家长教育活动是否系统化、教师与家长沟通频率和质量。家校合作紧密的学校更能形成教育合力，促进孩子全面发展。","legalRef":"教育部相关指导意见及各地招生政策","consumerBenefit":"重视家校合作质量，选择共育氛围好的学校。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["家庭教育指导重要吗","学校家校合作怎么看","家庭教育指导评估"]},{"id":"P2-C3-001","name":"孩子升学路径怎么规划","domain":"学区教育","subScene":"教育规划","scene":"学区教育·教育规划","cq":"从长远来看，孩子的升学路径应该怎么规划？","ola":"结合家庭资源和孩子特点分阶段规划。","cp":["按学段分阶段设定目标","预留灵活调整空间","匹配孩子兴趣和能力"],"detail":"孩子升学路径规划应结合家庭资源、孩子特点和当地教育资源综合考量。建议按学段分阶段规划：小学阶段注重习惯培养和兴趣探索，初中阶段关注学业发展和特长培养，高中阶段明确升学方向。规划时预留调整空间，避免过早锁定单一路径。同时关注政策变化，如多校划片、中考改革等，及时调整策略。","legalRef":"综合教育规划政策分析","consumerBenefit":"科学规划升学路径，为孩子教育铺路。","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前"]},"alias":["升学路径如何规划","孩子升学怎么安排","教育路径选择"]},{"id":"P2-C3-005","name":"教育支出大概多少","domain":"学区教育","subScene":"教育规划","scene":"学区教育·教育规划","cq":"从小学到初中，教育支出大概要花多少钱？","ola":"公办义务教育免费，课外支出因人而异。","cp":["公办义务教育阶段免学费","课外辅导是主要支出","总费用因家庭差异大"],"detail":"公办义务教育阶段学费和课本费免除，主要支出包括餐饮费、校服费、课后服务费等，每学期约数百至数千元。最大变量是课外辅导和兴趣班支出，因家庭选择差异很大，年均数千至数万元不等。民办学校学费每学期数千至数万元。建议根据家庭收入合理规划教育预算，避免过度投入影响家庭生活质量。","legalRef":"综合教育支出数据分析","consumerBenefit":"了解教育支出构成，合理规划家庭预算。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["教育费用多少","养孩子教育开支","教育支出预算"]},{"id":"P2-C3-012","name":"军人和人才子女入学有优待吗","domain":"学区教育","subScene":"教育规划","scene":"学区教育·教育规划","cq":"军人或引进人才的子女入学有什么优待政策？","ola":"有优待政策，可享受统筹安排或优先入学。","cp":["军人子女享受教育优待","人才子女可优先安排","需提供相关资格证明"],"detail":"军人子女和引进人才子女入学享有优待政策。军人子女按《军人子女教育优待办法》享受教育优待，可在驻地就近入学或优先安排。各地对引进高层次人才子女入学也有优先安排政策，通常由教育部门统筹保障。申请时需提供军人证明或人才认定证明等材料。具体优待标准和流程因地区而异，建议咨询当地教育部门。","legalRef":"各地军人及人才子女入学优待政策","consumerBenefit":"了解优待政策，保障军人人才子女入学权益。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["军人子女入学优待","人才子女入学政策","军人人才子女入学优待"]},{"id":"P2-C3-013","name":"学区房的房产类型有要求吗","domain":"学区教育","subScene":"教育规划","scene":"学区教育·教育规划","cq":"学区房的房产类型有要求吗？商住楼、小产权房能上学区学校吗？","ola":"通常要求住宅性质，非住宅可能不适用。","cp":["一般要求住宅性质房产","商住楼公寓可能不适用","小产权房通常无法认定"],"detail":"学区房入学通常要求房产为住宅性质。商住楼、公寓等非住宅性质房产在部分城市不作为学区入学依据。小产权房因无法办理合法产权证明，通常不能用于学区入学认定。部分城市对房产面积也有最低要求。建议购房前确认房产用途性质为住宅，并了解当地对房产类型的具体要求，避免买了房却无法入学。","legalRef":"各地义务教育招生入学房产类型要求细则","consumerBenefit":"明确房产类型要求，避免购房入学受阻。","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["学区房房产类型要求","什么类型房产能上学区","学区房产权性质要求"]},{"id":"OWN-LND-003","name":"租金包含哪些费用","domain":"业主资产","subScene":"出租定价与空置控制","scene":"业主资产·出租定价与空置控制","cq":"房东问：出租时租金应该包含哪些费用？物业费水电费谁出？","ola":"租金仅含房费，其他费用合同约定。","cp":["租金一般不含水电燃气","物业费由双方约定","费用承担写进合同"],"detail":"出租房租金一般仅指房屋使用费，水电燃气费、网络费等按实际使用量由租客承担。物业费、供暖费的承担方式由双方在合同中约定，无强制规定。建议在租赁合同中逐项列明费用承担方，避免退租时产生争议。部分房东选择租金含物业费以提升竞争力，但需将成本计入定价。维修费用按法律规定区分自然损耗和人为损坏分别承担。","legalRef":"《中华人民共和国民法典》第七百零四条（租赁合同内容）","consumerBenefit":"帮房东明确费用边界，避免退租纠纷。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["租金包含什么","出租租金含哪些费用","租金包不包物业费"]},{"id":"OWN-LND-004","name":"租金递增条款怎么设","domain":"业主资产","subScene":"出租定价与空置控制","scene":"业主资产·出租定价与空置控制","cq":"房东问：长租合同能不能约定租金逐年递增？递增比例设多少合理？","ola":"可约定递增，建议3%-5%年增幅。","cp":["合同明确递增条款","年增幅建议3%-5%","提前30天书面通知调租"],"detail":"长租合同可以约定租金递增条款。建议年增幅控制在3%-5%，与CPI涨幅和当地租金水平变化保持合理关联。递增条款应在合同中明确写明递增比例、生效时间和通知方式。部分城市对租金涨幅有限制政策，需查询当地规定。建议约定提前30天书面通知调租，给租客合理预期。递增幅度过大可能导致租客流失，重新招租的空置成本需综合考虑。","legalRef":"《中华人民共和国民法典》第七百零四条（租赁合同内容）","consumerBenefit":"帮房东合理设置租金递增，锁定长租收益。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["租金递增条款","租金逐年递增","出租房涨租金"]},{"id":"OWN-LND-005","name":"出租房需要装修吗","domain":"业主资产","subScene":"出租定价与空置控制","scene":"业主资产·出租定价与空置控制","cq":"房东问：房子要出租，需要装修吗？简装还是精装？","ola":"简装够用，重点在厨卫和家电。","cp":["简装性价比最高","厨卫重点投入","家电配齐提升租金"],"detail":"出租房装修建议以简装为主，重点投入厨卫两个功能区。墙面刷白、地板铺好、厨卫设施齐全即可出租。精装修的投入回收周期较长，且租客使用损耗大。家电配置建议配齐空调、洗衣机、冰箱、热水器四件套，可提升租金100-300元/月。装修材料选择耐用易清洁的，避免高端材料。毛坯房出租需确认当地是否允许毛坯出租。","legalRef":"《中华人民共和国民法典》第七百零八条（出租人交付义务）","consumerBenefit":"帮房东用最小投入获得最大租金回报。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["出租房装修策略","出租房要不要装修","出租房装修标准"]},{"id":"OWN-LND-008","name":"租客身份怎么核实","domain":"业主资产","subScene":"租客筛选与背调","scene":"业主资产·租客筛选与背调","cq":"房东问：租客的身份怎么核实？需要留哪些资料？","ola":"验原件留复印件，核实人证一致。","cp":["查验身份证原件","留存复印件","核实人证一致性"],"detail":"租客身份核实建议：一、查验身份证原件，核对照片与本人是否一致；二、留存身份证复印件并让租客签字确认用途；三、了解租客工作单位并验证在职情况；四、外籍租客需查验护照和居留许可。建议同时留存租客紧急联系人信息。根据《反恐怖主义法》，房东需登记承租人身份信息并向公安部门备案。未按规定登记可能面临罚款。建议使用各地住房租赁登记备案系统进行实名登记。","legalRef":"《中华人民共和国反恐怖主义法》第二十一条（实名登记）","consumerBenefit":"帮房东合规核实租客身份，履行法定义务。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["租客身份核实","出租房查验身份证","核实租客身份信息"]},{"id":"OWN-LND-011","name":"租客养宠物怎么办","domain":"业主资产","subScene":"租客筛选与背调","scene":"业主资产·租客筛选与背调","cq":"房东问：租客想养宠物，我该不该同意？怎么保护房子？","ola":"可附条件允许，加收宠物押金。","cp":["合同明确宠物条款","加收宠物押金","退租时检查损坏"],"detail":"房东可附条件允许租客养宠物。建议在合同中明确约定：宠物种类、数量限制，如仅允许养猫或小型犬；加收宠物押金500-1000元用于覆盖可能的清洁和维修费用；约定租客需对宠物造成的损坏承担赔偿责任。退租时重点检查地板划痕、墙面污损、异味等问题。如不允许养宠物，应在合同中明确禁止并约定违约金。注意导盲犬等工作犬受法律保护，不能拒绝。","legalRef":"《中华人民共和国民法典》第七百一十一条（承租人使用不当）","consumerBenefit":"帮房东平衡宠物友好与房屋保护。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["租客养宠物","出租房宠物问题","租房能养宠物吗"]},{"id":"OWN-LND-012","name":"租客扰民怎么处理","domain":"业主资产","subScene":"租客筛选与背调","scene":"业主资产·租客筛选与背调","cq":"房东问：邻居投诉租客噪音扰民，房东有责任吗？怎么处理？","ola":"房东有管理义务，需督促整改。","cp":["及时核实投诉内容","书面通知租客整改","拒不整改可解除合同"],"detail":"租客扰民时房东有一定管理义务。建议处理流程：一、及时核实邻居投诉内容，了解具体情况；二、书面通知租客限期整改，告知扰民的后果；三、如租客拒不整改，可依据合同中「不影响邻里正常生活」条款解除合同；四、与邻居保持沟通，积极协调。房东长期不处理可能导致邻居向物业或社区投诉。建议在合同中约定租客不得影响邻里正常生活的条款及违约责任。","legalRef":"《中华人民共和国民法典》第七百一十四条（妥善保管义务）","consumerBenefit":"帮房东处理扰民问题，维护邻里关系。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["租客扰民处理","租客噪音扰民","出租房扰民投诉"]},{"id":"OWN-LND-013","name":"租赁合同必须书面吗","domain":"业主资产","subScene":"租赁合同与押金约定","scene":"业主资产·租赁合同与押金约定","cq":"房东问：出租房子必须签书面合同吗？口头约定行不行？","ola":"租期6个月以上必须书面，口头视为不定期。","cp":["租期超6个月须书面","口头约定视为不定期","书面合同保护双方权益"],"detail":"租赁期限六个月以上的应当采用书面形式。未采用书面形式且无法确定租赁期限的，视为不定期租赁，双方可随时解除但需在合理期限前通知对方。建议无论租期长短都签订书面合同，明确租金、押金、维修责任、违约条款等关键事项。可使用各地住建部门发布的租赁合同示范文本。书面合同是维权的基础依据，口头约定举证困难，发生纠纷时难以保护房东权益。","legalRef":"《中华人民共和国民法典》第七百零七条（书面形式要求）","consumerBenefit":"帮房东理解合同形式要求，用书面合同保护权益。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["租赁合同必须书面","租房合同要书面吗","口头租赁有效吗"]},{"id":"OWN-LND-014","name":"押金收多少合理","domain":"业主资产","subScene":"租赁合同与押金约定","scene":"业主资产·租赁合同与押金约定","cq":"房东问：出租房押金收多少合适？一个月还是两个月？","ola":"通常1-2个月租金，最高不超3个月。","cp":["常见1-2个月租金","最高不超过3个月","押金条款写进合同"],"detail":"出租房押金通常收取1-2个月租金，部分城市对押金金额有上限规定。北京等地规定押金一般不超过1个月租金，深圳规定不超过3个月。建议在合同中明确押金金额、退还条件和扣减情形。退还时间建议约定为退租后7-15个工作日内。押金不得用于抵扣自然损耗，仅可用于租客拖欠费用、人为损坏或违约金。收取押金时应出具收据，退租时无正当理由不得扣减。","legalRef":"《住房租赁条例》第十条（押金管理）","consumerBenefit":"帮房东合理收取押金，合规管理。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["出租房押金收多少","租房押金标准","押金一个月还是两个月"]},{"id":"OWN-LND-017","name":"租客提前退租怎么办","domain":"业主资产","subScene":"租赁合同与押金约定","scene":"业主资产·租赁合同与押金约定","cq":"房东问：租客住半年就要提前退租，押金能全扣吗？","ola":"可扣违约金但需合理，不可全扣。","cp":["按合同约定收违约金","违约金不超实际损失","重新招租费用可主张"],"detail":"租客提前退租构成违约，房东可按合同约定收取违约金。但违约金应以实际损失为限，不能直接全额扣押押金。实际损失包括空置期租金损失、重新招租的中介费等。建议处理流程：一、确认提前退租原因，如工作调动等可酌情减免；二、按合同约定计算违约金，通常为1-2个月租金；三、扣除违约金后退还剩余押金；四、双方签署解除协议。如合同未约定违约金，房东可主张实际损失赔偿。","legalRef":"《中华人民共和国民法典》第五百八十五条（违约金）","consumerBenefit":"帮房东合理处理提前退租，减少损失。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["租客提前退租","提前退租违约金","租客提前解约"]},{"id":"OWN-LND-019","name":"租赁合同要不要备案","domain":"业主资产","subScene":"租赁合同与押金约定","scene":"业主资产·租赁合同与押金约定","cq":"房东问：租赁合同要不要去备案？不备案有什么后果？","ola":"建议备案，不影响合同效力但有保障。","cp":["备案不影响合同效力","备案可享受税收优惠","部分城市要求强制备案"],"detail":"租赁合同未办理登记备案不影响合同效力，但建议备案。备案的好处：一、部分地区可享受住房租赁税收优惠政策；二、备案记录可作为权属证明用于子女入学等事项；三、发生纠纷时备案合同是有力证据；四、部分城市要求房东在出租后规定期限内办理备案，逾期可能面临罚款。备案流程通常为双方携带身份证、房产证、租赁合同到街道办或房管部门办理，部分城市支持线上备案。","legalRef":"《中华人民共和国民法典》第七百零六条（备案不影响效力）","consumerBenefit":"帮房东理解备案价值，合规出租。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["租赁合同备案","租房登记备案","出租房要不要备案"]},{"id":"OWN-LND-021","name":"出租房维修责任怎么分","domain":"业主资产","subScene":"委托托管与维修责任","scene":"业主资产·委托托管与维修责任","cq":"房东问：出租房东西坏了，维修费该房东出还是租客出？","ola":"自然损耗房东修，人为损坏租客赔。","cp":["自然损耗房东负责","人为损坏租客承担","合同约定优先"],"detail":"出租房维修责任划分规则：合同有约定的从约定；无约定的，自然损耗由房东负责维修，人为损坏由租客承担维修费用。自然损耗包括水管老化渗漏、电器正常老化、墙面自然泛黄等。人为损坏包括暴力使用导致门窗损坏、私自拆改房屋结构等。租客发现需要维修时应及时通知房东，房东应在合理期限内维修。房东逾期不修的，租客可自行维修并要求房东承担费用。建议合同中明确维修责任划分。","legalRef":"《中华人民共和国民法典》第七百一十二条（出租人维修义务）","consumerBenefit":"帮房东明确维修责任边界，减少争议。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["出租房维修责任","房屋维修谁负责","出租房坏了谁修"]},{"id":"OWN-LND-023","name":"房屋漏水谁负责修","domain":"业主资产","subScene":"委托托管与维修责任","scene":"业主资产·委托托管与维修责任","cq":"房东问：租客反映房子漏水，这个该谁修？修费谁出？","ola":"自然老化房东修，租客过错租客修。","cp":["水管老化房东负责","租客使用不当租客负责","影响居住需减租或延租"],"detail":"出租房漏水维修责任需区分原因：一、水管自然老化、防水层自然失效导致的漏水，属于自然损耗，由房东负责维修；二、租客使用不当如忘关水龙头、暴力使用设施导致的漏水，由租客承担维修费用；三、如漏水影响租客正常居住，房东应及时维修，维修期间可相应减少租金或延长租期。建议房东收到漏水报告后尽快安排检查维修，保留维修记录和费用凭证。漏水造成楼下邻居损失的，由责任方承担赔偿。","legalRef":"《中华人民共和国民法典》第七百一十二条（出租人维修义务）","consumerBenefit":"帮房东区分漏水责任，及时妥善处理。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["出租房漏水维修","漏水责任划分","出租房漏水谁修"]},{"id":"OWN-LND-024","name":"托管公司跑路怎么办","domain":"业主资产","subScene":"委托托管与维修责任","scene":"业主资产·委托托管与维修责任","cq":"房东问：房子委托的托管公司跑路了，租客还在住，租金收不到怎么办？","ola":"托管跑路房东仍享有房屋所有权。","cp":["向托管公司追偿损失","与租客协商重新签约","报警并保留证据"],"detail":"托管公司跑路的处理建议：一、房东作为房屋所有权人有权收回房屋，但不能强制驱赶已交租金的租客；二、与租客协商，如租客已向托管公司付清租金，可协商重新签订租赁合同避免双重损失；三、向公安机关报案并保留委托合同、转账记录等证据；四、向住建部门投诉，部分城市设有租赁风险准备金；五、通过诉讼向托管公司追偿损失。建议委托前核查公司资质和经营状况，警惕高收低租、长收短付等异常模式。","legalRef":"《中华人民共和国民法典》第九百三十三条（委托解除）","consumerBenefit":"帮房东应对托管跑路风险，减少损失。","tags":{"clientType":["landlord"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["托管公司跑路","房屋托管公司失联","长租公寓暴雷"]},{"id":"OWN-SLR-014","name":"中介费怎么算谁出","domain":"业主资产","subScene":"出售委托","scene":"业主资产·出售委托","cq":"业主问：卖房中介费怎么算？应该谁出？","ola":"通常1%-3%，买卖双方各付或卖方全付。","cp":["佣金比例1%-3%","买卖双方协商承担","签书面协议约定"],"detail":"中介费（佣金）规则：一、收费标准，二手房交易佣金通常为成交价的1%-3%，各地有指导价但可协商；二、承担方式，常见有卖方全付、买卖双方各付一半、买方全付三种，由市场行情决定，卖方市场时买方承担较多；三、支付时点，通常在过户完成后支付，不建议提前支付全款；四、注意事项，佣金应在委托协议中明确约定比例和支付方式，口头约定难以维权。部分城市规定中介费上限，如北京规定住宅买卖中介费不超过2%。","legalRef":"《中华人民共和国民法典》第九百二十八条（委托人付费义务）","consumerBenefit":"帮业主明确中介费规则，控制交易成本。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["中介费谁出","卖房中介费","中介佣金标准"]},{"id":"OWN-SLR-015","name":"委托期限设多久合适","domain":"业主资产","subScene":"出售委托","scene":"业主资产·出售委托","cq":"业主问：卖房委托期限设多久合适？太长怕被锁死。","ola":"独家3-6个月，多家1-3个月可灵活调整。","cp":["独家3-6个月","多家1-3个月","约定提前解约条件"],"detail":"委托期限建议：独家委托设3-6个月，给中介足够时间营销和带看，同时避免过长被锁定；多家委托可设1-3个月，效果不好可随时更换。期限设定考虑因素：一、市场热度，卖方市场可缩短，买方市场需延长；二、房屋条件，热门户型1-2个月可成交，冷门户型需更长时间；三、价格预期，定价高于市场价需要更长的委托期。建议在协议中约定：到期未售出自动终止、提前解约需提前15天书面通知、解产后不影响已带看客户的佣金归属。","legalRef":"《中华人民共和国民法典》第九百三十三条（委托解除）","consumerBenefit":"帮业主合理设置委托期限，灵活掌控。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["委托期限多长","卖房委托期限","中介委托时间"]},{"id":"OWN-SLR-016","name":"中介不作为怎么办","domain":"业主资产","subScene":"出售委托","scene":"业主资产·出售委托","cq":"业主问：签了委托但中介不积极推房，怎么办？","ola":"先沟通再解约，保留证据维权。","cp":["书面要求中介履约","约定带看频次标准","可依法解除委托"],"detail":"中介不作为的处理建议：一、书面催告，发送书面通知要求中介按协议约定提供服务，保留沟通记录；二、要求反馈，要求中介定期提供带看记录、客户反馈和营销进展；三、协商解约，如中介确实未积极推广，可协商解除委托协议；四、依法解除，根据民法典第九百三十三条，委托人可随时解除委托合同，但可能需赔偿中介直接损失；五、投诉维权，如中介存在违规行为，可向当地住建部门或房地产中介行业协会投诉。","legalRef":"《中华人民共和国民法典》第九百三十三条（委托解除）","consumerBenefit":"帮业主应对中介不作为，维护权益。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["中介不作为","中介不卖房怎么办","中介不负责任"]},{"id":"OWN-SLR-017","name":"卖房要怎么布置","domain":"业主资产","subScene":"房源包装","scene":"业主资产·房源包装","cq":"业主问：卖房前房子要怎么布置才好看？","ola":"干净整洁、去个人化、采光通风。","cp":["彻底清洁去杂物","去个人化装饰","打开窗帘保持明亮"],"detail":"卖房布置建议：一、彻底清洁，包括厨房油污、卫生间水垢、窗户玻璃，干净是第一印象；二、去杂物，收起多余物品让空间显大，移走季节性衣物和杂物；三、去个人化，收起全家福照片、宗教物品等，让买家想象自己住进来的样子；四、采光通风，看房前打开所有窗帘和灯，开窗通风去除异味；五、简单装饰，客厅放一束鲜花、餐桌铺干净桌布，营造温馨感；六、修缮细节，修补墙面裂缝、更换坏灯泡、修复漏水龙头。投入不大但效果显著，","legalRef":"《中华人民共和国民法典》第五百条（缔约过失责任）","consumerBenefit":"帮业主用最小投入提升房屋卖相。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["卖房布置技巧","卖房怎么布置好看","房源布置"]},{"id":"OWN-SLR-018","name":"空房还是带家具卖好","domain":"业主资产","subScene":"房源包装","scene":"业主资产·房源包装","cq":"业主问：卖房时空房好还是带家具好？","ola":"看房带家具显温馨，签约后可空房交。","cp":["带家具看房效果好","空房展示空间感","合同约定交房标准"],"detail":"空房与带家具出售对比：带家具看房的优势是营造生活氛围，买家更容易产生代入感，尤其精装修房带品质家具效果更好；空房的优势是空间感强，买家能看清房屋实际面积和格局，也方便测量规划。建议策略：看房期间保留主要家具（沙发、床、餐桌）营造氛围，但在合同中约定交房标准为空房或带哪些家具。如家具较旧或不搭配，建议搬走腾空。如选择带家具出售，需在合同中列明家具清单和作价方式，避免交房时争议。","legalRef":"《中华人民共和国民法典》第五百九十六条（买卖合同内容）","consumerBenefit":"帮业主选择展示方式，提升成交率。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["空房卖还是带家具","卖房空房好还是精装","空房vs带家具"]},{"id":"OWN-SLR-019","name":"卖房前要不要维修","domain":"业主资产","subScene":"房源包装","scene":"业主资产·房源包装","cq":"业主问：卖房前要不要修一下？哪些值得修哪些不值得？","ola":"小修提升卖相，大修不划算。","cp":["小修投入回报高","大修翻新不划算","重点修厨卫和水电"],"detail":"卖房前维修建议：值得修的是低成本高回报的项目：一、修补墙面裂缝和刷白，成本几百元但显著提升观感；二、修复漏水龙头和水管，漏水是买家最敏感的问题；三、更换坏灯泡和老旧开关面板；四、修复门窗密封条和把手。不值得修的是大投入项目：一、重新装修厨房卫生间，投入数万但买方可能要按自己喜好重装；二、更换地板，除非严重损坏否则不建议；三、大规模防水翻新。原则是修小问题不修大项目，花小钱办大事。维修后拍照留存，","legalRef":"《中华人民共和国民法典》第七百零八条（出租人交付义务）","consumerBenefit":"帮业主用最小维修成本提升房屋价值。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["卖房前修不修","卖房要不要翻新","卖房维修值不值"]},{"id":"OWN-SLR-020","name":"房源照片怎么拍好看","domain":"业主资产","subScene":"房源包装","scene":"业主资产·房源包装","cq":"业主问：卖房照片怎么拍才好看？要不要请专业摄影师？","ola":"白天拍、广角、保持整洁。","cp":["白天自然光拍摄","广角镜头显空间","保持整洁干净"],"detail":"房源照片拍摄建议：一、时间选择，白天自然光充足时拍摄，避免夜间开灯拍；二、设备选择，手机广角模式够用，如预算允许可请专业摄影师（费用约200-500元）；三、拍摄要点，每个房间拍2-3张不同角度，客厅和主卧是重点；四、构图技巧，从房间角落拍摄能展示更多空间，镜头与腰部齐平保持平视；五、后期处理，可适度调亮和校正角度，但不可过度美化导致实地看房落差大；六、注意事项，","legalRef":"《中华人民共和国民法典》第五百条（缔约过失责任）","consumerBenefit":"帮业主拍出吸引买家的房源照片。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["房源拍照技巧","卖房照片怎么拍","房产摄影"]},{"id":"OWN-SLR-021","name":"Home Staging值不值得做","domain":"业主资产","subScene":"房源包装","scene":"业主资产·房源包装","cq":"业主问：听说有Home Staging服务，卖房值不值得做？","ola":"高端房值得，普通房简单布置。","cp":["高端房源值得做","普通房源简单布置即可","投入产出需评估"],"detail":"Home Staging（房屋展示布置）是通过专业软装提升房屋卖相的服务。值不值得做取决于房屋定位和预算：高端房源（总价500万以上）做Staging投入5000-20000元，可提升成交价1%-3%，投入产出比可观；普通房源不建议花大钱做Staging，自行简单布置即可达到大部分效果。自行布置要点：一、客厅放鲜花和靠枕；二、卧室铺整洁床品；三、厨房台面清空放水果碗；四、卫生间放新毛巾和绿植。","legalRef":"《中华人民共和国民法典》第五百条（缔约过失责任）","consumerBenefit":"帮业主评估Staging投入产出，合理选择。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["Home Staging值不值","房屋 staging","卖房家居布置"]},{"id":"OWN-SLR-022","name":"怎么配合中介带看","domain":"业主资产","subScene":"看房接待","scene":"业主资产·看房接待","cq":"业主问：中介要带客户来看房，我怎么配合？","ola":"保持整洁、看房回避、留钥匙。","cp":["保持房屋整洁明亮","看房时回避给空间","提前准备房屋信息"],"detail":"配合中介带看建议：一、保持房屋随时可看状态，日常保持整洁、通风、照明正常；二、看房时业主最好回避，让买家自由参观和提问，业主在场会让买家不自在影响判断；三、如必须在场，保持友善但不主动推销，中介负责介绍；四、提前准备好房屋相关信息，如房龄、物业费、车位、学区等，通过中介转达；五、贵重物品锁好，避免看房期间丢失；六、看房后及时向中介了解买家反馈，调整策略。建议给中介留一套钥匙或密码锁，方便随时带看，","legalRef":"《中华人民共和国民法典》第五百条（缔约过失责任）","consumerBenefit":"帮业主高效配合带看，提升成交概率。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["配合看房","怎么配合带看","卖房看房配合"]},{"id":"OWN-SLR-024","name":"看房时说什么不说什么","domain":"业主资产","subScene":"看房接待","scene":"业主资产·看房接待","cq":"业主问：看房时我该说什么不该说什么？","ola":"多说优点不说底价和急售原因。","cp":["多说优点不说底线","不透露急售原因","不评论买家出价"],"detail":"看房沟通原则：该说的包括房屋亮点（南北通透、采光好、学区优质）、周边配套（地铁、商场、医院）、邻里环境（安静、安全、物业管理好）、不该说的包括出售原因（急用钱、置换等会让买家压价）、底价和谈判空间、其他买家出价情况、邻居纠纷等负面信息。注意事项：一、不在买家面前与中介讨论价格策略；二、不主动提及房屋缺点，但被问到时诚实回答；三、不催促买家做决定，给其思考空间；四、不贬低周边其他在售房源，","legalRef":"《中华人民共和国民法典》第五百条（缔约过失责任）","consumerBenefit":"帮业主掌握看房沟通分寸，维护议价空间。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["看房说什么","卖房看房话术","看房沟通技巧"]},{"id":"OWN-SLR-028","name":"买家压价怎么办","domain":"业主资产","subScene":"议价谈判","scene":"业主资产·议价谈判","cq":"业主问：买家看了房总压价，怎么应对？","ola":"不急于回应低价，让步幅度递减。","cp":["不急于回应低价","让中介探真实预算","用优势支撑价格"],"detail":"买家压价应对策略：一、不急于拒绝低价，初次出价通常低于实际预算，让中介探明真实心理价位；二、用优势支撑价格，列举地段、学区、装修、配套等核心卖点说明定价合理；三、让步策略，每次让步幅度递减（如第一次降5万、第二次降2万），传递「已经接近底线」的信号；四、条件交换，降价的同时要求买家让步，如缩短付款周期、承担部分税费等；五、竞争 leverage，如有其他买家也在看房，让中介自然提及；六、底线思维，","legalRef":"《中华人民共和国民法典》第五百九十五条（买卖合同定义）","consumerBenefit":"帮业主守住价格底线，实现合理成交。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["买家压价应对","卖房被砍价","议价策略"]},{"id":"OWN-SLR-030","name":"怎么制造竞争感","domain":"业主资产","subScene":"议价谈判","scene":"业主资产·议价谈判","cq":"业主问：怎么让买家觉得有竞争，主动加价？","ola":"集中带看、中介传话、设截止日。","cp":["让中介提及其他意向","集中带看制造氛围","设报价截止时间"],"detail":"制造竞争感的方法：一、集中带看，多组客户同时看房自然形成竞争氛围；二、中介传话，让中介自然提及「有其他客户也在考虑」「某客户已出价XX」，但必须真实不能编造；三、设截止时间，告知中介「某日前确定买家」，给买家决策压力；四、拒绝首次出价，首次出价不要立即接受，即使出价已达预期，稍微犹豫让买家觉得有竞争；五、反向报价，对出价低的买家报一个高于其出价但低于挂牌价的价格，传递「还有空间但不多」的信号。","legalRef":"《中华人民共和国民法典》第五百九十五条（买卖合同定义）","consumerBenefit":"帮业主合理运用竞争策略，提升成交价。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["卖房制造竞争","竞价策略","卖房竞争感"]},{"id":"OWN-SLR-031","name":"谈判僵局怎么破","domain":"业主资产","subScene":"议价谈判","scene":"业主资产·议价谈判","cq":"业主问：价格谈不拢，双方僵住了怎么办？","ola":"找非价格条件、冷处理、折中。","cp":["寻找非价格条件","暂时搁置冷处理","中介居中斡旋"],"detail":"谈判僵局破解方法：一、转移焦点到非价格条款，如付款方式、交房时间、家具家电、税费承担、装修保留等，在非价格方面让步换取价格共识；二、冷处理，暂停谈判3-5天，双方重新评估，有时买家会主动加价；三、中介斡旋，让中介分别了解双方真实底线，在中间找平衡点，中介的专业建议可能打破僵局；四、折中方案，双方各让一半，如差距10万则各让5万；五、引入条件，如「我降到XX，但你必须一周内签约付定金」。","legalRef":"《中华人民共和国民法典》第五百九十五条（买卖合同定义）","consumerBenefit":"帮业主破解谈判僵局，促成交易。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["谈判僵局","卖房谈不拢","议价僵局"]},{"id":"OWN-SLR-032","name":"全款和贷款怎么选","domain":"业主资产","subScene":"议价谈判","scene":"业主资产·议价谈判","cq":"业主问：一个买家全款一个贷款，全款价格低5万，选哪个？","ola":"全款快但价低，贷款价高有风险。","cp":["全款快但价低","贷款价高但风险多","评估贷款审批风险"],"detail":"全款与贷款买家对比：全款优势是交易快（1-2周完成）、无贷款审批风险、过户简单、可要求缩短付款周期；劣势是通常出价更低。贷款优势是出价更高、买家群体更大；劣势是交易周期长（1-2个月）、存在贷款审批不通过风险、银行评估价可能低于成交价。选择建议：一、如全款与贷款差价在3%以内，优先全款降低风险；二、如贷款买家首付比例高（50%以上）且征信良好，风险可控可选贷款；","legalRef":"《中华人民共和国民法典》第五百九十六条（买卖合同内容）","consumerBenefit":"帮业主权衡全款与贷款，做出最优选择。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["全款还是贷款","卖房全款好还是贷款","全款买房优势"]},{"id":"OWN-SLR-033","name":"卖房收定金和订金有什么区别","domain":"业主资产","subScene":"议价谈判","scene":"业主资产·议价谈判","cq":"业主问：买家给的定金和订金有什么区别？收了能退吗？","ola":"定金有法律效力不退，订金可退。","cp":["定金有法律效力不退","订金可退无约束力","收定金需写收据"],"detail":"定金与订金的区别：定金是法律概念，具有担保性质，根据《民法典》第五百八十六条，给付定金一方不履行合同的无权要求返还，收受定金一方不履行的应双倍返还。订金不是法律概念，通常被视为预付款，无论哪方违约都可要求退还。卖房收取定金注意事项：一、写明「定金」而非「订金」或「意向金」；二、定金金额不超过合同标的额的20%；三、出具定金收据并注明定金性质和适用规则；四、定金收取后应在约定期限内签订正式买卖合同。","legalRef":"《中华人民共和国民法典》第五百八十六条（定金）","consumerBenefit":"帮业主正确收取定金，保障交易安全。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["定金和订金区别","定金订金","卖房定金"]},{"id":"OWN-SLR-034","name":"签约要注意什么","domain":"业主资产","subScene":"合同签署","scene":"业主资产·合同签署","cq":"业主问：签买卖合同要注意什么？","ola":"核对身份、逐条阅读、约定违约。","cp":["核对买方身份和资质","逐条阅读合同条款","约定违约责任和期限"],"detail":"签约注意事项：一、核对买方身份，查验身份证原件，如贷款购房确认贷款预审批结果；二、价格条款，写明成交总价、付款方式（全款/贷款）、付款节点（定金→首付→尾款）；三、过户条款，约定过户时间、费用承担、材料准备；四、交房条款，约定交房时间、交房标准（空房/带家具）、物业费用结清；五、违约责任，约定逾期付款、逾期过户、一方反悔的违约金标准；六、户口条款，如房屋内有户口约定迁出时间；七、附属条款，","legalRef":"《中华人民共和国民法典》第五百九十六条（买卖合同内容）","consumerBenefit":"帮业主审慎签约，防范交易风险。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["签约注意事项","卖房签约","合同签署注意"]},{"id":"OWN-SLR-035","name":"卖房签阴阳合同有什么风险","domain":"业主资产","subScene":"合同签署","scene":"业主资产·合同签署","cq":"业主问：买家提议签阴阳合同做低网签价避税，能同意吗？","ola":"违法、影响贷款、法院只认网签价。","cp":["阴阳合同违法风险大","可能被税务稽查","影响买方贷款额度"],"detail":"阴阳合同风险：阴阳合同指实际成交价与网签备案价不一致，通过做低网签价减少税费。风险包括：一、违法风险，涉嫌偷逃税款，税务部门可追缴税款并处罚款；二、贷款风险，做低合同价导致银行评估价更低，买方贷款额度减少反而需提高首付；三、违约风险，如交易纠纷，法院以网签价为准，卖方可能无法追回实际差额；四、刑事风险，情节严重的可能构成逃税罪。建议拒绝阴阳合同，按实际成交价网签。如买方坚持避税，","legalRef":"《中华人民共和国民法典》第一百四十六条（虚假表示）","consumerBenefit":"帮业主拒绝阴阳合同，合法合规交易。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["阴阳合同风险","做低合同价","阴阳合同"]},{"id":"OWN-SLR-036","name":"违约条款怎么写","domain":"业主资产","subScene":"合同签署","scene":"业主资产·合同签署","cq":"业主问：卖房合同的违约条款怎么写才保护自己？","ola":"约定具体违约金，覆盖主要场景。","cp":["约定具体违约金标准","覆盖主要违约场景","违约金与定金不重复"],"detail":"违约条款设计建议：一、买方逾期付款，按日万分之五收取违约金，超过15天可解除合同并没收定金；二、卖方逾期过户/交房，按日万分之五支付违约金，超过15天买方可解除合同并双倍返还定金；三、一方无故反悔，违约方支付合同总价20%的违约金；四、买方贷款不批，如非卖方原因，买方需在约定期限内补齐全款，否则解除合同没收定金；五、户口未按期迁出，按日支付违约金。注意事项：违约金标准不宜过高，","legalRef":"《中华人民共和国民法典》第五百八十五条（违约金）","consumerBenefit":"帮业主完善违约条款，保障交易安全。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["违约条款","卖房违约责任","合同违约金"]},{"id":"OWN-SLR-037","name":"卖房网签是什么意思","domain":"业主资产","subScene":"合同签署","scene":"业主资产·合同签署","cq":"业主问：网签是什么意思？必须网签吗？","ola":"在线签备案合同，防一房二卖。","cp":["网签=在线签备案合同","防止一房二卖","必须网签才安全"],"detail":"网签是指买卖双方通过房管部门的网上签约系统签订电子版买卖合同并备案。网签作用：一、防止一房二卖，网签后该房源在系统中锁定，无法再次网签给他人；二、合同备案，网签合同是后续缴税过户的必要文件；三、价格透明，网签价格作为税务部门核税依据；四、交易安全，网签流程受房管部门监管。网签流程：双方在房管部门网签系统填写合同信息→确认无误后提交→生成网签合同号→打印合同双方签字。建议签约后尽快网签，","legalRef":"《中华人民共和国城市房地产管理法》第三十六条（权属登记）","consumerBenefit":"帮业主理解网签意义，保障交易安全。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["网签是什么","房屋网签","二手房网签"]},{"id":"OWN-SLR-038","name":"卖房签约后能反悔吗","domain":"业主资产","subScene":"合同签署","scene":"业主资产·合同签署","cq":"业主问：签了买卖合同后不想卖了，能反悔吗？","ola":"反悔需双倍返还定金加违约金。","cp":["签约后反悔需担责","可能双倍返还定金","还需支付违约金"],"detail":"签约后反悔的法律后果：一、定金责任，如已收取定金，需双倍返还定金；二、违约金责任，如合同约定违约金，需按约定支付（通常为总价的10%-20%）；三、赔偿损失，如买方已产生实际损失（如贷款评估费、搬家费等），需赔偿；四、强制履行，买方可起诉要求继续履行合同，法院可能判决强制过户。定金与违约金的关系：买方只能选择适用定金条款或违约金条款，不能同时主张。建议签约前慎重考虑，一旦签约应诚信履行。","legalRef":"《中华人民共和国民法典》第五百八十五条（违约金）","consumerBenefit":"帮业主理解反悔后果，谨慎签约。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["签约后反悔","卖房签了合同能反悔吗","签了合同不想卖了"]},{"id":"OWN-SLR-041","name":"交房要注意什么","domain":"业主资产","subScene":"过户交房","scene":"业主资产·过户交房","cq":"业主问：交房时要注意什么？怎么避免后续纠纷？","ola":"结清费用、签署确认书、交接钥匙。","cp":["结清所有费用","签署交割确认书","交接钥匙和门禁卡"],"detail":"交房注意事项：一、费用结清，交房前结清水费、电费、燃气费、物业费、取暖费、有线电视费、宽带费等所有费用，保留结清凭证；二、设施检查，双方共同检查房屋设施状况，与合同约定的交房标准对比，如有损坏按约定处理；三、物品交接，合同约定的家具家电按清单交接，注明品牌型号和状况；四、钥匙门禁，交接房屋钥匙、门禁卡、车位卡、信箱钥匙等；五、签署确认书，双方签署《物业交割确认书》，注明交房日期和房屋状况；","legalRef":"《中华人民共和国民法典》第五百九十九条（交付义务）","consumerBenefit":"帮业主规范交房流程，避免后续纠纷。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["交房注意事项","卖房交房","房屋交接"]},{"id":"OWN-SLR-042","name":"户口迁出怎么处理","domain":"业主资产","subScene":"过户交房","scene":"业主资产·过户交房","cq":"业主问：卖房后我的户口要迁走吗？不迁有什么后果？","ola":"合同约定迁出期限，逾期有违约金。","cp":["建议及时迁出","合同约定迁出期限","逾期可约定违约金"],"detail":"户口迁出处理：一、法律上卖房后户口不强制迁出，但买家通常要求迁出，建议在合同中约定迁出期限（通常过户后30-60天内）；二、如卖方不迁出，买方可依据合同追究违约责任，但法院通常不直接判决强制迁出户口；三、部分城市（如北京）设立了户口强制迁出政策，可向公安机关申请将逾期未迁出的户口迁至社区公共户；四、如卖方暂无迁入地址，可申请迁入社区公共户或亲友地址；","legalRef":"《中华人民共和国民法典》第五百九十六条（买卖合同内容）","consumerBenefit":"帮业主妥善处理户口迁出，避免纠纷。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"术","meetingPhase":["见前"]},"alias":["户口迁出","卖房户口问题","房屋户口没迁走"]},{"id":"OWN-SLR-044","name":"过户后发现问题怎么办","domain":"业主资产","subScene":"过户交房","scene":"业主资产·过户交房","cq":"业主问：过户交房后买家说房子有问题找我，怎么办？","ola":"隐蔽瑕疵需担责，已知问题不负责。","cp":["区分隐蔽瑕疵和已知问题","合同约定瑕疵责任范围","合理处理避免诉讼"],"detail":"过户后发现问题处理：一、隐蔽瑕疵，如卖方明知存在但未告知的质量问题（如漏水、裂缝等），买方可要求赔偿或修复，卖方需承担责任；二、已知问题，如看房时已存在且买方知晓的问题，卖方不承担责任；三、自然损耗，过户后出现的正常老化损耗卖方不负责；四、合同约定，如合同中约定「以现状交付」或「买方已知悉房屋状况」，可减轻卖方责任；五、处理建议，先了解问题性质和严重程度，如确实属于隐瞒的隐蔽瑕疵建议协商解决，","legalRef":"《中华人民共和国民法典》第六百一十五条（瑕疵担保责任）","consumerBenefit":"帮业主应对过户后纠纷，合理处理。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["过户后发现问题","卖房后买方找麻烦","过户后纠纷"]},{"id":"OWN-SLR-045","name":"卖房后钱怎么规划","domain":"业主资产","subScene":"资产优化","scene":"业主资产·资产优化","cq":"业主问：卖房后拿到一笔钱，怎么规划使用？","ola":"留应急金、还高息债、分散投资。","cp":["留足应急资金","分散投资降风险","避免冲动消费"],"detail":"卖房款规划建议：一、留足应急资金，预留6-12个月生活费作为应急储备；二、如有贷款先还清高息负债，如信用卡、消费贷等；三、分散投资，避免将全部资金投入单一资产，建议按风险偏好分配：低风险（存款、国债、货币基金）40%-50%、中风险（债券基金、银行理财）30%-40%、较高风险（股票、基金）10%-20%；四、如为置换购房，先确定购房预算再安排资金；五、避免冲动消费，卖房款不是「额外收入」，","legalRef":"《中华人民共和国民法典》第五百九十五条（买卖合同定义）","consumerBenefit":"帮业主合理规划卖房款，保值增值。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"道","meetingPhase":["见前"]},"alias":["卖房后钱怎么用","卖房款规划","卖房后资金安排"]},{"id":"OWN-SLR-046","name":"换房还是投资","domain":"业主资产","subScene":"资产优化","scene":"业主资产·资产优化","cq":"业主问：卖了房是换套大的还是拿去投资？","ola":"居住需求优先于投资回报。","cp":["换房满足居住需求","投资看回报和风险","核心是需求导向"],"detail":"换房与投资选择建议：一、优先满足居住需求，如当前住房不满足家庭需求（面积小、学区差、通勤远），建议换房而非投资；二、投资回报分析，房产投资年化回报约3%-5%（租金+增值），低于部分理财产品但相对稳定；三、风险对比，房产流动性差、交易成本高，金融资产流动性好但波动大；四、组合策略，卖房款部分用于换房改善居住，部分用于金融投资分散风险；五、时机判断，如当地房价处于高位且有回落风险，","legalRef":"《中华人民共和国民法典》第五百九十五条（买卖合同定义）","consumerBenefit":"帮业主权衡换房与投资，做出理性决策。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"道","meetingPhase":["见前"]},"alias":["换房还是投资","卖房后买什么","换房还是理财"]},{"id":"OWN-SLR-047","name":"卖房时机与市场周期","domain":"业主资产","subScene":"资产优化","scene":"业主资产·资产优化","cq":"业主问：怎么判断房产市场周期？什么时候是卖房好时机？","ola":"关注量价关系和政策信号。","cp":["关注量价关系","政策放松是信号","量缩价涨是卖点"],"detail":"房产市场周期判断方法：一、量价关系，成交量连续3个月上升且价格开始上涨，进入上升期适合卖房；成交量持续下降但价格仍涨，接近顶部需警惕；二、政策信号，限购放松、利率下调、税费减免等利好政策出台后市场通常回暖，是卖房窗口期；三、供需关系，关注当地二手房挂牌量变化，挂牌量减少说明供给收缩有利于卖方；四、经济周期，经济上行期收入预期改善购房需求增加，适合卖房；五、区域因素，","legalRef":"《中华人民共和国民法典》第五百九十五条（买卖合同定义）","consumerBenefit":"帮业主判断市场周期，把握卖房时机。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"道","meetingPhase":["见前"]},"alias":["卖房时机市场周期","房产周期","什么时候卖房"]},{"id":"OWN-SLR-048","name":"卖房后税务规划","domain":"业主资产","subScene":"资产优化","scene":"业主资产·资产优化","cq":"业主问：卖房后有什么税务优化方式？能省多少税？","ola":"满二免增值税，满五唯一免个税。","cp":["换购住房可退个税","满五唯一免个税","满二免增值税"],"detail":"卖房税务规划方式：一、满二免增值税，持有满2年的住房出售免征增值税（3%征收率），不满2年需全额缴纳，差额可达数万；二、满五唯一免个税，家庭唯一住房持有满5年出售免征个人所得税（差额20%或总价1%），是最优出售时机；三、换购住房退税，出售自有住房后1年内在同一城市重新购买住房的，可申请退还已缴纳的个人所得税，新购金额大于等于售房金额的全退，小于的按比例退；四、合理确定扣除项目，","legalRef":"财政部 税务总局公告2025年第17号（个人销售住房增值税政策）","consumerBenefit":"帮业主合法节税，最大化卖房收益。","tags":{"clientType":["seller"],"stage":"pre,mid,post","layer":"法","meetingPhase":["见前"]},"alias":["卖房后税务","卖房税务规划","卖房退税"]},{"id":"P3-A2-005","name":"公积金贷款利率和额度是多少","domain":"法规政策","subScene":"调控政策","scene":"法规政策·调控政策","cq":"客户问：公积金贷款利率和额度是多少？","ola":"首套公积金利率2.6%，额度各地不同50至120万。","cp":["首套公积金利率2.6%","二套公积金利率2.85%","贷款额度各地差异较大"],"detail":"2026年公积金贷款首套利率为2.6%，二套利率2.85%，显著低于商业贷款利率。公积金贷款额度由各城市根据缴存年限、账户余额和房价等因素综合确定，单缴存人一般50万至80万，双缴存人80万至120万，部分高房价城市额度更高。公积金贷款与商贷组合使用可有效降低月供压力。","legalRef":"住房城乡建设部 财政部 中国人民银行2026年通知","consumerBenefit":"帮客户利用公积金低利率优势，最大限度节省贷款利息。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["公积金首套利率2.6%吗","公积金贷款额度上限","公积金贷款最新政策"]},{"id":"P3-A2-009","name":"认房不认贷怎么理解","domain":"法规政策","subScene":"调控政策","scene":"法规政策·调控政策","cq":"客户问：认房不认贷怎么理解？","ola":"认房不认贷即只看名下有无住房，不看历史贷款记录。","cp":["名下无房即按首套贷款执行","不再追溯历史贷款记录","换房族大幅降低利率和首付"],"detail":"认房不认贷政策核心是将首套房认定标准从「认房又认贷」调整为「只认房」。即只要购房家庭名下无住房，无论此前是否有过贷款记录，均可按首套房享受低首付和低利率。该政策已在全国大部分城市推行，对卖旧买新的换房族最为利好，可从二套利率3.45%降至首套3.05%，月供明显减少。","legalRef":"住房城乡建设部 中国人民银行 金融监管总局2023年通知","consumerBenefit":"帮换房客户利用认房不认贷政策享受首套优惠，降低贷款成本。","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["认房不认贷是什么意思","卖掉旧房再买算首套吗","认房不认贷适用条件"]},{"id":"P3-A2-010","name":"限贷政策有哪些最新变化","domain":"法规政策","subScene":"调控政策","scene":"法规政策·调控政策","cq":"客户问：限贷政策有哪些最新变化？","ola":"首付和利率全面下调，贷款审批放宽，首套首付15%二套25%。","cp":["首套首付降至15%","二套首付降至25%","贷款审批标准适度放宽"],"detail":"2026年限贷政策显著放松，首套首付由20%至30%降至15%，二套首付由30%至40%降至25%。商贷利率首套下限3.05%，二套3.45%。同时银行适度放宽贷款审批条件，对收入还贷比的要求有所松动，灵活就业人员贷款门槛降低。限贷放松旨在激活住房消费，但购房者仍需评估自身还款能力避免过度负债。","legalRef":"中国人民银行 银保监会2026年第8号公告","consumerBenefit":"帮客户把握限贷放松的红利，在能力范围内争取最优贷款。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["限贷政策2026调整","房贷政策最新变化","限贷放松了吗"]},{"id":"P3-A2-013","name":"公积金提取条件有哪些","domain":"法规政策","subScene":"调控政策","scene":"法规政策·调控政策","cq":"客户问：公积金提取条件有哪些？","ola":"购房、还贷、租房、退休等均可提取公积金，各地条件略有差异。","cp":["购房和偿还贷款可提取","租房可按月或按年提取","退休和离职可全额提取"],"detail":"住房公积金提取条件主要包括：购买自住住房、建造翻建大修自住住房、偿还购房贷款本息、支付房租、退休、完全丧失劳动能力并与单位终止劳动关系、出境定居等。其中租房提取在部分城市已大幅放宽，无需提供租房合同即可按月或按年提取，提取额度为每月1500元至3000元不等。各地具体条件以当地公积金中心规定为准。","legalRef":"《住房公积金管理条例》第二十四条","consumerBenefit":"帮客户了解公积金提取用途，合规使用公积金减轻住房负担。","tags":{"clientType":["buyer","tenant"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["公积金怎么提取","租房可以提公积金吗","公积金提取用途限制"]},{"id":"P3-A3-001","name":"买二手房要交多少契税","domain":"法规政策","subScene":"税费法规","scene":"法规政策·税费法规","cq":"客户问：买二手房要交多少契税？","ola":"首套140㎡以下1%以上1.5%，二套140㎡以上2%。","cp":["首套140平以下契税1%","首套140平以上契税1.5%","二套140平以上契税2%"],"detail":"2026年契税政策：首套住房面积140平方米及以下的税率为1%，140平方米以上的为1.5%。二套住房面积140平方米及以下的税率为1%，140平方米以上的为2%。三套及以上不享受优惠，统一按3%至5%的法定税率执行。契税以房屋成交价或评估价孰高为计税依据。家庭住房套数以不动产登记为准按家庭单位认定。","legalRef":"《中华人民共和国契税法》第三条","consumerBenefit":"帮客户精确计算契税金额，做好购房税费预算。","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["契税怎么算2026","首套房契税多少","二套房契税税率"]},{"id":"P3-A3-019","name":"直系亲属赠与房产要交什么税","domain":"法规政策","subScene":"税费法规","scene":"法规政策·税费法规","cq":"客户问：直系亲属赠与房产要交什么税？","ola":"直系赠与免征个税，契税3%，但再出售时个税按差额20%较重。","cp":["直系赠与免征个人所得税","契税按3%缴纳无优惠","再出售时个税按差额20%"],"detail":"直系亲属间赠与房产，免征增值税和个人所得税，但契税按3%缴纳不享受1%至2%的优惠税率。赠与过户的房产再次出售时，个人所得税按差额20%征收，不能适用1%核定征收。因此短期内有出售计划的房产不建议走赠与途径，买卖过户综合税费可能更低。建议在赠与和买卖两种方式间逐一计算总税费后再做决定。","legalRef":"《中华人民共和国契税法》第六条","consumerBenefit":"帮客户在赠与和买卖之间算清税费总账，选择最省钱的过户方式。","tags":{"clientType":["seller","buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["父母赠与子女房产税费","直系亲属赠与免契税吗","赠与房产要交个税吗"]},{"id":"P3-A4-021","name":"租房不签书面合同有效吗","domain":"法规政策","subScene":"租赁法规","scene":"法规政策·租赁法规","cq":"客户问：租房不签书面合同有效吗？","ola":"租赁期限六个月以上未签书面合同的，视为不定期租赁。","cp":["六个月以上须签书面合同","未签则视为不定期租赁","不定期双方可随时解除"],"detail":"租赁期限六个月以上的应当采用书面形式。未采用书面形式的，无论双方口头约定多长期限，法律上均视为不定期租赁。不定期租赁中，双方均可随时解除合同，但出租人解除合同应在合理期限之前通知承租人。不签书面合同还会导致押金退还、维修责任等争议缺乏证据，建议无论租期长短均签订书面合同。","legalRef":"《中华人民共和国民法典》第七百零七条","consumerBenefit":"帮租客和房东避免不签合同的法律风险，保障双方权益。","tags":{"clientType":["tenant","landlord"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["口头租房协议有效吗","不签租赁合同有什么风险","租赁合同必须书面吗"]},{"id":"P3-A4-022","name":"租房合同要不要去备案","domain":"法规政策","subScene":"租赁法规","scene":"法规政策·租赁法规","cq":"客户问：租房合同要不要去备案？","ola":"租赁备案非强制但建议办理，关系到居住证、入学和个税抵扣。","cp":["备案非合同生效的必要条件","办理居住证和入学需备案","住房租金个税抵扣需备案"],"detail":"房屋租赁合同签订后是否备案不影响合同本身的效力，但备案对承租人有多项实际利益：办理居住证通常需提供租赁备案证明，子女入学登记需备案材料，住房租金个人所得税专项附加扣除需要备案编号。办理备案需携带租赁合同、身份证明和房产证明到当地房管部门或社区服务中心，部分地区支持线上备案。","legalRef":"《商品房屋租赁管理办法》第十四条","consumerBenefit":"帮租客了解备案的实际用途，主动办理保障多项权益。","tags":{"clientType":["tenant","landlord"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["租赁备案有什么用","房屋租赁不备案违法吗","租房备案怎么办理"]},{"id":"D16-063","name":"改善家庭有什么画像特征和换房需求？","domain":"社区服务与运营","subScene":"家庭画像与需求预判","scene":"社区服务与运营·家庭画像与需求预判","cq":"客户问：我们想换个大点的房子，你们有什么建议？","ola":"改善家庭核心诉求是面积升级、品质提升和配套完善","cp":["升级动机：画像特征：年龄30-45岁为主","换房需求：换房动机通常为二孩出生空间不足","时序管理：先卖后买还是先买后卖","过渡服务：服务改善家庭时"],"detail":"改善家庭指已有一套住房但因家庭变化或收入提升而需要换更大或更好住房的家庭。画像特征：年龄30-45岁为主，家庭收入中等偏上，已有一套住房且有房贷或已还清，换房动机通常为二孩出生空间不足、老人同住需要更多房间、收入提升后追求更高品质社区、或对当前户型/物业/学区不满意。换房需求分三种类型：同小区大户型置换（成本最低、社区不变）、跨小区品质升级（追求更好物业/环境/配套）、学区+改善双重需求（同时解决教育和居住品质问题）。时序管理是改善家庭最核心的痛点：先卖后买资金压力小但过渡期需租房，先买后卖居住不中断但资金压力大，二套房首付比例和贷款政策也需提前了解。服务改善家庭时，除了匹配房源外，还需协调旧房出售/出租、过渡期居住安排、新房装修对接、孩子转学等系列服务。关键是帮客户算清换房成本账，包括税费、中介费、装修费、过渡租金等。","legalRef":"无","consumerBenefit":"帮客户规划改善换房全流程","tags":{"clientType":["buyer","seller"],"stage":"all","layer":"术","meetingPhase":["见前"]},"alias":["换大房子的家庭","改善型住户画像","升级换房需求"]},{"id":"D16-069","name":"社区发生重大事件时如何捕捉触发的家庭需求？","domain":"社区服务与运营","subScene":"家庭画像与需求预判","scene":"社区服务与运营·家庭画像与需求预判","cq":"客户问：小区最近发生的事对我们有什么影响？","ola":"关注物业更换、学区调整、周边拆迁、公共设施变化等事件","cp":["物业事件：物业费涨价","政策事件：政策类事件包括学区划分调整","环境事件：环境类事件包括周边工地施工","设施事件：设施类事件包括电梯频繁故障"],"detail":"社区事件触发需求是需求预判中时效性最强、转化率最高的一类。社区重大事件按类型分为四类：物业类事件包括物业更换、物业费涨价、服务质量下降等，直接影响业主居住体验，可能触发集体维权、投诉或出售搬离需求，需主动安抚并协调解决渠道。政策类事件包括学区划分调整、限购政策变化、公积金政策调整等，直接影响房产价值和交易决策，需第一时间解读政策影响并推送给相关家庭。环境类事件包括周边工地施工、道路开挖、垃圾站新建、商业体开业等，影响居住舒适度和房产价值，需评估正负面影响并主动告知。设施类事件包括电梯频繁故障、供水管网老化、外墙脱落等，影响居住安全和品质，需协调维修并评估是否触发改善换房需求。捕捉社区事件的关键是建立信息收集网络：物业公告栏、业主微信群、社区居委会、周边商户都是信息源。事件发生后24小时内须完成影响评估并制定触达计划，72小时内完成相关家庭的主动沟通。","legalRef":"无","consumerBenefit":"帮客户及时应对社区变化影响","tags":{"clientType":["buyer","landlord","seller","tenant"],"stage":"all","layer":"术","meetingPhase":["见前"]},"alias":["社区事件引发什么需求","突发事件怎么预判需求","社区变化触发需求"]},{"id":"D16-072","name":"装修会触发哪些关联家庭需求？","domain":"社区服务与运营","subScene":"家庭画像与需求预判","scene":"社区服务与运营·家庭画像与需求预判","cq":"客户问：我们要装修房子，社区这边有什么需要注意的？","ola":"装修触发施工协调、临时居住、建材采购、邻里告知","cp":["施工协调：安排装修垃圾清运","临时居住：家庭需安排过渡住所","资源对接：服务者可对接短租资源和仓储服务","邻里管理：建议开工前逐户告知邻居"],"detail":"装修是社区家庭的高频需求场景，本身即是一项大工程，同时会触发一系列关联需求。施工协调是第一个必须处理的环节：须向物业报批装修方案、遵守施工时间规定（通常工作日8:00-18:00）、安排装修垃圾清运、协调货梯使用时段，避免因违规施工被叫停。临时居住需求往往被低估：装修周期通常2-4个月，家庭需安排过渡住所，可能是同小区/附近短租、住酒店或借住亲友家，同时需要家具家电仓储服务，服务者可对接短租资源和仓储服务。资源对接是装修的核心需求：推荐靠谱装修公司（须核实资质）、建材采购指导（价格对比和品质把关）、智能家居方案设计（灯光、安防、影音系统）、装修预算控制（帮客户建立预算表并跟踪支出）。邻里管理是装修中最容易被忽视的环节：装修噪音和粉尘影响邻居体验，建议开工前逐户告知邻居、张贴装修公告、预留联系方式处理投诉、完工后送小礼物致歉修复关系。验收阶段还需对接甲醛检测治理、开荒保洁、甲醛清除等服务。","legalRef":"无","consumerBenefit":"帮客户顺利完成装修全流程","tags":{"clientType":["seller","buyer","tenant"],"stage":"all","layer":"术","meetingPhase":["见前"]},"alias":["装修时要准备什么","装修触发需求","装修关联服务需求"]},{"id":"D16-080","name":"如何判断社区是否在年轻化？年轻化社区服务怎么调整？","domain":"社区服务与运营","subScene":"家庭画像与需求预判","scene":"社区服务与运营·家庭画像与需求预判","cq":"客户问：这个小区年轻人多不多？氛围怎么样？","ola":"通过新房交付、租客涌入、二胎政策后换房三个信号判断年轻化","cp":["判断：租客平均年龄逐年下降","服务调整：兴趣社群","设施优化：设施优化上增设儿童活动区","商业适配：如咖啡店"],"detail":"社区年轻化是近年来部分社区出现的趋势，通常由三种原因驱动：一是新建小区交付后首批业主多为年轻家庭，二是老旧小区因交通便利或租金低廉吸引年轻租客涌入，三是优质学区或产业聚集区吸引年轻家庭置换入住。判断指标包括：35岁以下住户占比连续两年上升、社区内新生儿家庭增长率高于区域平均水平、租客平均年龄逐年下降、社区快递量显著增长（年轻人网购频率高）。年轻化社区的服务策略须做相应调整：社交层面增加社区联谊、兴趣社群、运动赛事等活动，满足年轻人的社交需求；育儿层面对接早教机构、亲子活动、托育服务等资源，服务大量学龄前家庭；宠物层面建立宠物友好设施和服务体系，应对养宠家庭增多；品质生活层面引入咖啡外卖、健身私教、生鲜配送、智能家居等品质化服务。设施优化上增设儿童活动区、室外健身器材、智能快递柜、社区共享空间（共享书吧、共享厨房等）。商业配套方面推动社区商业引入年轻化业态，如咖啡店、便利店、母婴店、宠物店、轻食沙拉店等，提升社区生活品质吸引力。","legalRef":"无","consumerBenefit":"帮客户了解社区年轻化趋势及活力","tags":{"clientType":["buyer","landlord","seller","tenant"],"stage":"all","layer":"术","meetingPhase":["见前"]},"alias":["小区年轻人多不多","社区年轻化趋势","年轻住户增多怎么办"]},{"id":"PRE-RISK-054","name":"学区政策变了房子还保值吗","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"听说学区政策要变多校划片了，我买的学区房还能保值吗？","ola":"学区政策调整会削弱学区溢价，保值性受多重因素影响。","cp":["学区政策变动削弱溢价","多校划片降低入学确定性","房产保值回归居住属性","签约前需评估政策风险"],"detail":"学区房的价值高度依赖教育政策。若实行“多校划片”或“教师轮岗”，单一学区房的确定性降低，学区溢价会被稀释，短期内可能面临贬值风险。但房产的整体保值性还受地段、交通、商业配套及房屋品质等核心居住属性影响。签约前需充分评估政策变动对房屋流动性和价格预期的冲击，切勿盲目为学区溢价买单。","legalRef":"行业通行做法（学区划分由教育行政部门动态调整）","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"器","meetingPhase":["见后"]},"alias":["学区房政策变了还保值吗","学区划分调整房子贬值吗","多校划片学区房还值钱吗"]},{"id":"OWN-TNT-CASE-037","name":"租客提前退租房东未采取减损措施扩大的损失法院怎么判？","domain":"资产持有与运营","subScene":"租客纠纷应对","scene":"资产持有与运营·租客纠纷应对","cq":"我提前退租了，房东房子空置半年的租金都要我赔吗？","ola":"房东需减损，扩大的空置损失法院不支持。","cp":["房东负有防止损失扩大的法定义务","故意空置或抬高租金属未减损","扩大的损失法院不支持租客承担","合理招租期通常为15天至2个月"],"detail":"租客违约提前退租，房东虽有权主张违约金及空置期租金，但依法负有“防止损失扩大”的义务。判例显示，若租客明确搬离并交还钥匙后，房东故意将房屋长期空置、拒绝重新出租，或故意抬高租金导致房屋无法租出，法院会认定房东未采取适当措施致使损失扩大。对于扩大的损失（如超出合理招租期的空置租金），法院不予支持由租客承担。合理招租期通常根据当地市场情况认定为15天至2个月不等。","legalRef":"《中华人民共和国民法典》第五百九十一条","consumerBenefit":"了解房东的减损义务，避免承担不合理的长期空置租金。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见后"]},"alias":["租客退租后房子空置房东能要全部租金吗","房东未及时重新出租扩大的损失法院怎么判","租客违约退租房东有减损义务吗"]},{"id":"OWN-SLD-CASE-051","name":"业主卖房时房屋有户口如何办理户口迁出手续","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"买房后原房东的户口怎么让他迁走？","ola":"准备迁入地证明，向辖区派出所申请户口迁移。","cp":["提前确认户口迁入地","准备迁入地接收证明材料","向辖区派出所提交迁移申请","按合同约定时间完成迁出"],"detail":"业务场景：业主出售的房屋内留有本人或亲属户口，合同约定过户后需迁出，业主需办理户口迁移。判断要点：户口迁出是二手房交易的重要环节，逾期可能面临违约金。关键决策因素：是否有迁入地接收、当地派出所户籍政策、迁出时间节点。业主需提前准备迁入地房产证或单位集体户口接收证明，向派出所申请迁移。","legalRef":"《中华人民共和国户口登记条例》第十条，公民迁出本户口管辖区，由本人或者户主在迁出前向户口登记机关申报迁出登记，领取迁移证件，注销户口。","consumerBenefit":"确保买家顺利落户，避免户口纠纷。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见中","见后"]},"alias":["卖房户口迁出流程","二手房户口怎么迁走","卖房后户口迁移手续"]},{"id":"SNG-TAX-097","name":"名下有房但已卖掉，再买房算首套还是二套契税？（SNG-TAX）","domain":"签约交易","subScene":"税费计算","scene":"签约交易·税费计算","cq":"我之前的房子卖了，现在买新房契税能按首套交吗？","ola":"看当地认房认贷政策及房贷是否结清。","cp":["认房城市无房即算首套","认贷城市看全国房贷记录","贷款结清与否影响认定","必须结合征信报告判断","切勿仅凭无房证明承诺"],"detail":"在认房城市，名下无房即算首套；但在认房又认贷城市，若之前买房用过贷款且未结清，再买房仍算二套。行动建议：必须结合当地最新认房认贷政策及客户征信报告综合判断。风险提示：切勿仅凭名下无房证明就承诺首套契税，若客户有未结清房贷，将导致契税从1%涨至2%或3%。","legalRef":"《中国人民银行 中国银行业监督管理委员会关于进一步完善差别化住房信贷政策有关问题的通知》（银发〔2016〕265号）","consumerBenefit":"精准匹配信贷与税收政策，避免首套变二套的契税损失。","tags":{"clientType":["buyer"],"stage":"mid","layer":"术","meetingPhase":["见中"]},"alias":["卖过房算首套吗","无房证明算首套吗","卖旧买新契税认定"]},{"id":"P1-A4-001","name":"租期内房屋维修该谁出钱","domain":"法规政策","subScene":"租住·租期内服务","scene":"法规政策·租住·租期内服务","cq":"租的房子坏了该谁出钱修？","ola":"自然老化房东修，人为损坏租客修，入住拍照留证","cp":["自然老化房东修","人为损坏租客修","入住拍照留证","紧急维修不拖延","合同约定优先"],"detail":"租期内维修责任划分：①自然老化/结构问题（水管老化/墙皮脱落/门窗变形）→房东负责维修费用 ②租客人为损坏（打孔/烫伤地板/宠物咬坏）→租客负责维修费用 ③家电维修→合同约定优先；无约定则自然损坏房东修，人为损坏租客修 ④维修流程→租客通知房东→房东3-7天内安排维修→维修后租客确认→费用按责任归属承担。实操建议：入住时拍照记录房屋状况并附在合同中，作为责任划分依据。","legalRef":"《中华人民共和国民法典》第七百一十二条（出租人维修义务）、第七百一十三条（承租人自行维修后求偿）","consumerBenefit":"明确维修责任，房东租客都不扯皮","tags":{"clientType":["tenant","landlord"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["租期内维修","出租房维修责任","租房维修谁出钱"]},{"id":"D16-051","name":"如何分析楼盘的住户类型？","domain":"社区服务与运营","subScene":"楼盘管理与销控","scene":"社区服务与运营·楼盘管理与销控","cq":"客户问：这个小区住的都是什么人？邻居都是做什么的？","ola":"通过亮灯时段、物业访谈、装修风格推断住户类型","cp":["原住民：回迁户或早期业主","置换改善：中年家庭为主，注重生活品质","投资客：空置率高，不参与社区活动","租客比例：过高的租客比影响社区稳定性"],"detail":"住户类型分析是判断社区氛围的重要维度。四大类型：原住民，包括回迁户和早期购房业主，通常生活节俭、社区归属感强、参与社区事务积极，但可能与新业主生活习惯有差异；置换改善客，中年家庭为主，注重生活品质和子女教育，是社区消费和服务的主力；投资客，购房后空置或出租，不参与社区活动，比例过高会削弱社区凝聚力；租客，流动性大、参与度低，租客占比超过40%的社区通常居住氛围较弱。分析方法：通过晚间亮灯时段（早亮多为家庭、晚亮多为年轻租客）、物业访谈（物业对住户画像最了解）、装修风格（简装多为出租、精装多为自住）等途径推断。住户类型对客户的价值在于：邻里圈层影响居住体验和房产价值。","legalRef":"无","consumerBenefit":"帮客户判断社区邻里圈层与居住氛围","tags":{"clientType":["buyer","tenant"],"stage":"all","layer":"术","meetingPhase":["见中"]},"alias":["小区住的都是什么人","小区住户类型怎么分","这小区业主什么群体"]},{"id":"D16-134","name":"社区证明怎么开具？","domain":"社区服务与运营","subScene":"便民服务","scene":"社区服务与运营·便民服务","cq":"客户问：我需要开一个社区居住证明，怎么办理？","ola":"携带身份证和居住材料到社区居委会或物业申请开具","cp":["明确客户需要开具的证明类型和用途","准备对应材料：身份证、房产证或租房合同等","办理地点：社区居委会或物业服务中心","部分证明需民警签字，需预留额外办理时间"],"detail":"社区证明开具是居民日常办事的常见需求。常见证明类型包括居住证明、无业证明、困难证明、亲属关系证明等，不同证明的办理要求和流程有所不同。办理前要帮客户明确需要什么证明、用途是什么，因为不同用途需要的证明格式和盖章要求不同。居住证明是最常见的类型，一般携带身份证和房产证或租房合同到社区居委会或物业即可开具。部分证明如户籍证明需要民警签字确认，办理时间会更长。建议提醒客户提前确认用证单位对证明格式的具体要求，避免开具后格式不符需要重新办理。部分社区已开通线上开具功能，可通过社区APP或政务网申请，邮寄或自行打印。开具的证明一般有有效期，建议客户按需开具，避免过期作废。","legalRef":"《居民委员会组织法》","consumerBenefit":"帮客户快速开具所需社区证明","tags":{"clientType":["buyer","landlord","seller","tenant"],"stage":"all","layer":"法","meetingPhase":["见后"]},"alias":["社区证明开具流程","居住证明怎么开","社区证明怎么办"]},{"id":"OWN-RNT-DEEP-009","name":"出租房发生安全事故房东责任怎么认定","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"出租房出安全事故，我受伤了房东赔吗？","ola":"房屋隐患致害房东赔，使用不当租客担责。","cp":["告诉业主房东安全责任边界","建议业主"],"detail":"本词条涉及出租管理领域的RISK类问题。告诉业主房东安全责任边界：1.交付时房屋必须安全可用 2.因房屋本身安全隐患致害→房东担责 3.因租客使用不当致害→租客自担 4.因第三方原因致害→第三方担责。建议业主：1.出租前做安全检查(燃气/电。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第七百零八条、第一千一百六十五条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["租房出事房东赔吗","房东安全责任认定","出租房出事谁负责"]},{"id":"CRO-GEN-010","name":"单身一个人买房怎么选","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我一个人住，买什么房子合适","ola":"地铁旁小户型月供可控未来好转手","cp":["通勤便利是第一优先","面积够用避免浪费","关注未来转手流动性","月供不超过收入一半"],"detail":"单身置业需重点考虑通勤便利性（地铁沿线）、面积够用不浪费（一居小两居为主）、未来转手流动性（小户型易出手）、月供压力可控（不超过月收入50%）。经纪人应引导单身客户关注持有成本和未来换房的灵活性。","legalRef":"行业通行做法","consumerBenefit":"住得方便，未来换房不亏","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["单身买房怎么选","一个人买房建议","单身购房要点"]},{"id":"CRO-GEN-012","name":"投资买房和自住有什么不同","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"买房投资和自住区别大吗","ola":"投资看增值回报自住看体验便利","cp":["投资看增值和租金回报","自住看体验和生活便利","投资关注规划利好","目的不同选房逻辑不同"],"detail":"投资买房侧重增值潜力和租金回报率，关注城市规划、地铁新线、产业导入等利好因素；自住买房侧重居住体验和生活便利，关注户型采光物业通勤等日常要素。经纪人需明确客户主要目的，避免用自住标准选投资房或反之。","legalRef":"行业通行做法","consumerBenefit":"选房逻辑匹配目的，不花冤枉钱","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["投资房和自住房区别","买房投资看什么","投资房产怎么选"]},{"id":"CRO-GEN-014","name":"经纪人分几个等级","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"你们经纪人分几个等级","ola":"基础进阶高级三层能力逐级提升","cp":["基础层：标准化流程执行","进阶层：专业判断方案设计","高级层：体系搭建复杂解决","层级越高服务能力越强"],"detail":"房地产经纪人按能力水平分为基础执行层、进阶专业层、高级战略层三个层级，分别对应标准化操作、专业判断与方案设计、体系搭建与复杂问题解决。职级越高，能处理的交易复杂度越高，服务客户类型越广。","legalRef":"行业通行做法","consumerBenefit":"找对等级的经纪人，服务更匹配需求","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["经纪人级别","房产经纪人有几种","经纪人职级体系"]},{"id":"CRO-GEN-016","name":"经纪人能帮我做哪些事","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"你们经纪人到底能帮我做什么","ola":"从找房到过户交房全流程服务","cp":["买方：从需求到售后全流程","卖方：从委托到交房全服务","通用：市场分析风险把控","核心：信息对称降低交易成本"],"detail":"经纪人服务贯穿交易全流程：买方服务包括需求诊断、房源匹配、带看讲解、谈判签约、交易执行、售后维护；卖方服务包括委托签约、房源推广、买家筛选、议价支持、交房协助。通用服务还包括市场分析、风险把控、政策解读。","legalRef":"行业通行做法","consumerBenefit":"清楚服务边界，知道什么时候找经纪人","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["经纪人服务范围","经纪人干什么","经纪人的工作内容"]},{"id":"CRO-GEN-017","name":"好经纪人有什么标准","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"什么样的经纪人才算好经纪人","ola":"沟通分析法律风控细节服务六项全能","cp":["沟通：倾听提问化解矛盾","分析：数据解读政策掌握","法律：合同解读风险规避","风控：预判风险设计方案"],"detail":"优秀经纪人需具备沟通能力（倾听提问化解矛盾）、市场分析能力（数据解读政策掌握）、法律知识（合同解读风险规避）、风控能力（预判风险设计方案）、细节管理（流程把控信息记录）、服务意识（主动跟进长期维护）六项核心胜任力。","legalRef":"行业通行做法","consumerBenefit":"知道好经纪人长什么样，选人不走眼","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["优秀经纪人标准","经纪人胜任力","怎么算好经纪人"]},{"id":"CRO-GEN-019","name":"经纪人需要什么资格证","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"你们当经纪人需要什么证吗","ola":"须通过全国统考取得经纪资格证","cp":["须通过全国统一资格考试","分经纪人和经纪人协理两级","无证执业属于违规行为","资格证书需定期继续教育"],"detail":"房地产经纪人员分为房地产经纪人和房地产经纪人协理两个级别，均需通过全国统一资格考试取得相应资格证书。《房地产经纪管理办法》第7条明确规定了经纪人员的资格条件。无证从事房地产经纪活动属于违规行为。","legalRef":"《房地产经纪管理办法》第7条","consumerBenefit":"确认经纪人持证，服务有专业保障","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["道"],"meetingPhase":["见前"]},"alias":["经纪人资格证怎么考","房产经纪人资质","经纪人执业证"]},{"id":"CRO-GEN-025","name":"买房遇到纠纷有哪些维权途径","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"买房遇到纠纷了，怎么维权","ola":"和解调解仲裁诉讼四种途径逐步升级","cp":["和解：双方自愿协商","调解：第三方居中协调","仲裁：一裁终局效率高","诉讼：法院判决强制执行"],"detail":"物权受到侵害的，权利人可通过和解、调解、仲裁、诉讼四种法定途径解决纠纷。《民法典》第233条明确了多元化纠纷解决机制。实践中建议先协商调解，协商不成可向住建部门投诉或申请仲裁，最终可向人民法院提起诉讼。","legalRef":"《中华人民共和国民法典》第233条","consumerBenefit":"遇到纠纷知道怎么维权，不慌不乱","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["道"],"meetingPhase":["见前"]},"alias":["买房纠纷怎么维权","房产纠纷维权方式","买房纠纷解决途径"]},{"id":"CRO-GEN-034","name":"房子值多少钱怎么估算","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"这房子值多少钱，怎么估算","ola":"对比同小区近期成交价加楼层朝向修正","cp":["市场比较法最常用最直观","对比同小区近期成交价","楼层朝向装修需修正","给出估值区间而非单一价格"],"detail":"房产估值常用市场比较法（对比同小区近期成交价）、成本法（土地价值+建筑折旧）、收益法（租金回报率反推）三种方法。经纪人应调取同小区3-6个月内成交数据作为定价参考，结合楼层朝向装修等修正系数给出合理估值区间。","legalRef":"行业通行做法","consumerBenefit":"出价有依据，不买贵也不卖亏","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["法"],"meetingPhase":["见前"]},"alias":["房产估值方法","房子值多少怎么判断","房价怎么评估"]},{"id":"CRO-GEN-043","name":"公摊面积到底是怎么算出来的","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"买房时售楼部说的公摊面积是怎么算出来的？","ola":"套内面积乘以整栋楼的公摊系数得出。","cp":["公摊包含电梯井楼梯间","套内面积乘公摊系数","外墙一半算入公摊","独立使用的地下室不算"],"detail":"公摊面积是指由整栋楼的产权人共同所有的整栋楼公用部分的建筑面积。计算公式为：公摊面积 = 套内建筑面积 × 公摊系数。公摊系数 = 总公共部位建筑面积 / 总套内建筑面积。公摊部分通常包括电梯井、管道井、楼梯间、垃圾道、变电室、设备间、公共门厅、过道、地下室、值班警卫室等，以及套与公共建筑之间的分隔墙和外墙水平投影面积的一半。","legalRef":"《房产测量规范》国家标准","consumerBenefit":"掌握计算方法，在购房时核对公摊数据是否合理。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"法","meetingPhase":["见中","见前"]},"alias":["公摊面积计算方式","买房公摊面积包含哪些","公摊面积合理范围是多少"]},{"id":"CRO-GEN-044","name":"买房得房率多少才算不亏","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我看中的房子得房率只有75%，是不是太亏了？","ola":"高层75%左右正常，过高反而影响居住品质。","cp":["得房率并非越高越好","高层得房率75%至80%适宜","过低影响使用面积","过高牺牲公共舒适度"],"detail":"得房率是指可供住户支配的面积（即套内建筑面积）与每户建筑面积（即销售面积）之间的比例。得房率并非越高越好，过低意味着公摊大、实际使用面积小；过高则可能压缩公共空间，导致电梯厅狭窄、楼道昏暗，影响居住舒适度。通常情况下，多层住宅得房率在85%-90%左右，小高层在80%-85%，高层在75%-80%较为合适。购房时需结合小区整体品质综合考量。","legalRef":"行业通行做法","consumerBenefit":"建立合理预期，避免盲目追求高得房率而牺牲居住体验。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"法","meetingPhase":["见中","见前"]},"alias":["得房率多少正常","得房率越高越好吗","高层住宅得房率标准"]},{"id":"CRO-GEN-047","name":"房屋维修基金什么情况下能申请使用","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"小区电梯坏了，物业说要动用维修基金，这钱我能用吗？","ola":"用于保修期满后的公共设施和部位维修。","cp":["用于保修期满后的共用部位","需双三分之二业主参与表决","紧急情况可走绿色通道","余额不足需续交"],"detail":"住宅专项维修资金是指专项用于住宅共用部位、共用设施设备保修期满后的维修和更新、改造的资金。共用部位包括屋顶、外墙、楼梯间等；共用设施设备包括电梯、消防设施、绿地、道路等。使用时需由物业或业委会提出方案，经专有部分面积占比三分之二以上的业主且人数占比三分之二以上的业主参与表决，并经参与表决专有部分面积过半数且参与表决人数过半数的业主同意。紧急情况下（如电梯故障、外墙脱落），可走绿色通道直接申请。","legalRef":"《中华人民共和国民法典》第281条","consumerBenefit":"了解动用门槛，有效监督维修资金的使用。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"道","meetingPhase":["见中","见前"]},"alias":["维修基金怎么提取","房屋维修基金使用条件","屋顶漏水能用维修基金吗"]},{"id":"CRO-GEN-048","name":"小区地下车位的产权到底归谁","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"开发商让我买人防车位，这种车位有产权吗？","ola":"人防车位无产权，最长只能签20年租赁。","cp":["规划内车位归开发商","占用公共道路归全体业主","人防车位只能租不能买","买无产权车位实为租赁"],"detail":"小区车位产权归属需根据车位类型和规划性质来判定。建筑区划内，规划用于停放汽车的车位、车库的归属，由当事人通过出售、附赠或者出租等方式约定，通常开发商拥有初始产权。占用业主共有的道路或者其他场地用于停放汽车的车位，属于业主共有。人防工程改造的车位，产权归国家，投资者（通常为开发商）只有使用权，且使用权转让期限不得超过20年。购买无产权车位实质上是租赁。","legalRef":"《中华人民共和国民法典》第275条","consumerBenefit":"认清车位产权性质，避免花买产权的钱买了租赁权。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"术","meetingPhase":["见中","见前"]},"alias":["地下车位产权归属","人防车位能买吗","小区地面车位归谁"]},{"id":"CRO-GEN-051","name":"住宅和公寓到底有什么区别","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我想买个能落户带学区的房子，买公寓行不行？","ola":"住宅能落户带学区，公寓通常不能且生活成本高。","cp":["住宅70年产权可落户","公寓40年产权难落户","公寓水电按商用收费","公寓交易税费较高"],"detail":"住宅和公寓在土地性质、产权年限、落户政策及生活成本上存在显著差异。住宅通常为70年产权，可落户且带学区，水电按民用标准收费；公寓多为40或50年商业产权，一般不能落户，无学区，水电按商用标准收费，且交易税费较高。了解两者区别有助于购房者根据自身需求做出合理选择。","legalRef":"《中华人民共和国城镇国有土地使用权出让和转让暂行条例》第十二条","consumerBenefit":"明确房屋性质，避免买错导致无法落户或生活成本过高。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"术","meetingPhase":["见中","见前"]},"alias":["住宅公寓区别","买住宅好还是公寓好","公寓和住宅的不同点"]},{"id":"CRO-GEN-052","name":"买商住两用房有什么利弊","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"商住两用房能不能用公积金贷款买？","ola":"优势是不限购总价低，劣势是不能落户且生活成本高。","cp":["优势是不限购总价低","劣势是不能落户无学区","商水商电生活成本高","人员混杂居住体验差"],"detail":"商住两用房指既能办公又能居住的房屋，土地性质多为商业或综合用地。其优势在于不限购、总价低、地段通常较好；劣势在于产权年限短、不能落户、无学区、商水商电生活成本高、居住密度大且人员混杂、交易税费极高。适合单身过渡或小型办公，不建议作为家庭长期自住首选。","legalRef":"《中华人民共和国城市房地产管理法》第四十四条","consumerBenefit":"全面评估商住两用房的优缺点，避免盲目购买影响居住体验。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"术","meetingPhase":["见中","见前"]},"alias":["商住两用房优缺点","商住公寓能买吗","商住两用房子好不好"]},{"id":"CRO-GEN-056","name":"房子限售对卖房有什么影响","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我买的期房刚交房，产证刚办下来，能马上挂牌卖吗？","ola":"取证后需满规定年限才能卖，会延长房屋变现周期。","cp":["取证后需满年限方可交易","降低房产流动性变现难","抑制短期投机炒房行为","买前必须查清限售状态"],"detail":"限售政策是指新购住房在取得不动产权证后，需满一定年限方可上市交易的规定。其影响在于：一是延长房屋持有周期，降低房产流动性；二是增加资金占用成本，抑制短期投机炒房；三是稳定市场预期，防止房价大起大落。购房前必须查清目标房产是否处于限售期内，以免无法及时变现。","legalRef":"《中华人民共和国民法典》第二百一十四条","consumerBenefit":"了解限售规则，合理规划资金，避免买入后急需资金却无法出售。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"道","meetingPhase":["见中","见前"]},"alias":["限售政策是什么意思","房子被限售了怎么办","限售期是多久"]},{"id":"CRO-GEN-058","name":"买二套房首付一般要多少","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我准备买第二套房，首付需要准备百分之几十？","ola":"各地政策不同，通常在20%至40%之间，需咨询当地银行。","cp":["首付比例通常高于首套房","各地执行标准动态调整","二套房贷利率相应上浮","需备足资金防首付不足"],"detail":"二套房首付比例是指购买家庭名下第二套住房时，需支付的最低首付款占房屋总价的比例。该比例由央行及各地金融监管部门根据市场情况动态调整，通常在百分之二十至四十之间。二套房首付比例高于首套房，且房贷利率也会相应上浮。购房前需向当地银行确认最新执行标准，备足首付资金。","legalRef":"《中国人民银行 中国银行业监督管理委员会关于进一步做好住房金融服务工作的通知》","consumerBenefit":"提前了解二套房首付要求，合理筹备资金，避免购房违约。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"法","meetingPhase":["见中","见前"]},"alias":["二套房首付比例","二套房首付是多少","买第二套房要付多少首付"]},{"id":"CRO-GEN-061","name":"现在商业贷款利率大概是多少","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我现在去银行办房贷，利息大概是多少啊？","ola":"商贷利率以LPR为基准加点，各城各行政策不同。","cp":["以LPR为定价基准加点","首套和二套利率不同","各城市执行标准有差异","受个人征信资质影响"],"detail":"商业贷款利率是指商业银行向借款人发放房贷时收取的利息比率。目前房贷利率以LPR（贷款市场报价利率）为定价基准加点形成。不同城市、不同银行、不同客户资质（如首套或二套）的加点数值不同，导致实际执行利率存在差异。了解当前利率有助于评估购房成本和月供压力。","legalRef":"行业通行做法","consumerBenefit":"准确预估购房贷款成本，合理安排资金。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"术","meetingPhase":["见中","见前"]},"alias":["商贷利率多少","商业房贷利率","买房商贷利息"]},{"id":"CRO-GEN-072","name":"老人留下的房子怎么办理过户","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"父亲过世后留下一套房产，我们兄妹几个该怎么办理过户手续？","ola":"需先办理继承公证或诉讼，再凭文书去不动产中心过户。","cp":["先确认继承权归属","公证或诉讼二选一","备齐死亡及亲属证明","去不动产中心办登记"],"detail":"遗产房过户需先确认继承权。通常需所有法定继承人到公证处办理继承公证，或向法院提起诉讼取得生效法律文书，随后凭公证书或法院判决书、死亡证明、房产证等材料，到不动产登记中心办理转移登记。若有遗嘱，需先确认遗嘱效力。","legalRef":"《不动产登记暂行条例》第十四条","consumerBenefit":"明确继承过户的法定流程，避免家庭内部因手续不清产生纠纷。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"法","meetingPhase":["见中","见前"]},"alias":["继承房产过户流程","父母房子怎么过户给子女","遗产房过户手续"]},{"id":"CRO-GEN-084","name":"小区想成立业委会要怎么弄","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我们小区想自己成立业委会，第一步该干嘛？","ola":"满足条件后，联名向街道办提交成立申请。","cp":["满足条件向街道办申请","成立筹备组起草规约","召开首次业主大会选举","选举后向住建部门备案"],"detail":"成立业主委员会是小区业主实现自治、监督物业服务的重要法定程序。通常需满足交房满一定年限或入住率达标等条件，由业主联名向街道办提出书面申请。随后成立筹备组，起草管理规约和议事规则，召开首次业主大会选举产生业委会委员，并在当地住建部门备案。","legalRef":"《物业管理条例》第十条","consumerBenefit":"清晰了解业委会成立流程，推动小区实现业主自治。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"法","meetingPhase":["见中","见前"]},"alias":["怎么成立业主委员会","成立业委会的流程是什么","小区业委会申请条件"]},{"id":"EXT-INH-014","name":"离婚时房产怎么分","domain":"退租出售","subScene":"继承赠与","scene":"退租出售·继承赠与","cq":"我和老公离婚，房子是我婚前买的但婚后一起还贷，怎么分？","ola":"房屋归你，但须补偿对方共同还贷及增值","cp":["婚前个人出资归登记方","婚后共同还贷属共同财产","婚后购房一般属共同财产","父母出资归出资方子女","协议须明确归属和补偿"],"detail":"离婚时房产的分割规则。婚前一方出资登记在自己名下的归一方，婚后共同还贷及增值部分属共同财产。婚后共同出资登记在双方名下的属共同财产，离婚时原则上均分。婚前父母出资登记在子女名下的一般归该方。离婚协议须明确房产归属和补偿金额。","legalRef":"《中华人民共和国民法典》第1062条、第1063条","consumerBenefit":"依法分割房产，不因不了解吃亏","tags":{"clientType":["buyer","seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["离婚房产分割","离婚分房","离婚财产处理"]},{"id":"EXT-INH-023","name":"继承的房子有抵押贷款怎么办","domain":"退租出售","subScene":"继承赠与","scene":"退租出售·继承赠与","cq":"继承的房子还有贷款没还完，怎么办？","ola":"继续还贷保住房产，或卖房还贷，也可放弃继承","cp":["继承人须在遗产价值内偿还债务","继续还贷可保住房产","可出售房产偿还贷款","放弃继承则不承担债务","银行有权处置抵押房产"],"detail":"继承有抵押贷款的房产，继承人须继续偿还贷款才能保住房产。根据《民法典》，继承人在继承遗产实际价值范围内清偿被继承人的债务。如继承人不愿或无力偿还贷款，银行有权对抵押房产进行处置。继承人可选择：1）继续还贷保住房产；2）出售房产偿还贷款后继承剩余价款；3）放弃继承避免承担债务。","legalRef":"《中华人民共和国民法典》第1161条","consumerBenefit":"了解继承有贷款房产的选择和风险","tags":{"clientType":["buyer","seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["继承有贷款的房产","房产继承房贷谁还","继承的房还有按揭怎么办"]},{"id":"EXT-INH-289","name":"老伴去世在世一方能全卖房吗","domain":"退租出售","subScene":"继承赠与","scene":"退租出售·继承赠与","cq":"买了房才知道卖家老伴刚去世，这合同有效吗？","ola":"不能直接卖，需先办理遗产继承过户后方可全权处分。","cp":["房产一半属遗产需先分割","在世方无权单独处分全房","需先办继承过户再行出售","隐瞒事实卖房属无权处分"],"detail":"依据《民法典》第1153条，夫妻共同房产一方去世，该房产的一半属于在世配偶的个人财产，另一半属于死者遗产。在世配偶不能单独全权处分该房产，必须先进行遗产分割，将属于死者的份额由法定继承人（含在世配偶、子女、父母）继承并过户后，方可出售。实践中，若子女放弃继承，需先办理继承公证将份额全归在世配偶，再行出售。风险提示：隐瞒配偶去世事实单独卖房，属无权处分，合同可能被认定无效或面临赔偿。","legalRef":"《中华人民共和国民法典》第1153条","consumerBenefit":"识别卖家隐瞒丧偶事实的无权处分风险，保障交易安全。","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见前","见中"]},"alias":["配偶去世房产全归在世一方吗","老伴死了房子能直接卖吗","夫妻一方去世另一方卖房"]},{"id":"EXT-MTG-001","name":"房子有抵押能卖吗","domain":"退租出售","subScene":"抵押贷款","scene":"退租出售·抵押贷款","cq":"我的房子还有贷款没还完，能挂牌卖吗？","ola":"能卖，但须先解押或走带押过户","cp":["有抵押仍可签署买卖合同","须先解押或走带押过户","卖方须明确解押时间","买方首付解押须专款专用","签约须填写抵押权人信息"],"detail":"抵押中的房屋能否出售的问题。有抵押的房屋签署买卖合同是有效的，但须先还清贷款并注销抵押登记才能过户，或通过带押过户方式交易。卖方须明确还清贷款和注销抵押的具体时间，买方首付用于解押的资金应专款专用或担保支付。","legalRef":"《中华人民共和国民法典》第406条","consumerBenefit":"有贷款也能卖房，了解操作路径","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["抵押房出售","有贷款的房子能卖吗","抵押中房屋交易"]},{"id":"EXT-MTG-014","name":"查封的房子能解封吗","domain":"退租出售","subScene":"抵押贷款","scene":"退租出售·抵押贷款","cq":"我的房子被法院查封了，怎么才能解封？","ola":"偿还债务或提供担保可申请解封","cp":["查封期禁止转让抵押","偿还债务可申请解封","提供担保可置换查封","查封期3年届满未续封自动解封","查封信息可到不动产中心查"],"detail":"被查封房屋的解封条件。房屋因债务纠纷、诉讼保全等原因被法院查封，查封期间禁止转让、抵押。解封方式：①偿还债务后申请法院解封；②提供等额担保申请置换查封；③查封期限届满未续封自动解封（一般查封期限3年）。查封信息可在不动产登记中心查询。","legalRef":"《中华人民共和国民事诉讼法》第104条","consumerBenefit":"了解解封路径，恢复房屋交易能力","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["查封房屋解封","被查封房产处理","法院查封房产"]},{"id":"EXT-MTG-022","name":"有贷款的房子公积金还能再贷吗","domain":"退租出售","subScene":"抵押贷款","scene":"退租出售·抵押贷款","cq":"我的公积金能贷多少钱？怎么算？","ola":"每缴1年可贷10万，首套最高120万，取各项最低值","cp":["北京首套最高120万二套60万","每缴存1年可贷10万元","月还款不超月收入60%","实际可贷取各项最低值","夫妻共同可叠加不超上限"],"detail":"公积金贷款额度受多个因素限制：1）最高贷款额度（北京首套120万，二套60万）；2）缴存年限（每缴存1年可贷10万元，不足整年按整年计算）；3）月缴存额和账户余额；4）还款能力（月还款额不超过月收入的60%）；5）房屋评估价和贷款成数。实际可贷额度取以上各项最低值。夫妻共同申请可叠加额度，最高不超过上限。","legalRef":"《住房公积金管理条例》第26条","consumerBenefit":"提前了解可贷额度，合理规划购房预算","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["公积金能贷多少","公积金贷款额度计算公式","北京公积金贷款上限"]},{"id":"EXT-MTG-023","name":"贷款还清后不解押有什么风险","domain":"退租出售","subScene":"抵押贷款","scene":"退租出售·抵押贷款","cq":"房贷还完了但没有办解押，有什么风险？","ola":"不解押无法卖房过户，还清后应尽快办抵押注销","cp":["不解押无法正常出售过户","无法办理二次抵押贷款","影响房屋市场价值","贷款结清后应尽快办理解押","带结清证明到不动产登记中心办理"],"detail":"贷款还清后如不办理抵押注销（解押），房屋产权仍登记有抵押信息，将影响后续交易和再融资。主要风险：1）无法正常出售过户（有抵押登记不能过户）；2）无法办理二次抵押贷款；3）房屋被认定为有权利负担，影响市场价值。贷款结清后应尽快携带银行出具的贷款结清证明和他项权证，到不动产登记中心办理抵押注销。","legalRef":"《中华人民共和国民法典》第394条","consumerBenefit":"及时解押保障房产完整产权，不影响后续交易","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["房贷还完不解押风险","贷款结清不解押能卖房吗","不解押房产算谁的"]},{"id":"EXT-SEL-002","name":"哪些房子不能上市出售","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"我有个小产权房想卖，能挂牌吗？","ola":"小产权房属集体产权，禁止上市交易","cp":["集体产权禁止交易","无产权证不能卖","违章建筑不能卖","被查封冻结不能卖","廉租公租房不能卖"],"detail":"法律禁止上市交易的房屋类型。包括：集体产权房屋（含使用权房）、未取得上市许可的校产房军产房宗教房、无法取得不动产权证书的房屋（含宅基房乡产房）、只有承租权的廉租房公租房、违章建筑、被限制交易的房屋（查封冻结等）、未取得完全所有权的经济适用房等。","legalRef":"《中华人民共和国城市房地产管理法》第38条","consumerBenefit":"避免挂牌后合同无效造成损失","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["禁止交易房屋","不可售房屋","不能卖的房"]},{"id":"EXT-SEL-003","name":"出售委托协议什么时候失效","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"卖房的委托协议到期了怎么办？","ola":"到期需重新签署，提前可申请延期","cp":["有效期届满自动失效","产权人中止则失效","房源核销则失效","到期前可延期","产权人变更须重签"],"detail":"出售委托协议失效的三种情形：①委托协议有效期届满；②产权人或产权人之一告知中止委托协议；③房源已经核销。委托到期前可与业主沟通延期，通过二手房交易监管平台修改委托时间并留存业主短信截图。委托到期后应重新签署委托协议。","legalRef":"《中华人民共和国民法典》第162条","consumerBenefit":"及时续签保障房源持续在售","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["委托到期","出售委托失效","委托期限届满"]},{"id":"EXT-SEL-007","name":"满五唯一能省多少税","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"我的房子满五唯一了，卖房能省多少税？","ola":"满五唯一免增值税和个税，省税最多","cp":["满五=取得产权证满5年","唯一=家庭在该省唯一住房","满五唯一免增值税和个税","不满2年需缴增值税","不唯一需缴个税"],"detail":"'满五唯一'是二手房交易中最重要的免税条件。满五指取得产权证满5年，唯一指卖方家庭在该省份仅此一套住房。满足满五唯一的，增值税及附加免征，个人所得税免征，可大幅降低交易成本。不满足的，增值税约5.3%，个税差额20%或核定1%。","legalRef":"《财税〔2018〕137号第1条","consumerBenefit":"满足条件可免数万元税费","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["满五唯一免税","满五年唯一住房","出售省税"]},{"id":"EXT-SEL-011","name":"夫妻共同房产出售需双方同意吗","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"房子写我老公名字，我自己能卖吗？","ola":"夫妻共同房产须双方同意才能出售","cp":["共同共有须双方同意","一方擅自出售可主张无效","买方善意取得除外","配偶可要求损害赔偿","签约须配偶到场签字"],"detail":"夫妻共同房产出售必须双方同意。依据《民法典》第301条，处分共有的不动产应当经占份额三分之二以上的按份共有人或全体共同共有人同意。夫妻对共同所有房产有平等处分权，一方擅自出售的，另一方可主张买卖合同无效。买方善意的除外，但配偶可要求赔偿。","legalRef":"《中华人民共和国民法典》第301条、第311条","consumerBenefit":"避免单方出售导致合同被撤销","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["共有房产出售","夫妻共同卖房","共有人同意出售"]},{"id":"EXT-SEL-012","name":"卖房迁户口有时间要求吗","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"我卖的房子里有户口，买家催我迁走，有什么规定？","ola":"按合同约定时间迁出，逾期须付违约金","cp":["合同须约定户口迁出时间","一般过户后30日内迁出","未迁出可主张违约金","影响买方落户和入学","是常见交易纠纷点"],"detail":"出售房屋时原产权人户口迁出的时间要求。合同中应明确约定户口迁出时间，一般在过户后一定期限内（如30日或交房前）迁出。卖方未按时迁出的，买方可按合同约定主张违约金。户口未迁出可能影响买方落户和子女入学，是常见纠纷点。","legalRef":"《户口登记条例》第10条","consumerBenefit":"明确迁户义务，避免违约纠纷","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["户口迁出期限","卖房迁户口","出售房屋户口迁出"]},{"id":"EXT-SEL-013","name":"卖房交房前要注意什么","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"我卖的房子快交房了，需要做哪些准备？","ola":"结清费用、迁户口、腾空交钥匙","cp":["结清所有杂费","迁出户口","腾空房屋交付钥匙","有租约须协商处理","物业保证金验收后退还"],"detail":"卖方交房前需完成的事项。包括：结清水电燃气物业供暖等费用、迁出户口、腾空房屋及个人物品、交付钥匙门禁卡、如有租约须与买方协商租客处理方式。物业交割保证金一般在交房验收合格后解冻退还卖方。交房时间以合同约定为准。","legalRef":"《中华人民共和国民法典》第604条","consumerBenefit":"规范交房避免后续纠纷和扣保证金","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["交房注意事项","物业交割","出售交房"]},{"id":"EXT-SEL-018","name":"卖房佣金怎么收","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"卖房中介费一般是多少？","ola":"一般成交价2%-2.7%，双方各付一半","cp":["佣金一般成交价的2%-2.7%","买卖双方分别支付","签约当日收取","须开具佣金发票","违约仍须付佣金"],"detail":"二手房出售的佣金收取规则。佣金由买卖双方按约定比例分别支付给经纪机构，北京地区常见标准为成交价的2%-2.7%，买卖双方各付一半或按约定执行。佣金在合同签订当日收取，须开具佣金发票。成交后因一方违约导致交易未成的，违约方仍须支付佣金。","legalRef":"《中华人民共和国民法典》第962条","consumerBenefit":"了解佣金成本，合理预算交易费用","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["出售佣金标准","卖方中介费","卖房服务费"]},{"id":"EXT-SEL-023","name":"卖房需要哪些证件和材料","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"我要卖房，需要准备哪些证件和材料？","ola":"房产证+身份证+婚姻证明+配偶同意书+购房发票","cp":["不动产权证书是核心证件","需身份证和婚姻证明","配偶须出具同意出售声明","购房发票用于计算税费","共有人需出具同意出售文件"],"detail":"卖房所需主要证件和材料包括：1）不动产权证书（房产证）；2）出卖人身份证原件；3）婚姻证明（结婚证或离婚证+离婚协议）；4）配偶同意出售的书面声明（夫妻共同财产）；5）购房原始发票和契税凭证（用于计算税费）；6）户口本（迁户口用）；7）如有共有人需共有人同意出售的书面文件。如房产证丢失须先补办。","legalRef":"《不动产登记暂行条例》第16条","consumerBenefit":"提前备齐材料，卖房流程不卡壳","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["二手房出售要什么材料","卖房过户需要什么证件","卖房准备什么资料"]},{"id":"EXT-SEL-028","name":"共有人不同意卖房合同有效吗","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"共有人不同意卖房，我签的合同有效吗？","ola":"未经共有人同意出售可能无效，须全体共有人同意","cp":["共有房产出售须经全体共有人同意","部分共有人擅自签约可能无效","买方善意有偿合同可能有效","夫妻一方擅自卖房另一方可追回","建议所有共有人共同签署合同"],"detail":"共有房产出售须经全体共有人同意。部分共有人未经其他共有人同意擅自签订的卖房合同，如买方善意且有偿，合同有效但其他共有人可主张赔偿；如买方明知共有人不同意仍签约，合同可能被认定无效。夫妻共同房产一方擅自出售，另一方有权追回。建议共有房产出售时所有共有人共同签署合同或在签约前取得其他共有人书面同意。","legalRef":"《中华人民共和国民法典》第301条、第311条","consumerBenefit":"了解共有房产出售的效力规则，避免合同纠纷","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["部分共有人签字卖房有效吗","共有人不同意出售怎么办","夫妻一方签字卖房有效吗"]},{"id":"EXT-SEL-029","name":"卖房房产证丢了怎么补办","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"要卖房但房产证丢了，怎么补办？","ola":"到不动产登记中心申请补证，约15-30天拿新证","cp":["须先补办才能出售","到不动产登记中心申请","公告15个工作日后补发","补办约需15-30个工作日","补证期间无法办理过户"],"detail":"房产证（不动产权证书）丢失后须先补办才能出售。补办流程：1）到不动产登记中心申请遗失声明和补证；2）登记机构在官网公告15个工作日；3）公告期满无人异议，予以补发新证。所需材料：身份证原件、遗失声明申请书等。补办周期约15-30个工作日。补证期间无法办理过户，建议提前补办避免影响交易进度。","legalRef":"《不动产登记暂行条例实施细则》第23条","consumerBenefit":"提前补办不耽误卖房进度","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["房产证丢了能卖房吗","不动产权证补办流程","房产证补办要多久"]},{"id":"EXT-SEL-032","name":"卖房定价怎么定合理","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"卖房定价怎么定合理","ola":"以同小区近期成交价为基准","cp":["以同小区近期成交价为基准","楼层朝向装修户型调价","挂牌价高于底价5-10%留空间","查贝壳等平台成交数据","以成交价而非挂牌价定价"],"detail":"二手房定价方法：①比价法：参考同小区近期成交价（3-6个月内），选楼层/朝向/面积相近的成交房源对标；②调整因素：楼层（中间层最优）、朝向（南向最优）、装修（精装加价）、户型（方正通透优）、学位（有学位加价）；③挂牌策略：挂牌价略高于心理底价5-10%留议价空间；④获取数据：贝壳/链家等平台查看同小区历史成交价和挂牌价；⑤切忌按挂牌价定价（挂牌价通常虚高10-15%），应以成交价为基准。","legalRef":"行业通行做法","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["卖房怎么报价","挂牌价怎么定","二手房定价方法"]},{"id":"EXT-SEL-039","name":"二手房出售要交哪些税","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"卖房要交哪些税","ola":"满2年免增值税","cp":["满2年免增值税","满五唯一免个税","不满2年增值税5.6%","个税可选利润20%或售价1%","税费各地有差异查最新规定"],"detail":"卖房税费：①增值税：持有满2年免征（北上广深满2年普通住宅免，非普通差额征收），不满2年全额×5.6%；②个人所得税：满五唯一（满5年+家庭唯一住房）免征，否则按利润×20%或售价×1%征收；③印花税：目前免征；④中介费：2-3%（可议价）；⑤注意：税费政策各地有差异须查当地最新规定。满五唯一是卖房最大的免税优惠。","legalRef":"《关于调整房地产交易环节契税 营业税优惠政策的通知》（财税〔2016〕23号）","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["卖房税费清单","二手房出售税费","满五唯一免税吗"]},{"id":"EXT-SEL-095","name":"卖房要准备哪些材料","domain":"退租出售","subScene":"出售","scene":"退租出售·出售","cq":"卖房要准备哪些材料","ola":"不动产权证书+身份证明","cp":["不动产权证书+身份证明","已婚须配偶书面同意","原始契税票购房发票","有抵押须解押或同意出售","委托须公证委托书"],"detail":"卖房所需材料：①不动产权证书（房产证+土地证合一新版）；②卖方身份证明（身份证/户口本/结婚证）；③配偶同意出售证明（已婚须配偶书面同意，否则属无权处分）；④购房原始票据（契税票/购房发票用于核算税费和满五认定）；⑤如有抵押：抵押权人同意出售证明或贷款结清证明；⑥委托他人出售的须公证委托书；⑦如有共有权人须共有权人同意出售书面文件。","legalRef":"《中华人民共和国城市房地产管理法》第38条","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["卖房需要什么证件","出售房屋材料清单","卖房身份证件"]},{"id":"EXT-TRM-002","name":"退租押金能全退吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"我退租了，房东说押金不退，这合理吗？","ola":"押金扣除欠费和违约金后须退还","cp":["押金扣欠费和违约金后退还","剩余押金必须退还","房东不能全额扣留","押金一般为一月租金","欠费包括水电燃气等"],"detail":"租赁合同解除后押金（租赁保证金）的退还规则。押金除用于抵扣租客应交未交的租金、费用以及违约金、赔偿金外，剩余部分应如数返还租客。房东无权全额扣留押金，但可依法扣除租客欠费和违约金。押金一般为1个月租金。","legalRef":"《中华人民共和国民法典》第586条、第587条","consumerBenefit":"避免房东无理由扣押金，保障合法权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["押金退还","退租退押金","押金扣完能退多少"]},{"id":"EXT-TRM-004","name":"到期退租要提前多久通知房东","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"房子下个月到期，我现在说不续租来得及吗？","ola":"一般需提前30天书面通知房东","cp":["一般需提前30天通知","应以书面形式通知","未约定则合理期限通知","到期不续视为退租","提前通知避免违约"],"detail":"租赁合同到期退租时租客需提前通知业主的期限要求。一般合同约定需提前30天书面通知业主不再续租。若合同未约定通知期，根据《民法典》第730条，当事人对租赁期限没有约定或约定不明确，可随时解除合同，但应在合理期限之前通知对方。","legalRef":"《中华人民共和国民法典》第730条","consumerBenefit":"按时通知避免被算违约扣押金","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["退租通知期限","到期不续租通知","租期届满退租"]},{"id":"EXT-TRM-007","name":"房东违约让我提前退租怎么办","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"房东说让我这月底搬走，但我合同还没到期，怎么办？","ola":"房东违约，你有权拒绝或要求赔偿","cp":["业主违约需承担赔偿责任","租客有权拒绝提前退租","业主须退还未发生租金","租客可主张搬家等损失","可要求继续履行合同"],"detail":"业主在租赁期内单方面要求租客提前退租的违约情形。根据《民法典》，业主需承担违约责任并赔偿租客损失，包括退还已缴未发生的租金、支付违约金、赔偿租客搬家和临时住宿等实际损失。租客有权拒绝并要求继续履行合同。","legalRef":"《中华人民共和国民法典》第577条、第584条","consumerBenefit":"知道业主违约时自己的权利和索赔方式","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["业主违约收房","房东赶人","房东提前收房"]},{"id":"EXT-TRM-008","name":"退租后户口要迁出吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"之前租房落了户，现在退租了户口要迁走吗？","ola":"是的，退租后需将户口迁出该地址","cp":["退租后租客应迁出户口","合同可约定迁出时限","未迁出影响业主后续交易","可约定违约责任","业主可向公安申请处理"],"detail":"租客在租赁房屋中落户后，退租时需将户口迁出的义务。租客户口挂在租赁地址上的，退租后应主动迁出，否则可能影响业主后续出租或出售。业主可在合同中约定户口迁出时限和违约责任。租客不迁出户口，业主可向公安机关申请处理。","legalRef":"《户口登记条例》第10条","consumerBenefit":"避免户口遗留影响后续落户和业主交易","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["退房迁户口","租客户口迁出","租赁户口问题"]},{"id":"EXT-TRM-009","name":"贝壳上退租解约怎么操作","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"在贝壳签的租房合同，退租怎么在APP上操作？","ola":"经纪人Link端发起解约，APP确认即可","cp":["贝壳APP支持线上解约","公司租客需线下办理","经纪人发起Link端解约","2023年3月起支持线上","无需双方到场签字"],"detail":"通过贝壳平台办理租赁合同线上解约的操作流程。自2023年3月11日起，业主和租客可在贝壳APP完成线上解约，无需亲自到场签署解约协议（公司租客仅支持线下）。流程为：经纪人发起Link电脑端→签约→租赁合同列表→合同编号→合同详情→预览→解约。","legalRef":"《中华人民共和国民法典》第562条","consumerBenefit":"无需跑门店，线上快速完成解约","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["线上退租流程","贝壳APP解约","Link系统退租"]},{"id":"EXT-TRM-010","name":"退租时家具家电损坏要赔吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租的时候冰箱坏了，是我赔还是房东自己修？","ola":"自然老化房东修，人为损坏租客赔","cp":["自然损耗业主负责修","人为损坏租客须赔偿","合理使用与保管不当区别","业主3日内未修租客可代修","合同另有约定从其约定"],"detail":"退租时房屋附属家具家电损坏的责任认定与赔偿规则。根据《民法典》第712条，租客合理使用致使物品因自然属性损耗的，由业主负责修复，租客无需赔偿。租客保管不当或不合理使用致损的，租客应负责维修或承担赔偿责任。合同另有约定的从其约定。","legalRef":"《中华人民共和国民法典》第712条、第713条","consumerBenefit":"区分自然损耗和人为损坏，避免被冤枉赔钱","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["退房家电损坏赔偿","家具损坏退租","退租设施赔偿"]},{"id":"EXT-TRM-012","name":"换租怎么办理","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"我现在住的不满意，想换一套，怎么办理换租？","ola":"先解约原合同，再签约新合同","cp":["需协商一致才能换租","原合同先解约结算","再签署新租赁合同","同一客户不同房源","可能涉及两次佣金"],"detail":"换租是租客在合同履约期间换到经纪公司其他代理房屋或业主其他房屋的情形。操作流程为：协商一致后办理原房屋的解约手续和新房屋的签约手续。简单说就是同一个客户从房间A换租为房间B。原合同需先解约结算，再签署新合同。","legalRef":"《中华人民共和国民法典》第562条","consumerBenefit":"了解换租流程，减少搬家成本","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["同一客户换房","换租流程","租期内换房"]},{"id":"EXT-TRM-013","name":"业主卖房我还能继续住吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"房东说房子要卖了，我还能继续住吗？","ola":"能，买卖不破租赁，你可住到期满","cp":["买卖不破租赁原则","租客可继续住到期满","新房东须履行原合同","业主卖房需提前30日通知","租客享有优先购买权"],"detail":"业主在租赁期内出售房屋的，租赁合同继续有效，租客有权按原合同继续居住至期满，即'买卖不破租赁'原则。依据《民法典》第725条，租赁物在承租人按租赁合同占有期限内发生所有权变动的，不影响租赁合同效力。新房东须履行原合同义务。","legalRef":"《中华人民共和国民法典》第725条、第726条","consumerBenefit":"房子被卖不影响居住权，安心续住","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["买卖不破租赁","房东卖房租客权利","卖房后租赁合同"]},{"id":"EXT-TRM-014","name":"房东卖房我有优先购买权吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"房东要把房子卖了，我能优先买吗？","ola":"同等条件下你有优先购买权，15日内须表态","cp":["租客享有同等条件优先购","业主须提前合理期限通知","15日未表态视为放弃","共有人优先权优于租客","卖近亲属不受限"],"detail":"依据《民法典》第726条，出租人出卖租赁房屋的，承租人享有以同等条件优先购买的权利。出租人应在出卖前合理期限内通知承租人，承租人15日内未明确表示购买的，视为放弃优先购买权。房屋共有人行使优先购买权或出卖给近亲属的除外。","legalRef":"《中华人民共和国民法典》第726条、第727条","consumerBenefit":"有机会优先购房，不被他人抢走","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["承租人优先购买权","租客优先买房","租赁房屋优先购买"]},{"id":"EXT-TRM-016","name":"退租纠纷怎么解决","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租时房东扣了我全部押金，怎么维权？","ola":"先协商，不成可投诉或起诉","cp":["协商为首选解决方式","中介可协助调解","可向住建部门投诉","留存合同和缴费证据","小额纠纷可走速裁"],"detail":"退租过程中因押金退还、费用结算、设施损坏等问题产生纠纷的解决途径。解决方式依次为：双方协商→中介调解→向住建部门投诉→向法院起诉。诉讼前建议留存合同、缴费记录、照片等证据。对于金额较小的纠纷，可申请小额诉讼程序。","legalRef":"《中华人民共和国民法典》第233条","consumerBenefit":"了解维权路径，不因怕麻烦放弃权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["退租争议处理","退房纠纷","退租维权"]},{"id":"EXT-TRM-018","name":"续租和退租怎么选","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"房租快到期了，续租还是换租划算？","ola":"比较续租涨幅和市场价，再做决定","cp":["续租需重新签合同","续订租期不超20年","退租需提前通知业主","比较市场租金水平","续租佣金可能减免"],"detail":"租赁合同到期前，租客面临续租或退租的决策。续租需双方协商一致重新签订合同，租期自续订之日起不得超过20年。退租则需提前通知业主并做好验收交接。决策应考虑：租金涨幅、居住需求变化、业主续租条件、市场同类房源价格等。","legalRef":"《中华人民共和国民法典》第705条","consumerBenefit":"做出最经济合理的续退决策","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["续租vs退租","租期到了续不续","续租注意事项"]},{"id":"EXT-TRM-019","name":"退租时要不要做房屋清洁","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租的时候房东要求找保洁，这费用谁出？","ola":"合同有约定从约定，无约定保持整洁即可","cp":["保持房屋整洁即可","合同有约定从其约定","无强制专业保洁要求","不得以不洁扣全部押金","建议入住时拍照留底"],"detail":"退租时房屋清洁的责任和标准。一般合同约定租客退租时应保持房屋整洁，但无强制专业保洁要求。若合同明确约定需专业保洁或还原装修前状态，租客应遵照执行。未约定清洁标准的，保持正常居住状态即可。业主不得以清洁不达标为由扣除全部押金。","legalRef":"《中华人民共和国民法典》第712条","consumerBenefit":"避免退租时因清洁问题被扣押金","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["退房保洁","退租清洁要求","退房打扫"]},{"id":"EXT-TRM-023","name":"租期内房东涨租金我该怎么办","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"合同还没到期，房东说要涨房租，我该怎么办？","ola":"合同期内房东不能单方涨租，可以拒绝","cp":["合同期内房东不得擅自涨租金","租金标准以合同约定为准","可拒绝涨租要求继续履行","房东断水断电属违法行为","签约时约定租期租金不变"],"detail":"租赁合同有效期内，房东无权单方面涨租金。根据《民法典》，租赁合同约定的租金标准对双方具有约束力，合同期内房东不得擅自提高租金。如房东以涨租为由威胁解约或断水断电，租客可拒绝涨租并要求继续履行合同，同时可向住建部门投诉。建议签约时明确约定租期内租金不变条款。","legalRef":"《中华人民共和国民法典》第709条","consumerBenefit":"合同期内租金有保障，不被房东随意涨价","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["房东中途涨房租怎么办","租期内房东加租合法吗","合同期内房东涨价"]},{"id":"EXT-TRM-024","name":"房东不退押金怎么维权","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租了房东就是不退押金，怎么维权？","ola":"先协商，不行投诉12345或小额诉讼，保留证据","cp":["先协商再调解再投诉再诉讼","入住和退租时照片对比留证","可向住建部门或12345投诉","小额诉讼程序审理快费用低","保留合同和押金收据等证据"],"detail":"房东不退押金是租赁纠纷中最常见的问题。维权路径：1）先与房东协商，出示入住和退租时的照片对比证明无损坏；2）协商不成向社区调解委员会申请调解；3）向住建部门或12345投诉；4）向法院提起小额诉讼（押金纠纷一般适用小额诉讼程序，审理快费用低）。注意保留合同、押金收据、入住退租照片等证据。","legalRef":"《中华人民共和国民法典》第577条","consumerBenefit":"掌握维权路径，拿回被扣押的押金","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["退租押金不退怎么办","房东扣押金怎么要回来","押金不退投诉渠道"]},{"id":"EXT-TRM-026","name":"退租后房东迟迟不退押金怎么办","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租快一个月了，房东一直拖着不退押金，怎么办？","ola":"书面催告限期退，不行投诉12345或起诉","cp":["押金应在7-15个工作日内退还","先书面催告限期退还","可向住建部门或12345投诉","可向法院提起诉讼","诉讼时效为3年"],"detail":"退租后房东应在合理期限内退还押金，一般不超过7-15个工作日。如房东无故拖延，租客可：1）书面催告房东限期退还，保留催告记录；2）向住建部门或12345投诉；3）向法院提起诉讼。注意押金退还请求的诉讼时效为3年，自知道权利被侵害之日起算。房东以各种理由拖延不退的，租客应及时维权，不要超过诉讼时效。","legalRef":"《中华人民共和国民法典》第188条、第577条","consumerBenefit":"不被房东无限期拖延，及时拿回押金","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["退房后押金一直不退","房东拖延退押金","退租多久退押金"]},{"id":"EXT-TRM-028","name":"退租水电燃气费没结清能走吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租时水电燃气费没结清，能直接走吗？","ola":"必须结清，未结清房东可从押金扣除","cp":["水电燃气费必须结清","未结清房东可从押金扣除","双方共同抄表确认读数","退租前2-3天共同抄表","物业费采暖费也需一并结清"],"detail":"退租时水电燃气费用必须结清，否则房东有权从押金中扣除欠费。结清方式：双方共同抄表确认读数，按照【实抄字数-上次结清字数】×单价计算未结费用。建议退租前2-3天与房东一起抄表，确保费用清楚。如欠费不结清直接离开，房东可从押金扣除，不足部分租客仍需补缴。物业费、采暖费等也需一并结清。","legalRef":"《中华人民共和国民法典》第712条","consumerBenefit":"退租交接清楚，不留下欠费纠纷","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["退租水电费怎么算","退房水电燃气结算","退租欠水电费谁承担"]},{"id":"EXT-TRM-029","name":"房东卖房让我搬走有赔偿吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"房东把房子卖了让我搬走，我有赔偿吗？","ola":"买卖不破租赁，新房东须继续履行合同至期满","cp":["买卖不破租赁原则保护租客","新房东须继续履行原合同","不得以已出售为由赶走租客","强行赶走可要求继续履行或赔偿","租客享有优先购买权"],"detail":"根据《民法典》'买卖不破租赁'原则，房屋所有权变动不影响租赁合同效力，新房东须继续履行原租赁合同至期满，不得以房屋已出售为由要求租客搬走。如房东强行赶走租客，租客可要求继续履行合同或要求赔偿。但如租客自愿同意提前搬离，可与房东协商补偿金额。租客还享有同等条件下的优先购买权。","legalRef":"《中华人民共和国民法典》第725条","consumerBenefit":"房子卖了租约仍在，不被房东随意赶走","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["房东卖房租客有赔偿吗","买卖不破租赁怎么理解","房东卖房赶走租客赔偿"]},{"id":"EXT-TRM-037","name":"退租时押金多久必须退还","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租时押金多久必须退还","ola":"合同约定7-15日内退还","cp":["合同约定7-15日内退还","正常损耗不应扣押金","拒退押金可起诉小额诉讼","保留退房交接记录","书面催告后可强制执行"],"detail":"退租押金退还规则：①租赁期满或合同解除后房东应在合理期限内退还押金（扣除应扣款项后的余额）；②各地规定不同，一般建议合同约定退租后7-15日内退还；③房东不得以不合理理由扣押金（正常损耗不应扣押金）；④房东拒退押金：先书面催告→向法院起诉（小额诉讼程序）→申请强制执行；⑤保留退房交接记录（照片/视频）证明房屋状况。","legalRef":"《中华人民共和国民法典》第577条；行业通行做法","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["退租押金退还期限","房东不退押金怎么办","押金退还时间规定"]},{"id":"EXT-TRM-039","name":"退租房屋交接要注意什么","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租房屋交接要注意什么","ola":"制作交接清单逐项检查","cp":["制作交接清单逐项检查","拍照录像留证现状","记录水电气表读数","钥匙门禁卡全部归还","区分正常损耗vs人为损坏"],"detail":"退租房屋交接要点：①制作交接清单逐项检查记录（墙面/地面/门窗/灯具/电器/家具等）；②拍照/录像留证房屋现状（每个房间全景+细节问题）；③水电气表读数记录并截图；④钥匙/门禁卡/车库遥控等全部归还并签字确认；⑤已与房东/中介三方到场确认签字；⑥房屋有损坏的区分正常损耗和人为损坏正常损耗不扣押金；⑦结清未付的水电燃气物业费。","legalRef":"行业通行做法","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["退房交接清单","退租验收要点","退房怎么检查"]},{"id":"EXT-TRM-051","name":"退租时房屋有正常损耗要赔吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租时房屋有正常损耗要赔吗","ola":"正常损耗不应扣押金","cp":["正常损耗不应扣押金","自然老化属合理折旧","人为损坏应赔偿或维修","入住退租都拍照对比","合同应约定正常磨损不扣"],"detail":"退租正常损耗vs人为损坏：①正常损耗（自然老化/合理使用磨损）：不应扣押金，如墙面自然泛黄/地板正常磨损/家具使用老化/灯泡寿命到期等；②人为损坏：应赔偿或维修，如墙面涂鸦/打孔/地砖砸裂/家具人为损坏/电器使用不当损坏等；③区分标准：是否因正常居住使用导致，合同可约定'正常使用磨损不扣押金'；④建议入住和退租都拍照对比以区分已有问题和新增损坏。","legalRef":"《中华人民共和国民法典》第710条","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["退租正常磨损不赔","自然老化房东能扣押金吗","房屋折旧算谁的责任"]},{"id":"EXT-TRM-057","name":"租期到了不搬会怎样","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"租期到了不搬会怎样","ola":"到期应按约定返还房屋","cp":["到期应按约定返还房屋","逾期须支付房屋占用费","催告不搬可起诉腾退","房东不得自行换锁清退","未续签继续住成立不定期租赁"],"detail":"租期届满不搬的法律后果：①租赁合同到期后租客应按约定期限返还房屋；②到期未搬出房东可要求搬离并主张逾期占用期间的房屋使用费（按原租金或市场租金标准）；③经催告仍不搬的房东可向法院起诉要求腾退房屋+支付占用费；④房东不得自行换锁/强行搬离租客物品（可能构成侵权），应通过法律程序解决；⑤到期后如双方未续签但租客继续居住房东未异议的成立不定期租赁任何一方可随时解除。","legalRef":"《中华人民共和国民法典》第733条、第734条","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["到期不退房后果","合同到期继续住","租赁到期不搬走"]},{"id":"EXT-TRM-064","name":"退租后水电费没结清怎么办","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租后水电费没结清怎么办","ola":"现场抄表读数拍照留证","cp":["现场抄表读数拍照留证","按实际使用量多退少补","租客期间欠费租客补缴","欠费可从押金中扣须凭证","物业费同理结清至退租日"],"detail":"退租水电费结算：①退租时应现场抄录水电气表读数拍照留证；②按实际使用量结算至退租日多退少补；③如退租后有欠费：属于租客使用期间的由租客补缴，属于退租后的房东承担；④合同约定水电费含在租金内的房东不得再额外扣除；⑤欠费未结清的房东可从押金中扣除实际欠费金额但须提供缴费凭证；⑥物业费同理须结清至退租日。","legalRef":"行业通行做法","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["退租水电费结算","退房时水电欠费","房东代扣水电费"]},{"id":"EXT-TRM-081","name":"退租时房东说东西坏了要赔","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租时房东说东西坏了要赔","ola":"人为损坏应赔偿或维修","cp":["人为损坏应赔偿或维修","自然老化不应赔偿","房东须举证人为损坏","非人为损坏房东负责修","争议可第三方评估或诉讼"],"detail":"退租物品损坏赔偿纠纷：①人为损坏（如摔坏电视/划伤地板/烫坏桌面）租客应赔偿或维修；②自然老化/正常使用损耗/产品质量问题导致的不应赔偿；③房东主张损坏扣押金的须举证证明系租客人为损坏而非自然老化；④租期内电器/家具非人为损坏的维修义务在房东（合同无另行约定时）；⑤双方对损坏原因有争议的可请第三方评估或通过诉讼由法院认定。","legalRef":"《中华人民共和国民法典》第710条、第712条","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["退租家具损坏赔偿","房东扣押金说物品损坏","退租赔偿纠纷"]},{"id":"EXT-TRM-091","name":"退租搬走东西可以拆走吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租搬走东西可以拆走吗","ola":"可移动物品可带走恢复原状","cp":["可移动物品可带走恢复原状","固定物可拆但须恢复原状","拆除损房屋的建议折价留房东","合同有约定从约定","退租前协商清楚归属"],"detail":"退租添附物（租客加装物品）处理规则：①租客自带的可移动物品（家具/电器/窗帘等）退租时可带走但须恢复原状（如补墙面打孔处）；②租客安装的固定物（空调/热水器/灯具/晾衣架等）原则上可拆除带走但须恢复原状不损坏房屋；③如拆除会损坏房屋的（如嵌入式橱柜/铺的地板）建议与房东协商折价留给房东；④合同有约定的按约定执行；⑤退租时协商好哪些带走哪些留下避免争议。","legalRef":"《中华人民共和国民法典》第715条；行业通行做法","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["退租能带走空调吗","租客装的电器能拆走吗","退租固定物归属"]},{"id":"EXT-TRM-102","name":"退租没签合同押金怎么要回","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租没签合同押金怎么要回","ola":"事实租赁关系受法律保护","cp":["事实租赁关系受法律保护","转账记录聊天记录可举证","无合同风险大建议签书面合同","押金纠纷仍可起诉","保留所有转账和聊天证据"],"detail":"无书面租赁合同的退租：①未签书面合同但已形成事实租赁关系的（有租金支付记录/入住事实等），双方仍受租赁相关法律保护；②押金退还：虽无书面合同但转账记录/微信聊天/收条等均可证明押金已付及金额；③举证：微信/短信聊天记录、银行/支付宝转账记录、收条、证人证言等均可作为证据；④风险：无书面合同对租客和房东都不利，建议租赁务必签书面合同明确权责；⑤押金纠纷仍可起诉。","legalRef":"《中华人民共和国民法典》第705条；行业通行做法","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["没签租房合同能退押金吗","口头约定退租纠纷","无书面合同押金退还"]},{"id":"EXT-TRM-127","name":"退租后房东不签退房确认","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租后房东不签退房确认","ola":"交接签字对租客很重要","cp":["交接签字对租客很重要","自行制作交接单+拍照留证","微信告知并发照片留证","第三方见证人可辅助证明","保留所有退租通知和记录"],"detail":"退租后房东不签交接确认的处理：①退租交接签字对租客非常重要，证明已按时返还房屋和房屋状况；②房东不配合签字的：租客自行制作交接单+拍照/录像留证+邀请第三方见证人（如物业/邻居）签字；③通过微信/短信告知房东已完成退房交接并发送房屋现状照片，房东未回复异议的可视为默认确认；④保留所有退租通知/交接证据/房东回复记录；⑤如房东事后主张房屋损坏的，租客以退租时的证据反驳。","legalRef":"行业通行做法","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["房东不签退房单","退租交接不签字","房东不确认退房怎么办"]},{"id":"LIV-DEC-001","name":"装修前要办什么手续","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"我家要装修，物业说要登记，不登行不行？","ola":"装修前必须向物业申报登记并签管理协议","cp":["开工前必须向物业申报登记","非业主需取得业主书面同意","须与物业签管理服务协议","协议含施工期限和禁止行为"],"detail":"装修开工前，装修人必须向物业管理企业或房屋管理机构申报登记，非业主使用人还需取得业主书面同意，并与物业管理单位签订装饰装修管理服务协议，约定施工内容、期限、时间、废弃物处置等事项。","legalRef":"《住宅室内装饰装修管理办法》第13条、第16条","consumerBenefit":"避免被物业停工或罚款，保障装修顺利进行","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["装修要报备吗","装修要去物业登记吗","装修申报登记"]},{"id":"LIV-DEC-006","name":"装修工期一般要多久","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"我家90平老房装修大概要多久能住进去？","ola":"老房装修约70-75个工作日，合同要写明","cp":["新房基础装修约60-70工作日","老房比新房多5-7工作日","工期须在合同中明确约定","超期可依合同追究违约责任"],"detail":"装修工期因房屋面积、装修档次和施工内容不同而异。参考行业标准：80㎡新房基础装修约63个工作日，老房因需拆改约68个工作日。每增加一个卫生间增加5个工作日，100㎡以上每增加50㎡增加5个工作日。工期应在合同中明确约定。","legalRef":"《住宅室内装饰装修管理办法》第二十四条","consumerBenefit":"合理预期工期，合同保障不超期","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["装修多久能完工","装修要多长时间","装修工期拖延怎么办"]},{"id":"LIV-DEC-017","name":"装修甲醛超标怎么办","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"新房装修完检测甲醛0.15，超标一倍，能找装修公司吗？","ola":"甲醛超标可要求装修公司返工并承担损失","cp":["国标甲醛≤0.08mg/m³","检测不合格装修企业须返工","通风是最有效除醛方法","须委托有资质检测机构"],"detail":"装修后室内甲醛浓度超过国家标准（≤0.08mg/m³，GB/T 18883）即为超标。装修工程竣工后空气质量应符合国家标准，检测不合格的装饰装修企业应当返工，由责任人承担损失。除醛方法包括通风换气、活性炭吸附、光触媒处理等，通风是最有效的基础手段。","legalRef":"《住宅室内装饰装修管理办法》第29条","consumerBenefit":"检测不合格可追责装修方，保障家人健康","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["装修后甲醛超标怎么处理","甲醛多少算超标","装修除甲醛方法"]},{"id":"LIV-DEC-025","name":"装修增项太多怎么办","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修说好8万，施工中一直加这加那要12万了，怎么办？","ola":"恶意增项属违约，未书面确认的增项可拒付","cp":["恶意增项属违约行为","增项须经业主书面确认","约定增项金额上限","签合同前核实报价完整性"],"detail":"装修增项是指合同签订后施工过程中增加的额外收费项目。恶意增项（即故意漏报项目后施工中加价）属于违约行为。防范措施：签合同前核实报价是否完整、明确约定增项须经业主书面确认、约定增项金额上限（如不超过合同总价的5%）。","legalRef":"《中华人民共和国民法典》第543条、第577条","consumerBenefit":"合同约定增项规则，避免预算翻倍","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["装修恶意增项","装修中途加价怎么办","装修增项超过预算怎么办"]},{"id":"LIV-DEC-047","name":"装修后多久能入住","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修完3个月了，家里有小孩能入住了吗？","ola":"先测甲醛达标再入住，有小孩建议6个月以上","cp":["入住取决于空气质量非等待期","至少通风3-6个月","须CMA机构检测甲醛达标","孕妇婴幼儿建议6-12个月"],"detail":"装修后入住时间取决于室内空气质量而非固定等待期。建议装修完工后至少通风3-6个月，入住前须委托有CMA资质的检测机构按GB/T 18883标准检测甲醛（≤0.08mg/m³）、TVOC等指标，达标方可入住。有孕妇、婴幼儿的家庭建议延长通风期至6-12个月，确保空气质量安全。","legalRef":"《住宅室内装饰装修管理办法》第29条","consumerBenefit":"空气质量达标才入住，保障家人健康","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["新房装修后多久入住","装修完通风多久安全","甲醛检测合格标准"]},{"id":"LIV-DEC-051","name":"老房装修和新房装修有什么不同","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"刚买了二手房要翻新，和毛坯装修有什么不一样？","ola":"多拆旧和水电重做，费用多10%-15%","cp":["老房多拆旧环节费用增10%-15%","原水电管线老化须全部更换","原防水层须重做","工期比新房多5-7工作日"],"detail":"老房装修比新房多了拆旧环节，包括铲除旧墙面、拆除旧瓷砖、旧地板、旧橱柜等，拆旧费约占装修总价的10%-15%。老房还需重点关注：原水电管线老化需全部更换、原防水层需重做、承重结构不可变动、原墙面砂灰层需铲除等。工期比同等面积新房多5-7个工作日。","legalRef":"《住宅室内装饰装修管理办法》第五条","consumerBenefit":"提前预算老房翻新额外成本和工期","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["老房翻新注意事项","二手房装修和毛坯区别","老房装修要拆什么"]},{"id":"LIV-DEC-066","name":"装修预算怎么控制不超支","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修预算怎么控制不超支","ola":"总预算预留15%弹性","cp":["总预算预留15%弹性","合同约定增项不超5%","水电闭口价防超支","主材先选再施工","逐项审核报价防漏项"],"detail":"装修预算控制：①先定总预算按比例分配硬装60%+软装25%+预留15%；②要求详细报价单逐项审核；③合同约定增项上限不超5%；④主材先选再施工避免中途换档次超支；⑤水电隐蔽工程最易超预算建议闭口合同。","legalRef":"行业通行做法","consumerBenefit":"了解关键要点避免踩坑","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["装修怎么不超预算","装修费用控制技巧","装修预算怎么做"]},{"id":"LIV-DEC-067","name":"装修能不能改户型砸墙","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修能不能改户型砸墙","ola":"承重墙绝对禁止拆除","cp":["承重墙绝对禁止拆除","拆非承重墙也须物业批准","擅拆承重墙须恢复+罚款","先索要结构图纸确认","≥24cm砖墙一般为承重墙"],"detail":"装修拆改墙体：承重墙绝对禁止拆除或开洞（通常厚度≥24cm的砖墙为承重墙）；非承重墙可拆除但须向物业申报批准。擅自拆承重墙属违法需恢复原状并处罚款危及整楼结构安全。装修前务必索要结构图纸确认承重墙体位置。","legalRef":"《住宅室内装饰装修管理办法》第5条、第8条","consumerBenefit":"了解关键要点避免踩坑","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["装修能拆承重墙吗","砸墙改造要注意什么","装修改户型合法吗"]},{"id":"LIV-DEC-075","name":"装修找设计师还是自己搞","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修找设计师还是自己搞","ola":"简单翻新可不请设计师","cp":["简单翻新可不请设计师","中大户型建议请设计师","设计师核心做空间规划","收费按平米100-500元/m²","免费设计深度有限"],"detail":"是否请设计师：简单翻新可不请自己参照案例做；中大户型结构改动多建议请设计师。核心价值：空间规划/风格把控/出图/材料推荐/施工跟进。收费按平米100-500元/m²。免费设计通常绑定施工套餐深度有限。","legalRef":"行业通行做法","consumerBenefit":"了解关键要点避免踩坑","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["装修要不要请设计师","设计师能帮我做什么","装修自己设计行吗"]},{"id":"LIV-DEC-079","name":"老房子翻新装修注意什么","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"老房子翻新装修注意什么","ola":"老房水电建议全部更换","cp":["老房水电建议全部更换","墙面铲至基层防起皮","防水层可能老化须重做","拆除费比新房多15-20%","门窗老化建议更换"],"detail":"老房翻新关键：①水电管线老化建议全部更换铝线换铜线铸铁管换PPR管；②墙面铲至基层重批腻子刷漆避免新漆起皮；③防水层可能老化建议重做+闭水试验；④确认承重墙位置严禁拆改；⑤门窗老化建议更换；⑥拆除费+垃圾清运费比新房多15-20%。","legalRef":"行业通行做法","consumerBenefit":"了解关键要点避免踩坑","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["旧房改造要注意什么","老房子装修能改水电吗","老房翻新要拆到什么程度"]},{"id":"LIV-HOM-041","name":"租房住装净水器值不值","domain":"居住中","subScene":"家居家电","scene":"居住中·家居家电","cq":"净水器有必要装吗","ola":"RO反渗透出水可直饮","cp":["RO反渗透出水可直饮","超滤保留矿物质但有水垢","RO产生废水需用电","滤芯6-12个月须更换","前置过滤器粗滤保护设备"],"detail":"净水器：市政自来水出厂达标但管网二次污染风险存在。RO反渗透出水可直饮但产生废水需用电；超滤保留矿物质但不除水垢不能直饮；前置过滤器粗滤保护设备。建议RO直饮首选滤芯6-12个月更换。","legalRef":"《生活饮用水卫生标准》GB 5749-2022","consumerBenefit":"了解关键要点避免踩坑","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["家里要不要装净水器","净水器哪种类型好","RO反渗透净水器好吗"]},{"id":"LIV-MNT-001","name":"房屋保修期各部位多长时间","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"新房各部位的保修期分别是多长？从什么时候开始算？","ola":"主体50年防水5年管道2年，从竣工起算","cp":["主体结构保修为设计年限","屋面防水保修5年","管道设备安装保修2年","装修工程保修2年","交房须提供质保书"],"detail":"依据《建设工程质量管理条例》第40条，法定最低保修期限：①基础设施工程和主体结构工程为设计文件规定年限（通常50年）②屋面防水工程、有防水要求的卫生间和房间及外墙防渗漏为5年③供热与供冷系统为2个采暖期供冷期④电气管线、给排水管道、设备安装和装修工程为2年。保修期自竣工验收合格之日起算。开发商应在交房时提供住宅质量保证书和使用说明书。","legalRef":"《建设工程质量管理条例》第40条；《城市房地产开发经营管理条例》第31条","consumerBenefit":"保修期内免费修，过了期就得自费","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["房屋保修期限","开发商保修几年","住宅质保期"]},{"id":"LIV-MNT-024","name":"水管爆裂造成损失谁来赔","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"家里水管爆裂把楼下淹了，谁来赔？","ola":"自家水管业主赔楼下，公共管道物业赔","cp":["公共主管道由供水企业或物业负责","专有部分水管业主自行承担","须赔偿楼下受损住户","装修施工不当由施工方承担","建议购买家庭财产保险"],"detail":"水管爆裂造成损失的赔偿需分情况：1）公共主管道爆裂由供水企业或物业承担责任和赔偿；2）业主专有部分水管（如进户管、室内管）爆裂由业主承担，同时须赔偿楼下受损住户；3）如因装修施工不当导致水管破裂，由施工方承担。建议业主购买家庭财产保险覆盖此类风险，装修时确保水管施工质量。","legalRef":"《中华人民共和国民法典》第288条、第1165条","consumerBenefit":"分清水管爆裂责任，避免不必要的赔偿纠纷","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["水管炸了漏水谁赔","自来水管爆裂损失赔偿","水管爆裂淹了楼下谁负责"]},{"id":"LIV-MNT-034","name":"家里墙裂了是质量问题吗","domain":"居住中","subScene":"维修维护","scene":"居住中·维修维护","cq":"家里墙裂了是质量问题吗","ola":"抹灰裂缝不影响安全由施工方修","cp":["抹灰裂缝不影响安全由施工方修","承重墙裂缝须专业鉴定","保修期内开发商负责",">0.3mm裂缝建议安全鉴定","区分结构问题vs装修问题"],"detail":"墙体裂缝判断：①抹灰层/腻子层裂缝（细小网状裂纹）：多为材料收缩或施工工艺问题不影响结构安全由施工方修复；②结构裂缝（贯穿性/斜向/水平裂缝尤其承重墙上的）：可能涉及结构安全须请专业机构鉴定；③新房保修期内可要求开发商维修严重结构裂缝可要求退房+赔偿；④裂缝宽度>0.3mm或持续扩展的建议请房屋安全鉴定机构检测。","legalRef":"《建设工程质量管理条例》第40条；《住宅设计规范》GB 50096","consumerBenefit":"了解关键要点避免踩坑","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["新房墙体裂缝","墙裂了找谁","墙体裂缝是不是危房"]},{"id":"LIV-MNT-073","name":"房子保修期多长","domain":"居住中","subScene":"维修维护","scene":"居住中·维修维护","cq":"房子保修期多长","ola":"主体结构保修50年合理使用期","cp":["主体结构保修50年合理使用期","防水保修5年","管道电气保修2年","装修保修2年","从竣工验收日起算"],"detail":"房屋各部位保修期限：①地基基础和主体结构：设计文件规定的合理使用年限（一般50年）；②屋面防水/有防水要求的房间/外墙防渗漏：5年；③供热/供冷系统：2个采暖期/供冷期；④电气管线/给排水管道/设备安装：2年；⑤装修工程：2年；⑥保修期从工程竣工验收合格之日起算。超过保修期的业主自费维修（公共部分用维修基金）。","legalRef":"《建设工程质量管理条例》第40条","consumerBenefit":"了解关键要点避免踩坑","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["房屋保修期限规定","新房保修几年","管道保修期"]},{"id":"LIV-MNT-CASE-001","name":"租的房子家电坏了房东不修怎么办","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"租的房子家电坏了，房东一直拖着不修，我能自己找人修吗？","ola":"自然损坏由房东修，拒修租客可代修扣租金。","cp":["自然老化由房东维修","租客可自行维修扣租金","合同特约日常维护除外","保留维修票据作为证据"],"detail":"张某承租李某房屋，合同约定家电由租客日常维护。入住半年后空调自然老化损坏，张某要求李某维修遭拒。张某自行维修花费800元，并在次月租金中扣除。李某起诉要求支付全额租金。法院审理认为，空调损坏属自然老化，非张某使用不当所致，依据《民法典》第七百一十二条，出租人应履行维修义务。判决李某承担800元维修费，张某扣除租金行为合法。","legalRef":"《中华人民共和国民法典》第七百一十二条","consumerBenefit":"明确自然损耗维修责任，避免自行垫付后无法追偿。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["出租屋电器损坏谁负责修","租房家电老化房东拒修","租客要求房东修家电"]},{"id":"LIV-MNT-CASE-004","name":"出租屋热水器漏电房东不修能退租吗","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"租的房子热水器漏电，房东一直不修，我害怕出事能直接退租吗？","ola":"房屋设施危及安全，租客有权随时退租。","cp":["危及安全可随时退租","安全隐患不受合同限制","出租人负有安全保障义务","承租人无需承担违约金"],"detail":"陈某承租房屋，发现热水器漏电存在安全隐患，要求房东李某维修。李某以合同未约定为由拒绝。陈某认为危及人身安全，搬离房屋并通知解除合同。李某起诉要求陈某支付剩余租期租金及违约金。法院认为，租赁物危及承租人安全或健康的，即使承租人订立合同时明知，仍可随时解除合同。依据《民法典》第七百三十一条，判决驳回李某诉讼请求，确认合同解除。","legalRef":"《中华人民共和国民法典》第七百三十一条","consumerBenefit":"明确生命安全优先原则，掌握因安全隐患单方解除合同的法定权利。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租房家电漏电要求退租","租赁房屋存在安全隐患退租","房东不修漏电设备解除合同"]},{"id":"LIV-MNT-CASE-008","name":"租期没到房东说要大修让我搬走合法吗","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"租期还没到，房东说房子要大修让我赶紧搬走，还停了水电，这合法吗？","ola":"房东不得以维修为由强行赶人或断水电。","cp":["维修不得强行解除合同","断水断电属违法行为","房东需赔偿停业损失","维修应尽量减少影响"],"detail":"吴某承租房屋三年，租期第二年时，房东赵某以房屋需要全面维修为由，要求吴某限期搬出，否则不退还押金。吴某拒绝搬离，赵某采取断水断电措施。吴某起诉要求赵某恢复供水供电并赔偿营业损失。法院认为，出租人维修房屋应提前通知并尽量减少对承租人的影响，不得以此为由强行解除合同。依据《民法典》第七百一十三条，判决赵某恢复水电，并赔偿吴某停业损失5000元。","legalRef":"《中华人民共和国民法典》第七百一十三条","consumerBenefit":"明确租赁期内的居住权保障，掌握应对房东违规驱赶的法律武器。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["房东以维修为由提前收房","租房期间房东要求搬离","房屋维修影响租客居住"]},{"id":"LIV-MNT-CASE-009","name":"租房家电坏了房东不修我自己修能报销吗","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"租的房子家电自然坏了，房东不管，我自己花钱修能找他报销吗？","ola":"自然老化损坏由房东承担维修费。","cp":["自然老化非人为损坏","出租人负有维修义务","租客可自行维修","维修费用由房东承担","保留维修票据作为证据"],"detail":"张某承租李某房屋，合同约定家电由承租人维护。入住后洗衣机主板自然老化损坏，李某拒绝维修。张某自行更换主板花费300元，退租时要求李某补偿被拒。法院审理认为，虽约定承租人维护，但自然老化非人为损坏，根据《民法典》第七百一十二条，出租人应履行维修义务。判决李某补偿张某维修费300元。","legalRef":"《中华人民共和国民法典》第七百一十二条","consumerBenefit":"明确自然损坏维修责任，避免替房东承担不合理费用。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["出租屋电器损坏维修费谁出","租客自己修家电房东不给钱","租房家电自然损坏维修责任"]},{"id":"LIV-MNT-CASE-012","name":"楼上漏水把我租的房子泡了该找谁赔偿","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"楼上漏水把我租的房子和东西泡了，我该找房东还是楼上赔钱？","ola":"楼上漏水属第三方侵权，直接找楼上赔。","cp":["第三方侵权致损找侵权人","房东对非房屋缺陷免责","租客直接向楼上索赔","需固定漏水及损失证据","房东有协助维权义务"],"detail":"租客陈某承租房屋期间，因楼上业主王某家水管破裂漏水，导致陈某个人电脑及衣物受损，损失约5000元。陈某要求房东李某赔偿，李某以非房屋设施问题为由拒绝。法院认为，漏水系楼上业主侵权所致，根据《民法典》第一千一百六十五条，应由侵权人承担赔偿责任。判决楼上业主王某赔偿陈某5000元，房东李某无责。","legalRef":"《中华人民共和国民法典》第一千一百六十五条","consumerBenefit":"明确索赔对象，避免找错人耽误维权，掌握向实际侵权人索赔的路径。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["楼上漏水泡了出租屋谁赔偿","租客物品被楼上漏水淹了找谁","租房期间楼上漏水损失谁承担"]},{"id":"LIV-MNT-CASE-013","name":"租房期间暖气不热房东一直不修怎么办","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"租的房子冬天暖气不热，房东一直拖着不修，我该怎么办？","ola":"房东拒修暖气，租客可自行修并扣租金。","cp":["房东负有供暖维修义务","室温不达标可要求维修","房东拒修租客可自行维修","维修费用依法由房东承担","保留报修及缴费凭证"],"detail":"冬季供暖期，租客周某发现承租房屋暖气不热，室温仅14度。周某多次要求房东吴某维修，吴某以供暖公司问题为由推诿。周某自行请人清洗管道花费400元，室温恢复正常。退租时周某要求扣除400元租金。法院认为，根据《民法典》第七百一十三条，出租人未履行维修义务，承租人可自行维修，费用由出租人负担。判决支持周某扣减400元。","legalRef":"《中华人民共和国民法典》第七百一十三条","consumerBenefit":"掌握房东拒不维修时的自救措施，合法垫付维修费并抵扣租金。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租房暖气不热房东不管怎么办","出租屋供暖不达标能退租吗","冬天租房暖气不热怎么维权"]},{"id":"LIV-MNT-CASE-015","name":"租客养猫抓坏皮沙发房东要求全额赔偿合理吗","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"我租的房子没禁养猫，猫抓坏了房东的皮沙发，房东让我赔原价合理吗？","ola":"宠物损坏家具需赔偿，但按折旧现值算。","cp":["租客对宠物损坏负有赔偿责任","赔偿应按物品折旧后现值计算","全额赔偿原价不合理","需保留物品购买及折旧证据","合同可提前约定宠物损坏条款"],"detail":"租客林某承租房屋，合同未禁止养宠。林某饲养的宠物猫将屋内皮沙发抓破。退租时，房东黄某要求林某按沙发原价5000元全额赔偿。林某认为沙发已使用5年，只愿赔偿折旧后价值。法院认为，根据《民法典》第七百一十四条，承租人应妥善保管租赁物，因保管不善造成毁损应赔偿。结合沙发折旧率，判决林某按评估现值1500元进行赔偿。","legalRef":"《中华人民共和国民法典》第七百一十四条","consumerBenefit":"了解宠物损坏物品的合理赔偿标准，避免被房东要求按原价全额赔偿。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租客养宠物损坏家具怎么赔","租房养猫抓坏沙发赔偿标准","租客宠物损坏房屋设施赔偿"]},{"id":"LIV-MNT-CASE-016","name":"租房时空调自然老化不制冷房东拒修怎么办","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"租的房子空调自然老化坏了，房东不肯修也不肯换，我该怎么办？","ola":"空调自然老化报废，房东需承担重置费。","cp":["附属设施自然老化由房东负责","房东有保持设施可用的义务","租客可自行替换并索赔","需获取专业维修报废鉴定","保留维修工单及购买凭证"],"detail":"夏季高温，租客杨某发现承租房屋空调不制冷，加氟后仍无法使用，维修工判定压缩机自然老化报废。杨某要求房东更换，房东以“合同未约定换空调”拒绝。杨某自行购买二手空调替换花费800元。法院审理认为，空调属房屋附属设施，自然老化报废非承租人过错。依据《民法典》第七百一十二条，出租人应保持租赁物符合约定用途。判决房东承担800元重置费用。","legalRef":"《中华人民共和国民法典》第七百一十二条","consumerBenefit":"明确房屋附属设施自然老化的维修与重置责任，保障居住舒适度。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租房空调坏了房东不修怎么办","出租屋空调不制冷维修费谁出","租房空调自然老化房东拒修"]},{"id":"LIV-MNT-CASE-017","name":"出租屋燃气热水器漏气导致中毒房东要赔钱吗","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"租的房子燃气热水器漏气导致我中毒，房东需要赔偿我的医药费吗？","ola":"房东提供不合格设备致人损害需全赔。","cp":["房东须保证设施符合安全标准","提供淘汰产品属重大过错","房东需承担人身损害赔偿责任","租客无过错时房东全责","保留医疗记录与事故鉴定"],"detail":"租客赵某在出租屋洗澡时，因房东提供的直排式燃气热水器漏气导致一氧化碳中毒，住院花费2万元。赵某要求房东赔偿。房东辩称赵某使用不当。法院查明，该热水器属国家明令淘汰产品，房东未提供安全设备。根据《民法典》第七百零八条，出租人应保证租赁物符合安全使用标准。判决房东承担全部医疗费及营养费共计2.5万元。","legalRef":"《中华人民共和国民法典》第七百零八条","consumerBenefit":"明确房东对房屋安全设施的法定保障义务，掌握人身受损时的索赔依据。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["出租屋燃气泄漏中毒房东责任","租房热水器漏气中毒能索赔吗","出租屋燃气设备安全隐患赔偿"]},{"id":"LIV-MNT-CASE-019","name":"租房期间窗户玻璃突然自爆砸伤人谁负责","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"我租的房子窗户玻璃突然自爆砸伤了楼下的人，我要承担赔偿责任吗？","ola":"玻璃自然老化自爆伤人，由房东赔偿。","cp":["玻璃自爆属设施自然老化","所有人承担脱落坠落侵权责任","租客无过错不承担赔偿责任","房东需证明自身无过错","受害人可直接起诉房东索赔"],"detail":"租客王某承租房屋期间，卧室窗户玻璃因老化突然自爆，碎片掉落砸伤楼下行人张某，张某医疗费共计8000元。张某起诉房东与租客。法院查明，玻璃自爆系自然老化所致，王某使用无不当。根据《民法典》第一千二百五十三条，建筑物设施脱落坠落造成损害，所有人不能证明自己没有过错的，应承担责任。判决房东承担全部赔偿责任，租客无责。","legalRef":"《中华人民共和国民法典》第一千二百五十三条","consumerBenefit":"明确房屋设施自然老化致害的责任归属，避免租客替房东承担侵权赔偿责任。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租房窗户玻璃自爆伤人谁赔偿","出租屋玻璃掉落砸伤人责任","租客窗户玻璃碎了砸到路人"]},{"id":"LIV-MNT-CASE-020","name":"租客出门忘关水龙头淹了楼下怎么划分责任","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"我租的房子出门忘关水龙头把楼下淹了，赔偿责任怎么划分？","ola":"租客过失导致漏水，由租客全额赔偿。","cp":["租客使用不当致损需担责","房东对租客过失漏水免责","租客需全额赔偿邻居损失","房东有协助处理纠纷义务","建议租客购买租客责任险"],"detail":"租客陈某出门忘关水龙头，导致承租房屋积水，渗漏至楼下邻居李某家，造成李某地板及家具受损，定损1.2万元。李某要求房东与租客共同赔偿。法院认为，漏水系陈某使用不当过失所致。根据《民法典》第一千一百六十五条，行为人因过错侵害他人民事权益应担责。同时依据第七百一十四条，承租人未妥善保管租赁物致损应赔偿。判决陈某承担全部1.2万元赔偿，房东无责。","legalRef":"《中华人民共和国民法典》第一千一百六十五条","consumerBenefit":"明确因个人过失导致漏水的法律责任，提示购买相关保险转移风险。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租客忘关水淹了楼下谁赔偿","租房漏水淹了楼下责任划分","租客使用不当导致漏水赔偿"]},{"id":"LIV-MNT-CASE-022","name":"退租时房东说墙面自然泛黄要扣押金怎么办","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"退租时房东说墙面自然泛黄旧了，要扣我押金重新刷墙，这合理吗？","ola":"墙面自然泛黄属正常损耗，房东无权扣押金。","cp":["自然泛黄属正常居住损耗","正常损耗承租人不承担赔偿","房东无权以此扣除押金","需区分正常损耗与人为损坏","退租时建议拍照留存证据"],"detail":"租客林某退租时，房东赵某以墙面自然泛黄、有轻微使用痕迹为由，扣除2000元押金作为重新粉刷费用。林某认为属正常损耗。法院审理认为，根据《民法典》第七百一十条，承租人按照约定方法使用租赁物，致使租赁物受到损耗的，不承担赔偿责任。墙面泛黄属正常居住损耗，非人为恶意破坏。判决房东全额退还2000元押金。","legalRef":"《中华人民共和国民法典》第七百一十条","consumerBenefit":"明确正常损耗与人为损坏的界限，避免被房东以折旧为由恶意克扣押金。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["退租墙面自然泛黄扣押金合理吗","租房退租墙面发黄房东扣钱","租客退租房屋自然损耗赔偿"]},{"id":"LIV-MNT-CASE-024","name":"出租屋电线老化引发火灾租客需要担责吗","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"租的房子电线老化短路起火了，我需要承担赔偿责任吗？","ola":"电线老化引发火灾，租客无违规不担责。","cp":["电线老化属房东维修义务范围","租客无违规使用不承担责任","火灾损失由房屋所有人承担","消防认定书是关键证据","房东需对相邻方承担赔偿责任"],"detail":"租客王某承租房屋期间，因墙内电线老化短路引发火灾，造成房屋部分烧毁及邻居财产损失。消防认定起火原因为线路老化。房东要求王某赔偿损失。法院查明，王某未违规使用大功率电器，火灾纯属线路老化所致。根据《民法典》第七百一十二条，出租人应履行租赁物维修义务。判决房东自行承担房屋损失，并由房东赔偿邻居损失，租客王某无责。","legalRef":"《中华人民共和国民法典》第七百一十二条","consumerBenefit":"明确房屋固有安全隐患导致事故的责任归属，避免租客替房东背锅。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["出租屋电线老化火灾租客责任","租房电线短路起火租客要赔吗","出租屋火灾隐患房东维修义务"]},{"id":"LIV-MNT-CASE-025","name":"租房发现热水器漏电房东隐瞒情况能索赔吗","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"刚租的房子发现热水器漏电，房东之前故意没说，我能退租并要求赔偿吗？","ola":"房东隐瞒漏电隐患，租客可退租索赔。","cp":["房东隐瞒安全隐患构成违约","危及人身安全可随时解除合同","承租人无需承担违约责任","房东需赔偿实际产生的医疗费","保留检测报告与就医记录"],"detail":"租客李某入住出租屋次日，发现热水器漏电被轻微电击。经检测，热水器接地线失效且房东明知此情况未告知。李某要求退租并索赔体检费及违约金。法院认为，房东交付的房屋存在严重安全隐患，危及人身安全。依据《民法典》第七百三十一条，租赁物危及安全健康的，承租人可随时解除合同。判决解除合同，房东退还押金租金并赔偿体检费。","legalRef":"《中华人民共和国民法典》第七百三十一条","consumerBenefit":"掌握房屋存在安全隐患时的法定解除权及索赔权，保障人身安全。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租房热水器漏电房东隐瞒索赔","出租屋电器漏电房东未告知","租房发现安全隐患能退租吗"]},{"id":"LIV-MNT-CASE-026","name":"租客垫付维修费后房东不给钱能直接抵租金吗","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"房东一直不修坏掉的水管，我自己垫钱修了，能直接从下个月租金里扣除吗？","ola":"房东拒修，租客垫付维修费可抵扣租金。","cp":["房东拖延维修租客可自行维修","垫付的合理维修费由房东承担","租客有权直接从租金中抵扣","需提前履行通知催告义务","保留报修记录及维修发票"],"detail":"租客赵某承租房屋，水管破裂后多次通知房东维修，房东以各种理由拖延。赵某为避免损失扩大，自行找水工维修垫付500元。次月交租时，赵某直接扣除500元。房东起诉要求全额支付租金。法院认为，根据《民法典》第七百一十三条，承租人在租赁物需要维修时可要求出租人在合理期限内维修，出租人未履行的，承租人可自行维修，费用由出租人负担。判决支持赵某抵扣500元。","legalRef":"《中华人民共和国民法典》第七百一十三条","consumerBenefit":"掌握合法抵扣租金的条件与程序，避免被房东反诉拖欠租金。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租客垫付维修费能抵扣租金吗","房东不修房子租客自己修扣租金","租房维修费房东不报销能抵租金"]},{"id":"LIV-MNT-CASE-027","name":"一楼下水管道反水把租的房子淹了找谁赔","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"我租的一楼房子下水道反水把东西都泡了，该找物业还是房东赔钱？","ola":"公共管道反水，物业与房东按过错赔偿。","cp":["公共管道堵塞物业负有管理责任","房东需提供合格防反水设施","租客无过错不承担损失","物业与房东按过错比例分担","需保留反水现场及损失证据"],"detail":"租客孙某承租一楼房屋，因公共下水主管道堵塞导致污水反水，淹毁屋内家具及地板，损失1.5万元。孙某起诉房东与物业。法院查明，物业未能提供定期疏通主管道的记录，存在管理过错；房东房屋设计无防反水装置。根据《民法典》第一千一百六十五条及第一千二百五十四条，判决物业公司承担70%赔偿责任，房东承担30%补充责任，租客无责。","legalRef":"《中华人民共和国民法典》第一千一百六十五条","consumerBenefit":"明确公共管道反水的责任主体，掌握向物业和房东分别索赔的依据。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["一楼下水反水泡了出租屋谁赔","租房一楼下水道反水责任划分","出租屋下水管道反水损失赔偿"]},{"id":"LIV-MNT-CASE-028","name":"租房发现墙体隔音极差能要求房东整改吗","domain":"居住中","subScene":"房屋维护","scene":"居住中·房屋维护","cq":"租的房子墙体隔音特别差，吵得睡不着，能要求房东花钱做隔音整改吗？","ola":"隔音未违反强制标准，房东无强制整改义务。","cp":["隔音差未违反强制标准不属违建","合同未约定则无整改义务","房东不构成违约无需赔偿","租客可协商解除合同","建议看房时重点测试隔音"],"detail":"租客周某承租房屋后，发现墙体隔音极差，严重影响休息。周某要求房东加装隔音层或退租。房东称房屋建设符合当时标准，拒绝整改。法院查明，该房屋属合法建筑，隔音虽差但未违反国家强制性建筑标准，且合同未约定隔音标准。根据《民法典》第七百零八条，出租人应保证租赁物符合约定用途。因无特殊约定，判决房东无需强制整改，周某若无法忍受可协商解除合同，但房东不承担违约责任。","legalRef":"《中华人民共和国民法典》第七百零八条","consumerBenefit":"明确房屋非结构性瑕疵的维权界限，提示签约前充分实地体验房屋状况。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租房隔音差能要求房东整改吗","出租屋隔音不好能退租吗","租房墙体隔音差影响休息"]},{"id":"LIV-NBR-CASE-003","name":"楼上小孩天天跑跳噪音大怎么维权","domain":"居住中","subScene":"邻里纠纷","scene":"居住中·邻里纠纷","cq":"楼上小孩跑跳太吵怎么让他们隔音？","ola":"楼上生活噪音超标需采取隔音措施。","cp":["生活噪音需控制在合理限度","监护人需管理未成年人行为","噪声污染防治法适用","判决采取有效隔音措施"],"detail":"孙某居住在楼下，楼上周某家小孩经常在夜间及午休时间跑跳，产生较大噪音。孙某多次与周某交涉并报警，周某虽加装了部分地垫但效果不佳。孙某起诉要求周某采取有效隔音措施。法院审理认为，周某未尽到管理义务，噪音超出合理限度。依据《民法典》第二百九十四条及《噪声污染防治法》第六十五条，判决周某采取铺设隔音地毯等有效措施，控制噪音排放。","legalRef":"《中华人民共和国民法典》第二百九十四条、《中华人民共和国噪声污染防治法》第六十五条","consumerBenefit":"依法要求楼上采取实质性降噪措施，保障休息权。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["楼上小孩跑跳扰民","楼上孩子蹦跳噪音","楼上儿童活动噪音"]},{"id":"LIV-NBR-CASE-005","name":"邻居把房子改成群租房太吵怎么投诉","domain":"居住中","subScene":"邻里纠纷","scene":"居住中·邻里纠纷","cq":"邻居搞群租房太乱怎么让他搬走？","ola":"违规群租改变房屋用途需拆除恢复。","cp":["擅自改变房屋使用性质违法","群租影响相邻方合法权益","违反房屋租赁管理规定","判决拆除隔断恢复原状"],"detail":"吴某将房屋违规打隔断，出租给8名租客，导致楼道人员杂乱、夜间噪音频发，严重影响邻居陈某生活。陈某向城管及住建部门投诉，并诉至法院。法院查明吴某改变房屋使用性质，违反当地房屋租赁管理规定。依据《民法典》第二百七十九条及《商品房屋租赁管理办法》第八条，判决吴某拆除隔断，恢复房屋原状，停止群租行为。","legalRef":"《中华人民共和国民法典》第二百七十九条、《商品房屋租赁管理办法》第八条","consumerBenefit":"掌握群租房投诉与诉讼依据，维护居住环境安全。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["邻居群租房扰民","隔壁群租房","邻居房屋打隔断出租"]},{"id":"LIV-NBR-CASE-024","name":"邻居把房子改成群租房有安全隐患怎么投诉","domain":"居住中","subScene":"邻里关系","scene":"居住中·邻里关系","cq":"邻居搞群租房存在消防隐患我向谁举报？","ola":"向城管或消防部门举报，责令拆除隔断。","cp":["擅自打隔断群租","用电及消防隐患大","违反群租管理规定","行政部门责令整改","可要求拆除并罚款"],"detail":"业主孙某将房屋打隔断出租给10人居住，导致用电负荷过大频繁跳闸，且存在严重消防隐患。邻居周某多次向物业和城管投诉。城管及消防部门现场核查，认定孙某擅自改变房屋内部结构，违反群租房管理规定。相关部门下达整改通知书，责令孙某限期拆除隔断，恢复房屋原结构，并对孙某处以罚款，消除安全隐患。","legalRef":"《商品房屋租赁管理办法》第八条","consumerBenefit":"掌握群租房举报途径，及时消除居住环境的消防及安全隐患。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["邻居群租房","房屋打隔断群租","群租房安全隐患"]},{"id":"LIV-NBR-CASE-026","name":"邻居养的大型犬不拴绳吓到我家小孩怎么办","domain":"居住中","subScene":"邻里关系","scene":"居住中·邻里关系","cq":"邻居遛狗不拴绳吓到我家孩子能索赔吗？","ola":"未拴绳致人受惊受伤，狗主需全额赔偿。","cp":["遛狗未拴犬绳","未采取安全措施","导致他人受惊受伤","违反养犬管理规定","承担侵权赔偿责任"],"detail":"陈某在小区公共区域遛养的大型犬未拴犬绳，犬只突然扑向正在玩耍的7岁儿童王某，虽未咬伤但导致王某受惊吓摔倒擦伤，并产生严重心理恐惧。王某家长报警并诉至法院。法院审理认为，陈某违反养犬管理规定，未对动物采取安全措施，造成他人损害，应当承担侵权责任。判决陈某赔偿医疗费及精神抚慰金共计3000元。","legalRef":"《中华人民共和国民法典》第一千二百四十六条","consumerBenefit":"明确宠物伤人/吓人索赔依据，有效保护家人特别是儿童的人身安全。","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["邻居养狗不拴绳","大型犬不拴绳","邻居狗吓到小孩"]},{"id":"LIV-PMG-001","name":"物业费包含什么不包含什么","domain":"居住中","subScene":"物业管理","scene":"居住中·物业管理","cq":"物业费交了为什么电梯坏了还要另收维修费？","ola":"物业费含日常维保不含大修，大修用维修基金","cp":["含公共区域保洁秩序绿化","含电梯运行和维保费用","不含专有部分维修","不含停车管理和特约服务"],"detail":"物业费包含：物业管理区域内的公共区域保洁、秩序维护、绿化养护、公共设施设备日常运行维护（含电梯电费和维保费）、物业管理服务人员薪酬等。不包含：业主专有部分维修、公共区域水电费（另行分摊）、停车管理费（另行收取）、有偿特约服务费等。物业费标准由物业服务合同约定。","legalRef":"《物业管理条例》第40条、第44条","consumerBenefit":"清楚物业费边界，不该掏的钱不掏","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["物业费包括哪些服务","物业费收费标准","物业费含不含电梯费"]},{"id":"LIV-PMG-010","name":"物业有义务公布收支吗","domain":"居住中","subScene":"物业管理","scene":"居住中·物业管理","cq":"电梯广告收入去了哪里？物业不公布收入怎么办？","ola":"公共收益须公示归业主，拒公示可投诉房管","cp":["物业须公示服务事项和质量标准","须公示物业费和公共收益收支","公共收益归全体业主","拒公示可向房管部门投诉"],"detail":"物业应定期公示以下信息：①物业服务合同约定的服务事项及质量标准；②物业费收支情况；③利用物业共用部位和设施进行经营的收益及使用情况（如电梯广告、地面停车费）；④专项维修资金的收支情况。业主有权查阅，物业拒不公示可向房管部门投诉。","legalRef":"《物业管理条例》第6条、第54条","consumerBenefit":"业主有权知道公共收益去向，监督物业用钱","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["物业收支公示要求","物业费使用情况公开","物业公共收益要公示吗"]},{"id":"LIV-PMG-038","name":"物业不作为怎么换掉","domain":"居住中","subScene":"物业管理","scene":"居住中·物业管理","cq":"物业不作为怎么换掉","ola":"须成立业主大会和业委会","cp":["须成立业主大会和业委会","业主大会表决解聘+选聘","双过半业主同意即可换","原物业15日内退出移交","未成立业委会找社区协调"],"detail":"更换物业的法定程序：①前提：须成立业主大会并选举业委会；②业主大会表决决定解聘现物业（双过半业主同意）；③选聘新物业：业主大会表决选聘新物业服务企业；④原物业须在约定期限或15日内退出并移交资料拒绝退出的可起诉强制退出；⑤未成立业主大会的由社区居委会协调。注意新老物业交接期不可出现管理真空。","legalRef":"《中华人民共和国民法典》第285条；《物业管理条例》第21条、第38条","consumerBenefit":"了解关键要点避免踩坑","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["物业服务差能换吗","怎么更换物业公司","换物业要走什么流程"]},{"id":"LIV-PMG-282","name":"小区公共收益钱去哪了怎么查","domain":"居住中","subScene":"物业管理","scene":"居住中·物业管理","cq":"电梯里的广告费到底进谁口袋了？","ola":"公共收益归全体业主，物业必须公示。","cp":["公共收益归全体业主","物业必须定期公示","隐瞒挪用可起诉返还","业委会可委托审计"],"detail":"依据《民法典》第282条，小区公共区域产生的收益（如电梯广告、公共停车费）归全体业主共有。物业需定期公示收支，若隐瞒或挪用，业主可要求审计并返还。实践中，物业常以“补贴亏损”为由拒交，业主需通过业委会或街道办介入核查账目，必要时提起诉讼。","legalRef":"《中华人民共和国民法典》第282条","consumerBenefit":"明确公共收益归属，拿回本该属于业主的钱。","tags":{"clientType":["buyer","seller"],"stage":"mid,post","layer":"术","meetingPhase":["见前","见中"]},"alias":["小区公共收益查询","电梯广告费归谁","公共区域收益公示"]},{"id":"LIV-PMG-285","name":"申请动用维修基金需要什么流程","domain":"居住中","subScene":"物业管理","scene":"居住中·物业管理","cq":"小区要修漏水屋顶，申请维修基金要多久？","ola":"需双三分之二参与表决且双过半同意。","cp":["需双三分之二业主参与","参与表决双过半同意","方案必须依法公示","紧急情况可走绿色通道"],"detail":"依《民法典》第278条，动用维修资金需由专有部分面积占比三分之二以上且人数占比三分之二以上的业主参与表决，并经参与表决双过半同意。流程包括：物业提出方案、业委会审核、业主大会表决、公示、住建部门备案后划拨。应急维修可走绿色通道。","legalRef":"《中华人民共和国民法典》第278条","consumerBenefit":"清晰掌握申请步骤，避免因流程不合规导致资金无法拨付。","tags":{"clientType":["buyer","seller"],"stage":"mid,post","layer":"术","meetingPhase":["见前","见中"]},"alias":["动用大修基金步骤","维修资金审批流程","申请房屋养老金"]},{"id":"LIV-PMG-286","name":"怎么查小区电梯广告收益明细","domain":"居住中","subScene":"物业管理","scene":"居住中·物业管理","cq":"我想知道电梯里换的广告牌一年能赚多少钱？","ola":"属公共收益，物业必须定期公示明细。","cp":["电梯广告费属公共收益","物业需定期公示账目","业主有权查阅明细","拒不开示可向部门投诉"],"detail":"电梯广告收益属小区公共收益，依《物业管理条例》第54条，物业应定期在小区显著位置公示公共收益收支情况。业主有权查阅账目。若物业拒绝公示，业主可向街道办、住建局投诉，或由业委会委托第三方审计机构进行专项审计，确保收益透明。","legalRef":"《物业管理条例》第54条","consumerBenefit":"掌握查账途径，确保公共区域产生的收益透明化。","tags":{"clientType":["buyer","seller"],"stage":"mid,post","layer":"术","meetingPhase":["见前","见中"]},"alias":["电梯广告费查询","公共收益查账","查小区广告收入"]},{"id":"LIV-SAF-006","name":"阳台栏杆高度不够孩子有坠落风险","domain":"居住中","subScene":"居住安全","scene":"居住中·居住安全","cq":"我家阳台栏杆比较矮，小孩子爬上去会不会掉下去？","ola":"多层≥1.05米高层≥1.10米，不达标加装防护网","cp":["多层阳台栏杆净高≥1.05米","高层阳台栏杆净高≥1.10米","杆件间距≤0.11米防钻出","窗台<0.9米须防护措施","加装防护网不影响逃生"],"detail":"住宅阳台栏杆高度国家标准：《住宅设计规范》GB50096规定低层多层住宅阳台栏杆净高不低于1.05米，高层住宅不低于1.10米，栏杆垂直杆件间净距不大于0.11米（防儿童钻出）。窗台低于0.9米时应有防护措施。如交付时栏杆高度不达标可要求开发商整改；自行加装防护栏时不得影响消防逃生。有儿童家庭建议额外加装隐形防护网。","legalRef":"《住宅设计规范》GB50096-2011第5.6.3条、第5.8.2条","consumerBenefit":"栏杆高度有国家标准，不达标可要求整改","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["阳台栏杆高度标准","阳台安全高度","儿童坠落风险"]},{"id":"LIV-SAF-011","name":"住宅电梯安全使用要注意什么","domain":"居住中","subScene":"居住安全","scene":"居住中·居住安全","cq":"小区电梯经常出故障，电梯多久检修一次才安全？","ola":"维保15天一次，每年须年检合格才能用","cp":["不得超载和阻挡电梯门","装修运货须防护不超载","儿童须成人陪同乘梯","维保周期15日一次","每年须经特种设备年检"],"detail":"住宅电梯安全使用规范：①不得超载运行（额定载重标注在轿厢内）②装修运货须用防护垫保护轿厢，不得超载③不得用物品阻挡电梯门自动关闭④儿童须成人陪同乘梯⑤禁止在电梯内蹦跳摇晃⑥电梯维保周期为15日一次（TSG T5002规定）⑦每年须经特种设备检验机构检验合格。发现电梯异响、顿挫、不平层等异常应立即报物业停用检修。","legalRef":"《特种设备安全法》第35条；《电梯维护保养规则》TSG T5002第6条","consumerBenefit":"电梯有强制维保和年检制度，保障乘梯安全","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["电梯使用注意事项","电梯超载危险","电梯安全规定"]},{"id":"LIV-SAF-026","name":"独居老人安全怎么保障","domain":"居住中","subScene":"居住安全","scene":"居住中·居住安全","cq":"老人一个人住，怎么保障安全？","ola":"装扶手防滑、配求助手环、装烟感报警器","cp":["卫生间装扶手和防滑垫","佩戴一键求助手环","安装烟感和燃气报警器","定期与邻居社区保持联系","手机设置紧急联系人","防诈骗不轻信电话推销"],"detail":"独居老人面临跌倒、突发疾病、诈骗、火灾等多重安全风险。建议保障措施：1）卫生间安装扶手和防滑垫，预防跌倒；2）佩戴一键求助手环或安装紧急呼叫装置；3）安装智能烟感和燃气报警器；4）定期与邻居或社区保持联系；5）防诈骗教育，不轻信电话推销；6）手机设置紧急联系人快捷拨号。","legalRef":"《老年人权益保障法》第13条","consumerBenefit":"降低独居老人意外风险，家人更安心","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["老人独居安全措施","独居老人防摔倒","独居老人应急求助"]},{"id":"LIV-SAF-029","name":"卫生间怎么做防滑防跌处理","domain":"居住中","subScene":"居住安全","scene":"居住中·居住安全","cq":"家里老人腿脚不好，怎么防止跌倒？","ola":"卫生间装扶手防滑垫，走廊装夜灯，地面清障碍","cp":["卫生间铺防滑垫装扶手","保持地面干燥无障碍","走廊卧室安装夜灯","常用物品放在易取高度","穿防滑鞋不穿拖鞋走动"],"detail":"老人跌倒是居家安全的首要威胁，预防措施：1）卫生间铺设防滑地垫，安装扶手（马桶旁和淋浴区）；2）保持地面干燥无障碍物，电线收好不绊脚；3）走廊和卧室安装夜灯，方便起夜；4）床头安装可触达的照明开关和电话；5）常用物品放在易取高度，避免攀爬凳子；6）穿防滑鞋，不穿拖鞋走动。卫生间和楼梯是跌倒高发区域，需重点防护。","legalRef":"《中华人民共和国民法典》第288条","consumerBenefit":"有效预防老人跌倒，减少骨折等严重伤害","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["老人防摔倒措施","老人跌倒预防家居改造","老年人居家防跌倒"]},{"id":"LIV-SAF-057","name":"家里要不要装烟雾报警器","domain":"居住中","subScene":"居住安全","scene":"居住中·居住安全","cq":"家里要不要装烟雾报警器","ola":"夜间熟睡时争取逃生时间","cp":["夜间熟睡时争取逃生时间","光电烟感家用不易误报","装卧室客厅天花板中央","每月测试每年换电池","出租房部分城市强制安装"],"detail":"家庭烟感建议：①作用：火灾初起阶段发出声光报警争取黄金逃生时间；②类型：光电烟感（家用推荐不易误报）vs离子烟感（响应快但含微量放射源）；③安装位置：卧室和客厅天花板中央走廊距墙角≥0.5m厨房装距灶2-3m防误报；④维护：每月按测试键每年换电池（或选10年锂电池款）每2年清洁传感器；⑤部分城市要求出租房强制安装联网烟感。","legalRef":"《建筑设计防火规范》GB 50016；《住房租赁条例》相关要求","consumerBenefit":"了解关键要点避免踩坑","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["烟感报警器有用吗","家里装烟感有必要吗","烟感报警器怎么选"]},{"id":"OWN-AST-CASE-003","name":"买卖不破租赁遇到拆迁怎么补偿","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"租的房子遇到拆迁，我能拿到哪些补偿？","ola":"征收致合同解除，租客可获装修搬迁补偿，不分产权款。","cp":["公益征收导致合同解除","租客无权分产权补偿款","租客可主张装修及搬迁费","房东需退剩余租金和押金","买卖不破租赁不适用于征收"],"detail":"孙某将房屋出租给周某，租期3年。第2年时，该房屋被纳入政府征收范围，孙某与征收部门签订补偿协议。周某要求继续履行租赁合同或分享拆迁补偿。法院审理认为，因公共利益需要征收房屋，租赁合同无法继续履行，属于不可归责于双方的原因。法院判决解除租赁合同，孙某退还周某剩余租金及押金，周某无权要求分享房屋产权性质的拆迁补偿，但可主张装修残值及搬迁损失。","legalRef":"《中华人民共和国民法典》第七百二十五条","consumerBenefit":"厘清拆迁补偿分配规则，避免业主与租客因补偿款产生纠纷。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["出租房遇到拆迁租客怎么补偿","买卖不破租赁拆迁补偿归谁","房子卖了租客能继续住吗"]},{"id":"OWN-AST-CASE-005","name":"租客在出租屋内发生意外房东要赔吗","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"在租的房子里因为电器漏电受伤，房东需要赔偿吗？","ola":"房东未提供安全设施致租客受伤，需按过错比例赔偿。","cp":["房东需保证设施安全可用","超龄电器隐患房东担主责","租客自身过错承担次责","出租前务必进行安全检修","保留设施交接及检修记录"],"detail":"租客林某在承租房屋内使用热水器时因漏电触电受伤。经查，该热水器已超过安全使用年限，且房东张某在出租前未进行安全检修。林某起诉张某要求赔偿医疗费等损失。法院认为，张某作为出租人，未提供符合安全使用条件的房屋及设施，存在过错，应承担主要赔偿责任。同时，林某作为成年人未尽到合理注意义务，承担次要责任。判决张某赔偿林某70%的损失。","legalRef":"《中华人民共和国民法典》第七百零八条","consumerBenefit":"明确出租屋安全保障义务，督促业主排查隐患，降低侵权赔偿风险。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租客在出租屋摔伤房东赔吗","出租屋发生安全事故房东责任","租客洗澡触电房东要赔偿吗"]},{"id":"OWN-AST-CASE-006","name":"提前收回出租房怎么支付违约金","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"房东提前让我搬走，我能要求哪些赔偿？","ola":"房东提前解约需按合同支付违约金及合理搬迁损失。","cp":["按合同约定支付违约金","违约金与搬家费可并存","租金差价需证明实际损失","提前通知并给予合理搬离期","协商解除需签订书面协议"],"detail":"房东刘某与租客马某签订2年租赁合同，约定月租金4000元，违约金为2个月租金。履约10个月时，刘某因需自用房屋，提前通知马某解约。马某同意搬离，但要求刘某支付违约金、剩余租期租金差价及搬家费。法院审理认为，刘某单方违约，应按合同约定支付违约金8000元。对于马某主张的搬家费，法院结合实际情况酌情支持1000元，但剩余租期租金差价因马某已找到同等条件房屋，未予支持。","legalRef":"《中华人民共和国民法典》第五百七十七条","consumerBenefit":"掌握提前解约的赔偿标准，避免业主因盲目违约承担过高赔偿。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["房东提前解约怎么赔违约金","房东违约提前收房赔偿标准","租期未满房东要求搬走怎么补偿"]},{"id":"OWN-AST-CASE-008","name":"房屋漏水殃及楼下租客和房东谁赔","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"租的房子漏水把楼下淹了，我要承担全部赔偿吗？","ola":"租客使用不当致漏水担主责，房东承担连带责任。","cp":["实际使用人操作不当担主责","房东对房屋设施负管理义务","房东通常承担连带赔偿责任","房东赔偿后可向租客追偿","及时止损并保留现场证据"],"detail":"房东吴某将房屋出租给郑某。某日，郑某出门未关紧水龙头，导致房屋积水渗漏至楼下邻居王某家，造成王某家地板及墙面受损，损失评估为8000元。王某起诉吴某和郑某要求赔偿。法院审理认为，郑某作为实际使用人，因使用不当导致漏水，应承担主要赔偿责任。吴某作为房屋所有权人，对房屋设施负有管理义务，承担连带赔偿责任。判决郑某赔偿8000元，吴某承担连带责任。","legalRef":"《中华人民共和国民法典》第一千一百六十五条","consumerBenefit":"明确漏水事故中的责任划分，指导业主和租客妥善处理相邻纠纷。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["出租屋漏水淹了楼下谁赔偿","租客使用不当导致漏水谁负责","房屋管道老化漏水殃及邻居"]},{"id":"OWN-AST-CASE-012","name":"房屋自然损耗维修费该谁出","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"出租屋里的家电自然老化坏了，维修费该谁出？","ola":"房屋设施自然损耗由房东承担维修责任及费用。","cp":["自然损耗维修责任在房东","格式条款免除房东义务无效","租客可代为维修并扣除费用","人为损坏维修责任在租客","交接时明确设施新旧状态"],"detail":"租客何某承租房屋期间，屋内原装空调因使用年限过长导致压缩机损坏，无法制冷。何某要求房东曹某维修，曹某以合同约定“租客负责屋内设施维修”为由拒绝。何某自行维修花费800元，并在下期租金中扣除。曹某起诉要求何某支付租金。法院审理认为，空调损坏属于自然损耗，虽合同有约定，但曹某作为出租人仍负有保持租赁物符合约定用途的义务。判决何某无需承担维修费，曹某需返还扣除的800元租金。","legalRef":"《中华人民共和国民法典》第七百一十二条","consumerBenefit":"厘清自然损耗与人为损坏的维修责任边界，减少租赁期间的维修纠纷。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["出租屋家电自然坏了谁修","房屋自然老化维修费谁承担","租客使用导致家电损坏谁修"]},{"id":"OWN-AST-CASE-014","name":"长租公寓暴雷房东如何驱赶租客","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"长租公寓跑路了，我交了一年租金，房东还能赶我走吗？","ola":"长租公寓违约房东可解约收房，租客损失向公寓追偿。","cp":["运营方违约房东可解除委托","房东有权要求租客腾退房屋","租客损失应向运营方追偿","房东收房需发书面解约通知","严禁采取暴力或断水断电清退"],"detail":"房东马某将房屋委托给某长租公寓运营，约定运营方按月支付租金。运营方又与租客郭某签订1年合同，郭某一次性支付1年租金。3个月后，运营方暴雷跑路，未向马某支付后续租金。马某向郭某发送解约通知，要求郭某搬离。郭某拒绝。法院审理认为，马某与运营方为委托合同关系，运营方违约，马某有权解除委托合同。但郭某与运营方的租赁合同对马某不直接生效，马某有权要求郭某腾退。郭某损失应向运营方追偿。","legalRef":"《中华人民共和国民法典》第九百三十三条","consumerBenefit":"明确长租公寓暴雷后的法律责任，指导业主和租客依法维护自身权益。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["长租公寓跑路房东怎么收房","长租公寓暴雷租客被赶怎么办","托管公司跑路房东和租客纠纷"]},{"id":"OWN-AST-CASE-015","name":"租客违约提前退租押金退不退","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"租客提前退租，房东有权扣光所有押金吗？","ola":"租客违约可扣押金，但违约金过高可请求法院调整。","cp":["提前退租构成违约可扣押金","违约金过分高于损失可调整","房东需证明实际空置损失","押金与违约金不能重复主张","协商解约需明确押金处理方式"],"detail":"租客林某与房东谢某签订2年租赁合同，约定押金2个月租金。履约8个月时，林某因工作调动要求提前退租。谢某同意解除合同，但没收全部押金作为违约金。林某认为押金过高，起诉要求退还部分押金。法院审理认为，林某提前退租构成违约，谢某有权扣除押金作为违约金。但考虑到谢某在1个月后即找到新租客，实际损失较小，约定的违约金过分高于实际损失。法院酌情调整违约金为1个月租金，判决谢某退还林某1个月押金。","legalRef":"《中华人民共和国民法典》第五百八十五条","consumerBenefit":"掌握押金扣除与违约金调整的法律规定，避免业主因过度扣除押金败诉。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租客违约退租押金怎么扣","提前解约租客押金不退合法吗","租客中途退租押金和租金怎么算"]},{"id":"OWN-OPS-006","name":"装修投入和租金回报怎么测算","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"房东翻新后涨租，装修投入能回本吗？","ola":"回本周期通常5-8年，5年内值得投","cp":["回本周期=投入/月租金增量","5年内回本值得投入","5-8年看情况","重硬装轻软装","单方造价500-800元/㎡"],"detail":"装修投入租金回报测算方法：回本周期=装修总投入/月租金增量。例如：装修投入8万元，月租金从4000元增至5000元（月增1000元），回本周期=80000/1000=80个月（约6.7年）。判断标准：回本周期<5年值得投入，5-8年看情况，>8年不建议。出租装修原则：重硬装轻软装（硬装影响结构安全，软装租客不珍惜）、选耐用品非颜值款、控制单方造价500-800元/㎡。","legalRef":"行业通行做法（装修投入回收周期测算）","consumerBenefit":"判断装修溢价是否合理","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["出租房装修回本周期","装修投入产出比","出租房装修值不值"]},{"id":"OWN-OPS-013","name":"房产保险有必要买吗","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"房东要我买房屋保险，有必要吗？","ola":"自住看需求，出租房建议买房东险保欠租和损坏","cp":["家财险保火灾自然灾害","房东险保欠租+损坏+三者","家财险年200-500元","房东险年500-1500元","出租房强烈建议买"],"detail":"房产保险分为家财险（自住）和房东险（出租）。家财险保障火灾、爆炸、自然灾害造成的房屋及室内财产损失，年保费约200-500元，保额50-200万。房东险额外保障租客欠租、租客损坏房屋、第三方责任（租客致邻居损失），年保费约500-1500元。自住房贷银行通常要求投保，出租房强烈建议买房东险（尤其高价值房屋）。经纪人应向业主介绍房东险作为增值服务。","legalRef":"《中华人民共和国保险法》第12条、第95条","consumerBenefit":"了解房屋保险种类和保障范围","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["房屋保险值不值得买","家财险保什么","出租房要不要买保险"]},{"id":"OWN-OPS-032","name":"出租房多久检修一次","domain":"资产持有与运营","subScene":"运营维护","scene":"资产持有与运营·运营维护","cq":"出租的房子我多久去检查一次比较好？","ola":"每6月巡检一次，提前通知租客","cp":["每6月一次系统巡检","重点查电路水管燃气","换租客时全面验收","巡检前24小时通知","合同约定巡查权"],"detail":"出租房建议每6个月做一次系统性巡检，重点检查：电路（开关插座有无发热变色）、水管（有无渗漏水渍）、燃气（软管有无老化）、门窗五金（启闭是否正常）、家电运转状态。每次换租客时做一次全面验收并拍照留证。巡检前须提前通知租客（一般24小时以上），合同中约定房东合理巡查权。","legalRef":"行业通行做法","consumerBenefit":"定期检修预防事故降低损失","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["出租房维护周期","房东定期检查有必要吗","出租房检修清单"]},{"id":"OWN-OPS-039","name":"出租房智能锁值不值得装","domain":"资产持有与运营","subScene":"运营维护","scene":"资产持有与运营·运营维护","cq":"出租房装智能门锁方便吗？值不值得装？","ola":"方便管租客免送钥匙，千元级值得装","cp":["远程发密码免送钥匙","租期到一键失效","出入记录可查","千元级2次换锁回本","多套房和异地房东最值"],"detail":"出租房装智能锁核心价值：远程发临时密码免送钥匙、租期到一键失效无需换锁、出入记录可查便于安全管理。成本：千元级智能锁1把，相当于2次换锁+跑腿送钥匙的人力成本。适用场景：多套房管理、短租/民宿、异地房东。选购要点：支持临时密码+远程管理、续航6月以上、有机械备用钥匙。","legalRef":"行业通行做法","consumerBenefit":"省时省力安全管理提升效率","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["出租房装智能锁好吗","智能门锁对出租管理好处","出租房换密码锁划算吗"]},{"id":"OWN-OPS-CASE-002","name":"租客在出租屋里发生意外房东要赔钱吗","domain":"业主资产","subScene":"运营","scene":"业主资产·运营","cq":"租的房子电器漏电导致我受伤，房东需要赔偿吗？","ola":"房东未保障设施安全需承担过错赔偿。","cp":["出租人需保障设施安全","老旧设备需定期检修","未尽维修义务需担责","按过错比例承担赔偿责任"],"detail":"王某将房屋出租给赵某，未对老旧热水器进行检修。赵某洗澡时因热水器漏电触电受伤。赵某起诉王某索赔。法院查明，王某作为出租人未提供符合安全标准的设施，未尽到安全保障和维修义务。依据《民法典》第七百零八条，法院判决王某承担70%责任，赔偿赵某医疗费等共计8万元。","legalRef":"《中华人民共和国民法典》第七百零八条（出租人交付义务）、第七百一十二条（出租人维修义务）","consumerBenefit":"明确出租房屋安全标准，规避意外事故赔偿风险。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["出租房火灾房东担责","租客坠楼房东赔偿","出租屋意外事故责任"]},{"id":"OWN-OPS-CASE-008","name":"出租房漏水淹了楼下谁赔偿","domain":"资产持有与运营","subScene":"运营维护","scene":"资产持有与运营·运营维护","cq":"楼上漏水把我淹了，我该找楼上房东还是租客赔？","ola":"租客使用不当主责，房东设施老化次责，按过错赔偿。","cp":["租客使用不当负主责","房东设施老化负次责","楼下受损可起诉双方","按过错比例承担赔偿责任"],"detail":"王某将房屋出租给赵某。赵某使用洗衣机时未接管导致漏水，淹了楼下陈某家。陈某起诉王某与赵某要求赔偿装修损失2万元。法院查明，漏水系赵某使用不当所致，且王某提供的洗衣机排水管老化。法院判决赵某承担主要赔偿责任，王某因未尽房屋及设施维护义务承担次要补充责任，共计赔偿陈某1.8万元。","legalRef":"《中华人民共和国民法典》第一千一百六十五条","consumerBenefit":"明确漏水责任划分，受损方知道该向谁主张权利。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["出租屋漏水楼下索赔","租客使用不当漏水谁赔","房东租客漏水连带责任"]},{"id":"OWN-OPS-CASE-009","name":"租客在房子里发生意外房东担责吗","domain":"资产持有与运营","subScene":"运营维护","scene":"资产持有与运营·运营维护","cq":"我在租的房子里因为设施问题受伤了，能找房东赔吗？","ola":"房东未尽安全保障义务导致设施伤人，需按过错担责。","cp":["房东需保证设施安全","隐患未告知需担主责","租客自身疏忽担次责","按过错程度划分责任"],"detail":"孙某出租房屋给周某，热水器存在漏电隐患且未告知。周某洗澡时触电受伤，起诉孙某索赔医疗费10万元。法院查明，孙某提供的热水器不符合安全标准且未定期检修，未尽到安全保障义务。法院判决孙某承担80%责任，赔偿周某8万元；周某自身未尽注意义务承担20%责任。","legalRef":"《中华人民共和国民法典》第一千一百九十八条","consumerBenefit":"提醒房东定期检修设施，保障租客安全，规避高额赔偿风险。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租客在出租屋受伤房东赔吗","出租房安全隐患责任","租客意外伤亡房东责任"]},{"id":"OWN-OPS-CASE-019","name":"群租房被查处房东受什么处罚","domain":"资产持有与运营","subScene":"运营维护","scene":"资产持有与运营·运营维护","cq":"我租了群租房被查处，房东会受到什么处罚？","ola":"违规群租将被责令整改、罚款，拒不整改将强制拆除。","cp":["打隔断改变房屋结构属违规","人均面积及消防需达标","面临责令整改及行政罚款","拒不整改将被强制拆除"],"detail":"房东田某将一套三居室打隔断分为6个房间出租给12人。街道办联合公安、住建部门检查时认定为群租房，存在严重消防隐患。相关部门责令田某限期拆除隔断，恢复房屋原状，并依据当地房屋租赁管理规定，对田某处以1万元罚款。田某逾期拒不整改，相关部门依法强制拆除，并向田某追缴强制执行费用。","legalRef":"《商品房屋租赁管理办法》第八条","consumerBenefit":"警示房东合规出租，避免行政处罚及强制拆除带来的经济损失。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["打隔断出租被查处房东罚款","群租房被举报房东怎么处罚","违规群租房东承担什么责任"]},{"id":"OWN-OPS-CASE-024","name":"房屋抵押期间出租租客能住多久","domain":"资产持有与运营","subScene":"运营维护","scene":"资产持有与运营·运营维护","cq":"我租的房子被房东抵押后拍卖了，新房东能赶我走吗？","ola":"先抵押后出租，抵押权实现时租客不受买卖不破租赁保护。","cp":["先抵押后出租不适用买卖不破租赁","抵押权实现后租客需腾退","租客只能向房东主张违约赔偿","租房前需核查房屋抵押状态"],"detail":"房东白某将已抵押给银行的房屋出租给租客李某，租期3年。后白某断供，银行行使抵押权，房屋被法院拍卖。新房东王某要求李某立即搬离。李某主张“买卖不破租赁”。法院审查认为，该房屋出租前已设立抵押权，抵押权实现导致所有权变动，不受“买卖不破租赁”保护。法院判决李某限期腾退房屋，李某可向白某主张违约赔偿。","legalRef":"《中华人民共和国民法典》第四百零五条","consumerBenefit":"明确抵押与租赁的顺位关系，提示租客核查抵押状态规避风险。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["抵押的房子出租租客受保护吗","房屋抵押后出租买卖不破租赁","房东抵押房子租客能住到期满吗"]},{"id":"OWN-OPS-CASE-025","name":"租客在屋内从事违法活动房东担责吗","domain":"资产持有与运营","subScene":"运营维护","scene":"资产持有与运营·运营维护","cq":"租客在我租的房子里干违法的事，房东会被抓吗？","ola":"房东明知或应知租客违法而不制止报警，需承担法律责任。","cp":["明知或应知违法活动需担责","租金异常高需尽核查义务","发现违法线索必须及时报警","面临行政拘留及没收违法所得"],"detail":"房东贺某将房屋出租给赵某，赵某在屋内组织网络赌博。公安机关查获时，贺某辩称不知情。但警方查明，贺某曾收到邻居关于屋内人员嘈杂、疑似赌博的投诉，且收取的租金远高于市场价，却未进行任何核查或报警。公安机关依据《治安管理处罚法》，认定贺某为赌博提供条件，对其处以行政拘留5日并罚款3000元，同时没收违法所得。","legalRef":"《治安管理处罚法》第七十条","consumerBenefit":"警示房东履行监督义务，发现违法线索及时报警，避免连带受罚。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见后","见前","见中"]},"alias":["租客在出租屋吸毒房东担责吗","租客搞传销房东有连带责任吗","出租房发生违法活动房东处罚"]},{"id":"OWN-POL-031","name":"限购政策变化对在售房产有什么影响","domain":"业主服务","subScene":"政策","scene":"业主服务·政策","cq":"听说限购政策要变，对我的房子有什么影响？","ola":"限购变影响买家资格，具体影响看你的房子","cp":["限购变→买方资格池变→需求变","放松≠必涨，收紧≠必跌","具体影响看房产位置和类型","不做确定性价格预测","缺失：未区分资格影响和价格影响"],"detail":"限购政策变化直接影响买方资格池，进而影响在售房产的潜在买家数量和出价意愿。政策放松→买方资格扩大→需求增加→卖方议价空间增大；政策收紧→买方资格缩小→需求减少→卖方可能降价或延迟出售。经纪人应帮业主分析政策变化对具体房产的影响程度，而非做确定性价格预测。缺失动作：未区分政策对买方资格的影响和对房价的影响是两回事。","legalRef":"各城市限购政策（以当地住建委公告为准）","consumerBenefit":"不被错误预测误导，理性判断出售时机","tags":{"clientType":["seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["限购变了我的房子还能卖吗","新限购政策对卖家有影响吗","限购调整影响出售吗"]},{"id":"OWN-POL-032","name":"经纪人对政策效果做确定性预测有什么风险","domain":"业主服务","subScene":"政策","scene":"业主服务·政策","cq":"中介说这个政策出来房价肯定涨，能信吗？","ola":"不能信，政策影响不确定勿做预测","cp":["确定性价格预测=越界+不可靠","政策影响是多变量综合结果","应列举影响维度而非下结论","缺失：未标注不确定性","误导业主可被追责"],"detail":"经纪人对政策效果做确定性价格预测（如'限购放松肯定涨'）属于越界行为。政策影响需综合供需、库存、信贷、预期等多变量，任何确定性预测都可能误导业主决策。正确做法是列举政策可能影响的几个维度（买方资格、供需关系、市场预期），强调不确定性，帮业主做信息充分下的自主判断。缺失动作：未标注预测不确定性且未提供多维度分析。","legalRef":"《房地产经纪管理办法》第22条（禁止超出经营范围）","consumerBenefit":"不被经纪人的确定性预测误导决策","tags":{"clientType":["seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["中介说政策出来房价肯定涨靠谱吗","经纪人说限购放松一定涨能信吗","中介预测政策影响可信吗"]},{"id":"OWN-POL-035","name":"业主想利用政策漏洞规避限购有什么风险","domain":"业主服务","subScene":"政策","scene":"业主服务·政策","cq":"朋友说假离婚能再买一套，有什么风险？","ola":"风险很大，合同可能无效还影响信用","cp":["利用政策漏洞=规避调控→违法风险","合同可能被认定无效","虚假信息可被联审查出","经纪人禁止协助规避政策","缺失：未拒绝且未告知风险"],"detail":"利用政策漏洞（如假离婚、假结婚、借名买房）规避限购，可能被认定为规避调控政策，面临合同无效、信用记录受损、行政处罚甚至刑事责任。各地住建部门已建立购房资格联审机制，虚假婚姻状况和社保记录可被查出。经纪人更不能协助或指导业主利用漏洞。缺失动作：未拒绝协助且未告知法律风险。","legalRef":"《中华人民共和国民法典》第154条（恶意串通无效）；各城市限购政策违规处罚条款","consumerBenefit":"了解规避限购的严重法律后果","tags":{"clientType":["seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["假离婚买房有什么风险","利用政策漏洞买房违法吗","规避限购被抓会怎样"]},{"id":"OWN-POL-036","name":"政策代办费和信息费是诈骗吗","domain":"业主服务","subScene":"政策","scene":"业主服务·政策","cq":"有人说花钱能提前知道政策消息，靠谱吗？","ola":"不靠谱，政策信息公开透明无需付费","cp":["政策信息官方渠道公开透明","不存在付费内部消息","政策代办费高度疑似诈骗","应引导业主查官方渠道","缺失：未提示诈骗风险"],"detail":"房产政策信息通过住建委、税务局、公积金中心等官方渠道公开透明发布，不存在需要付费获取的'内部消息'或'提前通知'。任何声称付费可提前获取政策信息或办理政策绿色通道的，高度疑似诈骗。经纪人应提醒业主通过官方渠道获取政策信息，不轻信付费代办。缺失动作：未提醒业主政策信息公开透明且未提示诈骗风险。","legalRef":"《反电信网络诈骗法》第18条；各政府部门信息公开规定","consumerBenefit":"避免被政策信息诈骗骗钱","tags":{"clientType":["seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["内部政策消息收费可信吗","花钱买政策内部信息靠谱吗","政策代办费是不是骗局"]},{"id":"OWN-PRP-042","name":"配偶偷偷卖房我能追回吗","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"我老公没经过我同意把房子卖了，我能找买家要回房子吗？","ola":"若买家构成善意取得则无法追回，只能向擅自卖房的配偶索赔。","cp":["处分共有房产需全体同意","买方善意取得则无法追回","受损方可向擅自处分人索赔","交易前必须核实共有人意愿"],"detail":"共有产权处分争议指部分共有人未经其他共有人同意，擅自处分共有房产引发的纠纷。依据《民法典》第301条，处分共有不动产应经占份额三分之二以上的按份共有人或全体共同共有人同意。实践中，若买方属于善意取得（支付合理对价、已办理登记且不知情），原所有权人无法追回房屋，只能向擅自处分人索赔。风险提示：共有房产交易时务必核实共有人同意证明，避免钱房两空。","legalRef":"《中华人民共和国民法典》第301条","consumerBenefit":"了解共有房产单方处分的法律风险，防范钱房两空的极端情况。","tags":{"clientType":["seller"],"stage":"pre,mid","layer":"术","meetingPhase":["见前","见中"]},"alias":["共有产权处分争议","夫妻单方卖房效力","瞒着配偶卖共有房产"]},{"id":"OWN-REF-057","name":"房子重新装修后租金能定高一点吗","domain":"业主服务","subScene":"房产改造","scene":"业主服务·房产改造","cq":"房子重新装修后租金能定高一点吗","ola":"可参考同小区基准，精装通常能溢价10%-30%。","cp":["参考同小区租金基准","精装可溢价百分之十到三十","避免定价过高拉长空置","算好装修成本回本周期"],"detail":"房产改造后出租定价需参考同小区同户型的租金基准，结合改造提升的品质进行溢价评估。精装修、家电齐全、风格现代的房源通常能获得10%-30%的租金溢价。定价过高可能导致空置期延长，需平衡租金收益与出租效率。","legalRef":"《商品房屋租赁管理办法》第八条（租金约定）","consumerBenefit":"掌握租金定价策略，平衡租金收益与出租效率，实现收益最大化。","tags":{"clientType":["landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["装修后租金定价","翻新后出租","精装房租金溢价"]},{"id":"OWN-REF-067","name":"学区政策变化对房产保值的影响","domain":"业主服务","subScene":"房产保值","scene":"业主服务·房产保值","cq":"买了学区房，万一学区政策变了房子会不会跌？","ola":"多校划片可致溢价缩水10-30%，需关注年度划片公告。","cp":["多校划片溢价缩水10-30%","教师轮岗弱化师资壁垒","划片变更需关注年度公告","公示期可行使异议权"],"detail":"学区政策是学区房溢价的核心支撑，近年三大政策变动冲击保值预期：①多校划片取代单校划片，锁定名校不确定性大增，溢价缩水10-30%；②教师轮岗制度弱化名校师资壁垒；③就近入学原则调整导致学区边界变更。业主需关注教育局年度划片公告，并在划片调整公示期内行使异议权。","legalRef":"《义务教育法》第十二条；《教育部关于进一步做好小学升入初中免试就近入学工作的实施意见》","consumerBenefit":"提前识别学区政策风险，避免溢价归零被套牢。","tags":{"clientType":["landlord","buyer"],"stage":"post","layer":"道","meetingPhase":["见前","见中","见后"]},"alias":["学区房保值风险","多校划片影响","学区调整与房价"]},{"id":"OWN-REF-074","name":"学区调整导致房价暴跌的真实案例","domain":"业主服务","subScene":"房产保值","scene":"业主服务·房产保值","cq":"有没有学区变了之后房价大跌的真实例子？","ola":"多校划片后名校学区房跌幅可达12-18%。","cp":["多校划片后跌幅12-18%","行政诉讼多被驳回","学区溢价是政策红利","溢价占比不宜超30%"],"detail":"真实案例：某新一线城市2024年实施多校划片后，原名校单学区房单月跌幅达12-18%，部分急售房源跌幅超20%。业主集体提起行政诉讼要求撤销划片调整，法院以教育行政部门具有自由裁量权为由驳回。教训：学区溢价本质是政策红利而非资产价值，政策调整时溢价可归零。购房时学区溢价占比不应超过房屋基础价值的30%。","legalRef":"《行政诉讼法》第十二条；各地教育局义务教育招生工作实施方案","consumerBenefit":"从真实案例中认识学区溢价的风险边界，合理设定止损预期。","tags":{"clientType":["landlord","buyer"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["学区房暴跌案例","多校划片跌价","学区行政诉讼"]},{"id":"OWN-REF-079","name":"老破小逆袭保值的真实案例与方法论","domain":"业主服务","subScene":"房产保值","scene":"业主服务·房产保值","cq":"有没有老房子反而涨价的例子？","ola":"电梯+品牌物业+学区=老破小逆袭公式。","cp":["加分项：电梯/物业/学区/地铁/商业","减分：无电梯/劣物业/无学区/噪音","10分以上强保值","5分以下需预警"],"detail":"对比案例揭示保值加减分规律：案例A（30年老小区+加装电梯+引入品牌物业+名校学区加持=5年涨幅45%逆势上涨）；案例B（同等房龄小区+物业崩盘+学区划出+房龄超30年贷款困难=3年贬值30%）。提炼可复用评估框架：保值加分项（电梯+2分、品牌物业+2分、学区+3分、地铁800米内+2分、商业1公里内+1分），减分项（无电梯-2分、劣质物业-3分、无学区-1分、临街噪音-1分、超30年房龄-2分）","legalRef":"《中华人民共和国民法典》第二百七十三条；《城市老旧小区改造工作方案》","consumerBenefit":"从真实案例中获得可操作的保值加减分框架，科学评估老房保值力。","tags":{"clientType":["landlord","buyer"],"stage":"post","layer":"器","meetingPhase":["见前","见中","见后"]},"alias":["老破小保值案例","老房子逆袭涨价","老房贬值逆转"]},{"id":"OWN-RET-005","name":"租客在出租房里养宠物怎么管","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"我想租个房子养狗，怎么跟房东沟通比较好？","ola":"养宠需房东同意，合同应约定损坏赔偿责任。","cp":["养宠需事先征得业主同意","合同应约定宠物种类及数量","明确宠物损坏设施的赔偿责任","需遵守当地养犬管理规定"],"detail":"租客在出租屋内饲养宠物，需事先征得业主同意，并在合同中明确约定。若未经同意养宠，业主有权要求整改或解除合同。若同意养宠，建议约定宠物种类、数量，并要求租客承担宠物造成的设施损坏、异味残留及深度保洁费用。同时，租客需遵守当地养犬管理条例，办理犬证，避免宠物扰民引发邻里投诉。","legalRef":"行业通行做法及各地《养犬管理条例》","consumerBenefit":"了解租房养宠的规则与责任，避免因违规养宠被解约或扣除押金。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["租房养宠物","租客养猫养狗","出租房允许养宠物吗"]},{"id":"OWN-RET-007","name":"出租房里的东西坏了谁负责修","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"租的房子马桶堵了，是我自己找人修还是让房东修？","ola":"自然损耗房东修，人为损坏租客修。","cp":["无约定时业主承担维修义务","人为损坏由租客负责维修","合同应明确大小修责任划分","建立清晰的报修与费用流程"],"detail":"出租房屋的维修责任通常由租赁合同约定。若无约定或约定不明，依据法律规定，业主应当履行租赁物的维修义务，确保房屋符合约定用途。但如果是因租客使用不当或人为故意造成的损坏，则由租客负责维修或赔偿。建议双方在合同中详细划分大修、小修及易耗品的维修责任，明确报修流程及费用承担方式，避免推诿。","legalRef":"《中华人民共和国民法典》第七百一十二条","consumerBenefit":"明确房屋设施维修的责任归属，避免在维修费用上产生不必要的纠纷。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["租房维修责任","出租屋家电维修","房屋漏水谁修"]},{"id":"OWN-RET-017","name":"把房子交给长租公寓托管有什么风险？","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"我租了长租公寓的房子，如果中介跑路了，房东来赶我走合法吗？","ola":"警惕高收低租模式，防范机构暴雷导致租金两空及清退纠纷。","cp":["警惕高收低租资金盘","机构暴雷致租金两空","房屋可能被违规改造","清退租客面临法律障碍"],"detail":"长租公寓托管模式虽能让业主获得稳定租金收益，但存在较大资金链断裂风险。部分机构采用“高收低租”、“长收短付”模式扩张，一旦资金链断裂即面临“暴雷”。风险包括：机构跑路导致业主收不到租金、租客被驱赶引发纠纷、房屋被违规改造或群租、机构破产后清退租客困难。业主应选择资质良好、资金受监管的头部企业，并警惕高于市场价的收房承诺。","legalRef":"《关于整顿规范住房租赁市场秩序的意见》","consumerBenefit":"帮助租客识别长租公寓风险，避免遭遇中介跑路后被迫搬离的困境。","tags":{"clientType":["landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["长租公寓托管靠谱吗","房屋托管给长租公寓的风险","长租公寓暴雷房东怎么办"]},{"id":"OWN-RET-020","name":"出租房屋有没有必要买专门的保险？","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"我在出租屋里洗澡滑倒摔伤了，房东买的出租房保险能赔我的医药费吗？","ola":"出租房保险可保财产损失及侵权赔偿，建议配置防范风险。","cp":["保障房屋财产损失","转移房东侵权赔偿责任","可附加租金损失保障","非强制但建议配置"],"detail":"出租房保险（如房东险、出租人责任险）是业主转移租赁期间意外风险的有效工具。主要保障范围包括：房屋及附属设施因火灾、水管破裂等造成的财产损失；租客或访客在房屋内发生意外伤亡，依法应由房东承担的赔偿责任；以及租客拖欠租金带来的租金损失保障。虽然非强制，但能有效避免业主因意外事故或租客纠纷面临巨额索赔，建议长期出租的业主配置。","legalRef":"行业通行做法","consumerBenefit":"让租客了解出租房保险的存在，在发生意外时知道可通过保险获得合理赔偿。","tags":{"clientType":["landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["房东险有必要买吗","出租房保险保什么","房屋出租买什么保险好"]},{"id":"OWN-RET-034","name":"房子出租必须去办租赁备案吗？","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"房东不配合办租赁备案，我办不了居住证怎么办？","ola":"依法应在签约后30日内办理租赁备案登记。","cp":["签约后三十日内备案","未备案可能面临罚款","备案是办居住证前提","不影响合同民事效力"],"detail":"根据规定，房屋租赁合同订立后三十日内，租赁当事人应当到租赁房屋所在地直辖市、市、县人民政府建设（房地产）主管部门办理房屋租赁登记备案。虽然未备案通常不影响合同本身的民事效力，但可能会面临责令限期改正或罚款的行政处罚，且备案是租客办理居住证、提取公积金支付房租的必要前提。","legalRef":"《商品房屋租赁管理办法》第十四条","consumerBenefit":"明确备案法定义务，保障租客办理居住证等合法权益。","tags":{"clientType":["landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["房屋租赁备案","租房合同备案","租赁登记证明"]},{"id":"OWN-RET-038","name":"租客想自己出钱装修房子能答应吗？","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"我自费给租的房子换了地板，退租时能要求房东补偿吗？","ola":"需签书面协议，明确退租时装修物的归属。","cp":["必须签订书面补充协议","明确装修范围与标准","约定退租时物品归属","未经同意需恢复原状"],"detail":"租客提出自费装修出租房，房东可以同意，但必须提前签订书面补充协议。协议需明确装修范围、风格标准、是否允许改动结构，以及最核心的：退租时装修物的归属（如归房东所有且无补偿，或租客需恢复原状）。若未获房东书面同意擅自装修，房东有权要求恢复原状或赔偿损失。","legalRef":"《中华人民共和国民法典》第七百一十五条","consumerBenefit":"规范装修流程，避免退租时因装修补偿产生经济纠纷。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["租客自费装修","出租房租客装修","租客改造房屋"]},{"id":"OWN-RET-039","name":"出租房的日常保洁和维修谁负责？","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"租的房子水管老化漏水，房东一直不修我该怎么办？","ola":"房东负责主体维修，租客负责日常保洁。","cp":["房东承担法定维修义务","租客使用不当租客赔","日常保洁由租客负责","合同有约定从其约定"],"detail":"出租房屋的维修和清洁责任通常由租赁合同约定。若无约定或约定不明，根据法律规定，房东应当承担租赁物的维修义务，确保房屋及原有设施符合约定用途。但如果是因租客使用不当或故意破坏导致的损坏，则由租客负责维修或赔偿。日常保洁通常由租客自行负责，保持房屋基本卫生。","legalRef":"《中华人民共和国民法典》第七百一十二条","consumerBenefit":"明确维修与保洁责任边界，保障居住体验，减少推诿。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["出租房维修责任","租房保洁谁负责","房屋维修义务"]},{"id":"OWN-RET-043","name":"出租房漏水淹了楼下谁赔","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"租的房子漏水把楼下淹了，房东说是我的责任，到底该谁赔？","ola":"管道老化房东赔，使用不当租客赔。","cp":["自然老化由房东负责","使用不当由租客赔偿","及时报物业排查原因","保留现场照片及定损证据"],"detail":"出租房漏水责任是指房屋在租赁期间发生漏水导致自身或楼下邻居财产损失时，房东与租客之间赔偿责任的界定。若因房屋管道老化、防水层失效等自然损耗导致，由房东承担维修及赔偿责任；若因租客使用不当、私自改造或忘关水龙头导致，则由租客承担赔偿责任。需及时报物业排查原因并固定证据。","legalRef":"《中华人民共和国民法典》第七百一十二条","consumerBenefit":"明确漏水责任归属，避免承担非自身过错导致的赔偿。","tags":{"clientType":["landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["出租房漏水责任划分","租客弄漏水谁赔偿","房子漏水赔楼下算谁的"]},{"id":"OWN-RET-045","name":"租客自己换门锁房东同意吗","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"刚搬进出租屋想换个锁芯保证安全，需要房东同意吗？","ola":"换锁需经房东同意，退租需恢复原状。","cp":["换锁需提前征得房东同意","不得破坏原有防盗门体","退租需恢复原状或协商","保留原锁芯以备退租交还"],"detail":"租客更换锁芯是指租客在租赁期间出于安全考虑，要求或自行更换入户门锁芯的行为。通常租客有权要求换锁以保障隐私，但需提前征得房东同意，且不得破坏原有锁体。退租时租客有义务将原锁芯交还或恢复原状，也可协商将新锁芯留给房东。未经同意私自换锁或破坏门锁，房东有权要求恢复原状或赔偿。","legalRef":"《中华人民共和国民法典》第七百一十五条","consumerBenefit":"明确换锁权限与流程，保障居住安全同时避免违约赔偿。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["租房换锁芯规定","租客换锁需要房东同意吗","出租房换锁谁出钱"]},{"id":"OWN-RET-046","name":"出租房消防和安全隐患怎么查","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"租房子的时候，怎么检查房子的消防和用电安不安全？","ola":"重点排查水电气及消防设施，留存检查记录。","cp":["排查燃气及用电安全","配备基础消防器材","确保房屋结构无危房","留存安全检查记录签字"],"detail":"出租房安全检查是指房东在房屋出租前及租赁期间，对房屋内的消防设施、用电用气安全、房屋结构等进行排查的过程。重点检查燃气热水器是否合规、电线是否老化、是否配备灭火器和烟感报警器、防盗门窗是否牢固等。房东需确保交付的房屋符合安全居住标准，若因房屋固有安全隐患导致事故，房东需承担主要法律及赔偿责任。","legalRef":"《中华人民共和国消防法》第十五条","consumerBenefit":"掌握安全检查要点，避免租住存在安全隐患的房屋。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["出租房安全检查表","租房安全隐患排查","房东出租房消防检查"]},{"id":"OWN-RET-049","name":"房东能断水断电逼租客搬走吗","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"房东因为一点纠纷就把我水电停了，我该怎么维权？","ola":"房东无权断水电，违约需通过合法途径解约。","cp":["房东无权擅自断水断电","违约应通过合法途径解约","断水电造成损失需赔偿","租客遇此情况可报警求助"],"detail":"出租房断电断水是指房东在租赁期间，以租客拖欠租金或违约为由，采取停水、停电、停气等极端方式逼迫租客搬离的行为。法律明确禁止此类私力救济行为。即使租客违约，房东也必须通过协商、发催告函或向法院起诉等合法途径解除合同，无权擅自切断生活必需资源。若房东强行断水电导致租客损失，租客有权要求赔偿并报警处理。","legalRef":"《中华人民共和国民法典》第九百四十四条","consumerBenefit":"知晓房东断水电属违法行为，掌握应对及维权方法。","tags":{"clientType":["landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["房东断水断电合法吗","租客不交租金房东能停水停电吗","出租房被断水断电怎么维权"]},{"id":"OWN-RET-051","name":"出租房发现白蚁了该谁负责灭治","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"出租房发现白蚁了该谁负责灭治","ola":"房屋结构问题由房东负责，租客原因由租客负责。","cp":["房屋结构问题由房东负责","租客带入家具导致由租客负责","发现白蚁应及时报修处理","保留消杀凭证明确费用归属"],"detail":"出租房白蚁防治涉及房屋维护责任划分。通常白蚁防治属于房屋主体结构及附属设施的维护范畴，若因房屋原有结构或环境导致白蚁滋生，房东应承担灭治费用及责任。若因租客使用不当（如带入带白蚁的家具）导致，则由租客负责。明确责任有助于及时消除隐患，保障居住安全与房屋资产价值。","legalRef":"《中华人民共和国民法典》第七百一十二条","consumerBenefit":"明确白蚁防治责任，避免租客承担不合理费用。","tags":{"clientType":["landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["出租房白蚁防治","租房发现白蚁谁出钱","房子长白蚁怎么处理"]},{"id":"OWN-RET-052","name":"租客私自接线偷电房东怎么处理","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"租客私自接线偷电房东怎么处理","ola":"固定证据，要求补交电费，严重可解约或报警。","cp":["立即制止并固定违规证据","要求补交电费及违约金","情节严重可解除合同","涉嫌违法破坏电力可报警"],"detail":"租客偷电属于违约及违法行为。房东发现租客私自接线、绕过电表偷电时，应立即制止并固定证据，如拍照、录像及调取用电异常记录。随后应要求租客补交电费并承担违约金，情节严重者可解除租赁合同。若涉及破坏电力设备，可报警处理。规范处理流程能有效挽回经济损失并规避消防安全风险。","legalRef":"行业通行做法","consumerBenefit":"了解处理流程，避免房东采取过激手段导致自身违法。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["租客偷电怎么办","出租房租客偷电","租客私接电线怎么处理"]},{"id":"OWN-RET-057","name":"出租房允许带小孩住会有什么风险","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"出租房允许带小孩住会有什么风险","ola":"存在设施损坏及安全风险，需合同明确赔偿标准。","cp":["小孩易造成墙面家具污损","需提前排查房屋安全隐患","合同明确损坏赔偿标准","租客需尽到安全监护责任"],"detail":"租客带小孩入住出租房，可能带来房屋设施损坏、噪音扰民及安全隐患等风险。小孩活泼好动易造成墙面污损、家具磕碰；同时，若房屋存在尖锐边角、未封阳台等隐患，易发生安全事故。房东应在合同中明确房屋使用规范及损坏赔偿标准，并提前告知房屋安全隐患。租客则需尽到监护责任，合理使用房屋设施。","legalRef":"行业通行做法","consumerBenefit":"了解带小孩租房的风险，提前排查隐患保障儿童居住安全。","tags":{"clientType":["landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["租客带小孩影响","租房带小孩房东介意吗","出租房小孩居住风险"]},{"id":"OWN-RET-058","name":"出租房燃气安全不达标房东会受罚吗","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"出租房燃气安全不达标房东会受罚吗","ola":"房东必须提供合格设施，违规将面临行政重罚。","cp":["房东必须提供合格燃气设施","违规改装或老化将面临重罚","需配合燃气公司定期安检","租客规范使用发现泄漏即报"],"detail":"出租房燃气安全受国家及地方政策严格监管。房东必须确保出租房屋的燃气设施符合安全标准，严禁提供不符合安全标准的房屋。若因燃气设施老化、违规改装导致安全事故，房东将承担行政罚款甚至刑事责任。各地燃气管理条例规定，房东需配合燃气公司定期安检，及时整改隐患。租客也需规范使用，发现泄漏立即报修。","legalRef":"《城镇燃气管理条例》第二十八条、第四十九条","consumerBenefit":"明确房东燃气安全法定责任，保障租客生命财产安全。","tags":{"clientType":["landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["出租房燃气安全","出租房燃气不合格怎么处罚","租房燃气安全谁负责"]},{"id":"OWN-RET-061","name":"租客在出租房里搞快递驿站我能管吗","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"我租了个房子想做快递代收点，房东不同意怎么办？","ola":"住宅改商用需合法合规，合同可约定违约解约。","cp":["住宅不得擅自改商用","需经有利害关系业主同意","合同需明确房屋用途","违约可要求整改或解约"],"detail":"租客将住宅性质的出租房用于经营快递驿站或代收点，涉及改变房屋使用性质。住宅用房未经批准不得擅自改为经营性用房。此行为不仅可能违反物业管理规约，还易引发邻里纠纷、安全隐患及房屋损耗加剧。业主需在租赁合同中明确约定房屋用途，若租客违约，业主有权要求其整改或解除合同，以维护自身合法权益及房屋安全。","legalRef":"《中华人民共和国民法典》第二百七十九条","consumerBenefit":"明确房屋用途限制，避免因违规经营导致被清退或罚款。","tags":{"clientType":["landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["租客做快递代收","出租房当快递点","租客搞快递驿站"]},{"id":"OWN-RET-062","name":"出租房墙面发霉了到底该谁负责弄","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"租的房子墙面发霉了，房东不给修我该怎么办？","ola":"房屋质量问题业主修，使用不当租客负责。","cp":["房屋结构问题业主修","使用不当导致租客修","及时沟通避免损失扩大","保留证据明确责任划分"],"detail":"出租房出现墙面发霉、通风不畅等问题，通常涉及房屋自然老化、建筑质量缺陷或租客使用不当。若因房屋本身结构或防水问题导致，维修责任在业主；若因租客长期关闭门窗、使用不当导致受潮发霉，则由租客承担修复或赔偿责任。双方应在合同中明确维修责任划分，及时沟通处理，避免损失扩大影响居住体验。","legalRef":"行业通行做法","consumerBenefit":"明确发霉责任归属，保障自身居住环境的健康与舒适。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["出租屋发霉怎么办","房子通风不好长霉","出租房除霉谁出钱"]},{"id":"OWN-RET-064","name":"租客自己花钱装的空调退租时能拆走吗","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"我自己花钱在出租屋装了空调，退租时房东要我留下还不给钱怎么办？","ola":"有约定按约定，可拆卸可带走，附合需协商。","cp":["有约定按约定处理","可拆卸且不损房屋可带走","形成附合需协商补偿","建议安装前书面确认"],"detail":"租客在租赁期间因生活需要自行出资安装空调，退租时的归属与处理需视合同约定及空调是否形成附合而定。若合同有约定则按约定执行；若无约定，可拆卸且不影响房屋结构的，租客可拆走；若拆除会严重毁损房屋或空调本身价值大幅贬损，则视为形成附合，业主可给予适当补偿或无偿取得所有权。建议双方在安装前书面确认处理方式，避免退租时产生纠纷。","legalRef":"《中华人民共和国民法典》第七百一十五条","consumerBenefit":"明确添附物处理规则，避免退租时因空调归属产生经济损失。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["租客自己装空调","出租房加装空调","退租空调怎么处理"]},{"id":"OWN-RET-065","name":"租客能不能自己改WiFi路由器或者拉网线","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"我租的房子网络太差，我能自己找师傅拉网线改WiFi吗？","ola":"换路由器可自由，打孔布线需房东同意。","cp":["升级路由器通常被允许","重新布线不得破坏装修","墙体打孔需征得同意","退租时需恢复原状"],"detail":"租客在出租房内更改WiFi路由器或重新拉网线，属于对房屋附属设施的日常使用与微调。通常情况下，租客有权自行升级路由器或办理宽带，但重新布线需确保不破坏房屋原有装修和结构。若涉及墙体打孔或破坏原有弱电箱，需征得业主同意。退租时，租客有义务恢复原状或经业主同意保留网络设施。建议在合同中明确网络改造的权限及恢复义务。","legalRef":"行业通行做法","consumerBenefit":"了解网络改造权限，合理改善居住网络环境且不违约。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["出租房改WiFi","租客自己拉网线","出租房网络改造"]},{"id":"OWN-RET-066","name":"出租房的物业费到底该房东交还是租客交","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"租房合同里没写物业费谁交，现在物业找我要钱我该怎么办？","ola":"有约定按约定，无约定通常由业主承担。","cp":["合同约定优先原则","未约定通常由业主承担","业主负有监督连带责任","签合同需明确费用明细"],"detail":"出租房屋的物业服务费缴纳责任，首先遵从租赁双方的合同约定。若合同明确约定由租客承担，则租客需按时缴纳；若未约定或约定不明，依据行业惯例及相关法律精神，物业费作为房屋所有权产生的法定义务，通常由业主承担。为避免纠纷，建议在签订租赁合同时，明确各项费用的承担主体及缴纳方式，业主对租客的缴纳情况负有监督和连带责任。","legalRef":"《物业管理条例》第四十一条","consumerBenefit":"明确物业费缴纳主体，避免因合同约定不明导致额外经济支出。","tags":{"clientType":["landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["出租房物业费谁出","租房物业费怎么算","租客不交物业费怎么办"]},{"id":"OWN-RET-067","name":"租客私自砸墙违规装修我该怎么制止","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"我想把出租屋的墙砸了改格局，房东不同意我硬砸会有什么后果？","ola":"未经同意严禁装修，破坏结构需赔偿并担责。","cp":["未经同意装修属违约","破坏承重墙涉嫌违法","业主有权要求恢复原状","及时取证发书面通知"],"detail":"租客未经业主同意擅自对出租房进行装修，尤其是砸墙、改变房屋主体结构等违规行为，严重威胁房屋安全并侵犯业主物权。业主有权立即要求其停止侵害、恢复原状或赔偿损失。若涉及破坏承重墙，还可能面临行政处罚甚至刑事责任。业主应在合同中明确禁止擅自装修及违约赔偿条款，发现违规行为应及时取证、通知物业并发送书面整改通知。","legalRef":"《中华人民共和国民法典》第七百一十五条","consumerBenefit":"认清违规装修的法律风险，避免因破坏房屋结构承担巨额赔偿。","tags":{"clientType":["landlord"],"stage":"post","layer":"术","meetingPhase":["见后","见前","见中"]},"alias":["租客私自装修","出租房砸墙怎么办","租客违规改造房屋"]},{"id":"OWN-RET-068","name":"租客想用我的出租房地址注册公司行不行","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"我想用租的房子地址注册个公司，房东不配合怎么办？","ola":"住宅注册受限，需防范地址异常及税务风险。","cp":["住宅注册需符合住改商","需取得利害关系人同意","防范地址异常及税务风险","合同约定注销迁出责任"],"detail":"租客要求使用出租房地址注册营业执照或公司，涉及房屋用途变更及工商登记规定。住宅性质的房屋注册公司通常受到严格限制，需符合“住改商”相关规定并取得利害关系业主同意。若房屋为商业性质，则相对宽松。业主若同意提供地址注册，需防范租客经营不善导致的地址异常、税务纠纷及房屋被查封等风险。建议在合同中明确约定注册用途、期限及注销迁出的违约责任。","legalRef":"《中华人民共和国市场主体登记管理条例》第十二条","consumerBenefit":"了解注册地址要求，合法合规办理营业执照，避免无效申请。","tags":{"clientType":["landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["出租房注册公司","租客办营业执照","住宅注册公司可以吗"]},{"id":"OWN-RET-069","name":"出租房里的家电老化坏了到底谁出钱修","domain":"业主服务","subScene":"租赁管理","scene":"业主服务·租赁管理","cq":"出租屋的洗衣机用久了自然坏了，房东让我自己买新的合理吗？","ola":"自然老化房东修，人为损坏租客赔。","cp":["自然老化由业主负责","人为损坏由租客赔偿","交房时需清点记录状态","合同需明确维修责任"],"detail":"出租房内家电及设施损坏的维修责任，需区分是自然老化还是人为损坏。若因家电本身老化、质量问题或正常使用寿命到期导致的损坏，维修或更换费用应由业主承担；若因租客使用不当、故意破坏或未尽到合理保管义务导致的损坏，则由租客负责维修或赔偿。双方应在交房时清点设施并记录状态，合同中明确各类设施的维修责任划分，以便发生问题时快速定责。","legalRef":"《中华人民共和国民法典》第七百一十二条","consumerBenefit":"明确家电维修责任，避免为房屋原有设施的自然老化买单。","tags":{"clientType":["landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["出租屋家电坏了谁修","租房空调坏了谁负责","家电自然老化谁出钱"]},{"id":"OWN-TAX-022","name":"房子出租收的租金要交税吗","domain":"业主服务","subScene":"税务筹划","scene":"业主服务·税务筹划","cq":"房子出租收的租金要交税吗","ola":"个人出租房屋取得的租金收入需依法纳税。","cp":["租金收入依法需纳税","包含个税增值税房产税","多地实行综合征收率","逾期申报有滞纳金罚款"],"detail":"个人出租房屋取得的租金收入属于财产租赁所得，依法应缴纳个人所得税、增值税及房产税等。通常各地税务局会采用综合征收率进行核定征收。业主需按规定期限申报纳税，否则面临滞纳金及罚款。了解纳税义务有助于业主合法合规获取租金收益，避免税务稽查风险。","legalRef":"《中华人民共和国个人所得税法》第二条","consumerBenefit":"知晓租金纳税义务，防范偷漏税带来的法律风险。","tags":{"clientType":["landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["租房收入纳税","房屋出租要交税吗","收租金需要报税吗"]},{"id":"P0-DEC-037","name":"虚假宣传与误导客户需求的法律责任","domain":"交易综合","subScene":"客户解码","scene":"交易综合·客户解码","cq":"中介吹嘘房子有学区结果没有，我能要求赔偿吗？","ola":"虚假宣传误导需求需担责，客户可索赔。","cp":["严禁虚假或引人误解宣传","宣传承诺需有事实依据","误导需求认知构成欺诈","客户有权撤销合同","需承担违约或赔偿责任"],"detail":"依据《反不正当竞争法》第8条，中介不得对房源信息、周边配套或政策进行虚假或引人误解的商业宣传，以迎合或误导客户需求。实践要点：所有宣传物料及口头承诺需有事实依据。风险提示：若因虚假宣传导致客户基于错误需求认知签约，客户有权撤销合同并要求赔偿损失。","legalRef":"《中华人民共和国反不正当竞争法》第8条","consumerBenefit":"免受虚假宣传欺骗，维护自身合法权益。","tags":{"clientType":["buyer"],"stage":"pre,mid","layer":"道","meetingPhase":["见前","见中"]},"alias":["虚假宣传责任","误导客户需求","承诺不兑现"]},{"id":"P0-DEC-CASE-004","name":"中介承诺的学区没兑现能退房吗","domain":"交易综合","subScene":"客户解码","scene":"交易综合·客户解码","cq":"中介当时口头保证是学区房，现在发现不是，我能要求退房吗？","ola":"口头承诺未写入合同且属行政行为，退房诉求难获支持。","cp":["口头承诺学区缺乏书面证据","学区划分属行政行为无法保证","未写入合同的诉求难以主张","主张欺诈需提供充分证据"],"detail":"孙某购房时口头向经纪人表示核心诉求是某小学学区，经纪人口头承诺该房在学区内。双方签订的书面买卖合同及补充协议中均未提及学区事宜。交房后孙某发现该房未被划入该校学区，遂以欺诈为由要求退房并赔偿。法院认为，书面合同未约定学区条款，口头承诺缺乏证据支持，且学区划分属行政行为，卖方及中介无法保证。依据《民法典》第一百四十八条，因证据不足驳回孙某退房诉求。","legalRef":"《中华人民共和国民法典》第一百四十八条","consumerBenefit":"明确核心需求必须落实到书面合同条款中。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前","见中"]},"alias":["学区房没兑现能退房吗","中介口头承诺学区能退房吗","买房后发现不是学区房能退吗"]},{"id":"P0-DEC-CASE-011","name":"没搞清楚自己是二套房多交的税能退吗","domain":"交易综合","subScene":"客户解码","scene":"交易综合·客户解码","cq":"买房时不知道自己是二套房，现在契税多交好几万，这钱能退吗？","ola":"买方隐瞒房产套数导致税费增加，需自行承担差额。","cp":["买方有义务如实申报房产套数","隐瞒房产信息导致税费增加自担","中介核实义务不免除买方申报责任","税费计算错误不构成根本违约"],"detail":"马某购买二手房，向经纪人声称自己名下无房。经纪人据此按首套房计算税费。签约后办理过户时，税务系统显示马某婚前曾有一套房产，需按二套房缴纳3%契税，多出数万元。马某以中介未核实清楚为由拒绝缴税并要求退房。法院认为，买方有义务如实申报家庭房产套数。中介虽未通过系统核实，但买方隐瞒婚前房产信息是导致税费增加的根本原因。依据《民法典》第五百零九条，判决马某自行承担税费差额，继续履行合同。","legalRef":"《中华人民共和国民法典》第五百零九条","consumerBenefit":"明确如实申报家庭房产情况是准确计算税费的前提。","tags":{"clientType":["buyer"],"stage":"pre","layer":"器","meetingPhase":["见前","见中"]},"alias":["没搞清楚是二套房多交的税能退吗","买房发现是二套房税费高能退吗","不知道自己是二套房多交税怎么办"]},{"id":"PRE-CONT-001","name":"买房合同跟谁签","domain":"签约前","subScene":"合同审查","scene":"签约前·合同审查","cq":"我买房合同应该跟谁签？","ola":"必须与产权证上的登记权利人或其合法代理人签约。","cp":["必须与产权人签约","新房找开发商签","代理人需公证授权","核实产权人身份"],"detail":"购房合同的签约主体必须是房屋的真实权利人。如果是二手房，卖方必须是房产证上登记的产权人；如果是新房，卖方必须是开发商（即预售许可证上的开发企业）。若产权人无法到场，需提供经过公证的授权委托书，由代理人代签。与无权处分人签约会导致合同无效或面临无法过户的风险。","legalRef":"《中华人民共和国民法典》第五百九十五条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["购房合同签约主体","和谁签购房合同","买房跟谁签合同"]},{"id":"PRE-CONT-015","name":"房屋面积误差怎么约定","domain":"签约前","subScene":"合同审查","scene":"签约前·合同审查","cq":"新房交房时面积有误差，合同里应该怎么约定？","ola":"按3%绝对值原则约定，多退少补，超3%买方有权退房。","cp":["3%以内据实结算","超3%买方有权退房","面积增加超3%买方不补","面积缩水超3%双倍返还"],"detail":"对于新房（期房），合同中必须明确面积差异的处理方式。行业通行做法及法定原则是“面积误差比绝对值在3%以内（含3%）的，据实结算房价款；超出3%时，买受人有权退房。若买受人不退房，实测面积大于约定面积时，3%以内部分由买受人补足，超出3%部分由开发商承担；实测面积小于约定面积时，3%以内部分由开发商返还，超出3%部分由开发商双倍返还。”二手房通常按套计价，不适用此规则。","legalRef":"《商品房销售管理办法》第二十条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["面积误差","房屋面积误差怎么约定","面积缩水怎么办"]},{"id":"PRE-CONT-040","name":"卖家收定金不卖了怎么办","domain":"签约前","subScene":"合同审查","scene":"签约前·合同审查","cq":"卖家收了我的定金现在反悔不卖了，我该怎么办？","ola":"卖方违约，买方可要求双倍返还定金或赔偿损失。","cp":["卖方违约需双倍返还","可主张房屋差价损失","协商不成可提起诉讼","注意保留违约证据"],"detail":"卖家收取定金后拒绝出售房屋，构成根本违约。根据定金罚则，收受定金的一方不履行债务，应当双倍返还定金。买方有权要求卖家退还已交定金并额外赔偿同等金额的违约金（即双倍返还）。如果双倍定金仍不足以弥补买方实际损失（如房屋差价损失），买方还可以要求卖家赔偿超出部分的损失。买方可先协商，协商不成可向法院起诉。","legalRef":"《中华人民共和国民法典》第587条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["卖家违约怎么办","房东不卖了","定金双倍返还"]},{"id":"PRE-CONT-066","name":"买商业性质房产合同注意什么","domain":"签约前","subScene":"合同审查","scene":"签约前·合同审查","cq":"我打算买商业性质的房产（如商铺、公寓），合同要注意什么？","ola":"重点看土地年限、落户学区限制及税费差异。","cp":["确认土地年限及续期规则","明确无落户及学区功能","约定高额交易税费承担方","审查带租约商铺的租赁条款"],"detail":"商业性质房产（如商铺、写字楼、商住房或公寓）与普通住宅在合同审查上有显著区别。首先，需明确土地使用权年限（通常为40年或50年），以及到期后的续期规则。其次，必须在合同中确认该房产不具备落户及划分学区的功能，防止销售虚假承诺。第三，商业房产的交易税费（如土地增值税、契税）远高于住宅，需在合同中明确各项税费的承担主体。最后，若是带租约出售的商铺，需重点审查原租赁合同的租期、租金递增条款及买卖不破租赁","legalRef":"《中华人民共和国民法典》第三百五十九条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["商业房产合同注意事项","买商住房合同要注意啥","商业性质房产合同审查"]},{"id":"PRE-FINA-043","name":"收入证明和流水对不上咋办","domain":"签约前","subScene":"融资贷款","scene":"签约前·融资贷款","cq":"我开的收入证明金额比我银行流水高，银行不认怎么办？","ola":"银行以流水为准，可补充其他资产证明、增加共同还款人或降额。","cp":["银行以实际流水为准","补充其他资产证明材料","增加共同还款人合并收入","降低贷款额度或提高首付"],"detail":"当收入证明金额与银行流水不匹配时，银行通常会以银行流水为主要认定依据。若流水不足以覆盖收入证明或月供要求，可采取以下补救措施：1.提供其他资产证明（如存款、理财、其他房产、车辆）；2.增加符合条件的共同还款人（如配偶、父母）合并计算收入；3.减少贷款额度或增加首付比例以降低月供；4.提供完税证明或社保公积金缴存记录作为辅助收入证明。切忌伪造流水，以免涉嫌骗贷。","legalRef":"《中华人民共和国刑法》第一百七十五条之一","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["收入证明与流水不符","流水不够收入证明凑","收入证明开高了流水不够"]},{"id":"PRE-MATCH-008","name":"商住房能不能买来住","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"商住房便宜很多，能买来自己住吗？","ola":"不能落户、水电贵一倍、转手税费高，不建议纯居住","cp":["产权40-50年非70年","不能落户不通天然气","水电商价约为住宅2倍","契税3%无首套优惠","流通性极低转手税费高"],"detail":"商住房（商业/办公用途的公寓）与住宅的核心区别：土地使用权40-50年（住宅70年）、不能落户、不通天然气、水电按商业标准收费（电费约为住宅2倍）、不能使用公积金贷款、契税统一3%（无首套优惠）、转让税费远高于住宅。商住房优势：不限购、总价低、层高可做LOFT。风险：居住品质差、流通性极低、二手转手税费高、银行贷款成数低、政策可能禁止商改住。","legalRef":"《城镇国有土地使用权出让和转让暂行条例》第12条（土地使用权年限）；《关于进一步加强商业办公类项目管理的意见》（各地禁止商改住政策）","consumerBenefit":"不贪便宜买错房，住宅和商住差的不止是价格","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["商住两用房居住风险","40年产权公寓能买吗","商住楼和住宅区别"]},{"id":"PRE-MATCH-009","name":"回迁房能不能买","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"回迁房比商品房便宜很多，能买吗？","ola":"有产权证可买，无证坚决不买，过不了户白花钱","cp":["有产权回迁房可正常交易","无证回迁房不能过户风险极高","办证周期3-5年甚至更久","可能需补缴土地出让金","小区品质和物业通常较差"],"detail":"回迁房是拆迁安置的房屋，分两种：有产权的回迁房（已办理不动产权证）可以正常交易，但可能需补缴土地出让金；无产权的回迁房（仅有回迁协议）不能办理过户，购买风险极高。回迁房常见问题：办证周期长（交房后3-5年甚至更久才能办证）、小区品质和物业管理较差、户型设计不合理。购买回迁房必须确认是否有不动产权证，无证坚决不买。","legalRef":"《不动产登记暂行条例》第14条（登记申请）；《中华人民共和国城市房地产管理法》第38条（未领证不得转让）","consumerBenefit":"不在产权上冒风险，买了就是你的","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["回迁房交易风险","安置房买卖限制","回迁房有产权吗"]},{"id":"PRE-MATCH-023","name":"房龄多少年就不建议买了","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"这套房子已经20多年了，还能买吗？贷款能批吗？","ola":"20年房龄贷款年限缩短，超25年慎买超30年可能拒贷","cp":["房龄+贷款≤40-50年","超25年贷款年限缩短","超30年部分银行拒贷","15年内正常15-25年折价","30年以上仅学区/核心地段可考虑"],"detail":"房龄对购房的影响主要体现在三方面：①贷款年限：银行要求房龄+贷款年限≤40-50年（各银行不同），房龄超25年贷款年限缩短，超30年部分银行拒贷；②居住品质：砖混结构80年代住宅预制板楼抗震差、管线老化、保温差；③流通性：房龄超20年二手房成交周期明显变长。建议：房龄15年以内正常购买，15-25年需折价考虑，25年以上仅学区房或核心地段可考虑，30年以上慎买。","legalRef":"各银行个人住房贷款管理办法（关于房龄与贷款年限的规定）","consumerBenefit":"不买贷不了款的老房子，提前算清贷款年限","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["老房子能买吗","老破小值得买吗","房龄对贷款影响"]},{"id":"PRE-MATCH-027","name":"怎么确认房子户口是空的","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"怎么确认想买的房子里面没有别人的户口？","ola":"去派出所查户籍底档，合同约定迁出时限和违约金","cp":["到派出所打印户籍底档确认","公安机关无权强制清户","合同约定迁出时限和违约金","预留5-10万户口迁出保证金","学区房必须核查户口"],"detail":"户口核验是购房前的必要步骤，尤其对有学区需求的客户。核验方法：买卖双方持身份证和不动产权证到辖区派出所打印户籍底档，确认房屋地址下无其他户口。遗留户口的法律困境：公安机关无权强制迁出他人户口，法院一般不支持强制清户诉讼。应对措施：在购房合同中约定户口迁出时限和逾期违约金（建议每日按总房款万分之五计算），预留户口迁出保证金（建议5-10万元）。","legalRef":"《户口登记条例》第10条（户口迁出）；《中华人民共和国民法典》第577条（违约责任）","consumerBenefit":"不买有遗留户口的房子，学区名额不被占","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["空户确认方法","户口核验流程","房子里有别人户口怎么办"]},{"id":"PRE-MATCH-045","name":"北向房子到底能不能住","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"朝北的房子是不是完全不能住？便宜能买吗？","ola":"冬天阴冷但便宜10%-20%，刚需预算有限可以考虑","cp":["全年无直射阳光冬季阴冷","比南向便宜10%-20%","夏季凉爽是优势","适合预算有限刚需和出租","高楼层+暖色装修弥补采光"],"detail":"北向房屋的核心问题是全年无直射阳光，冬季阴冷、通风差、易潮湿。但也有优势：夏季比南向凉爽、价格比同小区南向低10%-20%。北向房屋适合以下人群：预算有限但想进核心区域的刚需、夏季怕热人群、投资出租（租客对朝向敏感度低于买家）。改善北向居住体验的方法：选高楼层增加漫射光、暖色灯光和装修弥补采光、选通风好的户型。","legalRef":"《民用建筑设计统一标准》GB50352-2019","consumerBenefit":"用价格换朝向，预算有限也能住核心区","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["朝北的房子能买吗","纯北向住着怎么样","北向房间采光差怎么办"]},{"id":"PRE-MATCH-048","name":"小区住户构成怎么判断好不好","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"怎么知道一个小区的邻居都是什么人？这重要吗？","ola":"问物业+观察公共区域，住户构成影响社区氛围和房价","cp":["与物业交流了解住户类型","观察公共区域和车辆品牌","出租客为主的小区通常折价","改善型家庭为主溢价5%-15%","住户构成影响社区氛围和房价"],"detail":"小区住户构成影响居住氛围和房产价值。了解途径：与物业或维护人交流了解主要住户类型；观察小区公共区域的使用状况和车辆品牌；查看周边学校分布判断是否有学区家庭聚集；通过贝壳APP查看小区成交记录分析买家画像。住户构成对房价的影响：同品质小区，业主以改善型家庭为主的通常比出租客为主的小区溢价5%-15%，因维护意识更强、社区氛围更好。","legalRef":"《物业管理条例》第33条","consumerBenefit":"选对邻居群体住着舒心，房子还更保值","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["小区业主群体怎么判断","住户素质怎么看","小区居住人群类型"]},{"id":"PRE-MATCH-051","name":"顶楼能不能买漏水概率多大","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"顶楼会不会经常漏水？能不能买？","ola":"新盘顶楼漏的概率低，老小区看防水翻新，雨天检查","cp":["老小区顶楼漏水概率高","新建商品房防水技术大幅改善","顶楼采光好无楼上噪音","比中间层折价5%-15%","雨天看房检查漏水最有效"],"detail":"顶楼的核心风险是漏水和隔热差。老小区顶楼漏水概率较高，尤其是房龄10年以上且未做过防水翻新的；新建商品房顶楼防水技术已大幅改善，5年内漏水概率低于5%。顶楼优点：采光好、视野开阔、无楼上噪音、价格比中间层低5%-15%、可能带露台。检查漏水方法：看天花板有无水渍或漆色不均、选择雨天看房、查看物业维修记录。建议选5年内新盘顶楼或已做防水翻新的老顶楼。","legalRef":"《住宅设计规范》GB50096-2011","consumerBenefit":"选对顶楼省5%-15%还住得舒服，不踩漏水坑","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["顶楼漏水风险大吗","顶楼优缺点是什么","顶楼能不能买"]},{"id":"PRE-MATCH-055","name":"人车分流和部分分流有什么区别","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"人车分流的小区和不分流的差别大吗？","ola":"完全人车分流最安全有孩家庭必选，溢价3%-8%","cp":["完全分流地面无车道最安全","部分分流地面有少量车道","完全分流二手房溢价3%-8%","访客停车是否也在地下需确认","有老人儿童优先选完全分流"],"detail":"人车分流分为完全分流和部分分流。完全人车分流：车辆直接进入地下车库，地面无车道，行人安全、噪音少、绿化面积大，但需确认访客停车是否也在地下。部分人车分流：地面有少量车道或临时停车区，成本低于完全分流但仍有一定安全隐患。完全人车分流小区通常物业费更高，但二手房溢价约3%-8%。家中有老人儿童的优先选择完全人车分流小区，安全性显著提升。","legalRef":"《城市居住区规划设计标准》GB50180-2018","consumerBenefit":"选对人车分流方案，孩子老人在小区活动更安全","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["人车分流好不好","完全人车分流什么意思","部分人车分流够不够"]},{"id":"PRE-MATCH-056","name":"复式和跃层哪个更值得买","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"复式和跃层有什么区别？哪个更好住？","ola":"跃层空间完整舒适但面积算两层，复式得房率高","cp":["复式上层是夹层高度有限","跃层是完整两层面积按两层算","复式面积按单层计算","自住选跃层投资选复式","楼梯占空间老人上下不便"],"detail":"复式住宅是在层高较高的一层中增建夹层形成上下两层，上层是夹层高度有限；跃层住宅是跨越上下两个完整楼层且有套内楼梯。核心区别：复式总层高低于跃层，上层空间较矮；跃层是完整的两层面积按两层计算，复式面积按单层计算（部分城市复式上层不算面积）。选择建议：自住选跃层空间更舒适；投资选复式得房率高（买一层得两层使用面积）。注意复式楼梯占空间且老人上下不便。","legalRef":"《住宅设计规范》GB50096-2011第5.1.1条","consumerBenefit":"分清复式跃层不买错，选到最适合的户型","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["复式和跃层区别是什么","复式房好不好","跃层值得买吗"]},{"id":"PRE-MATCH-070","name":"新房样板间能信吗","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"样板间和实际交房一样吗？","ola":"不一样，家具缩小品牌降级是常态","cp":["家具缩尺镜面扩容是标配","看清非交付标准标注","要求看交付标准样板间","样板间≠交付现实"],"detail":"样板间是营销工具不是交付标准，常见美化手法：①家具缩尺（1.8米床换成1.5米显得空间大）；②镜面扩容（大量镜面和玻璃视觉放大空间）；③非交付标准（展示的进口品牌实际交付可能换国产）；④打通空间（拆除非承重墙展示大空间实际有隔墙）。务必看清水牌标注'非交付标准'，要求看交付标准样板间。","legalRef":"《商品房销售管理办法》第31条样板房交付标准约定","consumerBenefit":"不被样板间忽悠","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["样板间和交付一样吗","样板间有什么套路","精装样板间真实吗"]},{"id":"PRE-MATCH-079","name":"看房要不要看电梯","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"电梯质量怎么看？","ola":"看品牌数量速度年检，高峰实测等梯时间","cp":["30层以上至少2部电梯","大牌故障率低杂牌高","高层速度应2.5m/s以上","看年检标贴和实测候梯时间"],"detail":"电梯直接影响高层住户日常体验。看房查电梯：①数量（30层以上至少2部、1部电梯故障等于瘫楼）；②品牌（三菱/通力/奥的斯等大牌故障率低、杂牌故障率高）；③速度（高层应选2.5m/s以上否则等候久）；④维保记录（电梯内年检标贴是否在有效期内）；⑤候梯时间（早晚高峰实测等电梯时间，超3分钟不可接受）。","legalRef":"《特种设备安全法》电梯定期检验要求","consumerBenefit":"电梯不卡不瘫住得顺","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["电梯品牌重要吗","电梯数量怎么看","电梯经常坏怎么办"]},{"id":"PRE-MATCH-080","name":"新房交房时间怎么确认","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"期房多久能交房？","ola":"合同写明18-36个月，精装再晚半年","cp":["合同约定交房日期不接受模糊","精装比毛坯晚6-12个月","逾期违约金日万分之1-3合理","央企国企延期概率低"],"detail":"期房交房时间在合同中明确约定，通常为签约后18-36个月。精装比毛坯交付晚6-12个月。合同必须约定：①确切交房日期（不接受'约''左右'等模糊表述）；②逾期违约金（日万分之1-3为合理标准）；③交房标准附件。延期交房常见且维权难，选央企/国企开发商延期概率相对低。签约时务必关注交房时间和违约责任条款。","legalRef":"《商品房买卖合同示范文本》第9条交付期限及违约责任","consumerBenefit":"交房时间有底延期有赔偿","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["交房时间合同怎么写","交房延期怎么办","交房和交付是一回事吗"]},{"id":"PRE-MATCH-085","name":"新房和二手房看房重点有什么不同","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"新房和二手房看房关注点一样吗？","ola":"不同，新房看规划二手房查现状","cp":["新房看规划兑现能力","二手房查硬装和隐蔽问题","新房风险在未来兑现","二手房风险在过去遗留"],"detail":"新房看房特点：主要看沙盘+样板间+规划图（实物不可见），重点关注开发商品牌、规划落实可能性、交付标准、周边规划。二手房看房特点：所见即所得，重点查硬装细节、漏水老化、邻里噪音、物业管理。新房风险在'未来兑现'（规划可能缩水），二手房风险在'过去遗留'（隐蔽问题需挖掘），看房重点截然不同。","legalRef":"行业通行做法","consumerBenefit":"不同类型看房有侧重","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["新房二手房看房区别","新房看什么二手房看什么","期房没建好怎么判断"]},{"id":"PRE-MATCH-089","name":"选房要看重开发商品牌吗","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"大开发商的房子一定比小开发商好吗？","ola":"烂尾风险低但不等于品质一定好，小开发商查清再买","cp":["品牌资金安全烂尾风险低","交付和物业相对可靠","品牌不等于品质绝对保证","小开发商查口碑和资金再决定"],"detail":"品牌开发商核心优势：资金安全（烂尾风险极低）、交付相对可靠（减配概率低）、物业自营品质稳、品牌溢价保值强。但品牌不等于品质绝对保证（大品牌也有减配投诉）。小开发商不是不能买但要查：已交付项目口碑、资金状况（有无诉讼/被执行记录）、是否五证齐全。预算允许优先选品牌，预算紧查清小开发商再决定。","legalRef":"行业通行做法","consumerBenefit":"开发商选择有依据","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["大开发商好在哪","品牌开发商有什么优势","小开发商房子能买吗"]},{"id":"PRE-MATCH-091","name":"同户型不同楼层怎么选","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"同户型高楼层贵几万值不值？","ola":"黄金楼层贵5%但住着好太多值得花","cp":["黄金楼层贵5-10%但值得","极端楼层便宜10-15%但有硬伤","便宜不等于划算","老人低层年轻人中高层"],"detail":"同户型不同楼层选择：黄金楼层（总楼层1/3-2/3）比低楼层贵5%-10%但居住体验差距显著（采光通风噪音安全全面碾压），值得多花。极端楼层（顶楼/一楼）比中间楼层便宜10%-15%但硬伤明显（顶楼漏热、一楼潮噪安全差），便宜不等于划算。有老人选3-5楼、年轻人选中高层、预算紧选中低楼层避开极端层。","legalRef":"行业通行做法","consumerBenefit":"楼层差价花得值","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["同户型高低楼层怎么挑","同户型楼层价格差多少","好楼层值得多花钱吗"]},{"id":"PRE-MATCH-100","name":"新房沙盘图可信吗","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"沙盘上看着很好能信吗？","ola":"看大方向别信细节，查规划文件验证","cp":["沙盘美化楼间距绿化都可能偏大","配套可能只是规划未落地","查规划许可证和政府文件验证","沙盘看大方向不看细节"],"detail":"沙盘是营销展示工具，美化是常态：①楼间距可能拉大显得宽松（实际更密）；②绿化可能过度呈现（实际绿地率更低）；③周边配套可能标注规划中的（未落地）；④建筑高度可能调整（以审批为准）。验证方法：查规划许可证确认指标、问已交付业主实际感受、查政府规划文件确认周边配套落地情况。沙盘只看大方向不看细节。","legalRef":"行业通行做法","consumerBenefit":"不被沙盘美化忽悠","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["沙盘规划能兑现吗","沙盘有什么猫腻","沙盘和实际差别大吗"]},{"id":"PRE-MATCH-101","name":"选房要考虑电梯维保吗","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"电梯质量不好怎么办？","ola":"看年检问故障频率，老电梯别碰","cp":["看年检标贴是否在有效期","问业主故障频率月均>1次不行","超15年电梯故障率高","查大修基金是否充足"],"detail":"电梯维保直接影响日常使用安全。查看要点：①电梯内年检合格标贴（应在有效期内、超期未检有安全隐患）；②维保单位（专业维保公司优于物业自维保）；③故障频率（问已入住业主电梯故障频率，月均>1次不可接受）；④大修基金（查物业是否有电梯大修/更换专项资金）。超15年老旧电梯故障率高，选房时需特别关注。","legalRef":"《特种设备安全法》电梯使用登记及定期检验","consumerBenefit":"电梯安全有保障","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["电梯坏了谁修","电梯维修基金有吗","电梯年检怎么看"]},{"id":"PRE-MATCH-104","name":"买二手房要不要问卖家为什么卖","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"卖家为什么卖房要不要问？","ola":"要问，议价空间和风险都在原因里","cp":["换房急用钱离婚议价空间大","套现看空需自己也谨慎","隐问题脱手需深入排查","通过中介侧面了解更有效"],"detail":"了解卖方售房原因有助于判断议价空间和潜在风险：①换房升级（正常需求价格可谈空间适中）；②急用钱/离婚分割（议价空间大但需确认产权清晰无纠纷）；③投资套现/看空后市（议价难但需思考是否自己也该谨慎）；④房屋有隐问题想脱手（需深入排查）。问法技巧：通过中介侧面了解比直接问更有效，卖方不一定说实话。","legalRef":"行业通行做法","consumerBenefit":"售房原因有玄机","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["卖家卖房原因重要吗","卖家急售说明什么","卖房原因影响价格吗"]},{"id":"PRE-MATCH-CASE-001","name":"手绘生活地图+VR视频服务独居老人","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"老人不方便出门看房怎么办？","ola":"VR看房+手绘地图送到手上","cp":["VR视频解决老人出行难","生活地图精准匹配需求","连美缝都查是极致用心","精准匹配+人文关怀结合"],"detail":"上海经纪人詹昌来服务七旬独居老人，自学做带语音讲解的VR视频，手绘新居周边生活地图标注菜场医院公交站，装修期每周拍工地视频连瓷砖美缝都查。老人不用跑腿就能全面了解新居环境，体现了精准匹配与人文关怀的结合。","legalRef":"人民网2025","consumerBenefit":"不出门就能全面了解新居环境","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"器","meetingPhase":["见前","见后"]},"alias":["独居老人VR看房服务","詹昌来手绘生活地图","服务老人特殊需求案例"]},{"id":"PRE-MATCH-CASE-003","name":"许慧芸告知老人离世","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"经纪人会隐瞒房源不利信息吗？/ 该不该要求经纪人如实告知？","ola":"法律允许沉默时说真话最值钱","cp":["法律允许沉默仍选择说真话","客户半小时后回来找她","两周内签约另一套","一次诚实换终身信任"],"detail":"链家长沙经纪人许慧芸即将签约时发现房源曾有老人离世，法律上非凶宅可沉默成交，但她选择如实告知客户。客户放弃购买，半小时后回来说'虽然不买了买房还找你'，两周内签约另一套。许慧芸说'成交很重要但如实告知更重要'。法律允许沉默时选择说真话，是透明要素最极致的体现，一次诚实换来终身信任。","legalRef":"新华网2025","consumerBenefit":"不被隐瞒关键信息，做出知情决策","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"器","meetingPhase":["见前","见后"]},"alias":["告知老人离世案例","许慧芸说真话","非凶宅也如实告知"]},{"id":"PRE-NEED-032","name":"首付来源银行会查吗","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"首付钱是我东拼西凑的，银行会查吗？","ola":"会查近6个月流水，借贷资金付首付会被拒贷","cp":["银行追溯近6个月首付流水","消费贷经营贷不得付首付","父母赠与需签声明+转账记录","来源不合规直接拒贷","自有资金是唯一合规来源"],"detail":"2021年起银保监会要求银行严格审查首付款资金来源，重点排查消费贷、经营贷、信用贷等借贷资金流入楼市。审查方式：追溯首付资金近6个月流水，要求首付款来源于自有资金（工资、存款、理财赎回、父母赠与）。父母赠与需签署赠与声明并附转账记录。如发现借贷资金付首付，银行将拒贷并可能要求提前归还已发放贷款。首付款来源不合规是最常见的隐性拒贷原因。","legalRef":"《关于防止经营用途贷款违规流入房地产领域的通知》（银保监办发〔2021〕17号）；《个人贷款管理暂行办法》第14条、第18条","consumerBenefit":"合规准备首付，不因资金来源被拒贷","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["首付资金审查","首付钱从哪来要查","消费贷付首付行不行"]},{"id":"PRE-NEED-040","name":"怎么判断中介有没有套路","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"怎么判断中介说的靠不靠谱，有没有套路？","ola":"口头承诺不写合同就是套路，所有承诺必须落纸面","cp":["制造紧迫感催促签约","虚假房源引流再换房","口头承诺不写合同等于零","签约后加收隐藏费用","所有承诺必须写入合同"],"detail":"常见中介套路五大类：制造紧迫感（谎称多人看中催促签约）、虚假房源（低价优质房引流再推荐其他）、夸大承诺（承诺学区/贷款/落户但不在合同中约定）、隐藏费用（签约后加收评估费/代办费等）、双面议价（分别向买卖双方报不同价格赚取差价）。防范措施：所有承诺必须写入合同补充条款、坚持查看不动产权证原件、不签空白条款合同、确认中介机构备案资质。","legalRef":"《房地产经纪管理办法》第22条（禁止行为的13种情形）；第25条（罚则）","consumerBenefit":"识别套路不上当，只信合同不信嘴","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["中介套路识别","经纪人常见骗局","房产中介坑人手段"]},{"id":"PRE-NEED-056","name":"养宠家庭选房要注意什么","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我养了一只金毛，买房有什么要注意的？","ola":"先确认物业允许养宠，低楼层遛狗方便，注意犬种限制","cp":["确认物业是否允许养宠","低楼层方便遛狗但有噪音风险","大型犬需考虑电梯空间","户型需有独立宠物活动区","了解当地养犬管理条例"],"detail":"养宠家庭选房需关注三个维度：一是小区物业管理是否允许养宠、有无宠物活动区域和便溺设施；二是楼层选择，低楼层方便遛狗但可能受噪音投诉困扰，高楼层需考虑电梯空间对大型犬的适配性；三是户型方面，建议选择有独立阳台或玄关过渡区的户型，方便宠物活动区与生活区分离。此外需了解当地养犬管理条例对犬种和数量的限制。","legalRef":"《中华人民共和国动物防疫法》第30条；各地养犬管理条例","consumerBenefit":"入住后不因养宠与物业邻居产生纠纷","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["养宠物买房注意什么","养猫养狗选什么房子","宠物友好型小区怎么选"]},{"id":"PRE-NEED-059","name":"买房选新区好还是老城区好","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我想买房子，选老城区还是新区好？","ola":"要配套选老城，要户型选新区，看规划判断潜力","cp":["老城区配套成熟但房龄老","新区户型好但配套待完善","看政府规划判断新区潜力","地铁规划是新区价值关键信号","人口净流入是区域发展基础"],"detail":"新区与老城区的选择取决于客户核心需求优先级。老城区优势在于配套成熟（学校、医院、商业齐全）、通勤时间短、生活便利；劣势是房龄偏老、户型落后、停车困难。新区优势在于规划新、户型好、环境优、价格相对低；劣势是配套尚未完善、通勤距离可能较远、区域发展存在不确定性。判断新区潜力可关注：政府规划文件、地铁线路规划、头部开发商入驻情况、人口净流入数据。","legalRef":"《中华人民共和国城乡规划法》第2条","consumerBenefit":"根据自身需求做对选择，不因区域误判后悔","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["新区和老城区哪个好","买新房选新区还是市中心","新区发展潜力大吗"]},{"id":"PRE-NEED-064","name":"跨区买房要注意哪些政策差异","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我想从A区买到B区，两边政策有什么不一样吗？","ola":"限购、学区、税费各区都可能不同，必须逐项核实","cp":["限购条件各区可能不同","学区政策差异最显著","税费标准可能有地方差异","公积金贷款额度因区而异","跨区购房前必须逐项核实"],"detail":"同一城市不同行政区的购房政策可能存在显著差异。主要差异点包括：限购条件（社保缴纳区域要求、户籍要求）、学区政策（划片规则、入学条件）、税费标准（部分地区有地方附加税差异）、贷款政策（公积金贷款额度可能不同）、限售期限等。例如北京各区的入学政策不同，朝阳区和海淀区的多校划片规则差异大。跨区购房前必须逐项核实目标区域的具体政策。","legalRef":"各地住建部门限购实施细则","consumerBenefit":"提前核实避免因政策差异导致购房资格或入学出问题","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["不同区买房政策一样吗","跨区购房限购不同吗","学区政策各区一样吗"]},{"id":"PRE-NEED-065","name":"连环单风险有多大怎么防范","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我要卖掉现在的房子再买新的，万一卖不掉怎么办？","ola":"优先先卖后买，合同加售房付款条件，预留3个月缓冲","cp":["资金链断裂是最大风险","优先先卖后买降风险","合同约定以售房款为付款条件","预留至少3个月资金缓冲","同一经纪人协调两笔交易进度"],"detail":"连环单是指客户在同一时期既卖旧房又买新房的交易。主要风险：一是资金链断裂风险，旧房未及时卖出导致新房首付款无法到位；二是时间错配风险，新房合同约定的付款节点与旧房回款时间不匹配；三是合同违约风险，任一环出问题可能引发连锁违约。防范措施：优先选择先卖后买；在买方合同中约定'以售房款为付款条件'的免责条款；预留至少3个月资金缓冲期；两笔交易用同一经纪人协调进度。","legalRef":"《中华人民共和国民法典》第563条（合同法定解除权）","consumerBenefit":"连环单不出资金断裂，旧房没卖也不违约新房合同","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["连环单有什么风险","卖旧买新怎么防风险","连环交易出问题怎么办"]},{"id":"PRE-NEED-067","name":"预算做了但看房越看越贵怎么办","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"看了几套房觉得还是贵的好，但预算已经超了，怎么办？","ola":"算超预算的月供利息差额，超20%就暂停重新梳理","cp":["区分必要和想要控制升级","算超预算的月供和总利息差额","设定硬性预算上限告知经纪人","超预算20%应暂停重新梳理","用具体数字约束感性升级"],"detail":"看房过程中预算膨胀是常见现象，原因有三：一是接触更优质房源后需求升级；二是经纪人引导看超出预算的房源；三是对自身支付能力的误判。控制方法：回看核心需求清单，区分'必要'和'想要'；计算超预算部分的月供差额和总利息差额，用具体数字提醒自己；设定硬性预算上限并告知经纪人；如超预算超过20%说明需求定位出了问题，应暂停看房重新梳理需求。","legalRef":"《中华人民共和国民法典》第240条（所有权）","consumerBenefit":"不被'越看越贵'的陷阱裹挟，守住财务安全线","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["看房越看越贵怎么控制","买房预算超了怎么办","越看越贵怎么理性回归"]},{"id":"PRE-NEED-068","name":"买房家人意见不统一怎么协调","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我和老公对在哪个区买房意见不一致，怎么协调？","ola":"列出各自底线找共识，谁出钱谁住多谁说了算","cp":["列出不可妥协项和可妥协项","谁出钱谁住得多谁说了算","引入第三方数据理性决策","设定决策截止时间防拖延","避免一方完全妥协长期不满"],"detail":"家庭成员购房意见分歧是常见问题，通常集中在区域选择、预算标准、户型偏好三个方面。协调方法：先让每位家庭成员列出自己的'不可妥协项'和'可妥协项'，交叉比对找出共识；对分歧点采用'谁出钱/谁住得多谁说了算'原则；引入第三方数据（成交价、通勤时间、学区排名）辅助理性决策；设定决策截止时间避免无限拖延；避免一方完全妥协导致入住后长期不满。","legalRef":"《中华人民共和国民法典》第1062条（夫妻共同财产）","consumerBenefit":"家庭决策不伤感情，找到大家都接受的方案","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["家人不同意买房方案怎么办","夫妻买房意见不一致","父母和子女买房分歧"]},{"id":"PRE-NEED-074","name":"三胎家庭选房有什么特殊要求","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我们三个孩子，买什么样的房子才够住？","ola":"至少四室两卫150平以上，三卫和储物空间别省","cp":["至少四室两卫理想五室三卫","储物空间需求大幅增加","厨房操作台面不低于4米","建筑面积建议150平以上","餐厨空间需容纳大家庭"],"detail":"三胎家庭对房间数量和功能区有更高要求。至少需要四室两卫（主卧+三间儿童房），理想为五室三卫。若与老人同住则需五室以上。卫生间至少两卫，三卫更佳，减少早高峰排队。储物空间需求大幅增加，建议选择有独立储物间或入户储物柜的户型。餐厨空间需容纳大家庭用餐，厨房建议U型或L型操作台面不低于4米。建筑面积建议150平方米以上。","legalRef":"《人口与计划生育法》第18条","consumerBenefit":"一步到位不因人口增长又换房","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["三孩家庭买房注意什么","三个孩子要几室房","三胎户型需求"]},{"id":"PRE-NEED-078","name":"买期房好还是买二手房好","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"买期房和买二手房到底哪个更划算？","ola":"急住选二手所见即所得，不急选期房户型新但防烂尾","cp":["期房户型新但存在烂尾风险","二手房所见即所得即买即住","期房交房等1-3年","急需入住选二手房","看重户型选期房但需防烂尾"],"detail":"期房与二手房各有利弊。期房优势：户型新设计合理、小区规划新配套好、价格可能低于同区域二手房；劣势：交房等待1-3年、存在烂尾风险、实际交付可能与宣传不符、维权成本高。二手房优势：所见即所得、即买即住、周边配套成熟可实地考察、交易流程相对规范；劣势：房龄偏老户型可能过时、税费可能更高（不满二）、装修可能需重做。选择依据：急需入住选二手房，不急入住且看重户型选期房。","legalRef":"《中华人民共和国城市房地产管理法》第45条","consumerBenefit":"根据自身情况选对购房类型，不踩坑","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["期房和二手房怎么选","新房期房风险大吗","期房和现房优劣对比"]},{"id":"PRE-NEED-079","name":"买房被限购政策卡住怎么办","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我社保年限不够买不了房，有什么办法吗？","ola":"等社保达标最稳，人才引进可加速，商业公寓不限购","cp":["等待社保个税达标最稳妥","人才引进可缩短年限","商业公寓不限购但税费高","公司名义购房税费高限制多","假结婚虚构社保属违法"],"detail":"被限购政策卡住后的合法出路：一是等待条件满足，如继续缴纳社保或个税直到达标；二是人才引进，部分城市对高学历或紧缺人才放宽购房限制，可申请人才购房资格；三是购买不限购区域或不限购类型的房产，如商业性质公寓（但税费高、产权40年）；四是以公司名义购买（但公司购房税费高、再次转让限制多）。严禁通过假结婚、虚构社保等违法手段规避限购，一旦查实合同无效且可能面临行政处罚。","legalRef":"《中华人民共和国城市房地产管理法》第45条","consumerBenefit":"找到合法出路不因限购焦虑做出违法选择","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["没有购房资格怎么办","限购了还能买房吗","不满足限购条件怎么解决"]},{"id":"PRE-NEED-085","name":"买房到底为了什么","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我还没想清楚为什么要买房，你能帮我理理吗？","ola":"先想清楚自住还是投资，再选房不走弯路","cp":["先问动机再选房","五类动机对应不同策略","动机决定预算弹性","刚需最怕拖延投资最怕站岗"],"detail":"客户购房动机直接影响选房策略和决策效率。常见动机分为自住刚需、改善换房、学区教育、投资保值、养老安居五类。不同动机下，客户对价格敏感度、区域偏好、户型需求差异巨大。经纪人应在带看前通过2-3个关键问题快速锚定客户核心动机，避免无效带看和沟通成本浪费。","legalRef":"行业通行做法","consumerBenefit":"明确方向，不花冤枉时间看错房","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["买房目的是啥","购房动机","为啥要买房"]},{"id":"PRE-NEED-098","name":"要不要买带装修的房子","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"带装修的房子靠谱吗，还是自己装？","ola":"急住选精装但一定验房，不急选毛坯自装","cp":["精装省时但质量参差","毛坯自装品质可控但耗时","精装必须专业验房","重点查水电防水隐蔽工程"],"detail":"精装房省时省力但质量参差，常见问题：用材降标、隐蔽工程粗糙、风格不讨喜。毛坯房可按自己喜好装修但耗时6-12个月且成本不可控。建议：刚需急入住选精装但务必细验、改善追求品质选毛坯自装、投资出租选精装省事。精装房验房必须找专业验房师，重点查水电防水三大隐蔽工程。","legalRef":"《商品房销售管理办法》第31条精装修交付标准","consumerBenefit":"装修不踩坑，住得安心","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["精装房好不好","毛坯和精装怎么选","带装修的房子能买吗"]},{"id":"PRE-NEED-102","name":"楼层怎么选比较好","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"这栋楼30层，我买哪层比较好？","ola":"10-20层黄金区间，避开腰线层和设备层","cp":["总楼层1/3-2/3是黄金区","顶楼怕漏水热一楼怕潮噪","腰线层设备层要避开","有老人选低层年轻人选高"],"detail":"楼层选择需综合采光、噪音、安全、价格。总楼层1/3-2/3区间为黄金楼层，采光通风均优且不至太高。顶楼风险：漏水、夏天热、电梯故障爬楼；一楼风险：潮湿、蚊虫、噪音、安全差。有老人家庭选3-5楼，年轻人可选中高楼层。注意腰线层、设备层、槽钢层这三类特殊楼层避开。","legalRef":"行业通行做法","consumerBenefit":"楼层选对住得舒服好出手","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["买几楼好","高层好还是低层好","一楼好不好"]},{"id":"PRE-NEED-106","name":"买房子周边配套怎么看","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"看房时周边配套怎么判断好不好？","ola":"步行10分钟能买菜看病就是好配套","cp":["一级配套步行10分钟必须齐","二级配套车程10分钟","缺配套生活品质断崖","自住至少一二级全满足"],"detail":"周边配套分三级：一级配套（步行10分钟内）包括超市、菜场、药店、便利店；二级配套（车程10分钟内）包括医院、学校、商场、银行；三级配套（车程20分钟内）包括公园、文体设施、大型商业。自住至少满足一级+二级配套齐全，缺任何一项都会显著影响日常生活便利度。","legalRef":"行业通行做法","consumerBenefit":"生活方便，不用天天跑远路","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["配套怎么判断好坏","生活配套有哪些","周边配套重不重要"]},{"id":"PRE-NEED-118","name":"买公寓和住宅有什么不同","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"公寓比住宅便宜能买吗？","ola":"自住别买公寓，不能落户没学区贷款难","cp":["公寓不能落户无学区","首付50%贷10年限制大","水电商价贵一倍","自住必须选住宅"],"detail":"公寓vs住宅核心区别：①产权年限（公寓40/50年、住宅70年）；②首付比例（公寓50%起、住宅20%-30%）；③贷款年限（公寓最多10年、住宅30年）；④落户学区（公寓不能落户无学区、住宅可以）；⑤水电费（公寓商电商水贵1倍、住宅民水电）；⑥交易税费（公寓差额税费高）。自住刚需必须选住宅，投资出租可选公寓。","legalRef":"《城镇国有土地使用权出让转让暂行条例》第12条出让年限","consumerBenefit":"不买错产品类型","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["公寓能买吗","公寓住宅区别在哪","40年产权和70年区别"]},{"id":"PRE-NEED-119","name":"买房自己住要不要考虑以后卖","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我就自己住，不用管以后好不好卖吧？","ola":"要管，5年内换房概率超六成","cp":["5-10年换房概率超60%","流动性差可能降价仍难卖","核心地段主流户型流通好","自住也要选流通性强的"],"detail":"自住房也必须考虑未来流动性，因为人生变故不可预知（换工作城市、家庭结构变化、财务状况变化），5-10年内有换房概率超60%。流动性差的房子在需要出手时可能降价20%-30%仍难成交。选择标准：核心地段>远郊、品牌开发商>小开发商、主流户型>奇葩户型、配套成熟>配套缺失。","legalRef":"行业通行做法","consumerBenefit":"将来想卖卖得出不吃亏","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["自住房要考虑流动性吗","自住不用管以后好不好卖吧","自住房也要看保值吗"]},{"id":"PRE-NEED-120","name":"家里有小孩选房注意什么","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"家里有小孩，买房要特别注意什么？","ola":"人车分流+近学校+有游乐区+安全防护","cp":["人车分流保孩子安全","距学校步行15分钟内","要有儿童活动区","高层装防护网栏杆间距≤11cm"],"detail":"有小孩家庭选房六大要点：①小区内人车分流（孩子活动安全）；②护栏和阳台高度足够（防攀爬）；③距学校步行15分钟内（接送方便）；④有儿童活动区和游乐设施；⑤远离主干道和商业街（噪音和安全隐患）；⑥物业对儿童活动有管理。高层务必装防护网/窗限位器，阳台栏杆间距≤11cm防卡头。","legalRef":"《住宅设计规范》GB50096-2011阳台栏杆间距≤11cm","consumerBenefit":"孩子安全有保障，上学近方便","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["带小孩买房怎么选","小孩安全选房要点","儿童友好小区"]},{"id":"PRE-NEED-129","name":"预算卡在两个档位怎么选","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"预算刚好卡在两档之间怎么选？","ola":"保月供安全，差额5%内可上超5%果断降","cp":["需求刚性不能降档","月供安全线比面积重要","差额5%内可咬牙15%果断降","借父母可借网贷不可"],"detail":"预算卡在两档时决策逻辑：①看人口需求是否刚性（三口必须三居则不能降两居）；②看未来3年收入增长预期（稳定增长可稍超预算）；③看超预算部分的资金来源（借父母可、借网贷不可）；④看两档房价差占比（差5%以内咬牙上、差15%以上果断降）。原则：宁可面积小点也别月供超50%，刚需保月供安全线优先。","legalRef":"行业通行做法","consumerBenefit":"不因冲动超预算日后痛苦","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["预算尴尬期怎么办","差一档买不起怎么办","预算不够上大户型"]},{"id":"PRE-NEED-131","name":"买房子要不要装新风系统","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"新房要不要装新风系统？","ola":"临街或雾霾区建议装，每年换滤芯别忘","cp":["不开窗换气过滤PM2.5","临街/雾霾/新装修推荐装","中央8000-2万壁挂2-5千","每年换滤芯500-1000元"],"detail":"新风系统核心价值：不开窗即可通风换气、过滤PM2.5等颗粒物、排出室内甲醛和湿气。适用场景：①临街噪音大需关窗；②北方雾霾频发地区；③刚装修需排甲醛；④南方梅雨季防潮。中央新风安装成本8000-20000元，壁挂式2000-5000元。需定期更换滤芯（每年500-1000元），维护成本不容忽视。","legalRef":"行业通行做法","consumerBenefit":"空气好不用开窗吸灰","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["新风系统有必要吗","新风和空气净化器哪个好","新风系统多少钱"]},{"id":"PRE-NEED-135","name":"买房到底选几梯几户的楼好","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"一梯两户和两梯四户哪个好？","ola":"一梯两户最好，等梯快私密好","cp":["一梯两户最优两梯四户可接受","两梯六户以上太拥挤","高层至少两梯","梯户比低单价高5-10%但值得"],"detail":"梯户比决定电梯等候时间和居住密度。一梯两户最优（私密性好、等梯短、南北通透率高），两梯四户可接受，两梯六户及以上拥挤且户型多为单侧朝向。高层超30层建议至少两梯，早晚高峰等梯超5分钟很痛苦。梯户比低的楼栋单价高5%-10%但居住体验差距明显。优先选一梯两户或两梯三户。","legalRef":"《住宅设计规范》GB50096-2011电梯设置要求","consumerBenefit":"不用天天苦等电梯","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["一梯两户好还是两梯四户好","电梯数量怎么选","几梯几户住着舒服"]},{"id":"PRE-PRICE-001","name":"这套房子值不值这个价怎么判断","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"中介报的这个价格合理吗？怎么判断值不值？","ola":"找同小区3套以上成交价对比，楼层朝向装修加减分","cp":["市场比较法找同小区3套以上成交","楼层每层±1%-2%","南北比东西贵5%-10%","精装比毛坯贵800-2000元/㎡","用成交价不用挂牌价做基准"],"detail":"判断房价合理性最实用的方法是市场比较法：找到同小区3套以上近期成交的相似房源（面积/楼层/朝向/装修相近），取均价作为基准价，再根据楼层差（每层±1%-2%）、朝向差（南北比东西贵5%-10%）、装修差（精装比毛坯贵800-2000元/㎡）、楼层/采光/学区的加减分项调整。成交价参考住建局官网或贝壳平台历史成交，不要用挂牌价做基准（挂牌价比成交价高5%-15%）。","legalRef":"《房地产估价规范》GB/T50291-2015第4章（比较法）","consumerBenefit":"不被高价忽悠，砍价有理有据","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["房价评估方法","怎么判断报价合不合理","市场比较法怎么用"]},{"id":"PRE-PRICE-004","name":"怎么砍价最有效","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"想砍价但不知道怎么开口，有什么好方法？","ola":"做功课→指瑕疵→多套对比→低开5%→抓急售时机出价","cp":["做足功课掌握3套以上成交价","指出瑕疵作为减分理由","多套对比制造竞争感","首次出价低于心理价位5%-10%","急售信号出现时果断出价"],"detail":"砍价五步法：第一步做足功课——掌握同小区3套以上成交价和该房源挂牌历史；第二步用信息差——指出房屋瑕疵（漏水/噪音/楼层差）作为减分项；第三步多套对比——同时看2-3套相似房源让卖方感受到竞争；第四步合理出价——首次出价低于心理价位5%-10%留谈判空间；第五步促单时机——在卖方急售信号出现时（多次降价/挂牌超90天/换房急售）果断出价。红线：不得虚假报价欺骗对方。","legalRef":"《中华人民共和国民法典》第7条（诚实信用原则）；《房地产经纪管理办法》第22条第7项（不得隐瞒真实价格）","consumerBenefit":"科学砍价省几万到几十万，不靠蛮力靠方法","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["买房砍价技巧","议价五步法","怎么跟房东谈价"]},{"id":"PRE-PRICE-014","name":"继承的房子再卖税费有多高","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"继承的房子想卖掉，税费大概多少？","ola":"不满五唯一个税20%差额，比普通二手房重得多","cp":["不满五唯一个税按差额20%征","不可用1%核定征收","继承房持有年限合并原产权人","赠与房不满2年全额征增值税","无原购房发票个税可能极高"],"detail":"继承/赠与取得的房产再出售时税费显著高于普通二手房：个人所得税方面，若不满足满五唯一条件，只能按差额20%征收（差额=出售价-原购置成本-合理费用），而非普通房源的1%核定征收。增值税方面，继承房产持有年限可合并计算原产权人持有年限（满2年从原产权人取得时起算），但赠与房产不满2年需全额征收5%增值税。继承房的原购置成本以原产权人的购房发票为准，若无发票可能无法抵扣导致个税极高。","legalRef":"《中华人民共和国个人所得税法》第5条；国税发〔2006〕108号；财税〔2009〕78号（个人无偿受赠房屋个税规定）","consumerBenefit":"买继承房前算清税费，不买个税黑洞","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["继承房产出售税费","赠与房产再售20%个税","继承房买卖税费计算"]},{"id":"PRE-PRICE-020","name":"买非普通住宅税费比普通住宅多多少","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"中介说这套房是非普通住宅，税费会多很多吗？","ola":"会多，增值税差额征5%+契税3%，差异可达数万到数十万","cp":["北京五环内>468万或>140㎡为非普","上海内环内>450万或>144㎡","非普增值税满2年差额征5%","契税无首套优惠统一3%","税费差异可达数万至数十万"],"detail":"非普通住宅认定标准各城市不同：北京五环内总价>468万或面积>140㎡、上海内环内总价>450万或面积>144㎡、深圳容积率<1.0或面积>144㎡或成交价高于辖区均价1.2倍。非普通住宅的税费差异：增值税满2年按差额征收5%（普通住宅免征），契税无首套1%优惠统一3%（部分城市），豪宅属性导致个税和增值税均更高。购前必须确认是否为非普通住宅，税费差异可达数万至数十万元。","legalRef":"各城市普通住宅标准文件；《关于调整房地产交易环节契税 营业税优惠政策的通知》（财税〔2016〕23号）","consumerBenefit":"提前判断普非普，不因税费超预算","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["非普住宅认定标准","普通和非普通住宅区别","非普住宅税费差异"]},{"id":"PRE-PRICE-026","name":"婚内房产更名要交税吗","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"房产证上想加上老婆名字，要交税吗？","ola":"夫妻更名免契税增值税个税，只交80元登记费","cp":["夫妻更名免契税增值税个税","仅需交登记费80元","带身份证结婚证原产权证办理","加名后变为夫妻共同财产","持有年限从原取得时间起算"],"detail":"婚姻存续期间夫妻之间房产更名（加减名、份额变更）免征契税、增值税和个人所得税，仅需缴纳不动产登记费80元。办理流程：双方持身份证、结婚证、原产权证到不动产登记中心办理变更登记。注意：婚前房产加名后性质变为夫妻共同财产，离婚时按共同财产分割。夫妻更名后的房产再出售时，持有年限从原取得时间起算，不影响满五唯一认定。","legalRef":"《中华人民共和国契税法》第6条第5项（夫妻更名免征）；《中华人民共和国民法典》第1062条（夫妻共同财产）","consumerBenefit":"夫妻加名几乎零成本，婚后房产共同共有","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["夫妻房产更名免费吗","婚后加配偶名字费用","夫妻房产过户税费"]},{"id":"PRE-PRICE-027","name":"法拍房税费到底有多高","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"法拍房比市场价便宜，但税费到底有多高？","ola":"买卖双方税费全由你出，总计10%-20%加欠费修复","cp":["买方承担全部税费含卖方部分","总税费可达成交价10%-20%","可能有欠缴物业水电暖气费","腾退和装修修复另计","法拍价+税费+欠费+修复=真实成本"],"detail":"法拍房税费由买方全部承担，包括正常交易的卖方税费：增值税、个人所得税、土地增值税、印花税等，加上买方契税1%-3%。总税费可达成交价的10%-20%。此外还可能有欠缴的物业费、水电费、暖气费等。更隐蔽的成本：腾退费用、装修修复费用。参拍前必须算清总成本，法拍价+税费+欠费+修复才是真实成本。","legalRef":"《最高人民法院关于人民法院网络司法拍卖若干问题的规定》法释〔2016〕18号第30条","consumerBenefit":"不看法拍价看真实成本，不算清不举牌","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["法拍房税费计算","司法拍卖房产税费谁出","法拍房隐性成本"]},{"id":"PRE-PRICE-028","name":"开发商优惠价真的优惠吗","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"开发商说现在买有优惠，是真的划算还是套路？","ola":"查备案价对比周边成交价，优惠不写合同等于没有","cp":["虚构原价先提价再打折","特价房多为有瑕疵房源","限时优惠随时可申请","查备案价对比竞品成交价","优惠必须写入合同才有效"],"detail":"开发商优惠常见的三类套路：①虚构原价（先提价再打折，实际成交价与周边持平）②特价房陷阱（特价房多为顶楼/底层/临街/有瑕疵的房源，正常房源无此价）③限时优惠（制造紧迫感但优惠随时可申请）。判断方法：查该楼盘前期备案价（住建局官网可查）、对比同区域竞品成交价、要求书面承诺优惠金额和有效期。所有优惠必须在购房合同中体现，口头承诺的优惠不具有法律约束力。","legalRef":"《商品房销售管理办法》第20条（面积差异处理）、第23条（明码标价）；《价格法》第14条（不正当价格行为）","consumerBenefit":"不被虚假优惠忽悠，只信合同不信宣传","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["新房折扣真假判断","开发商特价房套路","新房优惠活动可信吗"]},{"id":"PRE-PRICE-031","name":"急售房能砍多少下来","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"中介说房东急卖，这种房子能砍多少价？","ola":"急售房通常能多砍5%-15%，但务必核实产权","cp":["急售房议价空间大5%-15%","极端情况可达20%以上","判断信号：低于均价/多次降价","砍价同时必须核实产权状况","急售原因可能暗含隐性风险"],"detail":"急售房通常指业主因资金周转、换房急迫、离异分割、出国等原因需要快速出售的房源。急售房议价空间通常比普通房源大5%-15%，部分极端情况可达20%以上。判断业主是否急售的信号：挂牌价明显低于同小区成交均价、房源带看描述中标注'诚心出售'、挂牌时间短但多次降价、经纪人提示'价格可谈'。但需注意：急售房可能存在隐性风险（抵押、查封等），砍价同时务必核实产权状况。","legalRef":"《中华人民共和国民法典》第5条（自愿原则）","consumerBenefit":"抓住急售机会多砍价，同时规避产权风险","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["急售房砍价空间多大","业主急卖能砍多少","急售房源议价技巧"]},{"id":"PRE-PRICE-032","name":"全款买房能优惠多少","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"如果全款买房，能比贷款便宜多少？","ola":"全款通常优惠3%-8%，急售业主可能给更多","cp":["全款通常优惠3%-8%","交易周期缩短1-2个月","无贷款审批失败风险","市场下行期优惠更大","资金流动性降低是劣势"],"detail":"全款购房相比贷款购房，通常可获得3%-8%的价格优惠。原因：业主无需等待银行放款，交易周期缩短1-2个月；无贷款审批失败风险；业主可更快拿到全款。在市场下行期，全款优惠空间更大，部分急售业主可能给到10%以上折扣。但全款购房也有劣势：资金流动性大幅降低、无法利用贷款杠杆、丧失公积金贷款低利率红利。建议资金充裕且无更好投资渠道时选全款。","legalRef":"《中华人民共和国民法典》第5条（自愿原则）","consumerBenefit":"全款砍价省真金白银，但也要考虑资金流动性","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["全款能便宜多少","全款和贷款差价多大","全款议价空间"]},{"id":"PRE-PRICE-034","name":"谈判时怎么用成交数据说服业主降价","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"怎么用成交数据让房东觉得他开价高了？","ola":"拿3-5套同小区成交价对比，算出合理估价区间","cp":["收集3-5套同小区近期成交数据","对比优劣势列出差异点","计算合理估价区间","用客观数据替代主观判断","数据越具体说服力越强"],"detail":"用成交数据谈判是最有说服力的砍价方法。步骤：第一步，收集同小区3-5套近期成交房源数据（面积/楼层/装修/成交价）；第二步，对比目标房源与成交房源的优劣势，列出差异点；第三步，计算目标房源合理估价区间=成交均价×(1+优势溢价-劣势折价)；第四步，以数据为支撑向业主说明'同户型近期成交XX万，您这套因为XX因素，合理价格应在XX万'。关键是用客观数据替代主观判断。","legalRef":"《中华人民共和国民法典》第5条（自愿原则）","consumerBenefit":"用数据说话砍价更有效，业主无法反驳事实","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["怎么用数据砍价","砍价成交数据怎么用","怎么向业主证明价格高了"]},{"id":"PRE-PRICE-038","name":"赠与的房子再卖税费怎么算","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"赠与的房子再卖出来，税费会不会很高？","ola":"非直系赠与再出售个税20%，直系赠与满五唯一可免","cp":["赠与房再出售个税按20%征收","直系赠与+满五唯一可免","非直系赠与再出售个税极高","法定继承不适用赠与税收规则","购房前必须确认房屋来源"],"detail":"受赠房屋再次出售时，个人所得税按'财产转让所得'20%税率征收，应纳税额=(成交价-原购价-合理费用)×20%。但有两种情况可免征20%个税：一是受赠人是直系亲属或抚养人，且该房屋是受赠人家庭唯一住房且满5年；二是法定继承、遗嘱继承所得房产。非直系赠与再出售个税成本极高，建议购买前确认房屋来源是否为赠与，避免税费远超预期。","legalRef":"《关于个人取得房屋赠与个人所得税计税问题的批复》（国税函〔2009〕975号）；《关于个人转让房屋有关税收问题的通知》（财税〔2009〕78号）","consumerBenefit":"识别赠与房源避高税坑，或者抓住满五唯一免税机会","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["赠与房产再出售税费","受赠房屋卖掉要交多少税","赠与的房子个税怎么算"]},{"id":"PRE-PRICE-042","name":"做低网签价省税有什么法律风险","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"中介建议做低网签价省税，这有什么风险？","ola":"阴阳合同违法，查实追税罚款，贷款额度也减少","cp":["阴阳合同部分条款可能被认定无效","税务部门查实追缴+0.5-5倍罚款","买方未来出售个税反而更多","贷款额度按网签价审批会减少","省的是卖方税增的是买方风险"],"detail":"做低网签价是指买卖双方在网签合同中填写低于实际成交价的价格，以减少税费。这种行为属于阴阳合同，法律风险极高：一是合同部分无效，如发生纠纷法院按真实成交价认定；二是税务部门查实后追缴税款并处0.5-5倍罚款；三是买方未来出售时个人所得税按差额计算，做低导致差额增大个税反而更多；四是银行按网签价审批贷款，做低导致贷款额度减少。做低网签价省的是卖方的税，增加的是买方风险。","legalRef":"《中华人民共和国民法典》第146条（虚假意思表示）；《中华人民共和国税收征收管理法》第63条","consumerBenefit":"了解做低网签价的真实风险，不做违法交易","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["做低合同价省税被查怎么办","网签价低于实际成交价后果","做低房价避税法律后果"]},{"id":"PRE-PRICE-050","name":"这套房子值不值这个价","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"这套房200万值不值？","ola":"查同小区成交价，别看挂牌价看成交价","cp":["成交价>挂牌价别搞反","对比同小区近期成交最准","至少查3套成交价","租金×20-30年验投资价"],"detail":"房价评估三法：①对比法——查同小区同户型近期成交价（最真实）、同板块类似楼盘成交价（区域参考）；②成本法——地价+建安+合理利润+税费=新房合理价；③收益法——年租金×20-30年=投资合理价。其中对比法最实用，成交价>挂牌价，别拿挂牌价当真实市价。务必查3套以上真实成交再判断。","legalRef":"行业通行做法","consumerBenefit":"不买贵不买亏","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["房价怎么判断贵不贵","房子定价合不合理","怎么判断房价虚高"]},{"id":"PRE-PRICE-051","name":"挂牌价和真实成交价差多少","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"挂牌价和实际卖价差多少？","ola":"一般差5-15%，查网签和贝壳成交最准","cp":["挂牌比成交高5-15%","网签数据最权威贝壳成交较真实","热门盘差距小冷门盘大","问清含税价还是净价"],"detail":"挂牌价通常高于真实成交价5%-15%，热门盘差距小（3-5%）、冷门盘差距大（10-20%）。查询真实成交价渠道：①房管局网签数据（最权威但滞后1-3月）；②贝壳等平台历史成交记录（较真实）；③咨询同小区多家中介了解近期成交。注意：中介报的'成交价'可能不含税费，需问清是含税价还是净价。","legalRef":"行业通行做法","consumerBenefit":"真实价格不踩虚高坑","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["挂牌价为什么比成交价高","砍价空间一般多大","挂牌价水分有多少"]},{"id":"PRE-PRICE-052","name":"房价还能再降吗","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"房价还会再降吗现在买合适吗？","ola":"刚需不择时投资等信号，没人能精确抄底","cp":["政策供需资金三维度判断","短期精准判断几乎不可能","刚需不择时投资等信号","库存去化周期看供需"],"detail":"房价走势判断看三个维度：①政策面（限购放松/利率下调=托市信号、收紧=压市信号）；②供需面（库存去化周期<12月偏卖方市场、>18月偏买方市场）；③资金面（M2增速/房贷利率走势）。但短期精准判断几乎不可能，刚需自住不必择时（居住需求不等人），投资需谨慎择时。口诀：刚需不择时、改善可观望、投资等信号。","legalRef":"行业通行做法","consumerBenefit":"时机判断不纠结","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["房价还会跌吗","现在是不是底部","什么时候买房最划算"]},{"id":"PRE-PRICE-053","name":"怎么砍价能砍多少","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"买房能砍多少钱下来？","ola":"新房3-8%二手5-15%，拿着成交数据谈","cp":["手握成交数据才有底气","找房源硬伤当砍价点","分步砍先大后小","新房3-8%二手5-15%"],"detail":"砍价核心策略：①知己知彼（查真实成交价+同小区竞品挂牌价，手握数据才有底气）；②找硬伤（临街/楼层差/户型硬伤/装修老旧都是砍价点）；③表诚意（让卖家感受到你真想买不是随便看看）；④分步砍（先砍5-8%试探→再砍2-3%逼近底线→最后一次性砍到心理价）。新房砍价空间3-8%、二手房5-15%，急售房可砍15-20%。","legalRef":"行业通行做法","consumerBenefit":"砍价有方法不买贵","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["能砍几个点","砍价怎么开口","谈判怎么谈"]},{"id":"PRE-PRICE-060","name":"新房和二手房哪个更划算","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"新房和二手房哪个更划算？","ola":"别比单价比总成本，含税费中介费装修","cp":["新房砍价空间小二手大","二手税费更复杂可能更贵","综合算总成本不比单价","次新房总成本可能低10-20%"],"detail":"新房vs二手房成本对比不能只看单价：新房标价通常不可大砍（3-8%空间）、二手房可砍5-15%但税费更复杂；新房契税低、二手房可能加增值税+个税（不满二/非满五唯一）；新房无中介费、二手房加2-3%中介费。综合算总成本（房价+税费+中介费+装修），同地段次新房总成本可能比新房低10%-20%。","legalRef":"行业通行做法","consumerBenefit":"总成本算清不买贵","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["新房二手价格对比","新房便宜还是二手便宜","同区域新房二手怎么选"]},{"id":"PRE-PRICE-069","name":"同一套房不同中介报价不一样","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"不同中介报价差很多以哪个为准？","ola":"多方对比+直接面谈业主最准","cp":["低报引流是常见套路","独家房源可能加价","多家中介分别谈看最低价","直接和业主面谈最准"],"detail":"不同中介报价差异原因：①低报引流（报低价吸引你联系再说不卖了推荐其他）；②信息滞后（未及时更新业主调价）；③独家房源加价（独家委托中介报价可能更高）；④业主真实底价不确定（不同中介谈判深度不同）。确认底价方法：让多家中介分别去谈看最低价到多少、查同小区成交价判断合理区间、直接和业主面对面谈。","legalRef":"行业通行做法","consumerBenefit":"真实底价不踩报价坑","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["不同中介价格不同怎么办","报价差异原因","哪个价格是真的"]},{"id":"PRE-PRICE-073","name":"新房折扣怎么算真实优惠","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"新房打85折是真优惠吗？","ola":"看最终价对比周边成交，别被折扣数字忽悠","cp":["先涨价再打折是常见套路","特价房通常有硬伤","最终价对比周边成交看真优惠","低于周边5%才是真优惠"],"detail":"新房折扣常见套路：①先涨价再打折（对比前期成交价而非标价）；②折扣叠加看似多实际只省2-3%；③特价房有硬伤（低楼层/临街/户型差）；④限时优惠制造紧迫感（通常可延续）；⑤'最后X套'催促（可能还有房源）。真实优惠判断：拿最终折后价对比同板块其他楼盘成交价，低于周边5%才是真优惠，否则只是营销包装。","legalRef":"行业通行做法","consumerBenefit":"折扣算清不买贵","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["特价房真便宜吗","折扣怎么算实际价格","新房优惠水分有多少"]},{"id":"PRE-PRICE-079","name":"物业费多少算合理","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"物业费2.5元/㎡贵吗？","ola":"看同档次小区水平和服务匹配度","cp":["普通1-2元中档2-3高端3-5元","对比同档次小区看是否偏高","费用公示看钱花在哪","物业费过低服务缩水更危险"],"detail":"物业费参考标准：老旧小区0.5-1元/㎡·月、普通商品房1-2元、中档小区2-3元、高端小区3-5元、豪宅5-10元。判断是否合理：①对比同档次同地段小区物业费水平；②看物业服务内容是否匹配收费（安保频次/保洁标准/绿化维护/维修响应）；③查看物业费收支公示（费用去向是否透明）。物业费过低反而危险——服务缩水小区贬值。","legalRef":"《物业管理条例》第35条物业服务标准及收费公示","consumerBenefit":"物业费合理服务匹配","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["物业费标准是多少","物业费太贵怎么办","物业费和品质挂钩吗"]},{"id":"PRE-PRICE-080","name":"装修预算怎么定","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"装修大概要花多少钱？","ola":"中档1500-2500元/㎡，预留20%弹性","cp":["简装800-1200元/㎡","中档1500-2500元/㎡","硬装60%软装25%家电15%","超预算TOP3水电升级漏项"],"detail":"装修预算参考（按㎡算）：简装800-1200元/㎡、中档1500-2500元/㎡、高档3000-5000元/㎡、豪华5000+元/㎡。预算分配：硬装60%（水电30%+泥木20%+油漆10%）、软装25%、家电15%。超预算原因TOP3：水电改造超预期、临时升级材料、漏项（踢脚线/门槛石/窗帘盒等小项）。建议：预算预留15-20%弹性空间。","legalRef":"行业通行做法","consumerBenefit":"装修预算不超支","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["装修要花多少钱","装修预算怎么规划","毛坯装修多少钱一平"]},{"id":"PRE-PRICE-082","name":"同地段新房和次新房怎么选","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"同地段新房和5年内的二手房怎么选？","ola":"次新房便宜5-15%且配套成熟性价比高","cp":["次新房通常比新房低5-15%","次新房所见即所得配套成熟","新房有交付风险但有全新体验","配套成熟次新房性价比高"],"detail":"同地段新房vs次新房（5年内二手房）：新房优势全新+首付比例低、劣势期房交付风险+可能偏远；次新房优势所见即所得+配套成熟+可砍价、劣势税费可能更高+有折旧。价格上次新房通常比新房低5-15%（急售更低）。性价比综合看：配套成熟的次新房往往比偏远新房更实用，但如新房在核心地段则新房更优。","legalRef":"行业通行做法","consumerBenefit":"新房次新房取舍有据","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["新房和次新房价格差多少","同地段新房贵还是二手贵","次新房性价比高吗"]},{"id":"PRE-PRICE-086","name":"房子涨了还是跌了怎么判断","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"怎么判断这个小区房价在涨还是跌？","ola":"看3个月成交价趋势，别看挂牌价","cp":["看成交价趋势非挂牌价","连续3月环比降=下行","挂牌量增成交缩=价格承压","去化<6月=价格坚挺"],"detail":"房价走势判断看成交价趋势而非挂牌价：连续3个月成交均价环比下降=下行、环比持平=盘整、环比上升=上行。其他信号：①挂牌量激增+成交萎缩=供大于求价格承压；②带看量增加+成交加快=需求回暖价格企稳；③政策放松（降利率/松限购）=托市信号短期稳；④库存去化<6月=偏卖方市场价格坚挺。","legalRef":"行业通行做法","consumerBenefit":"房价走势有判断","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["房价涨跌怎么看","怎么判断小区房价走势","房价走势判断方法"]},{"id":"PRE-PRICE-091","name":"砍价时怎么判断卖方心理","domain":"签约前","subScene":"价格评估","scene":"签约前·价格评估","cq":"怎么判断卖家愿不愿意降价？","ola":"看调价次数和挂牌时长，急售空间大","cp":["多次调价挂牌久=急售空间大","报价坚挺拒绝多=不急空间小","报低价看卖方反应判断底线","催你定=急不催=不急"],"detail":"判断卖方心态的信号：①急售信号——多次调价、挂牌超3个月、换房/离婚/急用钱原因、接受长账期；②不急信号——调价幅度小、拒绝看房时间多、报价坚挺不松口、原因含糊；③试探底线——报一个明显偏低的价格看卖方愤怒程度（暴怒=接近底线、平静=还有空间）；④谈判节奏——卖方催你快定=急、不催=不急。","legalRef":"行业通行做法","consumerBenefit":"卖方心理有判断砍价有底气","tags":{"clientType":["buyer","seller"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["怎么揣摩卖方心态","卖方急不急怎么看","卖方底线怎么试探"]},{"id":"PRE-QUAL-005","name":"公司名义买房有什么限制","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"以公司名义买房能避开限购吗？","ola":"不能避限购，税费更高还有限售，不适合个人投资","cp":["一线限购1套需注册满5年","契税3%无首套优惠","每年缴1.2%房产税","贷款成数低利率高","部分城市3-5年限售"],"detail":"公司名义购房限制：①限购——一线城市对企业购房限购1套住宅（深圳），北京企业需注册满5年且纳税满1年②税费——契税统一3%（无首套优惠）、需缴印花税0.05%、房产税按年1.2%或租金12%③贷款——企业购房贷款成数低（最高50%）、利率高于个人④限售——部分城市企业购房3-5年内不得转让。优势：不限个人购房套数、可抵扣企业所得税。适合自用办公，不适合个人投资避限购。","legalRef":"各城市企业购房限制政策；《中华人民共和国契税法》第3条；《房产税暂行条例》第3条","consumerBenefit":"了解企业购房限制，不走弯路不踩坑","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["企业购房条件","以公司名义买房限购吗","公司买房税费多少"]},{"id":"PRE-QUAL-016","name":"婚前买的房婚后算谁的","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我婚前买的房子，结婚后算谁的？","ola":"全款买属个人，贷款买婚后共同还贷部分需补偿对方","cp":["婚前全款属个人财产","婚前贷款婚后共还贷需补偿","婚前付首付婚后共还贷归登记方","婚前协议不公证也有效","加名后变为共同财产"],"detail":"婚前全款购买的房屋登记在一方名下，属于婚前个人财产，离婚时不参与分割。婚前贷款购买婚后共同还贷的，房屋归产权登记方，但共同还贷部分及对应增值需补偿另一方。婚前一方付首付登记在自己名下婚后共同还贷的，房屋归登记方但需补偿对方共同还贷及增值。婚前财产协议可明确约定房产归属，不公证也有效但公证后证明力更强。婚前买房婚后加名，该房产变为夫妻共同财产。","legalRef":"《中华人民共和国民法典》第1063条（个人财产）、第1062条（共同财产）；最高人民法院关于适用《中华人民共和国民法典》婚姻家庭编的解释（一）第29条、第78条","consumerBenefit":"搞清产权归属，婚前保护自己婚后不闹矛盾","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["婚前房产归属","婚前买房婚后加名","婚前财产婚后增值归谁"]},{"id":"PRE-QUAL-017","name":"父母出资买的房算谁的","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我父母出钱给我们买房子，这房子算谁的？","ola":"看登记谁名下和转账备注，只登记你名属你个人，双方名属共有","cp":["一方父母全款出只登记己方子女属个人","出首付共同还贷归登记方","双方出资登记双方按份共有","登记双方名下视为共同赠与","转账备注决定赠与还是借款"],"detail":"父母出资购房归属分四种情形：①一方父母全款出资登记在自己子女名下——属该子女个人财产②一方父母出首付登记在自己子女名下婚后共同还贷——房屋归登记方，父母出资视为对己方子女赠与③双方父母共同出资登记在双方名下——按出资比例按份共有④一方父母出资登记在双方名下——视为对双方赠与属共同财产。关键证据：转账记录备注「赠与」或「借款」决定性质，无备注的法院倾向于认定为赠与。","legalRef":"《中华人民共和国民法典》第1063条第3项（遗嘱或赠与合同中确定只归一方的财产）；婚姻家庭编解释（一）第29条","consumerBenefit":"明确出资性质和产权归属，家庭不因房产闹矛盾","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["父母出首付房子归谁","一方父母出资购房归属","双方父母出资房产分割"]},{"id":"PRE-QUAL-018","name":"假离婚买房有什么法律风险","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"听说离婚后能多买一套房，靠谱吗？","ola":"不靠谱，离婚1年内按原家庭算，假离婚可能变真离婚","cp":["离婚1年内按原家庭套数认定","假离婚可能变真离婚","银行审查发现异常会拒贷","虚构离婚骗资格涉嫌诈骗罪","法律上不存在假离婚"],"detail":"假离婚购房的风险：①离婚1年内购房按原家庭套数认定——多数城市已堵住这个漏洞②假离婚可能变真离婚——对方不同意复婚财产已分割无法追回③贷款审查——银行可能要求提供离婚证和财产分割协议，发现异常会拒贷④刑事风险——虚构离婚骗取购房资格可能构成诈骗罪。真实案例：某夫妻假离婚后男方不愿复婚，女方人财两空。法律上不存在「假离婚」，一旦办理离婚登记即产生法律效力。","legalRef":"《中华人民共和国民法典》第1076条（离婚登记效力）；《中华人民共和国刑法》第266条（诈骗罪）；各城市离婚购房限制政策","consumerBenefit":"不为多买一套房搭上婚姻和财产","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["离婚买房规避限购","假离婚买二套房后果","离婚后购房资格认定"]},{"id":"PRE-QUAL-029","name":"房产税试点会影响购房成本吗","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"房产税要来了，买房要多花多少钱？","ola":"试点细则未出，预期0.3%-1.2%年税率，首套可能免征","cp":["试点已授权细则未出","预期税率0.3%-1.2%","首套或一定面积可能免征","增加持有成本抑制投机","多套房持有可能税负压力大"],"detail":"房产税试点已于2021年获全国人大常委会授权国务院在部分地区开展，试点城市和细则尚未正式公布。预期征收方式：按房产评估价值的一定比例按年征收，税率预计0.3%-1.2%，首套或一定面积免征。对购房成本的影响：增加持有成本（每年额外支出=评估价×0.3%-1.2%），降低投资投机需求，可能对多套房业主产生较大影响。当前阶段建议：购房时将潜在房产税纳入持有成本测算，避免多套持有可能带来的税负压力。","legalRef":"《全国人民代表大会常务委员会关于授权国务院在部分地区开展房地产税改革试点工作的决定》（2021年10月23日）","consumerBenefit":"预判持有成本，不因房产税压力被迫甩卖","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["房产税什么时候出台","房产税对购房影响","房产税怎么征收"]},{"id":"PRE-QUAL-030","name":"限售期没到房子能卖吗","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我的房子还在限售期内，能先签合同等限售期满再过户吗？","ola":"合同有效但无法过户风险高，建议限售满后再交易","cp":["限售从取得产证日起算","新房限售2-3年热点5年","限售期合同有效但无法过户","私下交易风险极高","购房前必须确认限售限制"],"detail":"限售指购房后一定期限内禁止转让，限售期从取得不动产权证之日起计算。常见限售期限：新房2-3年、热点城市5年、法拍房不限售。限售期内签订的买卖合同有效但无法办理过户，需等限售期满后才能过户。限售期内私下交易的风险：无法过户导致合同无法履行、卖方一房多卖、买方资金安全无法保障。部分城市限售期未满可做预告登记锁定房源但不可过户。购房前必须确认是否存在限售限制。","legalRef":"各城市限售政策文件；《中华人民共和国民法典》第221条（预告登记）","consumerBenefit":"不在限售期冒险交易，等期满再卖最安全","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["限售几年才能卖","新房限售规则","取得产证后多久能卖"]},{"id":"PRE-QUAL-035","name":"公积金贷款额度上限怎么算","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我的公积金能贷多少？怎么算的？","ola":"余额10-20倍且不超当地最高限额，北京首套120万","cp":["贷款额度通常为余额10-20倍","月缴存额越高可贷越多","北京首套最高120万","贷款额度不超过总价70%-80%","不足部分由商业贷款补足"],"detail":"公积金贷款额度计算方式各地不同，主要受以下因素影响：一是公积金账户余额，通常贷款额度为余额的10-20倍；二是月缴存额，月缴存越高可贷额度越高；三是缴存年限，缴存时间越长额度越高；四是当地最高限额，北京首套最高120万，上海最高100万；五是房屋总价，贷款额度不超过总价的70%-80%。组合贷中公积金不足部分由商业贷款补足。","legalRef":"《住房公积金管理条例》第26条；各地住房公积金管理中心贷款办法","consumerBenefit":"提前算清公积金贷款额度，合理安排首付来源","tags":{"clientType":["buyer"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["公积金最高贷多少万","公积金贷款额度影响因素","公积金月缴和贷款额度"]},{"id":"PRE-QUAL-044","name":"集体户口买房和普通户口有什么不同","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我是集体户口，买房和普通户口有什么不一样吗？","ola":"购房资格一样，但学区认定可能受限，买房后可迁个人户","cp":["集体户口与普通户口购房资格相同","学校集体户口通常无购房资格","买房后可将集体户口迁入个人户口","需提供集体户口首页复印件+本人页","部分城市集体户口不认定学区"],"detail":"集体户口与普通户口在购房资格上一般没有区别，均属于当地户籍。但需注意：一是集体户口需提供集体户口首页复印件加盖单位公章+本人页；二是学校集体户口（学生）通常不具有购房资格，需毕业后转为单位集体户口或个人户口方可购房；三是买房后可凭房产证将集体户口迁入个人户口（立户）；四是部分城市集体户口不能作为学区认定依据，需迁入个人户口后才可按房产地址认定学区。","legalRef":"《中华人民共和国户口登记条例》第10条","consumerBenefit":"了解集体户口购房和学区差异，不因户口类型吃亏","tags":{"clientType":["buyer"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["集体户口能买房吗","集体户口和居民户口购房区别","单位集体户口算本地户籍吗"]},{"id":"PRE-QUAL-055","name":"商业贷款利率现在是多少","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"现在房贷利率是多少？","ola":"首套约3.25-3.45%，不同银行有差异","cp":["房贷利率=LPR±BP","首套约3.25-3.45%","利率下行选LPR浮动","不同银行BP不同可比较"],"detail":"当前房贷利率基于LPR定价：5年以上LPR由央行每月公布，各银行在此基础上加减BP点数形成实际利率。首套通常LPR-20BP至LPR+0BP（即3.25%-3.45%左右），二套LPR+60BP起。选择LPR浮动利率还是固定利率：预计利率下行周期选LPR浮动更划算、上行周期选固定更稳。不同银行BP点数不同可货比三家。","legalRef":"中国人民银行LPR公告及各商业银行住房贷款利率定价","consumerBenefit":"选对利率方案省利息","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["房贷利率多少","商贷利率最新","房贷利率还会降吗"]},{"id":"PRE-QUAL-061","name":"名下有房再买算几套","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我之前有套房卖了再买算首套吗？","ola":"看当地政策，认房不认贷就能算首套","cp":["认定标准各地不同变动频繁","认房又认贷最严","认房不认贷已卖可算首套","务必查当地最新政策"],"detail":"二套认定标准各地不同分为三种：认房又认贷（最严，名下有房或有贷记录均算二套）、认房不认贷（名下无房即可算首套，贷款记录不影响）、认贷不认房（仅有贷款记录算二套）。2023年起多地放松为认房不认贷，房贷结清且卖掉现有住房可按首套执行。务必查当地最新认定标准，政策变动频繁。","legalRef":"各城市差别化住房信贷政策最新认定标准","consumerBenefit":"争取首套优惠省几十万","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["已有房再买怎么认定","认房又认贷什么意思","认房不认贷城市有哪些"]},{"id":"PRE-QUAL-068","name":"共有产权房能买吗","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"共有产权房是什么能买吗？","ola":"便宜但只持部分产权，5年内不能卖","cp":["个人持50-80%份额","价格约为同地段50-70%","5年内禁售5年后可转商品房","适合预算有限刚需"],"detail":"共有产权房是政府与购房人按份共有的保障性住房，个人持有份额50%-80%（各地不同），价格约为同地段商品房的50%-70%。优势：总价低、有产权保障；限制：5年内禁售、5年后可增购政府份额转商品房、出售需政府优先回购。申请条件：本地户籍+无房+收入不超过上限。适合预算有限的刚需家庭。","legalRef":"《共有产权住房管理办法》各地实施细则","consumerBenefit":"低门槛上车有保障","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["共有产权房是什么","共有产权房资格条件","共有产权房便宜多少"]},{"id":"PRE-QUAL-072","name":"买房能不能用父母公积金","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我买房能用爸妈的公积金吗？","ola":"部分城市可以，查当地公积金政策","cp":["部分城市允许代际提取","各地政策差异大","通常要求同城市首购房","还贷阶段可能允许冲还"],"detail":"部分城市允许子女购房提取父母公积金（称公积金代际提取），但各地政策差异大。允许的城市通常要求：父母和子女在同一城市缴存、子女为首次购房、提取额度有限制。不允许的城市则只能提取本人及配偶公积金。还贷阶段部分城市允许父母公积金冲还子女贷款。务必查询当地公积金管理中心最新政策。","legalRef":"各地住房公积金提取管理办法代际提取条款","consumerBenefit":"用足家庭公积金资源","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["父母公积金我能用吗","子女买房父母公积金","公积金可以代际使用吗"]},{"id":"PRE-QUAL-073","name":"首付不够有什么办法","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"首付差几万怎么办？","ola":"自有资金或父母给，别用消费贷银行会查","cp":["首付必须自有资金","消费贷经营贷凑首付会被拒贷","银行查首付来源流水","差一点就降总价或等一等"],"detail":"首付来源必须合规：自有存款、父母赠与、公积金提取（部分城市允许）为合法来源。严禁使用消费贷、经营贷、信用贷等借贷资金凑首付——银行会查首付来源流水，发现借贷资金直接拒贷。首付差一点的解决方案：①降低购房总价；②增加共同还款人分担；③等待攒够不要硬上；④选低首付比例的公积金贷款。","legalRef":"《关于防止经营用途贷款违规流入房地产领域的通知》","consumerBenefit":"首付合规贷款不拒","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["首付差一点怎么办","首付能借吗","首付来源银行查吗"]},{"id":"PRE-QUAL-081","name":"共同还款人有什么要求","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"我妈能做我共同还款人吗？","ola":"有收入征信好就行，但可能影响她以后买房","cp":["需稳定收入征信良好","收入可叠加满足月供要求","影响共同还款人自身购房资格","配偶默认共同还款"],"detail":"共同还款人需满足：有稳定收入、征信良好、年龄+贷年限≤65-70年。常见共同还款人：配偶（默认共同还款）、父母、成年子女。共同还款人的收入可叠加计算满足月供2倍要求。风险：共同还款人名下有房贷记录可能影响其自身购房资格认定。配偶贷款已婚默认共债，未婚可自主选择共同还款人。","legalRef":"各商业银行共同还款人认定及要求","consumerBenefit":"贷款额度够月供无压力","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["加共同还款人条件","父母做共同还款人行吗","共同还款人风险"]},{"id":"PRE-QUAL-084","name":"购房合同备案要多久","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"合同备案要多久？","ola":"5到30个工作日，签约后记得确认","cp":["备案即网签5-30工作日","新房开发商办二手房自己办","未备案合同无官方效力","签约后务必确认备案完成"],"detail":"购房合同备案=网签备案，是同一事项的两种说法。流程：签约后5-30个工作日内完成（各地不同，新房由开发商办理、二手房由中介或自行办理）。备案后可在当地住建局官网用合同号查询备案状态。未备案风险：合同无官方效力、一房二卖无保障、银行可能不放款。签约后务必跟进确认备案完成。","legalRef":"《城市商品房预售管理办法》第10条合同登记备案","consumerBenefit":"备案及时交易有保障","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["合同备案流程","备案要多少天","备案和网签是一回事吗"]},{"id":"PRE-QUAL-085","name":"不动产权证什么时候能拿到","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"买完房多久能拿到房产证？","ola":"期房交房后90天起，二手房过户后几天","cp":["期房交房后90天到2年办证","二手房过户后3-5天拿证","无证不能售抵落入学","合同约定办证时限和违约金"],"detail":"不动产权证获取时间：新房期房通常交房后90天-2年内办理（合同约定时限）；二手房过户后当场或3-5个工作日领证。产证是房屋产权的法律凭证，没有产证无法出售、抵押、落户、入学。开发商逾期不办证可追究违约责任（合同通常约定日万分之1-3违约金）。购房合同务必约定办证时限和违约责任。","legalRef":"《商品房销售管理办法》第34条产权登记；《不动产登记暂行条例》","consumerBenefit":"产证按时拿权益有保障","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["产证多久能办","房产证和不动产权证区别","期房什么时候拿证"]},{"id":"PRE-QUAL-088","name":"银行拒贷了能换银行吗","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"这家银行拒了我能换一家吗？","ola":"能换但别短时间频繁申请，先改善问题","cp":["不同银行审批尺度不同","小银行通常比大行宽松","多次查询影响征信评分","先改问题再申请新银行"],"detail":"一家银行拒贷可以换银行再申请，不同银行对征信瑕疵、收入标准、房龄限制的容忍度不同。小银行/地方银行审批通常比大行宽松但利率可能略高。注意事项：每次申请都会查征信留记录，短期内多次查询会影响征信评分（3个月内超6次查询视为风险信号）。建议先了解拒贷原因针对性改善后再申请新银行。","legalRef":"行业通行做法","consumerBenefit":"拒贷不绝望换行有希望","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["贷款被拒换一家行吗","不同银行审批标准一样吗","这家拒了那家会批吗"]},{"id":"PRE-QUAL-092","name":"买房需要查土地性质吗","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"土地性质对买房有影响吗？","ola":"划拨地要多交钱，小产权别碰","cp":["出让地交易无障碍","划拨地交易要补土地出让金","住宅70年到期自动续期","小产权不受法律保护"],"detail":"土地性质直接影响产权和交易成本：出让地（商品房常见）产权清晰交易无障碍；划拨地（经济适用房/房改房）交易需补缴土地出让金。商业用地40年/住宅用地70年，到期后住宅自动续期（目前免补缴）、商业需申请续期并补缴。小产权房建在集体土地上无法办产证不受法律保护。查土地性质看不动产权证用途栏。","legalRef":"《城镇国有土地使用权出让转让暂行条例》第12条；《中华人民共和国民法典》第359条住宅续期","consumerBenefit":"土地性质不踩交易坑","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["土地性质影响产权吗","出让地和划拨地区别","土地年限到期怎么办"]},{"id":"PRE-QUAL-098","name":"买房资金监管是什么","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"资金监管是什么不走过户有风险吗？","ola":"钱放第三方过户才放，不走钱可能打水漂","cp":["过户后才释放资金给卖方","防止收钱不过户一房二卖","二手房必须走监管","新房防烂尾监管预售款"],"detail":"资金监管是买方将购房款存入第三方监管账户，过户完成后资金才释放给卖方，防止卖方收钱不过户或一房二卖。二手房交易务必走资金监管，不走的风险：卖方携款跑路、房屋被查封无法过户、一房二卖。新房的监管指预售资金监管账户，防止开发商挪用导致烂尾。监管费用通常由政府承担或极低。","legalRef":"《房地产交易资金监管办法》各地实施细则","consumerBenefit":"资金安全过户有保障","tags":{"clientType":["buyer"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["资金监管有必要吗","监管账户安全吗","不走监管有风险吗"]},{"id":"PRE-QUAL-CASE-002","name":"亓冠磊每日播报'只从你买'","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"经纪人会长期坚持跟进吗？/ 该不该选一个坚持跟进的经纪人？","ola":"日拱一卒的经纪人值得托付","cp":["每日播报从不中断","没新房源也发我继续盯","日拱一卒是最笨最有效","客户说只从你手里买"],"detail":"兴商地产北京经纪人亓冠磊服务客户陈先生，对方说1至3年后才换房。亓冠磊每日播报从未中断——有新房源第一时间筛选发送，没有也发'今天没有新增我继续盯着'。持续播报建立的不是信息优势而是存在感与可靠感。客户最终承诺'只从你手里买'，五一跨城签约视频通话半天搞定。7年从零做到百万经纪人，日拱一卒是最笨也最有效的信任建立法。","legalRef":"网易新闻2026","consumerBenefit":"有人持续帮你盯着，不用自己操心","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"器","meetingPhase":["见前","见后"]},"alias":["每日播报只从你买","亓冠磊日拱一卒","长期播报建信任"]},{"id":"PRE-QUAL-CASE-003","name":"雷隆稳劝别买赶不上入学的项目","domain":"签约前","subScene":"资格审查","scene":"签约前·资格审查","cq":"经纪人会劝我不买吗？/ 该不该相信劝我不买的经纪人？","ola":"劝你不买的经纪人更值得信任","cp":["劝退比成交更需勇气","发现交付赶不上入学坦诚说","劝退换来30%老带新","主动讲不利面筛选客户"],"detail":"华夏百纳行郴州经纪人雷隆稳遇到客户看中项目价格户型都满意，但他发现交付时间赶不上孩子入学，坦诚说明并推荐交付更早的另一项目。客户感叹'你是第一个劝我不着急买的销售'。劝退比成交更难，但一次劝退换来三位朋友转介绍，老带新占比达30%。主动讲不利面不是丢客户，是筛选真正匹配的客户建立长期信任。","legalRef":"郴州楼盘网2026","consumerBenefit":"不被误导做错误决策，有人替你把关","tags":{"clientType":["buyer","agent"],"stage":"pre","layer":"器","meetingPhase":["见前","见后"]},"alias":["劝别买赶不上入学","雷隆稳劝不买","第一个劝我不买的销售"]},{"id":"PRE-RISK-018","name":"资金监管有必要吗","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"我买二手房有必要做资金监管吗？","ola":"非常有必要，能防止钱房两空。","cp":["防止钱房两空","过户后划转资金","银行或官方机构托管","保障买卖双方权益"],"detail":"资金监管是指买卖双方在交易过程中，将购房款交由第三方（如银行或房管局指定机构）进行托管，待过户完成后才划转给卖方的制度。这能有效避免卖方拿钱不配合过户或房屋被查封导致钱房两空的风险，是二手房交易中最核心的资金安全保障机制。","legalRef":"《中华人民共和国民法典》第215条及各地二手房交易资金监管管理办法","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["买房资金监管","二手房资金托管","房款监管安全吗"]},{"id":"PRE-RISK-038","name":"房子有裂缝正常吗","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"我去看房发现墙上有几道裂缝，这正常吗？会不会有安全隐患？","ola":"细小温度裂缝属正常，结构性裂缝属严重质量问题。","cp":["表面龟裂属正常现象","承重墙裂缝属质量问题","需辨别裂缝成因","结构裂缝需安全鉴定"],"detail":"房屋裂缝是否正常取决于裂缝的成因和位置。如果是由于温度变化、材料收缩引起的表面抹灰层细小龟裂，属于正常物理现象，不影响结构安全，修补即可。但如果是承重墙、梁柱节点处出现的贯穿性裂缝、斜向裂缝或宽度较大的裂缝，则可能是地基沉降或结构受力异常导致的结构性裂缝，属于严重的房屋质量问题。遇到后者必须要求卖方提供房屋安全鉴定报告，必要时可拒绝交易或要求大幅降价。","legalRef":"《最高人民法院关于审理商品房买卖合同纠纷案件适用法律若干问题的解释》第9条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["墙面有裂缝正常吗","房子裂缝算质量问题吗","新房有裂缝怎么办"]},{"id":"PRE-RISK-043","name":"卖方配偶不同意能卖吗","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"卖房的房东说配偶不同意卖，但他自己一个人能签合同吗？","ola":"未经配偶同意擅自出售共有房屋，合同可能无效。","cp":["共有财产需双方同意","单方出售属无权处分","买方难主张善意取得","必须要求配偶面签"],"detail":"若房屋属于夫妻共同财产，即使房产证上只有一方的名字，出售时也必须取得配偶的同意。如果卖方隐瞒已婚事实或配偶明确反对，单方面签订房屋买卖合同，属于无权处分。虽然根据民法典买卖合同本身可能有效，但买方无法要求强制过户。除非买方能证明自己构成善意取得，否则配偶有权追回房屋。因此，交易时必须要求卖方配偶出具书面同意书或面签。","legalRef":"《中华人民共和国民法典》第301条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["配偶不同意房子能卖吗","夫妻共同房产一方能卖吗","瞒着配偶卖房有效吗"]},{"id":"PRE-RISK-044","name":"限售期内房子能卖吗","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"我看中一套房子，但房东说还在限售期内，这房子能买吗？","ola":"限售期内无法过户，私下交易存在极大违约风险。","cp":["限售期内无法过户","私下交易违约风险高","防范卖方债务查封","合同效力存在瑕疵"],"detail":"限售政策是指新购住房在取得不动产权证后的一定年限内不得上市交易。在限售期内，房管局系统会锁定该房屋，无法办理网签和过户手续。如果买卖双方私下签订协议并支付全款，由于无法及时过户，期间若遇房价大涨卖方极易违约反悔，或卖方因债务问题导致房屋被查封，买方将面临钱房两空的巨大风险。此外，此类私下交易合同在司法实践中可能被认定为规避政策而存在效力瑕疵。","legalRef":"《中华人民共和国民法典》第153条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["限售期内的房子能卖吗","房子被限售了怎么交易","限售期内可以过户吗"]},{"id":"PRE-RISK-048","name":"没有购房资格签合同有效吗","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"我其实没有当地的购房资格，如果我和房东签了合同，这合同有效吗？","ola":"合同通常有效，但因无法过户会导致合同目的落空。","cp":["合同本身通常有效","无法过户导致合同解除","隐瞒资格需担违约责任","可退定金但无法强求过户"],"detail":"根据司法实践，限购政策属于地方性调控措施，不具备法律、行政法规的效力层级。因此，无购房资格签订的房屋买卖合同本身通常是有效的。但是，由于买方不具备资格，房管局将拒绝办理网签和过户手续，导致合同无法继续履行。此时，买方可以不可归责于双方当事人的事由为由请求解除合同并退还定金及房款；但如果买方明知自己无资格仍隐瞒事实，卖方有权要求买方承担违约责任。","legalRef":"《中华人民共和国民法典》第580条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["没购房资格签合同有效吗","无购房资格买房合同算数吗","没有购房资格能签购房合同吗"]},{"id":"PRE-RISK-061","name":"卖家联系不上了怎么办","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"交了定金后卖家突然联系不上了，我该怎么办？","ola":"发送催告函，逾期可依法解除合同并追究违约责任。","cp":["发催告函保留证据","逾期可起诉解除合同","要求退款及违约金","法院可公告缺席判决"],"detail":"签约后卖家失联导致无法办理过户或交房，属于卖方根本违约。买方应首先通过EMS等可留痕方式向卖家合同预留地址发送《催告履行通知书》，给予合理宽限期。若宽限期届满卖家仍未出现，买方可向法院起诉解除合同，要求退还已付款项并支付违约金或双倍返还定金。若卖家下落不明，法院可公告送达并缺席判决，后续可申请强制执行其名下财产。","legalRef":"《中华人民共和国民法典》第五百六十三条、第五百七十七条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["卖家失联怎么办","房东联系不上怎么办","卖家失踪怎么过户"]},{"id":"PRE-RISK-063","name":"卖家欠债房子会被查封吗","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"听说卖家在外面有欠债，我买的房子会不会被法院查封？","ola":"未过户前存在查封风险，需做产调并资金监管。","cp":["未过户前存在查封风险","签约前必查最新产调","务必使用资金监管","发现查封应立即中止交易"],"detail":"若卖家存在未清偿债务且被债权人起诉，法院有权查封其名下房产。在未完成不动产过户登记前，房屋产权仍属卖家，存在被司法查封导致无法过户的重大风险。为防范此风险，买方签约前必须拉取最新《不动产登记簿查询证明》（产调），确认无查封、抵押等限制。交易过程中务必使用银行资金监管，避免首付款被卖家挪用或被法院直接划扣。","legalRef":"《中华人民共和国民法典》第二百零九条、《最高人民法院关于人民法院民事执行中查封、扣押、冻结财产的规定》","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["卖家有债务房子会被查封吗","房东欠债房子能买吗","卖家债务风险"]},{"id":"PRE-RISK-066","name":"卖家在国外怎么签合同","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"卖家人在国外回不来，这合同和过户怎么弄？","ola":"需办理使领馆认证或国内公证的委托公证手续。","cp":["需办理使领馆认证或公证","明确具体委托事项及权限","核实委托书真实性","防范无权代理风险"],"detail":"卖方若在国外无法亲自回国签约及办理过户，必须委托国内代理人代办。委托书需经中国驻该国使领馆认证，或通过国内公证处办理公证（部分城市支持远程视频公证）。委托书内容需明确具体的委托事项、权限及期限（如代为签约、代收房款、代办过户等）。买方需仔细核对委托书原件及认证/公证文件的真实性，确保代理人具备合法授权，防范无权代理风险。","legalRef":"《中华人民共和国民法典》第一百六十一条、第一百六十五条，《中华人民共和国民事诉讼法》第二百七十一条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["卖方在国外怎么签合同","房东在国外怎么过户","跨国卖房怎么签字"]},{"id":"PRE-RISK-068","name":"离婚期间房子能买卖吗","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"卖家正在办离婚，这房子产权不清楚，我能买吗？","ola":"需明确产权归属，凭离婚协议或法院判决办理交易。","cp":["未分割前不得擅自处分","需先办理析产过户","或凭生效法律文书交易","严格审查离婚及财产文件"],"detail":"离婚期间房产交易存在产权争议风险。若房产为夫妻共同财产，在未完成离婚财产分割前，任何一方不得擅自处分。若已达成离婚协议或法院判决，需先办理析产过户，将房产登记至一方名下后再进行交易；或凭生效的离婚协议/法院判决书，由获得产权的一方配合办理交易。买方需严格审查离婚证、离婚协议（需民政局盖章）或法院判决书，确保产权清晰无纠纷。","legalRef":"《中华人民共和国民法典》第一千零六十二条、第一千零八十七条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["离婚期间房产怎么处理","离婚时房子能卖吗","离婚房产分割交易"]},{"id":"PRE-RISK-084","name":"隐瞒房龄算欺诈吗","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"买完房才发现房龄比中介说的老了10年，这算欺诈吗？能退房吗？","ola":"故意隐瞒影响决策可认定为欺诈。","cp":["故意隐瞒影响决策算欺诈","可依法请求撤销合同退房","轻微误差主张违约赔偿"],"detail":"房龄直接影响房屋贷款年限、房屋价值及居住体验。若卖方或中介故意将老房龄伪造成新房龄，且该虚假信息足以影响买方作出购买决策（如导致贷款年限缩短、首付增加），则构成民事欺诈。买方可依据《民法典》请求法院或仲裁机构撤销合同，要求退房并赔偿损失。若仅是轻微误差或未对买方决策产生重大影响，则可能仅承担违约赔偿责任，较难直接退房。","legalRef":"《中华人民共和国民法典》第一百四十八条、《中华人民共和国消费者权益保护法》第五十五条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","landlord"],"stage":"pre","layer":"道","meetingPhase":["见前","见中"]},"alias":["中介隐瞒真实房龄算欺诈吗","老房子当新房子卖算欺诈吗","隐瞒房龄能退房吗"]},{"id":"PRE-SCH-008","name":"学区房溢价这么高以后还能卖掉吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"学区房比周边贵那么多，以后还卖得掉吗？","ola":"核心学区流通性仍好但溢价收窄，投资需谨慎自用为主","cp":["溢价20%-40%支撑力在减弱","多校划片+教育均衡+出生率下降","核心学区流通性仍好但溢价收窄","溢价超40%风险最大","以自用为主投资需谨慎"],"detail":"学区房溢价（核心学区比周边非学区贵20%-40%）的支撑力正在减弱：多校划片降低确定性、教育资源均衡化推进、出生率下降导致入学需求减少。流通性判断：核心学区房流通性仍好（每年有新的入学需求），但溢价收窄是趋势。风险最大的是溢价超过40%且对口学校仅靠单校划片支撑的房源，一旦划片调整跌幅最大。建议：学区房以自用入学为主，投资需谨慎，溢价超过30%的学区房投资风险已高于回报预期。","legalRef":"待补充法源","consumerBenefit":"不盲目追高学区溢价，理性判断未来流通性","tags":{"clientType":["buyer"],"stage":"pre","layer":["术"],"meetingPhase":["见前"]},"alias":["学区房泡沫风险","学区房流通性","学区房价格走势"]},{"id":"PRE-SCH-012","name":"中介承诺学区有法律效力吗","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"中介说这房子对口名校，但我怕到时候变卦，怎么办？","ola":"口头不算数，必须写入合同补充条款，不写不签","cp":["口头承诺学区无法律效力","必须写入合同才有效","宣传材料可能视为要约但举证难","要求写入补充条款不写不签","广告承诺不等于合同承诺"],"detail":"中介口头承诺学区对口关系无法律效力，只有写入购房合同才有效。中介/开发商的学区宣传材料（广告/沙盘/宣传页）根据《最高人民法院关于审理商品房买卖合同纠纷案件适用法律若干问题的解释》第3条，若宣传内容具体确定且对合同订立和房价有重大影响，应视为要约（合同内容）。但实践中证明「重大影响」较困难。建议：要求中介/卖方将学区承诺写入合同补充条款，否则视为无承诺，不签不买。","legalRef":"最高人民法院《最高人民法院关于审理商品房买卖合同纠纷案件适用法律若干问题的解释》第3条；《中华人民共和国民法典》第473条（要约邀请）","consumerBenefit":"只信合同不信口头，学区承诺不落地不签字","tags":{"clientType":["buyer"],"stage":"pre","layer":["道"],"meetingPhase":["见前"]},"alias":["中介学区承诺算数吗","口头承诺学区靠谱吗","学区宣传和实际不符"]},{"id":"PRE-SCH-017","name":"学区虚假宣传怎么维权","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"开发商宣传说有名校学区，交房发现不是，能维权吗？","ola":"能，保留宣传材料证据，投诉+起诉可获赔偿","cp":["向市场监管局投诉违反广告法","向住建局投诉违反经纪管理办法","民事诉讼主张欺诈撤销合同","集体维权效率更高","保存宣传册沙盘聊天记录作证据"],"detail":"学区虚假宣传的维权路径：①向市场监管局投诉——违反《广告法》第26条，可处广告费1-5倍罚款②向住建局投诉——违反《房地产经纪管理办法》第22条，可处1-3万元罚款③民事诉讼——主张欺诈请求撤销合同并赔偿④集体维权——多位业主联合维权效率更高。关键证据：宣传册/沙盘/销售人员聊天记录。","legalRef":"《广告法》第26条；《房地产广告发布规定》第18条；《中华人民共和国消费者权益保护法》第55条（欺诈三倍赔偿）；《中华人民共和国民法典》第148条","consumerBenefit":"虚假宣传法律管，留好证据维权有底气","tags":{"clientType":["buyer"],"stage":"pre","layer":["器","道"],"meetingPhase":["见前"]},"alias":["学区广告与实际不符","虚假学区宣传赔偿","开发商学区承诺不兑现"]},{"id":"PRE-SCH-021","name":"学区房合同里怎么写条款才安全","domain":"签约前","subScene":"学区房","scene":"签约前·学区房","cq":"买学区房合同里要不要特别写学区条款？怎么写？","ola":"必须写补充协议：学校名称、变更处理、户口迁出时间","cp":["补充协议写明对应学校名称","约定学区变更的处理方式","约定户口迁出和名额释放时间","中介口头承诺无法律效力","未约定学区条款法院不支持解约"],"detail":"购买学区房时，在合同中明确约定学区相关条款是保障权益的关键。建议在补充协议中写明：所购房屋对应的学区学校名称；如因政策调整导致学区变更的处理方式（解约退款或降价补偿）；前业主户口迁出时间和学区名额释放时间；如学区名额被占用的违约责任。注意：中介口头承诺学区不具有法律效力，必须落实到书面合同中。未约定学区条款的，法院通常不支持仅因学区变更解约。","legalRef":"《中华人民共和国民法典》第490条（合同成立）；第577条（违约责任）","consumerBenefit":"学区变更有合同兜底，不因口头承诺吃哑巴亏","tags":{"clientType":["buyer"],"stage":"pre","layer":["道"],"meetingPhase":["见前"]},"alias":["买学区房合同注意什么","学区条款怎么约定","学区承诺写进合同有效吗"]},{"id":"PRE-SCH-033","name":"看房怎么安排时间最合理","domain":"签约前","subScene":"排期规划","scene":"签约前·排期规划","cq":"看房时间怎么安排最高效？","ola":"工作日新房周末二手，同区域集中看","cp":["工作日上午新房周末二手房","晚上看噪音雨天看渗漏","三轮看房分三阶段","同区域集中看减少跑路"],"detail":"看房时间安排原则：①工作日上午看新房售楼处（销售有时间详细讲解无排队）；②周末看二手房（业主方便开门）；③晚上7-8点复看噪音和亮灯率；④雨天复看渗漏排水。首轮广筛安排2-3天每天3-5套，二轮细看1天2-3套重点复看，三轮1天最终1-2套比价决策。每个区域集中半天看完减少跑路时间。","legalRef":"行业通行做法","consumerBenefit":"看房效率高不白跑","tags":{"clientType":["buyer"],"stage":"pre","layer":["术"],"meetingPhase":["见前"]},"alias":["看房时间怎么规划","什么时候看房最好","看房选工作日还是周末"]},{"id":"PRE-SCH-034","name":"从看房到签约大概要多久","domain":"签约前","subScene":"排期规划","scene":"签约前·排期规划","cq":"从开始看房到住进去要多久？","ola":"二手房2-4个月，新房1.5-3年","cp":["看房1-4周签约1-2周","贷款2-4周过户1-2周","二手签约到拿钥匙2-4月","提前贷款预审可加快"],"detail":"购房全流程时间线：①看房选房1-4周；②谈判签约1-2周；③贷款审批2-4周；④过户1-2周；⑤放款1-3个月（受银行额度影响）；⑥交房1-2周。二手房从签约到拿钥匙约2-4个月，新房从签约到交房18-36个月。加快方法：提前完成贷款预审、材料一次备齐不补件、选放款快的银行。急入住选二手房现房。","legalRef":"行业通行做法","consumerBenefit":"购房周期有预期","tags":{"clientType":["buyer"],"stage":"pre","layer":["术"],"meetingPhase":["见前"]},"alias":["买房周期多长","看房到拿钥匙多久","整个购房流程时间线"]},{"id":"PST-DEC-007","name":"装修公司跑路了能追回钱吗","domain":"签约后","subScene":"装修装饰","scene":"签约后·装修装饰","cq":"装修公司老板卷钱跑了，我之前交的定金和工程款还能要回来吗？","ola":"能追回。应立即报警或起诉，申请财产保全并强制执行公司资产。","cp":["收集合同及付款转账凭证","向法院起诉并申请财产保全","报案要求公安刑事立案侦查","申请强制执行查封公司资产"],"detail":"装修公司跑路属于严重违约行为。根据《民法典》第577条规定，当事人一方不履行合同义务，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。实操中，发现跑路应立即报警并起诉，同时申请财产保全冻结其账户。若涉嫌合同诈骗，可通过刑事追赃挽回损失；若仅为民事违约，需尽快通过法院强制执行其名下资产来追回预付款。","legalRef":"《中华人民共和国民法典》第577条","consumerBenefit":"装修不花冤枉钱，住得安心","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见前","见中"]},"alias":["装修老板跑路怎么退钱","装修公司倒闭钱能要回吗","家装公司卷款跑路怎么办"]},{"id":"PST-DEC-045","name":"装修完发现漏水谁负责","domain":"签约后","subScene":"装修装饰","scene":"签约后·装修装饰","cq":"刚装修完房子漏水把楼下淹了，这钱该我出还是装修公司出？","ola":"业主先担责赔偿，后凭漏水鉴定结果向装修公司或开发商追偿。","cp":["漏水致损业主先赔偿后追偿","申请专业鉴定明确漏水原因","施工质量问题由装修公司担责","房屋原防水缺陷由开发商维修"],"detail":"装修完发现漏水，若造成邻居损失，根据《民法典》第1253条，业主作为房屋所有人需先承担赔偿责任，赔偿后可向装修公司追偿。实操中，需先做漏水鉴定明确原因。若是装修施工质量问题，业主可依据合同要求装修公司免费维修并赔偿损失；若是房屋本身防水不合格且在保修期内，则由开发商负责。","legalRef":"《中华人民共和国民法典》第1253条","consumerBenefit":"装修不花冤枉钱，住得安心","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见前","见中"]},"alias":["装修后漏水责任怎么算","刚装完房子漏水找谁赔","新房装修漏水该谁掏钱"]},{"id":"PST-INSR-045","name":"房贷险怎么办理退保","domain":"签约后","subScene":"保险","scene":"签约后·保险","cq":"我提前把房贷还清了，之前交的房贷险能退吗？怎么退？","ola":"提前结清房贷或卖房可申请退保，退还扣除手续费后的未满期保费。","cp":["提前结清房贷可申请退保","扣除手续费后退未满期保费","需带保单及身份证明柜面办","出售房屋可协商变更或退保"],"detail":"指投保人在保险期满前向保险公司申请解除房贷险合同的行为。常见于提前结清房贷或房屋出售。根据《保险法》第54条，保险责任开始前退保需扣除手续费，保险责任开始后退还未满期净保费。实践要点：需携带身份证、保单正本、退保申请书及贷款结清证明到保险公司柜面办理。风险提示：提前退保可能会扣除一定比例的手续费，导致实际退回金额少于预期。","legalRef":"《中华人民共和国保险法》第54条","consumerBenefit":"及时办理退保，收回未到期保费，减少资金占用。","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["房贷险退保流程","提前还清房贷退保险","退保手续费"]},{"id":"PST-KEY-013","name":"新房交房要不要交维修基金","domain":"签约后","subScene":"交房验房","scene":"签约后·交房验房","cq":"开发商让先交维修基金才给钥匙，这钱必须交吗？交给谁？","ola":"必须交，应在办理入住前直接存入房管局指定专户。","cp":["办理入住前必须存入专户","资金直接交至房管局专户","严禁开发商私自代收代缴","专项用于共用部位设施维修"],"detail":"新房交房时必须交维修基金。根据《住宅专项维修资金管理办法》第7条，商品住宅业主应在办理房屋入住手续前，将首期维修资金存入专户。实操中，这是房屋的“养老金”，用于保修期满后共用部位维修。业主应直接交至房管局指定专户，切勿直接交给开发商，防资金被挪用。","legalRef":"《住宅专项维修资金管理办法》第7条","consumerBenefit":"验房不踩坑，收房不吃亏","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见前","见中"]},"alias":["收房时要不要交房屋养老金","拿钥匙前必须交维修基金吗","办房产证要交房屋维修基金吗"]},{"id":"PST-MNT-001","name":"房屋保修期内出问题开发商不修怎么办","domain":"签约后","subScene":"维修维护","scene":"签约后·维修维护","cq":"新房还在保修期就漏水了，找开发商他们一直拖着不修，我该怎么办？","ola":"催告无果可自行维修，费用由开发商承担，或向住建部门投诉。","cp":["发书面催告函并保留证据","业主代修费用由开发商承担","向当地住建部门投诉举报","依法向法院起诉强制维修"],"detail":"在房屋保修期内出现质量问题，开发商必须承担维修责任。根据《建设工程质量管理条例》第40条规定，屋面防水、有防水要求的卫生间和外墙防渗漏保修期为5年。若开发商拒绝或拖延维修，业主可发书面催告函保留证据；若仍不修，业主可自行维修，费用由开发商承担，也可向住建部门投诉或起诉。","legalRef":"《建设工程质量管理条例》第40条","consumerBenefit":"房屋问题及时修，居住更安心","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见前","见中"]},"alias":["新房漏水开发商不管咋办","质保期内房屋质量维权指南","保修期内墙体开裂开发商拒修"]},{"id":"PST-MNT-002","name":"公共区域维修谁出钱","domain":"签约后","subScene":"维修维护","scene":"签约后·维修维护","cq":"小区电梯坏了或者楼道墙皮脱落，这维修费到底该谁出啊？","ola":"由全体业主按面积分摊，小修用物业费，大中修用维修资金。","cp":["业主按面积比例分摊共有维修费","日常小修费用从物业费中支出","大中修及改造动用专项维修资金","业主不得以放弃权利拒交费用"],"detail":"根据《民法典》第273条规定，业主对共有部分享有权利并承担义务，不得以放弃权利为由不履行。因此，小区公共区域及共用设施设备的维修费用，由全体业主按专有部分面积比例共同分摊。实操中，日常小额维修从物业费支出，大中修及更新改造则需依法动用住宅专项维修资金。","legalRef":"《中华人民共和国民法典》第273条","consumerBenefit":"房屋问题及时修，居住更安心","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见前","见中"]},"alias":["小区公区坏了谁掏钱修","楼道电梯维修费用谁承担","公共设施设备维修谁买单"]},{"id":"PST-MNT-009","name":"维修基金使用需要业主投票吗","domain":"签约后","subScene":"维修维护","scene":"签约后·维修维护","cq":"小区电梯坏了要动用维修基金，必须得我们业主投票同意才行吗？","ola":"需要，常规使用需业主投票表决，紧急情况可走绿色通道免投票。","cp":["常规使用需业主投票表决","参与表决需达面积人数双三分之二","同意票需达参与表决双过半数","紧急情况可走绿色通道免投票"],"detail":"动用维修基金必须经过业主投票表决。根据《民法典》第278条及《住宅专项维修资金管理办法》第22条规定，使用维修资金需由专有部分面积占比三分之二以上的业主且人数占比三分之二以上的业主参与表决，并经参与表决双过半同意。实操中，遇到电梯故障等紧急情况可走绿色通道，无需投票直接申请划拨。","legalRef":"《住宅专项维修资金管理办法》第22条","consumerBenefit":"房屋问题及时修，居住更安心","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见前","见中"]},"alias":["小区大修基金使用需投票吗","维修资金表决需要多少人同意","动用公维金必须全体业主签字吗"]},{"id":"PST-MNT-013","name":"住宅专项维修资金管理办法是什么","domain":"签约后","subScene":"维修维护","scene":"签约后·维修维护","cq":"国家关于小区维修基金怎么交、怎么用的具体规定是啥？","ola":"规范房屋养老金交存、使用与管理的专项部门规章。","cp":["维修资金归全体业主所有","专用于共用部位设施维修","动用资金需业主表决同意","实行专户存储与专款专用"],"detail":"《住宅专项维修资金管理办法》是规范房屋“养老金”交存、使用和管理的部门规章。它明确维修资金归业主所有，专项用于共用部位和设施保修期满后的维修更新。实操中，资金使用需经法定比例业主表决，遵循专户存储、专款专用原则。","legalRef":"《住宅专项维修资金管理办法》","consumerBenefit":"房屋问题及时修，居住更安心","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见前","见中"]},"alias":["房屋养老金管理规定","小区维修资金怎么管","住宅维修基金使用办法"]},{"id":"PST-MNT-040","name":"维修基金被挪用怎么办","domain":"签约后","subScene":"维修维护","scene":"签约后·维修维护","cq":"物业偷偷把咱们小区的维修基金花了，我们业主该怎么要回来？","ola":"立即收集凭证，向住建部门举报并追究法律责任。","cp":["收集资金违规流向凭证","向住建局或房管局举报","追究挪用者行政刑事责任","联合业主大会提起民事诉讼"],"detail":"维修基金是房屋养老金，若被挪用，业主可向住建部门投诉。根据《住宅专项维修资金管理办法》第37条规定，挪用维修资金的，由主管部门追回资金，给予警告、没收违法所得，可处挪用金额2倍以下罚款；构成犯罪的追究刑事责任。实操中业主需收集资金流向凭证，向房管局举报或起诉。","legalRef":"《住宅专项维修资金管理办法》第37条","consumerBenefit":"房屋问题及时修，居住更安心","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见前","见中"]},"alias":["小区维修金被物业挪用咋办","业委会乱花大修基金怎么管","房屋养老金被违规使用了"]},{"id":"PST-MNT-048","name":"维修基金被挪用业主维权案例","domain":"签约后","subScene":"维修维护","scene":"签约后·维修维护","cq":"物业偷偷挪用小区维修基金，业主怎么维权把钱要回来？","ola":"业主可查账、向住建部门投诉或起诉，追回被挪用的维修资金。","cp":["调取维修资金收支账目明细","向住建部门投诉举报违规行为","联合业主大会提起民事诉讼","追究挪用者行政及刑事责任"],"detail":"维修基金被挪用是指物业或业委会未经业主大会法定程序，擅自将住宅专项维修资金用于非规定用途。根据《住宅专项维修资金管理办法》第三十七条规定，挪用维修资金的，由主管部门追回资金，给予警告、罚款。业主可通过查账、向住建局投诉或提起诉讼等方式维权，要求返还资金并赔偿损失。","legalRef":"《中华人民共和国民法典》第577条","consumerBenefit":"房屋问题及时修，居住更安心","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见前","见中"]},"alias":["维修资金被物业偷偷用掉","房子养老金被挪用怎么办","业委会私自动用维修基金"]},{"id":"PST-MNT-052","name":"公共维修资金申请难怎么破","domain":"签约后","subScene":"维修维护","scene":"签约后·维修维护","cq":"小区电梯坏了要动用维修基金，但凑不够签字人数怎么办？","ola":"需满足法定表决比例，可联合业委会或走紧急通道。","cp":["需满足法定业主表决比例","低入住率小区签字难度大","业委会或居委会可协助推进","紧急维修可走绿色通道"],"detail":"指业主在申请使用住宅专项维修资金时，因表决比例不达标、流程繁琐或物业不作为导致资金难以启用的风险。依据《民法典》第281条，使用维修资金需经参与表决专有部分面积及人数占比三分之二以上的业主参与，且过半数同意。实践中，低入住率或投资客多的小区常因签字人数不足而卡壳。风险提示：需提前摸清小区业主结构，必要时联合业委会或社区居委会介入协调。","legalRef":"《中华人民共和国民法典》第281条","consumerBenefit":"了解资金动用规则，推动公共设施及时修复。","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["维修基金申请不下来","动用维修资金条件","维修基金审批慢"]},{"id":"PST-TAX-053","name":"契税优惠资格认定有争议吗","domain":"签约后","subScene":"税费缴纳","scene":"签约后·税费缴纳","cq":"我在老家有套房，在本地买房算首套还是二套交契税？","ola":"契税优惠按家庭住房套数认定，隐瞒套数将面临补缴及滞纳金。","cp":["契税税率与家庭套数挂钩","首套二套享优惠税率","异地房产是否计入看当地","隐瞒套数将被追缴滞纳金","婚前房产影响婚后套数认定"],"detail":"契税优惠资格主要依据买方家庭名下住房套数认定，首套和二套住房适用优惠税率，三套及以上则适用法定税率。实践中，争议多见于婚前个人房产与婚后家庭房产的套数合并计算、异地房产是否计入本地套数，以及共有产权住房的认定。若买方隐瞒已有房产导致按低税率缴纳，税务稽查时将要求补缴差额并加收滞纳金，且无法享受退税。","legalRef":"《中华人民共和国契税法》第三条","consumerBenefit":"厘清家庭住房套数认定规则，确保合法享受契税优惠。","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["契税优惠资格争议","首套二套契税税率","契税减免资格认定"]},{"id":"PST-TAX-057","name":"契税法定税率和优惠怎么算","domain":"签约后","subScene":"税费缴纳","scene":"签约后·税费缴纳","cq":"国家规定的契税税率到底是多少？首套和二套有区别吗？","ola":"法定税率3%-5%","cp":["法定税率幅度为3%至5%","首套90平以下优惠税率1%","首套90平以上优惠税率1.5%","二套房享1%至2%优惠税率","具体税率由省级人大决定"],"detail":"根据《契税法》，契税法定税率为3%至5%。但现行优惠政策规定，对个人购买家庭唯一住房，面积90平及以下减按1%征收，90平以上减按1.5%；购买家庭第二套改善性住房，90平及以下减按1%，90平以上减按2%。具体适用税率及优惠幅度由省级政府在法定幅度内提出，报同级人大常委会决定。实践中，买方需结合当地具体执行标准计算应纳税额。","legalRef":"《中华人民共和国契税法》第三条","consumerBenefit":"明确契税法定与优惠税率，精准计算购房税费成本。","tags":{"clientType":["buyer","seller"],"stage":"post","layer":"道","meetingPhase":["见前","见中"]},"alias":["契税法定税率","契税税率规定","买房契税交多少"]},{"id":"SNG-CONT-040","name":"签合同时卖方是未成年人怎么处理","domain":"签约中","subScene":"合同条款","scene":"签约中·合同条款","cq":"房主是未成年人，签合同怎么处理？","ola":"须监护人到场代签并办理监护公证","cp":["未成年人不能单独出售房屋","监护人代签须为被监护人利益","需办理监护公证","满16岁也需监护人代签","经纪人须核实监护关系"],"detail":"无民事行为能力或限制民事行为能力人不能单独出售房屋，需由其监护人代为办理。监护人出售未成年人名下房屋的前提必须是为了保证被监护人利益。签约时需办理监护公证或提供能证明监护关系的证件。满16周岁未成年人实践中一般也要求监护人代表处置。经纪人应核实监护关系真实性。","legalRef":"《中华人民共和国民法典》第20条、第21条、第22条、第23条、第35条","consumerBenefit":"按法律程序签约，避免合同因主体资格问题无效","tags":{"clientType":["buyer","seller"],"stage":"mid","layer":"法","meetingPhase":["见中","见前"]},"alias":["未成年人卖房怎么签约","监护人代签合同要求","未成年房主签约流程"]},{"id":"SNG-DEPO-036","name":"定金收了买方想换房怎么办","domain":"签约中","subScene":"定金订金","scene":"签约中·定金订金","cq":"交了定金后想换另一套房定金怎么办？","ola":"同卖方可协商换不同卖方定金不退","cp":["同卖方可协商调换","需重新签定金协议","换不同卖方定金不退","签约前充分比较房源","新房部分允许同项目换房"],"detail":"交定金后买方想换房的需与卖方协商。若换的是同一卖方的不同房源通常可以协商调换但需重新签订或变更定金协议。若换的是不同卖方的房源需先与原卖方解除定金协议买方违约的定金不退。建议签约前充分比较房源交定金后换房成本很高。","legalRef":"《中华人民共和国民法典》第543条","consumerBenefit":"定金交了换房代价大签约前想清楚","tags":{"clientType":["buyer","seller"],"stage":"mid","layer":"道","meetingPhase":["见中","见前"]},"alias":["定金后换另一套房","交定金想换房源","定金能换房吗"]},{"id":"SNG-FUND-041","name":"监管银行破产钱会没吗","domain":"签约中","subScene":"资金监管","scene":"签约中·资金监管","cq":"要是监管银行倒闭了，我放在里面的首付款还能拿回来吗？","ola":"监管资金独立于银行自有资产，受存款保险保护。","cp":["监管资金不属于银行破产财产","享受存款保险最高50万赔付","优先选择大型国有或股份制银行","中小银行破产需走清算受偿"],"detail":"监管银行若发生破产，存放在监管账户内的资金属于交易双方的特定化资金，不属于银行自有破产财产。根据《存款保险条例》，监管账户资金通常享受最高50万赔付，超出部分需通过破产清算受偿。实践中，大型国有银行破产概率极低，但中小银行存在理论风险。建议优先选择大型国有银行或股份制银行作为监管银行，以保障资金绝对安全。","legalRef":"《存款保险条例》第5条","consumerBenefit":"明确监管资金在银行破产时的优先受偿属性，消除资金灭失恐慌。","tags":{"clientType":["buyer","seller"],"stage":"mid","layer":"术","meetingPhase":["见前","见中"]},"alias":["监管银行倒闭资金安全","银行破产监管钱怎么赔","存款保险保监管账户吗"]},{"id":"SNG-INS-074","name":"房屋质量保险保什么","domain":"签约交易","subScene":"保险保障","scene":"签约交易·保险保障","cq":"买新房时说的房屋质量保险，具体都保些什么问题？","ola":"主要保房屋主体结构及防水工程在保修期内的质量缺陷。","cp":["保障主体结构与防水","覆盖施工及材料缺陷","开发商投保业主受益","保修期内免费维修"],"detail":"房屋质量保险（又称住宅工程质量潜在缺陷保险，简称IDI）主要用于保障房屋在正常使用条件下，因设计、施工或材料等原因造成的主体结构、防水工程及装饰装修工程的质量缺陷。在保修期内出现如地基沉降、墙体开裂、屋面漏水等问题时，由保险公司负责维修或赔偿。该险种通常由开发商投保，业主是最终受益人。","legalRef":"《建筑法》第六十二条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","seller","landlord"],"stage":"mid","layer":"道","meetingPhase":["见前","见中"]},"alias":["房屋质量保险","房屋质量保证险","新房质量保险"]},{"id":"SNG-LOAN-042","name":"流水不够月供两倍怎么办","domain":"签约交易","subScene":"贷款办理","scene":"签约交易·贷款办理","cq":"我的银行流水不够月供的两倍，还能贷款吗？","ola":"可增加共同还款人、提供其他资产证明或提高首付。","cp":["增加共同还款人","提供其他资产证明","提高首付降月供","严禁伪造流水"],"detail":"若个人银行流水不足以覆盖月供的两倍，可通过以下方式解决：1.增加符合条件的共同还款人（如配偶、父母），合并计算收入；2.提供其他资产证明，如大额存单、理财、其他房产或车辆行驶证；3.提供兼职收入证明或租金收入流水；4.适当提高首付比例，降低贷款总额和月供。切勿伪造流水，以免被拒贷或列入黑名单。","legalRef":"《中华人民共和国商业银行法》第三十五条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","seller","landlord"],"stage":"mid","layer":"道","meetingPhase":["见前","见中"]},"alias":["流水不够","收入不够月供","流水不达标"]},{"id":"SNG-LOAN-045","name":"担保人需要什么资格","domain":"签约交易","subScene":"贷款办理","scene":"签约交易·贷款办理","cq":"如果找担保人，什么样的人有资格做担保人？","ola":"需有本地户口、稳定收入、征信良好及代偿能力。","cp":["具备代偿能力","征信良好无逾期","有本地户口或资产","承担连带还款责任"],"detail":"房贷担保人需具备代为清偿债务的能力。基本资格包括：1.具有完全民事行为能力，通常要求本地户口或长期居住证明；2.有稳定的职业和收入，具备代偿能力；3.个人征信良好，无不良信用记录；4.拥有可变现的资产（如房产）；5.年龄一般不超过65岁。担保人需在担保合同上签字，若借款人断供，担保人需承担连带还款责任。","legalRef":"《中华人民共和国民法典》第六百八十一条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","seller","landlord"],"stage":"mid","layer":"道","meetingPhase":["见前","见中"]},"alias":["担保人","贷款担保人","担保条件"]},{"id":"SNG-PAY-005","name":"商业贷款利率怎么算","domain":"签约中","subScene":"付款方式","scene":"签约中·付款方式","cq":"商业贷款的利率是怎么算出来的？","ola":"利率=LPR+基点，LPR每月更新，基点看银行","cp":["商贷利率=LPR+基点","LPR每月公布一次","基点可正可负","首套利率低于二套","浮动vs固定利率选一个"],"detail":"商业房贷利率=LPR+基点（可为负值）。LPR由央行授权全国银行间同业拆借中心每月公布，5年以上LPR为基准。各银行根据客户资质和城市政策确定加点数。2024年多项政策调降后，多数城市首套商贷利率已降至LPR-20BP至LPR水平。选择浮动利率的，每年重定价一次；选择固定利率的全还款期不变。","legalRef":"中国人民银行公告〔2019〕第16号","consumerBenefit":"看懂利率构成，选到最低利率方案","tags":{"clientType":["buyer","seller"],"stage":"mid","layer":"道","meetingPhase":["见中","见前"]},"alias":["LPR利率计算","房贷利率怎么看","商贷利率基点"]},{"id":"SNG-PAY-035","name":"首付不够有什么解决办法","domain":"签约中","subScene":"付款方式","scene":"签约中·付款方式","cq":"首付差一点不够怎么办？","ola":"公积金补充或组合贷严禁消费贷凑首付","cp":["公积金余额可补充","组合贷降低首付比例","严禁消费贷做首付","首套首付15%-20%","二套首付30%-40%"],"detail":"首付不足的解决途径：使用公积金余额补充首付款；申请组合贷款降低商贷首付比例；与卖方协商延长付款周期；出售其他资产变现。严禁使用消费贷经营贷作为首付银行查到将拒贷。首套首付通常15%-20%二套30%-40%。","legalRef":"银保监会经营贷流入房地产通知","consumerBenefit":"首付不够有办法但别碰消费贷红线","tags":{"clientType":["buyer","seller"],"stage":"mid","layer":"道","meetingPhase":["见中","见前"]},"alias":["首付不足怎么办","首付差一点怎么凑","首付资金不够"]},{"id":"SNG-TAX-034","name":"离婚后卖房子个税怎么算","domain":"签约交易","subScene":"税费计算","scene":"签约交易·税费计算","cq":"我离婚后把分得的房子卖掉，这个房子的个人所得税怎么算？","ola":"离婚析产卖房可按原购房时间计算满五唯一免个税。","cp":["购房时间按原购房算","满五唯一可免征个税","不满足则正常缴个税","原值按原合同或判决认定"],"detail":"离婚析产后出售房产，其购房时间可以按原购房时间连续计算。如果原购房时间满五年，且该房产是出售方家庭的唯一住房，则可以享受满五唯一免征个人所得税的优惠。如果不满足满五唯一，则需按规定缴纳个税。在计算差额20%个税时，房屋原值通常按原购房合同价格或离婚协议中确认的价值来认定，具体需结合当地税务局对离婚析产原值认定的口径。","legalRef":"《国家税务总局关于明确个人所得税若干政策执行问题的通知》第四条","consumerBenefit":"了解相关知识，做出更明智的决策","tags":{"clientType":["buyer","seller","landlord"],"stage":"mid","layer":"道","meetingPhase":["见前","见中"]},"alias":["离婚售房个税怎么算","离婚卖房个税","离婚房产交易个税"]},{"id":"OWN-RNT-CASE-013","name":"业主出租前如何核验租客身份及资质？","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"租房时房东查我身份证合法吗？","ola":"必须查验身份证原件并留存复印件。","cp":["查验身份证原件并留存复印件","核实企业营业执照及授权书","通过第三方平台查询租客信用","身份不符或信用极差拒绝出租"],"detail":"业务场景：业主在签约前需确认租客真实身份及信用状况，防范欺诈及违法使用房屋。判断要点：必须查验身份证原件并留存复印件，通过公安系统或第三方信用平台核实身份真伪；若租客为企业，需查验营业执照及法人授权书。关键决策因素：身份不符或信用极差者应拒绝出租，避免后续收租困难或房屋被用于非法用途。","legalRef":"《商品房屋租赁管理办法》","consumerBenefit":"保障交易安全，防范欺诈风险。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["房东怎么查租客身份","出租房屋怎么核实承租人信息","业主怎么确认租客是不是骗子"]},{"id":"OWN-RNT-CASE-022","name":"业主出租毛坯房让租客装修有哪些风险？","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"租客自己花钱装修，退租时能要补偿吗？","ola":"面临违规装修连带责任及解约装修归属纠纷。","cp":["审核装修方案严禁破坏承重结构","明确免租期条件及违约追回机制","约定提前解约时装修残值归属","要求租客提供装修合规及环保承诺"],"detail":"业务场景：业主为促成出租，同意租客对毛坯房进行装修并可能给予免租期，但面临装修合规及到期后装修归属纠纷。判断要点：需审核租客装修方案是否破坏承重结构，明确装修材料环保标准；必须在合同中约定免租期条件及合同提前解除时装修残值的补偿机制。关键决策因素：租客装修质量不达标或违规施工，业主需承担连带责任；提前解约时装修归属极易引发高额索赔。","legalRef":"《中华人民共和国民法典》第七百一十五条","consumerBenefit":"规避装修违规风险，明确资产归属。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["毛坯房租给租客装修有风险吗","房东让租客装修毛坯房的坑","业主出租毛坯房租客装修注意事项"]},{"id":"OWN-RNT-CASE-023","name":"业主同意租客转租需要注意哪些法律风险？","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"二房东转租，原房东有权赶人吗？","ola":"面临次承租人违约及房屋被破坏的维权风险。","cp":["明确转租期限不得超过原租赁期","要求转租必须经业主书面备案同意","约定原租客对次承租人行为负连带责任","严禁次承租人再次转租或改变用途"],"detail":"业务场景：业主在合同中同意租客转租，但面临次承租人违约及房屋被破坏的风险。判断要点：必须在合同中明确转租期限不得超过原租赁期限，约定转租需经业主书面备案，并明确业主对次承租人的行为承担连带责任。关键决策因素：若未加限制，租客可能擅自改变房屋用途或群租，且次承租人损坏房屋时，原租客可能推诿扯皮，导致业主维权困难。","legalRef":"《中华人民共和国民法典》第七百一十六条","consumerBenefit":"规范转租行为，保障房屋资产安全。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["房东同意转租有什么风险","业主允许租客转租的注意事项","出租房屋同意转租的坑"]},{"id":"OWN-RNT-CASE-024","name":"业主在出租房内安装监控摄像头有什么风险？","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"房东在客厅装监控我有权要求拆除吗？","ola":"极易侵犯租客隐私权，面临民事及刑事处罚。","cp":["严禁在卧室卫生间等私密空间安装","公共区域安装必须提前书面告知租客","监控数据需妥善保管严禁外泄","退租时必须拆除并销毁相关数据"],"detail":"业务场景：业主为防范房屋被破坏或出于安全考虑，在出租房内安装监控摄像头，极易侵犯租客隐私权。判断要点：绝对禁止在卧室、卫生间等私密空间安装；即使在客厅或大门外安装，也必须在合同中明确告知租客并取得书面同意。关键决策因素：未经同意安装监控或监控覆盖私密区域，不仅面临民事侵权赔偿，情节严重者可能触犯治安管理处罚法甚至刑法。","legalRef":"《中华人民共和国民法典》第一千零三十三条","consumerBenefit":"避免侵犯隐私引发的法律制裁及赔偿。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["房东在出租屋装监控有风险吗","业主出租房安装摄像头隐患","租房装监控侵犯隐私吗"]},{"id":"OWN-RNT-CASE-025","name":"业主委托长租公寓机构包租有哪些资金风险？","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"长租公寓跑路了，房东有权赶我走吗？","ola":"面临机构爆雷跑路导致租金落空及清退纠纷。","cp":["审查机构资质警惕高收低租模式","约定租金支付周期及逾期解除权","防范机构爆雷导致租客驱赶纠纷","要求机构提供履约担保或保证金"],"detail":"业务场景：业主将房屋委托给长租公寓或包租机构进行统一出租，面临机构资金链断裂导致收不到租金的风险。判断要点：需审查机构的资质、注册资本及过往口碑，警惕“高收低租”、“长收短付”的异常商业模式；合同中应约定租金支付周期及违约解除权。关键决策因素：一旦机构爆雷跑路，业主不仅收不到租金，还可能面临被机构已收取长期租金的租客驱赶的复杂纠纷。","legalRef":"《中华人民共和国民法典》第七百一十六条","consumerBenefit":"识别资金风险，保障租金收益安全。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["房子交给长租公寓包租有风险吗","业主委托机构包租的资金坑","租房给长租公寓机构有什么隐患"]},{"id":"OWN-RNT-CASE-026","name":"业主出租房屋未约定维修责任会面临什么风险？","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"租房东西坏了，依法应该谁出钱修？","ola":"面临承担全部法定维修义务及费用失控风险。","cp":["法定默认由业主承担维修义务","未约定则业主需承担自然老化维修费","租客自行维修可能产生高额报销诉求","需明确小修租客负责大修业主负责的边界"],"detail":"业务场景：业主在租赁合同中未明确约定房屋及设施的维修责任，导致物品损坏时双方互相推诿。判断要点：法定原则是出租人承担维修义务，除非合同另有约定。若未约定，家电自然老化或管道漏水等维修费用及时间成本将由业主承担。关键决策因素：未明确责任边界，租客可能自行维修后要求业主报销高额费用，或因维修不及时导致损失扩大，业主需承担扩大的损失。","legalRef":"《中华人民共和国民法典》第七百一十二条","consumerBenefit":"明确维修边界，控制房屋维护成本。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["租房没约定维修责任有风险吗","房东不约定维修义务有什么隐患","业主出租房屋维修责任未明确的风险"]},{"id":"OWN-RNT-CASE-027","name":"业主把带租约的房子卖掉会面临什么违约风险？","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"房东把房子卖了，我有权继续住到期满吗？","ola":"面临买卖不破租赁及侵犯优先购买权风险。","cp":["必须遵守买卖不破租赁原则","提前通知租客保障其优先购买权","隐瞒租赁事实将面临违约赔偿","新业主需无条件继续履行原合同"],"detail":"业务场景：业主在房屋租赁期间将房屋出售，面临新产权人需继续履行原租赁合同及租客主张优先购买权的风险。判断要点：必须遵守“买卖不破租赁”原则，新业主需继续履行原合同至期满；同时需提前通知租客，保障其优先购买权。关键决策因素：若隐瞒租赁事实或强迫租客搬离，将面临对租客的违约赔偿；若未通知租客即出售，租客可主张赔偿或要求撤销交易。","legalRef":"《中华人民共和国民法典》第七百二十五条","consumerBenefit":"合规处置资产，避免对租客及买家的违约赔偿。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["带租约卖房有风险吗","房东卖房时房子还在租怎么办","业主出售出租中房屋的违约风险"]},{"id":"OWN-TNT-CASE-026","name":"租客在屋内堆放危险品房东未尽审查义务有何风险？","domain":"资产持有与运营","subScene":"租客纠纷应对","scene":"资产持有与运营·租客纠纷应对","cq":"我在出租屋放危险品，房东会被处罚吗？","ola":"面临消防处罚，引发事故需承担连带赔偿及刑责。","cp":["面临消防部门罚款及停业处罚","引发事故需承担民事连带赔偿","造成重大伤亡涉嫌刑事犯罪","必须履行安全审查与巡查义务"],"detail":"若租客在出租屋内堆放易燃易爆等危险品，房东若未尽到合理审查和监管义务，将面临严重的行政甚至刑事风险。行政方面，消防部门可对房东处以罚款、责令停产停业；民事方面，若危险品引发火灾爆炸造成第三方人身财产损失，房东因提供不符合安全条件的房屋或未尽管理义务，需承担连带赔偿责任；刑事方面，若造成重大伤亡，房东可能涉嫌消防责任事故罪。","legalRef":"《中华人民共和国消防法》第六十条、《中华人民共和国民法典》第一千一百六十八条","consumerBenefit":"明确危险品存放的法律后果，遵守消防安全规定。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["租客放危险品房东有责任吗","房屋内存放危险物品房东的风险","房东未审查租客用途有何法律风险"]},{"id":"OWN-TNT-CASE-028","name":"租客利用房屋注册公司退租后不迁出有何风险？","domain":"资产持有与运营","subScene":"租客纠纷应对","scene":"资产持有与运营·租客纠纷应对","cq":"退租后我不迁走公司地址，房东能把我怎么样？","ola":"导致房屋无法注册新公司，且易被牵连查处。","cp":["房屋无法注册新公司导致贬值","原租客违法经营牵连房东被查","地址被锁定影响正常出租自用","需在合同中约定迁出违约金"],"detail":"租客利用租赁房屋注册公司，退租后若拒不迁出工商地址，房东将面临房屋无法再次注册新公司的风险，导致房屋商业价值贬值。此外，若原租客利用该地址继续从事违法经营或产生债务纠纷，工商、税务部门可能上门查处，影响房东正常出租或自用。更严重的是，若原租客被列入经营异常名录，该房屋地址可能被工商局锁定，房东需耗费大量时间精力申请解除异常。","legalRef":"《中华人民共和国市场主体登记管理条例》","consumerBenefit":"明确地址迁出的法律义务，避免违约赔偿。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见后"]},"alias":["租客注册公司退租不迁走怎么办","房屋被占用工商注册房东有风险吗","退租后公司地址不迁出房东的风险"]},{"id":"OWN-TNT-CASE-029","name":"房东未核实租客身份直接出租面临哪些治安风险？","domain":"资产持有与运营","subScene":"租客纠纷应对","scene":"资产持有与运营·租客纠纷应对","cq":"租房时房东不查我的身份证合法吗？","ola":"违反治安管理，面临罚款甚至更严厉处罚。","cp":["违规出租面临二百至五百元罚款","未登记信息违反治安管理规定","租客犯罪房东知情不报受重罚","必须查验身份证并公安报备"],"detail":"房东出租房屋时，若未按规定查验租客身份证件、不登记信息或不向公安机关报备，将面临严重的治安处罚风险。根据《治安管理处罚法》，房东将房屋出租给无身份证件的人，或不按规定登记承租人姓名、身份证件种类和号码的，处二百元以上五百元以下罚款。若租客利用该房屋从事违法犯罪活动，房东明知而不清退的，还将面临更严厉的处罚甚至刑事责任。","legalRef":"《治安管理处罚法》第五十七条","consumerBenefit":"了解租赁实名制的法律要求，配合身份登记。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["出租房屋不登记租客身份有风险吗","房东不查身份证直接出租的后果","未核实承租人身份房东的治安风险"]},{"id":"OWN-TNT-CASE-031","name":"买卖不破租赁原则的法定例外情形有哪些？","domain":"资产持有与运营","subScene":"租客纠纷应对","scene":"资产持有与运营·租客纠纷应对","cq":"房东把房子卖了，新房东能让我搬走吗？","ola":"先抵押、先查封或另有约定可打破该原则。","cp":["先抵押后出租不适用该原则","先查封后出租不适用该原则","当事人另有书面约定的除外","例外情形下租客可向原房东索赔"],"detail":"“买卖不破租赁”是保护租客居住权的重要原则，但《民法典》及相关司法解释规定了例外情形。首先，房屋在出租前已设立抵押权，因抵押权人实现抵押权发生所有权变动的，不适用该原则；其次，房屋在出租前已被人民法院依法查封的，不适用该原则；最后，当事人另有约定的除外（如租客书面同意新房东可解除合同）。在这些例外情形下，新房东有权要求租客搬离，租客只能向原房东主张违约赔偿。","legalRef":"《中华人民共和国民法典》第七百二十五条、第四百零五条，《最高人民法院关于审理城镇房屋租赁合同纠纷案件具体应用法律若干问题的解释》第十四条","consumerBenefit":"了解买卖不破租赁的例外，合理评估购房及租房风险。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["买卖不破租赁有例外吗","新房东必须履行原租赁合同吗","哪些情况买卖不破租赁不适用"]},{"id":"OWN-TNT-CASE-040","name":"租客在群租房内发生意外房东因消防违规被判赔偿的典型案例？","domain":"资产持有与运营","subScene":"租客纠纷应对","scene":"资产持有与运营·租客纠纷应对","cq":"我租的群租房发生火灾受伤，房东需要赔偿我吗？","ola":"违规群租致意外，房东需承担重大赔偿责任。","cp":["违规群租存在重大安全隐患","房东对事故过错承担30%-70%赔偿","使用易燃材料隔断加重责任","严禁违规改变房屋结构出租"],"detail":"房东将房屋违规打隔断出租（群租），若租客在屋内发生火灾、触电等意外伤亡，房东极易被判决承担主要或次要赔偿责任。典型判例中，法院认定房东违规改变房屋结构、使用易燃材料隔断、未配备合格消防设施，存在重大安全隐患，对事故发生具有过错。即使租客自身也存在使用不当，房东仍需承担30%-70%不等的赔偿责任，赔偿金额高达数十万至百万。此案警示房东严禁违规群租。","legalRef":"《中华人民共和国民法典》第一千一百六十五条、第一千一百九十二条，《商品房屋租赁管理办法》第八条","consumerBenefit":"了解群租房的安全风险及房东责任，拒绝违规群租。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["群租房出事房东要赔偿吗","房屋违规隔断租客受伤房东有责任吗","群租房消防不合格租客意外房东判例"]},{"id":"OWN-OWN-CASE-026","name":"业主自住房屋的产权证遗失，申请补办的法定流程和条件是什么？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东的房产证丢了，补办需要满足什么法定条件和流程？","ola":"本人申请，官方公告15个工作日无异议后补发。","cp":["权利人本人可申请补发","需在官方渠道公告作废","公告期满15个工作日补发","有抵押查封需先解除限制"],"detail":"业务场景：业主自住房屋的不动产权证（或老房产证）不慎遗失或损毁，需要向登记机构申请补发。判断要点：依据《不动产登记暂行条例实施细则》，权利人可申请补发。关键决策因素在于登记机构是否能在官方门户网站或当地公开发行的报刊上公告作废，公告期满（通常为15个工作日）无异议后，方可补发新证。若房屋存在抵押或查封，需先解除限制或取得抵押权人同意。","legalRef":"《不动产登记暂行条例实施细则》第二十二条","consumerBenefit":"明确补办流程，避免因证件遗失影响房屋交易或抵押。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["房产证丢了补办法定流程和条件","不动产权证遗失申请补办法律规定","房屋产权证丢失怎么补办法定程序"]},{"id":"OWN-OWN-CASE-028","name":"业主自住房屋的产权证名字和身份证名字不一致，如何办理变更？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东的房产证名字和身份证不一样，如何办理变更才能过户？","ola":"凭派出所变更证明或登记机构笔误证明办理变更。","cp":["区分登记笔误还是自身改名","自身改名需派出所开证明","带齐证明到不动产中心办理","变更或更正均不收登记费"],"detail":"业务场景：业主自住房屋产权证上的姓名与现身份证姓名不一致（如早期登记错别字、姓名变更、身份证号升位等），影响后续交易或抵押。判断要点：需向不动产登记中心申请姓名变更或更正登记。关键操作步骤：若为登记机构笔误，申请更正登记；若为业主自身改名或身份证号变更，需先到派出所开具变更证明，再带齐证明、身份证、房产证到不动产中心办理变更登记。","legalRef":"《不动产登记暂行条例实施细则》第七十九条、第八十一条","consumerBenefit":"明确信息不一致的解决路径，消除交易障碍。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["房产证名字和身份证不一样怎么变更","产权证姓名与身份证不符如何更改","房产证名字写错了和身份证不一致怎么办"]},{"id":"OWN-OWN-CASE-032","name":"业主自住房屋需要办理委托公证以便他人代办权属业务，流程是什么？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东没空过来，需要办理委托公证代办过户，流程是什么？","ola":"本人带齐证件到公证处面签委托书并缴费出证。","cp":["受托人不能是交易相对方","需本人到公证处面签","明确委托事项及有效期限","部分城市支持线上远程公证"],"detail":"业务场景：业主因故无法亲自办理房屋买卖、抵押、加名等权属业务，需委托他人代办，办理委托公证。判断要点：受托人不能是买方或抵押权人。关键流程：1. 委托人带身份证、房产证、户口本及受托人身份证复印件到公证处；2. 填写公证申请表，公证员审查委托事项及权限；3. 在公证员面前签署委托书；4. 缴纳公证费，领取公证书。部分城市支持远程视频公证。","legalRef":"《中华人民共和国公证法》第二十六条","consumerBenefit":"掌握委托公证流程，解决业主异地或无法到场的交易障碍。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["房屋权属业务委托公证办理流程","代办房产证委托公证怎么做","自住房委托他人办理业务公证流程"]},{"id":"OWN-OWN-CASE-033","name":"业主自住房屋的契税发票丢失，如何补办或获取证明以办理后续业务？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东的契税发票丢了，如何补办或获取证明才能继续过户？","ola":"原件无法补开，需到税务局调档复印并盖章证明。","cp":["原件无法补开需调取档案","到原契税征收机关申请","复印存根并加盖税务印章","加盖印章的复印件同等有效"],"detail":"业务场景：业主自住房屋的契税发票遗失，但在办理卖房、落户或提取公积金时需要用到。判断要点：契税发票原件无法直接补开，但可通过调取档案获取证明效力。关键操作步骤：1. 业主带身份证、房产证到原契税征收机关；2. 申请调取契税缴纳档案；3. 复印契税缴款书或发票存根联；4. 由税务机关在复印件上加盖印章或出具契税完税证明。该证明与原件具有同等效力。","legalRef":"《中华人民共和国发票管理办法》第二十九条","consumerBenefit":"明确契税发票遗失的补救措施，避免耽误交易或办事进度。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["契税发票丢失如何补办或获取证明","自住房契税发票丢了怎么补办","房屋契税发票遗失获取证明流程"]},{"id":"OWN-OWN-CASE-036","name":"业主自住房屋存在历史遗留的违章建筑，过户时面临什么风险？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东的房子有历史遗留违建，过户时会面临什么风险？","ola":"违建会导致过户被冻结，需拆除验收后方可交易。","cp":["违建可能导致过户被冻结","需先拆除违建并恢复原状","经城管验收后方可解除限制","交易停滞易引发定金纠纷"],"detail":"业务场景：业主自住房屋存在历史遗留的违章建筑，在二手房过户时面临风险。判断要点：多数城市不动产登记中心与城管部门联网，若房屋被标注为附有违建或限制交易，将直接冻结过户。关键风险在于买家已付首付但无法过户，导致交易停滞。即使违建是前手业主遗留，现业主也需先拆除违建并恢复原状，经城管验收后方可解除限制。","legalRef":"《不动产登记暂行条例》第二十二条","consumerBenefit":"提前识别违建冻结风险，在合同中约定拆除责任及违约条款。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["房屋有历史遗留违建过户面临什么风险","自住房有违建过户会被冻结吗","房屋存在违章建筑过户风险"]},{"id":"OWN-OWN-CASE-037","name":"业主自住房屋内有非直系亲属的挂靠户口，迁出时有什么风险？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东的房子里有非直系亲属的挂靠户口，迁出时有什么风险？","ola":"公安无法强制迁出，易导致交易停滞或自身户口受阻。","cp":["公安无法强制非亲属迁出","买家可能因户口问题拒收房","影响业主自身户口迁入新房","需提前在合同中约定户口违约金"],"detail":"业务场景：业主自住房屋内除了家庭成员，还有非直系亲属的户口挂靠，现业主欲卖房或要求对方迁出。判断要点：公安机关户籍管理遵循自愿迁移原则，若挂靠人拒不配合迁出，业主无法强制要求其迁出。关键风险在于：卖房时买家因户口问题拒收房或要求扣减尾款；业主自身户口无法顺利迁入新购房屋。若原挂靠人失联或无房可迁，问题将长期僵持。","legalRef":"《中华人民共和国户口登记条例》第十条","consumerBenefit":"认清户口迁出的实操难点，通过合同条款约束或提前清理户口。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["房屋有非直系亲属挂靠户口迁出风险","自住房内有挂靠户口迁出有什么风险","房子里有别人挂靠户口迁出难吗"]},{"id":"OWN-OWN-CASE-038","name":"业主自住房屋是经济适用房，未满五年想通过协议转让，有什么法律风险？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东的经适房未满五年，想通过协议转让给我，有什么法律风险？","ola":"协议易被认定无效，面临退款赔偿及产权无法取得风险。","cp":["未满五年禁止上市交易","私下转让协议易被认定无效","合同无效需退还房款并赔偿","买家无法取得产权维权成本高"],"detail":"业务场景：业主自住房屋为经济适用房，购买未满五年，欲通过签订阴阳合同或长期租赁代买卖等协议形式私下转让给买家。判断要点：经适房未满五年禁止上市交易，此类私下转让协议因违反国家强制性规定及社会公共利益，极易被法院认定为无效。关键风险在于：合同无效后，业主需全额退还房款，可能还需承担缔约过失责任；买家无法取得产权，维权成本极高。","legalRef":"《中华人民共和国民法典》第一百五十三条","consumerBenefit":"识别经适房违规交易的致命风险，拒绝私下协议，避免钱房两空。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["经适房未满五年协议转让法律风险","自住房是经适房未满五年私下转让风险","经济适用房不满五年协议转让有什么风险"]},{"id":"OWN-OWN-CASE-040","name":"业主自住房屋存在未结清的物业费和供暖费，过户时被冻结有什么风险？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东的房子有未结清的物业费和供暖费，过户时被冻结有什么风险？","ola":"欠费可能导致过户受阻，且需承担尾款扣除或违约赔偿。","cp":["欠费可能导致过户被系统拦截","物业拒开证明影响交易进度","买家通常要求从尾款扣除欠费","巨额欠费易引发拒收房纠纷"],"detail":"业务场景：业主自住房屋存在历史遗留的未结清物业费、供暖费或水电燃气费，在办理过户时面临风险。判断要点：部分城市或小区的物业公司与不动产中心联网，或通过在小区公告、系统注记等方式限制欠费房屋过户。关键风险在于：过户时若被系统拦截或物业拒开证明，将导致交易停滞。即使能过户，买家在收房时发现欠费，通常会从尾款中扣除或要求业主结清，若欠费金额巨大，易引发纠纷。","legalRef":"《物业管理条例》第四十一条","consumerBenefit":"提前排查欠费情况，在交房前结清或预留足额物业交割保证金。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中","见后"]},"alias":["房屋有未结清物业供暖费过户被冻结风险","自住房欠物业费供暖费过户风险","房子欠物业费和供暖费过户会被冻结吗"]},{"id":"OWN-VAL-CASE-028","name":"住宅改为商用在估值和出售时法律上如何认定其价值","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"住宅改成商用了，卖房时能按商业价格估值吗？","ola":"估值以不动产登记用途为准，违规住改商无法享受商业溢价。","cp":["估值以不动产登记用途为准","未经审批住改商属违规面临查处","合法住改商可能需补缴土地出让金","违规使用可能导致买家解约"],"detail":"业主将住宅改为商用（如办公、民宿、私房菜），在估值时往往期望参照周边商业房产的高溢价。但法律上，房屋性质仍以不动产登记簿为准。判断要点在于住改商是否经过合法审批及利害关系业主同意。未经法定程序，住改商属于违规行为，面临被投诉取缔的风险，其估值仍只能按住宅计算，且因违规使用可能导致买家拒绝交易。若已合法获批，虽可按商业估值，但土地出让金及税费可能需补缴。关键决策因素是规划审批状态及不动产登记用途。","legalRef":"《中华人民共和国民法典》第二百七十九条（住改商限制）、《中华人民共和国城乡规划法》第四十三条","consumerBenefit":"认清房屋法定用途对估值的决定性作用，避免对违规改造产生不切实际的估值预期。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["住改商的房子在卖房时法律上怎么算估值","住宅改成公司或民宿出售时能按商业价格估值吗","房子性质是住宅但实际商用估值和出售有什么法律限制"]},{"id":"OWN-VAL-CASE-037","name":"业主为高估值隐瞒房屋重大瑕疵面临什么法律与交易风险","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"为了卖高价隐瞒房子漏水或死过人，有什么风险？","ola":"构成欺诈，买家可撤销合同并索赔差价及间接损失。","cp":["隐瞒重大瑕疵构成欺诈可撤销合同","买家有权要求退房并索赔差价损失","凶宅隐瞒可能面临精神损害赔偿","需赔偿买家中介费及装修等间接损失"],"detail":"业主为支撑高于市场平均水平的估值，故意隐瞒房屋曾发生过非正常死亡、严重漏水屡修不好、或存在结构安全隐患等重大瑕疵。风险在于，根据法律规定，此类隐瞒构成欺诈。买家在知情后有权要求撤销合同、退房退款，并要求业主赔偿差价损失及中介费、装修费等间接损失。此外，若涉及凶宅，可能面临精神损害赔偿。关键决策因素是瑕疵是否属于影响合同订立及价格的重大事项，以及业主是否存在主观故意。","legalRef":"《中华人民共和国民法典》第一百四十八条（欺诈）、第五百条（缔约过失责任）","consumerBenefit":"明确隐瞒瑕疵的严重法律后果，避免因小失大，规范信息披露。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["为了卖高价隐瞒房子漏水或死过人有什么风险","隐瞒房屋重大瑕疵提高估值面临什么风险","卖房时隐瞒凶宅或严重漏水等瑕疵有什么风险"]},{"id":"OWN-VAL-CASE-039","name":"房屋估值过高导致看房量极少坚持不降价面临什么沉没成本风险","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"房子挂太高没人看，坚持不降价有什么沉没成本？","ola":"面临持有成本增加、资金占用损失及房屋自然折旧。","cp":["长期空置增加物业及供暖等持有成本","资金占用错失其他投资理财收益","房屋房龄增加导致自然折旧贬值","长期滞销会被平台打上难卖标签"],"detail":"业主对房屋估值缺乏客观认知，设定远高于市场公允价的挂牌价，导致房屋在平台上曝光率和带看量极低。若业主受锚定效应影响，坚持不降价，将面临巨大的沉没成本风险。包括房屋长期空置的物业费、供暖费支出，资金被占用错失的其他投资理财收益，以及房屋自身因房龄增加、设施老化导致的自然折旧贬值。此外，长期滞销的房源在平台上会被打上难卖标签，进一步降低买家议价意愿。","legalRef":"行业风险提示","consumerBenefit":"认清长期滞销的隐性成本，打破心理锚定，及时调整估值策略。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["房子挂太高没人看坚持不降价有什么沉没成本","估值过高导致没看房量坚持不降价面临什么风险","房子挂牌价太高卖不掉坚持不降价有什么风险"]},{"id":"OWN-VAL-CASE-040","name":"业主在估值时忽略房屋剩余土地使用权年限会导致什么交易风险","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"卖房估值没考虑土地剩余年限，有什么交易风险？","ola":"忽略续期成本预期会导致估值虚高，易致谈判破裂。","cp":["土地年限届满续期费用存在不确定性","买家估值时会扣除预期续期成本","忽略此点会导致估值虚高谈判破裂","需核实土地使用权证上的剩余年限"],"detail":"业务中，业主在评估房屋价值时，往往只关注建筑本身的折旧，而忽略剩余土地使用权年限。对于房龄较老的老公房或早期商品房，土地年限可能已所剩无几。风险在于，虽然民法典规定住宅建设用地使用权期限届满自动续期，但续期费用的缴纳标准目前尚无明确细则，市场普遍预期需补缴一笔不菲的土地出让金。买家在估值时会将此预期成本扣除，若业主忽略此点，会导致估值虚高，交易时因价格分歧导致谈判破裂。","legalRef":"《中华人民共和国民法典》第三百五十九条（住宅建设用地使用权自动续期）","consumerBenefit":"全面评估房屋资产价值，避免因忽略土地年限导致的不合理估值预期。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["卖房估值没考虑土地剩余年限有什么风险","忽略房屋剩余土地使用权年限会导致什么交易风险","房子土地年限快到了估值没考虑有什么风险"]},{"id":"OWN-SLD-CASE-026","name":"卖房时卖方亲属代签合同买家能主张无效吗","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"卖家没来，他老婆拿着房产证和身份证代签的，我现在不想买了能算无效吗？","ola":"构成表见代理则有效，否则对业主无效。","cp":["无书面委托需审查表见代理","持有双证原件增强代理外观","夫妻日常家事代理权适用","买家善意且无过失是关键"],"detail":"业主因故无法亲自到场，委托配偶或父母等亲属代签房屋买卖合同。若未提供书面授权委托书，买家事后反悔主张无权代理。法院审查重点在于是否构成表见代理。若亲属持有业主身份证原件、房产证原件，且买家有理由相信其有代理权，法院通常认定合同有效。但若买家明知其无代理权或存在重大过失，则合同对业主不发生效力。","legalRef":"《中华人民共和国民法典》第一百七十二条（表见代理）、第一千零六十条（日常家事代理权）。","consumerBenefit":"规范代签审查流程，降低合同无效风险。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["卖房时老婆代老公签字合同有效吗","亲属代办卖房手续买家不认账怎么办","卖房没拿授权委托书亲属代签算数吗"]},{"id":"OWN-SLD-CASE-031","name":"卖房时业主想公证委托朋友代办手续具体流程是什么","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"卖家在外地，说让朋友拿公证委托书来代办，这流程正规吗？","ola":"需办理委托公证并核实当地非亲属受托限制。","cp":["在所在地公证处办理委托公证","明确委托事项权限及有效期限","公证书原件需邮寄给受托人","核实当地房管对非亲属受托限制"],"detail":"业主因在外地或国外无法亲自办理卖房手续，拟通过公证委托朋友代办。流程包括：业主在所在地公证处办理授权委托书公证，明确委托事项及期限；将公证书原件邮寄给受托人；受托人持公证书原件及相关身份证件到场办理。注意：部分城市房管局限制非亲属受托代办过户或代收房款，需提前核实当地政策。","legalRef":"《中华人民共和国公证法》第十一条、《中华人民共和国民法典》第一百六十一条。","consumerBenefit":"明确公证委托标准流程，防范代办风险。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["卖房时业主不在本地怎么委托朋友代办","公证委托朋友卖房需要哪些材料和流程","业主想委托朋友代签卖房合同怎么办公证"]},{"id":"OWN-SLD-CASE-036","name":"卖房时业主轻信买家全款承诺未核实资金导致拖延付款怎么办","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"我买二手房说全款，但一直拖延付款，卖家能直接解除合同吗？","ola":"需核实资金实力，逾期果断解约索赔。","cp":["签约前需核实买家资金实力","设定严格付款节点及逾期违约金","警惕高价全款锁盘错失良机","逾期超期果断发函解约并索赔"],"detail":"业主在卖房时，遇到买家承诺全款购买且出价高于市场价，但未要求买家提供资金证明或进行资金监管，直接签订高价合同。后续买家以各种理由拖延付款，甚至资金链断裂无法履约。此场景下，业主面临房屋被长期锁盘错失其他交易机会的风险。防范要点：签约前必须核实买家资金实力；合同中必须设定严格的付款节点及高额逾期违约金；若买家逾期超期应果断解约。","legalRef":"《中华人民共和国民法典》第五百六十三条（法定解除权）、第五百八十五条（违约金）。","consumerBenefit":"提示全款交易资金风险，保障业主收款安全。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["卖房时买家说全款但一直拖延付款怎么办","卖房时没核实买家资金实力买家全款违约怎么办","买家承诺全款买房却拿不出钱业主如何维权"]},{"id":"OWN-SLD-CASE-037","name":"卖房时业主配合买家做低网签价买家反悔按低价支付有什么风险","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"为了少交税做低了网签价，现在卖家反悔要按实际高价收钱，法院支持谁？","ola":"做低网签价违法，买家反悔易致房款损失。","cp":["做低网签价属逃税违法行为","买家反悔可能导致房款损失","需签补充协议明确实际成交价","保留银行转账流水作为核心证据"],"detail":"业主为配合买家减少契税，同意在网签合同中做低房屋交易价格。若买家事后反悔，拒绝按实际成交价支付，仅按网签低价付款，业主将面临巨大风险：法律风险方面，做低网签价属于逃税行为，一旦被查处需补缴税款并罚款；财务风险方面，若合同中对实际成交价证据保留不足，法院可能仅支持网签价格，导致业主损失巨额房款。防范核心：必须通过补充协议明确实际成交价并保留流水。","legalRef":"《中华人民共和国民法典》第一百四十六条（虚假意思表示）、《中华人民共和国税收征收管理法》第六十三条（偷税处罚）。","consumerBenefit":"警示阴阳合同逃税风险，保障业主合法收益。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["卖房时做低网签价买家按低价付款业主怎么办","为了省税做低网签价买家反悔了业主有风险吗","二手房阴阳合同做低网签价买家不认账怎么办"]},{"id":"OWN-SLD-CASE-038","name":"卖房时业主口头承诺留车位没写进合同事后反悔算违约吗","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"卖家口头答应送我车位但没写进合同，现在反悔了，我能告他违约吗？","ola":"口头承诺未入合同，有证据则算违约。","cp":["口头承诺未入合同效力存疑","书面合同效力通常优于口头","买家有确凿证据可认定违约","核心交易条件需必须书面化"],"detail":"业主在签约前为促成交易，口头承诺买家留个车位或送地下室，但未将其写入正式的房屋买卖合同或附件中。事后业主反悔，拒绝交付车位。此场景下，业主面临违约风险。根据法律规定，口头承诺若无录音、微信聊天记录等确凿证据佐证，且与书面合同条款冲突，法院通常以书面合同为准。但若买家能提供充分证据证明该口头承诺是促成签约的核心条件，法院可能认定该承诺构成合同内容。","legalRef":"《中华人民共和国民法典》第四百六十九条（合同形式）、《中华人民共和国民事诉讼法》第六十六条（证据种类）。","consumerBenefit":"提示口头承诺风险，规范交易条件书面化。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["卖房时口头答应送车位没写合同算违约吗","签约前口头承诺留车位事后反悔买家能索赔吗","卖房时没把车位写进合同口头承诺有效吗"]},{"id":"OWN-SLD-CASE-039","name":"卖房时带租约出售未取得租客放弃优先购买权声明有什么风险","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"我买的房带租约，现在租客跳出来说他要优先买，这合同还有效吗？","ola":"需取得租客书面放弃优先购买权声明。","cp":["租客享有同等条件优先购买权","未通知租客易引发诉讼纠纷","必须取得书面放弃优先购买权声明","买卖不破租赁需继续履行租约"],"detail":"业主将正在出租的房屋出售。根据法律规定，租客在同等条件下享有优先购买权。若业主未提前通知租客，或未取得租客书面放弃优先购买权的声明，租客有权向法院主张按同等条件优先购买该房屋，或要求业主承担赔偿责任。虽然这通常不会导致买卖合同无效，但会引发诉讼纠纷，导致过户受阻。防范要点：签约前必须向租客核实意愿，并要求租客签署放弃优先购买权声明书。","legalRef":"《中华人民共和国民法典》第七百二十六条（承租人优先购买权）、第七百二十五条（买卖不破租赁）。","consumerBenefit":"明确带租约交易规则，保障交易顺利推进。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["卖房时带租约没通知租客有什么风险","卖房时没取得租客放弃优先购买权声明怎么办","带租约出售房屋租客主张优先购买权有风险吗"]},{"id":"OWN-DISPUTE-041","name":"业主隐瞒房屋内发生过非正常死亡事件导致合同被撤销的判例","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"买到凶宅了怎么让业主退钱？","ola":"隐瞒凶宅属欺诈，买家可撤销合同并索赔。","cp":["隐瞒非正常死亡属欺诈","买家有权主张撤销合同","业主需退还房款并赔偿","经纪人需核实房屋历史"],"detail":"在二手房交易中，若业主故意隐瞒房屋内曾发生过自杀、他杀等非正常死亡事件，买家在知情后起诉要求撤销合同并索赔。此类判例中，法院通常认定“凶宅”信息属于影响缔约目的和房屋价值的重大事实，业主负有主动披露义务。经纪人需判断业主是否知情及是否刻意隐瞒，若业主隐瞒，买家有权主张撤销合同、退还房款并索赔中介费及资金占用利息。","legalRef":"《中华人民共和国民法典》第一百四十八条（欺诈撤销权）及第七条（诚实信用原则）","consumerBenefit":"明确凶宅披露义务，保障买家知情权与退房索赔权。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["卖房隐瞒凶宅被判撤销合同","没告知买家死过人合同能退吗","隐瞒凶宅法院怎么判"]},{"id":"OWN-DISPUTE-042","name":"业主在抵押期间未经银行同意卖房导致合同无效的判例","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"房贷没还清的房子能直接买吗？","ola":"未经银行同意或未走带押过户，抵押房无法直接过户。","cp":["未解押直接过户存在障碍","带押过户需符合当地政策","未经同意过户可能无效","需先解押或走带押流程"],"detail":"业主在房屋尚有银行按揭抵押且未办理“带押过户”的情况下，私下与买家签订买卖合同并试图直接过户，被银行起诉或买家发现后引发纠纷。根据最新判例，若未走带押过户流程且未经抵押权人同意，直接过户存在障碍，甚至可能因损害抵押权被认定部分行为无效。经纪人需判断当地是否支持带押过户，若不支持，必须要求业主先结清贷款解除抵押，否则交易无法推进且业主需承担违约责任。","legalRef":"《中华人民共和国民法典》第四百零六条（抵押财产转让）","consumerBenefit":"规避抵押房产交易障碍，确保过户流程合法合规。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["没解押直接卖房合同有效吗","带押过户没通知银行算违约吗","抵押房私下交易被判无效案例"]},{"id":"OWN-DISPUTE-049","name":"业主口头承诺赠送家具家电未写入合同有什么风险","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"房东口头说送家具，没写合同能信吗？","ola":"口头承诺无书面证据易违约，必须写入合同。","cp":["口头承诺举证困难","未入合同易被认定违约","交房时易引发拒收纠纷","必须转化为书面补充协议"],"detail":"业主在带看或谈判时，为促成交易口头承诺将屋内高档家具家电赠送给买家，但未将其写入《房屋买卖合同》或补充协议中。此类风险在于，法律上“谁主张谁举证”，若买家事后主张业主未兑现承诺，业主面临败诉风险；同时，若业主在交房前将物品搬走，买家可能以“欺诈”或“违约”为由拒绝收房或索赔。经纪人必须将所有口头承诺转化为书面条款，明确赠送物品的品牌、数量及状态，避免交房时产生纠纷。","legalRef":"《中华人民共和国民法典》第四百六十九条（合同形式）及第五百零九条（全面履行原则）","consumerBenefit":"警示口头承诺的法律风险，规范合同条款管理。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["口头答应送家具没写合同有效吗","卖房口头承诺赠送家电有风险吗","没写进合同的赠送承诺算数吗"]},{"id":"OWN-DISPUTE-051","name":"业主在房屋内设立居住权后再卖房有什么风险","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"买了有居住权的房子，能赶走里面的人吗？","ola":"居住权无法驱赶，未披露属欺诈可撤销合同。","cp":["买卖不破居住权","未披露构成欺诈可撤销","产调必须核实居住权登记","签约前必须向买家披露"],"detail":"业主在房屋上为他人（如老人、亲属）设立了居住权并登记后，再将房屋出售。此风险在于，居住权具有物权效力，买卖不破居住权。买家即使取得房屋所有权，也无法要求居住权人搬离，导致房屋实际使用价值大打折扣。若业主未在签约前明确告知买家居住权的存在，买家有权以欺诈或重大误解为由撤销合同并索赔。经纪人必须在产调时核实居住权登记情况，并在签约前向买家充分披露，否则极易引发重大纠纷。","legalRef":"《中华人民共和国民法典》第三百六十六条（居住权定义）及第三百六十九条（居住权不得转让、继承）","consumerBenefit":"明确居住权对房屋交易的限制，保障买家知情权。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["设立了居住权的房子能卖吗","房子有居住权卖房有什么风险","带居住权卖房买家能赶走老人吗"]},{"id":"OWN-DISPUTE-052","name":"业主委托亲属代签买卖合同未提供公证授权书的风险","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"房东没来，他亲戚代签的合同有效吗？","ola":"无公证授权代签无效，必须核实公证委托书。","cp":["未公证授权业主可否认","越权代签导致合同无效","必须核实公证授权书","明确授权范围及期限"],"detail":"业主因故无法到场，委托亲属或朋友代签《房屋买卖合同》，但仅提供手写委托书或未提供公证授权书。此风险在于，若业主事后不追认，代签行为对业主不发生效力，买家可主张合同无效或要求代签人承担缔约过失责任。即使有公证授权书，若授权范围不明确（如未明确授权代收定金、代签补充协议），代签人的越权行为也可能导致合同部分无效。经纪人必须要求提供经公证的明确授权委托书，并核实代签人身份及授权范围。","legalRef":"《中华人民共和国民法典》第一百六十一条（代理效力）及第一百七十一条（无权代理）","consumerBenefit":"规范委托代签流程，防范合同无效及违约风险。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["亲属代签没公证授权书有效吗","委托别人代签卖房合同有什么风险","没公证的委托书代签合同算数吗"]},{"id":"OWN-DISPUTE-053","name":"业主隐瞒房屋曾发生过火灾导致买家拒收房怎么防范索赔风险？","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"买的二手房以前着过火卖家没告诉我，我能拒收或退房吗？","ola":"需视火灾对结构及心理影响程度，隐瞒重大瑕疵需赔偿。","cp":["核实火灾定损报告","确认主体修复验收","签约前书面披露","留存修复合格证明"],"detail":"在二手房交易中，若房屋曾发生过火灾且业主未在带看或签约时如实披露，买家收房时发现后可能以“隐瞒重大瑕疵”为由拒收或要求降价。经纪人需判断火灾是否影响房屋主体结构安全及居住心理。若仅轻微熏黑且已修复，风险较低；若伤及承重墙或造成严重心理阴影，业主将面临解除合同及赔偿风险。关键在于火灾定损报告及修复验收证明。","legalRef":"《中华人民共和国民法典》第五百条规定，当事人在订立合同过程中故意隐瞒与订立合同有关的重要事实，造成对方损失的，应当承担赔偿责任。","consumerBenefit":"避免买到存在安全隐患或心理瑕疵的房屋，保障居住安全。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["卖房隐瞒火灾史被拒收怎么办","房屋发生过火灾没告诉买家会怎样","隐瞒房屋火灾记录有什么风险"]},{"id":"OWN-DISPUTE-054","name":"业主卖房时房屋内有租客怎么避免买卖不破租赁纠纷？","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"买的二手房里面还有租客，原房东说买卖不破租赁，我该怎么办？","ola":"需取得租客放弃优先购买权声明，并向买家如实披露租约。","cp":["取得放弃优先购买权声明","核实租约真实性及期限","向买家书面披露租约","约定租金交割及押金转移"],"detail":"业主在房屋带租约状态下出售，受“买卖不破租赁”原则限制，买家需继续履行原租赁合同。若业主未提前取得租客放弃优先购买权的书面声明，或未向买家如实披露租约期限及租金支付情况，极易引发三方纠纷。经纪人需判断租约真实性及到期时间，核心决策因素是租客是否签署放弃优先购买权承诺书及买家是否接受带租约过户。","legalRef":"《中华人民共和国民法典》第七百二十五条规定，租赁物在承租人按照租赁合同占有期限内发生所有权变动的，不影响租赁合同的效力。第七百二十六条规定出租人出卖租赁房屋的，承租人享有以同等条件优先购买的权利。","consumerBenefit":"明确房屋租赁状态，避免过户后无法使用房屋或陷入租金纠纷。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["带租约卖房怎么避免纠纷","房子里有租客买家要求清退怎么办","买卖不破租赁业主怎么规避风险"]},{"id":"OWN-DISPUTE-055","name":"业主委托中介独家代理后私自卖房要承担什么违约责任？","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"房东签了独家代理又自己把房子卖了，中介找我要违约金怎么办？","ola":"构成违约，需按独家协议约定支付违约金或全额佣金。","cp":["核实独家协议有效期","确认是否利用中介资源","明确违约金计算标准","保留带看及沟通记录"],"detail":"业主与中介机构签订独家代理协议后，在委托期限内绕开中介私自与买家成交，或委托其他中介成交，构成违约。经纪人需判断独家协议的生效条件及违约条款是否清晰。关键决策因素在于业主是否实际利用中介提供的信息或资源（如带看记录），以及合同中关于“跳单”违约金的计算标准（通常为总房款的1%-2%或全额佣金）。","legalRef":"《中华人民共和国民法典》第九百六十五条规定，委托人在接受中介人的服务后，利用中介人提供的交易机会或者媒介服务，绕开中介人直接订立合同的，应当向中介人支付报酬。","consumerBenefit":"避免买家因业主违约被卷入与中介的纠纷，保障交易顺畅。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["签了独家代理又自己卖掉算违约吗","独家委托期间业主私自卖房怎么赔","跳过中介私下成交要交违约金吗"]},{"id":"OWN-DISPUTE-056","name":"业主卖房时隐瞒房屋存在违章建筑被要求退房怎么规避风险？","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"买的二手房发现有部分是违建，原房东没告诉我，我能要求退房吗？","ola":"隐瞒违建构成欺诈，需承担恢复原状、降价或退房赔偿。","cp":["核实产证面积与实际是否一致","查询是否被城管立案冻结","签约前书面披露违建情况","约定违建拆除责任及费用"],"detail":"房屋存在未经审批的扩建、改建等违章建筑，业主若隐瞒该事实，买家在过户或交房时发现，有权要求恢复原状、降价或解除合同。经纪人需判断违建是否影响产证面积及过户，核心决策因素是违建是否已被城管部门立案查处、是否冻结产权，以及买家对违建的接受程度。必须要求业主签署《房屋状况说明书》如实披露。","legalRef":"《中华人民共和国民法典》第一百四十八条规定，一方以欺诈手段，使对方在违背真实意思的情况下实施的民事法律行为，受欺诈方有权请求人民法院或者仲裁机构予以撤销。","consumerBenefit":"避免买到无法过户或被强制拆除的违建房屋，保障产权完整。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["房子有违建没告诉买家被要求退房怎么办","隐瞒房屋违建事实有什么法律风险","二手房带违建交易买家拒收怎么赔"]},{"id":"OWN-DISPUTE-065","name":"业主卖房时配偶未签字买家主张合同无效法律依据是什么？","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"房东配偶没签字，现在配偶跳出来说合同无效，我该怎么办？","ola":"配偶未签字不影响合同效力，但可能导致无法强制过户。","cp":["区分合同效力与物权变动","未签字不影响买卖合同有效","配偶拒追认可能导致无法过户","买家善意取得可主张继续履行"],"detail":"房屋属于夫妻共同财产，但仅有一方在买卖合同上签字，买家或配偶可能以此主张合同无效。经纪人需判断合同效力及物权变动规则。根据法律规定，买卖合同自成立时生效，配偶未签字不影响合同本身的效力；但若配偶拒绝追认且买家不构成善意取得，则无法强制过户。核心在于区分“债权行为（合同效力）”与“物权行为（过户效力）”。","legalRef":"《中华人民共和国民法典》第五百九十七条规定，因出卖人未取得处分权致使标的物所有权不能转移的，买受人可以解除合同并请求出卖人承担违约责任。《最高人民法院关于审理买卖合同纠纷案件适用法律问题的解释》第三条，当事人一方以出卖人在缔约时对标的物没有所有权或者处分权为由主张合同无效的，人民法院不予支持。","consumerBenefit":"明确共有房产签约的法律效力，保障买家交易安全。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["配偶没签字买卖合同有效吗","夫妻共有房产一方签字卖房法律依据","买家以配偶未签字主张合同无效的依据"]},{"id":"OWN-DISPUTE-066","name":"业主在抵押期间未经银行同意卖房合同是否有效？","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"房东的房子还有贷款没还清，没经银行同意就跟我签约了，合同有效吗？","ola":"合同有效，但过户需先解押或办理带押过户。","cp":["未经同意不影响合同效力","抵押权不受转让影响","过户需注销抵押或带押过户","无力解押需承担违约责任"],"detail":"业主在房屋存在银行按揭抵押的情况下，未经抵押权人（银行）同意，私自与买家签订买卖合同。经纪人需判断该合同效力。根据《民法典》新规，抵押期间抵押人可以转让抵押财产，未经同意不影响买卖合同效力，但抵押权不受影响。核心在于合同有效，但过户时需先注销抵押或办理“带押过户”，若银行不同意带押过户且业主无力解押，则面临违约风险。","legalRef":"《中华人民共和国民法典》第四百零六条规定，抵押期间，抵押人可以转让抵押财产。当事人另有约定的，按照其约定。抵押财产转让的，抵押权不受影响。","consumerBenefit":"明确抵押房交易的合同效力，避免买家因误解导致交易失败。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["房子有抵押没经银行同意能卖吗","抵押期间卖房合同有效吗法律依据","未经抵押权人同意卖房合同效力"]},{"id":"OWN-DISPUTE-068","name":"业主卖房时口头承诺送家具家电未写入合同有法律效力吗？","domain":"业主服务","subScene":"纠纷","scene":"业主服务·纠纷","cq":"房东看房时口头说家具都送我，现在交房反悔了，我能告他吗？","ola":"口头承诺有效但举证难，未写入合同极易产生纠纷。","cp":["口头承诺具备法律效力","未写入合同举证极其困难","需通过录音或聊天记录固证","所有赠送必须落实于书面合同"],"detail":"业主在带看或谈判时口头承诺将屋内家具家电赠送给买家，但未将其写入正式的买卖合同或补充协议中。交房时业主反悔，买家主张违约。经纪人需判断口头承诺的效力。根据法律规定，口头合同同样有效，但举证困难。若买家无法提供录音、微信聊天记录等证据证明口头承诺的存在，则难以获得法律支持。核心在于证据的固定与合同条款的完整性。","legalRef":"《中华人民共和国民法典》第四百六十九条规定，当事人订立合同，可以采用书面形式、口头形式或者其他形式。《中华人民共和国民事诉讼法》第六十七条规定，当事人对自己提出的主张，有责任提供证据。","consumerBenefit":"提醒买家将口头承诺书面化，避免交房时物品被搬空。","tags":{"clientType":["seller"],"stage":"post","layer":"术","meetingPhase":["见前","见中"]},"alias":["口头承诺送家具家电有效吗","卖房时口头答应的赠送没写进合同算数吗","业主口头承诺赠送物品法律效力"]},{"id":"OWN-OWN-CASE-060","name":"业主自住房屋存在私接燃气管线的情况，面临哪些安全和交易风险？","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"我家装修时私接了燃气管线，面临哪些安全和以后卖房的风险？","ola":"面临爆炸安全事故及燃气安检不合格无法交易的风险。","cp":["1.极易引发燃气泄漏爆炸","2.需承担刑事及民事赔偿责任","3.燃气安检不合格拒绝通气","4.影响房屋正常过户和交房"],"detail":"业务场景：业主在装修时，为改变厨房布局或增加用气点，私自聘请非专业人员改动、私接燃气管线。判断要点：燃气管线改动涉及公共安全，必须由燃气公司专业人员进行。关键决策因素：私接管线极易导致燃气泄漏，引发爆炸或中毒等严重安全事故，业主需承担刑事及民事责任；在房屋交易时，燃气公司安检若发现私接，将拒绝通气或要求整改，导致无法过户或交房；买家也可因此拒绝收房。","legalRef":"《城镇燃气管理条例》第二十八条（禁止擅自安装、改装、拆除户内燃气设施）、《中华人民共和国刑法》第一百一十四条（危害公共安全罪）","consumerBenefit":"认清私接燃气的严重危害，规范装修行为，保障生命财产安全及资产流动性。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["房子私接燃气管线有什么风险","自住房私自改动燃气管道面临哪些风险","房屋私接燃气影响以后卖房吗"]},{"id":"OWN-RNT-CASE-042","name":"出租屋热水器漏电致租客伤亡房东要担责吗","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"在出租屋洗澡时热水器漏电受伤，房东需要赔偿我的医药费吗？","ola":"业主未尽维修安检义务导致漏电伤人，需承担赔偿责任。","cp":["核实家电是否超期服役","确认业主是否尽到检修义务","排查租客是否存在违规操作","审查租赁合同中的安全条款"],"detail":"在出租屋安全管理中，因房屋附属设施（如热水器、燃气管线）老化漏电导致租客伤亡的案件频发。法院判决的核心在于业主是否尽到了安全保障和维修义务。若业主交付的房屋及设施存在安全隐患且未定期检修，或租客报修后业主未及时维修，业主需承担主要或全部赔偿责任；若租客违规使用或擅自改装导致，租客自担主责。","legalRef":"《中华人民共和国民法典》第一千一百九十八条（安全保障义务）及第一千一百六十五条（过错责任原则）。","consumerBenefit":"明确设施漏电的责任归属，保障租客的人身损害赔偿权益。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["出租屋电器漏电电死租客房东赔钱吗","租客在出租屋触电身亡房东有责任吗","房屋内设施漏电导致租客受伤房东怎么赔"]},{"id":"OWN-RNT-CASE-044","name":"中介隐瞒房屋漏水导致租客损失业主需要连带赔偿吗","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"中介瞒着房子漏水的情况租给我，导致我的家具被泡，我能同时起诉房东和中介要求连带赔偿吗？","ola":"业主若未尽告知义务或全权委托未免责，需连带赔偿。","cp":["核实业主是否向中介如实告知瑕疵","审查全权委托合同的免责条款","确认中介是否存在故意隐瞒行为","界定业主与中介的连带责任边界"],"detail":"在业主委托中介全权代理出租的业务中，若中介为促成交易故意隐瞒房屋漏水等瑕疵，导致租客财产受损。法院通常认定中介构成欺诈或违约，同时审查业主是否尽到如实告知义务。若业主明知漏水但未告知中介，或业主将房屋全权委托给中介且未进行房屋状况交接确认，法院可能判决业主与中介承担连带赔偿责任；若业主已明确告知中介且合同免责，业主可免责并向中介追偿。","legalRef":"《中华人民共和国民法典》第九百六十二条（中介人应当就有关订立合同的事项向委托人如实报告。中介人故意隐瞒与订立合同有关的重要事实或者提供虚假情况，损害委托人利益的，不得请求支付报酬并应当承担赔偿责任）。","consumerBenefit":"明确多方委托模式下的索赔对象，保障租客财产损失得到充分赔偿。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["中介隐瞒漏水租客索赔房东要连带赔偿吗","委托中介出租房屋漏水中介瞒报房东担责吗","中介隐瞒房屋瑕疵致租客损失业主有责任吗"]},{"id":"OWN-RNT-CASE-055","name":"业主将房屋租给租客做剧本杀店面临哪些消防合规风险","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"我想租你的房子开剧本杀店，你作为房东需要承担消防不合格被罚款的风险吗？","ola":"房屋性质及消防不达标，业主面临停业罚款及连带刑责。","cp":["核实房屋产权性质是否允许商业经营","审查消防通道及设施是否达标","明确租赁合同约定消防合规责任方","提示业主可能面临的行政及刑事风险"],"detail":"将住宅或普通商业用房出租给租客经营“剧本杀”店，面临极高的消防及合规风险。剧本杀店属于人员密集场所，对消防通道、喷淋系统、烟感报警有严格要求。若房屋性质为住宅，属于“居改非”，无法办理营业执照及消防审批；若为商业用房但消防不达标，业主作为产权人可能面临消防部门的停业整顿、高额罚款，甚至在发生火灾时承担连带刑事责任。经纪人必须提示业主核实房屋用途及消防资质。","legalRef":"《中华人民共和国消防法》第十五条（公众聚集场所投入使用、营业前消防安全检查）及第六十一条。","consumerBenefit":"揭示“居改非”及消防不合规的严重风险，防止业主因盲目出租面临行政处罚或刑事责任。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["出租房屋做剧本杀店房东有什么消防风险","把房子租给租客开剧本杀店有哪些合规隐患","住宅改剧本杀店业主面临哪些行政处罚风险"]},{"id":"OWN-RNT-CASE-056","name":"业主同意租客在阳台搭建阳光房面临哪些违建拆除风险","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"我想在租的房子阳台搭个阳光房，房东同意了，如果被城管查处，房东会被罚款吗？","ola":"属违建，业主面临罚款及房屋被冻结交易的风险。","cp":["未经审批搭建阳光房属违法建筑","行政处罚及冻结交易对象为产权人","合同约定无法对抗行政机关的处罚","合同中必须明确禁止擅自改建扩建"],"detail":"业主若同意或默许租客在阳台、露台搭建阳光房，面临极高的违建查处风险。根据城乡规划相关法规，未经审批搭建阳光房属于违法建筑。城管或物业查处后，不仅会责令限期拆除，还可能对产权人（业主）处以罚款，并将房屋列入冻结交易名单（限制买卖、抵押）。即使租赁合同约定由租客承担违建责任，行政处罚的对象仍是产权人。业主需坚决拒绝此类要求，并在合同中明确禁止擅自改建。","legalRef":"《中华人民共和国城乡规划法》第六十四条（未取得建设工程规划许可证或者未按照建设工程规划许可证的规定进行建设的处罚）。","consumerBenefit":"明确违建行为的行政处罚主体，防止业主因默许租客改建导致房屋被冻结或遭受罚款。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["租客在阳台搭阳光房房东有什么违建风险","同意租客封阳台建阳光房业主面临什么处罚","出租房阳台搭建阳光房被城管查处房东担责吗"]},{"id":"OWN-RNT-CASE-059","name":"业主将地下室出租给租客居住面临哪些行政处罚风险","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"我想租地下室住，房东把地下室租给我住，他会被城管或派出所罚款吗？","ola":"属违规行为，面临罚款、强制清退及潜在刑责。","cp":["地下室出租居住属严重违规行为","面临责令整改、高额罚款及强制清退","存在极大消防及卫生安全隐患","发生事故业主需承担刑事责任"],"detail":"将地下室、半地下室出租用于人员居住，属于严重的违规行为。根据各地房屋租赁及消防管理规定，地下空间不具备自然通风和采光条件，存在极大的消防及卫生安全隐患。一旦被街道、住建或公安部门查处，业主将面临责令限期改正、高额罚款，甚至被强制清退租客、断水断电。若发生重大安全事故，业主还将承担刑事责任。经纪人必须明确告知业主此类行为的违法性及严重后果。","legalRef":"《商品房屋租赁管理办法》第八条（出租住房的，应当以原设计的房间为最小出租单位，人均租住建筑面积不得低于当地人民政府规定的最低标准。厨房、卫生间、阳台和地下储藏室不得出租供人员居住）。","consumerBenefit":"明确地下空间出租居住的违法性质，防止业主因贪图租金面临行政处罚及房屋被查封清退。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["把地下室租给人住房东会被罚款吗","出租地下室居住业主面临哪些行政处罚","地下室住人房东被查处有什么后果"]},{"id":"OWN-RNT-CASE-060","name":"出租屋留贵重家具未拍照留存退租时面临哪些举证风险","domain":"业主资产","subScene":"出租","scene":"业主资产·出租","cq":"房东在房子里留了很贵的实木家具，但交房时没拍照，退租时弄坏了我要全额赔吗？","ola":"未拍照留存证据，退租时面临举证不能及索赔失败风险。","cp":["交房时必须对贵重物品拍照录像","在交接单中明确记录品牌型号及现状","未留存证据退租时面临举证不能风险","无法证明原状及价值将自行承担损失"],"detail":"业主在出租屋内留下高档家具、家电等贵重物品，若在交房时未进行详细的拍照、录像留存，也未在《房屋物品交接单》中明确记录品牌、型号及现状，退租时若发生损坏或丢失，将面临极大的举证困难。根据“谁主张谁举证”原则，业主无法证明物品交付时的状况及价值，法院或仲裁机构将难以支持其索赔诉求，最终只能由业主自行承担损失。经纪人必须在交房环节强制要求双方完成物品现状确认。","legalRef":"《中华人民共和国民事诉讼法》第六十七条（当事人对自己提出的主张，有责任提供证据）。","consumerBenefit":"强调交房物品交接的取证重要性，保障业主在退租时对贵重物品损坏的合法索赔权益。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["出租房留有贵重家具没拍照退租怎么索赔","业主没给出租屋贵重家具拍照退租时怎么举证","退租时贵重家具损坏房东没拍照怎么让租客赔"]},{"id":"OWN-SLD-CASE-042","name":"中介隐瞒真实售价私自吃差价业主能起诉追回吗","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"中介瞒着房东多收了我的钱，我能要回来吗？","ola":"中介隐瞒售价吃差价属欺诈，业主可起诉追回。","cp":["中介吃差价构成欺诈","违反居间忠实义务","业主可主张退还差价","面临退一赔三处罚"],"detail":"业务场景：中介利用信息差，向业主隐瞒真实成交价，将买家多付的房款私自截留作为差价。判断要点：此行为严重违反居间合同忠实义务，构成欺诈。关键决策因素：业主是否掌握真实交易价格证据、中介是否存在阴阳合同、资金流向是否清晰。经纪人应坚守职业道德，严禁此类行为，否则面临退一赔三及行政处罚。","legalRef":"《中华人民共和国民法典》第九百六十二条，中介人应当就有关订立合同的事项向委托人如实报告。中介人故意隐瞒与订立合同有关的重要事实或者提供虚假情况，损害委托人利益的，不得请求支付报酬并应当承担赔偿责任。","consumerBenefit":"维护交易公平，保障业主应得售房款。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["中介吃差价业主起诉","中介隐瞒买家多收房款","房产中介赚取房屋差价"]},{"id":"OWN-SLD-CASE-047","name":"业主卖房时租客主张优先购买权卖家必须卖给租客吗","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"房子有租客，租客非要买，我能卖给其他人吗？","ola":"租客有优先购买权，但需在15日内按同等条件购买。","cp":["租客享有法定优先购买权","需在15日内明确表态","必须接受同等交易条件","逾期未表态视为放弃"],"detail":"业务场景：房屋处于出租状态，业主准备出售，租客得知后主张优先购买权，要求以同等条件购买该房屋。判断要点：租客享有法定优先购买权，但需满足特定条件。关键决策因素：租客是否在合理期限内明确表示购买、是否接受同等交易条件、房屋是否按份共有人购买。若租客放弃或逾期未表态，卖家可卖给第三方。","legalRef":"《中华人民共和国民法典》第七百二十六条，出租人出卖租赁房屋的，应当在出卖之前的合理期限内通知承租人，承租人享有以同等条件优先购买的权利；但是，房屋按份共有人行使优先购买权或者出租人将房屋出卖给近亲属的除外。","consumerBenefit":"保障承租人合法权益，维护交易秩序。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["卖房租客要买怎么办","租客主张优先购买权条件","带租约卖房租客优先买"]},{"id":"OWN-SLD-CASE-048","name":"卖家签订卖房意向书后反悔不签正式合同要承担缔约过失责任吗","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"签了意向书交了钱，房东突然不卖了，能要求赔偿吗？","ola":"卖家恶意反悔不签正式合同，需承担缔约过失责任。","cp":["意向书属预约合同性质","恶意反悔承担缔约过失","需赔偿信赖利益损失","意向金应当双倍返还或赔偿"],"detail":"业务场景：买卖双方及中介签订了购房意向书并支付了意向金，但卖家随后反悔，拒绝签订正式的房屋买卖合同。买家要求退还意向金并赔偿损失。判断要点：意向书属于预约合同，若具备本约核心条款可视为本约。关键决策因素：意向书内容是否具备买卖合同核心要素、卖家反悔是否有正当理由、买家是否产生信赖利益损失。卖家恶意磋商需承担缔约过失责任。","legalRef":"《中华人民共和国民法典》第五百条，当事人在订立合同过程中有下列情形之一，造成对方损失的，应当承担赔偿责任：（一）假借订立合同，恶意进行磋商；（二）故意隐瞒与订立合同有关的重要事实或者提供虚假情况；（三）有其他违背诚信原则的行为。","consumerBenefit":"约束恶意磋商行为，保障交易诚意。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["意向书反悔缔约过失","签了意向书不签买卖合同","卖房意向书违约赔偿"]},{"id":"OWN-SLD-CASE-050","name":"业主卖房时如何核实买家的购房资格和贷款能力","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"怎么确认自己有没有买房资格和贷款额度？","ola":"通过核验购房资格、查征信和收入流水来确认。","cp":["核验买家当地购房资格","审查买家个人征信报告","确认收入流水覆盖月供","在合同中约定资质不符解约条款"],"detail":"业务场景：业主在签订卖房合同前，担心买家没有购房资格或贷款批不下来导致交易失败。判断要点：提前核实资质可大幅降低违约风险。关键决策因素：买家社保或个税缴纳情况、征信报告是否良好、收入流水是否覆盖月供。经纪人需指导买家提前拉取征信和购房资格核验，业主需审查相关证明。","legalRef":"各地房地产限购政策及银行个人住房贷款管理办法。","consumerBenefit":"降低交易违约风险，提高过户成功率。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["核实买家购房资格","怎么查买家贷款能力","卖房前审查买家资质"]},{"id":"OWN-SLD-CASE-052","name":"业主卖房时如何办理房屋核验和网签备案手续","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"二手房网签和房源核验是怎么办理的？","ola":"先申请房源核验获取编码，再核对信息完成网签。","cp":["通过建委系统申请房源核验","获取核验编码及二维码","核对网签信息确保与合同一致","双方签字确认完成网签备案"],"detail":"业务场景：业主在挂牌出售或签订买卖合同后，需要办理房源核验和网签备案，以确保房屋产权清晰并锁定交易。判断要点：房源核验是网签的前置条件，网签是过户的必经程序。关键决策因素：房屋是否存在查封或抵押等限制、核验编码是否有效、网签信息是否与合同一致。经纪人需协助业主通过建委系统或窗口提交申请。","legalRef":"《房地产经纪管理办法》第二十二条，房地产经纪机构与委托人签订房屋出售、出租经纪服务合同，应当查看委托出售、出租的房屋及房屋权属证书。","consumerBenefit":"保障房源真实性，锁定交易防止一房二卖。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["房源核验怎么办理","二手房网签备案流程","卖房房源核验步骤"]},{"id":"OWN-SLD-CASE-059","name":"业主卖房时同意买家使用经营贷或消费贷付首付有什么风险","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"我用经营贷凑首付，卖家会有什么风险吗？","ola":"存在银行抽贷致交易失败及业主被牵连的风险。","cp":["银行严查首付资金来源","违规抽贷致买家资金断裂","交易失败业主面临解约纠纷","严禁配合买家做假流水"],"detail":"业务场景：买家因首付资金不足，违规使用经营贷或消费贷凑齐首付支付给业主。判断要点：此举违反监管规定，一旦银行抽贷，买家资金链断裂将导致交易失败。关键决策因素：银行严查首付资金来源，若发现违规将拒贷或要求提前还款；买家被抽贷后无力支付尾款，业主面临过户延期或解约纠纷；业主若配合做假流水，可能承担连带责任。","legalRef":"《中国银保监会办公厅 住房和城乡建设部办公厅 中国人民银行办公厅关于防止经营用途贷款违规流入房地产领域的通知》（银保监办发〔2021〕39号）。","consumerBenefit":"防范交易中断风险，保障业主顺利收款。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["买家经营贷付首付风险","消费贷买房有什么风险","买家违规贷款付首付"]},{"id":"OWN-VAL-CASE-041","name":"业主如何根据同小区历史成交底价反推当前合理挂牌价","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"买家问：这个小区的底价大概是多少？","ola":"参考近三月真实成交底价，结合房源差异修正后上浮挂牌。","cp":["剔除极端高低成交价","计算近三月加权均价","结合楼层朝向做修正","根据急售程度上浮3%"],"detail":"在二手房出售场景中，业主常需参考同小区历史成交数据来制定挂牌价。判断要点在于区分“挂牌价”与“真实底价”，历史成交价需结合当前市场供需、楼层朝向差异及装修折旧进行修正。关键决策因素包括近3个月同户型真实成交均价、小区带看转化率及竞品房源挂牌量。经纪人需协助业主剔除极端高价和急售低价，计算加权平均底价，再根据业主售房急迫程度上浮3%-5%作为初始挂牌价，避免脱离市场。","legalRef":"行业常规操作指引","consumerBenefit":"帮助买家了解真实市场底价，避免被虚高挂牌价误导。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["怎么查同小区历史底价","如何参考历史成交价定价","历史成交数据怎么算挂牌价"]},{"id":"OWN-VAL-CASE-046","name":"业主委托多家中介挂牌时如何制定差异化估值策略避免砸盘","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"买家问：这房子怎么好几家中介报的价格都不一样？","ola":"统一对外挂牌价与内部底价，对主力中介给价格保护防砸盘。","cp":["设定统一对外挂牌价","明确各中介内部底价","对主力中介给价格保护","避免网络低价信息踩踏"],"detail":"业主为扩大客源常将房屋委托给多家中介挂牌，但易因各中介为抢客源而恶意压低挂牌价导致“砸盘”。判断要点在于建立统一的价格底线，并对不同渠道实施差异化展示。关键决策因素包括业主的真实底价、各中介的客源质量及主推力度。经纪人应建议业主设定统一的“对外挂牌价”和“内部底价”，对主力合作中介给予一定价格保护或独家激励；同时要求所有渠道对外展示价格一致，避免低价信息在网络上互相踩踏，损害房屋整体估值形象。","legalRef":"《房地产经纪管理办法》第二十一条（房地产经纪机构不得隐瞒真实情况）","consumerBenefit":"帮助买家获取真实统一的房源价格信息，避免被虚假低价引流套路。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["多家中介挂牌怎么定价","怎么避免多家中介砸盘","委托多家中介估值策略"]},{"id":"OWN-VAL-CASE-047","name":"业主将房屋估值完全依赖某一家中介的独家高评估会面临什么风险","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"买家问：这房子挂这么高，业主是不是不想卖？","ola":"警惕无数据支撑的高估值，避免房屋长期滞销错失出售时机。","cp":["警惕无数据支撑口头高估","识别中介高评估真实动机","对比近期真实成交偏离度","避免错失最佳出售窗口"],"detail":"部分中介为获取独家委托或促成交易，会向业主提供远高于市场实际成交价的“高评估”。业主若完全依赖此单一高评估，将面临房屋长期滞销、错失最佳出售窗口的风险。判断要点在于识别中介高评估的动机（如骗取独家、掩盖房屋瑕疵或后续压价）。关键决策因素包括该评估价与同小区近期真实成交价的偏离度、中介是否提供书面承诺及违约赔偿条款。业主需警惕无数据支撑的口头高估值，避免因期望过高而拒绝合理议价，最终在时间成本压..","legalRef":"《中华人民共和国民法典》第九百六十二条（中介人故意隐瞒重要事实的赔偿责任）","consumerBenefit":"帮助买家识别虚高挂牌价背后的真实出售意愿，避免无效看房。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["依赖中介独家高评估有什么风险","中介高评估有什么坑","只听一家中介估值会怎样"]},{"id":"OWN-VAL-CASE-055","name":"业主与中介签订保底估值出售协议在法律上是否有效","domain":"业主资产","subScene":"保值","scene":"业主资产·保值","cq":"买家问：中介承诺保底估值，这房子价格是不是稳了？","ola":"真实意思表示通常有效，但需警惕中介无收购能力及恶意压价风险。","cp":["真实意思表示通常有效","警惕中介利用优势地位","无收购能力协议沦为空头","恶意压价可主张条款无效"],"detail":"业主为规避市场下跌风险，常要求与中介签订“保底估值出售协议”，约定若房屋低于某价格未售出，中介需补足差价或按保底价收购。判断要点在于该协议是否违反中介合同的居间/委托本质及是否存在利益冲突。关键决策因素包括协议具体条款、中介是否具备收购资质、以及是否存在欺诈或显失公平情形。根据《民法典》，若协议为双方真实意思表示且不违反强制性规定，通常有效。但若中介利用优势地位诱导业主签订，或后续以“保底”为..","legalRef":"《中华人民共和国民法典》第九百六十一条（中介合同定义）及第四百九十七条（格式条款无效情形）","consumerBenefit":"帮助买家了解中介保底承诺的法律实质，避免被虚假承诺误导。","tags":{"clientType":["seller","landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["保底估值出售协议有效吗","中介承诺保底估值合法吗","保底出售协议法律效力"]},{"id":"OWN-AST-CASE-017","name":"中介私自改变房屋用途导致被查封业主能索赔吗","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"中介私自改变房屋用途导致房屋被查封，房东能索赔吗？","ola":"中介擅自改用途属根本违约，业主可索赔租金损失及房屋贬值。","cp":["审查托管合同用途约定","中介擅自改用途属违约","可主张解除合同及赔偿","索赔含房屋贬值及租金损失","需保全中介违规证据"],"detail":"业主将房屋全权委托给中介或托管机构，若机构私自改变房屋用途（如住宅改商用、违规群租、甚至从事违法活动）导致房屋被查封或受损，业主有权索赔。判断关键在于委托合同中的权限约定及中介的违约/侵权行为。若合同明确禁止改变用途，中介构成根本违约，业主可要求解除合同、赔偿房屋贬值及查封期间的租金损失。经纪人应提示业主在托管合同中明确违约责任和用途限制条款。","legalRef":"《中华人民共和国民法典》第九百二十九条（受托人过错造成损失应赔偿）","consumerBenefit":"明确全权托管下的违约追责路径，保障资产安全与收益。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["托管中介违规改变用途房屋被查封怎么索赔","全权委托中介乱用房子被查封房东能要赔偿吗","中介擅自改变房屋用途被查封业主维权案例"]},{"id":"OWN-AST-CASE-019","name":"业主卖房未告知严重噪音租客要求解约赔偿法院怎么判","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"租的房子有严重噪音房东没告诉我，我要求退租赔偿法院怎么判？","ola":"隐瞒严重影响居住的噪音瑕疵，法院支持租客解约及索赔。","cp":["噪音需达严重影响居住程度","业主负有瑕疵告知义务","隐瞒严重噪音构成违约或欺诈","租客有权要求解约并索赔","需专业机构出具噪音检测报告"],"detail":"业主在出售或出租房屋时，若故意隐瞒房屋存在的严重噪音（如临近高架桥、工厂、设备层等）问题，租客事后发现并要求解除合同及赔偿，法院通常会支持租客。判断要点在于噪音是否达到“严重影响正常居住使用”的程度，以及业主是否履行了如实告知义务。若噪音超出国家声环境质量标准，且业主未告知，构成欺诈或根本违约。经纪人应提示业主如实披露房屋瑕疵，避免后续解约及赔偿风险。","legalRef":"《中华人民共和国民法典》第一百四十八条（欺诈撤销权）及第七百二十四条（租赁物危及安全健康）","consumerBenefit":"明确房屋瑕疵披露义务，降低因隐瞒噪音导致的解约赔偿风险。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["房东卖房隐瞒严重噪音租客退租索赔法院怎么判","出租房存在严重噪音房东未告知租客解约判例","租客入住后发现严重噪音要求房东赔偿法院支持吗"]},{"id":"OWN-AST-CASE-033","name":"业主将房屋租给多人合租群租面临哪些行政处罚和清退风险","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"业主将房屋租给多人合租（群租），面临哪些行政处罚和清退风险？","ola":"面临责令整改、高额罚款、强制清退及重大安全事故刑责。","cp":["面临责令限期改正及恢复原状","面临数千至数万元高额罚款","拒不整改将被强制清退及断水电","发生事故需承担重大刑事民事责任","严禁协助业主进行违规群租操作"],"detail":"业主将房屋违规群租（如打隔断、改变房屋结构、人均面积低于标准、居住人数超标），面临严厉的行政处罚和清退风险。风险点包括：1. 被城管、住建或公安部门责令限期改正，恢复原状；2. 面临高额罚款（各地标准不同，通常数千至数万元不等）；3. 若拒不整改，将被强制清退租客并断水断电；4. 若群租期间发生火灾等安全事故，业主需承担重大刑事及民事赔偿责任。经纪人应严禁协助业主进行违规群租操作。","legalRef":"《商品房屋租赁管理办法》第八条（出租住房应以原设计房间为最小出租单位，人均租住建筑面积不得低于当地最低标准）及各地房屋租赁条例。","consumerBenefit":"明确群租违法成本，警示业主合规出租，避免重大财产及人身风险。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前"]},"alias":["房屋群租房东面临哪些处罚和清退风险","出租房群租业主会被行政处罚吗","房东把房子租给多人群租有什么风险"]},{"id":"OWN-AST-CASE-034","name":"业主在租赁合同中约定房屋内发生任何安全事故房东概不负责该条款有法律效力吗","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"我在合同里写了“屋内发生任何安全事故房东概不负责”，这有法律效力吗？","ola":"造成人身损害的免责条款无效，无法免除房东法定安全责任。","cp":["造成人身损害的免责条款无效","无法免除房东法定安全保障义务","房屋设施缺陷导致事故房东仍需担责","免责条款不能对抗法定侵权责任","建议购买出租屋责任险转移风险"],"detail":"业主在租赁合同中约定“房屋内发生任何安全事故房东概不负责”，该条款通常被认定为无效。风险点在于：根据法律规定，造成对方人身损害的免责条款无效。若安全事故（如火灾、触电、坠物）是由于房屋本身设施缺陷、房东未尽维修义务或未履行安全提示义务导致的，房东必须承担相应的侵权或违约责任，不能通过格式条款免除。经纪人需提示业主，免责条款无法对抗法定安全保障义务，应通过购买出租屋责任险转移风险。","legalRef":"《中华人民共和国民法典》第五百零六条（合同中的下列免责条款无效：（一）造成对方人身损害的）","consumerBenefit":"破除“免责条款万能”的误区，提示业主依法履行安全保障义务。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["合同约定安全事故房东概不负责有效吗","租赁合同免责条款房东不担责有法律效力吗","房东约定屋内事故概不负责条款合法吗"]},{"id":"OWN-AST-CASE-035","name":"租客利用出租屋注册公司退租后未迁出地址对业主后续出租或出售有何风险","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"租客用我的房子注册公司，退租后不迁出地址，对我后续出租或出售有什么风险？","ola":"导致地址被锁定影响出租，原公司涉诉可能牵连房屋被查封。","cp":["地址被锁定影响新租客注册","原公司涉诉可能导致房屋被查封","影响房屋出售交易及评估价值","强制迁出地址流程繁琐耗时","需在合同中约定地址迁出违约金"],"detail":"租客利用出租屋注册公司，退租后未迁出地址，对业主后续出租或出售存在显著风险。风险点包括：1. 该地址被工商部门锁定，新租客无法使用该地址注册公司，影响房屋商业价值及出租率；2. 若原租客公司存在债务纠纷、被列入异常经营名录或涉诉，可能导致房屋被法院查封或影响业主个人征信；3. 在房屋出售时，买家可能因地址被占用而拒绝交易或要求大幅降价；4. 强制迁出地址需通过行政诉讼或协调市监局，流程繁琐且耗时。","legalRef":"《中华人民共和国民法典》第一百七十六条","consumerBenefit":"明确注册地址未迁出的潜在风险，提示业主在合同中增设约束条款。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见后"]},"alias":["租客注册公司退租未迁出地址有什么风险","出租屋被注册公司租客搬走不迁地址的风险","租客退租未迁出工商注册地址对房东的影响"]},{"id":"OWN-AST-CASE-037","name":"租客在屋内使用大功率电器引发火灾业主若未尽到消防提示义务需承担什么责任","domain":"资产持有与运营","subScene":"资产运营","scene":"资产持有与运营·资产运营","cq":"租客在屋里用大功率电器引发火灾，我没尽到消防提示义务，需承担什么责任？","ola":"未尽提示及安全保障义务，需承担财产赔偿甚至刑事责任。","cp":["线路老化或未配灭火器需担责","未书面提示安全用电认定有过错","需赔偿邻居及租客财产损失","造成人员伤亡可能追究刑事责任","建议配备消防器材并签署安全承诺书"],"detail":"租客在屋内使用大功率电器引发火灾，若业主未尽到消防提示及安全保障义务，需承担相应的民事赔偿甚至刑事责任。风险点在于：1. 若房屋原有线路老化、未配备合格漏电保护器或灭火器，业主需对火灾损失承担次要或主要赔偿责任；2. 若业主未向租客书面提示安全用电规范，在民事诉讼中会被认定存在过错，需赔偿邻居及租客的财产损失；3. 若火灾造成人员重伤或死亡，业主可能因涉嫌消防责任事故罪被追究刑事责任。","legalRef":"《中华人民共和国消防法》及《中华人民共和国民法典》第一千一百六十五条（过错侵权责任）","consumerBenefit":"明确消防提示义务的法律边界，提示业主完善安全设施以规避重大责任。","tags":{"clientType":["landlord"],"stage":"post","layer":"器","meetingPhase":["见前","见中"]},"alias":["租客用大功率电器引发火灾房东未尽提示义务担什么责","出租屋火灾房东未尽消防提示义务需承担什么责任","租客使用电器引发火灾房东未提示要担责吗"]},{"id":"OWN-SEL-DEEP-001","name":"独家委托到期中介不让解约怎么办","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"独家委托到期了中介说不能解约，房东该怎么办？","ola":"到期即终止，书面通知即可。","cp":["告诉业主","独家委托到期后自动终止","中介无权强制续签","提醒业主检查合同是否含自动续约条款","如有可主张无效"],"detail":"本词条涉及出售决策领域的PROC类问题。告诉业主：独家委托到期后自动终止，中介无权强制续签。提醒业主检查合同是否含自动续约条款，如有可主张无效。帮业主准备书面解约通知留存证据。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第九百六十六条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["独家委托到期中介不让解约怎么办","独家委托到期中介不让解约怎么处理","独家委托到期中介不让解约如何应对"]},{"id":"OWN-SEL-DEEP-004","name":"满五唯一卖房能省多少税怎么认定","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"满五唯一卖房能省多少税？怎么才算满五唯一？（从租客/买家角度）","ola":"可免个税1%-20%，家庭唯一住房是关键。","cp":["告诉业主","满五唯一可免个人所得税(总价的1%或.…","提醒业主三个认定标准","1.房产证满5年(以登记日期为准) .…","帮业主提前核实房产证日期和家庭住房套数"],"detail":"本词条涉及出售决策领域的LAW类问题。告诉业主：满五唯一可免个人所得税(总价的1%或差额的20%)。提醒业主三个认定标准：1.房产证满5年(以登记日期为准) 2.是家庭省内唯一住房 3.夫妻双方名下都算。帮业主提前核实房产证日期和家庭住房套数。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第五百九十五条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["满五唯一卖房能省多少税怎么认定","满五唯一卖房能省多少税如何认定","满五唯一卖房能省多少税怎样认定"]},{"id":"OWN-SEL-DEEP-005","name":"卖房税费买卖双方怎么分担才能合法又合理","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"卖房税费到底谁承担？中介说全由买家出，靠谱吗？（从租客/买家角度）","ola":"法律归卖方，惯例归买方，合同必须写明。","cp":["告诉业主","法定纳税义务人和实际承担方可以不同—.…","买方交契税","但实践中多数由买方承担全部税费","提醒业主"],"detail":"本词条涉及出售决策领域的LAW类问题。告诉业主：法定纳税义务人和实际承担方可以不同——法律规定卖方交增值税和个税，买方交契税，但实践中多数由买方承担全部税费。提醒业主：净得价和含税价要分清，合同中必须写明税费承担方式。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第五百六十三条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["卖房税费买卖双方怎么分担才能合法又合理","卖房税费买卖双方如何分担才能合法又合理","卖房税费买卖双方怎样分担才能合法又合理"]},{"id":"OWN-SEL-DEEP-007","name":"急售房产折价多少合理怎么避免被压价","domain":"资产持有与运营","subScene":"出售决策","scene":"资产持有与运营·出售决策","cq":"房东急需用钱要急售房产，折价多少合理？怎么避免被压价？","ola":"合理折价5%-10%，超15%即被压价。","cp":["帮业主理性评估急售折价幅度","正常市场急售折价5%-10%合理","超过15%属于被压价","建议业主用三条底线","1.不低于同小区最近成交价下浮10%.…"],"detail":"本词条涉及出售决策领域的RISK类问题。帮业主理性评估急售折价幅度：正常市场急售折价5%-10%合理，超过15%属于被压价。建议业主用三条底线：1.不低于同小区最近成交价下浮10% 2.不低于剩余贷款额 3.不低于业主心理底价。提醒业主不要被中介以'急售'为由恶意压价。。该问题属于medium级别，涉及行业规范标准。","legalRef":"《中华人民共和国民法典》相关条文","consumerBenefit":"掌握规范操作流程，降低风险。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["急售房产折价多少合理如何避免被压价","急售房产折价多少合理怎样避免被压价","急售房产折价多少合理怎么避免被压价"]},{"id":"OWN-OWN-DEEP-002","name":"代持房产被代持人私自称自己所有怎么办","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东找人代持的房子，代持人说房子是他的，怎么办？","ola":"持代持协议+出资凭证起诉确权。","cp":["告诉业主","代持房产的法律风险极高——房产证上的.…","对外以登记为准","如果代持人私自称房子是自己的","业主需要1.收集代持协议和出资凭证 .…"],"detail":"本词条涉及权属维护领域的RISK类问题。告诉业主：代持房产的法律风险极高——房产证上的名字是代持人，对外以登记为准。如果代持人私自称房子是自己的，业主需要1.收集代持协议和出资凭证 2.向法院提起确权诉讼 3.申请财产保全防止代持人卖房。提醒业主：代持协议务必书面+公证。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第二百三十四条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["代持房产被代持人私自称自己所有怎么办","代持房产被代持人私自称自己所有怎么处理","代持房产被代持人私自称自己所有如何应对"]},{"id":"OWN-OWN-DEEP-004","name":"邻居违建影响我家采光通风怎么维权","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"邻居违建挡了房东家采光，怎么维权？能让他拆吗？","ola":"举报城管→起诉相邻权→判拆+赔偿。","cp":["告诉业主维权路径","1.拍照录像固定证据 2.向城管/规.…","提醒业主","相邻权纠纷诉讼时效3年","越早维权越好"],"detail":"本词条涉及权属维护领域的PROC类问题。告诉业主维权路径：1.拍照录像固定证据 2.向城管/规划部门举报违建 3.举报无果可向法院起诉相邻权纠纷 4.要求拆除违建+赔偿损失。提醒业主：相邻权纠纷诉讼时效3年，越早维权越好。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第二百九十三条、第二百八十八条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["邻居违建影响我家采光通风怎样维权","邻居违建影响我家采光通风怎么维权","邻居违建影响我家采光通风如何维权"]},{"id":"OWN-OWN-DEEP-008","name":"房子被亲戚强占不还怎么合法要回","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"亲戚占着房东的房子不肯搬走，怎么合法要回来？","ola":"律师函→起诉返还原物→强制执行。","cp":["告诉业主合法要回路径","1.发律师函正式要求搬离 2.报警(.…","提醒业主","1.保留房产证等权属证明 2.不要自.…"],"detail":"本词条涉及权属维护领域的PROC类问题。告诉业主合法要回路径：1.发律师函正式要求搬离 2.报警(但警方多按民事纠纷处理) 3.向法院起诉返还原物 4.申请法院强制执行。提醒业主：1.保留房产证等权属证明 2.不要自行换锁断电——可能构成侵权 3.诉讼时效3年。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第二百三十五条、第二百三十六条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["房子被亲戚强占不还如何合法要回","房子被亲戚强占不还怎样合法要回","房子被亲戚强占不还怎么合法要回"]},{"id":"OWN-OWN-DEEP-012","name":"违建被举报后必须自拆吗怎么处理损失最小","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东家违建被举报了，必须自己拆吗？怎么处理损失最小？","ola":"主动自拆免罚款，被强拆加罚+征信影响。","cp":["告诉业主处理路径","1.城管下达限期拆除通知书→可申请听.…","损失最小方案","主动自拆>被强拆(免罚款+保住合法部.…","帮业主评估违建部分和合法部分的界限"],"detail":"本词条涉及权属维护领域的PROC类问题。告诉业主处理路径：1.城管下达限期拆除通知书→可申请听证 2.逾期不拆→城管强拆+罚款 3.自拆可免罚款。损失最小方案：主动自拆>被强拆(免罚款+保住合法部分+不影响征信)。帮业主评估违建部分和合法部分的界限。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国城乡规划法》第六十四条、第六十八条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["违建被举报后必须自拆吗如何处理损失最小","违建被举报后必须自拆吗怎样处理损失最小","违建被举报后必须自拆吗怎么处理损失最小"]},{"id":"OWN-RNT-DEEP-002","name":"租客把房子弄坏了押金不够赔怎么追偿","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"房东说我弄坏了房子要赔超押金的部分，合理吗？","ola":"押金优先扣，不足部分协商或起诉追偿。","cp":["告诉业主追偿路径","提醒业主","入住时必须做物品交接清单并拍照存档"],"detail":"本词条涉及出租管理领域的PROC类问题。告诉业主追偿路径：1.入住时拍摄房屋状况视频/照片做证据 2.退租时比对损坏情况 3.押金优先扣 4.押金不足的部分→先协商→协商不成可起诉索赔。提醒业主：入住时必须做物品交接清单并拍照存档。。该问题属于hard级别，涉及法律强制性规定。","legalRef":"《中华人民共和国民法典》第七百一十一条","consumerBenefit":"了解法律底线，避免权益受损。","tags":{"clientType":["landlord","seller"],"stage":"post","layer":"法","meetingPhase":["见前","见中","见后"]},"alias":["租客弄坏房子押金不够赔怎么追偿","房屋损坏押金不足追偿","租客损坏超押金怎么索赔"]},{"id":"OWN-CASE-VAL-001","name":"代持人私自卖房实际出资人如何追回","domain":"资产持有与运营","subScene":"权属维护","scene":"资产持有与运营·权属维护","cq":"房东的代持人把房子卖了，我买的房会被追回吗？","ola":"善意买家受保护，只能追偿不能追房。","cp":["善意第三人取得产权","代持人无权处分但买家受保护","实际出资人只能追偿不能追房","代持风险极大"],"detail":"张某出资购买房屋登记在李某名下，签订书面代持协议。后李某未经张某同意将房屋出售给王某，王某不知情且支付合理对价并完成过户。张某起诉要求确认买卖合同无效，法院认定王某构成善意取得，驳回张某诉请。张某只能向李某追偿卖房款。","legalRef":"《中华人民共和国民法典》第三百一十一条","consumerBenefit":"了解法院裁判规则，预判维权结果。","tags":{"clientType":["landlord","seller","tenant"],"stage":"post","layer":"器","meetingPhase":["见前","见中","见后"]},"alias":["代持人私自卖房实际出资人如何追回","怎么应对代持人私自卖房实际出","代持人私自卖房实怎么办"]},{"id":"OWN-CASE-RNT-001","name":"租客拖欠租金6个月房东起诉解除合同胜诉案例","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"房东因为我欠租起诉解约，法院会怎么判？","ola":"催告后不付租可解约，追回租金+违约金。","cp":["催告后仍不付租可解约","书面催告是必要程序","拖欠租金+违约金一并追偿","腾退期限由法院确定"],"detail":"房东周某将房屋出租给田某，月租3000元。田某连续6个月未交租金，周某多次催告无果后发书面解除通知并起诉。法院认定田某经催告后仍未付租，周某有权解除合同，判决合同解除、田某限期腾退并支付拖欠租金18000元及违约金3000元。","legalRef":"《中华人民共和国民法典》第七百二十二条","consumerBenefit":"了解法院裁判规则，预判维权结果。","tags":{"clientType":["landlord","seller","tenant"],"stage":"post","layer":"器","meetingPhase":["见前","见中","见后"]},"alias":["租客拖欠租金6个月房东起诉解除合同胜诉案例","租客拖欠租金6个月房东起诉解除合同胜诉判例","租客拖欠租金6个月房东起诉解除合同胜诉"]},{"id":"OWN-CASE-RNT-003","name":"房东断水断电逼租客搬走被判赔偿案例","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"房东断水断电逼我搬走，能索赔吗？","ola":"断水断电构成侵权，判赔6000元。","cp":["断水断电构成侵权","暴力清退要赔偿损失","维权应走法律程序","租金和侵权分别处理"],"detail":"房东钱某因租客孙某拖欠2个月租金，采取断水断电方式逼迫孙某搬走。孙某起诉钱某侵权，要求赔偿因断水断电造成的损失(冰箱食物腐坏、无法正常居住期间酒店费)共计8000元。法院认定钱某断水断电构成侵权，判决赔偿孙某6000元。同时孙某仍需支付拖欠租金。","legalRef":"《中华人民共和国民法典》第一千一百六十五条","consumerBenefit":"了解法院裁判规则，预判维权结果。","tags":{"clientType":["landlord","seller","tenant"],"stage":"post","layer":"器","meetingPhase":["见前","见中","见后"]},"alias":["房东断水断电逼租客搬走被判赔偿判例","房东断水断电逼租客搬走被判赔偿","房东断水断电逼租客搬走被判赔偿案例"]},{"id":"OWN-CASE-RNT-004","name":"二房东跑路房东起诉租客腾退胜诉案例","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"二房东跑路了，房东让我搬走，我有权住吗？","ola":"未经同意转租无效，可起诉要求腾退。","cp":["未经同意转租无效","租客需腾退房屋","租客损失向二房东追","签合同时约定转租条款"],"detail":"房东冯某将房屋出租给中介公司(二房东)，中介公司转租给多个租客后跑路。冯某起诉要求租客腾退。法院认定：冯某与中介公司签的是租赁合同，中介公司转租未经冯某书面同意，转租合同无效。判决租客限期腾退，租客损失另案向中介公司追偿。","legalRef":"《中华人民共和国民法典》第七百一十六条","consumerBenefit":"了解法院裁判规则，预判维权结果。","tags":{"clientType":["landlord","seller","tenant"],"stage":"post","layer":"器","meetingPhase":["见前","见中","见后"]},"alias":["二房东跑路房东起诉租客腾退胜诉判例","二房东跑路房东起诉租客腾退胜诉","二房东跑路房东起诉租客腾退胜诉案例"]},{"id":"OWN-CASE-RNT-009","name":"租客物品被房东擅自清理索赔胜诉案例","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"退租后东西还在房里房东直接扔了，能索赔吗？","ola":"需通知限期取回，擅自清理构成侵权。","cp":["退租遗留物品不能直接清理","需通知租客限期取回","合理保管期不少于7天","擅自清理构成侵权"],"detail":"租客唐某退租后留有部分物品未搬走，房东魏某3天后未经通知直接将物品清理变卖。唐某起诉索赔物品损失3万元。法院认定：魏某未经通知和合理保管期即处理他人财物，构成侵权。判决魏某赔偿唐某物品损失2万元。","legalRef":"《中华人民共和国民法典》第一千一百六十五条","consumerBenefit":"了解法院裁判规则，预判维权结果。","tags":{"clientType":["landlord","seller","tenant"],"stage":"post","layer":"器","meetingPhase":["见前","见中","见后"]},"alias":["租客物品被房东擅自清理索赔胜诉","租客物品被房东擅自清理索赔胜诉案例","租客物品被房东擅自清理索赔胜诉判例"]},{"id":"OWN-CASE-RNT-010","name":"买卖不破租赁新房东要求租客搬走败诉案例","domain":"资产持有与运营","subScene":"出租管理","scene":"资产持有与运营·出租管理","cq":"房东卖了房子新房东让我搬走，合法吗？","ola":"新房东受原租赁合同约束，不能赶租客。","cp":["买卖不破租赁是法定规则","新房东受原租赁合同约束","不能以过户为由赶租客","买房前需了解租赁情况"],"detail":"房东宋某将出租中的房屋出售给何某并完成过户。何某以自己是新房东为由要求租客朱某搬走，朱某拒绝。何某起诉要求朱某腾退。法院认定：原租赁合同对新房东继续有效(买卖不破租赁)，判决驳回何某诉请，何某需继续履行原租赁合同至期满。","legalRef":"《中华人民共和国民法典》第七百二十五条","consumerBenefit":"了解法院裁判规则，预判维权结果。","tags":{"clientType":["landlord","seller","tenant"],"stage":"post","layer":"器","meetingPhase":["见前","见中","见后"]},"alias":["买卖不破租赁新房东要求租客搬走败诉","买卖不破租赁新房东要求租客搬走败诉案例","买卖不破租赁新房东要求租客搬走败诉判例"]},{"id":"PRE-RNT-001","name":"租房预算怎么算才合理","domain":"签约前","subScene":"需求确认","scene":"签约前·需求确认","cq":"我月薪8000，租房预算多少合适？","ola":"月租不超2400，加上物业水电总居住成本不超2800","cp":["月租不超收入30%","隐性成本加总算","全成本核算表","实际支出比预期高二三成"],"detail":"租房预算的黄金法则是月租金不超过税后月收入的30%。计算时不能只看月租，还需加上物业费、水电燃气、网费、交通费等隐性成本，总居住成本建议控制在收入的35%以内。首次租房常见错误是只算月租不算隐性费用，实际入住后月支出比预期高20-30%。经纪人应帮客户做全成本核算表：月租+物业+水电+网费+通勤变化+生活配套差价，让客户看到真实总成本再决策。","legalRef":"无直接法条","consumerBenefit":"避免预算超支导致生活质量下降","tags":{"clientType":["tenant"],"stage":"pre","layer":"法","meetingPhase":["见前"]},"alias":["租金预算计算","租房花多少钱","租房成本核算"]},{"id":"PRE-RNT-009","name":"租房选毛坯还是精装更划算","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"租房选毛坯自己装还是直接租精装？","ola":"长租2年以上选毛坯划算，短租选精装省心","cp":["毛坯省租但前期投入大","精装省心但月租高","看租期定选择","做投入产出对比"],"detail":"毛坯和精装的选择取决于租期和预算。毛坯房月租低30-50%，但需自行购置家电家具和简单装修，前期投入2-5万，适合长租（2年以上）且预算有限但有装修能力的租客。精装房拎包入住，适合短租（1年内）或不愿折腾的租客。判断公式：毛坯月租差×租期>装修投入则选毛坯，反之选精装。经纪人应帮客户做投入产出对比表，而非简单推荐贵的。","legalRef":"无直接法条","consumerBenefit":"根据租期选择最优方案省钱省心","tags":{"clientType":["tenant"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["毛坯vs精装租房","租房装修选择","毛坯房租房"]},{"id":"PRE-RNT-019","name":"租到抵押房或查封房怎么办","domain":"签约前","subScene":"风险识别","scene":"签约前·风险识别","cq":"租的房子被抵押或查封了怎么办？","ola":"签约前查产调，抵押前出租受保护，查封房租赁无效可退租索赔","cp":["抵押前出租受保护","查封房不得出租","签约前查产调","合同加产权瑕疵赔偿条款"],"detail":"抵押房出租的法律效力：抵押权设立前已出租的，租赁关系不受抵押权影响（买卖不破租赁的延伸）；抵押权设立后出租的，抵押权实现时租赁合同可能被解除。查封房出租：已被法院查封的房屋不得出租，租赁合同无效。租客防范措施：①签约前到不动产登记中心查询房屋抵押查封状态②要求房东提供近一个月内的产调证明③合同中写明'如因房屋抵押/查封导致租客无法居住，房东退还全部租金押金并赔偿搬家费用'。","legalRef":"《中华人民共和国民法典》第四百零五条","consumerBenefit":"防范房屋产权风险","tags":{"clientType":["tenant"],"stage":"pre","layer":"道","meetingPhase":["见前"]},"alias":["抵押房出租","查封房租赁","租赁房屋抵押风险"]},{"id":"P3-A4-030","name":"租赁期满不续约要提前多久通知","domain":"法规政策","subScene":"租赁法规","scene":"法规政策·租赁法规","cq":"客户问：租赁期满不续约要提前多久通知？","ola":"有约定从约定，无约定一般提前一个月通知，否则可能视为续租。","cp":["合同有约定按约定执行","无约定一般提前一个月通知","不通知可能视为默示续租"],"detail":"租赁期满是否续约，首先看合同约定。合同约定了提前通知期限的从约定，常见为提前一个月。合同未约定的，依据惯例一般也应提前一个月通知对方。若租赁期满双方均未提出异议且承租人继续使用房屋、出租人没有异议的，原租赁合同继续有效，但租赁期限变为不定期。不定期租赁双方均可随时解除，但应提前合理期限通知。","legalRef":"《中华人民共和国民法典》第七百三十四条","consumerBenefit":"帮租客和房东规范到期通知行为，避免默示续租带来的被动。","tags":{"clientType":["tenant","landlord"],"stage":"pre","layer":"术","meetingPhase":["见前"]},"alias":["租期到了不续约要提前说吗","租赁到期通知期限","不续租需要提前多久告知"]},{"id":"D16-061","name":"宠物家庭的画像特征和特殊需求有哪些？","domain":"社区服务与运营","subScene":"家庭画像与需求预判","scene":"社区服务与运营·家庭画像与需求预判","cq":"客户问：我们家有猫有狗，社区有没有宠物相关的服务？","ola":"宠物家庭核心需求是宠物活动空间、医疗洗护、邻里关系协调","cp":["空间需求：空间需求方面","服务需求：服务需求集中在宠物医疗（疫苗","协调需求：公共区域卫生问题","出行需求：宠物电梯使用安排、携宠搬家协助"],"detail":"宠物家庭是近年增长最快的社区细分群体。画像特征：以80后、90后年轻家庭为主，将宠物视为家庭成员，消费意愿强、对宠物相关服务品质要求高。空间需求方面，宠物家庭需要社区内有安全的宠物活动区域、合理的遛狗路线规划，以及宠物友好型商户信息（如允许宠物进入的咖啡店、商场等）。服务需求集中在宠物医疗（疫苗、体检、急诊）、洗护美容（定期洗澡、剪毛、修甲）、寄养托管（出差旅游期间的宠物寄养）和用品配送（猫粮狗粮、猫砂等重物配送上门）。协调需求是宠物家庭的痛点：宠物噪音扰民、公共区域卫生问题、电梯内宠物行为等容易引发邻里矛盾，需要居间调解。出行需求方面，携宠搬家需要特殊包装和运输安排，部分小区电梯规定宠物乘坐需使用专用电梯或错峰。服务宠物家庭时建议建立社区宠物档案（种类、数量、疫苗情况），同时制定宠物行为公约，平衡宠物家庭与非宠物家庭的权益。","legalRef":"无","consumerBenefit":"帮养宠家庭解决社区生活难题","tags":{"clientType":["buyer","landlord","seller","tenant"],"stage":"all","layer":"术","meetingPhase":["见前"]},"alias":["养宠家庭要什么","有宠物的住户需求","宠物主人画像"]},{"id":"D16-064","name":"新婚家庭的画像特征和居住需求有哪些？","domain":"社区服务与运营","subScene":"家庭画像与需求预判","scene":"社区服务与运营·家庭画像与需求预判","cq":"客户问：我们刚结婚搬进来，有什么需要注意的？","ola":"新婚家庭核心需求是装修入住、家具家电配置、家庭理财规划","cp":["安家需求：甲醛检测治理","生活需求：生活需求方面","财务需求：家庭保险（重疾","预判需求：1-2年内可能面临育儿需求"],"detail":"新婚家庭是社区服务中最具成长潜力的群体，当前需求密度高且未来演变路径清晰。画像特征：年龄25-32岁，刚组建家庭，多为首次置业，对居住品质有追求但预算有限，处于从个人生活向家庭生活过渡的适应期。安家需求是新婚家庭最迫切的：新房装修验收、甲醛检测治理、家具家电选购安装、网络宽带开通、水电燃气过户等，建议提供一站式安家服务包。生活需求方面，新婚夫妇初到社区需要周边生活配套指引（超市、医院、餐饮、健身）、物业手续办理协助、邻里关系建立等。财务需求常被忽略但很关键：房贷月供规划、家庭保险（重疾、意外、家财险）配置建议、装修预算控制等，帮新婚家庭建立健康的财务基础。预判需求方面，新婚家庭通常在1-2年内面临育儿需求，可提前推送孕期保健、产检医院、月子中心、学区政策等信息，在客户尚未意识到需求时先行布局。服务新婚家庭的关键是做到一次性解决安家全流程需求，建立信任后再逐步延伸至育儿、改善等后续需求。","legalRef":"无","consumerBenefit":"帮新婚家庭一站式安家落户","tags":{"clientType":["buyer","seller","tenant"],"stage":"all","layer":"术","meetingPhase":["见前"]},"alias":["刚结婚的家庭需求","新婚夫妇画像","婚房住户要什么"]},{"id":"D16-143","name":"物业信息获取有哪些渠道？","domain":"社区服务与运营","subScene":"社区关系维护","scene":"社区服务与运营·社区关系维护","cq":"客户问：物业有什么新规定我怎么才能第一时间知道？","ola":"通过物业公告栏、业主群、物业APP和物业工作人员等多渠道获取","cp":["关注物业公告栏和电梯间的通知公告","加入业主微信群","关注物业微信公众号或APP，获取线上推送","与物业工作人员保持日常联系"],"detail":"物业信息获取是居住服务者为客户创造信息价值的重要能力。信息渠道分为公开渠道和非公开渠道两类。公开渠道包括物业公告栏（通常在一楼大堂或电梯间）、物业微信公众号或APP推送、业主微信群通知、社区公示栏等。非公开渠道包括与物业工作人员的日常沟通中获取的内部信息，如即将出台的新规、设备更换计划、车位释放信息等。获取信息后要交叉验证，避免单一渠道信息失真。对于涉及客户利益的重要信息（如物业费调价、停车管理变化、装修规定调整等），要第一时间通知客户并解读影响。建议建立物业信息档案，分类记录历史通知和政策变化，既方便日后查询，也能帮助新客户快速了解社区规则。","legalRef":"《物业管理条例》第六条","consumerBenefit":"帮客户第一时间掌握物业动态","tags":{"clientType":["buyer","landlord","seller","tenant"],"stage":"all","layer":"术","meetingPhase":["见前"]},"alias":["物业信息怎么获取","物业消息渠道","物业动态了解方法"]},{"id":"D16-144","name":"如何与居委会建立良好关系？","domain":"社区服务与运营","subScene":"社区关系维护","scene":"社区服务与运营·社区关系维护","cq":"客户问：居委会能帮什么忙？你们跟居委会熟吗？","ola":"主动参与居委会组织的社区活动","cp":["主动参与居委会组织的志愿服务和社区活动","向居委会介绍自己的身份和服务内容","协助居委会完成居民信息采集","遇到涉及政策的事务优先咨询居委会"],"detail":"居委会是基层群众自治组织，在社区治理中具有重要影响力，掌握着政策信息、公共资源分配和矛盾调解等关键职能。与居委会建立良好关系，首先要在正式场合亮相，参加居委会组织的社区活动、志愿服务等，让居委会成员认识你并了解你的服务角色。其次要主动提供价值，如协助居委会进行居民信息采集、政策宣传、通知传达等，让居委会感受到你是社区治理的积极力量。在处理涉及政策的事务时（如居住证办理、困难补助申请等），优先咨询居委会获取准确信息，避免自行解读政策误导客户。关系建立需要时间积累，切忌急功近利，更不可利用居委会关系谋取不当利益。建议保持每月至少一次与居委会的互动频率，维持关系的活跃度。","legalRef":"《城市居民委员会组织法》","consumerBenefit":"帮客户借助居委会资源解决社区事务","tags":{"clientType":["buyer","landlord","seller","tenant"],"stage":"all","layer":"法","meetingPhase":["见前"]},"alias":["居委会关系怎么建","和居委会搞好关系","居委会对接方法"]},{"id":"LIV-DEC-CASE-092","name":"装修公司用的胶水不环保导致超标怎么赔（LIV-DEC）","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修公司用的劣质胶水导致甲醛超标，我能要求他们赔偿我的租房费用吗？","ola":"证实辅料不环保，可索赔治理费、延期损失及部分退款。","cp":["锁定劣质辅料证据","申请同批次材料鉴定","主张治理与延期损失","要求退还部分装修款","保留材料进场清单"],"detail":"情境：装修完工后甲醛超标，经检测或鉴定，发现是装修公司使用的劣质胶水、板材等辅料导致。依据：施工方有义务提供符合国家环保标准的材料。案例参考：法院在审理此类案件时，若业主能证明超标系施工方辅料所致，会判决装修公司承担治理费用、延期入住损失，甚至退还部分装修款。建议：保留施工方进场材料清单，申请对现场残留辅料或同批次材料进行鉴定。风险：辅料已完全使用且无法提取样本，导致鉴定困难。","legalRef":"《中华人民共和国民法典》第五百八十二条（瑕疵履行违约责任）","consumerBenefit":"成功锁定辅料污染源头，获得包括延期租房在内的全面经济赔偿。","tags":{"clientType":["tenant"],"stage":"post","layer":"器","meetingPhase":["见后"]},"alias":["装修胶水甲醛超标怎么索赔","装修公司用劣质胶水超标","装修辅料不环保导致超标"]},{"id":"PRE-RNT-007","name":"租房看房必须检查的十个要点","domain":"签约前","subScene":"房源匹配","scene":"签约前·房源匹配","cq":"租房看房时应该检查什么？","ola":"水电燃气门窗墙地厨卫安全周边，十项逐一查并拍照留证","cp":["水电燃气门窗墙面地面厨卫家电安全周边","十查逐项打勾","带清单看房显专业","入住前留照片视频"],"detail":"租房看房十查：①水——水龙头水压/漏水②电——插座/配电箱③燃气——灶具热水器/漏气④门窗——密封性/锁具⑤墙面——裂缝/渗水/发霉⑥地面——翘起/空鼓⑦厨卫——防水/排水/通风⑧家电——空调/冰箱/洗衣机⑨安全——门锁/监控/逃生⑩周边——噪音/采光/邻里。经纪人带检查清单逐项打勾，入住前留照片视频。","legalRef":"《中华人民共和国民法典》第七百零八条","consumerBenefit":"入住前发现隐患避免纠纷","tags":{"clientType":["tenant"],"stage":"pre","layer":"法","meetingPhase":["见中"]},"alias":["租房看房清单","租房验房","看房检查事项"]},{"id":"PRE-RNT-024","name":"租房合同避坑检查清单","domain":"签约前","subScene":"合同审查","scene":"签约前·合同审查","cq":"（经纪人工具）签租房合同前怎么检查？","ola":"15项必查清单逐项打勾签字，从产权核实到设施清单不遗漏","cp":["15项必查逐项打勾","产权核实第一关","设施清单+表读数","双方签字确认"],"detail":"租房签约前15项必查清单：①房产证原件核对产权人身份②产权人身份证与合同一致③如非产权人签约须有授权委托书④押金金额及退还条件写明⑤月租金额及支付日期⑥物业费/供暖费承担方⑦维修责任条款⑧转租条款⑨提前退租条件及违约金⑩续租优先权及调租规则⑪附属设施清单及状态⑫水电气表读数记录⑬双方联系方式及送达地址⑭争议解决方式（仲裁或法院）⑮合同附件齐全。经纪人应将此清单打印，签约时逐项打勾，双方签字确认。","legalRef":"《中华人民共和国民法典》第七百零四条","consumerBenefit":"标准化合同审查避免遗漏","tags":{"clientType":["tenant","agent"],"stage":"pre","layer":"器","meetingPhase":["见中"]},"alias":["租赁合同检查表","租房签约清单","合同审查清单"]},{"id":"P1-A4-006","name":"租房期间物业费该谁交","domain":"法规政策","subScene":"租住·租期内服务","scene":"法规政策·租住·租期内服务","cq":"租房期间的物业费该谁交？","ola":"合同约定优先，无约定房东交，签约时列清费用","cp":["合同约定优先","无约定房东交","水电按量租客交","采暖费看约定","签约列清费用"],"detail":"物业费承担规则：①合同约定优先→合同写明谁交就谁交 ②无约定→一般由房东承担（物业费是房屋所有权人的义务），但实践中很多合同约定租客承担 ③区分情况→纯住宅物业费通常约定租客交；电梯/公共区域维护费房东交 ④水电燃气→按实际使用量由租客交 ⑤采暖费→北方城市一般租客承担，但合同可另行约定 ⑥建议→签约时明确列出所有费用承担方（物业/水电/燃气/采暖/网络/车位），避免后续争议。","legalRef":"《中华人民共和国民法典》第七百一十四条（承租人承担租赁物使用中的费用）","consumerBenefit":"签约时列清费用清单，住完不扯皮","tags":{"clientType":["tenant","landlord"],"stage":"mid","layer":["法"],"meetingPhase":["见中"]},"alias":["物业费","租房物业费","物业费谁交"]},{"id":"P3-A4-026","name":"租赁房屋内物品损坏谁修","domain":"法规政策","subScene":"租赁法规","scene":"法规政策·租赁法规","cq":"客户问：租赁房屋内物品损坏谁修？","ola":"自然损耗和老化由房东维修，租客故意或重大过失损坏由租客负责。","cp":["自然老化由房东负责维修","租客故意或重大过失自行承担","报修后房东不及时修租客可代修抵租"],"detail":"出租人应当履行租赁物的维修义务，但当事人另有约定的除外。房屋主体结构和固定设施的自然老化损坏由房东维修，如水管漏水、电路故障、电器自然损坏等。因承租人使用不当或故意造成的损坏，由承租人自行维修或赔偿。承租人发现需要维修时应及时通知出租人，出租人未在合理期限内维修的，承租人可自行维修并要求抵扣租金。","legalRef":"《中华人民共和国民法典》第七百一十二条","consumerBenefit":"帮租客和房东明确维修责任边界，遇损坏不推诿不扯皮。","tags":{"clientType":["tenant","landlord"],"stage":"mid","layer":"法","meetingPhase":["见中"]},"alias":["租房东西坏了谁修","房东维修义务范围","租客弄坏东西谁赔"]},{"id":"D16-042","name":"如何对比楼盘的物业费？","domain":"社区服务与运营","subScene":"楼盘管理与销控","scene":"社区服务与运营·楼盘管理与销控","cq":"客户问：这个小区物业费多少？贵不贵？服务值不值这个价？","ola":"同区域同档次楼盘物业费横向对比","cp":["物业费区间：分析时需两个维度：横向对比","横向对比：同区域同档次楼盘物业费差异","性价比判断：物业费与服务品质是否匹配","费用构成：还需关注物业费构成"],"detail":"物业费是持有房产的持续支出，直接影响居住成本。分析时需两个维度：横向对比，收集同区域同档次楼盘的物业费水平，判断本楼盘物业费是偏高还是偏低；性价比判断，物业费与服务品质的匹配度比绝对金额更重要，高物业费若配套高品质服务（24小时安保、即时维修、园林养护）则合理，低物业费但服务粗糙则居住体验差。常见物业费水平：刚需盘2-3元/㎡/月，改善盘3-5元/㎡/月，豪宅盘5元以上/㎡/月。还需关注物业费构成，基础物业费、公摊能耗费、电梯运行费等明细是否透明。物业费调整需经业主大会表决，不可单方面涨价，这是业主权益保障。","legalRef":"《物业管理条例》第四十条","consumerBenefit":"帮客户判断物业费性价比与长期持有成本","tags":{"clientType":["buyer","tenant","seller"],"stage":"all","layer":"术","meetingPhase":["见中"]},"alias":["物业费贵不贵","物业费多少合理","不同楼盘物业费差多少"]},{"id":"D16-138","name":"怎样组织社区团购？","domain":"社区服务与运营","subScene":"便民服务","scene":"社区服务与运营·便民服务","cq":"客户问：小区能不能组织团购，东西便宜又方便？","ola":"筛选优质货源、招募团长、建立团购群","cp":["筛选有资质：优先选择有食品经营许可证","招募社区团长，负责选品、开团、收货和分发","建立团购微信群，制定群规和售后处理流程","控制品类数量：确保商品质量和价格优势"],"detail":"社区团购组织是连接居民日常消费需求与优质货源的便民服务。组织社区团购首先要解决货源问题，优先选择有食品经营许可证、产地直供的供应商，确保商品质量和价格优势。其次要招募社区团长，团长是团购的核心角色，负责选品、开团、对接供应商、收货分发和售后处理，建议选择社区内有空闲时间、责任心强的居民担任。建立团购微信群是日常运营的基础，群内要制定清晰的群规，包括开团时间、截单时间、提货地点、售后流程等。选品策略上建议优先选择高频刚需商品如生鲜水果、米面粮油、日化用品等，避免贪多求全。售后方面要与供应商约定退换货规则，团长要做好验货把关，发现问题商品及时处理。团购规模建议从1-2个品类起步，验证模式后再逐步扩展。","legalRef":"《电子商务法》","consumerBenefit":"帮社区居民买到实惠靠谱的日常商品","tags":{"clientType":["buyer","landlord","seller","tenant"],"stage":"all","layer":"术","meetingPhase":["见后"]},"alias":["社区团购怎么搞","组织社区拼团","小区团购方法"]},{"id":"D16-160","name":"如何组织社区志愿服务？","domain":"社区服务与运营","subScene":"社区关系维护","scene":"社区服务与运营·社区关系维护","cq":"客户问：想组织小区志愿者做些有意义的事，怎么开始？","ola":"招募志愿者、确定服务项目、制定排班计划、准备物资保障","cp":["招募志愿者：通过业主群","确定服务项目：从居民最需要的帮扶开始","制定排班计划：根据志愿者时间安排轮值","准备物资保障：步准备物资保障"],"detail":"社区志愿服务组织是深化社区关系、提升社区凝聚力的重要方式。组织流程分为四步：第一步是招募志愿者，通过业主群、社区公告栏发布招募信息，说明服务内容、时间要求和报名方式，首批招募5-10人即可启动。第二步确定服务项目，建议从居民最需要的帮扶开始，如独居老人关爱（定期探访、代买代办）、社区环保（垃圾分类宣传、公共区域清洁）、邻里互助（临时照看、紧急帮忙）等。第三步制定排班计划，根据志愿者的空闲时间安排轮值，确保每个时段都有人值守，避免志愿服务断档。第四步准备物资保障，包括志愿服或标识、服务工具、饮水等基础物资，可向物业申请支持或自备。志愿服务要注重可持续性，切忌搞形式主义一阵风，要让志愿服务成为社区的常态风景。","legalRef":"《志愿服务条例》","consumerBenefit":"帮客户组织有意义的社区志愿活动","tags":{"clientType":["buyer","landlord","seller","tenant"],"stage":"all","layer":"术","meetingPhase":["见后"]},"alias":["社区志愿怎么组织","志愿服务组织方法","社区志愿者活动"]},{"id":"CRO-GEN-002","name":"房子价格由什么决定","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"这房子凭什么卖这么贵","ola":"地段供需配套政策楼层朝向共同决定","cp":["地段是核心定价因素","供需关系决定价格走势","政策调控影响短期波动","楼层朝向产生价差"],"detail":"房产价格由地段价值、建筑品质、市场供需、政策调控、配套设施、楼层朝向、房龄年限、业主急售程度等多因素共同决定。经纪人应掌握市场比较法和成本法两种基本估值思路，帮客户理解定价逻辑。","legalRef":"行业通行做法","consumerBenefit":"理解定价逻辑，出价更合理","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["房价看什么","房子值不值这个价","房价影响因素"]},{"id":"CRO-GEN-004","name":"买房有哪些风险要注意","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"买房最怕踩什么坑","ola":"产权资金合同政策信息五大风险逐一查","cp":["产权风险：抵押查封共有人","资金风险：房款安全流转","合同风险：关键条款审查","政策风险：限购限贷变动"],"detail":"房产交易风险分为产权风险（抵押查封共有人）、资金风险（房款安全）、合同风险（条款遗漏）、政策风险（限购限贷）、信息风险（虚假房源）五大类。经纪人需在交易全流程中逐项排查，建立风险清单制度。","legalRef":"行业通行做法","consumerBenefit":"提前识别风险，避免财产损失","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["买房风险有哪些","买房最怕什么坑","购房风险类型"]},{"id":"CRO-GEN-015","name":"怎么判断经纪人专不专业","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"怎么知道这个经纪人专不专业","ola":"看沟通分析法律风控四大能力","cp":["沟通：提问能挖掘深层需求","分析：数据解读而非笼统说法","法律：能识别合同风险条款","风控：提前预判潜在问题"],"detail":"判断经纪人专业度可从沟通能力（提问深度）、市场分析（数据解读能力）、法律知识（合同风险识别）、风控意识（预判潜在问题）四个维度评估。进阶经纪人应能提供定制方案，高级经纪人能设计复杂交易结构。","legalRef":"行业通行做法","consumerBenefit":"选到专业经纪人，交易更有保障","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["专业经纪人怎么辨别","经纪人专业度怎么看","好经纪人标准"]},{"id":"CRO-GEN-018","name":"经纪人和普通中介有什么区别","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"经纪人和外面中介到底有什么不一样","ola":"经纪人是持证受约束的专业中介","cp":["经纪人是中介的细分类型","持证经纪人须通过资格考试","受行业规范和法律约束","法律义务高于未持证人员"],"detail":"房地产经纪人是依法取得执业资格的专业人员，属于房地产中介服务机构中的细分类型。《城市房地产管理法》将房地产经纪机构明确列为中介服务机构的一种。持证经纪人须通过资格考试，受行业规范约束，法律义务高于未持证中介人员。","legalRef":"《中华人民共和国城市房地产管理法》第58条","consumerBenefit":"选持证经纪人，权益更有法律保障","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["道"],"meetingPhase":["见前"]},"alias":["经纪人和中介区别","房地产经纪人是什么","中介和经纪人一样吗"]},{"id":"CRO-GEN-020","name":"房子质量好不好怎么判断","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"这房子质量行不行，怎么看","ola":"结构防水门窗水电四项逐一看","cp":["结构安全：墙体裂缝地基沉降","防水工程：厨卫渗漏屋面漏水","门窗质量：密封性开合顺畅","水电设施：线路管道合规"],"detail":"房屋质量评估涵盖结构安全（墙体裂缝地基沉降）、防水工程（厨卫渗漏屋面漏水）、门窗质量（密封性开合顺畅）、水电设施（线路管道合规）、装修标准（材料环保等级）。经纪人带看时应主动指出可见质量问题和潜在隐患。","legalRef":"GB 50210-2018《建筑装饰装修工程质量验收标准》","consumerBenefit":"买到质量过关的房子，省维修烦恼","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["法"],"meetingPhase":["见前"]},"alias":["房屋质量怎么看","房子质量判断方法","验房看什么"]},{"id":"CRO-GEN-022","name":"买房受什么法律保护","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我买房法律上受什么保护","ola":"物权和合同双重保护依法维权有据","cp":["物权经登记受法律平等保护","合同依法成立即有约束力","购房者享有知情权","任何组织不得侵犯合法物权"],"detail":"购房者权利受《民法典》物权编和合同编双重保护。物权编保障不动产物权经登记后受法律平等保护，任何组织和个人不得侵犯；合同编保障买卖合同依法成立即具有法律约束力。购房者同时享有知情权、公平交易权等消费者权利。","legalRef":"《中华人民共和国民法典》第207条、第240条","consumerBenefit":"知道自己的法律权利，交易更有底气","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["道"],"meetingPhase":["见前"]},"alias":["购房法律保护","买房有哪些法律权利","购房者法律保护"]},{"id":"CRO-GEN-023","name":"合同签了对方不履行怎么办","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"合同签了但对方不履行怎么办","ola":"可要求继续履行或赔偿损失","cp":["违约方须承担违约责任","可要求继续履行合同","可要求赔偿实际损失","可要求赔偿可得利益损失"],"detail":"合同依法成立后，一方不履行合同义务或履行不符合约定的，应当承担继续履行、采取补救措施或赔偿损失等违约责任。《民法典》第577条明确了违约方的基本责任形式。守约方可要求违约方继续履行或赔偿实际损失和可得利益损失。","legalRef":"《中华人民共和国民法典》第577条","consumerBenefit":"签了合同就有法律保障，不怕对方反悔","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["道"],"meetingPhase":["见前"]},"alias":["签了合同对方违约怎么办","合同违约怎么处理","对方不履行合同怎么办"]},{"id":"CRO-GEN-024","name":"不动产登记有什么用","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"办不动产登记到底有什么用","ola":"登记才产生物权效力是法律保障基础","cp":["登记才发生物权效力","未经登记不发生效力","登记簿是物权归属根据","证书与登记簿不一致以簿为准"],"detail":"不动产登记是物权的法定公示方式。不动产物权的设立、变更、转让和消灭，经依法登记发生效力；未经登记不发生效力（法律另有规定的除外）。不动产登记簿是物权归属和内容的根据，与不动产权属证书不一致时以登记簿为准。","legalRef":"《中华人民共和国民法典》第209条、第214条、第216条","consumerBenefit":"登记才有法律保护，不登记产权不受认可","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["道"],"meetingPhase":["见前"]},"alias":["不动产登记有什么意义","房产登记有什么用","不动产登记效力"]},{"id":"CRO-GEN-026","name":"买房被骗了法律怎么追责","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"买房被骗了，法律上能怎么办","ola":"一年内可请求撤销合同并要求赔偿","cp":["受欺诈方可请求撤销合同","撤销后财产应予返还","欺诈方须赔偿对方损失","须在知道撤销事由一年内行使"],"detail":"一方以欺诈手段使对方在违背真实意思的情况下实施民事法律行为的，受欺诈方有权请求人民法院或仲裁机构予以撤销。撤销后因该行为取得的财产应当予以返还，有过错的一方应当赔偿对方由此所受到的损失。","legalRef":"《中华人民共和国民法典》第148条、第157条","consumerBenefit":"被骗了有法律救济，不是只能自认倒霉","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["道"],"meetingPhase":["见前"]},"alias":["买房被骗怎么办","房产欺诈怎么维权","买房被骗能追回钱吗"]},{"id":"CRO-GEN-027","name":"夫妻买房法律上怎么算","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我们夫妻买房，法律上算谁的","ola":"婚后买一般共有时婚前全款归个人","cp":["婚后购买一般为共同财产","婚前全款购买为个人财产","共同还贷部分需补偿对方","双方可书面约定归属"],"detail":"婚姻关系存续期间购买的房产，一般属于夫妻共同财产；婚前一方全款购买并登记在己方名下的属于个人财产。婚后共同还贷的房产，离婚时产权登记方应就共同还贷部分及增值部分对另一方进行补偿。双方可约定财产归属。","legalRef":"《中华人民共和国民法典》第1062条、第1063条、第1065条","consumerBenefit":"提前明确产权归属，避免日后纠纷","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["道"],"meetingPhase":["见前"]},"alias":["夫妻买房产权怎么算","婚后买房属于谁","夫妻共同财产房产"]},{"id":"CRO-GEN-028","name":"买房前要准备哪些材料","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"买房前我要准备哪些材料","ola":"身份证户口婚姻收入征信流水先备齐","cp":["身份证户口本婚姻证明必备","收入证明银行流水贷款必须","征信报告提前查询","公积金或社保证明视城市要求"],"detail":"购房所需材料因身份和交易类型不同而有差异，通用材料包括身份证、户口本、婚姻证明、收入证明、银行流水、征信报告。贷款购房还需公积金缴存证明或社保缴纳证明。经纪人应在签约前协助客户逐一备齐，避免临时缺失影响进度。","legalRef":"行业通行做法","consumerBenefit":"提前备齐材料，交易不卡壳","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["法"],"meetingPhase":["见前"]},"alias":["购房材料清单","买房要什么证件","购房需要准备什么"]},{"id":"CRO-GEN-029","name":"不动产登记信息怎么查","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"怎么查这套房子的产权信息","ola":"到不动产登记中心窗口或线上查询","cp":["权利人可查询登记资料","窗口或线上均可查询","签约前必须核实产权","重点关注抵押和查封信息"],"detail":"权利人和利害关系人可依法查询、复制不动产登记资料。《不动产登记暂行条例》第27条赋予查询权。查询途径包括不动产登记中心窗口、部分城市政务网线上查询。经纪人应在签约前代为查询，核实产权人、抵押、查封等信息。","legalRef":"《不动产登记暂行条例》第27条","consumerBenefit":"签约前查清产权，避免买到问题房","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["法","道"],"meetingPhase":["见前"]},"alias":["产调怎么查","房产登记信息查询","不动产查询怎么查"]},{"id":"CRO-GEN-030","name":"个人征信报告怎么查怎么看","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我的征信报告怎么查，怎么看","ola":"央行官网或柜台可查看逾期负债查询次数","cp":["央行征信中心官网可查","逾期记录是贷款审批关键","负债余额影响还款能力评估","近期频繁查询可能被视为风险"],"detail":"个人征信报告可通过中国人民银行征信中心官网线上查询或本人持身份证到人民银行柜台查询。征信报告重点关注逾期记录（连续3次或累计6次可能影响贷款）、负债余额、查询次数（近期频繁查询可能被视为风险）。","legalRef":"《征信业管理条例》第十七条","consumerBenefit":"提前查征信，贷款不意外被拒","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["法"],"meetingPhase":["见前"]},"alias":["征信报告怎么查","个人信用报告查询","征信怎么看"]},{"id":"CRO-GEN-031","name":"买房完整流程有几步","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"买房从头到尾到底有几步","ola":"需求资格选房签约网签贷款缴税过户交房","cp":["需求确认→资格审查先行","签约→网签→贷款→缴税→过户","环节有先后依赖关系","经纪人需全程把控节点时效"],"detail":"房产交易全流程可分为需求确认→资格审查→房源匹配→价格评估→谈判签约→网签→贷款审批→缴税→过户→交房十个核心环节。每个环节有先后依赖关系，前序环节未完成则后续无法推进。经纪人需全程把控节点和时效。","legalRef":"行业通行做法","consumerBenefit":"清楚全流程，每一步心里有数","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["法"],"meetingPhase":["见前"]},"alias":["购房流程步骤","买房全流程","房产交易完整流程"]},{"id":"CRO-GEN-032","name":"公积金可以怎么用","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"公积金能怎么用，买房能省多少","ola":"可低息贷款可提款还贷利率低于商贷","cp":["可低利率贷款购房","可提取支付房款","可提取偿还贷款本息","公积金贷款利率低于商贷"],"detail":"住房公积金可用于低利率贷款购房、提取支付房款或月供、提取偿还贷款本息等用途。《住房公积金管理条例》第24条列举了可提取情形：购买自住住房、偿还购房贷款本息、租房等。公积金贷款利率显著低于商业贷款，是购房重要资金工具。","legalRef":"《住房公积金管理条例》第24条","consumerBenefit":"善用公积金，贷款利息省一大笔","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["法","道"],"meetingPhase":["见前"]},"alias":["住房公积金怎么用","公积金贷款怎么贷","公积金提取条件"]},{"id":"CRO-GEN-033","name":"买房有哪些费用要交","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"买房除了房款还要交什么钱","ola":"契税增值税个税佣金评估费登记费等","cp":["契税1%-3%按面积套数定","增值税满2年可免","个税满五唯一可免","佣金评估费登记费等另计"],"detail":"购房费用除房款外还包含契税（1%-3%）、增值税（满2年免）、个人所得税（满五唯一免）、中介佣金、贷款相关费用（评估费担保费）、产权登记费、物业维修基金等。经纪人应在签约前提供完整费用清单，帮客户准确估算总支出。","legalRef":"《中华人民共和国契税法》第三条","consumerBenefit":"提前算清所有费用，不超预算","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["法"],"meetingPhase":["见前"]},"alias":["购房费用清单","买房要交什么钱","购房费用明细"]},{"id":"CRO-GEN-035","name":"找经纪人买房有什么好处","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"找你们经纪人买房到底有什么好处","ola":"消除信息差降风险控流程省成本","cp":["消除信息不对称","核验产权降低交易风险","匹配供需缩短成交周期","税费规划贷款选择省成本"],"detail":"经纪人核心价值在于消除信息不对称：提供市场真实数据、核验产权降低风险、匹配供需缩短成交周期、把控流程避免遗漏节点、协调买卖双方利益。专业经纪人还能在税费规划、贷款选择、议价策略上为客户节省成本。","legalRef":"行业通行做法","consumerBenefit":"专业人做专业事，买房省心省力省钱","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["为什么要找经纪人","经纪人有什么用","找中介买房值得吗"]},{"id":"CRO-GEN-036","name":"房产证上加名字有什么影响","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"房产证上加个名字有什么影响","ola":"加名即共有处分须同意且可能产生税费","cp":["加名须经登记才生效力","加名后变为共有财产","处分需经共有人同意","加名可能产生赠与税费"],"detail":"房产证上加名属于不动产物权变更，须经依法登记才发生效力。加名后该房产变为共有财产，处分需经共有人同意。加名可能涉及赠与税或交易税费，且加名后该人即享有物权份额，离婚时依法分割。加名前需充分考虑法律和税务后果。","legalRef":"《中华人民共和国民法典》第209条、第300条、第301条","consumerBenefit":"了解加名后果，避免日后纠纷和额外税费","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["道"],"meetingPhase":["见前"]},"alias":["房产证加名影响","房产证加名字后果","产权证加名要注意什么"]},{"id":"CRO-GEN-037","name":"买房后每年要花多少钱持有","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"买了房之后每年养房要花多少钱","ola":"物业采暖水电车位维修等月月年年支出","cp":["物业费按面积月月缴纳","采暖费北方城市每年支出","水电燃气费日常开支","月供加持有成本不超过收入合理比"],"detail":"持房成本包括物业费（按面积×单价月计）、采暖费（北方城市按面积季计）、水电燃气费、车位管理费、房屋维修基金分摊、房产税（试点城市）。经纪人应帮客户在购房前估算年度持有成本，确保月供+持有成本不超过家庭收入合理比例。","legalRef":"行业通行做法","consumerBenefit":"买房前算清养房成本，不做房奴","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["持房成本有哪些","买房后每年花费","持有房产成本"]},{"id":"CRO-GEN-038","name":"什么样的人适合买房","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我这种情况适合买房吗","ola":"收入稳定月供可控长期居住首付充足","cp":["稳定收入是购房基础","月供不超过月收入一半","计划居住5年以上才划算","首付不耗尽应急储备"],"detail":"适合购房的人群特征：有稳定收入来源、月供不超过家庭月收入50%、计划在同一城市居住5年以上、有足够首付资金且不影响应急储备。经纪人应帮客户客观评估自身条件，不鼓励超出能力的购房行为，也不因犹豫错过合适时机。","legalRef":"行业通行做法","consumerBenefit":"客观评估自身条件，不盲目跟风","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"pre,mid,post","layer":["术"],"meetingPhase":["见前"]},"alias":["哪些人适合买房","买房条件有哪些","什么情况下该买房"]},{"id":"CRO-GEN-050","name":"经济适用房和商品房有什么不同","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我看中一套经济适用房，价格很便宜，我能直接买吗？","ola":"需符合申购条件，且未满5年禁止交易。","cp":["经适房面向低收入困难家庭","经适房实行申请审批公示","经适房满5年才能上市交易","交易时需交纳土地收益金"],"detail":"经济适用房是指政府提供政策优惠，限定套型面积和销售价格，按照合理标准建设，面向城市低收入住房困难家庭供应，具有保障性质的政策性住房。商品房则是完全按市场化运作、由开发商自主定价的房屋。经济适用房实行申请、审批、公示制度，购买人拥有有限产权，通常取得契税完税凭证或房屋所有权证满5年后方可上市交易，且需按一定比例交纳土地收益等相关价款。商品房则无此类限制，产权完整，自由流转。","legalRef":"《经济适用住房管理办法》第30条","consumerBenefit":"明确经适房交易门槛，避免违规交易导致合同无效。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"道","meetingPhase":["见中","见前"]},"alias":["经济适用房能买吗","经适房和商品房区别","经济适用房可以上市交易吗"]},{"id":"CRO-GEN-055","name":"现在的限购政策到底怎么理解","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我是外地户口，在这个城市没交社保，能买房吗？","ola":"按户籍和社保限制家庭购房套数，违规无法过户。","cp":["限制家庭购房总套数","外地人需满足社保个税年限","违规购买无法网签过户","政策随市场动态调整"],"detail":"限购政策是地方政府为调控房地产市场、抑制投机炒房而出台的限制性措施。通常以家庭为单位，限制本地及外地户籍居民在一定区域内购买住房的套数。理解限购政策需关注户籍要求、社保或个税缴纳年限、认房认贷标准及特定区域限制。违反限购政策会导致无法网签和过户，甚至面临定金损失。","legalRef":"《中华人民共和国城市房地产管理法》第四条","consumerBenefit":"准确把握自身购房资格，避免因无资格购房导致违约赔偿。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"道","meetingPhase":["见中","见前"]},"alias":["限购政策是什么意思","买房限购怎么破","外地人买房限购吗"]},{"id":"CRO-GEN-057","name":"怎么才能算作首套房","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我老家有套房但没贷款，现在在大城市买算首套吗？","ola":"多数城市“认房不认贷”，名下无房即算首套。","cp":["认房不认贷看当地房产","无房即算首套享受低首付","首套享受最优惠房贷利率","具体标准依当地政策而定"],"detail":"首套房认定标准直接关系首付比例和房贷利率。目前多地执行“认房不认贷”政策，即只要家庭名下在当地无成套住房，无论是否有过贷款记录，均按首套房执行。部分城市仍结合“认贷”标准。认定首套可享受最低首付比例及最优惠的房贷利率。具体标准需以当地最新房地产调控政策及银行信贷政策为准。","legalRef":"《中国人民银行 中国银行保险监督管理委员会关于调整差别化住房信贷政策有关问题的通知》","consumerBenefit":"明确首套认定规则，最大化利用首套房低首付和低利率优惠。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"法","meetingPhase":["见中","见前"]},"alias":["首套房认定标准","怎么认定我是首套房","首套房和首贷的区别"]},{"id":"CRO-GEN-071","name":"房子还在抵押状态能直接卖吗","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我的房贷还没还清，现在想把房子卖了，可以直接卖吗？","ola":"可以卖，可通过“带押过户”或先还清贷款解押后交易。","cp":["抵押房依法可转让","带押过户免垫资","需通知抵押权人","合同约定禁止转让除外"],"detail":"房屋在抵押状态下是可以买卖的。根据《民法典》规定，抵押期间抵押人可以转让抵押财产，当事人另有约定的除外。目前多地已推行“带押过户”模式，无需先结清贷款解押即可办理过户，大幅降低交易成本和时间，但需买卖双方及银行达成一致。","legalRef":"《中华人民共和国民法典》第四百零六条","consumerBenefit":"了解合法交易途径，避免被黑中介忽悠交高额垫资费。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"道","meetingPhase":["见中","见前"]},"alias":["抵押房能交易吗","房贷没还清能卖房吗","带押过户怎么操作"]},{"id":"CRO-GEN-073","name":"买法院拍卖的房子有什么坑","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"法拍房比市场价便宜很多，我买的话会不会有什么风险踩坑？","ola":"有腾退难、欠费多、带租约等风险，需提前实地尽调。","cp":["警惕买卖不破租赁","确认房屋能否顺利腾退","查清拖欠物业水电费","核实户口能否迁出"],"detail":"法拍房虽价格较低，但存在多重风险。主要包括：房屋可能存在长期租赁（买卖不破租赁）、原房主拒不腾退导致无法入住、拖欠巨额物业水电费需买家承担、房屋存在隐性瑕疵或户口无法迁出等。购买前必须实地尽调并仔细阅读拍卖公告。","legalRef":"行业通行做法与最高法拍卖规定","consumerBenefit":"识别法拍房潜在风险，避免低价买入却面临无法入住或巨额隐性债务。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"术","meetingPhase":["见中","见前"]},"alias":["法拍房风险","法拍房有什么隐患","买法拍房要注意什么"]},{"id":"CRO-GEN-074","name":"开发商交房时必须达到什么标准","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"去收新房的时候，我怎么判断开发商交房是不是达标了？","ola":"必须查验《竣工验收备案表》及水电等基础生活条件。","cp":["必须取得竣工验收备案表","水电暖气需达到使用条件","消防规划必须验收合格","不达标可拒收并索赔"],"detail":"开发商交房必须满足法定和约定条件。法定底线是取得《建筑工程竣工验收备案表》，确保房屋主体结构合格、消防及规划验收通过。同时需具备水、电、气、暖等基本生活设施的使用条件。若未达到标准，购房者有权拒绝收房并要求开发商承担逾期交房违约责任。","legalRef":"《城市房地产开发经营管理条例》第十七条","consumerBenefit":"掌握法定收房底线，有效拒绝违规交房，维护自身合法权益。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"法","meetingPhase":["见中","见前"]},"alias":["新房交房标准","开发商交房条件","商品房交付法定标准"]},{"id":"CRO-GEN-076","name":"买了房子户口怎么才能迁进来","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我在当地买了房，也拿到房产证了，户口怎么迁过来？","ola":"需凭房产证及身份材料，符合当地政策后去派出所办理。","cp":["需取得不动产权证书","符合当地户籍准入条件","部分城市有面积社保限制","去派出所办准迁和迁移"],"detail":"购房落户需满足当地公安机关的户籍准入政策。通常要求取得房屋所有权证或不动产权证，且实际居住。部分大城市对房屋面积、社保缴纳年限或学历有附加要求。办理时需携带身份证、户口本、房产证等材料到房屋所在地派出所申请准迁证，再回原籍办理迁移。","legalRef":"各地公安机关户籍管理政策","consumerBenefit":"明确购房落户的具体门槛和流程，提前准备材料避免白跑腿。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"道","meetingPhase":["见中","见前"]},"alias":["买房落户条件","购房入户政策","新房户口怎么迁入"]},{"id":"CRO-GEN-081","name":"买房子有必要买房屋保险吗","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我买了房还要额外花钱买房屋保险吗？","ola":"非强制但建议买，保费低能转移房屋受损风险。","cp":["非强制但建议购买","保障房屋主体及装修","保费低杠杆高","覆盖火灾及自然灾害"],"detail":"房屋保险（家财险）是以房屋及其室内附属设备、室内装修等为保险标的的财产保险。在面临火灾、爆炸、自然灾害等意外时，能补偿经济损失。虽然非强制，但对于老旧小区、自建房或贷款购房家庭，购买家财险能以较低保费转移房屋主体及装修受损的重大财务风险，是完善家庭资产配置的重要一环。","legalRef":"行业通行做法","consumerBenefit":"了解家财险作用，用低成本防范房屋意外损失。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"术","meetingPhase":["见中","见前"]},"alias":["房屋保险要不要买","家财险有必要吗","房子买保险有用吗"]},{"id":"CRO-GEN-082","name":"邻居太吵了怎么投诉维权","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"楼上半夜总是吵，我该怎么合法维权？","ola":"先录音取证，找物业协调，无果可报警或起诉。","cp":["先录音录像固定证据","找物业社区协调","报警或环保部门投诉","起诉要求停止侵害"],"detail":"邻居噪音维权是指针对相邻方产生的超出国家规定标准的噪声干扰，通过协商、物业介入、行政投诉或诉讼等途径维护自身合法权益的行为。常见于装修噪音、生活噪音等。维权需先固定证据，再按先物业后报警、最后诉讼的顺序递进处理，核心在于证明噪音超标且影响正常生活。","legalRef":"《中华人民共和国民法典》第二百九十四条","consumerBenefit":"掌握合法维权步骤，有效解决邻里噪音干扰。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"道","meetingPhase":["见中","见前"]},"alias":["邻居噪音大怎么办","楼上噪音怎么解决","邻居扰民怎么投诉"]},{"id":"CRO-GEN-086","name":"买的期房烂尾了该怎么维权","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我买的期房停工烂尾了，现在该怎么办？","ola":"联合业主向政府反映保交楼，或起诉解除合同。","cp":["向住建部门反映保交楼","联合业主申请政府专班","诉讼要求解除合同退款","资不抵债时申报破产债权"],"detail":"烂尾楼维权是指购房者在开发商资金链断裂导致项目停工、无法按期交房时，采取法律及行政手段维护自身权益的行为。途径包括向住建部门反映要求保交楼、联合业主申请政府专班介入、通过诉讼要求解除合同并退款，或在资不抵债时申报破产债权。核心是抱团取暖争取交付。","legalRef":"《中华人民共和国民法典》第五百六十三条","consumerBenefit":"明确烂尾楼维权路径，最大程度挽回购房损失。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"术","meetingPhase":["见中","见前"]},"alias":["期房烂尾了怎么办","买到烂尾楼如何维权","房子烂尾了能退房吗"]},{"id":"CRO-GEN-088","name":"房子七十年产权到期了怎么办","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"我买的商品房70年产权到期后，房子会被收走吗？","ola":"住宅建设用地使用权到期自动续期，房子还是你的。","cp":["住宅建设用地自动续期","房屋所有权永久归属业主","续期费用按未来法规办理","非住宅需提前申请续期"],"detail":"房屋产权到期主要指住宅建设用地使用权期限届满后的处理问题。根据现行法律，住宅建设用地使用权期限届满的，自动续期。业主无需主动申请，房屋所有权依然归属业主。关于续期费用的缴纳或减免，将依照未来出台的法律、行政法规的具体规定办理。非住宅则需依法提前申请。","legalRef":"《中华人民共和国民法典》第三百五十九条","consumerBenefit":"消除产权到期顾虑，明确房屋所有权与土地使用权的区别。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"道","meetingPhase":["见中","见前"]},"alias":["产权到期房子还是我的吗","70年产权到期怎么处理","住宅建设用地使用权到期"]},{"id":"CRO-GEN-089","name":"买二手房资金监管是怎么回事","domain":"跨域通用","subScene":"通用基础","scene":"跨域通用·通用基础","cq":"买二手房中介让我做资金监管，这有必要吗？","ola":"非常有必要，过户后才给钱，防止钱房两空。","cp":["相当于二手房交易支付宝","过户完成后才划转给卖家","有效防止钱房两空","官方或银行第三方托管"],"detail":"二手房资金监管是指买卖双方在交易过程中，将购房款存入银行或官方指定的第三方监管账户，待房屋完成过户登记后，再由监管机构将资金划转给卖家的制度。此举相当于二手房交易的支付宝，能有效防止钱房两空，避免卖家挪用资金或房屋被查封导致买家损失，保障交易资金安全。","legalRef":"行业通行做法","consumerBenefit":"理解资金监管机制，保障二手房交易资金绝对安全。","tags":{"clientType":["buyer","seller","tenant","landlord"],"stage":"mid","layer":"法","meetingPhase":["见中","见前"]},"alias":["二手房资金监管安全吗","什么是二手房资金监管","买房为什么要做资金监管"]},{"id":"EXT-TRM-001","name":"租期没到想退租怎么办","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"我租的房子还没到期，现在想退租，要赔钱吗？","ola":"中途退租属违约，需按合同付违约金","cp":["中途退租属违约行为","需按合同付违约金","违约金一般为1-2月租金","到期退租不算违约","押金扣除违约金后退还"],"detail":"租期未满时租客单方解除租赁合同的行为。根据《民法典》第563条，当事人一方迟延履行债务致使不能实现合同目的的，另一方可以解除合同。但租客提前退租属于违约，需按合同约定承担违约责任，一般需支付违约金（通常为1-2个月租金）。租期到期退租和中途退租的法律后果不同。","legalRef":"《中华人民共和国民法典》第563条、第577条、第585条","consumerBenefit":"提前知道违约成本，做好资金规划","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["提前退租","中途退租","租期内退租"]},{"id":"EXT-TRM-003","name":"退租违约金怎么算","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"合同上写的违约金是两个月租金，这也太多了能少交吗？","ola":"违约金按合同执行，过高可申请调减","cp":["违约金以合同约定为准","常见标准为1-2月租金","未约定则赔实际损失","过高可请求法院调减","已缴未发生租金须退还"],"detail":"租客中途退租时需向业主支付的违约赔偿金。违约金数额以合同约定为准，常见标准为1-2个月租金。若合同未约定违约金，业主可主张实际损失赔偿。约定的违约金过分高于实际损失的，租客可请求法院适当减少。","legalRef":"《中华人民共和国民法典》第585条","consumerBenefit":"了解违约金上限，不被过高约定绑架","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["提前退租违约金","退租赔多少","违约金标准"]},{"id":"EXT-TRM-005","name":"退租交接需要查哪些项目","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"我要退租了，退房的时候要检查什么？","ola":"查验房屋设施、结清费用、归还钥匙","cp":["查房屋及附属设施状况","结清水电燃气等费用","归还钥匙门禁卡","双方现场验收签字","验收结果影响押金退还"],"detail":"退租时业主与租客对房屋及附属设施进行检查验收交接的过程。验收内容包括：房屋主体状况、家具家电完好度、水电燃气等费用结清、钥匙门禁卡归还、物业费等杂费结算。验收结果直接影响押金退还金额。建议双方现场共同验收并签字确认。","legalRef":"《中华人民共和国民法典》第712条","consumerBenefit":"规范验收避免纠纷，顺利拿回押金","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["退房验收清单","退租检查项目","退房交接"]},{"id":"EXT-TRM-006","name":"退租时水电燃气费怎么结清","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租的时候水电燃气费怎么算？","ola":"退租日抄表，按实际使用量和合同结算","cp":["退租日双方共同抄表","按合同约定分摊费用","未结清可从押金扣除","留存缴费凭证","含物业费供暖费等"],"detail":"退租时对租赁期间产生的水费、电费、燃气费等按实际使用量进行结算的操作。需在退租日由双方共同抄表记录最终读数，根据合同约定的费用承担方式，计算租客应缴金额。未结清的费用可从押金中扣除。建议留存最终缴费凭证。","legalRef":"《中华人民共和国民法典》第733条","consumerBenefit":"避免退租后因费用不清被追讨","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["退租水电结算","退房水电燃气","退租费用结清"]},{"id":"EXT-TRM-015","name":"退租后租金发票怎么开","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"退租了之前租金没开发票，现在还能开吗？","ola":"可与业主协商补开，税负按合同约定承担","cp":["业主应配合开具租金发票","税负承担由合同约定","退租后仍可补开发票","涉个税和增值税","双方协商税金承担方"],"detail":"退租后涉及租金发票开具的问题。租赁合同中一般约定业主应为租客开具租金发票，税金缴纳方由双方协商确定。退租时若租客需要之前租金的发票，需与业主协商开具。发票涉及个人所得税和增值税，业主需配合开具但税负可在合同中约定承担方。","legalRef":"《发票管理办法》第19条","consumerBenefit":"保留发票用于报销或抵扣个税","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["退租开发票","租金发票退租","退房发票"]},{"id":"EXT-TRM-017","name":"租期内哪种情况可以无责退租","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"租的房子甲醛超标，我退租要赔违约金吗？","ola":"甲醛超标可无责退租，不付违约金","cp":["房屋被查封可无责退租","甲醛超标可无责退租","业主迟交房达10日可解约","业主不修可解约","房屋不安全可立即退"],"detail":"租客在租赁期内可依法单方解除合同且不承担违约责任的情形。依据《民法典》第724条，租赁物被查封扣押、权属有争议、违反强制规定致使无法使用等情形，租客可解除合同。业主延迟交房达10日、房屋甲醛超标、不承担维修义务等，租客也可无责解约。","legalRef":"《中华人民共和国民法典》第724条、第731条","consumerBenefit":"识别法定解约条件，不花冤枉钱","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["法定解除租赁合同","无违约金退租","租客正当解约"]},{"id":"EXT-TRM-021","name":"提前退租押金能退吗","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"租期没到我想退租，押金还能退吗？","ola":"属违约可扣除违约金，但剩余押金应退还","cp":["提前退租属于单方违约","押金可扣除违约金后退还","扣除标准以合同约定为准","押金不得全部扣押不退","扣除违约金后应及时退还余额"],"detail":"提前退租属于租客单方违约，押金是否退还需看合同约定。根据《民法典》，承租人提前解除合同构成违约，出租人有权从押金中扣除违约金或实际损失。如合同约定提前退租押金不退，该条款在合理范围内有效；如约定扣除一个月租金作为违约金后退还剩余部分，则按约定执行。押金不得超期扣押，应扣除违约金后及时退还余额。","legalRef":"《中华人民共和国民法典》第577条、第726条","consumerBenefit":"提前退租也能拿回合理部分的押金","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["中途退租押金退还","提前退租押金全扣吗","租期没到退租押金怎么算"]},{"id":"EXT-TRM-042","name":"提前退租违约金怎么算","domain":"退租出售","subScene":"退租","scene":"退租出售·退租","cq":"提前退租违约金怎么算","ola":"按合同约定一般1-2月租金","cp":["按合同约定一般1-2月租金","未约定按实际损失赔偿","过高可请求法院调减","押金扣违约金后余额须退","配合找新租客可减少损失"],"detail":"提前退租违约金：①按合同约定的违约金条款执行，一般约定为1-2个月租金；②合同未约定的按实际损失赔偿房东可扣除寻找新租客期间的租金损失；③违约金过高（超实际损失30%）可请求法院适当调减；④房东不得同时扣违约金和全部押金，押金扣除违约金后余额须退还；⑤建议协商减少违约金如配合房东尽快找到新租客可减少空置损失。","legalRef":"《中华人民共和国民法典》第585条","consumerBenefit":"掌握要点保障权益","tags":{"clientType":["tenant","landlord"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["中途退租违约金标准","提前退租赔多少","违约金和押金关系"]},{"id":"LIV-DEC-002","name":"装修哪些墙不能拆","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"我想把客厅和阳台之间的墙打掉，可以吗？","ola":"承重墙不能拆，拆了违法且危害整栋楼","cp":["承重墙严禁拆除","变动主体结构需设计方案","拆承重墙属违法行为","扩大承重墙门窗尺寸也禁止"],"detail":"装修中严禁拆除承重墙、剪力墙等影响建筑主体和承重结构的墙体。未经原设计单位或具有相应资质等级的设计单位提出设计方案，不得变动建筑主体和承重结构。拆除承重墙属于违法行为，危及整栋楼安全。","legalRef":"《住宅室内装饰装修管理办法》第5条；《建设工程质量管理条例》第15条","consumerBenefit":"避免违法拆改被罚和恢复原状，保障房屋安全","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["承重墙能拆吗","装修拆墙有什么限制","哪些墙是承重墙"]},{"id":"LIV-DEC-003","name":"装修能把阳台改成厨房吗","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"我家阳台挺大的，想改成厨房行不行？","ola":"阳台不能改成厨卫，属于违规改造","cp":["阳台不得改为卫生间厨房","改造涉及防水和荷载问题","擅自改造属违规行为","须经设计单位出具方案"],"detail":"装修中不得将没有防水要求的房间或阳台改为卫生间、厨房间。阳台改建涉及增加楼面荷载和防水问题，未经设计单位出具方案擅自改造，属于违规行为，可能造成渗漏和结构安全隐患。","legalRef":"《住宅室内装饰装修管理办法》第5条第2款、第8条","consumerBenefit":"避免违规改造被罚恢复原状，防止渗漏纠纷","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["阳台改厨房违法吗","阳台能改功能吗","阳台改造有限制吗"]},{"id":"LIV-DEC-004","name":"装修扰民怎么办能投诉吗","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"邻居周末早上8点就开始装修，特别吵，能投诉吗？","ola":"周末和午休时间禁止噪音装修，可投诉","cp":["工作日限时施工早8晚6午休停","法定休息日节假日禁噪音施工","噪音扰民可向物业或公安投诉","物业有权制止违规施工"],"detail":"装饰装修企业应严格遵守规定的施工时间，降低施工噪音。法定休息日、节假日及工作日12时至14时、18时至次日8时，禁止进行产生噪音的装修作业。产生噪声干扰他人可向物业或公安投诉。","legalRef":"《住宅室内装饰装修管理办法》第26条；《中华人民共和国噪声污染防治法》第66条","consumerBenefit":"保障休息权利，有法可依投诉违规装修","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["装修噪音投诉","装修太吵能报警吗","装修施工时间规定"]},{"id":"LIV-DEC-005","name":"装修施工顺序怎么排","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修到底先装什么后装什么，工人说的都不一样？","ola":"拆改→水电→防水→瓦→木→油→安装→验收","cp":["先拆改再水电再瓦木油","隐蔽工程完工必须验收","防水做完必须闭水试验","工序倒置易返工多花钱"],"detail":"标准装修施工顺序为：拆改→水电改造（隐蔽工程）→防水→瓦工（贴砖）→木工→油工→安装（橱柜、门窗、卫浴等）→竣工验收。各工序环环相扣，前道工序验收合格后方可进入下道工序，严禁工序倒置。","legalRef":"《住宅室内装饰装修管理办法》第十条","consumerBenefit":"避免工序混乱导致返工和额外费用","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["装修流程步骤","装修先做什么后做什么","装修施工顺序"]},{"id":"LIV-DEC-008","name":"装修电线用多粗的","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修电工说2.5平的线够用了，到底要多粗的？","ola":"入户10mm²，空调厨卫4mm²，普通2.5mm²","cp":["入户线≥10mm²","空调专用回路≥4mm²","厨卫插座回路≥4mm²","普通插座≥2.5mm²照明≥1.5mm²"],"detail":"住宅电气线路应按用途选择导体截面：入户线不少于10mm²，空调等大功率设备专用回路不少于4mm²，厨房、卫生间插座回路不少于4mm²，普通插座回路不少于2.5mm²，照明回路不少于1.5mm²。不同回路应分路敷设并设漏电保护。","legalRef":"GB 50303-2015《建筑电气工程施工质量验收规范》；GB 50054-2011《低压配电设计规范》","consumerBenefit":"用对线径避免用电安全隐患和跳闸","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["装修电线规格怎么选","家用电线几平方","空调用多粗的线"]},{"id":"LIV-DEC-009","name":"卫生间防水做多高","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修公司说卫生间防水做到30公分就够了，真的吗？","ola":"淋浴区防水≥1.8m，30公分远远不够","cp":["淋浴区防水≥1.8m","洗手盆区≥1.2m其他≥0.3m","涂料涂2-3遍交叉施工","闭水试验48小时无渗漏"],"detail":"卫生间防水施工标准：地面全做防水层，墙面淋浴区防水高度不低于1.8m（通常做到顶），洗手盆区域不低于1.2m，其他墙面不低于0.3m。防水涂料应涂刷2-3遍，每遍方向垂直交叉，完工后必须做闭水试验，蓄水深度≥20mm，持续48小时无渗漏为合格。","legalRef":"GB 50209-2010《建筑地面工程施工质量验收规范》；JGJ 298-2014《建筑室内防水工程技术规程》","consumerBenefit":"避免防水高度不足导致渗漏和赔偿","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["卫生间防水高度标准","防水层做多高才合格","卫生间墙面防水要求"]},{"id":"LIV-DEC-010","name":"防水闭水试验怎么做","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修做防水说只要放水2小时看看就行，行吗？","ola":"闭水试验必须蓄水48小时，到楼下检查","cp":["蓄水深度≥20mm","蓄水时间≥48小时","须到楼下检查有无渗漏","不合格须重做再试验"],"detail":"闭水试验是检验防水质量的必做程序。施工方法：防水层完全干透后封堵地漏，蓄水深度不低于20mm，蓄水时间不少于48小时，期间到楼下对应位置检查有无渗漏痕迹。48小时无渗漏即为合格，如有渗漏须重新做防水并再次试验。","legalRef":"GB 50242-2002《建筑给水排水及采暖工程施工质量验收规范》第4.2.1条","consumerBenefit":"确保防水真正合格，避免入住后渗漏纠纷","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["闭水试验标准","防水验收怎么做","闭水试验要多久"]},{"id":"LIV-DEC-011","name":"隐蔽工程验收看什么","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修公司说水电不用验收直接封槽，这行吗？","ola":"隐蔽工程封槽前必须验收，不合格不能封","cp":["水电完工封槽前必须验收","防水涂刷完封闭前验收","验收不合格不得下道工序","拍照录像留存验收证据"],"detail":"隐蔽工程是指装修后被覆盖、无法直接检查的工程，主要包括水电管线、防水层、保温层、地暖管等。水电改造完工、防水涂刷完成后、封闭前必须进行验收，不合格不得进行下道工序。验收应拍照或录像留存证据。","legalRef":"GB 50327《住宅装饰装修施工规范》第8章","consumerBenefit":"避免隐蔽工程隐患被覆盖后无法追责","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["隐蔽工程指什么","水电验收怎么验","隐蔽工程不验收可以吗"]},{"id":"LIV-DEC-012","name":"装修水管走顶还是走地好","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"水管走顶和走地到底哪个好？差价多少？","ola":"走顶检修方便是主流推荐，走地省钱但修起来贵","cp":["走顶：漏点易发现检修方便","走地：管路短费用低","行业标准推荐走顶","走顶须加保温防冷凝水"],"detail":"给水管布设有走顶和走地两种方式。走顶方式的优点是漏水易发现、检修只需拆吊顶不破坏地面和邻居天花板；走地方式的优点是管路短、水压损耗小、费用低。目前行业标准推荐水管走顶，便于后期维修和漏损控制。","legalRef":"行业通行做法","consumerBenefit":"选择合理布管方式，降低日后维修成本","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["水管走顶走地哪个好","水管走顶的优缺点","水管走地漏水怎么办"]},{"id":"LIV-DEC-013","name":"装修墙面开裂怎么处理","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"刚装修完墙面就裂了，是装修公司的问题吗？","ola":"先区分是结构裂缝还是装修裂缝再追责","cp":["结构裂缝和装修裂缝要区分","贯穿性斜裂缝须专业鉴定","装修裂缝由施工方负责","新旧墙接缝须挂网处理"],"detail":"墙面开裂分结构裂缝和装修裂缝。结构裂缝由房屋沉降或温度变化引起，贯穿性斜裂缝需请专业机构鉴定；装修裂缝多为基层处理不当、新旧墙接缝未挂网、腻子过厚等造成。装修裂缝由施工方负责修补，结构裂缝需物业或建设单位处理。","legalRef":"GB 50210-2018《建筑装饰装修工程质量验收标准》第四章","consumerBenefit":"准确判定裂缝责任方，避免花钱修别人的问题","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["墙面裂缝正常吗","墙面裂纹什么原因","装修后墙面开裂谁负责"]},{"id":"LIV-DEC-014","name":"瓷砖空鼓怎么判断","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修完了我敲瓷砖有空声，这算空鼓吗？要紧吗？","ola":"空声就是空鼓，地砖空鼓率不超5%算合格","cp":["空鼓锤敲击听声辨别","地砖空鼓率≤5%","单块空鼓面积≤15%","墙砖不允许中心空鼓"],"detail":"瓷砖空鼓是指瓷砖与基层粘结不牢、存在空隙的现象。检测方法用空鼓锤轻敲瓷砖表面，空鼓处声音清脆（'咚咚'声），实贴处声音沉闷。验收标准：地砖空鼓率不超过5%，单块空鼓面积不超过该块砖面积的15%，墙砖不允许中心空鼓。","legalRef":"GB 50210-2018《建筑装饰装修工程质量验收标准》第十章","consumerBenefit":"验收时发现空鼓可要求返工，入住后脱落难追责","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["空鼓怎么检查","瓷砖空鼓标准","瓷砖空鼓多少算不合格"]},{"id":"LIV-DEC-015","name":"地暖漏水怎么查","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修师傅在地面打孔打到地暖管了，怎么办？","ola":"施工方负责修复和赔偿，打压测试确认无漏","cp":["打压0.6-0.8MPa保1小时","压降≤0.05MPa为合格","热成像仪定位漏点","地暖区域严禁打钉钻孔"],"detail":"地暖管属于隐蔽工程，漏水检测方法：先进行打压测试（0.6-0.8MPa保压1小时压降≤0.05MPa），确认管路密封性。如打压不合格，用红外热成像仪定位漏点。装修施工打穿地暖管由施工方负责赔偿和修复。地暖区域严禁打钉打孔。","legalRef":"GB 50242-2002《建筑给水排水及采暖工程施工质量验收规范》","consumerBenefit":"明确地暖漏水责任归属，规范施工避免损失","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["地暖管漏水怎么检测","地暖漏水谁负责","装修打到地暖管怎么办"]},{"id":"LIV-DEC-016","name":"下水管道装修时能改吗","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"我想把马桶移个位置，装修公司说可以，行吗？","ola":"排污立管不能改，移马桶要保坡度防堵","cp":["排污立管属公共设施不得拆改","排水横管坡度≥2%","移位后易堵塞返水","移位须经物业同意"],"detail":"下水管道（排污管、排水立管）属于公共设施，擅自拆改影响整栋楼排水系统的属于违规行为。存水弯和排水横管的坡度有严格标准（≥2%），移位后坡度不够容易堵塞返水。如必须移位，需经物业同意并确保坡度和管径符合规范。","legalRef":"《住宅室内装饰装修管理办法》第5条","consumerBenefit":"避免改管后堵塞返水，影响自己也影响邻里","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["下水管能移位吗","马桶下水管能改吗","排污管改造注意事项"]},{"id":"LIV-DEC-018","name":"装修材料怎么选才环保","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修选板材怎么判断环不环保？E0和ENF什么区别？","ola":"选ENF级板材最环保，查验检测报告和认证","cp":["板材选E1级以上认准ENF级","涂料VOC≤120g/L","查验材料检测报告","认准十环标志环保认证"],"detail":"装修材料须符合国家环保标准。人造板材甲醛释放量分E1级（≤0.124mg/m³，可直接用于室内）和ENF级（≤0.025mg/m³，最环保）。涂料须符合GB 18582（VOC≤120g/L），胶黏剂须符合GB 18583。选购时应查验检测报告，认准十环标志等环保认证。","legalRef":"《住宅室内装饰装修管理办法》第28条","consumerBenefit":"从源头控制甲醛，入住后不超标少操心","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["环保装修材料标准","E0级板材什么意思","装修材料环保等级"]},{"id":"LIV-DEC-019","name":"装修用胶水甲醛多吗","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"听说装修甲醛主要来自胶水，怎么选胶才安全？","ola":"选环保胶黏剂查验检测报告，减少用胶量","cp":["胶黏剂是甲醛主要来源","游离甲醛≤1.0g/kg为国标","选环保型胶黏剂查验报告","减量用胶或选免胶工艺"],"detail":"装修用胶黏剂是室内甲醛的主要来源之一，特别是人造板材用脲醛胶、壁纸胶、玻璃胶等。国标GB 18583规定胶黏剂游离甲醛≤1.0g/kg。选购时应选环保型胶黏剂，认准检测报告。减少用胶量、选用免胶工艺或环保替代品是降低甲醛的有效方法。","legalRef":"《住宅室内装饰装修管理办法》第28条","consumerBenefit":"从胶水源头控制甲醛，减少后期治理成本","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["胶水甲醛含量高吗","装修胶黏剂选什么好","玻璃胶甲醛多吗"]},{"id":"LIV-DEC-020","name":"装修辅材能用便宜的吗","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修公司说辅材用普通牌子就行，真的无所谓吗？","ola":"辅材关系安全质量，品牌型号必须写进合同","cp":["辅材直接关系安全和质量","水管选PPR电线选国标铜芯","辅材品牌型号须写入合同","辅材偷工减料是最常见陷阱"],"detail":"装修辅材（水管、电线、腻子、防水涂料、水泥等）虽不显眼，但直接影响装修质量和安全。水管须选PPR材质并有检测报告，电线须选国标铜芯线，防水涂料须有环保认证和检测报告。辅材偷工减料是最常见装修陷阱，所有辅材品牌和型号应在合同中明确约定。","legalRef":"《住宅室内装饰装修管理办法》第二十八条","consumerBenefit":"避免辅材以次充好埋下安全隐患","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["辅材差影响大吗","装修水管用什么牌子好","电线用什么品牌"]},{"id":"LIV-DEC-021","name":"装修壁纸和乳胶漆哪个更环保","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"墙面贴壁纸环保还是刷漆环保？","ola":"优质乳胶漆更易控甲醛，壁纸须配环保胶","cp":["乳胶漆VOC低干燥快易控","壁纸胶是甲醛主要来源","选乳胶漆看VOC和认证","选壁纸须搭配环保胶"],"detail":"乳胶漆和壁纸的环保性取决于产品等级。合格乳胶漆VOC含量低、干燥快，优质产品可达VOC≤2g/L（法国A+标准）；壁纸本身较环保，但壁纸胶是甲醛主要来源。综合比较：选高品质乳胶漆甲醛更可控，选壁纸须搭配环保糯米胶或淀粉胶。","legalRef":"GB 18582-2020《建筑用墙面涂料中有害物质限量》；GB 18585-2001《室内装饰装修材料壁纸中有害物质限量》","consumerBenefit":"根据环保需求选对墙面材料，减少甲醛风险","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["壁纸和乳胶漆哪个甲醛低","贴壁纸环保吗","乳胶漆有甲醛吗"]},{"id":"LIV-DEC-022","name":"装修验收要查哪些地方","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"装修完了说让我去验收，我都看什么才不被糊弄？","ola":"查水电、防水、空鼓、墙面、门窗、木作","cp":["水电通电出水排水通畅","防水闭水试验合格","瓷砖空鼓率达标","验收不合格不签字"],"detail":"装修竣工验收是对全部施工质量的最终检查，主要验收内容：①水电：开关插座通电、水龙头出水、排水通畅、地漏坡度；②防水：闭水试验合格；③墙地砖：空鼓率达标、拼缝均匀；④墙面：平整度、色差、开裂；⑤门窗：开合顺畅、密封良好；⑥木作：收口、色差、变形。验收不合格不得签字确认。","legalRef":"GB 50210《建筑装饰装修工程质量验收标准》；GB 50327《住宅装饰装修施工规范》","consumerBenefit":"验收到位避免入住后问题无人负责","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"法","meetingPhase":["见后","见前"]},"alias":["装修竣工验收清单","装修验收标准是什么","装修怎么验收才不吃亏"]},{"id":"LIV-DEC-023","name":"装修验收不合格怎么办","domain":"居住中","subScene":"装修","scene":"居住中·装修","cq":"验收发现好几处不合格，装修公司说先签字再修，行吗？","ola":"不合格不能签字，记录问题要求整改复验","cp":["不合格项目逐条记录","要求限期整改后复验","未整改到位拒签拒付尾款","拒不整改可追责或起诉"],"detail":"装修验收发现不合格项目，应在验收单上逐条记录问题，要求施工方限期整改，整改后复验合格方可签字确认。未整改到位业主有权拒绝签字和拒付尾款。如施工方拒不整改，可依据合同追究违约责任，协商不成可向消协投诉或起诉。","legalRef":"《中华人民共和国民法典》第577条","consumerBenefit":"签字前留有筹码，整改不到位有权拒付尾款","tags":{"clientType":["buyer","tenant"],"stage":"post","layer":"道","meetingPhase":["见后","见前","见中"]},"alias":["验收发现问题怎么处理","装修不达标可以拒收吗","装修整改流程"]}]}